// "Cute Lab Pastel" renderer — PixiJS v8. Reads run state, never mutates it.
// All entity looks are baked into textures once; per-frame work is sprite pools only.
//
// Contract used by main.js:
//   const r = createRenderer(app)
//   r.reset(run|null)          new run started (build world) or back to title (clear)
//   r.sync(run, dt, events)    draw current state; dt=0 means "frozen behind a modal"
//   r.idle(dt)                 no run active (title screen background)
import { Assets, Container, FillGradient, Graphics, Mesh, MeshGeometry, Rectangle, Shader, Sprite, Text, Texture, TilingSprite, UniformGroup } from 'pixi.js'
import { PLAYER, ENEMIES, WEAPONS, HOLE_CORE_FRAC, ELITE_AFFIXES, SHIELD_HP_FRAC, SUBMISSION_DURATION, MINIME_DRAW_SCALE, BERSERK_DURATION, STILLNESS_RAMP, STILL_STEPS, STILL_MORPH_MAX, BERSERK_TINT, BERSERK_TINT_MAX, BERSERK_TINT_TAIL, ALLY_RING, ALLY_RING_ARC, PACER_RADIUS, ORB_R, CHAPTERS, CURRENT_VIS, EDDY_VIS, STORM_VIS, LIGHTNING, districtAt, districtTintAt, PHEROMONE_LIFE, SNAP_TRAP_REARM, AMBUSH_R, TRAFFIC_WARN, TRAFFIC_CAR_LEN, TRAFFIC_CAR_W, TRAFFIC_APPROACH, TRAFFIC_BEAM, MOWER_DECK_LEN, MOWER_DECK_W, COVER_MIN_R, DEBRIS_R, POUNCE_AIM_T, POUNCE_LEAP_T, POUNCE_LEAP_DIST, POUNCE_TURN_AIM, POUNCE_TURN_LEAP, POUNCE_TURN_IDLE, AERIAL_MARK_T, FLASHLIGHT_RANGE, FLASHLIGHT_ARC, LINE_CHARGE_LOCK_T, LINE_CHARGE_LEN, LINE_CHARGE_W, PULL_BEAM_RANGE, PULL_BEAM_T, PULL_BEAM_W, PRISM_FLASH_T, RAMPAGE_DURATION, PROP_SCALE, roadAt, ROAD_MINOR_WIDTH, STRAFE_TELEGRAPH_T, DISTRICT_BLEND_PX, SKIES_FLOOR_KEEP, LANE_CAMERA_FRAC, LANE_AXIS_Y, laneAxes, BLANK_BOSS_R, BLANK_YANK_T, HYDRANT_STREAMS_MAX, darkness, lightRadius, refillSpec, TIDE_VIS, TIDE_POOL_VIS, SANDBAR_VIS, AIR_POCKET_VIS, SPLASH_VIS, CAUSTIC_VIS, WAKE_VIS, LOBE_SHAPES, LOBE_DEPTH, lobeFactor, CORAL_CRUSH, NOVA_LIFE, SHELL_R, TRAWL_HALF, TRAWL_WAKE_DEPTH,
  // ---- v5.10 skies art direction (docs/superpowers/specs/2026-07-25-skies-art-direction.md) ----
  // All render-only, skies-only data. See config.js's "SKIES ART DIRECTION" section header.
  SKIES_PALETTE, SKIES_INK, SKIES_TELEGRAPH_LOD_PX, SKIES_FLASH, SKIES_SMOKE, SKIES_JAM, SKIES_FX,
  SKIES_LIGHT, DISTRICT_SURFACE, DISTRICT_EDGE, ROAD_PAINT, ROAD_DECAL, ROAD_JUNCTION,
  SKIES_SHADOW, SKIES_BAKE_PX, SKIES_STRUCTURE_ART, SKIES_RUIN, SKIES_VEHICLE, SKIES_KAIJU,
  // sim constants the FX clocks key off (the spec's "arrival clock" rule is only enforceable if
  // the clock and the fuse are literally the same number — see SKIES_FX's own doc)
  ARTILLERY_FUSE, BOMBARDMENT_FUSE, ARTILLERY_ELITE_RADIUS, MISSILE_FIRE_RANGE,
  BREATH_CHARGE_T, // v7.23: the Atomic Breath's wind-up ring closes on exactly the sim's charge clock
  ROAD_MAJOR_WIDTH, HIGHWAY_WIDTH, highwaysNear, BLOCK_U, BLOCK_V, cityAt, nearestCity, CITY_GRID, STREET_SPACING_MAJOR_EVERY, parcelAt, PARCEL, terrainAt, clumpAt,
} from './config.js'
import { currentForce, tideForce } from './sim.js'


const DARK = 0x3b3345
const JET_BAKE_R = 34   // v6.10: every jet texture bakes at this radius, so rig scale = gy.r / it
// The hydrant is drawn at this many px ACROSS-ish regardless of the zone's damage radius. It is an
// object, not a zone: it must not grow when the weapon levels. See syncJets.
const HYDRANT_PX = 36
// The Surf's gull STRIKE bakes at this radius — module scope, not beside stepGullDives where it is
// read, because buildTextures() runs long before the bottom of createRenderer's body evaluates and a
// `const` down there is still in its temporal dead zone when the bake asks for it (a blank page, not
// a warning). GULL_DIVE_SPAN is the spread pose's wingspan in bake px, which is what the strike
// scales off so the folded stoop does not appear to shrink the bird.
const GULL_DIVE_R = 34
const GULL_DIVE_SPAN = 2.42 * 2 * GULL_DIVE_R
const MAX_PARTICLES = 200
const MAX_DMG_TEXTS = 30

// Foliage sprite sheet: white/shaded PNGs in src/props/, tinted per-instance at draw
// time. `eager: true` + `query: '?url'` resolves to plain URL strings at build time
// (no runtime dynamic-import graph), keeping this compatible with main.js's
// no-top-level-await / inlineDynamicImports constraints.
const PROP_MODULES = import.meta.glob('./props/*.png', { eager: true, query: '?url', import: 'default' })
const PROP_URLS = {}
for (const path in PROP_MODULES) {
  const name = path.match(/([^/]+)\.png$/)[1]
  PROP_URLS[name] = PROP_MODULES[path]
}

// Weapon/vfx sprite sheet: white/greyscale Kenney particle PNGs in src/fx/, tinted per-use
// (baked composites) or per-instance (live sprites). Same eager-url-glob trick as props
// above, folded into the same `ready` promise so both sheets land together.
const FX_MODULES = import.meta.glob('./fx/*.png', { eager: true, query: '?url', import: 'default' })
const FX_URLS = {}
for (const path in FX_MODULES) {
  const name = path.match(/([^/]+)\.png$/)[1]
  FX_URLS[name] = FX_MODULES[path]
}

const ENEMY_LOOKS = {
  drone: { fill: 0x8e97f2, line: 0x5560c9 },
  wisp: { fill: 0xffb3c6, line: 0xd5567d },
  tank: { fill: 0x7fa8d9, line: 0x4a6fa5 },
}

function mix(a, b, t) {
  const r = Math.round((a >> 16 & 255) + ((b >> 16 & 255) - (a >> 16 & 255)) * t)
  const g = Math.round((a >> 8 & 255) + ((b >> 8 & 255) - (a >> 8 & 255)) * t)
  const c = Math.round((a & 255) + ((b & 255) - (a & 255)) * t)
  return r << 16 | g << 8 | c
}

// Channel-wise multiply of two colours (== Pixi tint compositing) — lets a chapter's
// floorTint/playerTint modulate a sprite's already-baked tint. White (0xffffff) is the
// identity, so a body-chapter tint of 0xffffff leaves every baked colour untouched.
function tintMul(a, b) {
  const r = ((a >> 16 & 255) * (b >> 16 & 255) / 255) | 0
  const g = ((a >> 8 & 255) * (b >> 8 & 255) / 255) | 0
  const c = ((a & 255) * (b & 255) / 255) | 0
  return r << 16 | g << 8 | c
}

// Per-chapter render palette (CHAPTERS[id].render, config.js). BODY_RENDER is the neutral
// identity used for the title screen and any chapter that omits render data.
const BODY_RENDER = { bgColor: 0xf4efe6, floorTint: 0xffffff, playerTint: 0xffffff, tail: false }

// Deterministic pseudo-random in [0,1) from a numeric seed. Used for arc jitter so the
// jagged shape is stable frame-to-frame (no flicker, stays frozen when dt=0) instead of
// re-rolling with Math.random() every redraw.
// v5.21: planet surface spin, rad/s. Read in syncObstacles (outside buildTextures' block scope),
// so it lives here rather than beside the other PLANET_* bake constants.
// rad/s, signed, with a FLOOR. A plain (hash - 0.5) * MAX range puts half the planets within a
// whisker of zero, and a world turning at 0.02 rad/s takes four minutes to come round — indis-
// tinguishable from frozen. The floor is what guarantees every planet visibly turns; the ceiling
// keeps the slowest at ~60s per revolution and the fastest at ~24s.
const PLANET_SPIN_MIN = 0.10
const PLANET_SPIN_MAX = 0.26
// v5.23.6: moons ORBIT. They used to be painted into the same overlay canvas as the halo, which
// pinned them to one spot on the sprite forever — a moon that never moves is a freckle. Now each is
// its own sprite swung round the body, and because a real moon spends half its period BEHIND its
// planet, the sprite is re-parented above or below the sphere mesh each frame (tickPlanetSpin).
// Faster than the surface spin on purpose: the two motions have to be separable by eye or the moon
// reads as a bump on the planet rather than a body of its own.
const MOON_ORBIT_MIN = 0.28
const MOON_ORBIT_MAX = 0.46
// The orbit plane is seen near edge-on, not from directly above — a circle would read as a hoop
// drawn on the screen. This is its foreshortening.
const MOON_ORBIT_SQUASH = 0.42

// v5.23 — planets are real spheres now. Direction TO the star, in the shader's y-UP space, shared by
// every planet so the chapter agrees about where the light is. Up and to the left, matching the
// baked directional cues on every other prop in the beyond set.
// z is deliberately the SMALLEST component: a star sitting behind the camera lights the whole
// visible hemisphere evenly and the sphere flattens into a disc. Pushing the light sideways is what
// puts a terminator across the body, which is the strongest 3D cue there is.
const PLANET_LIGHT = (() => {
  const v = [-0.52, 0.58, 0.42], m = Math.hypot(...v)
  return new Float32Array(v.map((n) => n / m))
})()

// Quad in [-1,1]. The SPHERE is entirely in the fragment shader — the geometry is just the square
// that bounds it, so every planet shares one geometry and costs one draw call.
const PLANET_VERT = `
in vec2 aPosition;
in vec2 aUV;
out vec2 vUV;
uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform mat3 uTransformMatrix;
void main() {
  mat3 mvp = uProjectionMatrix * uWorldTransformMatrix * uTransformMatrix;
  gl_Position = vec4((mvp * vec3(aPosition, 1.0)).xy, 0.0, 1.0);
  vUV = aUV;
}`

// Reconstruct the sphere normal from the quad, rotate it into texture space by a full 3x3, then
// read the equirectangular map at that lat/long. Because the rotation is a real matrix and not a
// 2D `sprite.rotation`, the axis can point anywhere — which is the entire point of this shader.
// Lighting is per-pixel N.L, so the terminator is computed rather than painted, and it stays put
// while the surface turns underneath it.
const PLANET_FRAG = `
precision highp float;
in vec2 vUV;
uniform sampler2D uMap;
uniform sampler2D uEmit;
uniform vec3 uRot0;
uniform vec3 uRot1;
uniform vec3 uRot2;
uniform vec3 uLight;
uniform vec3 uAtmo;
uniform vec3 uTint;
void main() {
  vec2 p = vUV * 2.0 - 1.0;
  p.y = -p.y;                       // canvas is y-down, the sphere is y-up
  float r2 = dot(p, p);
  if (r2 > 1.0) discard;            // outside the disc there is no planet
  float z = sqrt(max(0.0, 1.0 - r2));
  vec3 n = vec3(p, z);              // unit normal, +z toward the camera
  vec3 m = mat3(uRot0, uRot1, uRot2) * n;
  // Longitude maps to u = lon/PI, which runs -1..1 over a full turn while the map holds only ONE
  // 180-degree copy of the art. The sampler's mirror-repeat folds that range back on itself, so the
  // far hemisphere is a reflection of the near one and both joins line up by construction. Doing it
  // in the sampler rather than baking two mirrored copies costs nothing and halves the texture.
  // It also fixes the aspect for free: 2 units of art now cover 180 degrees on BOTH axes, so a
  // drawn circle is a circle on the sphere instead of an ellipse twice as wide as it is tall.
  vec2 uv = vec2(atan(m.x, m.z) * 0.31830989, 0.5 - asin(clamp(m.y, -1.0, 1.0)) * 0.31830989);
  vec3 col = texture2D(uMap, uv).rgb * uTint;
  float day = smoothstep(-0.25, 0.85, dot(n, uLight));
  col *= mix(0.12, 1.16, day);
  // Emissive burns THROUGH the night side and is washed out by day — city lights and lava behave
  // the way the archetypes that own them were designed around.
  col += texture2D(uEmit, uv).rgb * (1.0 - day * 0.88);
  // Rim: atmosphere is thickest where the line of sight grazes the limb, and it is lit by the same
  // star, so it fades out on the night side instead of ringing the whole silhouette.
  col += uAtmo * pow(1.0 - z, 3.0) * (0.25 + 0.75 * day);
  // Antialias the limb by fading over a fixed slice of r2 rather than a derivative: Pixi compiles
  // this program as WebGL1, where fwidth needs GL_OES_standard_derivatives and fails to link
  // without it. 0.988 is r=0.994, so the fade is ~1.5px on a 230px-radius planet.
  float a = 1.0 - smoothstep(0.988, 1.0, r2);
  gl_FragColor = vec4(col * a, a);
}`

let planetGeom = null
function makePlanetMesh() {
  planetGeom ||= new MeshGeometry({
    positions: new Float32Array([-1, -1, 1, -1, 1, 1, -1, 1]),
    uvs: new Float32Array([0, 0, 1, 0, 1, 1, 0, 1]),
    indices: new Uint32Array([0, 1, 2, 0, 2, 3]),
  })
  const uniforms = new UniformGroup({
    uRot0: { value: new Float32Array([1, 0, 0]), type: 'vec3<f32>' },
    uRot1: { value: new Float32Array([0, 1, 0]), type: 'vec3<f32>' },
    uRot2: { value: new Float32Array([0, 0, 1]), type: 'vec3<f32>' },
    uLight: { value: PLANET_LIGHT, type: 'vec3<f32>' },
    uAtmo: { value: new Float32Array([0, 0, 0]), type: 'vec3<f32>' },
    uTint: { value: new Float32Array([1, 1, 1]), type: 'vec3<f32>' },
  })
  const shader = Shader.from({
    gl: { vertex: PLANET_VERT, fragment: PLANET_FRAG },
    resources: { uniforms, uMap: Texture.WHITE.source, uEmit: Texture.WHITE.source },
  })
  return new Mesh({ geometry: planetGeom, shader })
}

function hash(n) {
  const s = Math.sin(n) * 43758.5453
  return s - Math.floor(s)
}

function lerp(a, b, t) { return a + (b - a) * t }

// Deterministic hash for a (cell, salt) triple — same trick as hash() above, extended
// to two cell indices so floor-scatter content (ground blotches + props) never changes
// as a cell re-enters view; it's a pure function of position, nothing is re-rolled.
function cellHash(i, j, salt) {
  return hash(i * 12.9898 + j * 78.233 + salt * 37.719)
}

export function createRenderer(app) {
  const R = app.renderer

  // Active chapter palette + which MOVING-WATER field this chapter's signature is, if any. Set once
  // per reset(run); read by the floor populate* callbacks, syncPlayer, obstacle/enemy tinting and
  // updateCurrents. Defaults to the neutral body look (title screen / chapters without render).
  let chapterRender = BODY_RENDER
  // 'currents' (the pond's drift field), 'tide' (The Surf's alternating surge) or null. A STRING
  // rather than the boolean it started as, because both chapters draw the same pooled streak field
  // off a different force function — see updateCurrents, which samples currentForce or tideForce on
  // this. flowVis is the matching visual block (CURRENT_VIS / TIDE_VIS), latched here so the merge
  // and the per-sprite tint happen once per run instead of once per streak per frame.
  let flowKind = null
  let flowVis = CURRENT_VIS
  // v6.4 pond signature: whether the active chapter's currents also stream eddies (run.eddies —
  // CHAPTERS[id].signature.eddies). Same latch pattern as flowKind; read by updateEddies.
  let chapterHasEddies = false
  // v7.x Book 2: which REFILL CIRCLE look the active chapter draws into run.shafts — 'shaft' (The
  // Shelf's sun shafts), 'pool' (The Surf's tide pools) or 'pocket' (The Reef's air pockets), null
  // for a chapter with no refill geometry at all. Driven by refillSpec() (config.js), the same
  // function streamShafts uses to decide existence, so a chapter can never stream circles the
  // renderer then refuses to draw: that is exactly what shipped when this was
  // `signature.type === 'shafts'` and The Surf's pools — its entire refill mechanic — were
  // invisible. Read by updateShafts.
  let refillLook = null
  // v7.x Book 2: the active chapter's swell block (CHAPTERS[].render.swell) or null. A CONFIG
  // OBJECT rather than a boolean, unlike its neighbours here, because updateSwell reads six numbers
  // off it every frame and re-deriving them from run.chapter per crest per frame is the kind of
  // thing that quietly costs a chapter its frame budget.
  let swellCfg = null
  // Whether the active chapter wears the night-thunderstorm overlay (CHAPTERS[].render.storm —
  // currently only `skies`). Same latch pattern as flowKind; read by updateStorm.
  let chapterHasStorm = false
  // v6.3: whether the active chapter draws SCREEN-space rain (CHAPTERS[].render.storm OR .rain —
  // currently skies [storm implies rain] and city [rain alone, no clouds]). updateRain reads this
  // directly rather than chapterHasStorm, so city gets wet asphalt without skies' cloud shadows.
  let chapterHasRain = false
  // v6.3: whether crush leaves a permanent ruin decal (CHAPTERS[].render.storm OR .ruins —
  // currently skies and city). Same `storm || X` idiom as chapterHasRain; read by updateRuins.
  let chapterHasRuins = false
  // v5.11 kaiju redesign, generalised (undertow): which chapter-specific player body the active
  // chapter draws — CHAPTERS[].render.form, e.g. 'kaiju' for skies, 'fish' for Book 2 — in place of
  // the generic cross-chapter blob. null for a chapter that declares no form. Read by
  // syncPlayer/updateRampage/lightPlatesForBreath; every site checks the SPECIFIC form it owns
  // (playerForm === 'kaiju'), so a chapter with no form — or a future form neither of them draws —
  // renders the generic blob exactly as before this pass.
  let playerForm = null
  // How big the `fish` form is drawn in the active chapter (CHAPTERS[].render.formScale, default 1)
  // — Book 2's "you grow in each chapter" arc. Latched in reset() beside playerForm; read by
  // syncPlayer for the body AND its shadow, which must scale together or the fish stands on the
  // footprint of the chapter before it.
  let formScale = 1
  // v6.5 undergrowth: screen-space falling leaves (CHAPTERS[].render.leaves — currently only
  // `undergrowth`). Same latch pattern as chapterHasStorm; read by updateLeaves.
  let chapterHasLeaves = false
  let chapterHasLane = false   // v5.18 beyond: trailing-edge camera (CHAPTERS[].lane)
  // v7.x The Reef: does the active chapter's skill button BURST (CHAPTERS[].burst)? Read in exactly
  // one place — handleEvents' 'crush' case, which stepCrush now emits for two entirely different
  // reasons (a kaiju flattening a building, a fish going through coral) and which therefore has to
  // ask whose crush this is. Latched here rather than read per event for the usual reason: an event
  // handler that dereferences CHAPTERS[run.chapter] pays for it on every event in the frame.
  let chapterHasBurst = false
  // v7.x: WHICH edge — laneAxes(cfg) (config.js). 'y' (The Beyond) anchors the player near the
  // bottom; 'x' (The Reef) near the left. Latched with chapterHasLane and read only by the camera.
  let chapterLaneAxis = LANE_AXIS_Y
  // v5.24 the blank: the white void draws NO decorative floor (CHAPTERS[].render.voidFloor) —
  // every scatter layer's populate callback early-outs on this, so bgColor alone is the ground.
  // Same latch pattern as chapterHasLane.
  let chapterIsVoid = false
  // Whether the active chapter's ground is a per-cell Voronoi district map (CHAPTERS[].render.
  // districts — currently only `skies`, piece 4). districtSeed mirrors run._districtSeed so the
  // floor populate* callbacks and syncObstacles don't need `run` threaded through every call.
  let chapterHasDistricts = false
  let districtSeed = 0
  // Whether the active chapter has a street grid to draw (CHAPTERS[].roads — currently only
  // `skies`). v5.11: roadSeed now mirrors run._districtSeed, the ONE world seed. The old split
  // (roads on run._obstacleSeed, terrain on run._districtSeed) is exactly what let streets run
  // through open sea, and forced this file to gate road DRAWING per district cell to hide it —
  // which is what chopped every street into 600px stubs. Roads are generated from cities now, so
  // there is nothing to hide and nothing to gate.
  let chapterHasRoads = false
  let chapterEndlessGrid = false   // v6.9.5: city's grid repeats forever; skies' ends at its cities
  let roadSeed = 0
  // Active chapter's prop/obstacle biome (BIOMES, declared with the floor section below). Left null
  // here on purpose: BIOMES is a `const` further down, so reading it at construction time would be a
  // TDZ crash — it's seeded right after BIOMES itself and re-latched per reset(run).
  let chapterBiome = null

  // ---------------------------------------------------------------- textures
  // Bake a Graphics into a texture; return anchor so sprite.position = drawing origin.
  function bake(g, pad = 3) {
    const b = g.getLocalBounds()
    const frame = new Rectangle(b.x - pad, b.y - pad, b.width + pad * 2, b.height + pad * 2)
    const tex = R.generateTexture({ target: g, frame, resolution: 2, antialias: true })
    g.destroy(true)
    return { tex, ax: -frame.x / frame.width, ay: -frame.y / frame.height }
  }

  // Same as bake(), but for a Container of Sprites (fx composites, e.g. glow-behind-star).
  // Must NOT destroy(true) — its children reference textures shared from T.fx and destroying
  // a Sprite with `texture: true` would kill that shared texture for every other user of it.
  function bakeComposite(container, pad = 3) {
    const b = container.getLocalBounds()
    const frame = new Rectangle(b.x - pad, b.y - pad, b.width + pad * 2, b.height + pad * 2)
    const tex = R.generateTexture({ target: container, frame, resolution: 2, antialias: true })
    container.destroy({ children: true }) // children: true, texture left untouched
    return { tex, ax: -frame.x / frame.width, ay: -frame.y / frame.height }
  }

  // Kenney fx PNGs (src/fx/) are ~512px square canvases with the glyph centered but not
  // edge-to-edge (some transparent padding around it). FX_FILL is an eyeballed estimate of
  // how much of the canvas the glyph actually fills — used to convert a desired on-screen
  // px size into a sprite.scale factor without hand-tuning every single sprite. Nudge
  // FX_FILL (or the per-effect target sizes below) if the art reads too big/small in-game.
  const FX_FILL = 0.8
  function fxScale(tex, targetPx) { return targetPx / (tex.width * FX_FILL) }
  function fxRadius(tex) { return (tex.width * FX_FILL) / 2 }

  // Enemy body + baked kawaii face. `white` builds the hit-flash silhouette with
  // identical geometry (same bounds -> same anchor) so textures swap freely.
  function drawEnemy(g, type, elite, white) {
    const r = ENEMIES[type].radius
    // fallback keeps a new config.js enemy type renderable before it gets a look here
    let { fill, line } = ENEMY_LOOKS[type] ?? { fill: 0xcccccc, line: 0x888888 }
    if (elite) { fill = mix(fill, 0xff7a4d, 0.45); line = mix(line, 0xc94a1d, 0.4) }
    if (white) { fill = 0xffffff; line = 0xffffff }
    const lw = Math.max(2.5, r * 0.16)

    groundShadow(r, r * 0.95)

    if (type === 'drone') {
      g.beginPath().moveTo(0, -r + 2).lineTo(0, -r - 6).stroke({ width: lw * 0.8, color: line })
      g.circle(0, -r - 7, r * 0.17).fill(line)
      g.circle(0, 0, r).fill(fill).stroke({ width: lw, color: line })
    } else if (type === 'wisp') {
      g.circle(0, 0, r).fill(fill).stroke({ width: lw, color: line })
    } else {
      g.roundRect(-r, -r, r * 2, r * 2, r * 0.42).fill(fill).stroke({ width: lw, color: line })
    }

    if (elite) eliteCrown(type === 'drone' ? -r - 10 : -r - 1, r)

    if (!white) {
      const ex = r * 0.36
      const ey = -r * 0.08
      const er = r * 0.2
      g.circle(-ex, ey, er).fill(0xffffff)
      g.circle(ex, ey, er).fill(0xffffff)
      g.circle(-ex + r * 0.06, ey + er * 0.15, er * 0.5).fill(DARK)
      g.circle(ex + r * 0.06, ey + er * 0.15, er * 0.5).fill(DARK)
      if (elite || type === 'tank') {
        g.beginPath()
        g.moveTo(-ex - er, ey - er * 1.6).lineTo(-ex + er * 0.6, ey - er * 0.9)
        g.moveTo(ex + er, ey - er * 1.6).lineTo(ex - er * 0.6, ey - er * 0.9)
        g.stroke({ width: Math.max(2, r * 0.1), color: line, cap: 'round' })
      }
      if (type === 'tank') {
        g.beginPath().arc(0, r * 0.62, r * 0.2, Math.PI * 1.15, Math.PI * 1.85).stroke({ width: 2, color: DARK, cap: 'round' })
      } else {
        g.beginPath().arc(0, r * 0.28, r * 0.18, Math.PI * 0.15, Math.PI * 0.85).stroke({ width: 2, color: DARK, cap: 'round' })
      }
      g.circle(-ex - er * 0.9, ey + er * 1.7, er * 0.5).fill({ color: 0xff9eb0, alpha: 0.4 })
      g.circle(ex + er * 0.9, ey + er * 1.7, er * 0.5).fill({ color: 0xff9eb0, alpha: 0.4 })
    }
  }

  // maxLean 0: these are the archetype fallback blobs (daily/title/future chapters). They aren't drawn
  // nose-at-+x at all — the kawaii face looks straight OUT of the screen, eyes and smile symmetric
  // about the vertical — so there is nothing to aim. They mirror left/right and that's it.
  function makeEnemyLook(type, elite) {
    shadowSpec = null
    crownSpec = null
    const g = new Graphics()
    drawEnemy(g, type, elite, false)
    const normal = bake(g)
    const shadow = shadowSpec
    const crown = crownSpec
    const w = new Graphics()
    drawEnemy(w, type, elite, true)
    const white = bake(w)
    return {
      tex: normal.tex, white: white.tex, ax: normal.ax, ay: normal.ay,
      baseR: ENEMIES[type].radius, maxLean: 0, shadow, crown,
    }
  }

  // ---- Per-chapter creature silhouettes (v5.4) --------------------------------------
  // Each creature is built from FLOWING PARAMETRIC PATHS, not stacked circles: a spine plus a
  // half-width profile (`spineOutline`) for anything elongated, a radius-modulated closed loop
  // (`radialOutline`) for anything blobby, and arc-length-tapered polylines (`taperStroke`) for
  // legs / antennae / stingers. Volume comes from two low-alpha overlay passes in the same hue
  // (a darker underside crescent + a lighter dorsal highlight) plus hairline detail strokes.
  //
  // Each drawXxx(g, elite, white) draws IDENTICAL OUTLINE geometry in both variants — `white`
  // forces every body fill/stroke to 0xffffff for the hit-flash texture, so bounds (and thus the
  // baked anchor) match and textures swap freely. Interior detail (shading, organelles, eyes,
  // bands, veins) is normal-only since it never changes bounds.
  //
  // Every creature is drawn facing +x (RIGHT): heads/snouts point right and trailing bits (tadpole
  // tail, wasp stinger) go left. syncEnemies aims the sprite at the player off that +x nose, so it
  // is the contract — a creature drawn facing any other way will aim wrong. How FAR each one is
  // allowed to turn is its own business: see the `lean` column in ROSTER_LOOKS below.
  // 'boss' (v5.24 the blank): sim sets the Antibody's radius to BLANK_BOSS_R post-spawn, and its
  // looks are drawn at that same local r — so syncEnemies' radius/baseR ratio lands at exactly 1.
  const ROSTER_BASE_R = { normal: ENEMIES.drone.radius, fast: ENEMIES.wisp.radius, tank: ENEMIES.tank.radius, boss: BLANK_BOSS_R }

  // The ground shadow and the elite crown are NOT baked into the body (v5.6.5). They used to be, and
  // then the body started rotating: a creature facing north wore its shadow swung out to the side and
  // its crown lying on its ear. A shadow is cast by an overhead light and a crown is worn by gravity —
  // both belong to the WORLD, not to the body. So each draw fn now merely DECLARES where its footprint
  // and its crown sit, and makeRosterLook/makeEnemyLook hand those numbers to syncEnemies, which places
  // shared textures for them in enemyShadowLayer (under the crowd) and enemyCrownLayer (over it) at
  // rotation 0. Declaring instead of hardcoding a second table keeps the numbers next to the art that
  // chose them; drawing nothing keeps the white twin's bounds identical to the normal one's for free.
  let shadowSpec = null
  let crownSpec = null
  // soft ground shadow: an ellipse `halfW` wide, centred `cy` below the drawing origin
  function groundShadow(halfW, cy) {
    shadowSpec = { rx: halfW * 0.85, ry: Math.max(4, halfW * 0.3), y: cy }
  }
  // elite golden crown, centred over the silhouette's top edge (`top` = that y), sized off `r`
  function eliteCrown(top, r) {
    crownSpec = { top, r }
  }
  // The crown's own geometry, drawn with its base line on y=0 — baked once per distinct `r` by
  // crownLook() rather than baked once and scaled, so the 1.5px rim stays 1.5px on every creature.
  function crownPoly(g, r, white) {
    g.poly([-r * 0.34, 0, -r * 0.17, -r * 0.42, 0, -r * 0.14, r * 0.17, -r * 0.42, r * 0.34, 0])
      .fill(white ? 0xffffff : 0xffd93d).stroke({ width: 1.5, color: white ? 0xffffff : 0xc9a227 })
  }

  // ---- silhouette construction helpers ----
  // Closed loop from a polar radius function: fn(angle) -> radius. For blobs whose outline is one
  // continuous membrane (cells) rather than an assembly of discs.
  function radialOutline(fn, n = 48, sx = 1, sy = 1, cx = 0, cy = 0) {
    const pts = []
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2
      const rad = fn(a)
      pts.push(cx + Math.cos(a) * rad * sx, cy + Math.sin(a) * rad * sy)
    }
    return pts
  }
  // Closed outline swept from a spine and a half-width profile: walk t0..t1 down one side, back up
  // the other. spine(t) -> [x, y]; halfW(t) -> half-thickness normal to the spine. A profile that
  // reaches 0 at an end closes to a point there (tail tips, stingers, gaster apex); one that stays
  // fat gives a blunt cap. This is what makes a body taper instead of being a chain of circles.
  function spineOutline(spine, halfW, n = 26, t0 = 0, t1 = 1) {
    const top = []
    const bot = []
    for (let i = 0; i <= n; i++) {
      const t = t0 + (t1 - t0) * (i / n)
      const [x, y] = spine(t)
      const [ax, ay] = spine(Math.max(0, t - 0.008))
      const [bx, by] = spine(Math.min(1, t + 0.008))
      const dx = bx - ax
      const dy = by - ay
      const len = Math.hypot(dx, dy) || 1
      const nx = -dy / len
      const ny = dx / len
      const w = halfW(t)
      top.push(x + nx * w, y + ny * w)
      bot.unshift(x - nx * w, y - ny * w)
    }
    return [...top, ...bot]
  }
  // Stroke a jointed polyline with a linear width profile along its arc length. Sub-segments with
  // round caps fuse into one smooth tapered limb, so legs/antennae narrow toward the tarsus/tip
  // instead of being uniform-width sticks. `pts` = [[x,y], ...] — real joints, not smooth arcs.
  function taperStroke(g, pts, w0, w1, color, sub = 3) {
    const segs = []
    let total = 0
    for (let i = 0; i < pts.length - 1; i++) {
      const d = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1])
      segs.push(d)
      total += d
    }
    if (total <= 0) return
    let done = 0
    for (let i = 0; i < pts.length - 1; i++) {
      const [x0, y0] = pts[i]
      const [x1, y1] = pts[i + 1]
      for (let s = 0; s < sub; s++) {
        const fa = s / sub
        const fb = (s + 1) / sub
        const t = (done + segs[i] * (fa + fb) * 0.5) / total
        g.beginPath()
          .moveTo(x0 + (x1 - x0) * fa, y0 + (y1 - y0) * fa)
          .lineTo(x0 + (x1 - x0) * fb, y0 + (y1 - y0) * fb)
          .stroke({ width: Math.max(0.7, w0 + (w1 - w0) * t), color, cap: 'round' })
      }
      done += segs[i]
    }
  }
  // Half-width profile primitive: a sine bulge over u in [0,1] shaped by exponent k (k<1 = blunt
  // and full-shouldered, k>1 = slender). u is clamped and the sine floored at 0 because float
  // drift at the endpoints (0.28 + 0.72 === 1.0000000000000002) would otherwise hand Math.pow a
  // negative base and silently produce NaN — one NaN point blanks the whole baked texture.
  function bulge(u, k) {
    return Math.pow(Math.max(0, Math.sin(Math.PI * Math.min(1, Math.max(0, u)))), k)
  }
  // A dark creature eye: no white sclera, just the lens + at most one pinprick specular.
  function darkEye(g, x, y, rx, ry, color, hi) {
    g.ellipse(x, y, rx, ry).fill(color)
    if (hi) g.circle(x + rx * 0.34, y - ry * 0.38, Math.max(0.6, rx * 0.3)).fill({ color: 0xffffff, alpha: 0.9 })
  }

  // --- Body chapter (warm pink interior) ---
  // The Body floor is a PALE warm pink (~0xf3e2dc, relative luminance ~0.79). Every creature here
  // must therefore separate from it by VALUE, not hue: deep/saturated fills and — where the fill has
  // to stay pale (the white cell IS white) — a thick dark membrane that carries the silhouette on
  // its own. Pale-on-pale is the failure mode; a hard dark edge is the fix.
  //
  // redcell: one tilted biconcave disc, but a FLEXED one — the outline radius carries a soft concave
  // dent on the upper-left plus a low 2-lobe wobble, so it is never a clean lozenge (real RBCs
  // deform as they squeeze through). Thick dark rim for edge contrast on pink, a bright specular
  // crescent along the upper-left rim so it reads as a solid object rather than a flat sticker.
  function drawRedcell(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const tilt = -0.13
    const ct = Math.cos(tilt)
    const st = Math.sin(tilt)
    const rot = (x, y) => [x * ct - y * st, x * st + y * ct]
    groundShadow(r, r * 0.85)
    // the fold: a gaussian bite out of the radius around a=2.35rad, plus a gentle 2-lobe wobble
    const fold = (a) => {
      let d = a - 2.35
      while (d > Math.PI) d -= Math.PI * 2
      while (d < -Math.PI) d += Math.PI * 2
      return Math.exp(-(d / 0.62) * (d / 0.62))
    }
    const edge = (a) => r * (1 + 0.05 * Math.cos(a * 2 + 0.8) - 0.19 * fold(a))
    const disc = (k) => {
      const pts = []
      for (let i = 0; i < 56; i++) {
        const a = (i / 56) * Math.PI * 2
        const e = edge(a) * k
        pts.push(...rot(Math.cos(a) * e, Math.sin(a) * e * 0.71))
      }
      return pts
    }
    g.poly(disc(1)).fill(f(0xd64545)).stroke({ width: Math.max(3, r * 0.2), color: f(0x6e1a1a) })
    if (!white) {
      // volume: darker underside crescent, lighter dorsal sheen (both same hue family)
      g.ellipse(r * 0.05, r * 0.2, r * 0.8, r * 0.42).fill({ color: 0x8a2424, alpha: 0.26 })
      g.ellipse(-r * 0.12, -r * 0.24, r * 0.68, r * 0.3).fill({ color: mix(0xd64545, 0xffffff, 0.45), alpha: 0.16 })
      // rim specular: the top-left slice of the outline, inset and stroked bright — a lit edge
      const lit = []
      for (let i = 0; i <= 14; i++) {
        const a = Math.PI * (0.98 + (i / 14) * 0.62)
        const e = edge(a) * 0.9
        lit.push(...rot(Math.cos(a) * e, Math.sin(a) * e * 0.71))
      }
      g.poly(lit, false).stroke({ width: Math.max(1.6, r * 0.1), color: mix(0xd64545, 0xffffff, 0.6), alpha: 0.55, cap: 'round' })
      // the torus rim reads as a faint lighter ring around the biconcave dimple
      g.poly(disc(0.66)).stroke({ width: 2, color: mix(0xd64545, 0xffffff, 0.3), alpha: 0.32 })
      const [dx, dy] = rot(-r * 0.04, 0)
      g.ellipse(dx, dy, r * 0.42, r * 0.29).fill({ color: 0x8a2424, alpha: 0.34 })
      g.ellipse(dx, dy, r * 0.24, r * 0.16).fill({ color: 0x6e1a1a, alpha: 0.4 })
    }
    if (elite) eliteCrown(-r * 0.74, r)
  }
  // wbc: amoeboid ivory cell — ONE closed membrane with irregular lobes of varying depth (three
  // beat frequencies, no regular flower). The fill stays pale (it IS a white cell), so ALL of the
  // contrast against the pale pink floor is carried by a thick near-black-brown membrane plus a
  // ragged fringe of pseudopodia/filopodia around the leading (right) half — the fringe is both the
  // "this is hunting you" motion cue and what makes the silhouette unmistakably not a bubble.
  // Internal contrast comes from a deep saturated violet nucleus.
  function drawWbc(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x4a3f33)
    groundShadow(r, r * 1.0)
    const membrane = (a) => r * (0.82 + 0.085 * Math.cos(a * 3 + 0.6) + 0.06 * Math.cos(a * 5 - 2.1) + 0.045 * Math.sin(a * 8 + 1.2))
    // filopodia: fine tapered spikes, irregular in angle/length, clustered on the leading half.
    // Drawn before the membrane so their roots vanish under the body. Geometry is identical in both
    // variants (only the colour differs) so the white twin's bounds still match.
    const spikes = [[-1.15, 0.3], [-0.78, 0.19], [-0.42, 0.26], [-0.16, 0.14], [0.18, 0.31], [0.5, 0.17],
      [0.86, 0.24], [1.24, 0.13], [1.66, 0.22], [2.5, 0.16], [3.02, 0.25], [4.55, 0.15], [5.1, 0.21], [5.66, 0.12]]
    for (const [a, len] of spikes) {
      const rad = membrane(a)
      const x0 = Math.cos(a) * rad * 0.86
      const y0 = Math.sin(a) * rad * 0.94 * 0.86
      const x1 = Math.cos(a) * (rad + r * len)
      const y1 = Math.sin(a) * (rad + r * len) * 0.94
      taperStroke(g, [[x0, y0], [x1, y1]], Math.max(2, r * 0.11), 0.8, line, 4)
    }
    g.poly(radialOutline(membrane, 60, 1, 0.94)).fill(f(0xf2ead8)).stroke({ width: Math.max(3, r * 0.18), color: line })
    if (!white) {
      g.ellipse(r * 0.04, r * 0.3, r * 0.72, r * 0.44).fill({ color: 0xa89678, alpha: 0.3 })
      g.ellipse(-r * 0.1, -r * 0.3, r * 0.6, r * 0.34).fill({ color: 0xfffaf0, alpha: 0.3 })
      // multi-lobed nucleus: one path, three overlapping lobes (a real neutrophil read)
      const nucleus = (a) => r * 0.46 * (0.78 + 0.28 * Math.cos(a * 3 - 0.9))
      g.poly(radialOutline(nucleus, 44, 1, 1, -r * 0.06, r * 0.02)).fill({ color: 0x4a2a6b, alpha: 0.92 })
      g.poly(radialOutline((a) => nucleus(a) * 0.62, 44, 1, 1, -r * 0.06, r * 0.02)).fill({ color: 0x2d1745, alpha: 0.75 })
      for (const [gx, gy, gr] of [[-r * 0.5, -r * 0.34, r * 0.075], [r * 0.42, -r * 0.2, r * 0.06], [r * 0.5, r * 0.24, r * 0.05], [-r * 0.34, r * 0.46, r * 0.065], [r * 0.16, r * 0.52, r * 0.045], [-r * 0.62, r * 0.1, r * 0.05]]) {
        g.circle(gx, gy, gr).fill({ color: 0x6b5a8c, alpha: 0.5 })
      }
    }
    if (elite) eliteCrown(-r * 0.92, r)
  }
  // antibody: an immunoglobulin — two Fab arms + one Fc stem, built as ONE union outline (each limb
  // tapers from a wide hinge to a rounded tip, with a concave notch where the three meet). No face:
  // it's a protein. Bronze/amber rather than pale gold, because pale gold sat at nearly the same
  // value as the pink floor and disappeared; the arms are chunky and rooted in a hinge mass so it
  // reads as something that GRABS.
  function drawAntibody(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const hx = 0
    const hy = -r * 0.12
    // [angle, length, halfW at hinge, halfW at tip] — slight length/angle asymmetry keeps it organic
    const limbs = [
      [Math.PI * 0.5, r * 0.98, r * 0.42, r * 0.3],   // Fc stem, down
      [Math.PI * 1.32, r * 0.98, r * 0.4, r * 0.27],  // Fab, up-left
      [Math.PI * 1.72, r * 0.94, r * 0.38, r * 0.25], // Fab, up-right (a touch shorter)
    ].sort((a, b) => a[0] - b[0])
    groundShadow(r, r * 1.0)
    // hinge mass: a chunk of protein where the three limbs meet. Drawn under the union so its dark
    // ring only shows in the notches between limbs — it fills them out into a grabbing claw rather
    // than a thin letter Y. Same geometry in both variants; well inside the union's bounds.
    g.circle(hx, hy, r * 0.52).fill(f(0xb87a24)).stroke({ width: Math.max(2, r * 0.2), color: f(0x5e360b) })
    const pts = []
    for (const [th, len, wH, wT] of limbs) {
      const ux = Math.cos(th)
      const uy = Math.sin(th)
      const nx = -uy
      const ny = ux
      // base corners sit slightly BEHIND the hinge so the limbs fuse; the chord between adjacent
      // limbs' base corners becomes the subtle hinge notch.
      const bx = hx - ux * r * 0.06
      const by = hy - uy * r * 0.06
      const ex = hx + ux * len
      const ey = hy + uy * len
      pts.push(bx - nx * wH, by - ny * wH)
      for (let i = 0; i <= 6; i++) { // rounded tip cap
        const a = th - Math.PI * 0.5 + (i / 6) * Math.PI
        pts.push(ex + Math.cos(a) * wT, ey + Math.sin(a) * wT)
      }
      pts.push(bx + nx * wH, by + ny * wH)
    }
    g.poly(pts).fill(f(0xb87a24)).stroke({ width: Math.max(2.4, r * 0.2), color: f(0x5e360b) })
    if (!white) {
      g.ellipse(hx, hy + r * 0.5, r * 0.34, r * 0.44).fill({ color: 0x5e360b, alpha: 0.22 })
      g.ellipse(hx - r * 0.44, hy - r * 0.46, r * 0.3, r * 0.32).fill({ color: mix(0xb87a24, 0xffffff, 0.45), alpha: 0.2 })
      g.circle(hx, hy, r * 0.3).fill({ color: 0x8c5511, alpha: 0.5 }) // hinge core
      g.circle(hx, hy, r * 0.13).fill({ color: 0x5e360b, alpha: 0.55 })
      for (const [th] of limbs) { // a crease from the hinge core into each limb — reads as a joint
        g.beginPath().moveTo(hx + Math.cos(th) * r * 0.28, hy + Math.sin(th) * r * 0.28)
          .lineTo(hx + Math.cos(th) * r * 0.62, hy + Math.sin(th) * r * 0.62)
          .stroke({ width: 1.4, color: 0x5e360b, alpha: 0.4, cap: 'round' })
      }
    }
    if (elite) eliteCrown(-r * 1.1, r)
  }

  // --- Pond chapter (teal water) ---
  // The pond floor is a mid-dark teal (bg 0x2e6258 under blotches multiplied by floorTint 0x66c2a9).
  // The old roster was a low-saturation green/olive/tan family — i.e. the floor's own family — and
  // camouflaged itself. The three creatures are now pushed apart on BOTH value and hue, and each
  // takes a different corner so they are also mutually distinct:
  //   amoeba     = BRIGHT (luminous chartreuse, glows off the teal)
  //   tadpole    = DARK   (near-black, a silhouette on the teal)
  //   tardigrade = LIGHT-WARM (pale amber sand, the only warm thing in the water)
  // Elite pond bodies are tinted by a pale iridescent hue (mixed 50% to white first), so the tint
  // multiply is gentle — these fills all survive it without going muddy (nothing here relies on a
  // channel that a pale blue/pink/mint multiply would crush).
  //
  // amoeba: one membrane whose radius is a sum of broad blunt pseudopod bumps over a low base, so
  // 4 pods reach out further than the rest, ringed on the leading side by a ragged cilia fringe.
  // Translucent ectoplasm + solid endoplasm + a much darker nucleus for internal contrast.
  function drawAmoeba(g, elite, white) {
    const r = 16
    groundShadow(r, r * 1.0)
    // blunt pseudopods: wide gaussians in 4 directions, unequal reach (nothing bilaterally boring)
    const pods = [[0.35, 1.0, 0.85], [1.95, 0.86, 1.0], [3.4, 0.95, 0.78], [5.05, 0.72, 0.92]]
    const membrane = (a) => {
      let rad = 0.54
      for (const [dir, len, wid] of pods) {
        let d = a - dir
        while (d > Math.PI) d -= Math.PI * 2
        while (d < -Math.PI) d += Math.PI * 2
        rad += 0.44 * len * Math.exp(-(d / wid) * (d / wid))
      }
      return r * Math.min(1, rad)
    }
    const lw = Math.max(2.5, r * 0.17)
    const line = white ? 0xffffff : 0x3f6a0c
    // cilia: short irregular tapered spikes, densest on the leading (right) side. Under the membrane
    // so the roots are hidden; identical geometry in both variants.
    const cilia = [[-0.95, 0.22], [-0.6, 0.13], [-0.28, 0.24], [0.06, 0.15], [0.34, 0.26], [0.62, 0.12],
      [0.94, 0.2], [1.3, 0.14], [2.62, 0.19], [2.95, 0.11], [3.9, 0.13], [4.3, 0.2], [5.5, 0.12], [5.9, 0.18]]
    for (const [a, len] of cilia) {
      const rad = membrane(a)
      taperStroke(g, [[Math.cos(a) * rad * 0.85, Math.sin(a) * rad * 0.85], [Math.cos(a) * (rad + r * len), Math.sin(a) * (rad + r * len)]],
        Math.max(1.8, r * 0.1), 0.7, line, 4)
    }
    if (white) {
      g.poly(radialOutline(membrane, 60)).fill(0xffffff).stroke({ width: lw, color: 0xffffff })
    } else {
      g.poly(radialOutline(membrane, 60)).fill({ color: 0xd8f24a, alpha: 0.55 }).stroke({ width: lw, color: line })
      g.poly(radialOutline((a) => membrane(a) * 0.68, 60, 1, 1, -r * 0.03, r * 0.02)).fill(0xd8f24a)
      g.ellipse(r * 0.02, r * 0.3, r * 0.44, r * 0.24).fill({ color: 0x6d9414, alpha: 0.28 })
      g.ellipse(-r * 0.14, -r * 0.24, r * 0.36, r * 0.2).fill({ color: 0xf4ffb0, alpha: 0.35 })
      g.ellipse(r * 0.3, r * 0.16, r * 0.32, r * 0.27).fill({ color: 0x27400a, alpha: 0.85 }) // nucleus
      g.ellipse(r * 0.3, r * 0.16, r * 0.14, r * 0.12).fill({ color: 0x101c03, alpha: 0.7 })
      g.circle(-r * 0.3, -r * 0.02, r * 0.16).stroke({ width: 1.6, color: 0x3f6a0c, alpha: 0.75 }) // vacuoles
      g.circle(-r * 0.06, -r * 0.34, r * 0.1).stroke({ width: 1.3, color: 0x3f6a0c, alpha: 0.65 })
    }
    if (elite) eliteCrown(-r * 0.95, r)
  }
  // tadpole: head + trunk + tail are ONE tapered path (no seam) — a spine that runs right-to-left
  // with an S-wave and a sin profile that is fat at the head and closes to a point at the tail tip,
  // wrapped in a translucent caudal fin. Near-black body + a bright pale belly + pale-rimmed eyes:
  // at 24px on mid-teal water it reads as a dark darting silhouette with two visible eye points.
  function drawTadpole(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const noseX = r * 1.0
    const len = r * 3.2 // nose at +1.0r -> tail tip at -2.2r
    const R0 = r * 0.82
    const spine = (t) => [noseX - t * len, Math.sin(t * Math.PI * 1.65) * r * 0.3 * Math.pow(t, 1.25)]
    // Profile = a fat trunk lobe (gaussian, peaking just behind the nose) + a thin muscular tail
    // rod that carries on to a point. Keeping the two terms separate is what makes the trunk read
    // as a body and the tail as a TAIL — a single sin() bulge just gives you a leaf.
    const body = (t) => {
      const nose = t < 0.1 ? Math.sqrt(1 - Math.pow((0.1 - t) / 0.1, 2)) : 1
      const trunk = Math.exp(-Math.pow((t - 0.18) / 0.24, 2))
      const rod = 0.22 * Math.pow(Math.max(0, 1 - t), 0.85)
      return R0 * nose * (trunk + rod)
    }
    // caudal fin: a tall translucent membrane wrapping the tail rod, closing at the tip
    const fin = (t) => (t < 0.28 ? 0 : R0 * 0.95 * bulge((t - 0.28) / 0.72, 0.65))
    groundShadow(r * 1.5, r * 0.85)
    // fin first (behind the body); solid on the white twin so bounds match its translucent self
    g.poly(spineOutline(spine, fin, 26, 0.28, 1)).fill(white ? 0xffffff : { color: 0x2f2a20, alpha: 0.5 })
    g.poly(spineOutline(spine, body, 30)).fill(f(0x241d16)).stroke({ width: Math.max(2.2, r * 0.16), color: f(0x0b0806) })
    if (!white) {
      g.ellipse(r * 0.32, r * 0.34, r * 0.52, r * 0.28).fill({ color: 0xd9cfae, alpha: 0.85 }) // pale belly
      g.ellipse(r * 0.3, -r * 0.36, r * 0.42, r * 0.2).fill({ color: 0x8c8068, alpha: 0.3 })   // dorsal sheen
      g.beginPath()
      for (let i = 0; i < 3; i++) { // myotome creases across the trunk, where there is still width
        const t = 0.3 + i * 0.075
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x + r * 0.05, y - w * 0.82).lineTo(x - r * 0.05, y + w * 0.82)
      }
      g.stroke({ width: 1.1, color: 0x8c8068, alpha: 0.4 })
      for (const s of [-1, 1]) { // lateral eyes: prominent, set wide, bright pale rim carries them
        g.ellipse(r * 0.56, s * r * 0.52, r * 0.22, r * 0.2).fill(0xe8dfc2)
        darkEye(g, r * 0.56, s * r * 0.52, r * 0.14, r * 0.13, 0x000000, true)
      }
    }
    if (elite) eliteCrown(-r * 0.92, r)
  }
  // tardigrade: water bear in a slight 3/4 profile — ONE lumpy tapered outline (4 segment lumps
  // riding a rear-narrowing taper, rounded snout cap on the right), 4 prominent near-side legs with
  // claws + 3 darker far-side legs behind for depth. Pale warm sand body with dark legs and dark
  // segment creases: the only warm-LIGHT thing in the cool mid-value water, and the creases keep it
  // from being a featureless light blob.
  function drawTardigrade(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const far = white ? 0xffffff : 0x4a2c10
    const near = f(0x8a5320)
    const frontX = r * 0.95
    const len = r * 1.95 // snout +0.95r -> rear -1.0r
    const H = r * 0.66
    const spine = (t) => [frontX - t * len, Math.sin(t * Math.PI) * r * 0.03]
    const body = (t) => {
      const cap = bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.5 ? 0.22 : 0.4)
      const ripple = 1 + 0.075 * Math.cos((t * 4 - 0.12) * Math.PI * 2)
      return H * cap * ripple * (1 - 0.3 * t)
    }
    groundShadow(r * 1.1, H + r * 0.32)
    const leg = (x, y, kx, ky, fx, fy, col, w) => {
      taperStroke(g, [[x, y], [kx, ky], [fx, fy]], w, w * 0.42, col)
      const ux = fx - kx
      const uy = fy - ky
      const m = Math.hypot(ux, uy) || 1
      for (const s of [-1, 1]) { // two tiny claws
        taperStroke(g, [[fx, fy], [fx + (ux / m) * r * 0.1 + s * (-uy / m) * r * 0.07, fy + (uy / m) * r * 0.1 + s * (ux / m) * r * 0.07]], w * 0.42, 0.8, col)
      }
    }
    // far side first (behind the body, darker) — shorter and higher, so the body overlaps them
    for (const t of [0.28, 0.55, 0.82]) {
      const [x, y] = spine(t)
      leg(x, y + H * 0.2, x - r * 0.14, y + H * 0.62, x - r * 0.2, y + H * 0.95, far, r * 0.13)
    }
    g.poly(spineOutline(spine, body, 40)).fill(f(0xecc888)).stroke({ width: Math.max(3, r * 0.14), color: f(0x6b4520) })
    // near side legs: stubby, jointed, splayed — angle/length varied per pair
    const nearLegs = [[0.2, 0.22, 1.0], [0.44, 0.06, 0.94], [0.68, -0.1, 1.0], [0.9, -0.2, 0.86]]
    for (const [t, sweep, scale] of nearLegs) {
      const [x, y] = spine(t)
      const oy = y + body(t) * 0.55
      leg(x, oy, x + sweep * r * 0.2, oy + r * 0.3 * scale, x + sweep * r * 0.34, oy + r * 0.58 * scale, near, r * 0.19)
    }
    if (!white) {
      g.ellipse(-r * 0.02, H * 0.42, r * 0.72, H * 0.44).fill({ color: 0x8a5320, alpha: 0.24 })
      g.ellipse(r * 0.06, -H * 0.4, r * 0.6, H * 0.3).fill({ color: 0xfff3d2, alpha: 0.4 })
      g.beginPath()
      for (const t of [0.24, 0.48, 0.72]) { // segment creases: deep and dark, the light body's detail
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x + r * 0.05, y - w * 0.86).lineTo(x - r * 0.04, y + w * 0.86)
      }
      g.stroke({ width: 2, color: 0x6b4520, alpha: 0.85 })
      g.beginPath() // far-side leg roots read as creases too
      g.moveTo(frontX - r * 0.02, -r * 0.12).lineTo(frontX - r * 0.02, r * 0.12)
      g.stroke({ width: 1.2, color: 0x6b4520, alpha: 0.5 })
      g.circle(r * 0.84, r * 0.02, r * 0.11).stroke({ width: 2.2, color: 0x4e2f12, alpha: 0.9 }) // terminal mouth ring
      g.circle(r * 0.84, r * 0.02, r * 0.045).fill({ color: 0x2a1806, alpha: 0.8 })
      // primitive eyespot: a pigment cup, but sat on a pale rim so the eye still lands at 24px
      g.ellipse(r * 0.6, -r * 0.16, r * 0.14, r * 0.125).fill(0xfff3d2)
      darkEye(g, r * 0.6, -r * 0.16, r * 0.085, r * 0.075, 0x1a1206, false)
      g.ellipse(r * 0.71, -r * 0.03, r * 0.055, r * 0.048).fill({ color: 0x1a1206, alpha: 0.5 })
    }
    if (elite) eliteCrown(-H * 1.05, r)
  }

  // --- Shelf chapter (open blue water) ---
  // Owner: "the enemies should be new, this is open sea not a pond" — then, on a first set of
  // jellyfish/squid/turtle: "too big, those could be for next chapter. maybe plankton, shrimp and
  // jelly". So the cast is the PLANKTON COLUMN, at the pond's own size class: nothing here is
  // bigger than the tardigrade it replaces, and two of the three are smaller.
  //
  // The Shelf floor is mid-blue (bg 0x18567f under blotches multiplied by floorTint 0x9fd6f0), so —
  // exactly as in the pond above — the three have to separate from the water on VALUE and HUE and
  // from each other as well. Warm is the whole opportunity: nothing else in this chapter is warm,
  // and it is also true to life (copepods and krill are carotenoid orange-red), so two of the three
  // take it and the third goes pale and cold.
  //   copepod = MID WARM   (saturated amber, the loudest body in the water)
  //   krill   = PALE WARM  (translucent coral, lighter and two thirds the size)
  //   jelly   = COLD LIGHT (dark bell, lit rim, the biggest and the only one that EMITS)
  // The jelly's column was "near-white bell, the faintest" until it went side-on: a lantern is the
  // opposite reading, and it is the better one for the same reason the rule was written. This
  // chapter dims its OWN world, so the question is what survives the scrim — and a body that emits
  // survives it completely, while the palest reflector is the first thing it takes.
  // EYE COUNT is the backup read, and it needs no light at all: the copepod has ONE median eye, the
  // krill has TWO on stalks, the jelly has none — three silhouettes still tellable apart at the edge
  // of your lamp. The jelly now also has the only non-plan-view silhouette in the chapter (see
  // drawJelly for why a water column earns that), which is a third, shape-only read on top.
  //
  // Every flag is inherited unchanged from the pond roster (split / dashBurst / phase+unshakeable):
  // this is an art change, and the spawn economy the refill sweep was tuned against is untouched.

  // copepod: the plankton everyone has seen down a microscope. A blunt teardrop prosome, a narrow
  // segmented urosome behind it, two caudal setae trailing, and the pair of enormous first antennae
  // held out sideways that nothing else in this game has — at 24px the antennae ARE the silhouette,
  // the body is just the blob between them. One median (nauplius) eye, dead centre on the head.
  //
  // The paired EGG SACS are not decoration. This is the roster's `split` carrier, and a gravid
  // copepod slung with two egg sacs that burst into nauplii is exactly, literally what the flag
  // does (SPLIT_CHILD_COUNT = 2, at SPLIT_RADIUS_FRAC 0.7 of the parent). They are drawn where they
  // really sit, either side of the prosome/urosome joint, so the tell is on the animal before it
  // dies rather than being a surprise afterwards.
  function drawCopepod(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x7c3c08)
    const noseX = r * 0.92
    const len = r * 1.5           // prosome: nose +0.92r -> waist -0.58r
    const H = r * 0.4             // SLIM. A round prosome plus jointed limbs is a flea, not plankton
    const spine = (t) => [noseX - t * len, 0]
    // Blunt round head, narrowing steadily to the waist: k=0.3 up front is the tardigrade's flat-cap
    // trick, k=0.85 behind lets it actually taper to a teardrop instead of closing as a capsule.
    const prosome = (t) => H * bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.4 ? 0.3 : 0.85)
    groundShadow(r * 1.15, H + r * 0.18)
    const waistX = noseX - len
    // FIRST ANTENNAE — the whole silhouette. Held nearly STRAIGHT OUT to the sides and barely swept,
    // which is the copepod's own resting pose and the thing that separates it from every jointed
    // bug in this bestiary: two long straight spars making a T, not a splay of legs. Drawn before
    // the body so their roots disappear under it, and identical in both twins (taperStroke takes
    // `line`, which is white on the flash twin) so the baked bounds stay equal.
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 0.6, s * H * 0.5], [r * 0.36, s * r * 1.0], [r * 0.08, s * r * 1.92]],
        Math.max(1.7, r * 0.105), 0.7, line, 6)
    }
    // swimming legs: three short paired oars, tucked close under the prosome. Deliberately stubby —
    // long jointed legs are what made the first cut of this read as an insect.
    for (let i = 0; i < 3; i++) {
      const t = 0.42 + i * 0.16
      const [x] = spine(t)
      const w = prosome(t)
      for (const s of [-1, 1]) {
        taperStroke(g, [[x, s * w * 0.5], [x - r * 0.13, s * (w + r * 0.17)]], Math.max(1.1, r * 0.065), 0.6, line, 2)
      }
    }
    // urosome + caudal setae: a narrow rod carrying on from the waist, ending in two splayed hairs
    const uroLen = r * 0.8
    const uro = (t) => [waistX - t * uroLen, 0]
    const uroW = (t) => H * (0.36 - 0.16 * t)
    g.poly(spineOutline(uro, uroW, 10)).fill(f(0xd97a22)).stroke({ width: Math.max(1.7, r * 0.095), color: line })
    for (const s of [-1, 1]) {
      taperStroke(g, [[waistX - uroLen, s * H * 0.1], [waistX - uroLen - r * 0.66, s * r * 0.3]],
        Math.max(1.4, r * 0.08), 0.7, line, 3)
    }
    // EGG SACS. BEHIND the waist, flanking the urosome and angled back like a pair of saddlebags —
    // this is where a gravid copepod really carries them, and it is also the only placement that
    // reads as CARRIED. The first cut sat them over the prosome and they read as beetle wing-cases.
    for (const s of [-1, 1]) {
      const ex = waistX - uroLen * 0.42
      const ey = s * (H * 0.42 + r * 0.13)
      g.ellipse(ex, ey, r * 0.3, r * 0.17)
        .fill(white ? 0xffffff : { color: 0xa9cede, alpha: 0.95 })
        .stroke({ width: Math.max(1.3, r * 0.07), color: line })
      if (!white) {
        for (const [ox, oy] of [[-0.11, -0.02], [0.02, 0.03], [0.13, -0.01]]) {
          g.circle(ex + ox * r, ey + oy * r, r * 0.05).fill({ color: 0x5d86a0, alpha: 0.6 })
        }
      }
    }
    g.poly(spineOutline(spine, prosome, 34)).fill(f(0xef8f28)).stroke({ width: Math.max(2.2, r * 0.14), color: line })
    if (!white) {
      g.ellipse(noseX - r * 0.5, -H * 0.34, r * 0.5, H * 0.3).fill({ color: 0xffd9a0, alpha: 0.45 }) // dorsal sheen
      g.ellipse(noseX - r * 0.72, H * 0.38, r * 0.42, H * 0.26).fill({ color: 0xa8560c, alpha: 0.26 })
      g.beginPath()
      for (const t of [0.52, 0.7, 0.86]) { // prosome segment creases
        const [x] = spine(t)
        const w = prosome(t)
        g.moveTo(x, -w * 0.88).lineTo(x, w * 0.88)
      }
      g.stroke({ width: 1.3, color: 0x8f4a0c, alpha: 0.6 })
      g.beginPath()
      for (let i = 1; i < 3; i++) { // urosome segments
        const x = waistX - (i / 3) * uroLen
        g.moveTo(x, -H * 0.26).lineTo(x, H * 0.26)
      }
      g.stroke({ width: 1.1, color: 0x8f4a0c, alpha: 0.55 })
      // the single median eye: one dark red lens on the midline, the copepod's whole species read
      g.ellipse(noseX - r * 0.16, 0, r * 0.2, r * 0.17).fill(0xffe0b4)
      darkEye(g, noseX - r * 0.16, 0, r * 0.13, r * 0.115, 0x8c1218, true)
    }
    if (elite) eliteCrown(-r * 1.5, r)
  }

  // krill: a small shrimp, and drawn as one — segmented carapace, a rostrum spike off the front, two
  // BLACK STALKED EYES set wide, a row of thoracic legs down each side and a three-bladed tail fan.
  // Pale translucent coral with hard dark segment creases: at 18px on blue it reads as a light,
  // busy, fast thing, which is the archetype. The tail fan is what sells `dashBurst` — the flag is a
  // burst of speed and a krill's escape is one flick of exactly that fan.
  function drawKrill(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0xb04a2e)
    const noseX = r * 1.05
    const len = r * 2.5           // rostrum tip +1.05r -> tail root -1.45r
    const H = r * 0.44
    // A shrimp is never straight: a gentle constant camber down the body, deepest at the abdomen.
    const spine = (t) => [noseX - t * len, Math.sin(t * Math.PI * 0.85) * r * 0.16]
    const body = (t) => {
      const head = Math.exp(-Math.pow((t - 0.26) / 0.22, 2))       // fat carapace
      const tail = 0.42 * Math.pow(Math.max(0, 1 - t), 0.7)        // abdomen tapering back
      const cap = t < 0.08 ? Math.sqrt(Math.max(0, 1 - Math.pow((0.08 - t) / 0.08, 2))) : 1
      return H * cap * (head + tail)
    }
    groundShadow(r * 1.3, H + r * 0.3)
    // antennae: two long ones streaming back past the tail, the giveaway that this is a crustacean
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 0.78, s * H * 0.5], [-r * 0.4, s * r * 0.66], [-r * 1.9, s * r * 0.82]],
        Math.max(1.4, r * 0.1), 0.7, line, 5)
    }
    // thoracic legs: six short paired oars under the carapace
    for (let i = 0; i < 6; i++) {
      const t = 0.2 + i * 0.078
      const [x, y] = spine(t)
      const w = body(t)
      for (const s of [-1, 1]) {
        taperStroke(g, [[x, y + s * w * 0.6], [x - r * 0.1, y + s * (w + r * 0.26)]], Math.max(1.1, r * 0.07), 0.6, line, 2)
      }
    }
    // TAIL FAN: telson on the midline plus a uropod blade either side, the whole thing spread
    const [tx, ty] = spine(1)
    for (const [ax, ay] of [[-r * 0.72, 0], [-r * 0.62, -r * 0.44], [-r * 0.62, r * 0.44]]) {
      g.poly([tx, ty, tx + ax, ty + ay - r * 0.1, tx + ax * 1.1, ty + ay + r * 0.1])
        .fill(white ? 0xffffff : { color: 0xff9d84, alpha: 0.85 }).stroke({ width: Math.max(1.3, r * 0.08), color: line })
    }
    g.poly(spineOutline(spine, body, 30)).fill(f(0xffc0a6)).stroke({ width: Math.max(2, r * 0.15), color: line })
    if (!white) {
      g.beginPath()
      for (let i = 0; i < 5; i++) { // abdominal segment creases, the busy detail that reads as "shrimp"
        const t = 0.5 + i * 0.1
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x + r * 0.04, y - w * 0.92).lineTo(x - r * 0.04, y + w * 0.92)
      }
      g.stroke({ width: 1.3, color: 0xc4553a, alpha: 0.8 })
      g.ellipse(noseX - r * 0.6, -H * 0.4, r * 0.5, H * 0.34).fill({ color: 0xfff0e4, alpha: 0.5 }) // carapace sheen
      // photophores: the light organs a krill actually has. Two faint dots — and in a chapter about
      // stealing light, the one animal here that MAKES its own gets to show it.
      for (const t of [0.62, 0.82]) {
        const [x, y] = spine(t)
        g.circle(x, y, r * 0.075).fill({ color: 0xbfefff, alpha: 0.75 })
      }
      // two black eyes on short stalks, set wide off the rostrum
      for (const s of [-1, 1]) {
        taperStroke(g, [[noseX - r * 0.62, s * H * 0.36], [noseX - r * 0.34, s * H * 0.78]], Math.max(1.2, r * 0.08), 1, 0xb04a2e, 2)
        darkEye(g, noseX - r * 0.3, s * H * 0.86, r * 0.16, r * 0.15, 0x140a08, true)
      }
    }
    if (elite) eliteCrown(-r * 1.05, r)
  }

  // MOON JELLY, side elevation. Owner: "I want some design with tentacles. It's a top down game but
  // those chapters are in the water so the jellyfish can be sideways." That is an exception to the
  // plan-view rule in CLAUDE.md rather than a breach of it: the rule exists because the camera looks
  // at a FLOOR, and an animal hanging in a water column has no floor to lie on. (The v6.8 tornado
  // failed the mirror-image test — a ground-attached thing drawn as though it were not.)
  //
  // ORIENTATION IS LOAD-BEARING. The apex points +x, the axis ROSTER_LOOKS aims at the player, and
  // the mouth and every tentacle trail to -x — so the body is bilaterally symmetric about the
  // forward axis, and lean 90 is legal by the same argument as the tadpole's. It therefore swims
  // bell-first at you with its tentacles streaming behind, which is how a jelly actually moves, and
  // it costs no new facing code: just a nose the existing machinery can already aim. Bell-UP with
  // tentacles hanging down would instead be a distinct UP, i.e. lean 30, and would drift sideways.
  //
  // The bake anchors on the drawing ORIGIN (see bake()), so the trailing tentacles hang off the back
  // without dragging the sprite off its hit circle. The bell stays centred on the origin for that
  // reason — r = 26 is the hitbox, and the tentacles are overhang exactly like the tadpole's tail.
  //
  // It is a LANTERN: dark body, lit rim, a bead of light at every tentacle tip. This chapter dims
  // its own world (The Shelf's Light bar), and a creature that EMITS rather than reflects is the one
  // still readable at the edge of your lamp. That inverts the role it used to play in the cast, so
  // the art-direction block above is written to match rather than left to contradict it.
  //
  // It carries the tardigrade's `phase` (PHASE_* in config.js), ghosting through obstacles and out
  // of damage for 1.0s in every 2.6s, and a jelly is already the translucent thing you cannot get
  // hold of. The low fill alpha is that fact drawn: solid enough to read against dark water, thin
  // enough that the ghost frames are a difference of degree rather than a costume change.
  function drawJelly(g, elite, white) {
    const r = 26
    const xf = r * 0.78     // apex, forward
    const xa = -r * 0.36    // mouth plane, aft
    const hw = r * 0.90     // half-width at the margin
    const N = 30
    const FILL = 0x123a52
    const LINE = 0x7fe7ff
    const TENT = 0x6fd8f5
    const TIP = 0xeaffff
    const ARM = 0xffc4ee
    const CANAL = 0x8fe4ff
    const GONAD = 0xffb0e4
    groundShadow(r * 0.78, r * 0.72)
    // Bell profile: half-width 0 at the apex (t=0) to hw at the margin (t=1). (2t - t^2)^0.5 is
    // exactly a half-ellipse, i.e. a DOME — round at the apex, falling away at the sides. The first
    // cut used sin((pi/2) * t^0.6), which comes to a point and reads as a leaf.
    const prof = (t) => hw * Math.pow(Math.max(0, 2 * t - t * t), 0.46)
    // The mouth is barely concave, and it is STROKED SEPARATELY from the dome. The first cut bulged
    // it 0.24r forward and stroked it at the dome's full weight as one closed outline, which drew a
    // hard bright arc across the middle of the body: the bell then read as a clam, split into a lens
    // and a crescent. Only the dome gets the heavy line.
    const mouthX = (s) => xa + r * 0.24 * (1 - (2 * s - 1) ** 2)
    const dome = []
    for (let i = N; i >= 0; i--) { const t = i / N; dome.push(xf + (xa - xf) * t, -prof(t)) }
    for (let i = 0; i <= N; i++) { const t = i / N; dome.push(xf + (xa - xf) * t, prof(t)) }
    const mouth = []
    for (let i = 1; i < 14; i++) { const s = 1 - i / 14; mouth.push(mouthX(s), -hw + 2 * hw * s) }
    const outline = [...dome, ...mouth]

    // TENTACLES first, so the translucent bell sits over their roots and they emerge from under it.
    // FORESHORTENING IS WHAT MAKES THE RIM READ AS A CIRCLE. The margin is a ring seen edge-on, so
    // the tentacles near y=0 are the ones on its near and far side, pointing away from the camera —
    // they project SHORT. Giving them all one length drew a flat parallel curtain, i.e. a broom.
    // Length scales with |y0|/hw, and the short middle ones are drawn first so the long rim ones
    // pass in front of them.
    const hash = (i) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x) }
    const tent = []
    for (let i = 0; i < 16; i++) {
      const s = (i + 0.5) / 16
      const y0 = -hw + 2 * hw * s
      tent.push({ y0, s, fore: Math.abs(y0) / hw })
    }
    tent.sort((a, b) => a.fore - b.fore)
    for (let i = 0; i < tent.length; i++) {
      const { y0, s, fore } = tent[i]
      const x0 = mouthX(s) * 0.5 + xa * 0.5
      const L = r * 1.9 * (0.28 + 0.72 * fore) * (0.7 + 0.3 * hash(i))
      const ph = hash(i + 7) * Math.PI * 2
      const pts = []
      for (let k = 0; k <= 9; k++) {
        const t = k / 9
        pts.push([x0 - L * t, y0 * (1 - 0.06 * t) + Math.sin(ph + t * 7) * r * 0.10 * t * fore])
      }
      taperStroke(g, pts, r * 0.032, r * 0.008, white ? 0xffffff : TENT, 2)
      if (!white) g.circle(pts[9][0], pts[9][1], r * 0.045).fill({ color: TIP, alpha: 0.9 })
    }
    // Four oral arms, of which three read in profile: broad ruffled ribbons off the mouth. They have
    // to stay visibly WIDER than the tentacles or they are simply three more tentacles.
    for (let i = 0; i < 3; i++) {
      const y0 = (i - 1) * hw * 0.36
      const spine = (t) => [xa - r * 1.15 * t, y0 * (1 + 0.3 * t) + Math.sin(t * Math.PI * 2.2 + i * 2.1) * r * 0.11 * t]
      g.poly(spineOutline(spine, (t) => r * (0.012 + 0.11 * (1 - t * 0.8)), 18))
        .fill({ color: white ? 0xffffff : ARM, alpha: white ? 1 : 0.5 })
    }
    if (white) {
      g.poly(outline).fill(0xffffff).stroke({ width: Math.max(2.4, r * 0.1), color: 0xffffff })
      if (elite) eliteCrown(-r * 1.02, r)
      return
    }
    for (let k = 0; k < 3; k++) {
      g.poly(dome, false).stroke({ width: r * (0.10 + 0.07 * k), color: LINE, alpha: 0.08 })
    }
    g.poly(outline).fill({ color: FILL, alpha: 0.55 })
    g.poly(mouth, false).stroke({ width: Math.max(1, r * 0.03), color: LINE, alpha: 0.35 })
    g.poly(dome, false).stroke({ width: Math.max(1.6, r * 0.055), color: LINE, alpha: 0.85 })
    // Two of the four radial canals run the bell's length edge-on, with a gonad horseshoe on each —
    // the plan view's clover, turned 90deg. The horseshoes are arcs of their OWN circle rather than
    // chords of the bell profile, which is what stopped them reading as two isolated dashes.
    for (const sgn of [-1, 1]) {
      const canal = []
      for (let i = 3; i <= N - 3; i++) { const t = i / N; canal.push([xf + (xa - xf) * t, sgn * prof(t) * 0.60]) }
      taperStroke(g, canal, r * 0.028, r * 0.028, CANAL, 1)
      const gx = xf + (xa - xf) * 0.46
      const gy = sgn * hw * 0.40
      const arc = []
      for (let i = 0; i <= 16; i++) {
        const b = Math.PI * 0.18 + (i / 16) * Math.PI * 1.28
        arc.push([gx + Math.cos(b) * r * 0.21, gy + sgn * Math.sin(b) * r * 0.17])
      }
      taperStroke(g, arc, r * 0.095, r * 0.095, GONAD, 2)
    }
    if (elite) eliteCrown(-r * 1.02, r)
  }

  // --- Surf chapter (Book 2 ch 1, pale sand) ---
  // Beach sand is pale and warm, so this cast is the opposite problem from the Shelf's plankton
  // above: nothing here can be a pale warm body without vanishing into the floor. Two go one hue
  // further than the sand can follow, the third goes the other direction entirely:
  //   shorecrab  = DEEP RED-ORANGE  (the loudest, darkest body on the beach — a real shore crab's
  //                own colouring, and the one hue sand never reaches)
  //   sandhopper = MID GREY-BROWN   (close to the sand's hue but a full step down in VALUE, so it
  //                reads as a shadow moving across the beach rather than more sand)
  //   gull       = NEAR-WHITE COLD  (the one creature the warm floor cannot touch at all — it wins
  //                by contrast, not by finding a colour nothing else owns)
  // BACKUP READ — what each keeps once colour and detail have both dissolved to a dot at range:
  // the crab's two raised claws, the hopper's long trailing jump-legs, the gull's notched wingtips.

  // sandhopper (Talitrus saltator, "beach flea"): a small amphipod, plan view. A gently arched,
  // segmented body with short antennae up front and short walking legs down both flanks — ordinary
  // crustacean furniture, all of it deliberately understated. The one limb drawn LOUD is the pair of
  // long, thick uropods kicked out behind the tail: the actual jumping legs, and the reason this
  // animal is called a hopper at all. Everything else here can blur into the sand; those cannot.
  function drawSandhopper(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x3c3220)
    const noseX = r * 0.8
    const len = r * 1.7             // nose +0.8r -> tail -0.9r
    const H = r * 0.34
    // a shallow dorsal arch, deepest at the third segment and tapering hard toward the tail
    const spine = (t) => [noseX - t * len, -Math.sin(t * Math.PI) * r * 0.06]
    const body = (t) => H * bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.32 ? 0.3 : 0.65)
    groundShadow(r * 1.0, H + r * 0.24)
    // short paired antennae, held forward and low
    for (const s of [-1, 1]) {
      taperStroke(g, [[noseX - r * 0.02, s * H * 0.36], [noseX + r * 0.36, s * r * 0.3]],
        Math.max(1.2, r * 0.08), 0.6, line, 3)
    }
    // seven short pereopod pairs down the flanks — busy and stubby, nothing here competes with the tail
    for (let i = 0; i < 7; i++) {
      const t = 0.14 + i * 0.1
      const [x] = spine(t)
      const w = body(t)
      for (const s of [-1, 1]) {
        taperStroke(g, [[x, s * w * 0.55], [x - r * 0.04, s * (w + r * 0.14)]], Math.max(1, r * 0.05), 0.5, line, 2)
      }
    }
    // THE TELL: a pair of long, thick uropods kicked back off the tail, drawn heavier and longer
    // than every other limb on the body so they read as the one weapon even at 12px
    const [tx, ty] = spine(1)
    for (const s of [-1, 1]) {
      taperStroke(g, [[tx, ty + s * H * 0.16], [tx - r * 0.5, ty + s * r * 0.36], [tx - r * 0.92, ty + s * r * 0.56]],
        Math.max(1.7, r * 0.12), 0.75, line, 4)
    }
    g.poly(spineOutline(spine, body, 30)).fill(f(0x8a7a5e)).stroke({ width: Math.max(2, r * 0.13), color: line })
    if (!white) {
      g.ellipse(noseX - r * 0.34, -H * 0.32, r * 0.42, H * 0.3).fill({ color: 0xb8a578, alpha: 0.4 }) // dorsal sheen
      g.beginPath()
      for (const t of [0.3, 0.5, 0.7, 0.86]) { // segment creases
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x, y - w * 0.85).lineTo(x, y + w * 0.85)
      }
      g.stroke({ width: 1.1, color: 0x5c4c30, alpha: 0.6 })
      for (const s of [-1, 1]) darkEye(g, noseX - r * 0.08, s * H * 0.44, r * 0.075, r * 0.07, 0x1c150c, s > 0)
    }
    if (elite) eliteCrown(-r * 0.95, r)
  }

  // shore crab: plan view, and the one animal on this roster whose real gait is SIDEWAYS rather
  // than nose-forward — which is exactly why ROSTER_LOOKS gives it lean 0 instead of turning to
  // square up at the player the way everything else here does. A carapace WIDER than it is long
  // (the trait that separates it from every other rounded tank in this game), eight walking legs
  // fanned to the flanks, and two big claws held forward, raised clear of the shell and closing to
  // a point — the backup read that survives once the deep red-orange has gone to grey.
  // THE CLAW, painted into any Graphics rather than baked into one texture — the Pincer weapon and
  // the Shore Crab's guard are the same drawing at different sizes, and a second hand-drawn claw
  // would drift from this one the first time either is touched.
  //   R    the claw's reach: it occupies x in [0.46R, R], so its LENGTH is 0.54R. Size is a RATIO,
  //        which is what lets the weapon state its own tested radius (placeGuard scales by
  //        r / CLAW_BAKE_R and the fingertips land on the catch radius) while the crab picks an R
  //        that simply matches its own body.
  //   rot/ox/oy  where to put it. Every coordinate goes through P(), so the caller can hold the
  //        claw ACROSS its body instead of pointing along the facing — a shield is perpendicular to
  //        the threat, which is the note that killed four cuts of the weapon's art.
  //   white  the silhouette pass used by the cast bake, same contract as every draw* above.
  //   col  the palette. Defaults to the WEAPON's warm orange, which was chosen to read on teal water
  //        and to sit apart from every enemy tint in the surf roster — so a creature holding this
  //        claw must override it, or it wears another species' colours and reads as clipped on.
  function paintClaw(g, R, open, { rot = 0, ox = 0, oy = 0, white = false, col = null } = {}) {
    const f = (c) => white ? 0xffffff : c
    const c0 = col || { shell: 0xe8763c, lit: 0xffc08a, line: 0x7a2f12, nail: 0xf6bd85, tooth: 0xfff0d8, stub: 0xc55c29 }
    const shell = f(c0.shell)
    const lit = f(c0.lit)
    const line = f(c0.line)
    const nail = f(c0.nail)    // the FINGERS are paler than the palm, as a fiddler's actually are;
    const tooth = f(c0.tooth)  // that two-tone is most of what makes the gape legible at phone size
    const cs = Math.cos(rot), sr = Math.sin(rot)
    const P = (x, y) => [ox + x * cs - y * sr, oy + x * sr + y * cs]
    const x0 = R * 0.46             // the wrist, clear of the body carrying it
    const L = R - x0                // claw length; for the weapon, the tips land on the tested radius
    const px = x0 + L * 0.55        // the palm's front, where the fingers leave it
    const pd = L * 0.19             // palm half-depth: a 1.4:1 mass, a fiddler's own proportion
    // BOTH fingers hinge, and the gape straddles the claw's axis rather than opening upward off
    // it — a claw whose lower half is a fixed baseline reads as a hand. The dactyl swings twice
    // as far as the pollex, which is the asymmetry that keeps this a claw and not pliers.
    const sP = open ? 0.26 : 0.03
    const sD = open ? 0.50 : 0.03

    // Carpus stub, angled back to the body so the claw is CARRIED rather than floating. Short
    // and thin: the pre-v7.75 bake ran a long thick limb back to the player, and at phone size
    // that stem turned the whole sprite into a carrot.
    taperStroke(g, [P(x0 - L * 0.30, L * 0.13), P(x0 + L * 0.16, L * 0.03)],
      L * 0.09, L * 0.15, f(c0.stub), 4)

    // A finger: swung about its hinge, and outlined by laying a fatter dark stroke under the
    // pale one. Built from ONE description at two angles, so open and shut cannot disagree about
    // where the tips are. `hook` curves the centreline back toward the axis, which is what makes
    // the gape a LENS; two straight fingers at an angle are a pair of tweezers.
    const finger = (hxx, hyy, th, len, hook, w0, w1) => {
      const c = Math.cos(th), sn = Math.sin(th)
      const pts = []
      for (let i = 0; i <= 4; i++) {
        const u = i / 4
        const sx = len * u, sy = hook * Math.pow(u, 1.5)
        pts.push(P(hxx + sx * c - sy * sn, hyy + sx * sn + sy * c))
      }
      taperStroke(g, pts, w0 + L * 0.05, w1 + L * 0.045, line, 6)
      taperStroke(g, pts, w0, w1, nail, 6)
      return pts
    }
    // POLLEX — heavier, swings least, hooks up toward the axis so its tip meets the dactyl's.
    const pol = finger(px - L * 0.08, L * 0.05, sP, L * 0.53, -L * 0.09, L * 0.125, L * 0.028)
    // DACTYL — slimmer, swings furthest, hooks down onto the pollex.
    const dac = finger(px - L * 0.11, -L * 0.09, -sD, L * 0.56, L * 0.16, L * 0.105, L * 0.024)

    // PALM last, so it covers both finger roots and they read as growing out of it. A smooth
    // oval mass narrowing at both ends — two earlier cuts baked a hexagon and then a brick,
    // both because the depth profile was flat across its middle instead of curved.
    const dep = (t) => pd * Math.pow(Math.sin(Math.PI * (0.06 + 0.80 * t)), 0.85)
    const pal = []
    const N = 20
    for (let i = 0; i <= N; i++) { const t = i / N; pal.push(...P(x0 + (px - x0) * t, -dep(t) * 0.94)) }
    for (let i = N; i >= 0; i--) { const t = i / N; pal.push(...P(x0 + (px - x0) * t, dep(t) * 1.06)) }
    g.poly(pal).fill(shell).stroke({ width: Math.max(1.4, L * 0.044), color: line })

    // Teeth on both cutting faces, pointing across the gape at the gap a body has to cross —
    // read straight off the finger centrelines so they cannot drift off the fingers when the
    // swing changes. Shutting the claw hides them, which is its own tell.
    for (const [pts, sgn] of [[pol, -1], [dac, 1]]) {
      for (let i = 1; i <= 3; i++) {
        const a = pts[i], b = pts[i + 1]
        const nx = -(b[1] - a[1]), ny = b[0] - a[0]
        const nl = Math.hypot(nx, ny) || 1
        const w = L * (0.088 - 0.020 * i)
        g.circle(a[0] + (nx / nl) * w * sgn, a[1] + (ny / nl) * w * sgn, L * 0.025)
          .fill({ color: tooth, alpha: 0.9 })
      }
    }
    if (white) return
    // Granulation and the top highlight. The camera looks straight down, so the lit face is the
    // upper surface — a plan view's only shading cue, and the one every creature bake uses.
    for (let i = 0; i < 4; i++) {
      const t = 0.30 + 0.15 * i
      const c = P(x0 + (px - x0) * t, dep(t) * (0.18 + 0.24 * (i % 2)))
      g.circle(c[0], c[1], L * 0.022).fill({ color: line, alpha: 0.22 })
    }
    const hi = []
    for (let i = 0; i <= 10; i++) { const t = 0.12 + 0.66 * (i / 10); hi.push(...P(x0 + (px - x0) * t, -dep(t) * 0.5)) }
    g.poly(hi).stroke({ width: L * 0.05, color: lit, alpha: 0.55 })
  }

  // The crab's own claw palette: the weapon's warm orange belongs to the weapon.
  const CRAB_CLAW_COL = { shell: 0xc1391b, lit: 0xe0693a, line: 0x4a1206, nail: 0xd9705a, tooth: 0xffe8dc, stub: 0x9c2a12 }

  // ---- Shore Crab, TWO POSES (v7.76) --------------------------------------------------------
  // The crab alternates GUARDED (direct hits do nothing) and OPEN on a timer, so the player has to
  // read the state off the sprite in a crowd, on a phone, while being chased. That read is carried
  // by the SILHOUETTE'S ASPECT, never by interior detail — at 50px there is no interior:
  //   GUARDED  DEEP and NARROW. One unbroken convex wall of shell thrown across the front, legs
  //            drawn in under the body, no face. Bounds run long in +x and short in ±y.
  //   OPEN     WIDE and SHALLOW. Both claws swung out to the flanks and GAPING, legs fanned, the
  //            whole dorsal shell bare with its sheen and its eyes on top. Bounds run short in +x
  //            and long in ±y.
  // Those two outlines cannot be confused at any size, which is the only property that survives a
  // phone screen. Everything below is in service of one of them.
  //
  // Draw ORDER carries the depth, because a plan view has no other way to say "raised":
  //   guarded  shell first, claws painted OVER it -> the claws are held above the body.
  //   open     claws first, shell painted OVER their roots -> the claws are down beside the body.
  // That is the same observation the old guard comment made, used in both directions.

  // ONE CHELA of the guard, and NOT paintClaw. The weapon's claw is drawn along its own axis and a
  // shut one tapers to a point; a point is not cover, which is why both cuts that reused it were
  // rejected. This one is built on an ARC: the wrist sits out at the shoulder, the arc bows FORWARD
  // and runs INWARD to a blunt tip a little past the centreline, so the mirrored pair OVERLAP in
  // the middle and each tip is hidden behind the other one. What is left in silhouette is a single
  // continuous bowed wall with no notch and no arrowhead. It still reads as a claw rather than a
  // plank because the mass is a chela's — fat at the wrist, the paler fingers occupying the inner
  // third, split by a dark shut seam — and because the arm carrying it is visible at the outer end.
  const CRAB_CHELA_W = [0.30, 0.33, 0.32, 0.28, 0.22, 0.13] // half-depth / r, sampled along t=0..1
  // arc = [wrist, control, tip] in units of r, written for s=+1; the y of the tip is the OVERLAP,
  // i.e. how far past the centreline this chela reaches into its twin's half.
  function crabChelaSpine(r, s, arc) {
    const [P0, P1, P2] = arc.map(([x, y]) => [r * x, s * r * y])
    return (t) => {
      const u = 1 - t
      return [u * u * P0[0] + 2 * u * t * P1[0] + t * t * P2[0],
        u * u * P0[1] + 2 * u * t * P1[1] + t * t * P2[1]]
    }
  }
  function crabChelaDep(r, k, w = CRAB_CHELA_W) {
    return (t) => {
      const u = Math.min(0.9999, Math.max(0, t)) * (w.length - 1)
      const i = Math.floor(u)
      return r * k * (w[i] + (w[i + 1] - w[i]) * (u - i))
    }
  }
  // The half-depth profile WITH THE PINCER NOTCH, and the notch is the whole point. Every smooth
  // egg-shaped chela this file tried read as half a bivalve — a crab sitting in a cracked shell —
  // because a smooth taper is a shell's outline and a claw's is not. A real chela steps DOWN where
  // the fingers leave the palm, from a fat rounded manus to a pair of slim ones, and that single
  // step is what the eye uses to name the shape. Two of them held across the front therefore read
  // as knuckles bridged by crossed fingers, not as one plank and not as an opening shell.
  // The wrist end is BLUNT (0.23, not the 0.16 the first cut used). A palm that narrows to a neck
  // before the arm meets it leaves a concave wedge between the two, and a concave wedge on a red
  // shell reads as a chip knocked out of it.
  const CRAB_PALM_W = [0.23, 0.30, 0.34, 0.33, 0.30]   // u = 0 .. 0.56, the manus
  const CRAB_FINGER_W = [0.17, 0.145, 0.105, 0.05]     // u = 0.56 .. 1, past the notch
  const CRAB_NOTCH_U = 0.56
  function crabNotchDep(r, k, fw = CRAB_FINGER_W) {
    const lerp = (w, v) => {
      const u = Math.min(0.9999, Math.max(0, v)) * (w.length - 1)
      const i = Math.floor(u)
      return w[i] + (w[i + 1] - w[i]) * (u - i)
    }
    return (t) => r * k * (t < CRAB_NOTCH_U
      ? lerp(CRAB_PALM_W, t / CRAB_NOTCH_U)
      : lerp(fw, (t - CRAB_NOTCH_U) / (1 - CRAB_NOTCH_U)))
  }
  // The outward normal at t: the side of the arc facing AWAY from the body. Used for the lit
  // leading edge, which is the single strongest "this is hard armour" cue a plan view has.
  function crabChelaRim(spine, dep, t0, t1, n, push) {
    const pts = []
    for (let i = 0; i <= n; i++) {
      const t = t0 + (t1 - t0) * (i / n)
      const [x, y] = spine(t)
      const [ax, ay] = spine(Math.max(0, t - 0.01))
      const [bx, by] = spine(Math.min(1, t + 0.01))
      const dx = bx - ax, dy = by - ay
      const m = Math.hypot(dx, dy) || 1
      let nx = -dy / m, ny = dx / m
      if (nx * x + ny * y < 0) { nx = -nx; ny = -ny }
      pts.push(x + nx * dep(t) * push, y + ny * dep(t) * push)
    }
    return pts
  }

  // The Shore Crab's two poses, as tuning for ONE draw function. Both were picked off a contact
  // sheet at true gameplay size; what separates them is SILHOUETTE ASPECT, because at ~50px on a
  // phone there is no interior detail left to read. Guarded is a compact, forward-massed block with
  // nothing protruding; open is a wide spiky star. Three further tells stack on that same pair so
  // the state survives a crowd: guarded has no face and a shaded shell, open has both eyestalks up
  // on a bright bare one, and DRAW ORDER carries depth in each direction — guarded paints the
  // chelae OVER the shell, open paints the shell over the wrists, which in a plan view is the only
  // way to say "claws down".
  //
  // Do not "improve" these by adding interior contrast. A lit rim laid just inside each palm's dark
  // outline was tried four times and read as a CRACKED SHELL the crab was sitting in — it looks
  // like craftsmanship at 3x zoom and destroys the read at the size the game is played at, which is
  // why `bare: 1` is set. Same lesson as the Pincer's own art: detail above gameplay size is a lie.
  // How fast the crab swings round as it raises the guard, rad/s. Slow enough that the turn READS
  // as a telegraph rather than a snap: at ~2.6 rad/s a half-turn takes about half a second, which
  // is the window a player has to notice and stop shooting.
  const CRAB_SQUARE_UP_RATE = 2.6
  const CRAB_OPEN = { openTh: 1.22, openR: 52, legK: 0.82, flat: 1 }
  const CRAB_GUARD = {
    arc: [[0.16, 0.72], [0.64, 0.60], [0.76, -0.22]],
    fw: [0.21, 0.19, 0.155, 0.09],
    notch: 1, chela: 0xd6431e, shade: 0.46, flat: 1, legK: 0.72, dome: 1, pale: 0.40, bare: 1,
    chelaK: 1.06, armX: 0.10, armY: 0.50,
  }
  function drawShorecrabPose(g, elite, white, guard, o = {}) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x4a1206)
    const shellC = f(0xb8341c)
    const chelaC = f(o.chela || 0xcb3d1c)
    const nailC = f(o.nail || 0xe58a5f)
    const litC = f(o.lit || 0xf79a63)
    const k = o.chelaK || 1                       // guard scale knob
    const legK = guard ? (o.legK || 0.60) : (o.legK || 0.78)
    groundShadow(r * 1.05, r * 0.85)

    // Eight walking legs. Guarded pulls them IN (a braced crab plants low and short); open fans
    // them wide, and they are what makes the open silhouette spiky rather than a disc.
    const legSets = [
      [[0.52, 0.18], [0.92, 0.62], [1.10, 0.98]],
      [[0.30, 0.20], [0.50, 0.78], [0.42, 1.14]],
      [[0.06, 0.20], [-0.22, 0.80], [-0.50, 1.12]],
      [[-0.20, 0.18], [-0.62, 0.70], [-0.94, 0.92]],
    ]
    const spread = guard ? 0.86 : 1.16            // how far the fan swings toward ±y
    for (const s of [-1, 1]) {
      for (const set of legSets) {
        const p = set.map(([lx, ly]) => [lx * r * legK, s * ly * r * legK * spread])
        taperStroke(g, [[p[0][0], p[0][1] * 0.5], ...p], r * 0.14, r * 0.035, line, 3)
      }
    }

    // --- OPEN: claws down and thrown out to the flanks, GAPING ---------------------------------
    // paintClaw is the right drawing here and the wrong one for the guard: a gape is exactly what
    // "you can hit me" wants, and the claw pointing outward off the shoulder is not covering
    // anything. Painted BEFORE the carapace so the shell laps over the wrists — that occlusion is
    // the plan view saying the claws are DOWN.
    if (!guard) {
      for (const s of [-1, 1]) {
        const R = o.openR || 48
        const th = s * (o.openTh || 1.02)         // out and a little forward, not along the facing
        const sx = r * 0.26, sy = s * r * 0.44
        paintClaw(g, R, true, {
          rot: th,
          ox: sx - Math.cos(th) * R * 0.46,       // back it off so the WRIST lands on the shoulder
          oy: sy - Math.sin(th) * R * 0.46,
          white, col: CRAB_CLAW_COL,
        })
      }
    }

    // --- the carapace: broad, flattened, WIDER across (±y) than long (±x) ----------------------
    // The flattening is the trait that separates this from every other rounded tank in the game,
    // and at 50px a 0.82:1.02 oval still reads as a circle — v13 pushes it to 0.74:1.08.
    const sx = o.flat ? 0.74 : 0.82
    const sy = o.flat ? 1.08 : 1.02
    g.poly(radialOutline((a) => r * (0.62 + 0.04 * Math.cos(a * 2)), 40, sx, sy))
      .fill(shellC).stroke({ width: Math.max(2.6, r * 0.12), color: line })
    if (!white) {
      // Open wears a brighter dorsal sheen than guarded does: the bare back catching the light IS
      // the vulnerable read, and under the claws that same back is in shade.
      g.ellipse(-r * 0.06, -r * 0.14, r * 0.42 * sx, r * 0.26)
        .fill({ color: 0xe0693a, alpha: guard ? 0.22 : 0.45 })
      g.beginPath() // the H-shaped cervical/branchiocardiac grooves a real crab shell carries
      g.moveTo(-r * 0.02, -r * 0.4).lineTo(-r * 0.02, r * 0.4)
      g.moveTo(-r * 0.02, 0).lineTo(r * 0.3, -r * 0.22)
      g.moveTo(-r * 0.02, 0).lineTo(r * 0.3, r * 0.22)
      g.stroke({ width: 1.3, color: 0x7a1e0c, alpha: 0.55 })
    }

    // --- OPEN: the face. Eyestalks up ON TOP of the shell, past its front rim ------------------
    // Guarded has no face at all — the claws are in front of it and a crab withdraws its stalks
    // behind them. Face vs no face is a second, independent read on the same pair of bakes.
    if (!guard) {
      for (const s of [-1, 1]) {
        taperStroke(g, [[r * 0.34, s * r * 0.16], [r * 0.60, s * r * 0.26]], Math.max(1.4, r * 0.055), 0.9, f(0x7a1e0c), 2)
        // drawn in BOTH passes at identical geometry — the white twin's bounds have to match the
        // normal one's or the baked anchor moves when a crab takes a hit
        darkEye(g, r * 0.62, s * r * 0.27, r * 0.085, r * 0.08, f(0x1c0a04), true)
      }
    }

    // --- GUARDED: the wall ---------------------------------------------------------------------
    if (guard && o.pcR) {
      if (!white && o.shade) {
        g.poly(radialOutline((a) => r * (0.62 + 0.04 * Math.cos(a * 2)), 40, sx, sy))
          .fill({ color: 0x3a0d03, alpha: o.shade * 0.5 })
      }
      // -1 is drawn LAST so its fingertip lands on its twin's palm rather than on the sand: an
      // exposed shut tip is the point that stopped every earlier cut reading as cover.
      for (const sd of [1, -1]) {
        const th = -sd * o.pcTh
        const wx = r * o.pcX, wy = sd * r * o.pcY
        paintClaw(g, o.pcR, false, {
          rot: th,
          ox: wx - Math.cos(th) * o.pcR * 0.46,   // back it off so the WRIST sits at (wx, wy)
          oy: wy - Math.sin(th) * o.pcR * 0.46,
          white, col: CRAB_CLAW_COL,
        })
      }
    } else if (guard) {
      const arc = o.arc || [[0.34, 0.62], [1.02, 0.50], [0.88, -0.26]]
      const spine = (s) => crabChelaSpine(r, s, arc)
      const dep = o.notch ? crabNotchDep(r, k, o.fw) : crabChelaDep(r, k, o.w)
      // 1. the whole back drops into shade under the raised claws, and the strip directly beneath
      //    them goes darker still. The camera looks straight down, so a raised thing shades what is
      //    under it — the offset is small and INWARD, never a cast shadow thrown to one side.
      if (!white && o.shade) {
        g.poly(radialOutline((a) => r * (0.62 + 0.04 * Math.cos(a * 2)), 40, sx, sy))
          .fill({ color: 0x3a0d03, alpha: o.shade * 0.5 })
        for (const s of [-1, 1]) {
          const sp = spine(s)
          g.poly(spineOutline((t) => { const [x, y] = sp(t); return [x - r * 0.13, y] }, (t) => dep(t) * 0.92, 22))
            .fill({ color: 0x3a0d03, alpha: o.shade })
        }
      }
      // 1b. the eyes, BEFORE the claws, so a slit guard leaves them peering out between the two
      //     and a merged one buries them — the same drawing, hidden or not by the pose itself.
      if (o.peek && !white) {
        for (const s of [-1, 1]) {
          taperStroke(g, [[r * 0.30, s * r * 0.10], [r * 0.62, s * r * 0.13]], Math.max(1.4, r * 0.055), 0.9, f(0x7a1e0c), 2)
          darkEye(g, r * 0.66, s * r * 0.14, r * 0.085, r * 0.08, 0x1c0a04, true)
        }
      }
      // 2. both arms, then both chelae — two passes so no arm lands on top of a claw. The arm is
      //    SHORT and its far end is under the chela: it exists to say the wall is carried, and a
      //    long one just crosses the sprite as a dark bar (v10 did exactly that).
      for (const s of [-1, 1]) {
        const [wx, wy] = spine(s)(0)
        const sh = [r * (o.armX || 0.06), s * r * (o.armY || 0.40)]
        taperStroke(g, [sh, [wx, wy]], r * 0.24, r * 0.19, line, 4)
        taperStroke(g, [sh, [wx, wy]], r * 0.15, r * 0.12, f(0xa32c12), 4)
      }
      for (const s of [-1, 1]) {
        const sp = spine(s)
        g.poly(spineOutline(sp, dep, o.notch ? 54 : 26)).fill(chelaC).stroke({ width: Math.max(2.6, r * 0.115), color: line })
        // The SHUT GAPE. Two fingers pressed together still leave a hairline you can see, and it
        // runs the full length of the finger section to a tiny dark wedge at the tip. This plus
        // the notch is the entire claw read at 50px; the granulation and the teeth are decoration.
        if (o.notch && !white) {
          const gape = []
          for (let i = 0; i <= 10; i++) {
            const t = CRAB_NOTCH_U + (1 - CRAB_NOTCH_U) * (i / 10)
            const [x, y] = sp(t)
            const [ax, ay] = sp(Math.max(0, t - 0.01))
            const [bx, by] = sp(Math.min(1, t + 0.01))
            const m = Math.hypot(bx - ax, by - ay) || 1
            gape.push(x + (-(by - ay) / m) * dep(t) * 0.16, y + ((bx - ax) / m) * dep(t) * 0.16)
          }
          g.poly(gape, false).stroke({ width: Math.max(1.5, r * 0.055), color: 0x4a1206, alpha: 0.9, cap: 'round' })
          const [tx0, ty0] = sp(0.995)
          g.circle(tx0, ty0, r * 0.045).fill({ color: 0x4a1206, alpha: 0.8 })
        }
        // The FINGERS: the inner third, paler, split by the shut seam. This two-tone is the whole
        // reason the wall reads as a pair of claws rather than a plank — but it must NOT be a
        // second outlined shape. v10 gave it its own dark stroke and the two mirrored pale ends
        // met at the centreline as a bright wedge with a black edge, which read as a HOLE in the
        // guard. Here it is an unstroked wash inset behind the chela's own outline.
        if (o.splitFingers) {
          g.poly(spineOutline(sp, (t) => dep(t) * 0.9, 14, 0.54, 1))
            .fill(nailC).stroke({ width: Math.max(1.8, r * 0.08), color: line })
        } else if (!white) {
          // The fingers are PALER than the palm, as a real chela's are — but as an unstroked wash
          // inset well inside the outline. v10 gave it its own dark stroke and the two mirrored
          // pale ends met at the centreline as a bright black-edged wedge, which read as a HOLE.
          const t0 = o.notch ? CRAB_NOTCH_U + 0.02 : (o.pale ? 0.60 : 0.50)
          g.poly(spineOutline(sp, (t) => dep(t) * (o.pale ? 0.62 : 0.80), 14, t0, 0.99))
            .fill({ color: nailC, alpha: o.pale || 0.55 })
        }
        if (!white) {
          if (!o.notch) {
            const seam = []
            for (let i = 0; i <= 8; i++) { const t = 0.48 + 0.51 * (i / 8); seam.push(...sp(t)) }
            g.poly(seam, false).stroke({ width: Math.max(1.4, r * 0.05), color: 0x4a1206, alpha: 0.85, cap: 'round' })
          }
          // the carpus joint: one crease across the fat end, the mark that says this is a limb
          // The decoration `bare` drops, and the reason it is a knob rather than a deletion: at 3x
          // zoom all three of these read as craftsmanship, and all three are why the guard kept
          // coming back as a CRACKED SHELL. The rim especially — a pale line laid just inside a
          // dark outline is exactly the broken lip of a shell.
          if (!o.bare) {
            const [jx, jy] = sp(0.14)          // the carpus crease across the fat end
            const [bx, by] = sp(0.20)
            const jm = Math.hypot(bx - jx, by - jy) || 1
            const jn = [-(by - jy) / jm, (bx - jx) / jm]
            g.beginPath()
              .moveTo(jx + jn[0] * dep(0.14) * 0.85, jy + jn[1] * dep(0.14) * 0.85)
              .lineTo(jx - jn[0] * dep(0.14) * 0.85, jy - jn[1] * dep(0.14) * 0.85)
              .stroke({ width: Math.max(1.2, r * 0.045), color: 0x7a1e0c, alpha: 0.6 })
            g.poly(crabChelaRim(sp, dep, 0.05, o.notch ? CRAB_NOTCH_U - 0.04 : 0.90, 14, 0.74), false)
              .stroke({ width: Math.max(2, r * 0.08), color: litC, alpha: 0.8, cap: 'round' })
            for (let i = 0; i < 3; i++) {      // tubercles on the palm
              const t = 0.24 + 0.13 * i
              const [x, y] = sp(t)
              g.circle(x, y, r * 0.032).fill({ color: 0x7a1e0c, alpha: 0.35 })
            }
          }
          // A lit dome on the palm — the same overhead-light cue every carapace in this file wears,
          // and the one that says the claw is a raised hard shell rather than a flat cut-out. It is
          // a soft blob with no edge of its own, so it survives the strip above.
          if (o.dome) {
            const [dx0, dy0] = sp(0.30)
            g.ellipse(dx0, dy0, dep(0.30) * 0.66, dep(0.30) * 0.50)
              .fill({ color: litC, alpha: o.bare ? 0.26 : 0.32 })
          }
        }
      }
    }
    if (elite) eliteCrown(-r * 1.1, r)
  }

  // THE SHORE CRAB, two poses. `pose` is the plain index ROSTER_LOOKS `poses: 2` hands the draw fn
  // (0 open, 1 guarded); syncEnemies picks it through poseOf off the sim's `guarding` field.
  function drawShorecrab(g, elite, white, pose) {
    return drawShorecrabPose(g, elite, white, pose === 1, pose === 1 ? CRAB_GUARD : CRAB_OPEN)
  }
  // SEA ROACH (Ligia) — The Surf's `fast` slot, taking over from the gull when that became a hazard.
  // The animal was chosen for its SILHOUETTE, because at ~40px on a phone, in a crowd, a creature is
  // an outline and a value and nothing else. The crab is a wide round disc; the hopper is a short
  // arched stub. This is built to be neither, out of four things and no interior detail:
  //   1. ONE LONG STREAK — 3.6:1 body, parallel-sided and flat, never an egg. Nothing else on this
  //      beach is longer than it is wide.
  //   2. A V AT EACH END — antennae thrown forward past the nose and biramous uropods thrown back
  //      past the telson, both nearly half the body long again. A shape that forks at BOTH ends
  //      cannot be read as a disc or as a stub even when it is twelve grey pixels.
  //   3. A LEG FRINGE THAT RAKES BACK — seven kneed pairs, the front ones reaching ahead and each
  //      one behind it swept further back. That rake is the whole "this thing is quick" read, and it
  //      is present in a still frame, which is where the player actually judges it.
  //   4. DARK COLD SLATE. The crab owns deep red-orange and the hopper owns a mid grey-brown one
  //      step under the sand; this goes three steps under and the other way round the wheel, so it
  //      is the only cold body on a warm floor. Ligia's own colour, as it happens.
  // Deliberately NOT here: mottling, banding, a lit dorsal ridge. Every one of those was what turned
  // the Shore Crab's guard into a cracked shell — detail above gameplay size is a lie.
  // The Sea Roach's palette. COLD SLATE against a warm beach: the Shore Crab owns deep red-orange
  // and the sand is pale warm ochre, so the one thing neither of them can be is grey-blue. Colour is
  // doing real work here because the silhouette alone (long, low, many-legged) has to survive at
  // ~40px next to a round crab.
  const ROACH_LOOK = { shell: 0x545c5e, line: 0x191f22, lit: 0x8b9793, eye: 0x0b0f11, wide: 1.00, ant: 1.00 }
  function drawSeaRoach(g, elite, white) {
    const r = 13
    const P = ROACH_LOOK
    const f = (c) => white ? 0xffffff : c
    const line = f(P.line)
    const shell = f(P.shell)
    const headX = r * 1.06
    const tailX = -r * 1.78
    const SEG = 7
    const segX = (i) => headX + (tailX - headX) * (i / SEG)
    // Half-width: blunt at the head, widest at the third tergite, tapering to the telson. The low
    // exponent keeps the middle nearly parallel-sided instead of bulging — an isopod is a plank.
    const wAt = (u) => r * 0.40 * P.wide * Math.pow(Math.max(0, Math.sin(Math.PI * (0.16 + 0.76 * u))), 0.40)
    groundShadow(r * 2.0, r * 0.7)

    // LEGS. Long, kneed, and raked progressively backward down the body.
    for (const sd of [-1, 1]) {
      for (let i = 0; i < SEG; i++) {
        const u = (i + 0.5) / SEG
        const bx = headX + (tailX - headX) * u
        const rake = -0.42 + i * 0.29
        taperStroke(g, [
          [bx, sd * wAt(u) * 0.8],
          [bx - rake * r * 0.26, sd * r * 0.76],
          [bx - rake * r * 0.50, sd * r * (1.00 + i * 0.035)],
        ], r * 0.115, r * 0.03, line, 3)
      }
    }
    // ANTENNAE — the front V, held splayed forward the way a running Ligia carries them. Thick at
    // the base so they are still two strokes and not two hairs once the sprite is 40px.
    for (const sd of [-1, 1]) {
      taperStroke(g, [
        [headX - r * 0.12, sd * r * 0.20],
        [headX + r * 0.60, sd * r * 0.50 * P.ant],
        [headX + r * 1.14 * P.ant, sd * r * 0.60 * P.ant],
        [headX + r * 1.44 * P.ant, sd * r * 0.38 * P.ant],
      ], r * 0.125, r * 0.022, line, 4)
    }
    // UROPODS — the back V, and BIRAMOUS: two rami a side, so the tail ends in four points. This is
    // the half of the shape the player sees most, because a `fast` enemy spends its life running at
    // you and this is what is pointing back down its own wake.
    for (const sd of [-1, 1]) {
      taperStroke(g, [[tailX + r * 0.16, sd * r * 0.16], [tailX - r * 0.44, sd * r * 0.46], [tailX - r * 0.90 * P.ant, sd * r * 0.64 * P.ant]],
        r * 0.10, r * 0.022, line, 4)
      taperStroke(g, [[tailX + r * 0.14, sd * r * 0.09], [tailX - r * 0.40, sd * r * 0.17], [tailX - r * 0.74 * P.ant, sd * r * 0.19]],
        r * 0.075, r * 0.02, line, 3)
    }

    // BODY. Traced tergite by tergite rather than swept as one smooth profile: each plate's lateral
    // edge flares out and back before the next one starts narrower, which leaves a row of shallow
    // notches down both flanks. That sawtooth is what separates this outline from the hopper's
    // continuous arch when both are grey — it survives as texture on the edge long after the
    // individual notches are sub-pixel.
    const FLARE = 1.14, TUCK = 0.90
    const pts = []
    for (let i = 0; i < SEG; i++) {
      pts.push(segX(i), -wAt(i / SEG) * TUCK)
      pts.push(segX(i + 1), -wAt((i + 1) / SEG) * FLARE)
    }
    pts.push(tailX - r * 0.30, -wAt(1) * 0.40)   // telson, a short rounded wedge
    pts.push(tailX - r * 0.44, 0)
    pts.push(tailX - r * 0.30, wAt(1) * 0.40)
    for (let i = SEG - 1; i >= 0; i--) {
      pts.push(segX(i + 1), wAt((i + 1) / SEG) * FLARE)
      pts.push(segX(i), wAt(i / SEG) * TUCK)
    }
    pts.push(headX + r * 0.22, wAt(0) * 0.58)    // head cap
    pts.push(headX + r * 0.32, 0)
    pts.push(headX + r * 0.22, -wAt(0) * 0.58)
    g.poly(pts).fill(shell).stroke({ width: Math.max(1.7, r * 0.12), color: line })

    if (!white) {
      for (let i = 1; i < SEG; i++) {                  // tergite creases
        const x = segX(i)
        const h = wAt(i / SEG) * 0.86
        g.beginPath().moveTo(x, -h).lineTo(x, h).stroke({ width: 1, color: P.line, alpha: 0.55 })
      }
      // ONE highlight: a soft dorsal sheen over the head and shoulders. No edge of its own, so it
      // cannot read as a crack the way an inset rim does.
      g.ellipse(headX - r * 0.42, 0, r * 0.44, wAt(0.12) * 0.52).fill({ color: P.lit, alpha: 0.20 })
      // Ligia's eyes are huge and sit on the head's outer corners, facing sideways.
      for (const sd of [-1, 1]) darkEye(g, headX - r * 0.02, sd * wAt(0) * 0.62, r * 0.10, r * 0.085, P.eye, sd > 0)
    }
    if (elite) eliteCrown(-r * 1.4, r)
  }

  function drawGull(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0xb7bbb2)
    groundShadow(r * 1.45, r * 0.5)
    // ONE wing, mirrored ±y: root at the shoulder, a leading edge swept back through the wrist to
    // the tip, then a trailing edge pulled IN at the notch before closing back to the root
    const wing = (s) => {
      const root = [r * 0.5, s * r * 0.2]
      const wrist = [-r * 0.3, s * r * 1.3]
      const tip = [-r * 1.7, s * r * 2.5]
      const notch = [-r * 1.0, s * r * 1.65] // pulled inward — the bite in the trailing edge
      g.poly([...root, ...wrist, ...tip, ...notch]).fill(f(0xf2f0e8)).stroke({ width: Math.max(1.3, r * 0.09), color: line })
      if (!white) {
        // dark wingtip: the outer portion, over-painted so the wing base stays pale
        const mid = [wrist[0] + (tip[0] - wrist[0]) * 0.55, wrist[1] + (tip[1] - wrist[1]) * 0.55]
        g.poly([...mid, ...tip, ...notch]).fill({ color: 0x2c2e30, alpha: 0.92 })
      }
    }
    wing(-1)
    wing(1)
    // body: a small torpedo, nose right
    const spine = (t) => [r * 0.85 - t * r * 1.75, 0]
    const bodyW = (t) => r * 0.26 * bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.4 ? 0.4 : 0.7)
    g.poly(spineOutline(spine, bodyW, 24)).fill(f(0xf7f6f1)).stroke({ width: Math.max(1.4, r * 0.1), color: line })
    for (const s of [-1, 1]) { // shallow forked tail
      taperStroke(g, [[-r * 0.9, 0], [-r * 1.3, s * r * 0.32]], r * 0.1, 0.5, f(0xe8e6de), 3)
    }
    if (!white) {
      g.ellipse(r * 0.2, -r * 0.06, r * 0.3, r * 0.12).fill({ color: 0xffffff, alpha: 0.4 }) // dorsal sheen
      darkEye(g, r * 0.62, 0, r * 0.06, r * 0.06, 0x1a1a1a, true)
    }
    taperStroke(g, [[r * 0.82, 0], [r * 1.1, 0]], r * 0.07, 0.5, f(0xd8a23a)) // beak, the one warm mark
    if (elite) eliteCrown(-r * 2.1, r)
  }

  // BOOK 2'S PLAYER: a small fish (CHAPTERS[].render.form === 'fish', see playerForm in
  // syncPlayer) — not part of run.roster, this beach's three creatures are the trio above.
  //
  // ONE BODY FOR THE WHOLE BOOK, deliberately. The arc is "you grow in each chapter", which is a
  // SIZE and tint step per chapter (render.formScale), not five separate animals — five bakes would
  // be five chances for the player to stop recognising themselves between chapters, which is the
  // one sprite in the game that must never happen to.
  //
  // THREE THINGS MAKE IT READ AS A SWIMMER rather than a crawler, and they are the whole drawing:
  // the undulation RAMPS toward the tail instead of running uniformly (see spine below), the body is
  // fusiform with a narrow peduncle instead of near-constant width, and the propulsion is one hinged
  // forked caudal fin rather than a row of legs.
  //
  // ANIMATED like the centipede: the `phase` arg shifts spine(t)'s sine, and buildTextures bakes
  // FISH_PHASES frames from it. The player rig has no `.frames`/`_animFrame` object the way
  // syncEnemies' ROSTER_LOOKS path does (that machinery exists per-enemy-sprite, and there is only
  // ever one player) — syncPlayer instead indexes T.fishBody/T.fishFlash directly off animT, the
  // same "pick a rung by hand" idiom the STILLNESS morph ladder (T.playerStill) already uses. This
  // still sits under the hop/breathe squash-stretch every other player form gets — the phase flip
  // and the squash-stretch are two independent transforms, not one replacing the other.
  const FISH_R = 26
  const FISH_PHASES = 6
  function drawFish(g, white, phase = 0) {
    const r = FISH_R
    const f = (c) => white ? 0xffffff : c
    const bodyLit = f(0xf2a184), bodyMid = f(0xd97a5c), bodyShade = f(0x8a3a2c)
    const line = f(0x5c2418), finFill = f(0xe0906c), finEdge = f(0x7a3122)
    const lw = Math.max(2.2, r * 0.11)
    const noseX = r * 1.5
    const len = r * 2.55
    // The undulation, and the reason it is not a plain sine: a swimming fish holds its head almost
    // still and throws its tail, so the amplitude RAMPS with t^1.9 instead of running at one
    // amplitude down the whole body. A uniform sine is what makes a fish read as an eel.
    const spine = (t) => [noseX - t * len, Math.sin(t * Math.PI * 1.35 - phase) * r * 0.4 * Math.pow(t, 1.9)]
    // The width profile IS the silhouette, and it is the difference between a fish and a tadpole:
    // a short rounded snout rising to the widest point a third back, then a LONG taper to a peduncle
    // thin enough that the caudal fin reads as a separate blade rather than as the end of the body.
    // The two halves meet at t = 0.30 with both terms equal to 1, so the outline is continuous.
    // Two numbers do all the work here. The 0.4 is WHERE the fish is widest, and pulling it back
    // from a third to two fifths is what gives the head length — at 0.32 the head was wider than it
    // was long, which reads as a frog. The 0.62 exponent rounds the snout: a linear rise gives a
    // wedge, a high exponent gives a spike, and spineOutline closes whatever width is left at t=0
    // with a straight segment, so any width at the tip reads as a chopped hexagon rather than a nose.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.4), 0.62)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.4) / 0.64), 1.15)
      return r * 0.58 * Math.max(0.09, t < 0.4 ? rise : fall)
    }

    // Tail: hinged just SHORT of the peduncle tip (0.96, so fin and body overlap and no seam opens
    // between them) and swung by the spine's own local angle, so the fin follows the body instead of
    // being a shape stuck on the back. Deeply forked — the fork is most of what says "fish" at the
    // 26px this is actually drawn at.
    const [tx, ty] = spine(0.96)
    const [ax, ay] = spine(0.84)
    const ta = Math.atan2(ty - ay, tx - ax)
    const lobe = r * 1.18
    const tip = (da, k) => [tx + Math.cos(ta + da) * lobe * k, ty + Math.sin(ta + da) * lobe * k]
    g.poly([tx, ty, ...tip(0.46, 1), ...tip(0, 0.36), ...tip(-0.46, 1)])
      .fill({ color: finFill, alpha: 0.95 }).stroke({ width: lw * 0.8, color: finEdge })

    // Pectorals: one pair, set behind the widest point and swept back along the body rather than
    // out from it — a fin held out square reads as a wing. They scull against the tail beat
    // (opposite sign of the same phase) so the whole animal moves as one thing.
    const pt = 0.42
    const [ptx, pty] = spine(pt)
    const pw = body(pt)
    for (const s of [-1, 1]) {
      const beat = Math.sin(-phase) * 0.12 * s
      const bx = ptx, by = pty + s * pw * 0.66
      g.poly([
        bx + r * 0.2, by,
        bx - r * 0.34, by + s * (r * 0.44 + beat * r),
        bx - r * 0.46, by + s * r * 0.08,
      ]).fill({ color: finFill, alpha: 0.9 }).stroke({ width: lw * 0.55, color: finEdge })
    }

    g.poly(spineOutline(spine, body, 44)).fill(bodyMid).stroke({ width: lw, color: line })

    if (!white) {
      // Countershading read from above: the dorsal ridge is the darkest line on the animal and it
      // runs the midline, which is the single cue that says "seen from the top" rather than "seen
      // from the side" — the projection question the tornado failed.
      g.poly(spineOutline(spine, (t) => body(t) * 0.22, 30, 0.1, 0.9))
        .fill({ color: bodyShade, alpha: 0.6 })
      // ONE pale gill stroke and nothing else. An earlier cut carried three lateral bars and a
      // shoulder highlight on top of the ridge; at the 26px this is drawn at they stopped being
      // pattern and became mud, which is the usual fate of interior detail on a small sprite.
      const [gx, gy] = spine(0.26)
      g.ellipse(gx, gy, r * 0.05, body(0.26) * 0.6).fill({ color: bodyLit, alpha: 0.45 })
      // Both eyes are visible from overhead — that is the plan view stating itself. On the snout,
      // where a fish's are, not back on the shoulders where they read as a frog's.
      const [ex, ey] = spine(0.16)
      for (const s of [-1, 1]) darkEye(g, ex, ey + s * body(0.16) * 0.58, r * 0.085, r * 0.085, 0x1a0d05, true)
    }
  }

  // --- Reef chapter (Book 2 ch 3, deep water over warm coral) ---
  // The hardest palette problem in the book, and worth stating before the drawings. This chapter's
  // WORLD is warm — dark coral reds, magentas and violets (BIOME_REEF) — and so is the PLAYER: Book
  // 2's fish is a saturated rust-coral body (drawFish, and 1.3x bigger here than on the beach). A
  // roster that reached for the reef's own colours would be competing with both at once.
  // So the separation is by SIDE OF THE FLOOR and by SILHOUETTE, not by hue. Every coral is DARKER
  // than the water (1.8x-2.5x); all three of these are LIGHTER than it (2.7x-4.9x), and none is
  // saturated. The reef is dark and hot; the animals in it are pale.
  //   moray      = PALE OCHRE, dark reticulation    (the only NET pattern in the game)
  //   damselfish = WHITE with three hard BLACK BARS (the only achromatic body in the chapter)
  //   lionfish   = CREAM with MAROON bands          (the one that does share the reef's hue, and
  //                separates on shape alone — see its own note)
  // BACKUP READ — what is left once colour has gone at range, and the reason no two of these read
  // as each other or as the player's compact rust fusiform: the moray is a RIBBON three times its
  // own width long, the damselfish a short barred SPINDLE with fanned pectorals, and the lionfish a
  // spiky STARBURST wider than it is long.
  // All three are PLAN VIEW. The moon jelly is the one side-elevation body in this game and it
  // earns that by hanging in a water column with no floor under it (see drawJelly); these three are
  // all over the reef floor, so the overhead camera is the honest one — and lean 90 on each is the
  // geometry falling out of that, not a habit: every one is bilaterally symmetric about its own +x
  // nose, with paired eyes and paired appendages in +-y and nothing that could be called UP.

  // moray: a big eel seen from above, which is a RIBBON — no waist, no peduncle, a long slow taper
  // to a point, and three times longer than the two fish beside it. THE GAPE IS THE `latch` FLAG
  // DRAWN: latch is the enemy that takes hold of you, slows you and dies doing it, and the one thing
  // you see of a moray from directly overhead is an open mouth arriving.
  //
  // THE HEAD IS ONE POLYGON WITH A V BITTEN OUT OF ITS FRONT, and that shape is the whole reason it
  // works. The first cut bolted two thin jaw slivers onto the body's flat front cap and painted a
  // dark wedge behind them: on screen that was a rectangular block with a saw in it, because
  // spineOutline closes whatever width is left at t=0 with a STRAIGHT SEGMENT and the jaws were too
  // slight to break that line. Cutting the notch out of the skull's own outline instead makes the
  // SILHOUETTE fork — the gape survives at any size and in the white hit-flash twin, where interior
  // detail does not exist at all.
  // Animated like the centipede (`phases: 6`): the phase arg shifts spine(t)'s sine.
  function drawMoray(g, elite, white, phase = 0) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x3a2c14)
    const skin = f(0xe3d5a4)
    const lw = Math.max(2.4, r * 0.1)
    const headX = r * 0.8           // where the skull meets the body; the jaws run forward of this
    const len = r * 3.15
    const H = r * 0.4
    // THE UNDULATION, and why it is not drawFish's. A fish holds its head still and throws its tail,
    // so that amplitude ramps as t^1.9; an eel throws its WHOLE body, so this one is near uniform
    // and only eases off over the skull. Two full waves down the length is what reads as swimming
    // rather than as a bent stick — and it is the same difference the fish's own comment warns about
    // in the other direction ("a uniform sine is what makes a fish read as an eel").
    const spine = (t) => [headX - t * len, Math.sin(t * Math.PI * 2.2 - phase) * r * 0.3 * Math.min(1, t * 3.4)]
    // Thickest at the shoulders and then a very long taper: no waist anywhere, which is exactly what
    // separates this outline from the two fish.
    const body = (t) => H * Math.max(0.04,
      Math.pow(Math.max(0, 1 - t), 0.5) * (0.86 + 0.18 * Math.exp(-Math.pow((t - 0.08) / 0.13, 2))))
    groundShadow(r * 1.5, H + r * 0.34)

    g.poly(spineOutline(spine, body, 40)).fill(skin).stroke({ width: lw, color: line })

    // The skull, drawn OVER the body's flat cap so the cap never shows. Back corners sit inside the
    // body; the widest point is just ahead of it; the two jaw tips fork forward with the gape's apex
    // between them.
    const hb = headX - r * 0.45, hs = headX - r * 0.05, ht = headX + r * 0.85
    const apex = headX + r * 0.3
    const hw = r * 0.44, tipY = r * 0.22
    // The throat overshoots the tips a little so a band of dark shows INSIDE the notch rather than
    // the water — the difference between an open mouth and a forked stick.
    if (!white) g.poly([apex - r * 0.05, 0, ht + r * 0.05, -tipY - r * 0.06, ht + r * 0.05, tipY + r * 0.06]).fill(0x2a1408)
    // The BACK of the skull is a chevron, not a straight edge. A straight one is drawn inside the
    // body, so its stroke lands on the pale flank as a hard vertical bar — a collar across the neck,
    // clearly visible in the probe frame. Two lines converging back to a point on the spine instead
    // read as the head plates a real eel has, which is what that stroke should have been saying.
    const [bkx, bky] = spine(0.2)
    g.poly([bkx, bky, hb, -r * 0.3, hs, -hw, ht, -tipY, apex, 0, ht, tipY, hs, hw, hb, r * 0.3])
      .fill(skin).stroke({ width: lw * 0.95, color: line })
    if (!white) {
      // The dorsal crest runs the whole midline — a moray's dorsal fin starts behind the head and
      // never stops. On the midline it is also the cue that says "seen from the top", the same job
      // drawFish's dark ridge does.
      g.poly(spineOutline(spine, (t) => body(t) * 0.32, 34, 0.16, 0.99))
        .fill({ color: 0xc6b177, alpha: 0.6 })
      for (const s of [-1, 1]) { // teeth along the gape, pointing back into the throat
        for (const u of [0.22, 0.46, 0.7]) {
          const bx = ht + (apex - ht) * u
          const by = s * tipY * (1 - u)
          g.poly([bx, by, bx + r * 0.09, by - s * r * 0.08, bx - r * 0.06, by - s * r * 0.015]).fill(0xfaf1d6)
        }
      }
      // RETICULATION: staggered rows of small dark blotches down the flanks. A net rather than
      // stripes or spots, because a net is the one pattern nothing else in this bestiary wears — and
      // SMALL, because the first cut's 0.115r ellipses merged into giraffe patches at drawn size.
      for (let i = 0; i < 17; i++) {
        const t = 0.06 + i * 0.055
        const [x, y] = spine(t)
        const w = body(t)
        for (const s of [-1, 1]) {
          g.ellipse(x, y + s * w * (i % 2 ? 0.58 : 0.24), r * 0.075, w * 0.24)
            .fill({ color: 0x4a3a1e, alpha: 0.72 })
        }
      }
      for (const s of [-1, 1]) { // gill pore, one either side of the neck
        const [gx, gy] = spine(0.14)
        g.ellipse(gx, gy + s * body(0.14) * 0.62, r * 0.05, body(0.14) * 0.26).fill({ color: 0x5f4a1e, alpha: 0.8 })
        // eyes: high on the skull, well forward, in the ±y pair that makes this a plan view
        darkEye(g, hs + r * 0.08, s * r * 0.26, r * 0.075, r * 0.07, 0x140d05, s > 0)
      }
      // A pale ridge along each jaw, the lip line — it separates the two forks from each other and
      // from the throat when the whole head is a single flat colour at distance.
      for (const s of [-1, 1]) {
        taperStroke(g, [[hs + r * 0.1, s * r * 0.3], [ht - r * 0.06, s * (tipY - r * 0.02)]],
          Math.max(1.1, r * 0.05), 0.8, 0xfaf1d6, 3)
      }
    }
    if (elite) eliteCrown(-r * 0.82, r)
  }

  // damselfish: the roster's flagless baseline, and drawn as the plainest thing on the reef — a
  // humbug damsel, brilliant white with three hard black bars. Achromatic on purpose: it is the one
  // body here that shares no hue with the coral, the water or the player, so it needs no pattern
  // trick to be found in a crowd.
  // NARROW ON PURPOSE, and that is the projection rather than a style choice: a damselfish is
  // laterally compressed — deep top-to-bottom, thin side-to-side — so from DIRECTLY ABOVE it is a
  // slim spindle where the player's rounder body (drawFish, half-width 0.58r against this one's
  // 0.34r) is a broad one. Drawing it deep-bodied would be a side elevation wearing a plan view's
  // clothes, which is the mistake CLAUDE.md lost a whole version to.
  function drawDamselfish(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x252c36)
    const pale = f(0xf4f7f8)
    const fin = f(0xdde6ec)
    const lw = Math.max(2, r * 0.11)
    const noseX = r * 1.0
    const len = r * 1.95
    const spine = (t) => [noseX - t * len, 0]
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.34), 0.6)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.34) / 0.72), 1.2)
      return r * 0.4 * Math.max(0.1, t < 0.34 ? rise : fall)
    }
    groundShadow(r * 0.95, r * 0.4)
    // Pectorals: rounded PADDLES swept a little back, not pointed vanes held forward. A damselfish
    // hovers on them, and on a body this narrow they are most of what gives the silhouette any width
    // at all — but the first cut's forward-pointing tips read as swept wings and turned the whole
    // animal into a small aircraft.
    const pt = 0.38
    const [ptx] = spine(pt)
    const pw = body(pt)
    for (const s of [-1, 1]) {
      g.poly([
        ptx + r * 0.1, s * pw * 0.75,
        ptx - r * 0.06, s * (pw + r * 0.5),
        ptx - r * 0.28, s * (pw + r * 0.5),
        ptx - r * 0.44, s * (pw + r * 0.18),
        ptx - r * 0.3, s * pw * 0.85,
      ]).fill({ color: fin, alpha: 0.92 }).stroke({ width: lw * 0.5, color: line })
    }
    // Caudal: forked, hinged just short of the tail tip so no seam opens between fin and body.
    const [tx] = spine(0.96)
    for (const s of [-1, 1]) {
      g.poly([tx, 0, tx - r * 0.55, s * r * 0.38, tx - r * 0.44, s * r * 0.05])
        .fill({ color: fin, alpha: 0.9 }).stroke({ width: lw * 0.5, color: line })
    }
    g.poly(spineOutline(spine, body, 34)).fill(pale).stroke({ width: lw, color: line })
    if (!white) {
      // THE THREE BARS, cut from the body's own outline over a t-range rather than laid on as
      // rectangles — spineOutline(t0, t1) returns exactly the strip of silhouette between them, so a
      // bar can never overhang the fish it belongs to.
      for (const [t0, t1] of [[0.16, 0.3], [0.46, 0.6], [0.74, 0.88]]) {
        g.poly(spineOutline(spine, body, 8, t0, t1)).fill({ color: 0x1d2430, alpha: 0.95 })
      }
      g.poly(spineOutline(spine, (t) => body(t) * 0.2, 24, 0.08, 0.94))
        .fill({ color: 0x8f9aa4, alpha: 0.35 })   // dorsal ridge: the plan view stating itself
      // Both eyes visible from overhead, set just ahead of the first bar — a real humbug's runs
      // straight THROUGH the eye, which on a 32px sprite simply deletes it.
      const [ex] = spine(0.11)
      for (const s of [-1, 1]) darkEye(g, ex, s * body(0.11) * 0.62, r * 0.085, r * 0.08, 0x11161d, true)
    }
    if (elite) eliteCrown(-r * 0.95, r)
  }

  // ---- The Trawl (Book 2 chapter 4) — open water ------------------------------------------------
  // The floor here is the darkest, coldest one in the book so far (bgColor 0x05203f under floorTint
  // 0x93b6cc), and there is no decor competing for attention the way the reef's coral does. So this
  // roster's separation problem is the OPPOSITE of the reef's: not "how do three warm bodies avoid a
  // warm floor" but "how do three pelagic fish, which in life are all silver, avoid being the same
  // fish three times". They separate on SILHOUETTE and on tail, which is also how you tell them apart
  // in the water:
  //   mackerel — a plain spindle with a small forked tail and a barred back. The baseline.
  //   tuna     — thicker through the shoulder, tapering to a hard narrow wrist and a CRESCENT tail,
  //              with long sickle pectorals swept back. The outline says "this one is fast" before
  //              any colour does, which matters because dashBurst gives no telegraph of its own.
  //   sea lion — NOT A FISH, and that is the whole design of the tank slot. Broad fore-flippers
  //              thrown out to the sides, a blunt round whiskered head, hind flippers trailing. The
  //              one body in the chapter that breaks the fish outline, and it is also the one that
  //              is warm — a brown animal is a hue this water cannot reach, the same trick the Surf's
  //              shore crab plays on pale sand.
  // All three PLAN VIEW: they swim over open water with a definite nose, and unlike the moon jelly
  // (the game's one deliberate side elevation) each is bilaterally symmetric about that nose with
  // paired eyes and paired fins in ±y and nothing that could be called UP. See CLAUDE.md.

  // mackerel: the flagless baseline, drawn as the plainest fish in the game. Steel-blue back with the
  // wavy black bars a real mackerel wears, silver flanks. The bars run ACROSS the body rather than
  // along it, which from directly above is the pattern's actual orientation — a fish's bars are on
  // its back, and its back is what an overhead camera sees.
  function drawMackerel(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x1b2733)
    const back = f(0x4d7f9e)
    const flank = f(0xc8dae6)
    const fin = f(0x9fbccd)
    const lw = Math.max(2, r * 0.1)
    const noseX = r * 1.05
    const len = r * 2.15
    const spine = (t) => [noseX - t * len, 0]
    // A mackerel is a slim fusiform: widest just past a third, tapering to a thin wrist before the
    // tail. `pow` on the fall keeps that wrist genuinely narrow instead of a lazy cone.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.32), 0.55)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.32) / 0.62), 1.5)
      return r * 0.34 * Math.max(0.08, t < 0.32 ? rise : fall)
    }
    groundShadow(r * 0.9, r * 0.35)
    // Pectorals: short and low, swept back. A mackerel does not hover, so these are small.
    const pt = 0.34
    const [ptx] = spine(pt)
    const pw = body(pt)
    for (const s of [-1, 1]) {
      g.poly([ptx, s * pw * 0.8, ptx - r * 0.34, s * (pw + r * 0.34), ptx - r * 0.4, s * (pw + r * 0.1)])
        .fill({ color: fin, alpha: 0.9 }).stroke({ width: lw * 0.45, color: line })
    }
    // Caudal: forked, and hinged just short of the tip so no seam opens between fin and body.
    const [tx] = spine(0.95)
    g.poly([tx + r * 0.06, 0, tx - r * 0.62, r * 0.46, tx - r * 0.4, 0, tx - r * 0.62, -r * 0.46])
      .fill({ color: fin, alpha: 0.92 }).stroke({ width: lw * 0.45, color: line })
    g.poly(spineOutline(spine, body, 34)).fill(flank).stroke({ width: lw, color: line })
    if (!white) {
      // The back, cut from the body's own outline so it can never overhang the fish — the damselfish's
      // bar trick, used here for the dorsal half instead of for stripes.
      g.poly(spineOutline(spine, (t) => body(t) * 0.55, 28, 0.04, 0.93)).fill({ color: back, alpha: 0.95 })
      // The bars: short strokes across the back, thinning toward the tail as a real one's do.
      for (let i = 0; i < 6; i++) {
        const t = 0.14 + i * 0.12
        const [bx] = spine(t)
        const w = body(t) * 0.5
        g.moveTo(bx, -w).quadraticCurveTo(bx - r * 0.09, 0, bx, w)
          .stroke({ width: lw * 0.72, color: f(0x14202b), alpha: 0.85 })
      }
      const [ex] = spine(0.1)
      for (const s of [-1, 1]) darkEye(g, ex, s * body(0.1) * 0.66, r * 0.085, r * 0.08, 0x0d151d, true)
    }
    if (elite) eliteCrown(-r * 0.9, r)
  }

  // tuna: the fast slot, and the read is entirely in the outline. Deep through the shoulder, a hard
  // narrow wrist, and a CRESCENT (lunate) caudal — the shape only the ocean's fastest fish have, and
  // the one thing on screen that is unambiguously not the mackerel it is swimming beside.
  function drawTuna(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x18242f)
    const back = f(0x2f5f86)
    const flank = f(0xdbe8f0)
    const fin = f(0xf2c94c)   // the yellow finlets a real tuna carries — the one warm accent
    const lw = Math.max(2, r * 0.1)
    const noseX = r * 1.05
    const len = r * 2.1
    const spine = (t) => [noseX - t * len, 0]
    // Fuller than the mackerel through 0.2-0.45 and pinched harder after it: same length, different
    // distribution of it, which is what "built for speed" looks like from above.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.3), 0.42)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.3) / 0.6), 1.9)
      return r * 0.46 * Math.max(0.07, t < 0.3 ? rise : fall)
    }
    groundShadow(r * 1.0, r * 0.4)
    // Sickle pectorals: long, thin and swept hard back, reaching most of the way to the wrist.
    const pt = 0.32
    const [ptx] = spine(pt)
    const pw = body(pt)
    // Laid ALONG the body, not held out from it. The first cut put these at 0.62r of clearance in
    // the bright flank colour with a hard outline, and they read as two white blades crossing the
    // fish — a tuna folds its pectorals into grooves at speed, so the honest drawing is a narrow
    // sliver close to the flank. No outline, and it inherits the flank colour, so it reads as part
    // of the same animal rather than as something attached to it.
    for (const s of [-1, 1]) {
      g.poly([
        ptx + r * 0.04, s * pw * 0.85,
        ptx - r * 0.72, s * (pw + r * 0.3),
        ptx - r * 0.9, s * (pw + r * 0.2),
        ptx - r * 0.34, s * pw * 0.92,
      ]).fill({ color: flank, alpha: 0.7 })
    }
    // THE CRESCENT. Two swept lobes meeting at a narrow centre, concave on the trailing edge — that
    // concavity is the whole difference between this and the mackerel's fork, so it is drawn with a
    // quadratic rather than a straight line back to the wrist.
    const [tx] = spine(0.94)
    for (const s of [-1, 1]) {
      g.moveTo(tx, 0)
        .quadraticCurveTo(tx - r * 0.14, s * r * 0.34, tx - r * 0.54, s * r * 0.7)
        .quadraticCurveTo(tx - r * 0.3, s * r * 0.26, tx - r * 0.16, 0)
        .fill({ color: back, alpha: 0.9 }).stroke({ width: lw * 0.4, color: line })
    }
    g.poly(spineOutline(spine, body, 34)).fill(flank).stroke({ width: lw, color: line })
    if (!white) {
      g.poly(spineOutline(spine, (t) => body(t) * 0.6, 28, 0.03, 0.92)).fill({ color: back, alpha: 0.95 })
      // Finlets: the little yellow flags between the second dorsal and the tail, in ±y pairs. TINY —
      // the first cut stood them off the body by 0.16r and they read as a row of spikes, which turned
      // the whole animal into something mechanical. At 0.07r they are a serrated yellow edge, which
      // is what they look like on a real fish and is still the second thing (after the crescent) that
      // names it a tuna.
      for (let i = 0; i < 4; i++) {
        const t = 0.62 + i * 0.075
        const [fx] = spine(t)
        const w = body(t)
        for (const s of [-1, 1]) {
          g.poly([fx, s * w, fx - r * 0.07, s * (w + r * 0.07), fx - r * 0.13, s * w])
            .fill({ color: fin, alpha: 0.85 })
        }
      }
      const [ex] = spine(0.1)
      for (const s of [-1, 1]) darkEye(g, ex, s * body(0.1) * 0.6, r * 0.1, r * 0.095, 0x0b1219, true)
    }
    if (elite) eliteCrown(-r * 1.0, r)
  }

  // sea lion: the tank, and the one body in this chapter that is not a fish. Everything about the
  // drawing is chosen so that a glance separates it from the two fish beside it — a blunt ROUND head
  // instead of a point, fore-flippers thrown WIDE to both sides instead of tucked back, and a warm
  // brown coat where everything else here is silver over cold blue.
  function drawSeaLion(g, elite, white) {
    const r = 20
    const f = (c) => white ? 0xffffff : c
    const line = f(0x2a1d12)
    const coat = f(0x8a5c33)
    const belly = f(0xb98a5c)
    const lw = Math.max(2, r * 0.1)
    const noseX = r * 0.95
    const len = r * 2.0
    const spine = (t) => [noseX - t * len, 0]
    // Blunt at the nose and full through the chest — a pinniped tapers toward the TAIL, which is the
    // reverse of both fish here and is most of why the silhouette reads as a mammal.
    // FULL THROUGH THE CHEST. 0.52r, not the 0.42 this started at: the flippers below reach well
    // outside the outline, and on a narrow body they become the whole animal — the first probe frame
    // read as a cross with a head on it because the body they hang off was three times thinner than
    // they were long. A pinniped is a barrel, and the barrel has to win.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.16), 0.35)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.28) / 0.86), 1.15)
      return r * 0.52 * Math.max(0.16, t < 0.28 ? rise : fall)
    }
    groundShadow(r * 1.05, r * 0.42)
    // Fore-flippers: broad at the shoulder, raked backward, TAPERING TO A NEAR-POINT. All three of
    // those are load-bearing and only the first two survived the first cut — its "tip" was two points
    // 0.37r apart, i.e. a bar with a bevel, and a bar on a body is a plank at any tint. Width at the
    // tip is now 0.19r against 0.42r at the root, and the reach is cut from pw + 0.95r to pw + 0.6r
    // so the animal is a body with flippers rather than flippers with a body.
    const pt = 0.34
    const [ptx] = spine(pt)
    const pw = body(pt)
    for (const s of [-1, 1]) {
      g.poly([
        ptx + r * 0.18, s * pw * 0.7,
        ptx - r * 0.42, s * (pw + r * 0.55),
        ptx - r * 0.6, s * (pw + r * 0.6),
        ptx - r * 0.34, s * (pw + r * 0.18),
        ptx - r * 0.16, s * pw * 0.85,
      ]).fill({ color: coat, alpha: 0.95 }).stroke({ width: lw * 0.5, color: line })
    }
    // Hind flippers: trailing, held together and splayed at the tips — same taper rule as above, and
    // deliberately smaller than the fore pair so the silhouette has a front and a back.
    const [hx] = spine(0.97)
    for (const s of [-1, 1]) {
      g.poly([hx + r * 0.08, s * r * 0.05, hx - r * 0.3, s * r * 0.3, hx - r * 0.4, s * r * 0.1, hx - r * 0.08, s * r * 0.02])
        .fill({ color: coat, alpha: 0.92 }).stroke({ width: lw * 0.45, color: line })
    }
    g.poly(spineOutline(spine, body, 32)).fill(coat).stroke({ width: lw, color: line })
    if (!white) {
      g.poly(spineOutline(spine, (t) => body(t) * 0.5, 24, 0.2, 0.9)).fill({ color: belly, alpha: 0.5 })
      // The head: a separate rounded mass at the nose, so the outline has a NECK. Two fish have no
      // neck and cannot get one, so this is the cheapest single cue that this is another kind of animal.
      const [hdx] = spine(0.07)
      g.circle(hdx, 0, r * 0.4).fill({ color: coat, alpha: 1 }).stroke({ width: lw * 0.8, color: line })
      g.circle(hdx + r * 0.3, 0, r * 0.12).fill({ color: f(0x241810) })   // muzzle
      // Whiskers, in ±y pairs, the one detail that survives at sprite size as "this has a face".
      for (const s of [-1, 1]) {
        for (let i = 0; i < 3; i++) {
          const a = s * (0.28 + i * 0.3)
          g.moveTo(hdx + r * 0.3, s * r * 0.06)
            .lineTo(hdx + r * 0.3 + Math.cos(a) * r * 0.5, s * r * 0.06 + Math.sin(a) * r * 0.42)
            .stroke({ width: Math.max(0.8, r * 0.035), color: f(0xe8d5bd), alpha: 0.75 })
        }
      }
      for (const s of [-1, 1]) darkEye(g, hdx + r * 0.06, s * r * 0.2, r * 0.09, r * 0.085, 0x120b06, true)
    }
    if (elite) eliteCrown(-r * 1.5, r)
  }

  // ---- The Deep (Book 2 chapter 5) ------------------------------------------------------------
  // Four bodies for the darkest floor in the game, and the whole set is built on ONE constraint:
  // down here a body is not read by its colour, because there is barely any light on it. Every one
  // of these separates on OUTLINE and on the placement of its few bright marks — a lure, a row of
  // photophores, a mouth — which is also what deep-sea animals actually do to each other.
  //
  // All four are PLAN VIEW and lean 90, the ordinary case: each is bilaterally symmetric about its
  // own +x nose with paired eyes, and none of them has an UP. (The Shelf's moon jelly is the one
  // side-on body in the game and it is deliberate — see CLAUDE.md. Nothing here is that case.)
  //
  // ⚠ THE ANGLERFISH'S MOUTH IS NOT BAKED HERE. Its gape changes per fish per frame, and a bake is
  // a texture made once at boot, so the opening mouth is drawn as a per-frame overlay from the
  // published `gape` field (drawDeepTells). What is baked is the body, the teeth and the dark
  // socket the gape opens over — the parts that never move.

  // anglerfish: the chapter. Round, heavy, front-loaded, with a lure held out ahead on a stalk and a
  // mouth that is most of the head. The ESCA is the only genuinely bright thing in the chapter and
  // it is the thing the player navigates by, so it is drawn as a hot core inside a soft halo rather
  // than as a flat dot.
  function drawAnglerfish(g, elite, white) {
    const r = 17
    const f = (c) => white ? 0xffffff : c
    const line = f(0x0a1016)
    // ⚠ DARK, BUT NOT A VOID. A real deep-sea anglerfish is very nearly black, and the first cut
    // painted it that way (0x2b2230 on a 0x03101d floor): the body disappeared entirely and the
    // animal read as a floating dark pennant with a spike. The design intent survives — you
    // navigate this chapter by the LURE, not by the fish — but the body still has to be findable
    // once you are on top of it, or the thing you must judge a gape on is not on screen.
    const skin = f(0x473b52)
    const belly = f(0x6a5a78)
    const tooth = f(0xe8e2d4)
    const lw = Math.max(2, r * 0.11)
    const noseX = r * 0.95
    const len = r * 1.85
    const spine = (t) => [noseX - t * len, 0]
    // A globe, not a spindle: widest almost immediately and holding it, so the silhouette reads as
    // a swimming head with a fish attached rather than as a fish with a big head.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.2), 0.5)
      // A LOW exponent, so the body stays fat most of its length and only collapses at the wrist.
      // At 1.15 it fell away linearly and the silhouette read as a tent — a cone with a spike —
      // rather than as the globe an anglerfish is.
      const fall = Math.pow(Math.max(0, 1 - (t - 0.2) / 0.78), 0.62)
      return r * 0.62 * Math.max(0.07, t < 0.2 ? rise : fall)
    }
    groundShadow(r * 1.0, r * 0.7)
    const [tx] = spine(0.97)
    g.poly([tx + r * 0.05, 0, tx - r * 0.42, r * 0.34, tx - r * 0.3, 0, tx - r * 0.42, -r * 0.34])
      .fill({ color: belly, alpha: 0.9 }).stroke({ width: lw * 0.45, color: line })
    g.poly(spineOutline(spine, body, 34)).fill(skin).stroke({ width: lw, color: line })
    if (!white) {
      // THE SOCKET the gape opens over. Baked dark and permanent, so when drawDeepTells widens the
      // mouth on top there is already blackness underneath it rather than body colour showing
      // through a half-open jaw.
      g.ellipse(noseX - r * 0.18, 0, r * 0.42, r * 0.5).fill({ color: f(0x07090d), alpha: 0.95 })
      // Teeth: a ring of needles around the socket's rim. Few and long — a row of small ones turns
      // to a grey smudge at sprite size, which is the failure mode the viperfish below shares.
      for (let i = 0; i < 9; i++) {
        const a = -1.15 + (i / 8) * 2.3
        const bx = noseX - r * 0.18 + Math.cos(a) * r * 0.38
        const by = Math.sin(a) * r * 0.46
        g.poly([bx, by, bx + Math.cos(a) * r * 0.2, by + Math.sin(a) * r * 0.22,
                bx - Math.sin(a) * r * 0.07, by + Math.cos(a) * r * 0.07])
          .fill({ color: tooth, alpha: 0.92 })
      }
      // THE ILLICIUM: the stalk, arching forward over the head, with the esca at its tip. Offset in
      // +y rather than dead centre so it does not sit on the body's own axis and vanish into it.
      const ex = noseX + r * 0.52, ey = -r * 0.34
      g.moveTo(noseX - r * 0.5, -r * 0.1).quadraticCurveTo(noseX + r * 0.3, -r * 0.7, ex, ey)
        .stroke({ width: lw * 0.6, color: f(0x171420), alpha: 0.95 })
      // Three stops rather than two, and wider than it looks like it needs to be: this is the only
      // light source in the chapter and it is what the player crosses the screen toward.
      g.circle(ex, ey, r * 0.52).fill({ color: f(0x5fd8c0), alpha: 0.16 })
      g.circle(ex, ey, r * 0.30).fill({ color: f(0x7fe9d0), alpha: 0.38 })
      g.circle(ex, ey, r * 0.17).fill({ color: f(0xaef4e2), alpha: 0.75 })
      g.circle(ex, ey, r * 0.09).fill({ color: f(0xf2fffb), alpha: 1 })
      for (const s of [-1, 1]) darkEye(g, noseX - r * 0.52, s * r * 0.25, r * 0.09, r * 0.085, 0x05070a, true)
    }
    if (elite) eliteCrown(-r * 1.1, r)
  }

  // hagfish: a rope. No fins, no shoulders, no taper worth the name — the one body in the game whose
  // outline is very nearly a constant-width tube, which is exactly what separates it from every
  // other fish on this floor without needing a single colour to survive the dark.
  function drawHagfish(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x2a1f22)
    const skin = f(0x8f6f72)
    const pale = f(0xc0a29e)
    const lw = Math.max(2, r * 0.09)
    const noseX = r * 1.15
    const len = r * 2.5
    const spine = (t) => [noseX - t * len, Math.sin(t * 5.4) * r * 0.3]  // a body caught mid-writhe
    const body = (t) => r * 0.19 * Math.max(0.35, 1 - Math.pow(Math.max(0, t - 0.72) / 0.28, 1.3) * 0.6)
    groundShadow(r * 1.1, r * 0.3)
    g.poly(spineOutline(spine, body, 40)).fill(skin).stroke({ width: lw, color: line })
    if (!white) {
      // THE SLIME PORES, the one mark it has: a row down each flank, which is literally where a
      // hagfish's slime glands are and the tell for the webZone patch it leaves behind.
      for (let i = 0; i < 9; i++) {
        const t = 0.12 + i * 0.085
        const [px, py] = spine(t)
        const w = body(t)
        for (const s of [-1, 1]) g.circle(px, py + s * w * 0.75, r * 0.048).fill({ color: pale, alpha: 0.8 })
      }
      // The head is barely a head — a blunt cap and four barbels, no jaw. A hagfish has no jaws at
      // all, and the absence is the animal.
      const [hx, hy] = spine(0.04)
      g.circle(hx, hy, r * 0.21).fill({ color: skin }).stroke({ width: lw * 0.7, color: line })
      for (let i = 0; i < 4; i++) {
        const a = -0.9 + i * 0.6
        g.moveTo(hx + r * 0.14, hy).lineTo(hx + r * 0.14 + Math.cos(a) * r * 0.34, hy + Math.sin(a) * r * 0.3)
          .stroke({ width: Math.max(0.8, r * 0.03), color: pale, alpha: 0.8 })
      }
    }
    if (elite) eliteCrown(-r * 1.4, r)
  }

  // viperfish: the fast slot, and it is all jaw and light. A thin dark ribbon you would lose against
  // this floor entirely if not for two things: fangs too long to close over, and a line of
  // photophores down each flank. Both are real viperfish anatomy and both are legible at 16px.
  function drawViperfish(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x0b1418)
    const skin = f(0x1f3038)
    const glow = f(0x9fe0ff)
    const tooth = f(0xf0efe4)
    const lw = Math.max(2, r * 0.09)
    const noseX = r * 1.1
    const len = r * 2.4
    const spine = (t) => [noseX - t * len, 0]
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.22), 0.6)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.22) / 0.74), 1.7)
      return r * 0.22 * Math.max(0.06, t < 0.22 ? rise : fall)
    }
    groundShadow(r * 1.0, r * 0.22)
    const [tx] = spine(0.96)
    g.poly([tx + r * 0.05, 0, tx - r * 0.5, r * 0.3, tx - r * 0.34, 0, tx - r * 0.5, -r * 0.3])
      .fill({ color: skin, alpha: 0.9 }).stroke({ width: lw * 0.5, color: line })
    g.poly(spineOutline(spine, body, 34)).fill(skin).stroke({ width: lw, color: line })
    if (!white) {
      // The fangs. FOUR, long, and reaching PAST the snout — a viperfish's teeth do not fit inside
      // its mouth, and drawing a mouthful of small ones instead reads as a grey smudge.
      for (const s of [-1, 1]) {
        for (let i = 0; i < 2; i++) {
          const bx = noseX - r * 0.1 - i * r * 0.16
          const by = s * r * 0.1
          g.poly([bx, by, bx + r * 0.42 - i * r * 0.1, by + s * r * 0.05, bx + r * 0.04, by + s * r * 0.09])
            .fill({ color: tooth, alpha: 0.94 })
        }
      }
      // Photophores: the row of lights down each flank, and the only colour on the animal.
      for (let i = 0; i < 8; i++) {
        const t = 0.22 + i * 0.085
        const [px] = spine(t)
        const w = body(t)
        for (const s of [-1, 1]) {
          g.circle(px, s * (w + r * 0.02), r * 0.055).fill({ color: glow, alpha: 0.85 })
        }
      }
      for (const s of [-1, 1]) darkEye(g, noseX - r * 0.42, s * r * 0.11, r * 0.075, r * 0.07, 0x040a0d, true)
    }
    if (elite) eliteCrown(-r * 1.3, r)
  }

  // gulper eel: a mouth with a thread attached. The proportions ARE the animal — the head is most of
  // the mass and the tail is a hair — so this is the one body here that needs no marks at all to be
  // told apart from the other three at a glance, in the dark, at speed.
  function drawGulperEel(g, elite, white) {
    const r = 18
    const f = (c) => white ? 0xffffff : c
    const line = f(0x0d0a12)
    const skin = f(0x241d2e)
    const gum = f(0x5c2f3d)
    const tipGlow = f(0xff9f6b)
    const lw = Math.max(2, r * 0.1)
    const noseX = r * 1.0
    const len = r * 2.9
    const spine = (t) => [noseX - t * len, Math.sin(t * 3.1) * r * 0.16]
    // A hard, early peak and then a collapse to almost nothing: the pouch, then the whip.
    const body = (t) => {
      const rise = Math.pow(Math.min(1, t / 0.12), 0.45)
      const fall = Math.pow(Math.max(0, 1 - (t - 0.12) / 0.88), 2.6)
      return r * 0.66 * Math.max(0.035, t < 0.12 ? rise : fall)
    }
    groundShadow(r * 1.0, r * 0.55)
    g.poly(spineOutline(spine, body, 40)).fill(skin).stroke({ width: lw, color: line })
    if (!white) {
      // The pouch, open. Drawn as a wedge from the hinge forward rather than as an ellipse, so the
      // mouth has CORNERS and reads as hinged rather than as a hole cut in the head.
      //
      // ⚠ THE GUM IS THE ONLY REASON THIS READS AS A MOUTH. The first cut filled the pouch at
      // 0x08060c against a 0x241d2e body — two near-blacks — and the thumbnail came back as a KITE:
      // a dark wedge with a thread, no mouth in it at all. On a floor this dark an interior cannot
      // be told from a body by its fill, so the opening is carried by a bright RIM instead, and the
      // rim is thick enough to survive a 16px sprite.
      g.poly([noseX - r * 0.62, 0, noseX + r * 0.34, -r * 0.62, noseX + r * 0.5, 0, noseX + r * 0.34, r * 0.62])
        .fill({ color: f(0x0d0a14), alpha: 0.98 }).stroke({ width: lw * 1.15, color: gum })
      for (const s of [-1, 1]) {
        g.moveTo(noseX - r * 0.62, 0).lineTo(noseX + r * 0.34, s * r * 0.62)
          .stroke({ width: lw * 1.3, color: gum, alpha: 1 })
      }
      // The jaw line across the gape's leading edge, pale: the lip. It closes the wedge into a shape
      // the eye reads as a container rather than as a corner of the body.
      g.moveTo(noseX + r * 0.34, -r * 0.62).lineTo(noseX + r * 0.5, 0).lineTo(noseX + r * 0.34, r * 0.62)
        .stroke({ width: lw * 0.9, color: f(0xa8697a), alpha: 0.9 })
      // The tail tip is luminous in the real animal, and here it doubles as the cue that the thread
      // trailing behind the mouth is still part of the same creature.
      const [ttx, tty] = spine(0.99)
      g.circle(ttx, tty, r * 0.13).fill({ color: tipGlow, alpha: 0.28 })
      g.circle(ttx, tty, r * 0.06).fill({ color: tipGlow, alpha: 0.85 })
      for (const s of [-1, 1]) darkEye(g, noseX - r * 0.5, s * r * 0.2, r * 0.075, r * 0.07, 0x05040a, true)
    }
    if (elite) eliteCrown(-r * 1.1, r)
  }

  // lionfish: the one body here that DOES share the reef's own hue, and it separates on shape alone.
  // From directly overhead a lionfish is not a fish outline at all — it is a STARBURST of pectoral
  // rays thrown out to both sides, wider than the body is long. No retint could have bought that
  // separation from a warm player on a warm floor; the silhouette does it for free.
  //
  // FOUR POSES, DRIVEN BY THE `pounce` STATE MACHINE, not by a timer (the toad's idiom — `poses`
  // selects a frame, `phases` would flip through them on animT). The fan is the state: spread while
  // it drifts, flared widest while it aims, folded flat along the body while it is in the air, then
  // half-open as it recovers. That is a lionfish's real hunting behaviour and it is also the clearest
  // telegraph available — a fan snapping shut is visible at a glance, where a colour change is not.
  const LIONFISH_POSES = [
    { spread: 1.0, rake: 0.1 },    // hold — drifting, fan open and raked a little back
    { spread: 1.26, rake: -0.16 }, // aim  — flared forward: the threat display
    { spread: 0.3, rake: 0.62 },   // leap — folded flat along the body: a dart
    { spread: 0.72, rake: 0.3 },   // land — half open, re-spreading
  ]
  function drawLionfish(g, elite, white, pose = 0) {
    const r = 12
    const P = LIONFISH_POSES[Math.min(LIONFISH_POSES.length - 1, Math.max(0, pose | 0))]
    const f = (c) => white ? 0xffffff : c
    const line = f(0x5e2320)
    const cream = f(0xf6e3c8)
    const band = f(0x8e2f2c)
    const lw = Math.max(1.8, r * 0.12)
    const noseX = r * 0.95
    const len = r * 2.0
    const H = r * 0.36
    const spine = (t) => [noseX - t * len, 0]
    const body = (t) => H * bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.36 ? 0.35 : 0.8)
    groundShadow(r * 1.1, H + r * 0.3)
    // THE FAN. 6 rays a side, each a banded spine rather than a webbed blade — separated rays are
    // what a lionfish has and a webbed fan is what every other fin in this game is, so the gaps are
    // load-bearing. The pose's `spread` scales the fan about its own centre and `rake` swings the
    // whole thing back, so folding is one number rather than four drawings.
    // THE LENGTH LOBE IS WHAT KEEPS IT A FISH. Rays of near-equal length all the way round read as a
    // sea urchin, which is what the first cut came back as: 0.5 + 0.5 sin makes the middle rays
    // twice the end ones, so the fan has a shape and the body still shows through it.
    const RAYS = 6
    const A0 = Math.PI * 0.28, A1 = Math.PI * 0.8, AC = (A0 + A1) / 2
    for (const s of [-1, 1]) {
      for (let i = 0; i < RAYS; i++) {
        const u = i / (RAYS - 1)
        const a = AC + (A0 + (A1 - A0) * u - AC) * P.spread + P.rake
        const L = r * 2.15 * (0.5 + 0.5 * Math.sin(Math.PI * u))
        const x0 = r * 0.22, y0 = s * H * 0.72
        const x1 = x0 + Math.cos(a) * L, y1 = y0 + s * Math.sin(a) * L
        taperStroke(g, [[x0, y0], [x1, y1]], Math.max(1.5, r * 0.13), Math.max(0.7, r * 0.045), cream, 4)
        if (!white) { // two maroon bands per ray — the banding is the second read after the shape
          for (const [b0, b1] of [[0.28, 0.44], [0.62, 0.78]]) {
            taperStroke(g, [[x0 + (x1 - x0) * b0, y0 + (y1 - y0) * b0], [x0 + (x1 - x0) * b1, y0 + (y1 - y0) * b1]],
              Math.max(1.4, r * 0.11), Math.max(0.8, r * 0.07), 0x8e2f2c, 2)
          }
        }
      }
    }
    // Dorsal spines: venomous, and from above they project as a short fringe either side of the
    // midline rather than as a sail. Four and short — six long ones joined the pectoral rays into
    // one undifferentiated ball of spikes.
    for (let i = 0; i < 4; i++) {
      const t = 0.2 + i * 0.13
      const [x] = spine(t)
      const s = i % 2 ? 1 : -1
      taperStroke(g, [[x, 0], [x - r * 0.16, s * (body(t) + r * 0.22)]], Math.max(1.2, r * 0.1), 0.7, band, 3)
    }
    const [tx] = spine(0.97) // caudal: a small spread fan, banded like the rest of it
    for (const s of [-1, 1]) {
      g.poly([tx, 0, tx - r * 0.52, s * r * 0.36, tx - r * 0.44, s * r * 0.05])
        .fill({ color: cream, alpha: 0.92 }).stroke({ width: lw * 0.5, color: line })
    }
    g.poly(spineOutline(spine, body, 30)).fill(cream).stroke({ width: lw, color: line })
    if (!white) {
      for (const [t0, t1] of [[0.14, 0.26], [0.38, 0.5], [0.62, 0.74], [0.84, 0.94]]) {
        g.poly(spineOutline(spine, body, 6, t0, t1)).fill({ color: 0x8e2f2c, alpha: 0.9 })
      }
      const [ex] = spine(0.12)
      for (const s of [-1, 1]) darkEye(g, ex, s * body(0.12) * 0.62, r * 0.09, r * 0.085, 0x2a0f0c, true)
    }
    if (elite) eliteCrown(-r * 1.5, r)
  }

  // --- Garden chapter (lawn green) ---
  // ant: head (right) + narrow thorax + a VISIBLE petiole node + a big tapered gaster (left) — three
  // separate flowing paths so the waist reads, 6 jointed legs (coxa->femur->tibia->tarsus) in
  // forward/mid/back pairs, elbowed antennae (scape then funiculus), mandibles.
  function drawAnt(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x5e2e18)
    const lw = Math.max(2.2, r * 0.12)
    groundShadow(r, r * 0.72)
    // legs: 3 per side, each 3 straight-ish segments to a fine tarsus; the far side (s=-1) is
    // slightly shorter/tighter so the pose is not mirror-boring.
    const legSets = [
      [[0.46, 0.16], [0.96, 0.72], [1.2, 1.02]],   // fore, angled forward
      [[0.28, 0.17], [0.44, 0.82], [0.32, 1.15]],  // mid, straight out
      [[0.04, 0.16], [-0.44, 0.76], [-0.88, 1.05]], // hind, angled back
    ]
    for (const s of [-1, 1]) {
      const ys = s < 0 ? 0.9 : 1
      const xs = s < 0 ? 1.04 : 1
      for (const set of legSets) {
        const p = set.map(([lx, ly]) => [lx * r * xs, s * ly * r * ys])
        taperStroke(g, [[p[0][0], p[0][1] * 0.4], ...p], r * 0.16, r * 0.05, line)
      }
    }
    // elbowed antennae: long scape, then a bent funiculus (different bends per side)
    taperStroke(g, [[r * 0.96, -r * 0.1], [r * 1.3, -r * 0.42], [r * 1.16, -r * 0.86]], r * 0.13, r * 0.045, line)
    taperStroke(g, [[r * 0.96, r * 0.1], [r * 1.34, r * 0.36], [r * 1.1, r * 0.8]], r * 0.13, r * 0.045, line)
    // mandibles: two small forward points
    taperStroke(g, [[r * 1.02, -r * 0.14], [r * 1.28, -r * 0.04]], r * 0.11, r * 0.035, line)
    taperStroke(g, [[r * 1.02, r * 0.14], [r * 1.26, r * 0.06]], r * 0.11, r * 0.035, line)
    // gaster: egg tapering to a rounded apex at the rear
    const gSpine = (t) => [-r * 0.35 - t * r * 1.0, t * r * 0.04]
    const gW = (t) => r * 0.5 * bulge(0.1 + 0.9 * t, 0.62)
    g.poly(spineOutline(gSpine, gW, 30)).fill(f(0x9e5230)).stroke({ width: lw, color: line })
    // petiole: the ant signature — a thin waist with a raised node
    taperStroke(g, [[-r * 0.36, 0], [-r * 0.06, 0]], r * 0.15, r * 0.17, f(0x9e5230))
    g.circle(-r * 0.22, -r * 0.03, r * 0.11).fill(f(0x9e5230)).stroke({ width: 1.4, color: line })
    // thorax: narrow, humped
    const tSpine = (t) => [-r * 0.06 + t * r * 0.62, -t * r * 0.04]
    const tW = (t) => r * 0.27 * (0.72 + 0.28 * bulge(Math.pow(t, 0.8), 1))
    g.poly(spineOutline(tSpine, tW, 20)).fill(f(0x9e5230)).stroke({ width: lw * 0.85, color: line })
    // head: egg, wider behind the eyes than at the mandibles
    g.poly(radialOutline((a) => r * 0.36 * (1 - 0.1 * Math.cos(a)), 40, 1, 0.95, r * 0.76, -r * 0.02))
      .fill(f(0x9e5230)).stroke({ width: lw, color: line })
    if (!white) {
      g.ellipse(-r * 0.8, r * 0.16, r * 0.42, r * 0.26).fill({ color: 0x5e2e18, alpha: 0.22 })
      g.ellipse(-r * 0.78, -r * 0.16, r * 0.34, r * 0.18).fill({ color: mix(0x9e5230, 0xffffff, 0.45), alpha: 0.16 })
      g.ellipse(r * 0.72, -r * 0.14, r * 0.2, r * 0.1).fill({ color: mix(0x9e5230, 0xffffff, 0.45), alpha: 0.16 })
      g.beginPath()
      for (const t of [0.34, 0.55, 0.75]) { // gaster tergite plates
        const [x, y] = gSpine(t)
        const w = gW(t)
        g.moveTo(x + r * 0.03, y - w * 0.88).lineTo(x - r * 0.03, y + w * 0.88)
      }
      g.stroke({ width: 1.2, color: 0x5e2e18, alpha: 0.5 })
      for (const s of [-1, 1]) darkEye(g, r * 0.84, s * r * 0.17, r * 0.13, r * 0.15, 0x2a1409, true)
    }
    if (elite) eliteCrown(-r * 0.52, r)
  }
  // wasp: pinched waist between a dark thorax and a TAPERED abdomen that closes into a fine stinger
  // (left); the 3 yellow/black bands are slices of the abdomen's own outline so they follow the
  // taper. Two translucent wings with hairline venation, swept back. Dark head, compound eyes.
  function drawWasp(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const lw = Math.max(2, r * 0.14)
    groundShadow(r, r * 0.8)
    const aSpine = (t) => [r * 0.18 - t * r * 1.22, t * r * 0.06]
    const aW = (t) => r * 0.62 * bulge(0.1 + 0.9 * t, 0.55)
    // wings first (behind); solid white on the twin so the translucent originals' bounds match
    const wing = (bx, by, tx, ty, W) => {
      const s = (t) => [bx + (tx - bx) * t, by + (ty - by) * t]
      const w = (t) => W * bulge(Math.pow(t, 0.55), 0.85)
      g.poly(spineOutline(s, w, 20)).fill(white ? 0xffffff : { color: 0xffffff, alpha: 0.4 })
        .stroke({ width: 1.2, color: white ? 0xffffff : 0xbcd2dd, alpha: white ? 1 : 0.8 })
      if (!white) {
        // Hairline venation. Each vein rides the wing's OWN half-width profile (offset = w(t)*v,
        // |v| <= 0.55), so it fans with the taper and can never reach past the wing's stroked
        // outline — which keeps the normal variant's bounds identical to the white twin's.
        const nx = -(ty - by)
        const ny = tx - bx
        const m = Math.hypot(nx, ny) || 1
        g.beginPath()
        for (const v of [-0.5, 0.05, 0.55]) {
          for (let i = 0; i <= 5; i++) {
            const t = 0.08 + (0.9 - 0.08) * (i / 5)
            const [sx, sy] = s(t)
            const o = w(t) * v
            const px = sx + (nx / m) * o
            const py = sy + (ny / m) * o
            if (i === 0) g.moveTo(px, py)
            else g.lineTo(px, py)
          }
        }
        g.stroke({ width: 1, color: 0x8fb0c0, alpha: 0.55 })
      }
    }
    wing(r * 0.5, -r * 0.16, -r * 0.9, -r * 0.82, r * 0.26)
    wing(r * 0.5, r * 0.16, -r * 0.78, r * 0.72, r * 0.22)
    // stinger: fine tapered spike off the abdomen apex (sets the left bound in both variants)
    taperStroke(g, [[-r * 1.02, r * 0.06], [-r * 1.36, r * 0.12]], r * 0.16, 0.7, f(0x2a2a2a))
    g.poly(spineOutline(aSpine, aW, 30)).fill(f(0xf2c93a)).stroke({ width: lw, color: f(0xb8942a) })
    if (!white) {
      for (const [t0, t1] of [[0.1, 0.26], [0.4, 0.56], [0.7, 0.86]]) {
        g.poly(spineOutline(aSpine, aW, 8, t0, t1)).fill(0x2a2a2a) // bands follow the taper
      }
      g.ellipse(-r * 0.4, r * 0.3, r * 0.5, r * 0.2).fill({ color: 0xb8942a, alpha: 0.2 })
      g.ellipse(-r * 0.4, -r * 0.3, r * 0.42, r * 0.14).fill({ color: mix(0xf2c93a, 0xffffff, 0.5), alpha: 0.18 })
    }
    // pinched waist (petiole)
    taperStroke(g, [[r * 0.14, 0], [r * 0.36, 0]], r * 0.14, r * 0.16, f(0x2a2a2a))
    // legs: 6 short danglers off the thorax
    for (const s of [-1, 1]) {
      const ys = s < 0 ? 0.88 : 1
      for (const [ox, kx, ky, fx, fy] of [[0.72, 0.98, 0.5, 1.1, 0.76], [0.55, 0.6, 0.58, 0.44, 0.84], [0.4, 0.24, 0.56, 0.02, 0.8]]) {
        taperStroke(g, [[r * ox, s * r * 0.1], [r * kx, s * r * ky * ys], [r * fx, s * r * fy * ys]], r * 0.12, r * 0.04, f(0x1c1c1c))
      }
    }
    // thorax + head
    const thSpine = (t) => [r * 0.34 + t * r * 0.5, 0]
    g.poly(spineOutline(thSpine, (t) => r * 0.36 * (0.76 + 0.24 * bulge(Math.pow(t, 0.7), 1)), 20))
      .fill(f(0x2a2a2a)).stroke({ width: lw * 0.8, color: f(0x101010) })
    g.poly(radialOutline((a) => r * 0.3 * (1 - 0.14 * Math.cos(a)), 32, 0.86, 1, r * 0.98, -r * 0.02))
      .fill(f(0x2a2a2a)).stroke({ width: lw * 0.7, color: f(0x101010) })
    if (!white) {
      g.ellipse(r * 0.58, -r * 0.14, r * 0.2, r * 0.1).fill({ color: 0x6a6a6a, alpha: 0.35 })
      for (const s of [-1, 1]) darkEye(g, r * 0.98, s * r * 0.15, r * 0.09, r * 0.13, 0x0b0b12, true)
    }
    if (elite) eliteCrown(-r * 0.9, r)
  }
  // spider: a large egg-shaped abdomen (left) + a distinctly smaller cephalothorax (right) joined at
  // a pedicel, 8 jointed legs (femur raised out to a knee, then tibia back down to a fine tarsus)
  // with the front pair reaching furthest, pedipalps, folium marking, and an 8-eye cluster.
  function drawSpider(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x3a2337)
    const lw = Math.max(2.5, r * 0.12)
    const farLine = white ? 0xffffff : mix(0x3a2337, 0x000000, 0.35)
    groundShadow(r, r * 0.95)
    // Abdomen as a TRUE OVOID. A spine + width-profile is the wrong primitive here: a sin^k profile
    // holds ~95% of max across its whole middle, which draws a barrel with flat parallel sides. So
    // parametrise the closed curve directly — x sweeps as cos(u) while the half-width carries an
    // asymmetry term (1 + k*cos u), k<0. That fattens the rear and narrows the front, putting the
    // widest point ~64% back from the pedicel, and every point sits on a curve: no straight runs,
    // no corner radius. NORM rescales the peak of that term back to 1.
    const AB = { cx: -r * 0.52, cy: -r * 0.02, L: r * 0.78, W: r * 0.6, k: -0.32, tilt: -0.1 }
    const NORM = 1.046
    const abPt = (u, sw = 1) => {
      const x = AB.L * Math.cos(u)
      const y = AB.W * sw * Math.sin(u) * (1 + AB.k * Math.cos(u)) / NORM
      const c = Math.cos(AB.tilt)
      const s = Math.sin(AB.tilt)
      return [AB.cx + x * c - y * s, AB.cy + x * s + y * c]
    }
    const abPath = (n = 56, sw = 1) => {
      const p = []
      for (let i = 0; i < n; i++) { const [x, y] = abPt((i / n) * Math.PI * 2, sw); p.push(x, y) }
      return p
    }
    // A band between two half-width scales over a u range. Both edges share the same x(u), so the
    // band tracks the abdomen's own curvature and cannot escape the silhouette at any tilt.
    const abBand = (u0, u1, swOut, swIn, n = 22) => {
      const p = []
      for (let i = 0; i <= n; i++) { const [x, y] = abPt(u0 + (u1 - u0) * (i / n), swOut); p.push(x, y) }
      for (let i = n; i >= 0; i--) { const [x, y] = abPt(u0 + (u1 - u0) * (i / n), swIn); p.push(x, y) }
      return p
    }
    // legs: origin on the cephalothorax -> raised femur to an outermost knee -> descending tibia ->
    // fine tarsus. Four distinct radial directions per side (forward / fwd-mid / back-mid / back)
    // so they splay instead of clustering; the front pair reaches furthest.
    const legSets = [
      [[0.85, 0.2], [1.5, 0.8], [1.95, 0.5], [2.08, 0.38]],
      [[0.7, 0.26], [1.1, 1.15], [1.35, 1.48], [1.44, 1.58]],
      [[0.52, 0.28], [0.32, 1.25], [0.26, 1.55], [0.24, 1.66]],
      [[0.36, 0.26], [-0.35, 1.05], [-0.9, 1.35], [-1.08, 1.45]],
    ]
    const legs = (s, col) => {
      const ys = s < 0 ? 0.9 : 1
      const xs = s < 0 ? 1.02 : 1
      for (const set of legSets) {
        taperStroke(g, set.map(([lx, ly]) => [lx * r * xs, s * ly * r * ys]), r * 0.15, r * 0.028, col)
      }
    }
    legs(-1, farLine) // far side first: darker and behind the body, for depth
    g.poly(abPath()).fill(f(0x5b3a52)).stroke({ width: lw, color: line })
    // pedicel + cephalothorax (clearly smaller)
    taperStroke(g, [[r * 0.16, 0], [r * 0.34, 0]], r * 0.1, r * 0.12, f(0x5b3a52))
    const cSpine = (t) => [r * 0.24 + t * r * 0.72, 0]
    const cW = (t) => r * 0.48 * bulge(0.2 + 0.7 * t, 0.5)
    g.poly(spineOutline(cSpine, cW, 24)).fill(f(0x5b3a52)).stroke({ width: lw * 0.85, color: line })
    legs(1, line) // near side on top, so the legs read as attaching to the cephalothorax
    // pedipalps
    for (const s of [-1, 1]) taperStroke(g, [[r * 0.86, s * r * 0.12], [r * 1.08, s * r * 0.3], [r * 1.2, s * r * 0.22]], r * 0.1, r * 0.04, line)
    if (!white) {
      // folium: a soft lanceolate dorsal marking that rides the abdomen's own curvature (it reuses
      // the same (1 + k*cos u) asymmetry), pointed at both ends, gently scalloped. Its half-width is
      // <=0.45 of the outline's at the same u while its x is pulled in, so it stays well inside.
      const fol = []
      for (let i = 0; i < 48; i++) {
        const u = (i / 48) * Math.PI * 2
        const su = Math.sin(u)
        const x = AB.L * 0.78 * Math.cos(u)
        const y = AB.W * 0.4 * Math.sign(su) * Math.pow(Math.abs(su), 1.45) *
          (1 + AB.k * Math.cos(u)) / NORM * (1 + 0.12 * Math.cos(u * 3))
        const c = Math.cos(AB.tilt)
        const s = Math.sin(AB.tilt)
        fol.push(AB.cx + x * c - y * s, AB.cy + x * s + y * c)
      }
      g.poly(fol).fill({ color: 0xe0b8d8, alpha: 0.26 })
      g.poly(abBand(0.12 * Math.PI, 0.92 * Math.PI, 1, 0.42)).fill({ color: 0x3a2337, alpha: 0.2 })
      g.poly(abBand(-0.85 * Math.PI, -0.25 * Math.PI, 0.86, 0.4)).fill({ color: mix(0x5b3a52, 0xffffff, 0.45), alpha: 0.15 })
      g.ellipse(r * 0.58, -r * 0.14, r * 0.24, r * 0.1).fill({ color: mix(0x5b3a52, 0xffffff, 0.5), alpha: 0.16 })
      g.beginPath()
      for (const u of [0.42 * Math.PI, 0.66 * Math.PI]) { // faint chitin ridges, across the curve
        const [x0, y0] = abPt(u, 0.82)
        const [x1, y1] = abPt(-u, 0.82)
        g.moveTo(x0, y0).lineTo(x1, y1)
      }
      g.stroke({ width: 1.1, color: 0x3a2337, alpha: 0.3 })
      // eye cluster: 2 big + 6 small, two ranks, each with a pinprick
      for (const [ex, ey, er] of [[0.85, -0.09, 0.062], [0.85, 0.09, 0.062], [0.74, -0.19, 0.036], [0.74, 0.19, 0.036], [0.93, -0.19, 0.034], [0.93, 0.19, 0.034], [0.69, -0.04, 0.032], [0.69, 0.04, 0.032]]) {
        darkEye(g, r * ex, r * ey, r * er, r * er, 0x150d16, er > 0.05)
      }
    }
    if (elite) eliteCrown(-r * 0.72, r)
  }

  // --- Undergrowth chapter (dead-leaf loam) ---
  // The undergrowth floor is the DARKEST biome yet: bg 0x2b2417 under blotches multiplied by
  // floorTint 0x8a7a4e lands around 0x514628, relative luminance ~0.06. Dark-on-dark is the failure
  // mode, and going darker still cannot win (pure black only reaches 2.3x against a floor this dim),
  // so all three predators are LIGHT — spread across the light half so they also stay mutually
  // distinct by VALUE, not just by hue and shape:
  //   cat = LIGHTEST  (pale silver tabby, 5.6x on the loam)
  //   owl = MID-LIGHT (tawny gold, 4.3x)
  //   rat = DIMMEST   (dusty grey-mauve, 2.8x — still well clear of the ~1.5x invisibility floor)
  //

  // --- Undergrowth's pouncing TANK. Was a cat through v6.6.31 and is a toad from v6.6.32 (owner,
  // after rejecting seven cat revisions: "what's another animal that could fit the lore and be
  // easier to draw?" -> three were drawn, this one was picked).
  //
  // Why the cat could never be made to work at this size, recorded so it is not re-attempted: a cat
  // has NO GRAPHIC HOOK. Its identity is subtle proportion and flow — head-to-body ratio, the curve
  // of the back — and at 26px subtlety is simply gone, leaving a pale quadruped indistinguishable
  // from the chapter's rat. Every creature in this game that reads well has a feature you can COUNT:
  // the spider's eight legs, the wasp's wings, the centipede's segments. The toad was chosen on
  // exactly that property, and its hook is the pair of EYE DOMES that break the front silhouette.
  // Nothing else in the game is a wide body with two lamps on the front of it.
  //
  // It is also the one candidate whose real locomotion IS the pounce, so hold -> aim -> leap -> land
  // stops being a state machine bolted onto an animal and becomes what a toad actually does. The
  // 0.5s frozen landing reads as a heavy toad recovering rather than as an arbitrary punish window.
  // Lore fit is free: leaf litter is where toads live, and one that eats things your size is a
  // genuine predator at ankle height.
  //
  // Palette: pale olive-stone. The undergrowth floor lands around 0x514628 and its documented
  // failure mode is dark-on-dark, so the chapter's predators are all LIGHT — see the contrast note
  // above drawRat. The green is warm and desaturated enough to stay in that family.
  //
  // FOUR POSES, keyed off the pounce state by ROSTER_LOOKS.toad.poseOf (the state-driven sibling of
  // `phases` — see makeRosterLook). `fold` is the whole animation: 0 = hind legs folded into the
  // sitting Z, 1 = extended straight back mid-leap. Every other number just squashes or stretches
  // the same body, so the four poses read as one animal moving.
  const TOAD_POSES = [
    { len: 1.00, wid: 1.00, fold: 0.00 },  // hold:   sitting squat, legs folded
    { len: 0.88, wid: 1.14, fold: 0.30 },  // aim:    gathered and wider, legs coiling
    { len: 1.32, wid: 0.84, fold: 1.00 },  // leap:   stretched, legs trailing straight back
    { len: 0.92, wid: 1.24, fold: 0.12 },  // land:   splatted widest, legs splayed
  ]
  function drawToad(g, elite, white, pose = 0) {
    const r = 23
    const P = TOAD_POSES[pose] ?? TOAD_POSES[0]
    const L = P.len
    const W = P.wid
    const K = P.fold
    const f = (c) => white ? 0xffffff : c
    const line = f(0x3d3a22)
    const skin = f(0xd3cc9e)
    const under = white ? 0xffffff : 0xa39c6e
    const lw = Math.max(2.4, r * 0.1)
    const X = (v) => v * L * r
    const Y = (v, sgn) => v * sgn * W * r
    const lerp2 = (a, b) => a + (b - a) * K
    groundShadow(r * 1.1, 0)

    // HIND LEGS first, and drawn FAT. Rev.1 of this toad had them at 0.3r and the eyes were doing
    // all the work at 26px; the folded Z is meant to be the second cue and it has to survive being
    // downsampled to read at all. hip -> knee -> ankle, lerped from folded to extended.
    for (const sgn of [-1, 1]) {
      const hip = [X(-0.46), Y(0.52, sgn)]
      const knee = [X(lerp2(-0.1, -1.1)), Y(lerp2(1.24, 0.78), sgn)]
      const ankle = [X(lerp2(-0.66, -1.8)), Y(lerp2(1.32, 0.5), sgn)]
      taperStroke(g, [hip, knee, ankle], r * 0.4, r * 0.19, under, 4)
      // splayed foot: three toes off the ankle. A toad's foot is a fan, and the fan is what stops
      // the leg reading as a stub.
      for (const t of [-0.36, 0, 0.36]) {
        const tx = ankle[0] + X(lerp2(-0.4, -0.42)) * (1 + t * 0.3)
        const ty = ankle[1] + Y(lerp2(0.1, -0.16), sgn) + Y(t * 0.42, sgn)
        taperStroke(g, [ankle, [tx, ty]], r * 0.12, r * 0.05, under, 2)
      }
    }
    // front feet: tucked under the chin when sitting, reaching forward mid-leap
    for (const sgn of [-1, 1]) {
      const sh = [X(0.42), Y(0.42, sgn)]
      const hand = [X(lerp2(0.84, 1.16)), Y(lerp2(0.6, 0.36), sgn)]
      taperStroke(g, [sh, hand], r * 0.17, r * 0.09, under, 2)
      for (const t of [-0.3, 0, 0.3]) {
        taperStroke(g, [hand, [hand[0] + X(0.24), hand[1] + Y(0.04 + t * 0.5, sgn)]], r * 0.08, r * 0.035, under, 2)
      }
    }
    // body: wider than long, blunt at the snout, broad over the haunches. ONE outline — a toad is a
    // single mass and any attempt to articulate it just brings back the lumpiness the cat died of.
    g.poly(radialOutline((a) => r * 0.92 * (1 - 0.16 * Math.cos(a) + 0.07 * Math.cos(2 * a)), 52, L, 1.06 * W, 0, 0))
      .fill(skin).stroke({ width: lw, color: line })
    // EYE DOMES, drawn last and deliberately overlapping the outline so they BREAK the silhouette.
    // This is the hook the whole design rests on; if they ever stop poking out, it is a bean again.
    for (const sgn of [-1, 1]) {
      const ex = X(0.5)
      const ey = Y(0.44, sgn)
      g.circle(ex, ey, r * 0.3).fill(skin).stroke({ width: lw * 0.85, color: line })
      if (!white) {
        g.circle(ex + r * 0.04, ey, r * 0.19).fill(0xd9c24a)
        g.ellipse(ex + r * 0.05, ey, r * 0.055, r * 0.15).fill(0x171408)
        g.circle(ex + r * 0.13, ey - r * 0.09, Math.max(0.7, r * 0.055)).fill({ color: 0xffffff, alpha: 0.9 })
      }
    }
    if (!white) {
      g.beginPath() // the wide mouth line across the snout
      g.moveTo(X(0.76), Y(-0.32, 1)).quadraticCurveTo(X(0.98), 0, X(0.76), Y(0.32, 1))
      g.stroke({ width: 1.6, color: 0x6d6840, alpha: 0.8 })
      g.ellipse(X(0.32), 0, r * 0.3 * L, r * 0.34 * W).fill({ color: 0xe8e2c2, alpha: 0.4 }) // pale throat
      // mottling + warts. Four big blotches carry at 26px; the dot scatter is texture that only
      // shows when the sprite is large, which is the right way round.
      for (const [bx, by, br] of [[-0.42, -0.34, 0.3], [-0.5, 0.4, 0.26], [0.02, 0.02, 0.22], [-0.78, 0.02, 0.2]]) {
        g.ellipse(X(bx), Y(by, 1), br * r * L, br * r * 0.78 * W).fill({ color: 0x8f8b57, alpha: 0.34 })
      }
      for (const [wx, wy] of [[-0.2, -0.6], [-0.62, -0.62], [-0.24, 0.62], [-0.66, 0.6], [-0.86, -0.3], [0.1, -0.42], [0.12, 0.46]]) {
        g.circle(X(wx), Y(wy, 1), r * 0.07).fill({ color: 0x6d6840, alpha: 0.45 })
      }
    }
    if (elite) eliteCrown(-r * 1.2 * W, r)
  }
  // owl: seen from above-behind mid-swoop — body along x (head right), wings spread ±y and swept
  // back, each ONE tapered membrane with a scalloped trailing edge. The primaries are separate
  // tapered fingers off each tip (that splay is the owl read), and the barbs ride each wing's own
  // half-width profile — the same trick the wasp's venation uses, so they fan with the taper and can
  // never escape the outline, keeping the white twin's bounds identical.
  function drawOwl(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x6b4715)
    const lw = Math.max(1.8, r * 0.13)
    groundShadow(r * 1.2, r * 1.05)
    const wing = (s, tipX, tipY, W) => {
      const bx = r * 0.1
      const by = s * r * 0.3
      const sp = (t) => [bx + (tipX - bx) * t, by + (tipY - by) * t + s * Math.sin(t * Math.PI) * r * 0.16]
      // fat at the shoulder, tapering to the wrist; scalloped along the trailing half
      const w = (t) => W * bulge(Math.pow(t, 0.5), 0.8) * (1 + 0.09 * Math.cos(t * 9))
      g.poly(spineOutline(sp, w, 24)).fill(f(0xd9a959)).stroke({ width: lw * 0.8, color: line })
      // primaries: 4 tapered fingers fanning off the wingtip, each at its own angle
      for (let i = 0; i < 4; i++) {
        const a = Math.atan2(tipY - by, tipX - bx) + (i - 1.5) * 0.3
        taperStroke(g, [[tipX, tipY], [tipX + Math.cos(a) * r * 0.5, tipY + Math.sin(a) * r * 0.5]],
          W * 0.5, W * 0.14, f(0xc99447), 3)
      }
      if (!white) {
        const nx = -(tipY - by)
        const ny = tipX - bx
        const m = Math.hypot(nx, ny) || 1
        g.beginPath()
        for (const v of [-0.45, 0.5]) { // barbs, riding the wing's own half-width
          for (let i = 0; i <= 5; i++) {
            const t = 0.12 + 0.76 * (i / 5)
            const [sx, sy] = sp(t)
            const o = w(t) * v
            const px = sx + (nx / m) * o
            const py = sy + (ny / m) * o
            if (i === 0) g.moveTo(px, py)
            else g.lineTo(px, py)
          }
        }
        g.stroke({ width: 1, color: 0x8a5d1e, alpha: 0.5 })
      }
    }
    wing(-1, -r * 0.62, -r * 1.5, r * 0.34) // swept back, unequal reach per side
    wing(1, -r * 0.5, r * 1.42, r * 0.3)
    // tail fan: short tapered rectrices off the rear
    for (let i = 0; i < 3; i++) {
      const a = Math.PI + (i - 1) * 0.28
      taperStroke(g, [[-r * 0.62, 0], [-r * 0.62 + Math.cos(a) * r * 0.6, Math.sin(a) * r * 0.6]],
        r * 0.16, r * 0.07, f(0xc99447), 3)
    }
    // talons: two small hooked grabs under the body
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 0.2, s * r * 0.24], [r * 0.44, s * r * 0.5], [r * 0.66, s * r * 0.44]], r * 0.11, r * 0.035, f(0x8a6a2a))
    }
    // body: one blunt ovoid, tail-end left
    const bSpine = (t) => [-r * 0.66 + t * r * 1.4, 0]
    g.poly(spineOutline(bSpine, (t) => r * 0.44 * bulge(0.12 + 0.82 * t, 0.5), 26))
      .fill(f(0xd9a959)).stroke({ width: lw, color: line })
    // head: big and round, set forward-right, the classic owl disc
    g.poly(radialOutline((a) => r * 0.42 * (1 - 0.05 * Math.cos(a)), 36, 1, 0.96, r * 0.72, -r * 0.06))
      .fill(f(0xd9a959)).stroke({ width: lw, color: line })
    if (!white) {
      g.ellipse(0, r * 0.24, r * 0.5, r * 0.2).fill({ color: 0x7d5518, alpha: 0.24 })
      g.ellipse(-r * 0.1, -r * 0.22, r * 0.42, r * 0.14).fill({ color: mix(0xd9a959, 0xffffff, 0.5), alpha: 0.16 })
      g.beginPath() // breast barring — hairline chevrons, the owl's texture
      for (const t of [0.35, 0.5, 0.65]) {
        const [x] = bSpine(t)
        g.moveTo(x - r * 0.1, -r * 0.24).lineTo(x, -r * 0.06).lineTo(x - r * 0.1, r * 0.12)
      }
      g.stroke({ width: 1.1, color: 0x8a5d1e, alpha: 0.5 })
      // facial disc: a pale heart-shaped mask, the one light accent, carrying both eyes
      g.poly(radialOutline((a) => r * 0.34 * (1 + 0.14 * Math.cos(a * 2)), 32, 1, 1, r * 0.76, -r * 0.04))
        .fill({ color: 0xf2dcae, alpha: 0.85 })
      for (const s of [-1, 1]) darkEye(g, r * 0.78, s * r * 0.17, r * 0.11, r * 0.11, 0x120c05, true)
    }
    taperStroke(g, [[r * 0.94, -r * 0.02], [r * 1.16, r * 0.1]], r * 0.09, 0.8, f(0x3a2a10)) // beak (silhouette)
    if (elite) eliteCrown(-r * 1.62, r)
  }
  // centipede: top-down forest-floor predator — ONE tapered trunk (spineOutline) carrying an
  // S-undulation (sine in the spine) so it reads sinuous, not a stick; 16 tergite segments over a
  // LONG (~4.4r) body, ONE short leg pair per segment drawn on BOTH sides (for s of [-1,1] ->
  // symmetric about the forward axis, which is why lean 90 works), the pairs raking in a
  // metachronal wave. Head at +x with long forward antennae and prominent forward FORCIPULES (the
  // venom pincer-claws that curve inward to a point — the read that makes it a hunter, not a worm),
  // plus twin longer anal legs trailing the rear. Warm rust-amber body (0xdb7b3c, ~3.06x on the
  // loam — above the rat's 2.8x) with a dark rim.
  // ANIMATED: the 4th arg `phase` shifts the spine's sine; ROSTER_LOOKS declares `phases: 6`, so
  // makeRosterLook bakes 6 wave positions and syncEnemies flips through them — the wave travels
  // head -> tail and the centipede SLITHERS. Everything derives from spine(t), so one parameter
  // moves the outline, legs, creases and keel together.
  function drawCentipede(g, elite, white, phase = 0) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x5e2e18)
    const fang = f(0x47230f)
    const lw = Math.max(2, r * 0.13)
    const frontX = r * 1.05
    const len = r * 4.4 // trunk front +1.05r -> rounded tail -3.35r: LONG, like the real thing
    const undA = r * 0.28
    // S-undulation: ~1.3 full sine cycles along the length, offset by `phase`. The whole drawing
    // (outline, legs, creases, keel) derives from this one spine, so shifting the phase slithers
    // everything coherently — makeRosterLook bakes several phases and syncEnemies flips through
    // them, making the wave TRAVEL down the body. Minus phase => crests move head -> tail, which
    // reads as the body pushing backward against the ground (forward locomotion).
    // With >= a full cycle in view, some crest is always near max, so getLocalBounds is phase-
    // invariant and the frames don't jitter against each other.
    const spine = (t) => [frontX - t * len, Math.sin(t * Math.PI * 2.6 - phase) * undA]
    // near-uniform worm width, closing to a rounded (not pointed) rear; the anal legs give the point
    const body = (t) => r * 0.4 * bulge(0.05 + 0.9 * t, 0.4)
    groundShadow(r * 2.6, r * 0.2) // long ellipse — the centipede is long along x
    // legs first, so the trunk overlaps their roots and they read as attaching underneath.
    const N = 16
    for (let i = 0; i < N; i++) {
      const t = 0.08 + 0.84 * (i / (N - 1))
      const [x, y] = spine(t)
      const w = body(t)
      const ph = Math.sin(i * 0.9 - phase)      // metachronal wave, rowing with the slither
      const reach = 1 + 0.16 * Math.sin(t * Math.PI) // mid-body legs a touch longer
      for (const s of [-1, 1]) {
        const base = [x, y + s * w * 0.6]
        const knee = [x - r * 0.12 + ph * r * 0.06, y + s * (w + r * 0.26 * reach)]
        const foot = [x - r * 0.26 + ph * r * 0.12, y + s * (w + r * 0.46 * reach)]
        taperStroke(g, [base, knee, foot], r * 0.09, r * 0.028, line)
      }
    }
    // twin anal legs: longer, trailing back and out off the tail — a centipede signature
    const [tx, ty] = spine(0.99)
    for (const s of [-1, 1]) {
      taperStroke(g, [[tx, ty + s * r * 0.1], [tx - r * 0.3, ty + s * r * 0.32], [tx - r * 0.58, ty + s * r * 0.46]], r * 0.1, r * 0.03, line)
    }
    // antennae: long, forward and out — the furthest +x reach (sets the nose bound)
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 1.3, s * r * 0.12], [r * 1.7, s * r * 0.3], [r * 2.02, s * r * 0.22]], r * 0.09, r * 0.03, line)
    }
    // forcipules: forward venom claws that curve INWARD to a point (tips converge on the midline)
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 1.24, s * r * 0.22], [r * 1.54, s * r * 0.26], [r * 1.72, s * r * 0.05]], r * 0.11, r * 0.03, fang)
    }
    // trunk: one flowing tapered outline over the legs
    g.poly(spineOutline(spine, body, 44)).fill(f(0xdb7b3c)).stroke({ width: lw, color: line })
    // head: an egg that narrows toward the front, overlapping the trunk's front
    g.poly(radialOutline((a) => r * 0.32 * (1 - 0.12 * Math.cos(a)), 36, 1, 0.92, r * 1.18, 0))
      .fill(f(0xdb7b3c)).stroke({ width: lw, color: line })
    if (!white) {
      // darker dorsal keel-ribbon, riding the same undulating spine (well inside the outline)
      g.poly(spineOutline(spine, (t) => body(t) * 0.3, 30)).fill({ color: 0x8f3f1a, alpha: 0.4 })
      g.ellipse(-r * 0.9, r * 0.02, r * 1.9, r * 0.18).fill({ color: 0x5e2e18, alpha: 0.16 }) // low flank shadow
      g.beginPath()
      for (let i = 0; i < N; i++) { // hairline tergite creases at each segment, following the wiggle
        const t = 0.12 + 0.8 * (i / (N - 1))
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x + r * 0.02, y - w * 0.85).lineTo(x - r * 0.02, y + w * 0.85)
      }
      g.stroke({ width: 1, color: 0x5e2e18, alpha: 0.5 })
      g.ellipse(r * 1.24, -r * 0.12, r * 0.16, r * 0.09).fill({ color: mix(0xdb7b3c, 0xffffff, 0.5), alpha: 0.2 }) // head sheen
      for (const s of [-1, 1]) darkEye(g, r * 1.3, s * r * 0.16, r * 0.06, r * 0.06, 0x1a0d05, true) // small ocelli
    }
    if (elite) eliteCrown(-r * 0.9, r)
  }
  // rat: nose to rump is ONE tapered path (fat over the hips, closing to a pointed snout on the
  // right) with a long NAKED tail — the tail is the silhouette read, so it's a separate S-curved
  // taper that keeps narrowing all the way to a whip tip, and it carries hairline scale rings
  // instead of fur.
  function drawRat(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x413533)
    const lw = Math.max(2.2, r * 0.13)
    const snoutX = r * 1.05
    const len = r * 1.85 // snout +1.05r -> rump -0.8r
    const spine = (t) => [snoutX - t * len, -r * 0.04 + Math.sin(t * Math.PI * 0.9) * r * 0.06]
    // snout cap on the right closes to a near-point; the mass sits over the hips at t~0.7
    const body = (t) => {
      const cap = bulge(0.04 + 0.94 * t, t < 0.4 ? 1.1 : 0.42)
      return r * 0.56 * cap * (1 + 0.22 * Math.exp(-Math.pow((t - 0.72) / 0.26, 2)))
    }
    groundShadow(r * 1.05, r * 0.72)
    // tail: an S that keeps tapering to a whip tip — three joints, drawn before the body
    const tail = [[-r * 0.72, r * 0.04], [-r * 1.3, -r * 0.14], [-r * 1.85, r * 0.16], [-r * 2.3, -r * 0.02]]
    taperStroke(g, tail, r * 0.15, r * 0.035, f(0xc2a49c), 5)
    // legs: hind gathered under the hips, fore short and forward — real joints, far side darker
    const far = white ? 0xffffff : 0x6b5a56
    taperStroke(g, [[-r * 0.42, r * 0.24], [-r * 0.24, r * 0.52], [-r * 0.44, r * 0.7]], r * 0.11, r * 0.04, far)
    taperStroke(g, [[r * 0.36, r * 0.2], [r * 0.42, r * 0.48], [r * 0.56, r * 0.62]], r * 0.1, r * 0.035, far)
    g.poly(spineOutline(spine, body, 34)).fill(f(0x9b8a86)).stroke({ width: lw, color: line })
    taperStroke(g, [[-r * 0.34, r * 0.26], [-r * 0.1, r * 0.58], [-r * 0.34, r * 0.8], [-r * 0.06, r * 0.86]], r * 0.13, r * 0.045, f(0x8d7d79))
    taperStroke(g, [[r * 0.44, r * 0.22], [r * 0.5, r * 0.54], [r * 0.66, r * 0.7]], r * 0.12, r * 0.04, f(0x8d7d79))
    // ears: big thin rounded discs, the near one larger — a rat's ears are half its head
    g.poly(radialOutline((a) => r * 0.26, 24, 1, 1, r * 0.24, -r * 0.5)).fill(f(0x9b8a86)).stroke({ width: lw * 0.7, color: line })
    g.poly(radialOutline((a) => r * 0.2, 24, 1, 1, r * 0.44, -r * 0.42)).fill(f(0x9b8a86)).stroke({ width: lw * 0.7, color: line })
    if (!white) {
      g.ellipse(-r * 0.2, r * 0.24, r * 0.6, r * 0.2).fill({ color: 0x4e4240, alpha: 0.24 })
      g.ellipse(-r * 0.3, -r * 0.26, r * 0.5, r * 0.14).fill({ color: mix(0x9b8a86, 0xffffff, 0.5), alpha: 0.16 })
      g.circle(r * 0.24, -r * 0.5, r * 0.15).fill({ color: 0xc99a96, alpha: 0.75 }) // inner ear
      g.beginPath()
      for (let i = 0; i < 5; i++) { // tail scale rings — hairline, the "naked tail" cue
        const t = 0.2 + i * 0.18
        const a = tail[0]
        const x = lerp(-r * 0.9, -r * 2.2, t)
        g.moveTo(x, -r * 0.16 + Math.sin(t * 4) * r * 0.1).lineTo(x + r * 0.04, r * 0.16 + Math.sin(t * 4) * r * 0.1)
      }
      g.stroke({ width: 1, color: 0x8a6c66, alpha: 0.45 })
      g.beginPath() // guard-hair tufts along the back
      for (const t of [0.45, 0.6, 0.75]) {
        const [x, y] = spine(t)
        const w = body(t)
        g.moveTo(x, y - w * 0.85).lineTo(x - r * 0.06, y - w * 1.1)
      }
      g.stroke({ width: 1.1, color: 0x6b5a56, alpha: 0.55 })
      g.ellipse(r * 1.0, r * 0.02, r * 0.07, r * 0.06).fill({ color: 0xd0a0a0, alpha: 0.9 }) // nose
      darkEye(g, r * 0.6, -r * 0.16, r * 0.09, r * 0.085, 0x160f0e, true)
    }
    // whiskers reach past the snout — silhouette, not detail: same geometry in both variants
    g.beginPath()
    for (const s of [-1, 1]) g.moveTo(r * 0.98, r * 0.04).lineTo(r * 1.5, r * 0.04 + s * r * 0.24)
    g.stroke({ width: 1, color: white ? 0xffffff : 0xd8ccc8, alpha: white ? 1 : 0.45 })
    if (elite) eliteCrown(-r * 0.6, r)
  }

  // --- City chapter (cold concrete) ---
  // The city floor is a dim neutral grey (bg 0x2c2f38 under floorTint 0x9aa0ac → ~0x585c5c,
  // luminance ~0.11). Everything here is a MACHINE or a city animal, so no creature eyes: lenses,
  // sensors and beaks instead. Value ladder (a grey floor gives no hue to hide behind, so value is
  // doing all the work):
  //   vacuum   = LIGHTEST (white appliance plastic, 5.6x)
  //   ratDrone = MID      (safety-amber chassis, 3.6x)
  //   pigeon   = DIMMEST  (slate blue-grey, 2.8x)
  //
  // vacuum: a disc robot in 3/4 — the silhouette is ONE closed loop (the top ellipse's upper arc,
  // then the same ellipse's lower arc dropped by the shell height), which is what draws a real
  // cylinder rather than two stacked ovals. Bumper band, sensor turret with a dark lens, panel
  // seams and rivets as hairline detail.
  function drawVacuum(g, elite, white, phase = 0) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x5c5f66)
    const lw = Math.max(2.6, r * 0.1)
    const rx = r * 0.92
    const ry = r * 0.44
    const hgt = r * 0.34
    // one continuous shell loop: over the top, down the right wall, back under, up the left wall
    const shell = () => {
      const p = []
      for (let i = 0; i <= 30; i++) { const a = Math.PI + (i / 30) * Math.PI; p.push(Math.cos(a) * rx, Math.sin(a) * ry) }
      for (let i = 0; i <= 30; i++) { const a = (i / 30) * Math.PI; p.push(Math.cos(a) * rx, Math.sin(a) * ry + hgt) }
      return p
    }
    groundShadow(r * 1.05, ry + hgt + r * 0.14)
    // caster wheel peeking under the front rim (same geometry in both variants)
    g.ellipse(r * 0.5, ry + hgt * 0.9, r * 0.12, r * 0.09).fill(f(0x3f434a))
    g.poly(shell()).fill(f(0xe9eaec)).stroke({ width: lw, color: line })
    if (!white) {
      // volume: the wall in shadow under the lit top face — a cylinder, not a sticker
      g.poly(shell()).fill({ color: 0x000000, alpha: 0 })
      g.ellipse(0, hgt * 0.5, rx * 0.99, ry * 0.62).fill({ color: 0x6f747c, alpha: 0.2 })
      g.ellipse(0, 0, rx, ry).fill(0xdfe1e4).stroke({ width: 1.6, color: 0xa8adb5, alpha: 0.8 }) // top face
      g.ellipse(-r * 0.18, -r * 0.14, rx * 0.6, ry * 0.42).fill({ color: 0xffffff, alpha: 0.5 })  // dorsal sheen
      // bumper band: a slice of the shell's own lower wall, so it wraps with the curve
      const bump = []
      for (let i = 0; i <= 24; i++) { const a = (i / 24) * Math.PI; bump.push(Math.cos(a) * rx, Math.sin(a) * ry + hgt * 0.22) }
      for (let i = 24; i >= 0; i--) { const a = (i / 24) * Math.PI; bump.push(Math.cos(a) * rx, Math.sin(a) * ry + hgt) }
      g.poly(bump).fill({ color: 0x4a4e55, alpha: 0.85 })
      g.beginPath() // panel seams across the top face — hairline, reads as moulding
      g.ellipse(0, 0, rx * 0.72, ry * 0.72).stroke({ width: 1.2, color: 0xa8adb5, alpha: 0.7 })
      g.ellipse(0, 0, rx * 0.3, ry * 0.3).stroke({ width: 1.2, color: 0xa8adb5, alpha: 0.55 })
      for (let i = 0; i < 8; i++) { // rivets around the rim
        const a = (i / 8) * Math.PI * 2
        g.circle(Math.cos(a) * rx * 0.86, Math.sin(a) * ry * 0.86, 1.3).fill({ color: 0x8f959d, alpha: 0.8 })
      }
      // sensor turret + lens: the "face" a machine is allowed — a dark lens with one specular
      g.ellipse(r * 0.34, -r * 0.06, r * 0.2, r * 0.13).fill(0xc4c8cd).stroke({ width: 1.4, color: 0x8f959d })
      darkEye(g, r * 0.36, -r * 0.07, r * 0.1, r * 0.07, 0x14171c, true)
      g.rect(-r * 0.3, hgt * 0.62, r * 0.6, r * 0.09).fill({ color: 0x2f333a, alpha: 0.8 }) // brush slot
      // police light bar (v5.6.14, user: "police roombas"): twin domes on a dark base amidships,
      // ALTERNATING red/blue via the baked-phase mechanism (phases: 2 in ROSTER_LOOKS — the
      // centipede's slither machinery; syncEnemies strobes the two frames at ~10 flips/s). The
      // lit side gets a soft halo; halos sit well inside the shell, so bounds stay phase-invariant.
      const lit = phase >= Math.PI // phase 0 = red side on, phase pi = blue side on
      const lamp = (x, col, on) => {
        g.circle(x, -r * 0.3, r * 0.11).fill({ color: col, alpha: on ? 1 : 0.35 })
        if (on) g.circle(x, -r * 0.3, r * 0.24).fill({ color: col, alpha: 0.22 }) // glow halo
      }
      g.roundRect(-r * 0.3, -r * 0.36, r * 0.6, r * 0.14, r * 0.05).fill({ color: 0x2f333a, alpha: 0.9 })
      lamp(-r * 0.16, 0xff3040, !lit)
      lamp(r * 0.16, 0x2f7bff, lit)
    }
    if (elite) eliteCrown(-ry - r * 0.06, r)
  }
  // ratDrone: a quadrotor — small hard chassis, four arms that TAPER out to motor pods (real joints:
  // each arm elbows once), spinning rotors as low-alpha discs (solid on the white twin, the wasp-wing
  // trick, so bounds match), a forward sensor lens, and the rat-catcher's cage slung underneath.
  function drawRatDrone(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x6b4a10)
    const lw = Math.max(2, r * 0.12)
    groundShadow(r * 1.05, r * 0.86)
    // arms + pods first, so the chassis overlaps their roots. Front pair reaches further forward.
    const arms = [[r * 1.05, -r * 0.86], [r * 0.95, r * 0.8], [-r * 0.86, -r * 0.78], [-r * 0.8, r * 0.72]]
    for (const [px, py] of arms) {
      const ex = px * 0.45
      const ey = py * 0.62 // the elbow: arms kink, they don't sweep
      taperStroke(g, [[ex * 0.3, ey * 0.3], [ex, ey], [px, py]], r * 0.16, r * 0.08, f(0xc98f2a), 3)
      g.circle(px, py, r * 0.14).fill(f(0xa8741f)).stroke({ width: 1.4, color: line })
    }
    for (const [px, py] of arms) { // rotor discs: the blur of a blade, not a blade
      g.ellipse(px, py, r * 0.42, r * 0.4).fill(white ? 0xffffff : { color: 0xf6e3b4, alpha: 0.3 })
        .stroke({ width: 1, color: white ? 0xffffff : 0xf6e3b4, alpha: white ? 1 : 0.45 })
    }
    // chassis: a hard tapered wedge, nose right — a machine reads by its straightness
    const cSpine = (t) => [-r * 0.58 + t * r * 1.28, 0]
    const cW = (t) => r * 0.4 * (0.55 + 0.45 * bulge(Math.pow(t, 0.7), 1.3))
    g.poly(spineOutline(cSpine, cW, 22)).fill(f(0xf2b13c)).stroke({ width: lw, color: line })
    if (!white) {
      g.ellipse(0, r * 0.16, r * 0.5, r * 0.14).fill({ color: 0x8a6210, alpha: 0.24 })
      g.ellipse(-r * 0.06, -r * 0.16, r * 0.42, r * 0.1).fill({ color: mix(0xf2b13c, 0xffffff, 0.5), alpha: 0.2 })
      g.beginPath() // panel lines along the chassis — hairline
      g.moveTo(-r * 0.44, -r * 0.1).lineTo(r * 0.5, -r * 0.1)
      g.moveTo(-r * 0.44, r * 0.1).lineTo(r * 0.5, r * 0.1)
      g.stroke({ width: 1, color: 0x8a6210, alpha: 0.5 })
      g.rect(-r * 0.3, -r * 0.12, r * 0.26, r * 0.24).fill({ color: 0x2f2a1c, alpha: 0.7 }) // battery bay
      // cage: the rat-catcher's business end, slung under the nose
      g.beginPath()
      g.moveTo(r * 0.2, r * 0.16).lineTo(r * 0.2, r * 0.5).lineTo(r * 0.7, r * 0.5).lineTo(r * 0.7, r * 0.14)
      for (const cx of [r * 0.33, r * 0.46, r * 0.58]) g.moveTo(cx, r * 0.18).lineTo(cx, r * 0.5)
      g.stroke({ width: 1.2, color: 0x5c4a28, alpha: 0.85 })
      // forward sensor lens (no eyes — it's a drone)
      g.circle(r * 0.62, 0, r * 0.14).fill(0x9c6f1c)
      darkEye(g, r * 0.62, 0, r * 0.09, r * 0.09, 0x12100a, true)
      g.circle(-r * 0.5, 0, r * 0.05).fill({ color: 0xff4d5e, alpha: 0.9 }) // tail beacon
    }
    if (elite) eliteCrown(-r * 1.28, r)
  }
  // pigeon: a plump city bird in profile facing right — ONE outline that swells over the crop and
  // closes into a wedge tail on the left, a folded wing sitting inside it with hairline covert
  // edges, and the iridescent neck patch (the only saturated thing on it) as a two-pass shimmer.
  function drawPigeon(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x3f4a57)
    const lw = Math.max(1.9, r * 0.13)
    groundShadow(r * 1.0, r * 0.92)
    // feet: two small jointed grabs, drawn before the body so the tarsi tuck under it
    for (const s of [0, 1]) {
      const ox = s ? r * 0.42 : r * 0.16
      taperStroke(g, [[ox, r * 0.42], [ox + r * 0.04, r * 0.72], [ox + r * 0.2, r * 0.8]], r * 0.09, r * 0.035, f(0xd98a6a))
      taperStroke(g, [[ox + r * 0.04, r * 0.72], [ox - r * 0.14, r * 0.8]], r * 0.06, 0.7, f(0xd98a6a), 2)
    }
    // tail: a wedge of rectrices off the rear, tapering to a squared-off fan
    const tSpine = (t) => [-r * 0.5 - t * r * 0.9, t * r * 0.12]
    g.poly(spineOutline(tSpine, (t) => r * 0.3 * (1 - 0.45 * t), 12)).fill(f(0x7b90a6)).stroke({ width: lw * 0.7, color: line })
    // body: fat over the crop (front), closing toward the tail — a pigeon is front-heavy
    const bSpine = (t) => [r * 0.62 - t * r * 1.24, -r * 0.06 + t * r * 0.1]
    const body = (t) => r * 0.56 * bulge(0.16 + 0.74 * t, 0.55) * (1 + 0.16 * Math.exp(-Math.pow((t - 0.24) / 0.3, 2)))
    g.poly(spineOutline(bSpine, body, 28)).fill(f(0x8fa8bf)).stroke({ width: lw, color: line })
    // head + neck: one small blunt taper rising forward-right off the crop
    const hSpine = (t) => [r * 0.44 + t * r * 0.62, -r * 0.36 - t * r * 0.28]
    g.poly(spineOutline(hSpine, (t) => r * 0.3 * bulge(0.3 + 0.65 * t, 0.6), 16)).fill(f(0x8fa8bf)).stroke({ width: lw * 0.8, color: line })
    g.poly(radialOutline((a) => r * 0.28, 28, 1, 0.96, r * 0.98, -r * 0.62)).fill(f(0x8fa8bf)).stroke({ width: lw * 0.8, color: line })
    taperStroke(g, [[r * 1.16, -r * 0.6], [r * 1.5, -r * 0.5]], r * 0.1, r * 0.03, f(0x4a4a52)) // beak
    if (!white) {
      g.ellipse(-r * 0.1, r * 0.24, r * 0.5, r * 0.2).fill({ color: 0x4f6070, alpha: 0.26 })
      g.ellipse(-r * 0.06, -r * 0.3, r * 0.42, r * 0.14).fill({ color: mix(0x8fa8bf, 0xffffff, 0.5), alpha: 0.18 })
      // folded wing: a lanceolate plate riding the body's own profile, with covert hairlines
      const wg = []
      for (let i = 0; i <= 20; i++) { const t = 0.14 + 0.66 * (i / 20); const [x, y] = bSpine(t); wg.push(x, y + body(t) * 0.1) }
      for (let i = 20; i >= 0; i--) { const t = 0.14 + 0.66 * (i / 20); const [x, y] = bSpine(t); wg.push(x, y + body(t) * 0.86) }
      g.poly(wg).fill({ color: 0x6d829a, alpha: 0.9 })
      g.beginPath()
      for (const t of [0.3, 0.45, 0.6, 0.75]) {
        const [x, y] = bSpine(t)
        g.moveTo(x, y + body(t) * 0.18).lineTo(x - r * 0.08, y + body(t) * 0.8)
      }
      g.stroke({ width: 1, color: 0x46586b, alpha: 0.6 })
      g.beginPath() // the two dark wing bars every city pigeon has
      for (const t of [0.36, 0.52]) {
        const [x, y] = bSpine(t)
        g.moveTo(x + r * 0.02, y + body(t) * 0.22).lineTo(x - r * 0.06, y + body(t) * 0.82)
      }
      g.stroke({ width: 2.2, color: 0x36414e, alpha: 0.8 })
      // iridescent neck: two low-alpha passes (green over violet) on the throat only
      g.poly(spineOutline(hSpine, (t) => r * 0.3 * bulge(0.3 + 0.65 * t, 0.6) * 0.9, 12, 0.05, 0.8))
        .fill({ color: 0x3fd08a, alpha: 0.5 })
      g.poly(spineOutline(hSpine, (t) => r * 0.3 * bulge(0.3 + 0.65 * t, 0.6) * 0.55, 12, 0.3, 0.95))
        .fill({ color: 0xa06cf0, alpha: 0.45 })
      // pigeon eye: orange iris ring + dark pupil (a bird's eye, no sclera)
      g.circle(r * 1.06, -r * 0.66, r * 0.1).fill(0xf2913a)
      darkEye(g, r * 1.06, -r * 0.66, r * 0.05, r * 0.05, 0x140c06, true)
      g.circle(r * 1.2, -r * 0.56, r * 0.05).fill({ color: 0xe8e2d8, alpha: 0.8 }) // cere
    }
    if (elite) eliteCrown(-r * 0.98, r)
  }

  // --- Skies chapter (night thunderstorm) ---
  // v5.6.17: the skies floor FLIPPED DARK for the storm redesign: bg 0x2a3240 under floorTint
  // 0x717c88 → effective floor luminance ~0.07 (was ~0.38 pre-flip). That inverts the rule this
  // section used to run on — light military greys would now vanish, so every machine goes LIGHT,
  // spread across the same contrast multiples as before (just mirrored: light-on-dark, not
  // dark-on-light) so the three stay tellable apart by hue + silhouette, not just value:
  //   jet        = BRIGHTEST (pale steel-blue gunmetal, 4.8x)
  //   helicopter = MID       (bright olive drab, 3.5x)
  //   tankColumn = DIMMEST of the three (pale khaki/tan, still 2.2-4.0x across its parts)
  //
  // jet: top-down, nose right — fuselage is ONE spine tapering from a needle nose to the exhaust,
  // and the delta wings are real polygons with a swept leading edge meeting a straight trailing edge
  // at a hard angle (a fighter's read is its ANGLES; anything rounded looks like a toy).
  function drawJet(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x14181e)
    const lw = Math.max(1.8, r * 0.11)
    groundShadow(r * 1.1, r * 1.0)
    // delta wings: leading edge sweeps back from the shoulder, trailing edge runs straight across
    for (const s of [-1, 1]) {
      const sc = s < 0 ? 1 : 0.94 // a hair of asymmetry so it never reads as a stencil
      g.poly([
        r * 0.5, s * r * 0.16,
        -r * 0.32, s * r * 1.34 * sc,
        -r * 0.72, s * r * 1.3 * sc,
        -r * 0.66, s * r * 0.2,
      ]).fill(f(0xb6c4d2)).stroke({ width: lw * 0.8, color: line })
    }
    for (const s of [-1, 1]) { // tailplanes: the same wedge, smaller, further aft
      g.poly([-r * 0.7, s * r * 0.16, -r * 1.14, s * r * 0.66, -r * 1.32, s * r * 0.6, -r * 1.22, s * r * 0.14])
        .fill(f(0xb6c4d2)).stroke({ width: lw * 0.7, color: line })
    }
    // fuselage: needle nose right, tapering back to a blunt exhaust
    const spine = (t) => [r * 1.5 - t * r * 2.9, 0]
    const body = (t) => r * 0.3 * bulge(0.02 + 0.9 * t, t < 0.35 ? 1.4 : 0.4)
    g.poly(spineOutline(spine, body, 30)).fill(f(0xb6c4d2)).stroke({ width: lw, color: line })
    if (!white) {
      g.ellipse(-r * 0.2, r * 0.12, r * 0.7, r * 0.12).fill({ color: 0x0e1116, alpha: 0.3 })
      g.ellipse(-r * 0.2, -r * 0.1, r * 0.7, r * 0.08).fill({ color: 0x7d8b9c, alpha: 0.22 }) // dorsal sheen
      g.beginPath() // panel lines + wing spars — hairline, the whole "military hardware" texture
      g.moveTo(r * 0.9, 0).lineTo(-r * 1.2, 0)
      for (const s of [-1, 1]) {
        g.moveTo(r * 0.36, s * r * 0.18).lineTo(-r * 0.4, s * r * 1.1)
        g.moveTo(-r * 0.16, s * r * 0.2).lineTo(-r * 0.5, s * r * 1.16)
      }
      g.stroke({ width: 1, color: 0x6b7684, alpha: 0.45 })
      for (const s of [-1, 1]) { // intakes
        g.ellipse(r * 0.24, s * r * 0.26, r * 0.16, r * 0.08).fill({ color: 0x0b0e12, alpha: 0.9 })
      }
      // canopy: a glass bubble, the one bright specular on the whole airframe
      g.poly(radialOutline((a) => r * 0.2 * (1 - 0.3 * Math.cos(a)), 24, 1, 0.7, r * 0.62, 0)).fill(0x1d2b3a)
      g.ellipse(r * 0.68, -r * 0.05, r * 0.11, r * 0.05).fill({ color: 0x9fd8ff, alpha: 0.75 })
      g.ellipse(-r * 1.3, 0, r * 0.09, r * 0.14).fill({ color: 0xff8c42, alpha: 0.55 }) // afterburner
      for (const s of [-1, 1]) { // roundels
        g.circle(-r * 0.34, s * r * 0.62, r * 0.09).fill({ color: 0xd94d4d, alpha: 0.7 })
      }
    }
    if (elite) eliteCrown(-r * 1.36, r)
  }
  // helicopter: top-down, nose right — a fat cockpit tapering into a long thin tail boom is ONE
  // profile (that length ratio IS the helicopter read), with the rotor as a big low-alpha disc
  // implying spin over it. The disc is drawn solid on the white twin (wasp-wing trick) since it
  // sets the bounds, and two blade streaks inside it keep it from reading as a bubble.
  function drawHelicopter(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const line = f(0x1c2216)
    const lw = Math.max(2, r * 0.11)
    groundShadow(r * 1.1, r * 1.05)
    // tail fin + tail rotor, drawn first so the boom overlaps their roots
    g.poly([-r * 1.32, -r * 0.1, -r * 1.62, -r * 0.44, -r * 1.72, -r * 0.1, -r * 1.6, r * 0.12])
      .fill(f(0x9cae66)).stroke({ width: lw * 0.7, color: line })
    g.ellipse(-r * 1.62, -r * 0.28, r * 0.1, r * 0.34).fill(white ? 0xffffff : { color: 0xc4d0b4, alpha: 0.35 })
    for (const s of [-1, 1]) { // skids: two straight rails, offset — not a smooth arc
      g.rect(-r * 0.5, s * r * 0.46 - r * 0.04, r * 1.16, r * 0.08).fill(f(0x333c2b))
      taperStroke(g, [[r * 0.3, s * r * 0.2], [r * 0.34, s * r * 0.44]], r * 0.07, r * 0.05, f(0x333c2b), 2)
      taperStroke(g, [[-r * 0.3, s * r * 0.2], [-r * 0.34, s * r * 0.44]], r * 0.07, r * 0.05, f(0x333c2b), 2)
    }
    // fuselage: bulbous cockpit right, closing into a slender boom left — one continuous taper
    const spine = (t) => [r * 0.98 - t * r * 2.3, 0]
    const body = (t) => {
      const cab = 0.52 * Math.exp(-Math.pow((t - 0.14) / 0.24, 2))
      const boom = 0.12 * Math.pow(Math.max(0, 1 - t), 0.5)
      return r * bulge(0.04 + 0.9 * t, 0.7) * (cab + boom)
    }
    g.poly(spineOutline(spine, body, 34)).fill(f(0x9cae66)).stroke({ width: lw, color: line })
    if (!white) {
      g.ellipse(r * 0.3, r * 0.2, r * 0.5, r * 0.14).fill({ color: 0x232b1b, alpha: 0.3 })
      g.ellipse(r * 0.3, -r * 0.2, r * 0.44, r * 0.1).fill({ color: 0x93a37f, alpha: 0.22 })
      g.beginPath() // boom frames + door seam
      g.moveTo(-r * 0.4, 0).lineTo(-r * 1.3, 0)
      for (const x of [-r * 0.6, -r * 0.9, -r * 1.15]) g.moveTo(x, -r * 0.14).lineTo(x, r * 0.14)
      g.moveTo(r * 0.24, -r * 0.44).lineTo(r * 0.24, r * 0.44)
      g.stroke({ width: 1, color: 0x8d9c79, alpha: 0.45 })
      g.poly(radialOutline((a) => r * 0.3 * (1 - 0.28 * Math.cos(a)), 24, 1, 0.86, r * 0.78, 0)).fill(0x1f2c33) // canopy glass
      g.ellipse(r * 0.84, -r * 0.08, r * 0.14, r * 0.07).fill({ color: 0x9fd8ff, alpha: 0.7 })
      g.circle(r * 0.2, 0, r * 0.1).fill({ color: 0x2a3320, alpha: 0.8 }) // rotor mast head
    }
    // rotor disc LAST: the blur sits over everything it turns above. It sets the bounds, so the rim
    // stroke has to exist in BOTH variants (solid on the twin) — the wasp-wing rule.
    g.ellipse(r * 0.2, 0, r * 1.34, r * 1.26).fill(white ? 0xffffff : { color: 0xdfe8d2, alpha: 0.22 })
      .stroke({ width: 1.2, color: white ? 0xffffff : 0xdfe8d2, alpha: white ? 1 : 0.4 })
    if (!white) {
      g.beginPath() // two blade smears inside the disc — spin, not a bubble
      for (const a of [0.5, 2.6]) {
        g.moveTo(r * 0.2 - Math.cos(a) * r * 1.28, -Math.sin(a) * r * 1.2)
        g.lineTo(r * 0.2 + Math.cos(a) * r * 1.28, Math.sin(a) * r * 1.2)
      }
      g.stroke({ width: 1.5, color: 0xeef4e6, alpha: 0.3 })
    }
    if (elite) eliteCrown(-r * 1.3, r)
  }
  // tankColumn: 3/4 from the front-right — a sloped hull whose glacis, roof and rear are ONE
  // outline (a tank is a faceted box; the silhouette must have real corners, so this is a poly with
  // deliberate angles, not a sin profile), riding a track band with road wheels, turret and a
  // tapered gun barrel with a muzzle brake pointing right.
  function drawTankColumn(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x2b2718)
    const lw = Math.max(2.6, r * 0.1)
    groundShadow(r * 1.15, r * 0.78)
    // track band: a slab with rounded ends (idler + drive sprocket), the whole thing sits low
    const trk = []
    for (let i = 0; i <= 16; i++) { const a = -Math.PI / 2 + (i / 16) * Math.PI; trk.push(r * 0.86 + Math.cos(a) * r * 0.24, r * 0.44 + Math.sin(a) * r * 0.24) }
    for (let i = 0; i <= 16; i++) { const a = Math.PI / 2 + (i / 16) * Math.PI; trk.push(-r * 0.86 + Math.cos(a) * r * 0.24, r * 0.44 + Math.sin(a) * r * 0.24) }
    g.poly(trk).fill(f(0x8a7f5e)).stroke({ width: lw * 0.8, color: line })
    // hull: hard facets — sloped glacis on the right, flat roof, cut-back rear
    g.poly([
      r * 1.02, r * 0.3, r * 0.62, -r * 0.16, // glacis slope
      r * 0.34, -r * 0.28, -r * 0.72, -r * 0.28, // roof
      -r * 0.98, r * 0.04, -r * 0.98, r * 0.34, // rear plate
    ]).fill(f(0xb3a374)).stroke({ width: lw, color: line })
    // turret: a squat faceted mass, offset back from the glacis
    g.poly([
      r * 0.42, -r * 0.3, r * 0.26, -r * 0.66, -r * 0.28, -r * 0.72,
      -r * 0.52, -r * 0.5, -r * 0.5, -r * 0.3,
    ]).fill(f(0xc2b183)).stroke({ width: lw, color: line })
    // gun: a long taper to a muzzle brake — the reach IS the threat read
    taperStroke(g, [[r * 0.2, -r * 0.5], [r * 1.5, -r * 0.5]], r * 0.1, r * 0.07, f(0x998a5f), 4)
    g.rect(r * 1.42, -r * 0.6, r * 0.18, r * 0.2).fill(f(0x998a5f)).stroke({ width: 1.4, color: line })
    if (!white) {
      g.poly([r * 1.02, r * 0.3, r * 0.62, -r * 0.16, r * 0.34, -r * 0.28, -r * 0.72, -r * 0.28, -r * 0.98, r * 0.04, -r * 0.98, r * 0.34])
        .fill({ color: 0x000000, alpha: 0 })
      g.rect(-r * 0.98, r * 0.1, r * 2.0, r * 0.24).fill({ color: 0x3b3423, alpha: 0.3 }) // hull in shadow, low
      g.beginPath()
      g.moveTo(r * 0.62, -r * 0.16).lineTo(-r * 0.72, -r * 0.16)
      g.stroke({ width: 2, color: 0xa2966d, alpha: 0.25 }) // lit roof edge
      // road wheels + track links: hairline, the detail that sells "tracks"
      for (let i = 0; i < 5; i++) {
        const x = -r * 0.72 + i * r * 0.36
        g.circle(x, r * 0.44, r * 0.12).fill({ color: 0x2b2718, alpha: 0.55 })
        g.circle(x, r * 0.44, r * 0.05).fill({ color: 0xc2b183, alpha: 0.5 })
      }
      g.beginPath()
      for (let i = 0; i < 14; i++) {
        const x = -r * 1.08 + i * r * 0.16
        g.moveTo(x, r * 0.2).lineTo(x, r * 0.68)
      }
      g.stroke({ width: 1, color: 0x1f1c11, alpha: 0.4 })
      g.beginPath() // turret + hull panel seams
      g.moveTo(r * 0.26, -r * 0.62).lineTo(-r * 0.26, -r * 0.66)
      g.moveTo(-r * 0.5, -r * 0.34).lineTo(-r * 0.28, -r * 0.68)
      g.stroke({ width: 1.2, color: 0x9a8f66, alpha: 0.4 })
      for (const [rx, ry] of [[r * 0.5, -r * 0.24], [-r * 0.6, -r * 0.22], [-r * 0.9, r * 0.1]]) {
        g.circle(rx, ry, 1.4).fill({ color: 0x9a8f66, alpha: 0.55 }) // rivets
      }
      // vision block: a dark glass slit, a machine's "eye"
      g.rect(r * 0.28, -r * 0.56, r * 0.14, r * 0.07).fill(0x141208)
      g.rect(r * 0.29, -r * 0.555, r * 0.05, r * 0.02).fill({ color: 0x9fd8ff, alpha: 0.6 })
      g.circle(-r * 0.36, -r * 0.68, r * 0.05).fill({ color: 0x8a7f5e, alpha: 0.9 }) // hatch periscope
    }
    if (elite) eliteCrown(-r * 0.76, r)
  }

  // --- Beyond chapter (violet void) ---
  // The beyond floor is the DARKEST of all seven: bg 0x120a26 under floorTint 0x6a5fa0 → ~0x362d4e,
  // luminance ~0.03. Everything here therefore GLOWS — these are the brightest bodies in the game
  // (7-9x), which is also what makes them survive the eliteIridescent multiply: the pale hues mix
  // 50% to white before tinting, so the worst-case channel factor is ~0.87 and no body here leans on
  // a channel that could be crushed to mud.
  //   blinker    = BRIGHTEST (cyan glitch, 9.1x)
  //   swarmDrone = MID       (amber, 7.0x)
  //   flicker    = DIMMEST   (violet, 5.2x — it is the one that's half-there)
  //
  // blinker: a form that cannot hold still — a faceted crystal (hard angular radius, jittered per
  // vertex by the deterministic hash so it's irregular but stable) with two GHOST ECHOES offset
  // fore/aft of it, drawn solid on the white twin so bounds match. The echoes are the whole idea:
  // you see where it just was and where it's about to be.
  function drawBlinker(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const line = f(0x1d6e8c)
    const N = 9
    // faceted radius: a hard polygon, each vertex kicked out/in by a stable hash — never a circle
    const facet = (k) => {
      const p = []
      for (let i = 0; i < N; i++) {
        const a = (i / N) * Math.PI * 2 - 0.2
        const rad = r * 0.76 * k * (0.74 + hash(i * 7.13 + 2.9) * 0.5)
        p.push(Math.cos(a) * rad, Math.sin(a) * rad * 0.92)
      }
      return p
    }
    groundShadow(r * 0.95, r * 0.86)
    // ghost echoes: the same crystal displaced, low-alpha (solid on the twin so bounds hold)
    for (const [ox, oy, al] of [[-r * 0.34, r * 0.08, 0.3], [r * 0.3, -r * 0.06, 0.22]]) {
      const e = facet(0.94)
      for (let i = 0; i < e.length; i += 2) { e[i] += ox; e[i + 1] += oy }
      // the echoes set the bounds, so their rim is stroked in BOTH variants (wasp-wing rule)
      g.poly(e).fill(white ? 0xffffff : { color: 0x7fe8ff, alpha: al })
        .stroke({ width: 1.4, color: white ? 0xffffff : 0xbff4ff, alpha: white ? 1 : al * 0.9 })
    }
    g.poly(facet(1)).fill(f(0x7fe8ff)).stroke({ width: Math.max(2.6, r * 0.11), color: line })
    if (!white) {
      g.poly(facet(1)).fill({ color: 0x1d6e8c, alpha: 0 })
      g.ellipse(r * 0.04, r * 0.28, r * 0.5, r * 0.26).fill({ color: 0x1d6e8c, alpha: 0.24 })
      g.ellipse(-r * 0.1, -r * 0.28, r * 0.42, r * 0.2).fill({ color: 0xdcfaff, alpha: 0.3 })
      g.beginPath() // internal facet edges from the core to each vertex — a crystal, not a blob
      const p = facet(1)
      for (let i = 0; i < N; i++) {
        g.moveTo(0, 0).lineTo(p[i * 2] * 0.94, p[i * 2 + 1] * 0.94)
      }
      g.stroke({ width: 1.1, color: 0x2f8fb0, alpha: 0.45 })
      g.poly(facet(0.34)).fill({ color: 0xeafdff, alpha: 0.9 }) // core
      g.poly(facet(0.16)).fill({ color: 0xffffff, alpha: 0.95 })
      g.beginPath() // scan bars: the glitch tell
      for (const y of [-r * 0.4, -r * 0.06, r * 0.3]) g.moveTo(-r * 0.66, y).lineTo(r * 0.66, y)
      g.stroke({ width: 1.4, color: 0xdcfaff, alpha: 0.3 })
    }
    if (elite) eliteCrown(-r * 0.76, r)
  }
  // flicker: a shape that is only half here. ONE soft membrane, but the LEADING (right) half is
  // solid while the trailing half is a low-alpha wash cut by hairline scan gaps — it reads as a form
  // resolving out of the void rather than a translucent ball. The whole outline (both halves) is
  // drawn in the white twin so bounds match; sim's _phaseSolid drives the sprite alpha on top.
  function drawFlicker(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const membrane = (a) => r * 0.86 * (0.9 + 0.09 * Math.cos(a * 2 + 0.7) + 0.05 * Math.sin(a * 5 - 1.1))
    groundShadow(r * 0.9, r * 0.9)
    // full silhouette: on the twin it's solid white; on the normal it's the faint "not-there" wash.
    // The rim is stroked in BOTH variants — it's what sets the bounds (wasp-wing rule).
    g.poly(radialOutline(membrane, 48, 1, 0.94)).fill(white ? 0xffffff : { color: 0xb894f5, alpha: 0.3 })
      .stroke({ width: 1.6, color: white ? 0xffffff : 0xd9c0ff, alpha: white ? 1 : 0.4 })
    if (!white) {
      // the solid half: the same membrane, sampled only over the leading arc, closed back through
      // the center — same curve, so the "materialised" edge is unmistakably part of one form. Inset
      // to 0.95 so its heavier stroke still lands inside the full membrane's rim.
      const half = []
      for (let i = 0; i <= 24; i++) {
        const a = -Math.PI / 2 + (i / 24) * Math.PI
        const rad = membrane(a) * 0.95
        half.push(Math.cos(a) * rad, Math.sin(a) * rad * 0.94)
      }
      g.poly(half).fill({ color: 0xb894f5, alpha: 0.95 })
      g.poly(half).stroke({ width: 2.4, color: 0x6f4fa8, alpha: 0.9 })
      g.ellipse(r * 0.3, r * 0.28, r * 0.34, r * 0.2).fill({ color: 0x5e3f96, alpha: 0.3 })
      g.ellipse(r * 0.24, -r * 0.3, r * 0.3, r * 0.16).fill({ color: 0xf0e2ff, alpha: 0.35 })
      g.beginPath() // scan gaps: hairline slices missing out of the form
      for (let i = 0; i < 6; i++) {
        const y = -r * 0.66 + i * r * 0.26
        g.moveTo(-r * 0.76, y).lineTo(r * 0.76, y)
      }
      g.stroke({ width: 1.2, color: 0x1c0f33, alpha: 0.4 })
      // core: the part that is always real, and the one place it has an eye
      g.poly(radialOutline((a) => membrane(a) * 0.3, 24, 1, 1, r * 0.24, 0)).fill({ color: 0xf6ecff, alpha: 0.9 })
      darkEye(g, r * 0.3, 0, r * 0.11, r * 0.13, 0x1a0b33, true)
    }
    if (elite) eliteCrown(-r * 0.82, r)
  }
  // swarmDrone: small, sharp, many-eyed — a dart-shaped chitin wedge (hard poly, nose right) with
  // spines raking backward off it and a cluster of seven lenses on the leading face. Everything
  // about it is a point: at 24px it should read as an arrowhead coming at you.
  // invader (v5.18, The Beyond's lane): the Space Invaders half. Seen almost exclusively IN RANK —
  // six abreast, marching down the lane — so it is authored for the block, not the close-up. That
  // means one hard, symmetrical silhouette with a wide flat shoulder line: six of these side by side
  // read as a WALL with gaps in it, which is the only thing the player actually needs to see. A
  // rounded or busy shape would blur into the neighbouring columns at rank spacing.
  // Nose at +x like every other look here (ROSTER_LOOKS lean rotates it to travel).
  function drawInvader(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x2a1a52)
    const lw = Math.max(1.8, r * 0.12)
    groundShadow(r * 0.9, r * 0.8)
    // two down-swept mandibles, drawn first so their roots hide under the hull
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 0.1, s * r * 0.55], [r * 0.85, s * r * 0.95], [r * 1.1, s * r * 0.6]],
        r * 0.17, 0.55, f(0x7f6adf), 3)
    }
    // hull: a flat-shouldered hexagon — the wide ±y edge is what makes a rank read as a line
    g.poly([
      r * 1.0, 0, r * 0.45, -r * 0.85, -r * 0.55, -r * 0.85,
      -r * 0.95, 0, -r * 0.55, r * 0.85, r * 0.45, r * 0.85,
    ]).fill(f(0xa78bfa)).stroke({ width: lw, color: line })
    if (!white) {
      // lit from the star side (-y): a pale crown and a shadowed belly, same one-light rule the
      // planets use, so every object in the chapter agrees about where the sun is
      g.poly([r * 1.0, 0, r * 0.45, -r * 0.85, -r * 0.55, -r * 0.85, -r * 0.95, 0])
        .fill({ color: 0xe4dcff, alpha: 0.26 })
      g.poly([r * 1.0, 0, r * 0.45, r * 0.85, -r * 0.55, r * 0.85, -r * 0.95, 0])
        .fill({ color: 0x3d2a7a, alpha: 0.3 })
      // a single wide eye band — one bright horizontal slot, legible at rank distance
      g.roundRect(r * 0.05, -r * 0.3, r * 0.6, r * 0.6, r * 0.16).fill(f(0x1a1030))
      g.roundRect(r * 0.16, -r * 0.19, r * 0.34, r * 0.38, r * 0.1).fill(0x6ff0ff)
      g.circle(r * 0.3, -r * 0.06, r * 0.09).fill({ color: 0xffffff, alpha: 0.85 })
    }
  }

  // hulk (v5.18): the rank's anchor. Same silhouette language as the invader so they read as one
  // army, but slab-sided and plated — it is the column you route AROUND rather than through.
  function drawHulk(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x241546)
    const lw = Math.max(2, r * 0.14)
    groundShadow(r * 1.05, r * 0.95)
    // shoulder plates, outboard, squared off
    for (const s of [-1, 1]) {
      g.poly([r * 0.15, s * r * 0.7, r * 0.8, s * r * 0.85, r * 0.7, s * r * 1.15, -r * 0.1, s * r * 1.0])
        .fill(f(0x6b5ab8)).stroke({ width: lw * 0.8, color: line })
    }
    // slab hull — blunter and squarer than the invader's, no taper to the nose
    g.poly([
      r * 0.95, -r * 0.5, r * 0.95, r * 0.5, r * 0.2, r * 0.95,
      -r * 0.9, r * 0.8, -r * 0.9, -r * 0.8, r * 0.2, -r * 0.95,
    ]).fill(f(0x8b79d6)).stroke({ width: lw, color: line })
    if (!white) {
      g.poly([r * 0.95, -r * 0.5, r * 0.2, -r * 0.95, -r * 0.9, -r * 0.8, -r * 0.9, 0, r * 0.95, 0])
        .fill({ color: 0xe4dcff, alpha: 0.2 })
      g.poly([r * 0.95, r * 0.5, r * 0.2, r * 0.95, -r * 0.9, r * 0.8, -r * 0.9, 0, r * 0.95, 0])
        .fill({ color: 0x2f1f63, alpha: 0.34 })
      // armour seams
      g.beginPath()
      for (const s of [-1, 1]) g.moveTo(r * 0.7, s * r * 0.3).lineTo(-r * 0.7, s * r * 0.5)
      g.stroke({ width: 1.2, color: 0x2a1a52, alpha: 0.5 })
      // two narrow slit eyes — meaner than the invader's single band
      for (const s of [-1, 1]) {
        g.roundRect(r * 0.3, s * r * 0.34 - r * 0.11, r * 0.42, r * 0.22, r * 0.08).fill(f(0x140b26))
        g.roundRect(r * 0.36, s * r * 0.34 - r * 0.06, r * 0.28, r * 0.12, r * 0.05).fill(0xff8a5c)
      }
    }
  }

  function drawSwarmDrone(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const line = f(0x8a4a08)
    const lw = Math.max(1.8, r * 0.12)
    groundShadow(r * 0.95, r * 0.72)
    // spines: raked back, unequal — drawn first so their roots vanish under the wedge
    for (const [a, len] of [[2.5, 0.95], [3.0, 1.2], [3.5, 0.9], [2.1, 0.7], [3.9, 0.75], [4.5, 0.5], [1.7, 0.45]]) {
      taperStroke(g, [[Math.cos(a) * r * 0.3, Math.sin(a) * r * 0.3], [Math.cos(a) * r * len, Math.sin(a) * r * len]],
        r * 0.14, 0.7, f(0xd98a1e), 3)
    }
    // wedge: a hard dart — nose, two swept shoulders, a notched tail
    g.poly([
      r * 1.15, 0, r * 0.1, -r * 0.62, -r * 0.5, -r * 0.5,
      -r * 0.28, 0, -r * 0.5, r * 0.5, r * 0.1, r * 0.62,
    ]).fill(f(0xffb03d)).stroke({ width: lw, color: line })
    if (!white) {
      g.poly([r * 1.15, 0, r * 0.1, r * 0.62, -r * 0.5, r * 0.5, -r * 0.28, 0]).fill({ color: 0x9c5a0c, alpha: 0.28 })
      g.poly([r * 1.15, 0, r * 0.1, -r * 0.62, -r * 0.5, -r * 0.5, -r * 0.28, 0]).fill({ color: 0xffe6b0, alpha: 0.22 })
      g.beginPath() // carapace ridges — hairline, raked like the spines
      for (const s of [-1, 1]) {
        g.moveTo(r * 0.86, s * r * 0.08).lineTo(-r * 0.16, s * r * 0.4)
        g.moveTo(r * 0.6, s * r * 0.06).lineTo(-r * 0.3, s * r * 0.24)
      }
      g.stroke({ width: 1, color: 0x8a4a08, alpha: 0.5 })
      // seven lenses, two ranks, biggest forward — many-eyed, no sclera, one specular each
      for (const [ex, ey, er] of [[0.72, 0, 0.13], [0.5, -0.19, 0.1], [0.5, 0.19, 0.1],
        [0.26, -0.3, 0.075], [0.26, 0.3, 0.075], [0.06, -0.18, 0.06], [0.06, 0.18, 0.06]]) {
        darkEye(g, r * ex, r * ey, r * er, r * er, 0x2b0f02, er > 0.07)
      }
    }
    if (elite) eliteCrown(-r * 0.66, r)
  }

  // ---- The Blank (v5.24, hidden final chapter) — authored for WHITE -----------------------------
  // Every roster above sells its silhouette against a DARK floor with a saturated fill; the void's
  // floor IS near-white, so these four invert the recipe: warm-white bodies a hair off the
  // background, carried entirely by their gray-lavender EDGE, interior detail in the chapter ink.
  // Values shadow CHAPTERS.blank.render (bg 0xf2efe8 / ink 0x4a4458) — bakes run once at boot,
  // before any chapter latch, so they are literals here like every other draw fn's palette.
  const VOID_BODY = 0xfbfaf6
  const VOID_EDGE = 0x8880a8
  const VOID_INK = 0x4a4458

  // probe: the trail-sniffer (pastSeek — it hunts where you WERE). A slim dart aimed +x with one
  // wide reading lens; its tail carries echo ticks trailing -x, fading like the trail it follows.
  function drawProbe(g, elite, white) {
    const r = 12
    const f = (c) => white ? 0xffffff : c
    const lw = Math.max(2.2, r * 0.18)
    groundShadow(r * 0.85, r * 0.75)
    // echo ticks behind — solid on the twin (they set the -x bounds; wasp-wing rule)
    for (let i = 0; i < 3; i++) {
      const h = r * (0.6 - i * 0.14)
      g.roundRect(-r * (0.92 + i * 0.45), -h / 2, r * 0.24, h, r * 0.1)
        .fill(white ? 0xffffff : { color: VOID_EDGE, alpha: 0.5 - i * 0.13 })
    }
    // body: hard tapered dart, nose +x
    g.poly([r * 1.05, 0, r * 0.3, -r * 0.55, -r * 0.55, -r * 0.4, -r * 0.72, 0, -r * 0.55, r * 0.4, r * 0.3, r * 0.55])
      .fill(f(VOID_BODY)).stroke({ width: lw, color: f(VOID_EDGE) })
    if (!white) {
      g.poly([r * 1.05, 0, r * 0.3, r * 0.55, -r * 0.55, r * 0.4, -r * 0.72, 0]).fill({ color: VOID_EDGE, alpha: 0.16 })
      darkEye(g, r * 0.42, 0, r * 0.24, r * 0.2, VOID_INK, true) // the one wide reading lens
    }
    if (elite) eliteCrown(-r * 0.62, r)
  }

  // binder: the latcher (P2's preview). A rounded pale cell with two open grappler hooks reaching
  // +x — the gap between them is aimed at you. Hooks in a ±y pair, so it rotates freely (lean 90).
  function drawBinder(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    const lw = Math.max(2.4, r * 0.15)
    groundShadow(r * 0.95, r * 0.9)
    // grappler hooks first — their roots hide under the membrane
    for (const s of [-1, 1]) {
      taperStroke(g, [[r * 0.3, s * r * 0.55], [r * 0.95, s * r * 0.6], [r * 1.25, s * r * 0.2]],
        r * 0.17, r * 0.08, f(VOID_EDGE), 4)
    }
    // membrane body: soft 3-lobe wobble, never a clean circle
    g.poly(radialOutline((a) => r * (0.86 + 0.05 * Math.cos(a * 3 + 0.8))))
      .fill(f(VOID_BODY)).stroke({ width: lw, color: f(VOID_EDGE) })
    if (!white) {
      g.ellipse(0, r * 0.32, r * 0.52, r * 0.26).fill({ color: VOID_EDGE, alpha: 0.14 })
      g.circle(-r * 0.08, -r * 0.05, r * 0.3).fill({ color: VOID_EDGE, alpha: 0.4 }) // binding core
      g.circle(-r * 0.08, -r * 0.05, r * 0.13).fill({ color: VOID_INK, alpha: 0.6 })
    }
    if (elite) eliteCrown(-r * 0.92, r)
  }

  // eraser: the slow wake-layer (P3's preview). A blunt slab pushed flat-face-first (+x) like a
  // squeegee — the leading edge is the darkest line on it, the rear feathers into pale streaks.
  function drawEraser(g, elite, white) {
    const r = 26
    const f = (c) => white ? 0xffffff : c
    const lw = Math.max(3, r * 0.12)
    groundShadow(r * 1.0, r * 0.9)
    // feathered wake streaks behind — solid on the twin (they set the -x bounds)
    for (const [y, len] of [[-0.5, 0.5], [0, 0.72], [0.5, 0.5]]) {
      g.roundRect(-r * (0.85 + len), r * y - r * 0.09, r * len, r * 0.18, r * 0.09)
        .fill(white ? 0xffffff : { color: VOID_EDGE, alpha: 0.4 })
    }
    // slab: flat leading face at +x, rounded rear corners
    g.roundRect(-r * 0.85, -r * 0.8, r * 1.7, r * 1.6, r * 0.28)
      .fill(f(VOID_BODY)).stroke({ width: lw, color: f(VOID_EDGE) })
    // the hard leading edge — the part that erases
    g.roundRect(r * 0.55, -r * 0.78, r * 0.3, r * 1.56, r * 0.12).fill(f(VOID_EDGE))
    if (!white) {
      g.roundRect(r * 0.63, -r * 0.64, r * 0.12, r * 1.28, r * 0.06).fill({ color: VOID_INK, alpha: 0.5 })
      g.ellipse(-r * 0.1, r * 0.45, r * 0.6, r * 0.26).fill({ color: VOID_EDGE, alpha: 0.16 })
      g.beginPath() // seam lines across the slab — a machined block, not a creature with a face
      for (const y of [-0.35, 0, 0.35]) g.moveTo(-r * 0.6, r * y).lineTo(r * 0.45, r * y)
      g.stroke({ width: 1.4, color: VOID_EDGE, alpha: 0.45 })
    }
    if (elite) eliteCrown(-r * 0.85, r)
  }

  // bindnode: the P2 anchor. Stationary (speedMul 0) — no heading, no face: a pale knot in an open
  // collar with three filament stubs radiating. The live filament to the player is bindG's job
  // (syncBinds); the yank countdown (e._bindT) is told there, not here.
  function drawBindnode(g, elite, white) {
    const r = 16
    const f = (c) => white ? 0xffffff : c
    groundShadow(r * 0.8, r * 0.7)
    for (let i = 0; i < 3; i++) { // filament stubs
      const a = -Math.PI / 2 + (i / 3) * Math.PI * 2
      taperStroke(g, [[Math.cos(a) * r * 0.5, Math.sin(a) * r * 0.5], [Math.cos(a) * r * 1.15, Math.sin(a) * r * 1.15]],
        r * 0.13, r * 0.05, f(VOID_EDGE), 3)
    }
    g.circle(0, 0, r * 0.8).fill(f(VOID_BODY)).stroke({ width: Math.max(2.4, r * 0.16), color: f(VOID_EDGE) })
    if (!white) {
      g.circle(0, 0, r * 0.52).stroke({ width: 1.6, color: VOID_EDGE, alpha: 0.6 })
      g.circle(0, 0, r * 0.28).fill({ color: 0x8a5fe0, alpha: 0.55 }) // violet core: the thing holding YOU
      g.circle(0, 0, r * 0.12).fill({ color: VOID_INK, alpha: 0.7 })
    }
    if (elite) eliteCrown(-r * 0.8, r)
  }

  // The Antibody (archetype 'boss', baked at local r = BLANK_BOSS_R): reality's immune response —
  // chapter 1's immunoglobulin Y grown to arena scale, three near-equal lobes in true 3-fold
  // symmetry about the hinge so the slow look.spin rotation (syncEnemies) turns it about its own
  // centre. One draw fn, three script stages of escalating menace bound by the ROSTER_LOOKS
  // wrappers: stage 2 grows spurs off every lobe, stage 3 sharpens the tips into blades and the
  // core goes dark ink — the same silhouette reassembling angrier, never a different monster.
  function drawTheAntibody(g, elite, white, stage) {
    const r = BLANK_BOSS_R
    const f = (c) => white ? 0xffffff : c
    groundShadow(r * 0.85, r * 0.55)
    // stem down + two arms up, exactly 2pi/3 apart; hair of length asymmetry keeps it organic
    // without moving the mass off the hinge (rotation must not wobble)
    const limbs = [
      [Math.PI * 0.5, r * 1.0], [Math.PI * 0.5 + Math.PI * 2 / 3, r * 0.98], [Math.PI * 0.5 + Math.PI * 4 / 3, r * 0.99],
    ]
    const lw = Math.max(4, r * 0.05) + stage * 1.5
    // hinge mass under the union — fills the notches out into a grabbing claw, not a thin letter
    g.circle(0, 0, r * 0.42).fill(f(VOID_BODY)).stroke({ width: lw, color: f(VOID_EDGE) })
    const pts = []
    for (const [th, len] of limbs) {
      const ux = Math.cos(th), uy = Math.sin(th)
      const nx = -uy, ny = ux
      const wH = r * 0.34, wT = r * (stage >= 3 ? 0.16 : 0.24) // stage 3 tapers toward a blade
      const bx = -ux * r * 0.05, by = -uy * r * 0.05
      const ex = ux * len, ey = uy * len
      pts.push(bx - nx * wH, by - ny * wH)
      if (stage >= 3) {
        // bladed tip: a hard point past the cap instead of the rounded lobe
        pts.push(ex - nx * wT, ey - ny * wT, ex + ux * r * 0.2, ey + uy * r * 0.2, ex + nx * wT, ey + ny * wT)
      } else {
        for (let i = 0; i <= 6; i++) { // rounded lobe cap
          const a = th - Math.PI * 0.5 + (i / 6) * Math.PI
          pts.push(ex + Math.cos(a) * wT, ey + Math.sin(a) * wT)
        }
      }
      pts.push(bx + nx * wH, by + ny * wH)
    }
    g.poly(pts).fill(f(VOID_BODY)).stroke({ width: lw, color: f(VOID_EDGE) })
    if (stage >= 2) {
      // spurs off both edges of every lobe — solid on the twin (they extend the bounds)
      for (const [th, len] of limbs) {
        const ux = Math.cos(th), uy = Math.sin(th)
        const nx = -uy, ny = ux
        for (const s of [-1, 1]) {
          const sx = ux * len * 0.58 + nx * s * r * 0.31
          const sy = uy * len * 0.58 + ny * s * r * 0.31
          g.poly([sx - ux * r * 0.09, sy - uy * r * 0.09,
            sx + nx * s * r * 0.17 + ux * r * 0.04, sy + ny * s * r * 0.17 + uy * r * 0.04,
            sx + ux * r * 0.11, sy + uy * r * 0.11]).fill(f(VOID_EDGE))
        }
      }
    }
    if (!white) {
      for (const [th, len] of limbs) { // a crease from the core into each lobe — reads as a joint
        g.beginPath().moveTo(Math.cos(th) * r * 0.24, Math.sin(th) * r * 0.24)
          .lineTo(Math.cos(th) * len * 0.8, Math.sin(th) * len * 0.8)
          .stroke({ width: 2.2, color: VOID_EDGE, alpha: 0.5, cap: 'round' })
      }
      // the core darkens as the stages escalate — the one dial that says "angrier" up close
      g.circle(0, 0, r * 0.3).stroke({ width: 2.5, color: VOID_EDGE, alpha: 0.7 })
      g.circle(0, 0, r * 0.2).fill({ color: stage >= 3 ? VOID_INK : VOID_EDGE, alpha: 0.3 + stage * 0.16 })
      g.circle(0, 0, r * 0.09).fill({ color: VOID_INK, alpha: 0.45 + stage * 0.15 })
      if (stage >= 3) {
        g.beginPath() // desperation cracks radiating off the core
        for (let i = 0; i < 6; i++) {
          const a = i * (Math.PI / 3) + 0.4
          g.moveTo(Math.cos(a) * r * 0.22, Math.sin(a) * r * 0.22)
            .lineTo(Math.cos(a + 0.18) * r * 0.52, Math.sin(a + 0.18) * r * 0.52)
        }
        g.stroke({ width: 2, color: VOID_INK, alpha: 0.55 })
      }
    }
  }

  // `lean` = MAX LEAN IN DEGREES, 0..90: how far off horizontal this creature may aim its +x nose
  // at the player (syncEnemies mirrors it left/right on top of that, so lean+flip spans the circle).
  // The number falls straight out of the VIEW the art is drawn in, so judge it from the geometry:
  //   90 = TRUE TOP-DOWN. Bilaterally symmetric about the forward axis — appendages on both sides
  //        (`for (const s of [-1, 1])`), eyes in ±y pairs — so there is no "up" to lose. Rotates freely.
  //   30 = 3/4 or PROFILE. There is a distinct UP in the drawing (ears/roof at -y, every leg/track at
  //        +y), and rotating one past vertical lands it upside down with its legs in the air. It leans
  //        toward the player and mirrors, like it did before v5.6.4, but it never tips over.
  //    0 = NO FORWARD AXIS. Discs, cells, vertical cylinders. Rotating them isn't "facing", it's
  //        tumbling — and these are the ones whose art also violates the nose-at-+x contract.
  const ROSTER_LOOKS = {
    redcell: { archetype: 'normal', draw: drawRedcell, lean: 0 },      // biconcave disc, no forward axis — it would just tumble
    wbc: { archetype: 'tank', draw: drawWbc, lean: 0 },                // radial membrane, filopodia all round; no nose
    antibody: { archetype: 'fast', draw: drawAntibody, lean: 0 },      // 3-fold Y (Fc stem at +y), no +x front — a protein has no heading
    amoeba: { archetype: 'normal', draw: drawAmoeba, lean: 0 },        // radial blob, pseudopods in 4 directions; no nose
    tadpole: { archetype: 'fast', draw: drawTadpole, lean: 90 },       // top-down: nose +x, tail -x, lateral eyes in a ±y pair
    tardigrade: { archetype: 'tank', draw: drawTardigrade, lean: 30 }, // 3/4: all 7 legs at +y, eyespot at -y
    // v7.x The Shelf (Book 2). Replaces the pond ids this chapter was standing in with; every flag
    // is inherited unchanged, so these three are a repaint of amoeba/tadpole/tardigrade and not a
    // re-tune. A missing key here is SILENT — syncEnemies falls through to a generic archetype blob.
    copepod: { archetype: 'normal', draw: drawCopepod, lean: 90 },     // top-down: antennae, legs, setae and egg sacs all ±y mirrored
    krill: { archetype: 'fast', draw: drawKrill, lean: 90 },           // top-down: stalked eyes, leg rows and tail fan all ±y mirrored
    // side elevation: apex +x, mouth and tentacles -x, mirrored about that axis — so it rotates
    // freely and always swims bell-first at you, tentacles streaming behind. See drawJelly.
    jelly: { archetype: 'tank', draw: drawJelly, lean: 90 },
    // v7.x The Reef (Book 2 chapter 3). All three PLAN VIEW, all three lean 90 — and that is the
    // geometry, not a habit: each is bilaterally symmetric about its own +x nose, with paired eyes
    // and paired appendages in ±y and nothing in the drawing that could be called UP. (The moon
    // jelly above is the one side-elevation body in the game and it earns that by hanging in a water
    // column; these three are over the reef floor.) A missing key here is SILENT — syncEnemies falls
    // through to a generic archetype blob. See the Reef section of the draw fns for the palette.
    damselfish: { archetype: 'normal', draw: drawDamselfish, lean: 90 }, // top-down: barred spindle, pectorals and eyes in ±y pairs
    moray: { archetype: 'tank', draw: drawMoray, lean: 90, phases: 6 },  // top-down ribbon: jaws fork ±y, tail -x; 6 baked wave phases = the swim
    // Four POSES rather than phases, selected by the pounce state machine exactly as the toad's are
    // (see that entry): the pectoral fan is spread while it stalks, flared while it aims, FOLDED
    // FLAT while it is in the air, half-open as it lands. faceDir/turnRate keep it committed to the
    // heading the sim locked at the start of 'aim' — a body that steered mid-leap while its
    // trajectory did not is the bug v6.6.33 fixed on the toad, and it would return here for free.
    lionfish: {
      archetype: 'fast', draw: drawLionfish, lean: 90, poses: 4,
      poseOf: (e) => ({ hold: 0, aim: 1, leap: 2, land: 3 })[e._pounceState] ?? 0,
      faceDir: (e) => ((e._pounceState === 'aim' || e._pounceState === 'leap')
        ? [e._pounceDirX ?? 0, e._pounceDirY ?? 0] : null),
      turnRate: (e) => (e._pounceState === 'leap' ? POUNCE_TURN_LEAP
        : e._pounceState === 'aim' ? POUNCE_TURN_AIM : POUNCE_TURN_IDLE),
    },
    // v7.x The Trawl (Book 2 chapter 4). All three PLAN VIEW, all three lean 90, for the same reason
    // the Reef's three are: each is bilaterally symmetric about its own +x nose with paired eyes and
    // paired fins in ±y, and nothing in any of them could be called UP. A missing key here is
    // SILENT — syncEnemies falls through to a generic archetype blob. See the Trawl section of the
    // draw fns for why the tank is a mammal and the fast one is all outline.
    // v7.x The Deep (Book 2 chapter 5). Four, not three — the chapter needed a tank the spec's set
    // did not have (see CHAPTERS.deep's roster). All PLAN VIEW, all lean 90. The anglerfish's MOUTH
    // is not in its bake: the gape is per-fish and per-frame, so it is an overlay (drawDeepTells).
    anglerfish: { archetype: 'normal', draw: drawAnglerfish, lean: 90 }, // top-down: globe + lure on a stalk in -y, tooth ring at +x
    hagfish: { archetype: 'normal', draw: drawHagfish, lean: 90 },       // top-down: near-constant-width rope, slime pores in ±y rows
    viperfish: { archetype: 'fast', draw: drawViperfish, lean: 90 },     // top-down: thin ribbon, fangs past the snout, photophore rows
    gulper: { archetype: 'tank', draw: drawGulperEel, lean: 90 },        // top-down: open pouch at +x collapsing to a whip at -x
    mackerel: { archetype: 'normal', draw: drawMackerel, lean: 90 }, // top-down: barred spindle, forked tail -x, eyes in a ±y pair
    tuna: { archetype: 'fast', draw: drawTuna, lean: 90 },           // top-down: crescent tail, sickle pectorals and finlets all ±y mirrored
    sealion: { archetype: 'tank', draw: drawSeaLion, lean: 90 },     // top-down: fore-flippers thrown wide ±y, blunt head +x, hind flippers -x
    // v7.x The Surf (Book 2 chapter 1). A new roster, not a repaint — every flag here is new
    // (unshakeable, diveBomb) rather than carried over the way the Shelf's are. A missing key here
    // is SILENT — syncEnemies falls through to a generic archetype blob.
    // All three are PLAN VIEW: the water-column exception the jelly above takes (see CLAUDE.md)
    // is for animals that swim in open water with a bell-first heading. These three are on or over
    // the sand — two crawl and one flies above it — so the overhead camera is the honest one.
    sandhopper: { archetype: 'normal', draw: drawSandhopper, lean: 90 },
    searoach: { archetype: 'fast', draw: drawSeaRoach, lean: 90 },   // top-down: a flat many-legged sprinter, legs and antennae +/-y mirrored // top-down: antennae, legs and the long jump-uropods all ±y mirrored
    // TWO POSES, chosen by the sim's `guarding` field, not by a timer — the pose IS the state, and
    // a player who cannot see which one they are shooting is being asked to waste damage blind.
    // lean 90 (bilaterally symmetric about the forward axis) rather than the 0 this carried before:
    // 0 means "no forward axis, it would just tumble", and a crab that never rotates cannot show
    // WHICH SIDE its 120-degree guard is covering. It only ever swings while guarding — turnRate 0
    // freezes the held heading the rest of the time, so the squaring-up motion happens on the raise
    // and nowhere else (owner ruling: "it squares up only while guarding"), and an open crab
    // visibly stops tracking you as you move around it.
    shorecrab: {
      archetype: 'tank', draw: drawShorecrab, lean: 90, poses: 2,
      poseOf: (e) => (e.guarding ? 1 : 0),
      // The bearing the guard was RAISED at, held for that window — see stepCrabGuard. Guarded with
      // `!= null` rather than a truth test: angle 0 is a legal bearing (due east) and would
      // otherwise fall through to face-the-player on a quarter of all raises.
      faceDir: (e) => (e.guarding && e.guardAngle != null ? [Math.cos(e.guardAngle), Math.sin(e.guardAngle)] : null),
      turnRate: (e) => (e.guarding ? CRAB_SQUARE_UP_RATE : 0),
    },
    gull: { archetype: 'fast', draw: drawGull, lean: 90 },               // top-down: wings, wingtips and the forked tail all ±y mirrored
    ant: { archetype: 'normal', draw: drawAnt, lean: 90 },             // top-down: 6 legs, 2 antennae, 2 eyes, all ±y mirrored
    wasp: { archetype: 'fast', draw: drawWasp, lean: 90 },             // top-down: wings/legs/eyes all in ±y pairs
    spider: { archetype: 'tank', draw: drawSpider, lean: 90 },         // top-down: 8 legs + pedipalps + 8 eyes, all ±y mirrored
    // lean 90 (top-down — the whole animal turns to face you) and four baked POSES driven by the
    // pounce state machine rather than by a timer. `poseOf` is the only thing separating this from
    // `phases`: phases flip on animT (the centipede's slither), poses are SELECTED, so a toad
    // crouched to leap stays crouched for exactly as long as it is crouching. Unknown/absent state
    // falls to 0, which is also correct for one that has never pounced.
    toad: {
      archetype: 'tank', draw: drawToad, lean: 90, poses: 4,
      poseOf: (e) => ({ hold: 0, aim: 1, leap: 2, land: 3 })[e._pounceState] ?? 0,
      // v6.6.33 (owner: "when it leaps, it turns mid air towards the player: it shouldn't. It has
      // committed to a jump and should keep facing same direction during jump"). While aiming and
      // leaping the toad faces the heading the SIM locked at the start of 'aim' — the same vector
      // the telegraph is drawn along — instead of tracking the player. Before this the body steered
      // through the air while the trajectory did not, so the two disagreed on screen every leap.
      faceDir: (e) => ((e._pounceState === 'aim' || e._pounceState === 'leap')
        ? [e._pounceDirX ?? 0, e._pounceDirY ?? 0] : null),
      // ...and it swings round at a real rate rather than snapping. Fast enough during the wind-up
      // to finish aimed before launch (7 rad/s over a 0.9s aim is ample), ZERO in the air, and slow
      // once it lands — "toads are slow and tanky: when they land, they slowly turn towards the
      // player and build-up another leap" is this line plus POUNCE_LAND_T.
      turnRate: (e) => (e._pounceState === 'leap' ? POUNCE_TURN_LEAP
        : e._pounceState === 'aim' ? POUNCE_TURN_AIM : POUNCE_TURN_IDLE),
    },
    owl: { archetype: 'fast', draw: drawOwl, lean: 90 },               // PARKED (v5.6.8): aerialStrike is unkillable in a melee chapter — kept for a future ranged one
    centipede: { archetype: 'fast', draw: drawCentipede, lean: 90, phases: 6 }, // top-down, ±y mirrored; 6 baked wave phases = the slither
    rat: { archetype: 'normal', draw: drawRat, lean: 30 },             // 3/4: both ears at -y, every leg at +y
    // v6.6.28 removed the 'dartRat' key here with the roster entry it existed for (config.js,
    // undergrowth). A key with no roster entry is dead weight, not a safety net — the fallback runs
    // the other way (an entry with no key here silently renders as a generic archetype blob).
    vacuum: { archetype: 'tank', draw: drawVacuum, lean: 0, phases: 2 }, // vertical cylinder, never rotates; 2 phases strobe the police light bar
    ratDrone: { archetype: 'normal', draw: drawRatDrone, lean: 90 },   // top-down quadrotor: 4 arms + rotors in ±y pairs
    patrolDrone: { archetype: 'normal', draw: drawRatDrone, lean: 90 }, // v6.3: same quadrotor art, aerialStrike's ranged-chapter home
    pigeon: { archetype: 'fast', draw: drawPigeon, lean: 30 },         // profile: feet at +y, head raised at -y
    jet: { archetype: 'fast', draw: drawJet, lean: 90 },               // top-down: delta wings, tailplanes, intakes, roundels all ±y
    helicopter: { archetype: 'normal', draw: drawHelicopter, lean: 90 }, // top-down: skids ±y, rotor disc centred on the hub
    tankColumn: { archetype: 'tank', draw: drawTankColumn, lean: 20 }, // 3/4: roof/turret at -y, track band and road wheels at +y
    // v5.18 The Beyond. The chapter's roster ids changed (blinker/flicker -> the five below) and a
    // missing key here is SILENT — syncEnemies falls through to the generic archetype blob, so the
    // enemies simply render as Chapter 1's kawaii cells with no error anywhere. Every id in
    // CHAPTERS.beyond.roster must have an entry.
    // The two SEEKERS reuse the void art already authored for this chapter rather than adding more:
    // the crystal and the phantom were drawn for beyond and were orphaned by the roster change, so
    // they come back as the swarm half of the merge instead of being deleted and re-drawn.
    warden: { archetype: 'tank', draw: drawBlinker, lean: 90 },        // void crystal, no gravity-up
    drifter: { archetype: 'normal', draw: drawFlicker, lean: 90 },     // void phantom, no gravity-up
    // The two MARCHERS are new, and authored to be read in rank rather than close up.
    invader: { archetype: 'normal', draw: drawInvader, lean: 90 },     // flat-shouldered hex; a rank of six reads as one wall
    hulk: { archetype: 'tank', draw: drawHulk, lean: 90 },             // slab + shoulder plates; the column you route around
    swarmDrone: { archetype: 'fast', draw: drawSwarmDrone, lean: 90 }, // top-down dart: nose +x, spines raked back, 7 lenses in ±y ranks
    // v5.24 The Blank (hidden final chapter) — see the VOID_BODY draw-fn section's own header.
    // The three antibodies are the SAME boss reassembling per script stage (the wrappers bind the
    // stage). `spin` is a slow constant self-rotation in rad/s (syncEnemies) — radially symmetric
    // forms with lean 0 have no facing to fake, and it quickens as the phases escalate. `noElite`
    // skips the elite twin bake (buildTextures): the script only ever spawns forceNormal, and a
    // boss bake is a ~430px texture pair nothing could reach.
    probe: { archetype: 'fast', draw: drawProbe, lean: 90 },          // top-down dart: nose +x, echo ticks -x, ±y mirrored
    binder: { archetype: 'normal', draw: drawBinder, lean: 90 },      // top-down: grappler hooks in a ±y pair
    eraser: { archetype: 'tank', draw: drawEraser, lean: 90 },        // top-down slab: leading edge +x, wake streaks -x
    bindnode: { archetype: 'normal', draw: drawBindnode, lean: 0 },   // stationary anchor — no heading at all
    antibody1: { archetype: 'boss', draw: (g, e, w) => drawTheAntibody(g, e, w, 1), lean: 0, spin: 0.25, noElite: true },
    antibody2: { archetype: 'boss', draw: (g, e, w) => drawTheAntibody(g, e, w, 2), lean: 0, spin: 0.38, noElite: true },
    antibody3: { archetype: 'boss', draw: (g, e, w) => drawTheAntibody(g, e, w, 3), lean: 0, spin: 0.55, noElite: true },
  }
  const DEG = Math.PI / 180
  function makeRosterLook(id, elite) {
    const entry = ROSTER_LOOKS[id]
    shadowSpec = null
    crownSpec = null
    // A look is 1 frame unless the entry declares `phases: n` — then the draw fn takes a 4th
    // `phase` arg (0..2pi) and we bake n of them; syncEnemies flips through look.frames to animate
    // (the centipede's slither). Normal and white twins are baked PER PHASE from identical
    // geometry, so each frame keeps the hit-flash anchor parity on its own.
    const bakePhase = (phase) => {
      const g = new Graphics()
      entry.draw(g, elite, false, phase) // records shadowSpec/crownSpec on the way past
      const normal = bake(g)
      const w = new Graphics()
      entry.draw(w, elite, true, phase)
      const white = bake(w)
      return { tex: normal.tex, white: white.tex, ax: normal.ax, ay: normal.ay }
    }
    // `phases` bakes n frames at evenly spaced ANGLES and flips through them on animT (the
    // centipede's slither). `poses` bakes n frames and passes the plain INDEX, for a look whose
    // frame is chosen by state instead of by time — see poseOf below and in syncEnemies.
    const n = entry.poses ?? entry.phases ?? 1
    const frames = []
    for (let p = 0; p < n; p++) frames.push(bakePhase(entry.poses ? p : (p / n) * Math.PI * 2))
    return {
      tex: frames[0].tex, white: frames[0].white, ax: frames[0].ax, ay: frames[0].ay,
      frames: n > 1 ? frames : null,
      baseR: ROSTER_BASE_R[entry.archetype], maxLean: entry.lean * DEG,
      poseOf: entry.poseOf || null,
      // v6.6.33: these two MUST be forwarded. The baked look is a fresh object, not the ROSTER_LOOKS
      // entry, so a hook that is declared and not copied here is silently inert — syncEnemies reads
      // `look.faceDir`, finds undefined, and falls straight back to the old always-face-the-player
      // behaviour with no error anywhere. That is exactly how the first cut of the committed-leap
      // fix shipped as a no-op, and it was only caught by measuring the drawn heading.
      faceDir: entry.faceDir || null,
      turnRate: entry.turnRate || null,
      spin: entry.spin || 0,
      shadow: shadowSpec, crown: crownSpec,
    }
  }

  // Generic cute blob (title-screen ambience)
  function makeBlobTexture(fill, line, r) {
    const g = new Graphics()
    g.ellipse(0, 0, r, r * 0.9).fill(fill).stroke({ width: 3, color: line })
    const ex = r * 0.34
    const ey = -r * 0.12
    g.circle(-ex, ey, r * 0.2).fill(0xffffff)
    g.circle(ex, ey, r * 0.2).fill(0xffffff)
    g.circle(-ex, ey + r * 0.04, r * 0.1).fill(DARK)
    g.circle(ex, ey + r * 0.04, r * 0.1).fill(DARK)
    g.beginPath().arc(0, r * 0.22, r * 0.18, Math.PI * 0.15, Math.PI * 0.85).stroke({ width: 2, color: mix(line, 0x000000, 0.2), cap: 'round' })
    g.circle(-ex - r * 0.22, ey + r * 0.34, r * 0.11).fill({ color: 0xff9eb0, alpha: 0.5 })
    g.circle(ex + r * 0.22, ey + r * 0.34, r * 0.11).fill({ color: 0xff9eb0, alpha: 0.5 })
    return bake(g)
  }

  const T = {}
  // THE SHARPNESS KNOB. How much of the light's radius is fully lit before the falloff starts;
  // raise it and the transition from your light to the dark gets shorter and harder-edged.
  //
  // ONE const for two readers that must not drift: the bake's first ramp stop, and updateDark's
  // early-out (a fully-lit core that already reaches the farthest corner means there is nothing to
  // draw). Raising it therefore hardens the edge AND lets the layer switch off slightly earlier,
  // which is correct — both follow from the same fact about where the falloff starts.
  const LIGHT_CORE_FRAC = 0.62
  // The falloff's shape, as DARKNESS at evenly-spaced samples from the core out to the rim. Held as
  // a shape and positioned by LIGHT_CORE_FRAC so the sharpness knob moves where the ramp happens
  // without changing what it looks like — an eased ramp rather than a straight line, because a
  // linear one reads as a grey ring at its own midpoint (Mach banding: the eye finds the second
  // derivative) and the point of a falloff is that you cannot say where it starts.
  const DARK_RAMP = [0, 0.09, 0.36, 0.73, 1]
  // ---- lifted shadow + crown textures (see the groundShadow/eliteCrown note above) --------------
  // ONE shadow disc for the whole roster: a flat alpha fill with no stroke, so squashing it per
  // creature to (spec.rx, spec.ry) is exact — nothing to distort. Baked big (SHADOW_TEX_R) because
  // it gets scaled UP for the tanks.
  const SHADOW_TEX_R = 32
  // Crowns bake once per distinct `r` instead: the rim is a constant 1.5px in drawing space, so a
  // single scaled crown would thicken it on the big creatures and lose it on the small ones.
  const crownTexes = new Map() // r -> { tex, white, ax, ay }
  function crownLook(r) {
    let l = crownTexes.get(r)
    if (!l) {
      const g = new Graphics()
      crownPoly(g, r, false)
      const normal = bake(g)
      const w = new Graphics()
      crownPoly(w, r, true)
      const white = bake(w)
      l = { tex: normal.tex, white: white.tex, ax: normal.ax, ay: normal.ay }
      crownTexes.set(r, l)
    }
    return l
  }

  function buildTextures() {
    {
      const g = new Graphics()
      g.circle(0, 0, SHADOW_TEX_R).fill({ color: 0x000000, alpha: 0.12 })
      T.enemyShadow = bake(g)
    }

    T.enemies = {}
    for (const type of Object.keys(ENEMIES)) {
      T.enemies[type] = makeEnemyLook(type, false)
      T.enemies[type + '_elite'] = makeEnemyLook(type, true)
    }

    // Per-rosterId themed creature silhouettes (v5.4). Keyed by rosterId (+ '_elite'); syncEnemies
    // prefers these over the archetype T.enemies fallback whenever e.rosterId names one.
    T.roster = {}
    for (const id of Object.keys(ROSTER_LOOKS)) {
      T.roster[id] = makeRosterLook(id, false)
      // noElite (the blank's bosses): alias the elite key instead of baking a second giant twin
      // pair — the blank's script spawns everything forceNormal, so it's unreachable anyway
      T.roster[id + '_elite'] = ROSTER_LOOKS[id].noElite ? T.roster[id] : makeRosterLook(id, true)
    }

    // The gull STRIKE's three poses (The Surf). Baked at GULL_DIVE_R rather than reusing the 12px
    // roster gull: the strike is drawn ~140px across, and that texture would be a 6x magnification —
    // every edge visibly stepped. See stepGullDives for the beat these cycle on.
    //   0 stoop (wings folded, feet thrown forward)  1 downstroke (spread)  2 upstroke (foreshortened)
    T.gullDive = [[0.86, 0.62, true], [0, 1, false], [0, 0.56, false]].map(([sw, sp, feet]) => {
      const g = new Graphics()
      drawGullPose(g, GULL_DIVE_R, sw, sp, feet, false)
      return bake(g)
    })

    // player body (eye whites, blush, smile baked; pupils are live sprites)
    const pr = PLAYER.radius
    {
      const g = new Graphics()
      g.ellipse(0, 0, pr, pr * 0.91).fill(0x7de3c3).stroke({ width: 3.5, color: 0x3aa88a })
      g.circle(-pr * 0.36, -pr * 0.18, pr * 0.23).fill(0xffffff)
      g.circle(pr * 0.36, -pr * 0.18, pr * 0.23).fill(0xffffff)
      g.beginPath().arc(0, pr * 0.2, pr * 0.2, Math.PI * 0.15, Math.PI * 0.85).stroke({ width: 2.5, color: 0x2f7f68, cap: 'round' })
      g.circle(-pr * 0.55, pr * 0.14, pr * 0.14).fill({ color: 0xffa8b8, alpha: 0.55 })
      g.circle(pr * 0.55, pr * 0.14, pr * 0.14).fill({ color: 0xffa8b8, alpha: 0.55 })
      T.playerBody = bake(g)
    }
    // STILLNESS (v7.14): the body's own SILHOUETTE sharpens toward a triangle as the ramp climbs —
    // a skin change rather than a badge, which is the Isaac idiom the owner asked for.
    //   A baked LADDER, not a live morph: the outline is a 60-point path and rebuilding it every
    // frame would put Graphics work in the hottest sync in this file, where every other player
    // element is a static bake. STILL_STEPS frames over a 2s ramp is ~14 fps of shape change,
    // which reads as continuous at this size.
    //   Points lerp between the ellipse and an up-pointing rounded triangle of the SAME area, so
    // the blob sharpens without appearing to grow or shrink.
    //   Screen-up, not facing-relative: the generic blob pins bodyC.rotation to 0 and supplies
    // facing with an x-flip alone (see syncPlayer), so a facing-relative point would force the rig
    // to start rotating — which would spin the baked face with it. Up survives the flip unchanged.
    //   STILL_MORPH_MAX caps how far it goes: the brief was "slightly more triangular", and a full
    // polygon stops reading as the same creature.
    T.playerStill = []
    T.playerStillFlash = []
    for (let s = 0; s < STILL_STEPS; s++) {
      const k = (s / (STILL_STEPS - 1)) * STILL_MORPH_MAX
      const g = new Graphics()
      const pts = []
      const N = 60
      for (let i = 0; i < N; i++) {
        const th = (i / N) * Math.PI * 2
        // ellipse radius at this angle, and the regular-triangle radius with a vertex at screen-up
        const ex = Math.cos(th) * pr
        const ey = Math.sin(th) * pr * 0.91
        const er = Math.hypot(ex, ey)
        const seg = ((th + Math.PI / 2) % (Math.PI * 2 / 3)) - Math.PI / 3
        const tr = pr * 1.12 * Math.cos(Math.PI / 3) / Math.cos(seg)
        const r = er + (tr - er) * k
        pts.push(Math.cos(th) * r, Math.sin(th) * r)
      }
      g.poly(pts).fill(0x7de3c3).stroke({ width: 3.5, color: 0x3aa88a })
      // the face is drawn at fixed coordinates on top, exactly as in T.playerBody — only the
      // outline morphs, so the character never stops being the same character
      g.circle(-pr * 0.36, -pr * 0.18, pr * 0.23).fill(0xffffff)
      g.circle(pr * 0.36, -pr * 0.18, pr * 0.23).fill(0xffffff)
      g.beginPath().arc(0, pr * 0.2, pr * 0.2, Math.PI * 0.15, Math.PI * 0.85).stroke({ width: 2.5, color: 0x2f7f68, cap: 'round' })
      g.circle(-pr * 0.55, pr * 0.14, pr * 0.14).fill({ color: 0xffa8b8, alpha: 0.55 })
      g.circle(pr * 0.55, pr * 0.14, pr * 0.14).fill({ color: 0xffa8b8, alpha: 0.55 })
      T.playerStill.push(bake(g))
      // ...and the same outline as a flat white silhouette, for BERSERK's red wash and for the hit
      // flash. Baked per rung from the SAME points so the wash can never be a round blob sitting
      // over a triangular body.
      const gf = new Graphics()
      gf.poly(pts).fill(0xffffff).stroke({ width: 3.5, color: 0xffffff })
      T.playerStillFlash.push(bake(gf))
    }
    {
      const g = new Graphics()
      g.ellipse(0, 0, pr, pr * 0.91).fill(0xffffff).stroke({ width: 3.5, color: 0xffffff })
      T.playerFlash = bake(g)
    }
    {
      const g = new Graphics()
      g.circle(0, 0, pr * 0.115).fill(0x2f3140)
      g.circle(-pr * 0.04, -pr * 0.04, pr * 0.04).fill(0xffffff)
      T.pupil = bake(g)
    }
    {
      const g = new Graphics()
      g.ellipse(0, 0, pr * 0.82, pr * 0.3).fill({ color: 0x000000, alpha: 0.12 })
      T.playerShadow = bake(g)
    }
    // Book 2's player body (drawFish, defined above in The Surf's roster section) — baked here
    // alongside the generic blob it replaces, same "build once regardless of chapter, swap in
    // syncPlayer at use time" contract T.kaijuBody follows for skies. FISH_PHASES frames, so
    // T.fishBody/T.fishFlash are arrays here, not single {tex,ax,ay} bakes; syncPlayer indexes them
    // off animT. A dedicated elongated shadow, not the round T.playerShadow above: the fish runs
    // long on x, and the round disc would sit visibly narrower than the body it grounds. The shadow
    // does NOT flip per phase — a swimming body's footprint envelope barely moves, so one fixed
    // ellipse is the honest shape and six of them would be six identical bakes.
    T.fishBody = []
    T.fishFlash = []
    for (let wp = 0; wp < FISH_PHASES; wp++) {
      const ang = (wp / FISH_PHASES) * Math.PI * 2
      const bg = new Graphics(); drawFish(bg, false, ang); T.fishBody.push(bake(bg))
      const wg = new Graphics(); drawFish(wg, true, ang); T.fishFlash.push(bake(wg))
    }
    T.fishShadow = (() => {
      const g = new Graphics()
      g.ellipse(0, 0, FISH_R * 1.5, FISH_R * 0.46).fill({ color: 0x000000, alpha: 0.2 })
      return bake(g)
    })()

    // bullet star, orbit spark, nova ring: built in buildFxTextures() below (fx sprites)
    // gems vs coins: gems flat yellow, coins gold with shine arc + inner circle
    {
      // xp gem: blue crystal — must NOT read as gold (coins are the other drop)
      const g = new Graphics()
      g.poly([0, -7, 5, 0, 0, 7, -5, 0]).fill(0x4da3ff).stroke({ width: 1.8, color: 0x2a6fd1 })
      g.poly([0, -7, 5, 0, 0, 0]).fill({ color: 0x9fd0ff, alpha: 0.9 }) // top-right facet
      g.circle(-1.5, -2.2, 1.2).fill({ color: 0xffffff, alpha: 0.9 })
      T.gem = bake(g)
    }
    {
      const g = new Graphics()
      g.circle(0, 0, 6.5).fill(0xffcf4d).stroke({ width: 2, color: 0xb9891d })
      g.circle(0, 0, 3.6).stroke({ width: 1.5, color: 0xffe9a8 })
      g.beginPath().arc(0, 0, 5, -2.3, -1.1).stroke({ width: 1.6, color: 0xffffff, alpha: 0.9, cap: 'round' })
      T.coin = bake(g)
    }
    // particles: soft white dot + 4-point sparkle (tinted per use)
    {
      const g = new Graphics()
      g.circle(0, 0, 6).fill({ color: 0xffffff, alpha: 0.45 })
      g.circle(0, 0, 3.6).fill(0xffffff)
      T.dot = bake(g)
    }
    {
      const g = new Graphics()
      g.star(0, 0, 4, 7, 2.4).fill(0xffffff)
      T.sparkle = bake(g)
    }

    // ---- v2 weapon visuals -------------------------------------------------
    // boomerang, slime mine, homing wisp: built in buildFxTextures() below (fx sprites)
    // warm nova ring (mine explosion) — same technique as the old T.nova, orange tint
    {
      const g = new Graphics()
      g.circle(0, 0, 64).stroke({ width: 10, color: 0xffb37a })
      g.circle(0, 0, 57).stroke({ width: 4, color: 0xffe0b8, alpha: 0.7 })
      T.novaWarm = bake(g)
    }
    // neutral-white ring, same geometry as novaWarm, for spawnRing's optional tint param
    // (tinted bursts recolor this live instead of baking one per hue)
    {
      const g = new Graphics()
      g.circle(0, 0, 64).stroke({ width: 10, color: 0xffffff })
      g.circle(0, 0, 57).stroke({ width: 4, color: 0xffffff, alpha: 0.7 })
      T.novaRing = bake(g)
    }
    // black hole: dark near-black core, baked once at the weapon's max radius so most
    // instances (lower levels) scale down rather than blur up. The swirling vortex itself
    // is live counter-rotating fx sprites (see acquireHole()), not part of this bake.
    {
      const R = WEAPONS.hole.levels[WEAPONS.hole.levels.length - 1].radius
      const g = new Graphics()
      g.circle(0, 0, R * 0.16).fill(0x140a24)
      T.holeCore = bake(g)
      T.holeRefR = R
      // The hole's BODY. Same radial gradient it has always been — the four stops below are the
      // canvas gradient's own — but rasterised as concentric strokes and put through bake() like
      // every other sprite in this file, so there is NO canvas anywhere in the path.
      //
      // It used to be `Texture.from(canvas)`. That is the second time this exact texture had to be
      // taken out of an object, on the same reporter's device: v5.23.7 removed it from the gravity
      // well, which was showing "a hard-edged rectangle stuck to the well, measured at exactly that
      // sprite's width with hard top and bottom edges" — a sprite's own QUAD, visible where only a
      // soft disc should be. The well was fixed and the hole was left on it, so the artifact just
      // moved house: reported again on the hole, a red band across the top of the disc, always
      // level, always attached to it. The fault has only ever been seen on CANVAS-backed textures
      // (this and a canvas clip() in v5.23.5); the several hundred bake()/PNG sprites on the same
      // device are fine, which is the whole reason this stays a sprite and only changes how the
      // texture is made. Do not put a canvas back in here.
      //
      // DISJOINT ANNULI, each carrying the gradient's exact colour and alpha at its own radius — a
      // circle stroke IS an annulus, so nothing composites over anything and there is nothing to
      // solve. The two approaches tried before this both distorted the look, and both were caught
      // by pixel-diffing the result against the canvas gradient itself:
      //   - nested FILLS composited up to the curve: needs a per-ring colour solve that demands
      //     out-of-range channels once the rings are fine, and clamping left the tint ~6/255 off.
      //   - OVERLAPPING strokes (1.3x width, to hide seams): near the centre a stroke's width
      //     exceeds its radius, so they pile up on each other — alpha 181 where it should be 140.
      // Hence butt-jointed widths and a plain fill for the middle, inside which the gradient is
      // flat enough (0.550 -> 0.542) that one colour is truthful.
      {
        const RREF = 128          // baked small and upscaled: it is low-frequency, it takes it well
        const N = 192             // bands: quantisation is then under 1/255 across the whole disc
        const T0 = 0.02           // below this the fill takes over
        const stops = [[0, 0x261454, 0.55], [0.55, 0x3a207a, 0.34], [0.85, 0x5a2fb0, 0.14], [1, 0x5a2fb0, 0]]
        const at = (t) => {
          let k = 1
          while (k < stops.length - 1 && t > stops[k][0]) k++
          const [t0, c0, a0] = stops[k - 1]
          const [t1, c1, a1] = stops[k]
          const f = (t - t0) / (t1 - t0)
          const ch = (sh) => Math.round(((c0 >> sh) & 255) + (((c1 >> sh) & 255) - ((c0 >> sh) & 255)) * f)
          return { color: (ch(16) << 16) | (ch(8) << 8) | ch(0), alpha: a0 + (a1 - a0) * f }
        }
        const gd = new Graphics()
        const w = (RREF * (1 - T0)) / N
        for (let i = 0; i < N; i++) {
          const r = RREF * T0 + (i + 0.5) * w
          gd.circle(0, 0, r).stroke({ width: w, ...at(r / RREF) })
        }
        gd.circle(0, 0, RREF * T0).fill(at(T0 / 2))
        T.holeDisc = bake(gd)
        T.holeDiscRef = RREF
      }
    }
    // neon beam: horizontal bar baked at the weapon's max length/width, anchored so local (0,0)
    // sits at the left edge (player origin). v5.6.13 (user art direction): a SITH SABER, not a
    // rainbow — a white-hot core sheathed in crimson inside a soft red bloom. No gradients in
    // Graphics, so the bloom is stepped sleeves of rising alpha; normal-blend (additive washes to
    // white on the city's light concrete, and a red saber that turns white has lost the point).
    {
      const len = WEAPONS.rainbow.levels[WEAPONS.rainbow.levels.length - 1].length
      const w = WEAPONS.rainbow.levels[WEAPONS.rainbow.levels.length - 1].width
      const R = w / 2
      const blade = (bloom, sheath, core, hot) => {
        const g = new Graphics()
        // bloom sleeves, widest first (each with round caps overhanging the emitter end a little)
        g.roundRect(-R, -R, len + R * 2, w, R).fill({ color: bloom, alpha: 0.22 })
        g.roundRect(-R * 0.75, -R * 0.8, len + R * 1.5, w * 0.8, R * 0.8).fill({ color: sheath, alpha: 0.4 })
        g.roundRect(-R * 0.5, -R * 0.58, len + R, w * 0.58, R * 0.58).fill({ color: core, alpha: 0.95 })
        g.roundRect(-R * 0.3, -R * 0.27, len + R * 0.6, w * 0.27, R * 0.27).fill({ color: hot, alpha: 0.98 })
        return bake(g)
      }
      T.beam = blade(0xc41220, 0xdc1f2b, 0xff3b45, 0xfff2ef)
      // The Beyond's Pulsar Sweep is a run.beams entry too, so it was drawing itself with the
      // saber above — a crimson bar sweeping a chapter whose whole palette is violet and cyan, and
      // the only saturated red in it. Same blade, folded into the chapter's own colour. Tinting
      // wasn't an option: a blue tint on a red bake multiplies to mud.
      T.beamSweep = blade(0x2d2a8c, 0x4b46d6, 0x8f7dff, 0xf0ecff)
      T.beamRefLen = len
      T.beamRefWidth = w
    }

    // red vignette (canvas radial gradient, stretched over the screen)
    {
      const c = document.createElement('canvas')
      c.width = c.height = 256
      const ctx = c.getContext('2d')
      const grad = ctx.createRadialGradient(128, 128, 60, 128, 128, 182)
      grad.addColorStop(0, 'rgba(255,70,80,0)')
      grad.addColorStop(1, 'rgba(235,60,70,0.65)')
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, 256, 256)
      T.vignette = Texture.from(c)
    }


    // storm blob (skies overlay, v5.6.18): a plain soft white radial gradient, center to fully
    // transparent at the edge — no Graphics gradient support, same canvas trick as the vignette
    // above. One bake, tinted+scaled per instance for both the ground cloud-shadows (dark, huge,
    // slow) and the overhead parallax clouds (lighter, even bigger) — see STORM_VIS/updateStorm.
    {
      const c = document.createElement('canvas')
      c.width = c.height = 512
      const ctx = c.getContext('2d')
      const grad = ctx.createRadialGradient(256, 256, 0, 256, 256, 256)
      grad.addColorStop(0, 'rgba(255,255,255,0.9)')
      grad.addColorStop(0.5, 'rgba(255,255,255,0.45)')
      grad.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, 512, 512)
      T.stormBlob = Texture.from(c)
    }

    // ---- organic floor: ground blotches + hand-drawn detail bits -----------
    // soft mottling, radial-gradient canvas textures (center color -> transparent)
    {
      function blotch(r, g, b, a) {
        const c = document.createElement('canvas')
        c.width = c.height = 300
        const ctx = c.getContext('2d')
        const grad = ctx.createRadialGradient(150, 150, 0, 150, 150, 150)
        grad.addColorStop(0, `rgba(${r},${g},${b},${a})`)
        grad.addColorStop(1, `rgba(${r},${g},${b},0)`)
        ctx.fillStyle = grad
        ctx.fillRect(0, 0, 300, 300)
        return Texture.from(c)
      }
      T.blotches = [
        blotch(207, 216, 174, 0.55), // soft green
        blotch(233, 222, 196, 0.6),  // warm sand
        blotch(196, 214, 189, 0.45), // sage
        blotch(238, 215, 197, 0.4),  // blush
      ]
    }
    // ---- district ground SIGNATURE patterns (skies only, v5.9.1 render fix) -------------------
    // "the biomes are not clear enough" (playtest report): DISTRICTS' floorTint (config.js) is
    // deliberately squeezed into a ~0.06-0.09 luminance band (a night storm, not daylight — see
    // that constant's own comment) so hue alone was never going to carry six districts, but the
    // OTHER half of the bug is that every district paints the exact same shape as its base ground
    // texture — T.blotches right above, four soft round radial-gradient blobs, reused everywhere.
    // Downtown pavement and a park lawn were literally the same mottling, just recoloured. These
    // five bakes give five of the six districts (parks keeps the original blotch: soft organic
    // mottling already reads as "wild/unmanicured," and it isn't one of this task's named examples)
    // their own PATTERN, not just their own tint: asphalt slab seams, a mown-lawn tick hatch,
    // parallel crop furrows, a rocky stipple, gentle water ripples.
    // Baked WHITE (alpha alone carries the shape) so floorTint (districtTintAt, below) is STILL the
    // only thing setting hue — exactly like T.blotches' own tint path (populateBlotch) — these only
    // add a silhouette on top of it, never a second competing colour. bake()'s default pad crops
    // tightly to whatever's drawn (unlike T.blotches' fixed 300px canvas), which is fine: populate-
    // Blotch's scale math is a relative multiplier on the texture's OWN size either way, and its
    // anchor comes from bake()'s own {ax,ay}, not a hardcoded 0.5 — see that function below.
    {
      function groundTile(draw) {
        const g = new Graphics()
        draw(g)
        return bake(g)
      }
      // downtown: asphalt slab — a hard rounded-rect block (not a soft round blotch) with 1-2
      // engraved seam gaps (low-alpha cuts through the fill) reading as pavement joints. Two
      // variants (seam position/slab size differ) so a paved block doesn't repeat visibly.
      T.districtGround = {}
      T.districtGround.downtown = [
        groundTile((g) => {
          g.roundRect(-135, -95, 270, 190, 12).fill({ color: 0xffffff, alpha: 0.48 })
          g.rect(-135, -14, 270, 8).fill({ color: 0x000000, alpha: 0.32 })  // horizontal joint
          g.rect(-24, -95, 8, 190).fill({ color: 0x000000, alpha: 0.32 })  // vertical joint
        }),
        groundTile((g) => {
          g.roundRect(-115, -125, 230, 250, 10).fill({ color: 0xffffff, alpha: 0.44 })
          g.rect(-115, 30, 230, 7).fill({ color: 0x000000, alpha: 0.3 })
          g.rect(45, -125, 7, 250).fill({ color: 0x000000, alpha: 0.3 })
        }),
      ]
      // suburbs: mown lawn — a dense, evenly-fanned hatch of short ticks (grass blades). The
      // REGULARITY is the "manicured" read (versus parks' loose organic blotch below) — each tile
      // still lands at a random rotation like every other blotch, so the hatch direction still
      // varies yard to yard; it's the density/uniformity that reads as "lawn," not a global grain.
      T.districtGround.suburbs = [
        groundTile((g) => {
          for (let row = -5; row <= 5; row++) {
            for (let col = -5; col <= 5; col++) {
              const x = col * 22 + (hash(row * 7.1 + col * 3.7) - 0.5) * 11
              const y = row * 22 + (hash(row * 2.3 + col * 9.9 + 4) - 0.5) * 11
              if (x * x + y * y * 1.6 > 125 * 125) continue // round off the tile's corners
              const a = 1.35 + (hash(row * 5.3 + col * 1.7 + 8) - 0.5) * 0.7
              g.moveTo(x, y).lineTo(x + Math.cos(a) * 8, y + Math.sin(a) * 8)
                .stroke({ width: 2.4, color: 0xffffff, alpha: 0.4, cap: 'round' })
            }
          }
        }),
      ]
      // farms: parallel furrow lines — populateBlotch (below) rotates this to the FIELD's own row
      // angle (farmRowSnap, shared with the cropTuft prop) instead of a random spin, so every cell
      // in one field shares the SAME line direction and the belt reads as cultivated rows, not
      // scattered dashes. Two variants (line spacing/count differ) for a little texture variety.
      T.districtGround.farms = [
        groundTile((g) => {
          for (let k = -4; k <= 4; k++) g.rect(-150, k * 24 - 3, 300, 6).fill({ color: 0xffffff, alpha: 0.4 })
        }),
        groundTile((g) => {
          for (let k = -5; k <= 5; k++) g.rect(-150, k * 20 - 2, 300, 4).fill({ color: 0xffffff, alpha: 0.44 })
        }),
      ]
      // hills: rocky stipple — a scatter of small hard-edged fleck polygons (same fixed-jitter n-gon
      // idiom as the T.rockChunk/pebble bakes elsewhere), grittier than every other district's soft
      // blotch. Two variants (fleck count/placement differ).
      T.districtGround.hills = [
        groundTile((g) => {
          for (let n = 0; n < 20; n++) {
            const a = hash(n * 3.7 + 1.1) * Math.PI * 2
            const d = hash(n * 5.3 + 2.9) * 115
            const x = Math.cos(a) * d, y = Math.sin(a) * d * 0.75
            const r = 4 + hash(n * 7.1 + 0.4) * 7
            const pts = []
            for (let k = 0; k < 6; k++) {
              const pa = (k / 6) * Math.PI * 2
              const pr = r * (0.7 + hash(n * 11 + k * 2.3) * 0.5)
              pts.push(x + Math.cos(pa) * pr, y + Math.sin(pa) * pr)
            }
            g.poly(pts).fill({ color: 0xffffff, alpha: 0.3 + hash(n * 2.1) * 0.18 })
          }
        }),
        groundTile((g) => {
          for (let n = 0; n < 15; n++) {
            const a = hash(n * 4.3 + 9.1) * Math.PI * 2
            const d = hash(n * 6.1 + 3.7) * 108
            const x = Math.cos(a) * d, y = Math.sin(a) * d * 0.8
            const r = 5 + hash(n * 8.3 + 1.2) * 9
            const pts = []
            for (let k = 0; k < 6; k++) {
              const pa = (k / 6) * Math.PI * 2
              const pr = r * (0.7 + hash(n * 13 + k * 3.1) * 0.5)
              pts.push(x + Math.cos(pa) * pr, y + Math.sin(pa) * pr)
            }
            g.poly(pts).fill({ color: 0xffffff, alpha: 0.28 + hash(n * 3.3) * 0.2 })
          }
        }),
      ]
      // sea: gentle ripple bands — soft parallel curves, lower alpha than every land pattern above
      // (water reads calmer/flatter, not busy). Two variants (curve bow/spacing differ).
      // v5.11: open water was reading as a flat dead-navy plane between the sparse foam/container
      // props (kill list-adjacent complaint: "large areas of flat dead navy"). More ripple bands
      // (5, was 3) plus a scatter of tiny moonlit glint flecks — still one bake, still white-alpha
      // so floorTintAt still carries all the hue, just enough incident texture that the water reads
      // as a surface instead of empty canvas.
      T.districtGround.sea = [
        groundTile((g) => {
          for (const yOff of [-110, -55, 0, 55, 110]) {
            g.moveTo(-150, yOff).quadraticCurveTo(0, yOff - 24, 150, yOff)
              .stroke({ width: 5, color: 0xffffff, alpha: 0.2, cap: 'round' })
          }
          for (let k = 0; k < 14; k++) {
            const gx = (hash(k * 4.1 + 0.7) - 0.5) * 280
            const gy = (hash(k * 6.7 + 1.9) - 0.5) * 190
            g.circle(gx, gy, 1.3).fill({ color: 0xffffff, alpha: 0.22 + hash(k * 2.3) * 0.18 })
          }
        }),
        groundTile((g) => {
          for (const yOff of [-95, -40, 20, 75, 120]) {
            g.moveTo(-150, yOff).quadraticCurveTo(0, yOff + 22, 150, yOff)
              .stroke({ width: 4.5, color: 0xffffff, alpha: 0.18, cap: 'round' })
          }
          for (let k = 0; k < 12; k++) {
            const gx = (hash(k * 5.3 + 2.4) - 0.5) * 280
            const gy = (hash(k * 3.9 + 4.1) - 0.5) * 190
            g.circle(gx, gy, 1.2).fill({ color: 0xffffff, alpha: 0.2 + hash(k * 1.7) * 0.18 })
          }
        }),
      ]
    }

    // ---- TERRAIN TILES (v5.11) — the ground is a surface, not a scatter -----------------------
    // "the backgrounds is still bad... some white lines are crossing everything i dont know what is
    // it, maybe crops but it's so ugly it doesnt resemble anything" (playtest report).
    //
    // The white lines were T.districtGround.farms, above: nine 300px stripes per tile, stamped at a
    // random 1.1-1.7x scale on a 420px cell and rotated to the field angle. Farmland was being drawn
    // as INDIVIDUAL CROP STROKES, which is the wrong level of abstraction for a camera this high —
    // from above you cannot resolve a furrow, you resolve a FIELD. So the strokes never read as
    // crops; they read as hatching scribbled over the whole map, including over biomes that have no
    // crops at all, because a 420px blotch cell samples its district at its own centre and lands
    // wherever it likes.
    //
    // The replacement is a different kind of layer. Every tile here is a FULL SQUARE covering its
    // whole cell edge-to-edge, at a fixed position, with no jitter, no random scale and no random
    // rotation. That single change is what turns the floor from "things scattered on a void" into a
    // continuous SURFACE — which is what a satellite view is.
    //
    // Farmland is now a PATCHWORK OF PARCELS: one flat field per cell, its own crop colour, its own
    // row direction, bordered by a headland strip so neighbouring fields visibly abut. That is the
    // actual overhead signature of agriculture, and it is the reason parcels are axis-aligned — real
    // surveyed farmland follows section lines, and an axis-aligned lattice also tiles a square cell
    // grid perfectly, so fields meet with no gaps and no overlap.
    //
    // COLOUR STILL COMES FROM THE TINT. Each tile is baked WHITE (alpha carries the shape only), so
    // districtTintAt — which v5.11 made continuous in the raw elevation/moisture/urban fields —
    // remains the only thing setting hue. This matters at coastlines: the TEXTURE changes abruptly
    // at a cell boundary, but the COLOUR does not, so a shoreline reads as a smooth curve instead of
    // a 280px staircase. Texture popping is nearly invisible; colour popping is not.
    {
      const TT = 256   // bake reference size; populateTerrain scales this to the cell
      const H = TT / 2
      // v5.12: a terrain tile carries TEXTURE ONLY — no fill, no colour. Colour is a continuous
      // field drawn underneath by updateGroundField; see its header for why the two were separated.
      // The square here is a ZERO-ALPHA BOUNDS KEEPER (the same idiom skiesPlan uses): it fixes
      // bake()'s tight crop to exactly TTxTT so every biome's tile scales alike, while contributing
      // nothing visible. `baseAlpha` is gone — a tile that paints no colour cannot quantise one.
      function terrainTile(draw) {
        const g = new Graphics()
        g.rect(-H, -H, TT, TT).fill({ color: 0x000000, alpha: 0 })
        if (draw) draw(g)
        // bake() returns {tex, ax, ay} and NOTHING else — it has no `ref`. Carrying the reference
        // size explicitly is what lets populateTerrain scale a tile to its cell; reading a
        // non-existent look.ref silently yields NaN, which Pixi renders as an invisible sprite.
        return { ...bake(g), ref: TT + 6 }
      }
      // Farmland is the ONE exception that keeps an opaque, coloured, hard-edged tile — a surveyed
      // field really is a flat rectangle of one crop with a sharp boundary, and the patchwork is the
      // whole point. Applying that logic to a coastline is what produced the staircase; applying it
      // to a parcel is just correct. populateTerrain uses these only where a cell is SOLIDLY
      // farmland (all four corners too), so a parcel can never cut a square edge into a shoreline.
      function parcelTile(draw) {
        const g = new Graphics()
        g.rect(-H, -H, TT, TT).fill({ color: 0xffffff, alpha: 1 })
        if (draw) draw(g)
        return { ...bake(g), ref: TT + 6 }
      }
      // Rows for a cultivated parcel: thin, low-contrast, and CLOSE together. The v5.10 furrows
      // failed by being wide, bright and far apart, which reads as stripes rather than as texture.
      function rows(g, vertical, pitch, alpha) {
        for (let k = -8; k <= 8; k++) {
          const o = k * pitch - 1
          if (vertical) g.rect(o, -H, 2, TT).fill({ color: 0xffffff, alpha })
          else g.rect(-H, o, TT, 2).fill({ color: 0xffffff, alpha })
        }
      }
      // The headland: the turn-strip at a field's edge where the tractor comes about. Drawn as an
      // inset darker border, it is what makes one parcel legibly a DIFFERENT parcel from its
      // neighbour — without it a patchwork of similar greens is just noise.
      function headland(g) {
        g.rect(-H + 1.5, -H + 1.5, TT - 3, TT - 3).stroke({ width: 3, color: 0x000000, alpha: 0.22 })
      }
      T.terrainTile = {}
      // Solid-interior farm parcels: opaque, crop-coloured, hard-edged (see parcelTile).
      T.parcelTile = [
        parcelTile((g) => { rows(g, false, 15, 0.11); headland(g) }),
        parcelTile((g) => { rows(g, true, 15, 0.11); headland(g) }),
        parcelTile((g) => { rows(g, false, 22, 0.09); headland(g) }),
        parcelTile((g) => { rows(g, true, 22, 0.09); headland(g) }),
        // centre-pivot irrigation: a perfect circle in a field of straight lines is the single most
        // recognisable thing in an overhead photograph of farmland.
        parcelTile((g) => {
          g.circle(0, 0, H * 0.92).fill({ color: 0xffffff, alpha: 0.13 })
          g.circle(0, 0, H * 0.92).stroke({ width: 2.5, color: 0xffffff, alpha: 0.20 })
          g.rect(-1.5, -H * 0.92, 3, H * 0.92).fill({ color: 0xffffff, alpha: 0.16 })   // the arm
          headland(g)
        }),
      ]
      // ...and the texture-only version used on a farm cell that touches another biome, so a
      // parcel's hard edge never lands on a shoreline.
      T.terrainTile.farms = [
        terrainTile((g) => rows(g, false, 15, 0.10)),
        terrainTile((g) => rows(g, true, 15, 0.10)),
        terrainTile((g) => rows(g, false, 22, 0.08)),
        terrainTile((g) => rows(g, true, 22, 0.08)),
      ]
      // Desert: wind-blown dune ripples — long, shallow, near-parallel arcs at very low contrast.
      // An arid surface is defined by how LITTLE is on it, so this is the sparsest tile here.
      T.terrainTile.desert = [
        terrainTile((g) => {
          for (let k = -4; k <= 4; k++) {
            g.moveTo(-H, k * 30)
            g.bezierCurveTo(-H / 2, k * 30 - 13, H / 2, k * 30 + 13, H, k * 30)
            g.stroke({ width: 2.5, color: 0xffffff, alpha: 0.07 })
          }
        }),
        terrainTile((g) => {
          for (let n = 0; n < 14; n++) {
            const x = (hash(n * 3.1 + 0.7) - 0.5) * TT
            const y = (hash(n * 5.9 + 2.2) - 0.5) * TT
            g.circle(x, y, 1.4 + hash(n * 2.3) * 1.6).fill({ color: 0xffffff, alpha: 0.10 })
          }
        }),
      ]
      // Beach: wet sand, with the swash lines the tide leaves parallel to the water.
      T.terrainTile.beach = [
        terrainTile((g) => {
          for (let k = -3; k <= 3; k++) {
            g.moveTo(-H, k * 36 + 6)
            g.bezierCurveTo(-H / 3, k * 36 - 9, H / 3, k * 36 + 15, H, k * 36 + 2)
            g.stroke({ width: 2, color: 0xffffff, alpha: 0.13 })
          }
          for (let n = 0; n < 26; n++) {
            g.circle((hash(n * 4.7 + 1.3) - 0.5) * TT, (hash(n * 6.1 + 3.9) - 0.5) * TT, 1)
              .fill({ color: 0xffffff, alpha: 0.16 })
          }
        }),
      ]
      // Water: broad, calm, low-contrast ripple banding. Deliberately the flattest tile — water is
      // the one surface that should NOT compete for attention, since the threats fly over it.
      T.terrainTile.sea = [
        terrainTile((g) => {
          for (let k = -4; k <= 4; k++) {
            g.moveTo(-H, k * 32)
            g.bezierCurveTo(-H / 2, k * 32 + 9, H / 2, k * 32 - 9, H, k * 32)
            g.stroke({ width: 3, color: 0xffffff, alpha: 0.06 })
          }
        }),
        terrainTile((g) => {
          for (let k = -3; k <= 3; k++) {
            g.moveTo(-H, k * 40 + 12)
            g.bezierCurveTo(-H / 2, k * 40 + 2, H / 2, k * 40 + 22, H, k * 40 + 10)
            g.stroke({ width: 3, color: 0xffffff, alpha: 0.05 })
          }
        }),
      ]
      // Woodland: overlapping canopy crowns. Irregular, clustered, and the only tile whose detail
      // is meant to read as individual OBJECTS from above — because tree crowns actually do.
      // Parks: MOWN STRIPES. v5.13 — this tile used to be 22 soft white discs per 256px cell, and
      // in a park-sized region that is ~260 overlapping pale circles on screen at once: the "bokeh"
      // haze the user reported as visual clutter, and (kill list §8.10) the exact soft-radial-blob
      // idiom the art direction spec set out to remove. The stripe bake that was written to replace
      // it has existed since v5.10 as T.districtGround.parks — but populateBlotch, its only caller,
      // returns early for any chapter with a terrain map, so skies has never once drawn it. Moving
      // it here, into the tile populateTerrain actually reads, is the whole fix.
      // ONE variant, no random rotation (populateTerrain pins rotation 0): a mown field has a single
      // grain, and v5.12's lesson was that per-cell randomness is what reads as lattice noise.
      // Pitch divides TT evenly (256 / 32 = 8, an even count) so the A/B alternation meets itself
      // across a cell boundary instead of seaming.
      T.terrainTile.parks = [
        terrainTile((g) => {
          const st = DISTRICT_SURFACE.parks
          for (let k = -4; k <= 3; k++) {
            g.rect(-H, k * st.stripePx, TT, st.stripePx)
              .fill({ color: 0xffffff, alpha: (k & 1) ? st.stripeAlphaA : st.stripeAlphaB })
          }
        }),
      ]
      // High ground: contour banding. A contour line is the one mark that says "slope" to a camera
      // with no horizon, which is the whole problem with drawing terrain relief from directly above.
      T.terrainTile.hills = [
        terrainTile((g) => {
          for (let k = 0; k < 5; k++) {
            g.ellipse(10, -6, H * (0.28 + k * 0.19), H * (0.20 + k * 0.16))
              .stroke({ width: 2.5, color: 0xffffff, alpha: 0.09 })
          }
        }),
        terrainTile((g) => {
          for (let n = 0; n < 16; n++) {
            const x = (hash(n * 3.7 + 6.1) - 0.5) * TT
            const y = (hash(n * 5.3 + 2.9) - 0.5) * TT
            const r = 4 + hash(n * 7.1 + 0.4) * 7
            const pts = []
            for (let k = 0; k < 6; k++) {
              const pa = (k / 6) * Math.PI * 2
              const pr = r * (0.7 + hash(n * 11 + k * 2.3) * 0.5)
              pts.push(x + Math.cos(pa) * pr, y + Math.sin(pa) * pr)
            }
            g.poly(pts).fill({ color: 0xffffff, alpha: 0.13 })
          }
        }),
      ]
      // Built ground. Downtown is a paved slab with expansion joints; suburbs is lawn plus the lot
      // lines that divide one garden from the next. Both keep their v5.10 character — those two
      // patterns were never the problem — but as full tiles rather than floating blobs.
      // NO STRAIGHT LINES IN A TILE THAT REPEATS. The first cut of these two drew slab seams and lot
      // lines as full-width rects at fixed offsets — which, stamped on every cell, tiled into a
      // hard 280px lattice across the whole city. The floor grew its own visible grid, competing
      // with the actual street grid drawn on top of it. Only the farm parcel is allowed a border,
      // because there the repetition IS the subject; everywhere else the detail has to be
      // hash-scattered so no two neighbouring tiles line up.
      T.terrainTile.downtown = [
        terrainTile((g) => {
          // worn asphalt: irregular patches and old repairs, never a seam that reaches an edge
          for (let n = 0; n < 9; n++) {
            const x = (hash(n * 3.3 + 1.4) - 0.5) * TT * 0.8
            const y = (hash(n * 5.7 + 2.8) - 0.5) * TT * 0.8
            const w = 14 + hash(n * 2.1) * 34, h2 = 10 + hash(n * 4.4) * 26
            g.rect(x, y, w, h2).fill({ color: 0x000000, alpha: 0.06 + hash(n * 7.7) * 0.06 })
          }
        }),
        terrainTile((g) => {
          for (let n = 0; n < 30; n++) {
            const x = (hash(n * 4.9 + 3.1) - 0.5) * TT
            const y = (hash(n * 6.3 + 0.6) - 0.5) * TT
            g.circle(x, y, 2 + hash(n * 3.7) * 5).fill({ color: 0x000000, alpha: 0.07 })
          }
        }),
      ]
      T.terrainTile.suburbs = [
        terrainTile((g) => {
          for (let n = 0; n < 90; n++) {
            const x = (hash(n * 2.7 + 0.9) - 0.5) * TT
            const y = (hash(n * 4.1 + 5.7) - 0.5) * TT
            g.rect(x, y, 1.6, 5).fill({ color: 0xffffff, alpha: 0.11 })
          }
        }),
        terrainTile((g) => {
          for (let n = 0; n < 70; n++) {
            const x = (hash(n * 3.9 + 2.3) - 0.5) * TT
            const y = (hash(n * 5.7 + 1.1) - 0.5) * TT
            g.rect(x, y, 1.6, 5).fill({ color: 0xffffff, alpha: 0.10 })
          }
          // one hedge stub, hash-placed and well short of any edge, so it cannot line up with a
          // neighbouring tile's
          g.rect(-40 + hash(9.1) * 60, -20 + hash(4.4) * 40, 54, 3).fill({ color: 0x000000, alpha: 0.13 })
        }),
      ]
    }
    // pebble: tiny irregular rounded stone (7-gon, fixed jitter baked once)
    {
      const g = new Graphics()
      const n = 7
      const pts = []
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2
        const rr = 9 * (0.72 + hash(i * 13.7 + 4.21) * 0.5)
        pts.push(Math.cos(a) * rr, Math.sin(a) * rr)
      }
      g.poly(pts).fill(0xb9b0a2).stroke({ width: 1.4, color: 0x8f8778 })
      g.ellipse(-2.6, -3, 3, 1.8).fill({ color: 0xffffff, alpha: 0.55 })
      T.pebble = bake(g)
    }
    // puddle: irregular pool squashed vertically, with a pale shine arc
    {
      const g = new Graphics()
      const n = 9
      const pts = []
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2
        const rr = 16 * (0.8 + hash(i * 9.3 + 11.13) * 0.4)
        pts.push(Math.cos(a) * rr, Math.sin(a) * rr * 0.6)
      }
      g.poly(pts).fill({ color: 0x8db2ff, alpha: 0.28 }).stroke({ width: 1.4, color: 0x8db2ff, alpha: 0.45 })
      g.beginPath().arc(-4, -2.5, 6, Math.PI * 1.1, Math.PI * 1.7).stroke({ width: 1.4, color: 0xffffff, alpha: 0.5, cap: 'round' })
      T.puddle = bake(g)
    }
    // ---- per-chapter baked props (v5.4) ------------------------------------
    // The prop sheet (src/props/) is entirely foliage, and chapters 4-7 have no botany to scatter —
    // a city street strewn with mushrooms is the tell. So their floor furniture is hand-drawn here
    // exactly the way pebble/puddle already are: baked once in its own natural colours, then
    // multiplied by the chapter floorTint at populate time so it sits in the biome's light.
    // UPRIGHT props are drawn with their ORIGIN AT THE BASE (y=0 is the ground line) — bake() hands
    // back the matching anchor, so they plant on the floor instead of floating.
    {
      // lilypad (pond, v6.4 — BIOME_POND below): a flat top-down pad. Irregular lobed rim
      // (radialOutline-style cosine perturbation, the same trick T.asteroid uses below) plus the
      // classic wedge notch cut to the centre, radial veins fanned across the rim the notch didn't
      // cut, a darker rim edge and a subtle off-centre sheen. NEVER a smooth disc — render.js's
      // own rule: a plain green circle is the single most "programmer art" shape on offer. Flat and
      // top-down (no `upright` — spins freely, same as puddle/asteroid). Murky green family, tuned
      // into BIOME_POND's decor luminance band — see that block's own comment for the measured
      // numbers this was authored against.
      const g = new Graphics()
      const R = 32
      const body = 0x4e9473
      const rim = 0x357a5c
      const hi = 0xd1f4e0
      const notchA = 0.4      // the notch points off to one side, never straight +x
      const notchHalf = 0.32  // rad, notch half-width — a real wedge, not a nick
      const shape = (a) => {
        let rr = R * (0.88 + 0.09 * Math.cos(a * 2 + 0.6) + 0.06 * Math.cos(a * 3 - 1.4)) // 2-3 uneven lobes
        let d = a - notchA
        while (d > Math.PI) d -= Math.PI * 2
        while (d < -Math.PI) d += Math.PI * 2
        if (Math.abs(d) < notchHalf) rr *= 0.12 + 0.88 * (Math.abs(d) / notchHalf) // wedge cut toward the centre
        return rr
      }
      g.poly(radialOutline(shape, 56)).fill(body).stroke({ width: 2, color: rim })
      g.beginPath() // radial veins, fanned across the rim the notch did NOT cut — none cross the gap
      const veins = 6
      for (let v = 0; v <= veins; v++) {
        const va = notchA + notchHalf + (v / veins) * (Math.PI * 2 - notchHalf * 2)
        const vr = shape(va)
        g.moveTo(Math.cos(va) * R * 0.1, Math.sin(va) * R * 0.1).lineTo(Math.cos(va) * vr * 0.94, Math.sin(va) * vr * 0.94)
      }
      g.stroke({ width: 1.1, color: rim, alpha: 0.5 })
      g.ellipse(-R * 0.24, -R * 0.2, R * 0.32, R * 0.22).fill({ color: hi, alpha: 0.35 }) // subtle off-centre sheen
      T.lilypad = bake(g)
    }
    {
      // root arch (undergrowth): knuckled roots breaking the loam. Real joints at each knuckle and a
      // taper to every tip — the same rule the creatures follow, so it never reads as bent tubing.
      const g = new Graphics()
      const bark = 0x6b5334
      taperStroke(g, [[-46, 1], [-30, -19], [-4, -27], [22, -15], [41, 2]], 11, 3.4, bark, 4)
      taperStroke(g, [[-25, 1], [-10, -11], [12, -13], [31, -1]], 7, 2.2, bark, 4)
      for (const [x0, y0, x1, y1] of [[-30, -19, -43, -33], [22, -15, 33, -29], [-4, -27, -2, -42]]) {
        taperStroke(g, [[x0, y0], [x1, y1]], 5, 1.2, bark, 3)
      }
      g.beginPath() // bark grain: hairline, follows the run of the root
      for (const [x0, y0, x1, y1] of [[-38, -6, -12, -22], [-8, -24, 18, -18], [4, -20, 28, -8]]) {
        g.moveTo(x0, y0).lineTo(x1, y1)
      }
      g.stroke({ width: 1.2, color: 0x8a6d45, alpha: 0.5 })
      T.root = bake(g)
    }
    {
      // bone (undergrowth): a long bone with two epiphyses — pale ivory, the one LIGHT thing on the
      // dark loam, so it reads as a warning about what lives here.
      const g = new Graphics()
      const ivory = 0xd8cfb8
      const line = 0x9c9078
      taperStroke(g, [[-13, 1], [13, -1]], 6.5, 6, ivory, 3)
      for (const [x, s] of [[-14, 1], [14, -1]]) { // knuckle pairs at each end
        g.circle(x, -4 * s, 5).fill(ivory).stroke({ width: 1.2, color: line })
        g.circle(x + s * 1.5, 4 * s, 4.4).fill(ivory).stroke({ width: 1.2, color: line })
      }
      g.beginPath().moveTo(-9, -2).lineTo(9, -3).stroke({ width: 1, color: line, alpha: 0.5 })
      T.bone = bake(g)
    }
    {
      // fire hydrant (city): upright, origin at the base. Dome cap, side nozzles, base flange —
      // a silhouette every player already knows, so it only needs its proportions right.
      const g = new Graphics()
      const red = 0xc4432f
      const line = 0x6e2318
      g.rect(-11, -4, 22, 4).fill(red).stroke({ width: 1.4, color: line })       // base flange
      g.poly(spineOutline((t) => [0, -5 - t * 22], (t) => 7.5 * (1 - 0.12 * Math.sin(t * Math.PI * 2)), 14))
        .fill(red).stroke({ width: 1.6, color: line })                            // barrel
      for (const s of [-1, 1]) taperStroke(g, [[s * 5, -16], [s * 11, -16]], 4, 3.2, red, 2) // nozzles
      g.circle(0, -29, 6).fill(red).stroke({ width: 1.6, color: line })          // dome cap
      g.circle(0, -33, 2.2).fill(red).stroke({ width: 1.2, color: line })        // bonnet nut
      g.ellipse(-3, -22, 2.2, 6).fill({ color: 0xf2937f, alpha: 0.45 })          // lit edge
      g.ellipse(3.5, -18, 2.4, 8).fill({ color: 0x6e2318, alpha: 0.22 })         // shaded side
      T.hydrant = bake(g)
    }
    {
      // dumpster (city, big layer): a steel bin in 3/4 — a hard trapezoid body with a lid slab,
      // corrugation as hairline ribs, small casters. Origin at the base.
      const g = new Graphics()
      const steel = 0x3f6b4a
      const line = 0x1f3a27
      for (const x of [-26, 26]) g.circle(x, -3, 3.4).fill(0x22252a) // casters
      g.poly([-34, -4, -29, -34, 29, -34, 34, -4]).fill(steel).stroke({ width: 2, color: line }) // body
      g.poly([-33, -34, -37, -41, 37, -41, 33, -34]).fill(0x4d7d58).stroke({ width: 2, color: line }) // lid
      g.beginPath() // corrugation ribs — hairline, what makes it steel and not a box
      for (let i = -3; i <= 3; i++) g.moveTo(i * 8.5, -32).lineTo(i * 8.2, -6)
      g.stroke({ width: 1.2, color: 0x2b4f36, alpha: 0.55 })
      g.poly([-34, -12, -33, -4, 34, -4, 34, -12]).fill({ color: 0x1f3a27, alpha: 0.25 }) // shaded skirt
      g.poly([-36, -40, -37, -41, 37, -41, 36, -40]).fill({ color: 0x8fbf9c, alpha: 0.3 }) // lit lid edge
      T.dumpster = bake(g)
    }
    {
      // traffic cone (city): upright, origin at the base — one tapered cone with the two reflective
      // bands taken as slices of its OWN profile, so they wrap with the taper.
      const g = new Graphics()
      const orange = 0xe8712f
      const line = 0x8a3a12
      const spine = (t) => [0, -2 - t * 24]
      const wide = (t) => 8.5 * (1 - 0.82 * t) + 1.2
      g.rect(-11, -4, 22, 4).fill(orange).stroke({ width: 1.4, color: line }) // base plate
      g.poly(spineOutline(spine, wide, 14)).fill(orange).stroke({ width: 1.5, color: line })
      for (const [t0, t1] of [[0.3, 0.46], [0.6, 0.74]]) { // reflective bands, following the cone
        g.poly(spineOutline(spine, wide, 6, t0, t1)).fill({ color: 0xf2ece0, alpha: 0.9 })
      }
      g.poly(spineOutline(spine, (t) => wide(t) * 0.34, 10, 0, 0.9)).fill({ color: 0xf7a06a, alpha: 0.35 }) // lit centre
      T.cone = bake(g)
    }
    {
      // rubble (skies): a shattered concrete slab with rebar. Value here is a three-way squeeze —
      // the floor is PALE and the whole roster is DARK, so the prop must not sit in the enemies'
      // band or a tank parked on rubble disappears (measured: 1.41x at the first pass). So the
      // chunk is drawn LIGHT, well above every aircraft (2.3-3.9x clear of them), and its read
      // against the pale floor is carried by the dark outline + rebar rather than by its fill —
      // the same trick the white blood cell uses to sit on pale pink.
      const g = new Graphics()
      const crete = 0xb5b0a2
      const line = 0x4f4a41
      for (const [x0, y0, kx, ky, x1, y1] of [[-14, -12, -18, -20, -21, -24], [6, -16, 9, -23, 13, -26], [-2, -14, -1, -20, 1, -23]]) {
        // rebar: kinked at a real joint and SHORT — long straight spikes read as antennae, not steel
        taperStroke(g, [[x0, y0], [kx, ky], [x1, y1]], 2.6, 1.1, 0x6b4a2f, 3)
      }
      g.poly([-30, 2, -24, -14, -6, -20, 16, -16, 28, -2, 20, 4]).fill(crete).stroke({ width: 1.8, color: line })
      g.poly([-24, -14, -6, -20, 16, -16, 12, -10, -12, -8]).fill({ color: 0xd6d1c2, alpha: 0.4 }) // lit top face
      g.poly([-30, 2, -12, -8, 20, 4]).fill({ color: 0x4f4a41, alpha: 0.22 })                      // shaded base
      g.beginPath() // fracture lines — hairline, the "shattered" read
      g.moveTo(-18, -12).lineTo(-8, 0)
      g.moveTo(4, -17).lineTo(10, -3)
      g.moveTo(-6, -19).lineTo(-2, -6)
      g.stroke({ width: 1.1, color: 0x5f5a50, alpha: 0.5 })
      T.rubble = bake(g)
    }
    {
      // asteroid (beyond): an irregular cratered rock. The void floor is near-black, so the rock is
      // drawn LIGHT and the cold violet floorTint pushes it back down into the dark.
      const g = new Graphics()
      const rock = 0xa9a2bb
      const line = 0x4e4763
      const shape = (a) => 26 * (0.78 + 0.14 * Math.cos(a * 3 + 0.9) + 0.09 * Math.cos(a * 5 - 2.2) + 0.06 * Math.sin(a * 8))
      g.poly(radialOutline(shape, 40, 1, 0.86)).fill(rock).stroke({ width: 1.8, color: line })
      g.ellipse(2, 6, 17, 8).fill({ color: 0x4e4763, alpha: 0.26 })   // shaded underside
      g.ellipse(-4, -7, 14, 6).fill({ color: 0xd6d0e6, alpha: 0.3 })  // lit dorsal
      for (const [cx, cy, cr] of [[-8, -3, 5], [7, 2, 3.6], [-2, 8, 2.6], [12, -6, 2.2]]) {
        g.circle(cx, cy, cr).fill({ color: 0x6f6788, alpha: 0.5 })           // craters
        g.circle(cx - cr * 0.2, cy - cr * 0.2, cr * 0.6).fill({ color: 0x8b83a4, alpha: 0.5 })
      }
      T.asteroid = bake(g)
    }
    // planet (v5.18, The Beyond): the chapter's largest object by far and the thing that sells
    // "star system". It gets its OWN bake rather than reusing T.asteroid, which is authored at a
    // ~51-unit content radius: at the new collider sizes (up to r 260) that rock was being magnified
    // ~9.7x into a blurred smear of torn paper, and a second copy of it was stamped at the rim.
    // Baked ONCE at a high reference radius and scaled DOWN per planet, so it stays crisp.
    // Lit from -y, the direction of the distant star, and every other object in the chapter agrees
    // with that (see drawInvader's crown/belly). A sphere is a disc plus a terminator, and the
    // terminator is the only thing that makes it read as a ball rather than a coin.
    {
      // PLANETS (beyond) — v5.20. Seven baked archetypes instead of one repeated sphere.
      //
      // Why seven complete bakes rather than one texture re-tinted per instance: Pixi's tint is a
      // MULTIPLY, so it can only cool/warm/darken. It cannot turn a banded violet gas giant into a
      // grey cratered moon. Rotation is no help either — this chapter has an explicit one-light
      // direction (see the kaiju/prop bakes: everything agrees where the sun is), and spinning a lit
      // sphere moves its terminator. Tint survives as a SECONDARY axis only: 7 bakes x 5 hues.
      //
      // Sizing reality, which is what drives the art: world.scale is 1, so an o.r=260 planet is a
      // 520px sprite on a ~430px-wide phone. You usually see a LIMB AND A SLICE, never a whole disc.
      // So every archetype's identifying mark repeats across the whole surface — no single centred
      // motif — and the limb/halo colour matters most, because it enters the screen first.
      const PLANET_R = 256
      // Body disc as a fraction of PLANET_R. Was 0.985, which put the halo stroke (centred 0.995R,
      // width 0.06R) out to 1.025R on a canvas whose half-extent IS 1.0R — so the halo was shaved
      // flat at the four cardinal points. 0.90 gives every archetype room for its halo AND its rings.
      const PLANET_BODY = 0.90
      // Near-white on purpose. Two gas giants side by side should read as two gas giants, not as a
      // gas giant and a bruise — the archetype's real palette is baked, this only nudges hue.
      const PLANET_TINTS = [0xffffff, 0xffe4cc, 0xd8e2ff, 0xffd8e8, 0xd8fff0]
      // rad/s. Deliberately tiny — see skin.planetSpinRate where it is used.

      const RING_TILT = -0.2
      // The ellipse's minor/major. Also the cosine of how far the ring plane is tipped away from
      // edge-on, which is what ringPole below needs.
      const RING_SQUASH = 0.3
      const RING_BANDS = [[0.98, 0.86, 'rgba(228,214,186,0.55)'], [0.84, 0.74, 'rgba(255,244,220,0.75)'],
        [0.72, 0.63, 'rgba(190,172,142,0.45)']]
      const ICE_RINGS = [[0.99, 0.91, 'rgba(198,232,255,0.5)'], [0.89, 0.81, 'rgba(255,255,255,0.72)'],
        [0.79, 0.71, 'rgba(140,190,238,0.4)']]
      const SHARD_RINGS = [[0.97, 0.92, 'rgba(196,158,255,0.42)'], [0.9, 0.85, 'rgba(240,226,255,0.6)'],
        [0.83, 0.79, 'rgba(150,112,214,0.35)']]
      // A ring is drawn TWICE — once under the body (far half) and once over it (near half, clipped
      // to its own lower half-plane, hence rotate-then-clip). That sandwich is the only thing that
      // makes a ring pass BEHIND a planet. It is also why a ringed archetype's body shrinks: the
      // ring has to fit the same centred square every other planet uses, or syncObstacles' "texture
      // width == collider diameter" contract stops holding for exactly those entries.
      // v5.23.5 — the near half is now an EXPLICIT half-annulus path, not a full annulus behind a
      // rect clip(). On one reporter's Android the near half rendered as nothing at all while the
      // far half was perfect, on a build verified to contain this code — and a clip() was the only
      // canvas op the near path used that the far path did not. Same geometry, one less construct.
      // Canvas angles run clockwise on screen (y is down), so 0..PI IS the lower/near half; the
      // implicit line ellipse() draws to each new sub-arc's start gives the two flat end caps.
      function ringAnnulus(ctx, c, R, half, tilt = RING_TILT, bands = RING_BANDS) {
        const near = half === 'near'
        ctx.save(); ctx.translate(c, c); ctx.rotate(tilt)
        for (const [ro, ri, col] of bands) {
          ctx.beginPath()
          ctx.ellipse(0, 0, R * ro, R * ro * RING_SQUASH, 0, 0, near ? Math.PI : Math.PI * 2)
          ctx.ellipse(0, 0, R * ri, R * ri * RING_SQUASH, 0, near ? Math.PI : Math.PI * 2, 0, true)
          ctx.closePath()
          ctx.fillStyle = col; ctx.fill()
        }
        ctx.restore()
      }
      // A ring lies in its planet's EQUATORIAL plane, so a ringed world's spin axis is that plane's
      // normal — pinned, never random, or the belts would run visibly across the rings. Derived, not
      // eyeballed: tip a ring by asin(RING_SQUASH) out of edge-on and its normal comes out at
      // (0, cos, sin) in the shader's y-UP space; the canvas tilt then rotates it in-screen, and a
      // canvas rotation is CLOCKWISE in y-up terms, which is where the sin's sign comes from.
      const ringPole = (tilt) => {
        const s = Math.sqrt(1 - RING_SQUASH * RING_SQUASH)
        return [Math.sin(tilt) * s, Math.cos(tilt) * s, RING_SQUASH]
      }
      // A moon: the only SECOND BODY in the set, and the fastest way to say "this is a system, not a
      // ball". Two tones, lit from up-left to agree with PLANET_LIGHT — the shader can't help here,
      // this rides the flat overlay. It always straddles the limb (the overlay canvas is only 1.0R
      // wide, so nothing fits entirely outside a 0.9R body); half behind the planet is the read.
      // The lit disc is INSET rather than clipped (0.27r off-centre + 0.72r radius = 0.99r, so it can
      // never reach the limb). Same reason as ringAnnulus above: this renderer now uses no canvas
      // clip() at all, because one device disagreed with the only two that existed.
      function moon(ctx, x, y, r, dark, lit) {
        ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2)
        ctx.fillStyle = dark; ctx.fill()
        ctx.beginPath(); ctx.arc(x - r * 0.18, y - r * 0.2, r * 0.72, 0, Math.PI * 2)
        ctx.fillStyle = lit; ctx.fill()
      }
      // Soft-edged pool, used for lava lakes and city conurbations alike.
      function glowBlob(ctx, x, y, r, inner, outer) {
        const g = ctx.createRadialGradient(x, y, 0, x, y, r)
        g.addColorStop(0, inner); g.addColorStop(1, outer)
        ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill()
      }
      // Closed blob from normalised points — continents, for the ocean and night-side worlds.
      // Curved, not straight: at gameplay scale a planet is ~500px, and straight-edged polygons read
      // as green paper cutouts glued to the sphere. Each source point becomes a quadratic control
      // point and the curve passes through edge midpoints, so a 4-point list gives a rounded blob.
      function landmass(ctx, c, br, pts, fill, stroke) {
        const px = (i) => c + br * pts[(i + pts.length) % pts.length][0]
        const py = (i) => c + br * pts[(i + pts.length) % pts.length][1]
        ctx.beginPath()
        ctx.moveTo((px(-1) + px(0)) / 2, (py(-1) + py(0)) / 2)
        for (let i = 0; i < pts.length; i++) {
          ctx.quadraticCurveTo(px(i), py(i), (px(i) + px(i + 1)) / 2, (py(i) + py(i + 1)) / 2)
        }
        ctx.closePath(); ctx.fillStyle = fill; ctx.fill()
        if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = br * 0.016; ctx.stroke() }
      }

      // The shared scaffold, in the same order the single planet used: body gradient, clipped
      // surface, terminator, optional emissive ON TOP of the terminator, rim arc, halo.
      // v5.21 SPLIT: surface and lighting are now TWO textures, because planets rotate.
      //
      // Rotating a fully-lit sphere drags its terminator and rim light around with it, so a spinning
      // planet reads as a planet whose SUN is orbiting it — and this chapter's whole prop set agrees
      // on one light direction. So the archetype bake keeps only rotation-INVARIANT content (a
      // CONCENTRIC body gradient, the surface features, the halo) and every directional cue moves
      // into one shared shell drawn unrotated on top, in the pooled sprite (clumpB) the planet branch
      // was already leaving empty. Surface spins underneath; the light never moves.
      // v5.23 — THE RE-PROJECTION. This used to bake a flat DISC; the sphere shader wants a lat/long
      // MAP. Every archetype's surface()/emissive() already draws into a [-1,1] square, so the whole
      // conversion is one transform: that square becomes the full 360x180 map. Belts stay belts, the
      // ice world's caps land on the actual poles, and PLANET_ARCHETYPES did not change at all.
      // ponytail: 1024x512 per archetype (~2MB) is 2x the old disc bake. Halve it if the beyond
      // chapter ever shows memory pressure on a phone — the visible hemisphere is only half the map.
      // ONE square of art covering 180 degrees of longitude; the sampler mirrors it round the back
      // (see the uv line in PLANET_FRAG). 512 is the size the art was authored at, so this is 1:1 —
      // and at gameplay a planet is ~470px across showing exactly this one copy, which puts it
      // right at one texel per pixel. Baking the mirror instead would double every map for nothing.
      const MAP_S = 512
      const planetMapTex = (a, emissive) => {
        const t = canvasTex(MAP_S, MAP_S, (ctx, w, h) => {
          if (!emissive) {
            // Flat albedo, NOT the old centre-bright radial: that gradient was a hand-painted sphere
            // shade, and the shader computes the real one per pixel now — baking it in would darken
            // every limb twice. The emissive map starts transparent: it is ADDED, never lit.
            ctx.fillStyle = a.base; ctx.fillRect(0, 0, w, h)
            // Latitude shading is not directional shading. The spin axis IS the map's pole axis, so
            // a pole-to-equator gradient is invariant under the planet's own rotation — it adds
            // depth to a flat fill without smuggling back a fixed light direction.
            if (a.polar) {
              const rgb = hexRGB(a.polar)
              for (const top of [true, false]) {
                const g = ctx.createLinearGradient(0, top ? 0 : h, 0, top ? h * 0.32 : h * 0.68)
                g.addColorStop(0, `rgba(${rgb},0.5)`); g.addColorStop(1, `rgba(${rgb},0)`)
                ctx.fillStyle = g; ctx.fillRect(0, top ? 0 : h * 0.68, w, h * 0.32)
              }
            }
          }
          const draw = emissive ? a.emissive : a.surface
          if (!draw) return
          ctx.save()
          ctx.translate(w / 2, h / 2); ctx.scale(w / 2, h / 2)
          draw(ctx, 0, 1)
          ctx.restore()
        })
        // MIRROR-repeat, not plain repeat: the far hemisphere is this art reflected, so both the
        // mid join and the wrap join match by construction. Plain repeat would butt art x=+1
        // against x=-1 and step at every seam — the cut-off edge this whole scheme exists to kill.
        // V clamps: latitude does not wrap, and the north pole must not bleed into the south.
        t.source.style.addressModeU = 'mirror-repeat'
        t.source.style.addressModeV = 'clamp-to-edge'
        return t
      }

      // Everything that is NOT on the sphere: the atmosphere glow, which extends past the limb, and
      // the ringed world's annulus, which has to straddle it. Both are rotation-invariant, so they
      // stay ordinary sprites — `behind` under the mesh, `front` over it.
      // The halo is a radial FADE, not a stroke: a constant-width constant-alpha ring reads as a
      // hard outline, which against this chapter's near-black background is the most artificial
      // thing on screen. 1.10 is the ceiling, not a taste call — PLANET_BODY is 0.90, so the halo
      // reaches 0.99 of the canvas half-extent; past 1.11 it comes back shaved at the four cardinals.
      const planetOverlayTex = (a, front) => canvasTex(PLANET_R * 2, PLANET_R * 2, (ctx, w) => {
        const R = PLANET_R, c = w / 2, br = R * (a.bodyR ?? PLANET_BODY)
        if (!front) { a.behind(ctx, c, R, br); return }
        if (a.halo) {
          const hg = ctx.createRadialGradient(c, c, br * 0.94, c, c, br * 1.1)
          hg.addColorStop(0, `rgba(${a.halo},0)`)
          hg.addColorStop(0.35, `rgba(${a.halo},${a.haloA})`)
          hg.addColorStop(1, `rgba(${a.halo},0)`)
          ctx.beginPath(); ctx.arc(c, c, br * 1.1, 0, Math.PI * 2); ctx.fillStyle = hg; ctx.fill()
        }
        if (a.front) a.front(ctx, c, R, br)
      })

      // The lighting shell is GONE (v5.23). Day-side lift, terminator and rim light were three
      // painted gradients faking a sphere under a fixed sun, and they are now three lines of the
      // fragment shader computed from the real normal. That is also what unlocked all-axis rotation:
      // the old surface could only spin because none of its lighting lived in the same texture.

      // A latitude belt in lat/long space is a full-width BAND. Drawn as the ellipse it used to be,
      // it tapers to a point at both map edges, and on the sphere that reads as the belt pinching
      // shut along one meridian — one of the two things that made the surface look cut up. Soft top
      // and bottom edges keep it weather rather than a painted stripe. Stops carry the band's OWN
      // rgb at zero alpha: fading to transparent BLACK would put a dark fringe on every edge.
      const hexRGB = (h) => `${parseInt(h.slice(1, 3), 16)},${parseInt(h.slice(3, 5), 16)},${parseInt(h.slice(5, 7), 16)}`
      const band = (ctx, oy, ry, col, al) => {
        const rgb = hexRGB(col)
        const g = ctx.createLinearGradient(0, oy - ry, 0, oy + ry)
        g.addColorStop(0, `rgba(${rgb},0)`)
        g.addColorStop(0.5, `rgba(${rgb},${al})`)
        g.addColorStop(1, `rgba(${rgb},0)`)
        ctx.fillStyle = g; ctx.fillRect(-1, oy - ry, 2, ry * 2)
      }
      // A polar cap covers EVERY longitude, so it is the map's top or bottom row, full width — not
      // an ellipse parked near the edge of a square.
      const cap = (ctx, top, depth, rgb, al) => {
        const y0 = top ? -1 : 1, y1 = top ? -1 + depth : 1 - depth
        const g = ctx.createLinearGradient(0, y0, 0, y1)
        g.addColorStop(0, `rgba(${rgb},${al})`)
        g.addColorStop(1, `rgba(${rgb},0)`)
        ctx.fillStyle = g; ctx.fillRect(-1, Math.min(y0, y1), 2, depth)
      }
      const PLANET_ARCHETYPES = [
        { // A. gas giant — eight irregular belts + one storm oval + a moon rising off its shoulder.
          base: '#e0a55f', polar: '#8a5330',
          halo: '255,190,120', haloA: 0.2,
          moons: [[0.12, 1.22, '#4a3a2c', '#cbb79a']],
          surface(ctx, c, br) {
            // Deliberately irregular widths — the old four near-symmetric belts read as a test pattern.
            // v5.23.4: alphas roughly doubled. At 0.16-0.22 over a flat albedo the belts washed out
            // to nothing on a phone and the planet read as a plain orange ball ("basketballs").
            for (const [oy, ry, al, col] of [[-0.72, 0.07, 0.42, '#fff2d8'], [-0.5, 0.11, 0.36, '#7d4a2a'],
              [-0.28, 0.09, 0.4, '#ffdaa6'], [-0.08, 0.14, 0.32, '#6b3d22'], [0.14, 0.08, 0.44, '#ffe4b8'],
              [0.34, 0.12, 0.36, '#5e3520'], [0.56, 0.07, 0.32, '#ffd39a'], [0.74, 0.1, 0.4, '#4a2a19']]) {
              band(ctx, oy, ry, col, al)
            }
            ctx.beginPath(); ctx.ellipse(c + br * 0.26, c + br * 0.2, br * 0.24, br * 0.13, -0.12, 0, Math.PI * 2)
            ctx.fillStyle = '#b9432a'; ctx.fill()
            ctx.beginPath(); ctx.ellipse(c + br * 0.26, c + br * 0.2, br * 0.13, br * 0.065, -0.12, 0, Math.PI * 2)
            ctx.fillStyle = 'rgba(255,190,140,0.55)'; ctx.fill()
          },
        },
        { // B. cratered moon — the ONLY body with no halo. Airlessness is the fastest discriminator.
          base: '#a8a29a', polar: '#585349',
          halo: null,
          surface(ctx, c, br) {
            // Fixed table, not hashed: this bakes ONCE, so there is nothing to vary, and a literal
            // list is legible where a seeded loop is not (same reasoning as T.asteroid's craters).
            for (const [cx, cy, cr] of [[-0.42, -0.2, 0.17], [0.18, -0.44, 0.11], [0.4, 0.12, 0.2],
              [-0.14, 0.34, 0.13], [0.06, -0.06, 0.08], [-0.55, 0.3, 0.09], [0.55, -0.22, 0.07],
              [-0.28, -0.55, 0.06], [0.24, 0.52, 0.1], [-0.66, -0.02, 0.06], [0.68, 0.36, 0.05]]) {
              const x = c + br * cx, y = c + br * cy, r = br * cr
              ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2)
              ctx.fillStyle = 'rgba(52,46,40,0.5)'; ctx.fill()
              ctx.beginPath(); ctx.arc(x, y, r * 0.94, Math.PI * 0.95, Math.PI * 1.95)
              ctx.strokeStyle = 'rgba(255,250,240,0.62)'; ctx.lineWidth = r * 0.22; ctx.stroke()
              ctx.beginPath(); ctx.arc(x, y, r * 0.94, Math.PI * 0.05, Math.PI * 0.9)
              ctx.strokeStyle = 'rgba(30,26,22,0.52)'; ctx.lineWidth = r * 0.18; ctx.stroke()
            }
            ctx.beginPath(); ctx.ellipse(c - br * 0.12, c + br * 0.08, br * 0.46, br * 0.38, 0.5, 0, Math.PI * 2)
            ctx.fillStyle = 'rgba(60,54,48,0.45)'; ctx.fill()
          },
        },
        { // C. ice world — brightest thing in a chapter whose background is 0x120a26, and RINGED, at
          // a steeper tilt than the gas giant's so the two never read as the same silhouette.
          bodyR: 0.6, pole: ringPole(0.44),
          base: '#cfe6ff', polar: '#5f86bd',
          halo: '150,220,255', haloA: 0.26,
          behind(ctx, c, R) { ringAnnulus(ctx, c, R, 'far', 0.44, ICE_RINGS) },
          front(ctx, c, R) { ringAnnulus(ctx, c, R, 'near', 0.44, ICE_RINGS) },
          surface(ctx, c, br) {
            // Caps ride BOTH poles, so a fragment of either limb still names the planet.
            cap(ctx, true, 0.34, '255,255,255', 0.8)
            cap(ctx, false, 0.28, '255,255,255', 0.55)
            ctx.lineCap = 'round'
            // The three cracks that cross the seam START and END at the same latitude, so the tiled
            // copies chain into one continuous line around the planet instead of stepping at it.
            for (const [x0, y0, qx, qy, x1, y1] of [[-1, -0.3, -0.1, -0.52, 1, -0.3], [-1, 0.1, 0.05, 0.34, 1, 0.1],
              [-0.62, -1, -0.3, 0.05, -0.05, 1], [0.3, -1, 0.52, 0.1, 0.24, 1], [-1, 0.46, 0.1, 0.62, 1, 0.46]]) {
              ctx.beginPath(); ctx.moveTo(c + br * x0, c + br * y0)
              ctx.quadraticCurveTo(c + br * qx, c + br * qy, c + br * x1, c + br * y1)
              ctx.strokeStyle = 'rgba(46,74,122,0.42)'; ctx.lineWidth = br * 0.028; ctx.stroke()
              ctx.strokeStyle = 'rgba(236,248,255,0.5)'; ctx.lineWidth = br * 0.01; ctx.stroke()
            }
          },
        },
        { // D. molten — the only planet whose detail SURVIVES the terminator. That inversion is the read.
          base: '#4a1f16', polar: '#241009',
          halo: '255,110,40', haloA: 0.22,
          surface(ctx, c, br) {
            for (const [x, y, r] of [[-0.3, -0.25, 0.42], [0.32, 0.1, 0.46], [-0.05, 0.48, 0.34]]) {
              ctx.beginPath(); ctx.ellipse(c + br * x, c + br * y, br * r, br * r * 0.8, 0.4, 0, Math.PI * 2)
              ctx.fillStyle = 'rgba(12,7,6,0.45)'; ctx.fill()  // basalt plates give the crust scale
            }
          },
          emissive(ctx, c, br) {
            ctx.lineCap = 'round'; ctx.lineJoin = 'round'
            // The two cracks that circle the body run edge to edge at a MATCHED latitude, so the
            // tiled copies meet at the seam and read as one unbroken rift rather than stopping dead.
            for (const path of [[[-1, -0.12], [-0.5, -0.28], [-0.12, -0.05], [0.3, -0.22], [1, -0.12]],
              [[-1, 0.46], [-0.28, 0.3], [0.1, 0.42], [0.55, 0.28], [1, 0.46]],
              [[-0.2, -0.9], [-0.05, -0.5], [-0.22, -0.1], [0, 0.35], [-0.1, 0.92]],
              [[0.45, -0.85], [0.6, -0.4], [0.42, 0], [0.66, 0.5]]]) {
              ctx.beginPath()
              path.forEach(([x, y], k) => (k ? ctx.lineTo(c + br * x, c + br * y) : ctx.moveTo(c + br * x, c + br * y)))
              ctx.strokeStyle = 'rgba(255,96,20,0.85)'; ctx.lineWidth = br * 0.038; ctx.stroke()
              ctx.strokeStyle = 'rgba(255,222,150,0.9)'; ctx.lineWidth = br * 0.012; ctx.stroke()
            }
            for (const [x, y, r] of [[-0.12, -0.06, 0.28], [0.52, 0.3, 0.22], [-0.5, 0.44, 0.18]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(255,220,140,0.95)', 'rgba(255,80,20,0)')
            }
          },
        },
        { // E. ocean world — the only CURVED WHITE marks in the set. THREE surface colours (sea, green
          // continent, ochre interior) plus ice caps: this is the "continents" world of the set.
          base: '#2f8fd8', polar: '#124a86',
          halo: '120,200,255', haloA: 0.28,
          moons: [[0.1, 1.28, '#3d4450', '#b9c3d0']],
          surface(ctx, c, br) {
            cap(ctx, true, 0.16, '255,255,255', 0.85)
            cap(ctx, false, 0.13, '255,255,255', 0.7)
            for (const pts of [[[-0.55, -0.35], [-0.15, -0.5], [0.12, -0.28], [-0.1, -0.02], [-0.45, 0.02]],
              [[0.15, 0.08], [0.6, 0], [0.72, 0.3], [0.4, 0.52], [0.1, 0.36]],
              [[-0.7, 0.3], [-0.35, 0.28], [-0.2, 0.6], [-0.6, 0.72]]]) {
              landmass(ctx, c, br, pts, 'rgba(74,124,72,0.95)', 'rgba(180,220,150,0.4)')
            }
            // Dry interiors — a continent of one flat green is a paper cutout; two tones make it land.
            for (const pts of [[[-0.42, -0.3], [-0.2, -0.36], [-0.12, -0.18], [-0.34, -0.1]],
              [[0.3, 0.14], [0.56, 0.1], [0.58, 0.34], [0.28, 0.38]]]) {
              landmass(ctx, c, br, pts, 'rgba(186,158,96,0.75)', null)
            }
            ctx.lineCap = 'round'
            for (const [x, y, r, a0, a1] of [[-0.3, -0.1, 0.3, 0.4, 3.4], [-0.36, -0.1, 0.16, 1.2, 4.4],
              [0.36, 0.34, 0.26, 2.2, 5.2], [0.3, 0.3, 0.13, 3, 6], [0.1, -0.62, 0.34, 0.2, 2.6]]) {
              ctx.beginPath(); ctx.arc(c + br * x, c + br * y, br * r, a0, a1)
              ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.lineWidth = br * 0.07; ctx.stroke()
            }
            // v5.23.2: the specular glint is GONE. It was painted at the light's focus, which was
            // fine on a still disc — but it lives on the surface, so on a turning planet it slid
            // around the body like a headlight. A highlight that moves with the terrain is worse
            // than no highlight; the shader's own N.L already brightens the sub-stellar point.
          },
        },
        { // F. night side — every other planet is alive TOWARD the star. This one is alive away from it.
          base: '#3d5a55', polar: '#17282c',
          halo: '255,190,110', haloA: 0.16,
          surface(ctx, c, br) {
            for (const pts of [[[-0.6, -0.3], [-0.1, -0.46], [0.3, -0.2], [0.1, 0.12], [-0.5, 0.06]],
              [[0.2, 0.2], [0.66, 0.12], [0.78, 0.44], [0.34, 0.62]],
              [[-0.72, 0.36], [-0.3, 0.34], [-0.16, 0.72], [-0.66, 0.8]]]) {
              landmass(ctx, c, br, pts, 'rgba(14,26,28,0.8)', 'rgba(96,132,124,0.35)')
            }
          },
          emissive(ctx, c, br) {
            // v5.23.2: no daylight gate any more. It used to skip lights near a baked sun position,
            // which was right for a still disc — but the surface TURNS now, so a gate baked into it
            // would carry a fixed patch of "no cities" around the planet with the terrain. The
            // shader suppresses this whole map by N.L instead, so the lights fade as they rotate
            // into daylight and come back as they leave it, which is what the gate was faking.
            const dot = (x, y) => ctx.fillRect(c + br * x, c + br * y, br * 0.014, br * 0.014)
            for (const [x, y, r] of [[0.34, 0.3, 0.16], [0.58, -0.05, 0.12], [0.16, 0.62, 0.13],
              [0.62, 0.46, 0.09], [-0.05, 0.8, 0.1]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(255,196,110,0.45)', 'rgba(255,160,60,0)')
            }
            ctx.fillStyle = 'rgba(255,214,150,0.95)'
            // Cities crowd coastlines, so walk fixed polylines and scatter perpendicular to them.
            for (const line of [[[0.05, 0.1], [0.3, 0.24], [0.55, 0.2], [0.72, 0.4]],
              [[0.4, -0.4], [0.56, -0.12], [0.5, 0.14], [0.62, 0.44]],
              [[-0.1, 0.5], [0.16, 0.62], [0.44, 0.66], [0.66, 0.56]],
              [[0.2, -0.66], [0.44, -0.5], [0.62, -0.2]]]) {
              for (let s = 0; s < line.length - 1; s++) {
                const [ax, ay] = line[s], [bx, by] = line[s + 1]
                for (let k = 0; k < 8; k++) {
                  const t = k / 8, jx = (k % 3 - 1) * 0.035, jy = (k % 2 ? 1 : -1) * 0.028
                  dot(ax + (bx - ax) * t + jx, ay + (by - ay) * t + jy)
                }
              }
            }
          },
        },
        { // G. ringed — the only broken silhouette, and the ring enters the screen BEFORE the planet,
          // which on a phone is the most valuable property in the set. Body shrinks to make room.
          bodyR: 0.58,
          pole: ringPole(RING_TILT),
          base: '#c9a86a', polar: '#7a5a34',
          halo: '255,220,160', haloA: 0.16,
          surface(ctx, c, br) {
            for (const [oy, ry, al, col] of [[-0.5, 0.12, 0.34, '#ffeccb'], [-0.16, 0.15, 0.3, '#8a6740'],
              [0.2, 0.13, 0.34, '#ffe0ae'], [0.56, 0.11, 0.3, '#6d5030']]) {
              band(ctx, oy, ry, col, al)
            }
            // v5.23.3 — WHY THIS EXISTS: bands are uniform across every longitude, so a surface made
            // of nothing but bands is rotationally symmetric about the pole. This planet spins about
            // exactly that axis, so every rotation mapped each point onto another point of identical
            // colour and the render was mathematically invariant — it turned perfectly and looked
            // frozen. Any archetype whose surface is pure banding needs marks like these or it will
            // read as broken in exactly the same way.
            for (const [x, y, rx, ry, rot, col, al] of [[-0.44, -0.3, 0.22, 0.1, 0.12, '#fff6e2', 0.5],
              [0.36, 0.16, 0.28, 0.11, -0.09, '#6b4c2c', 0.42], [0.02, 0.55, 0.17, 0.075, 0.05, '#ffeccb', 0.4],
              [-0.2, 0.02, 0.13, 0.06, 0.2, '#8a6740', 0.35]]) {
              ctx.beginPath(); ctx.ellipse(c + br * x, c + br * y, br * rx, br * ry, rot, 0, Math.PI * 2)
              ctx.globalAlpha = al; ctx.fillStyle = col; ctx.fill()
            }
            ctx.globalAlpha = 1
          },
          behind(ctx, c, R) { ringAnnulus(ctx, c, R, 'far') },
          // The near half and nothing else. There used to be a "ring shadow" here — one flat ellipse
          // of rgba(6,4,14,0.45) clipped to the body — and it was the black stripe painted across
          // the planet in every capture: 45% black, limb to limb, at its OWN angle rather than the
          // ring's, drawn ON TOP of the pale near-ring bands that were supposed to be the read. The
          // near half crossing the disc is already the depth cue; the shadow only hid it.
          front(ctx, c, R) { ringAnnulus(ctx, c, R, 'near') },
        },
        { // H. rust desert — the driest thing here: one dust-hazed sky, one dirty cap, two moons.
          base: '#b8703f', polar: '#6d3c22',
          halo: '255,170,110', haloA: 0.14,
          // Two, and both small: a pair of captured rocks says "desert world" harder than one big moon.
          moons: [[0.08, 1.16, '#42302a', '#c2a494'], [0.055, 1.36, '#3a2a24', '#ab8f80']],
          surface(ctx, c, br) {
            cap(ctx, true, 0.12, '236,244,255', 0.55)   // one thin dirty cap: not an ice world, but not airless either
            for (const [x, y, rx, ry, rot, al] of [[-0.3, -0.3, 0.5, 0.3, 0.4, 0.45],
              [0.34, 0.1, 0.42, 0.26, -0.3, 0.38], [-0.1, 0.52, 0.46, 0.22, 0.2, 0.42]]) {
              ctx.beginPath(); ctx.ellipse(c + br * x, c + br * y, br * rx, br * ry, rot, 0, Math.PI * 2)
              ctx.fillStyle = '#8c4d29'; ctx.globalAlpha = al; ctx.fill()
            }
            ctx.globalAlpha = 1
            ctx.lineCap = 'round'
            // Canyons: the one hard-edged mark on an otherwise hazy body, so it still reads as rock.
            for (const path of [[[-1, 0.1], [-0.4, 0.02], [0.1, 0.22], [1, 0.1]],
              [[-0.5, -0.6], [-0.2, -0.3], [-0.3, 0.1]],
              [[0.2, -0.8], [0.42, -0.4], [0.3, 0.04], [0.5, 0.5]]]) {
              ctx.beginPath()
              path.forEach(([x, y], k) => (k ? ctx.lineTo(c + br * x, c + br * y) : ctx.moveTo(c + br * x, c + br * y)))
              ctx.strokeStyle = 'rgba(74,35,18,0.55)'; ctx.lineWidth = br * 0.035; ctx.stroke()
              ctx.strokeStyle = 'rgba(255,206,160,0.3)'; ctx.lineWidth = br * 0.012; ctx.stroke()
            }
          },
        },
        { // I. toxic — the sickly one. Sulphur yellows nothing else in the set uses.
          base: '#93b83c', polar: '#43601f',
          halo: '180,255,90', haloA: 0.3,
          surface(ctx, c, br) {
            // Sulphur haze belts UNDER the arcs: at gameplay size a planet is ~470px of smooth shaded
            // sphere, and four thin arcs on a flat albedo washed out into a plain green ball. The
            // belts give it structure everywhere, the arcs give it weather on top.
            for (const [oy, ry, al, col] of [[-0.55, 0.16, 0.34, '#d9f27a'], [-0.05, 0.2, 0.3, '#4d6b1c'],
              [0.42, 0.15, 0.32, '#e4ff9a'], [0.8, 0.12, 0.28, '#3d5616']]) band(ctx, oy, ry, col, al)
            ctx.lineCap = 'round'
            // Churning cloud bands, drawn as thick open arcs so the whole surface looks like it moves.
            for (const [x, y, r, a0, a1, col, lw] of [[-0.2, -0.3, 0.5, 0.2, 3.6, 'rgba(238,255,170,0.75)', 0.14],
              [0.3, 0.2, 0.44, 2.4, 5.6, 'rgba(96,132,36,0.8)', 0.16], [-0.1, 0.55, 0.4, 3.4, 6.1, 'rgba(238,255,170,0.6)', 0.12],
              [0.1, -0.68, 0.36, 0.6, 3.0, 'rgba(112,158,40,0.75)', 0.13]]) {
              ctx.beginPath(); ctx.arc(c + br * x, c + br * y, br * r, a0, a1)
              ctx.strokeStyle = col; ctx.lineWidth = br * lw; ctx.stroke()
            }
            for (const [x, y, r] of [[0.24, -0.22, 0.16], [-0.42, 0.28, 0.12]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(246,255,200,0.8)', 'rgba(200,255,120,0)')
            }
          },
        },
        { // J. storm — deep blue with white cyclones. The only body whose features are SPIRALS.
          base: '#3f5db8', polar: '#1b2a63',
          halo: '150,180,255', haloA: 0.24,
          surface(ctx, c, br) {
            ctx.lineCap = 'round'
            for (const [cx, cy, rr] of [[-0.28, -0.24, 0.34], [0.34, 0.22, 0.28], [0.06, 0.66, 0.2], [0.5, -0.44, 0.18]]) {
              // Each cyclone is three tightening arcs — a spiral without a spiral primitive.
              for (let k = 0; k < 3; k++) {
                ctx.beginPath()
                ctx.arc(c + br * cx, c + br * cy, br * rr * (1 - k * 0.28), k * 1.9, k * 1.9 + 4.1)
                ctx.strokeStyle = `rgba(238,246,255,${0.45 + k * 0.2})`
                ctx.lineWidth = br * (0.062 - k * 0.008); ctx.stroke()
              }
              glowBlob(ctx, c + br * cx, c + br * cy, br * rr * 0.3, 'rgba(255,255,255,0.5)', 'rgba(255,255,255,0)')
            }
          },
        },
        // ---- v5.23.3: five more worlds. All authored MAP-NATIVE from the start — belts go through
        // band(), nothing uses a full-width ellipse (it would taper to a point at the seam), nothing
        // bakes a light direction (the shader owns that), and no surface is pure banding (that is
        // invariant under its own rotation — see the ringed world). ------------------------------
        { // K. jungle — the only LIVING green. Toxic (I) is a sulphur yellow-green; this is deep
          // emerald under canopy, and at gameplay size the two never read as the same world.
          base: '#2f7a48', polar: '#14361f',
          halo: '150,255,180', haloA: 0.2,
          moons: [[0.12, 1.2, '#2d3a2c', '#a8bc9c']],
          surface(ctx, c, br) {
            for (const pts of [[[-0.62, -0.4], [-0.12, -0.55], [0.2, -0.25], [-0.05, 0.05], [-0.5, 0]],
              [[0.2, 0.1], [0.68, 0], [0.8, 0.34], [0.42, 0.58], [0.14, 0.4]],
              [[-0.72, 0.34], [-0.32, 0.3], [-0.18, 0.68], [-0.66, 0.78]]]) {
              landmass(ctx, c, br, pts, 'rgba(22,74,38,0.75)', 'rgba(126,200,110,0.4)')
            }
            // A savannah belt so the canopy is not the only green — two greens plus tan, not one.
            for (const pts of [[[-0.5, 0.46], [-0.02, 0.4], [0.16, 0.62], [-0.3, 0.74]],
              [[0.34, -0.5], [0.7, -0.44], [0.72, -0.2], [0.36, -0.24]]]) {
              landmass(ctx, c, br, pts, 'rgba(160,166,84,0.6)', null)
            }
            ctx.lineCap = 'round'
            // Rivers are the one BRIGHT mark, so the canopy reads as wet rather than merely dark.
            for (const path of [[[-0.5, -0.5], [-0.3, -0.15], [-0.4, 0.2], [-0.15, 0.55]],
              [[0.5, -0.2], [0.34, 0.1], [0.5, 0.4]], [[-0.05, -0.7], [0.1, -0.35], [-0.02, -0.05]]]) {
              ctx.beginPath()
              path.forEach(([x, y], k) => (k ? ctx.lineTo(c + br * x, c + br * y) : ctx.moveTo(c + br * x, c + br * y)))
              ctx.strokeStyle = 'rgba(120,200,220,0.55)'; ctx.lineWidth = br * 0.022; ctx.stroke()
            }
            for (const [x, y, r] of [[0, -0.15, 0.12], [-0.55, 0.55, 0.1]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(190,255,170,0.35)', 'rgba(150,255,150,0)')
            }
          },
        },
        { // L. machine — the only BUILT world here. Everything else is geology or weather, so
          // straight edges and running lights are the whole read at a glance.
          base: '#59626e', polar: '#2b3138',
          halo: '150,200,255', haloA: 0.1,
          surface(ctx, c, br) {
            for (const [oy, ry, al, col] of [[-0.62, 0.08, 0.35, '#7d8794'], [-0.2, 0.1, 0.3, '#3f4750'],
              [0.24, 0.09, 0.32, '#79838f'], [0.66, 0.08, 0.28, '#3a424b']]) band(ctx, oy, ry, col, al)
            // Panels, not continents: axis-aligned rectangles are the cheapest "manufactured" there is.
            ctx.globalAlpha = 0.4
            for (const [x, y, pw, ph, col] of [[-0.55, -0.35, 0.32, 0.16, '#8b95a2'], [0.1, -0.5, 0.26, 0.12, '#39414a'],
              [0.4, 0.05, 0.36, 0.2, '#8b95a2'], [-0.3, 0.3, 0.28, 0.14, '#39414a'],
              [-0.7, 0.55, 0.22, 0.1, '#8b95a2'], [0.05, 0.52, 0.3, 0.13, '#6f7883']]) {
              ctx.fillStyle = col; ctx.fillRect(c + br * x, c + br * y, br * pw, br * ph)
            }
            ctx.globalAlpha = 1
            // Full-width seams: constant latitude, so they meet themselves across the mirror.
            ctx.strokeStyle = 'rgba(24,28,33,0.55)'; ctx.lineWidth = br * 0.012
            for (const y of [-0.45, -0.05, 0.42]) {
              ctx.beginPath(); ctx.moveTo(c - br, c + br * y); ctx.lineTo(c + br, c + br * y); ctx.stroke()
            }
          },
          emissive(ctx, c, br) {
            ctx.fillStyle = 'rgba(120,240,255,0.95)'
            for (const [x, y, n] of [[-0.55, -0.28, 7], [0.42, 0.12, 8], [-0.3, 0.37, 6], [0.08, 0.58, 5]]) {
              for (let k = 0; k < n; k++) ctx.fillRect(c + br * (x + k * 0.045), c + br * y, br * 0.016, br * 0.016)
            }
            for (const [x, y, r] of [[0.5, -0.4, 0.14], [-0.15, 0.05, 0.12]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(120,240,255,0.5)', 'rgba(80,200,255,0)')
            }
          },
        },
        { // M. crystal — the ANGULAR one. Every other body in the set is made of curves, so a
          // surface of straight facets is the fastest thing to tell apart at gameplay size. Its
          // rings are a shard belt: narrower, tipped the OTHER way from the other two ringed worlds.
          bodyR: 0.62, pole: ringPole(-0.62),
          base: '#6d55a8', polar: '#2b1f4d',
          halo: '205,165,255', haloA: 0.3,
          behind(ctx, c, R) { ringAnnulus(ctx, c, R, 'far', -0.62, SHARD_RINGS) },
          front(ctx, c, R) { ringAnnulus(ctx, c, R, 'near', -0.62, SHARD_RINGS) },
          surface(ctx, c, br) {
            for (const [pts, col, al] of [
              [[[-0.7, -0.45], [-0.25, -0.62], [-0.05, -0.2], [-0.45, -0.05]], '#a98ce0', 0.55],
              [[[0.05, -0.55], [0.5, -0.4], [0.42, 0.02], [0.02, -0.1]], '#4a3578', 0.5],
              [[[-0.6, 0.1], [-0.15, 0.05], [-0.05, 0.5], [-0.5, 0.62]], '#b79ded', 0.4],
              [[[0.15, 0.15], [0.62, 0.22], [0.5, 0.66], [0.1, 0.55]], '#54407f', 0.5],
              [[[-0.2, -0.9], [0.15, -0.8], [0.05, -0.5], [-0.25, -0.55]], '#c6b1f5', 0.45]]) {
              ctx.beginPath()
              pts.forEach(([x, y], k) => (k ? ctx.lineTo(c + br * x, c + br * y) : ctx.moveTo(c + br * x, c + br * y)))
              ctx.closePath()
              ctx.globalAlpha = al; ctx.fillStyle = col; ctx.fill()
              ctx.globalAlpha = 0.5; ctx.strokeStyle = '#e2d4ff'; ctx.lineWidth = br * 0.008; ctx.stroke()
            }
            ctx.globalAlpha = 1
          },
        },
        { // N. veiled — the SMOOTH one. Against a set of busy surfaces a near-featureless haze is
          // the most distinctive thing left, and it carries the thickest atmosphere here to sell it.
          base: '#d8bd88', polar: '#a5843d',
          halo: '255,232,175', haloA: 0.36,
          surface(ctx, c, br) {
            ctx.lineCap = 'round'
            // Broad, soft and low-contrast — but deliberately NOT banded. Pure banding is invariant
            // under this planet's own rotation and would look frozen however fast it actually turns.
            for (const [x, y, r, a0, a1, col, lw] of [[-0.3, -0.35, 0.62, 0.3, 2.7, 'rgba(255,244,205,0.3)', 0.2],
              [0.35, 0.05, 0.55, 2.6, 5.4, 'rgba(168,132,61,0.28)', 0.22],
              [-0.15, 0.6, 0.5, 3.3, 6, 'rgba(255,240,195,0.24)', 0.18],
              [0.2, -0.7, 0.42, 0.5, 3.1, 'rgba(180,146,74,0.22)', 0.16]]) {
              ctx.beginPath(); ctx.arc(c + br * x, c + br * y, br * r, a0, a1)
              ctx.strokeStyle = col; ctx.lineWidth = br * lw; ctx.stroke()
            }
            for (const [x, y, r] of [[-0.4, 0.2, 0.28], [0.45, -0.35, 0.22]]) {
              glowBlob(ctx, c + br * x, c + br * y, br * r, 'rgba(255,250,220,0.3)', 'rgba(255,240,190,0)')
            }
          },
        },
        { // O. iron — rust (H) is a bright dusty desert; this is dark oxidised metal, near-black in
          // its lowlands, where the pale mineral veins are the only thing that catches the star.
          base: '#7d3529', polar: '#2f110d',
          halo: '255,120,80', haloA: 0.14,
          moons: [[0.13, 1.25, '#2a1a18', '#9c8078']],
          surface(ctx, c, br) {
            for (const [x, y, rx, ry, rot] of [[-0.35, -0.28, 0.44, 0.34, 0.3], [0.38, 0.14, 0.4, 0.3, -0.25],
              [-0.1, 0.55, 0.38, 0.26, 0.15], [0.3, -0.6, 0.28, 0.2, 0.4]]) {
              ctx.beginPath(); ctx.ellipse(c + br * x, c + br * y, br * rx, br * ry, rot, 0, Math.PI * 2)
              ctx.globalAlpha = 0.68; ctx.fillStyle = '#2a100c'; ctx.fill()
            }
            ctx.globalAlpha = 1
            ctx.lineCap = 'round'
            for (const path of [[[-1, -0.1], [-0.35, -0.25], [0.05, 0], [0.55, -0.15], [1, -0.1]],
              [[-0.4, -0.75], [-0.2, -0.35], [-0.35, 0.1], [-0.15, 0.6]],
              [[0.45, -0.5], [0.6, -0.1], [0.42, 0.3], [0.62, 0.7]]]) {
              ctx.beginPath()
              path.forEach(([x, y], k) => (k ? ctx.lineTo(c + br * x, c + br * y) : ctx.moveTo(c + br * x, c + br * y)))
              ctx.strokeStyle = 'rgba(232,186,158,0.7)'; ctx.lineWidth = br * 0.034; ctx.stroke()
              ctx.strokeStyle = 'rgba(255,240,226,0.75)'; ctx.lineWidth = br * 0.011; ctx.stroke()
            }
          },
        },
      ]
      // Parallel arrays indexed by variant: the lat/long albedo, its emissive twin, the two
      // off-sphere overlays, the body radius the mesh scales to, and the rim colour.
      // `spin` is gone — every archetype turns now, the ringed one included: a ring does not follow
      // its planet's rotation, so the annulus simply stays a still sprite while the body turns
      // inside it, which is what a real ringed world does.
      T.planetMaps = PLANET_ARCHETYPES.map((a) => planetMapTex(a, false))
      T.planetEmitNone = canvasTex(1, 1, () => {})   // fully transparent: adds nothing
      T.planetEmits = PLANET_ARCHETYPES.map((a) => (a.emissive ? planetMapTex(a, true) : T.planetEmitNone))
      T.planetBehind = PLANET_ARCHETYPES.map((a) => (a.behind ? planetOverlayTex(a, false) : null))
      T.planetFront = PLANET_ARCHETYPES.map((a) => (a.halo || a.front ? planetOverlayTex(a, true) : null))
      T.planetBodyR = PLANET_ARCHETYPES.map((a) => a.bodyR ?? PLANET_BODY)
      T.planetPole = PLANET_ARCHETYPES.map((a) => a.pole || null)   // null = hash a random tilt per planet
      // Moons, one texture each: [radius, orbit radius] both as a fraction of R, so the runtime
      // scales them off o.r exactly like the overlays. 128px is well past the ~34px a 0.13R moon
      // occupies on a 260px world — a moon crossing the limb is the one place the eye lingers.
      // Every orbit radius is >1.1, i.e. OUTSIDE the body (PLANET_BODY is 0.90) and outside its
      // halo. Under that, the foreshortened orbit never clears the limb and the moon only ever
      // reads as a spot painted on the face or as nothing at all — which is what it was before.
      T.planetMoons = PLANET_ARCHETYPES.map((a) => (a.moons || []).map(([mr, dist, dark, lit]) => ({
        tex: canvasTex(128, 128, (ctx, w) => moon(ctx, w / 2, w / 2, w / 2, dark, lit)), mr, dist,
      })))
      // Rim colour comes straight off the archetype's own atmosphere, so the limb glow and the halo
      // sprite around it are the same hue. The moon has no atmosphere and gets a black rim — which
      // is correct, not a gap: an airless body has no limb glow, and that is its whole read.
      T.planetAtmo = PLANET_ARCHETYPES.map((a) => {
        if (!a.halo) return new Float32Array([0, 0, 0])
        const k = a.haloA * 2.2   // haloA is tuned for a 2D alpha fade; the rim is an ADD, so it needs lifting
        return new Float32Array(a.halo.split(',').map((n) => (Number(n) / 255) * k))
      })
      T.planetTints = PLANET_TINTS
    }
    {
      // house (suburbs district, skies — v5.7.x): the one hand-drawn suburbs prop besides the
      // fence (the district's "car" reuses T.car below, already drawn for the city's traffic
      // lanes). Low box + pitched roof, one door, one window. Upright, origin at the base.
      const g = new Graphics()
      const wall = 0xc9b08a
      const roof = 0x7a4a3a
      const line = 0x3a2a1e
      g.rect(-20, -26, 40, 26).fill(wall).stroke({ width: 2, color: line })          // wall block
      g.poly([-24, -26, 0, -44, 24, -26]).fill(roof).stroke({ width: 2, color: line }) // pitched roof
      g.rect(-5, -14, 10, 14).fill(0x4a3324).stroke({ width: 1.4, color: line })     // door
      g.rect(9, -20, 8, 8).fill(0x8fc4e0).stroke({ width: 1.2, color: line })        // window
      g.rect(-24, -26, 48, 3).fill({ color: 0x000000, alpha: 0.18 })                 // eave shadow
      g.poly([-24, -26, 0, -44, -12, -40]).fill({ color: 0x9a6a52, alpha: 0.35 })    // lit roof face
      T.house = bake(g)
    }
    {
      // picket fence (suburbs district, skies): three posts + two rails, origin at the base.
      const g = new Graphics()
      const wood = 0xc4b190
      const line = 0x5a4c34
      for (const x of [-18, 0, 18]) g.rect(x - 2, -20, 4, 20).fill(wood).stroke({ width: 1.4, color: line })
      g.rect(-20, -16, 40, 4).fill(wood).stroke({ width: 1.2, color: line })
      g.rect(-20, -7, 40, 4).fill(wood).stroke({ width: 1.2, color: line })
      T.fence = bake(g)
    }
    // ---- pier kind props (sea district, skies — v5.8 kaiju redesign) ----------------------------
    // Sea's obstacle skin used to be a plain rock (a low-effort placeholder — see the sea entry's
    // ponytail note in DISTRICT_BIOMES below); now it's crushable dock furniture, same "flat baked
    // vector" idiom as every other structure kind. All three are drawn top-down and MASS-CENTRED —
    // like rubble/rockChunk/asteroid, not base-anchored like house/hydrant — because they read as
    // things floating/sitting ON open water, not planted upright on ground.
    {
      // jetty: a short wooden dock plank on pilings.
      const g = new Graphics()
      const wood = 0xa9835a
      const line = 0x4a3420
      g.poly([-26, -7, 20, -9, 26, -1, 22, 8, -22, 9, -27, 1]).fill(wood).stroke({ width: 1.8, color: line }) // deck planking
      g.beginPath() // plank seams
      for (let x = -16; x <= 12; x += 8) g.moveTo(x, -8).lineTo(x - 1.5, 8.5)
      g.stroke({ width: 1, color: line, alpha: 0.4 })
      for (const [x, y] of [[-19, 8], [0, 9], [17, 6]]) g.rect(x - 2, y, 4, 7).fill({ color: 0x2e2216, alpha: 0.65 }) // pilings, dipping below the deck into the water
      g.poly([-24, -8, 18, -9, 22, -2, -20, -1]).fill({ color: 0xceac7f, alpha: 0.35 }) // lit top face
      T.jetty = bake(g)
    }
    {
      // boat: a small wooden rowboat, drifted loose.
      const g = new Graphics()
      const hull = 0x8a5a3a
      const line = 0x3f2a18
      g.poly(spineOutline((t) => [-19 + t * 38, 0], (t) => 9.5 * bulge(0.05 + 0.9 * t, 0.55), 20))
        .fill(hull).stroke({ width: 1.8, color: line })                                          // hull
      g.poly(spineOutline((t) => [-12 + t * 24, 0], (t) => 5.2 * bulge(0.08 + 0.84 * t, 0.5), 14))
        .fill({ color: 0x5f6f52, alpha: 0.85 }).stroke({ width: 1.2, color: line })               // open well
      g.beginPath().moveTo(0, -5.2).lineTo(0, 5.2).stroke({ width: 1.4, color: line, alpha: 0.6 }) // centre thwart
      g.ellipse(-2, -3, 8, 2.6).fill({ color: 0xc9a578, alpha: 0.4 })                              // lit gunwale
      T.boat = bake(g)
    }
    {
      // buoy: a small striped mooring float bobbing on the water.
      const g = new Graphics()
      const red = 0xd8452f
      const line = 0x6e2318
      g.circle(0, 0, 9).fill(red).stroke({ width: 1.6, color: line })
      g.poly([-9, -2, 9, -2, 9, 2, -9, 2]).fill({ color: 0xf2ece0, alpha: 0.9 }) // white stripe band
      g.circle(0, -9, 2.4).fill(red).stroke({ width: 1.2, color: line })        // top nub
      g.ellipse(-3, -3, 3, 2).fill({ color: 0xffffff, alpha: 0.4 })             // sheen
      T.buoy = bake(g)
    }
    // ---- barn/silo kind props (farms district, skies — v5.9 top-down region overhaul) ----------
    // Same hand-drawn baked-vector idiom as T.house right above: solid fill, dark outline, one lit
    // face. Upright, base-anchored (STRUCTURE_KINDS' 'barn'/'silo', config.js).
    {
      // barn: a low wall block under a gambrel roof, hay-loft door on the gable end.
      const g = new Graphics()
      const wall = 0x9c3f30
      const roof = 0x5a3226
      const line = 0x2e1a14
      g.rect(-26, -30, 52, 30).fill(wall).stroke({ width: 2.2, color: line })                       // wall block
      g.poly([-30, -30, -14, -46, 0, -38, 14, -46, 30, -30]).fill(roof).stroke({ width: 2.2, color: line }) // gambrel roof
      g.rect(-8, -16, 16, 16).fill(0x2e1a14).stroke({ width: 1.6, color: line })                    // hay-loft door
      g.rect(-30, -30, 60, 3).fill({ color: 0x000000, alpha: 0.2 })                                 // eave shadow
      g.poly([-30, -30, -14, -46, -20, -42]).fill({ color: 0xc06a52, alpha: 0.35 })                 // lit roof face
      T.barn = bake(g)
    }
    {
      // silo: a narrow cylinder under a faceted dome, ring seams down the body.
      const g = new Graphics()
      const metal = 0xc7c9cc
      const line = 0x53565a
      g.rect(-11, -40, 22, 40).fill(metal).stroke({ width: 2, color: line })                        // body
      g.poly([-11, -40, 0, -54, 11, -40]).fill(0xa7aaad).stroke({ width: 2, color: line })           // domed cap
      for (let y = -34; y <= -6; y += 8) {
        g.beginPath().moveTo(-11, y).lineTo(11, y).stroke({ width: 1, color: line, alpha: 0.35 })    // ring seams
      }
      g.rect(-11, -40, 6, 40).fill({ color: 0xffffff, alpha: 0.22 })                                 // lit left flank
      g.rect(5, -40, 6, 40).fill({ color: 0x000000, alpha: 0.18 })                                   // shaded right flank
      T.silo = bake(g)
    }
    {
      // tractor (farms): a boxy cab + oversized rear wheels, nose +x — same top-down vehicle
      // idiom as T.car (below) but boxier, slower-looking, farm green. Reuses PROP_SCALE.car's
      // band (a working vehicle, same tier as a parked car) rather than getting its own class.
      const g = new Graphics()
      const body = 0x5a8f3d
      const line = 0x2e4a1e
      g.rect(-6, -9, 20, 18).fill(body).stroke({ width: 2, color: line })                            // body/cab block
      g.rect(10, -6, 8, 12).fill({ color: 0x2b3a4a, alpha: 0.85 }).stroke({ width: 1.4, color: line }) // cab glass
      for (const s of [-1, 1]) {
        g.circle(-8, s * 10, 6).fill(0x232323).stroke({ width: 1.6, color: line })                   // big rear wheels
        g.circle(12, s * 7, 3.4).fill(0x232323).stroke({ width: 1.2, color: line })                  // small front wheels
      }
      g.ellipse(0, -3, 10, 4).fill({ color: 0x86c25a, alpha: 0.3 })                                  // lit flank
      T.tractor = bake(g)
    }
    {
      // crop tuft (farms): the "crop row" signature prop — a tiny fan of blades drawn ALONG +x so
      // applyPropKind's cropRow branch (rotation locked to the field's shared row angle, see
      // farmRowSnap below) lays it flat along the furrow instead of spinning freely like every
      // other top-down scatter prop. Filled white so kind.tints drives the colour per instance
      // (golden wheat / green leaf-row / tilled-brown row — CROP_TINTS below, darkened v5.11 —
      // see that array's own comment).
      // v5.11: a low-alpha soil patch drawn FIRST, visible only in the gaps BETWEEN the opaque
      // blades — that two-tone (bright blade / dark soil peeking through) is the actual "furrow"
      // texture a single flat-alpha silhouette never had, at zero extra draw calls per instance
      // (still one bake). Bring-the-value-down half of the fix is CROP_TINTS itself.
      const g = new Graphics()
      g.ellipse(0, 1, 7, 3.4).fill({ color: 0x000000, alpha: 0.22 })
      for (const [dy, len] of [[-2.6, 9], [0, 11], [2.6, 8.5]]) {
        taperStroke(g, [[-len * 0.4, dy], [len * 0.6, dy * 0.4]], 2.4, 0.6, 0xffffff, 3)
      }
      g.ellipse(-3, 0, 3, 2).fill({ color: 0xffffff, alpha: 0.55 }) // base clump
      T.cropTuft = bake(g)
    }
    {
      // hay bale (farms): a round baled bundle, top-down — a filled disc with wrap-line chords.
      // Spins freely (not upright), like puddle/asteroid.
      const g = new Graphics()
      const straw = 0xc9a94a
      const line = 0x8a6f2e
      g.circle(0, 0, 11).fill(straw).stroke({ width: 1.6, color: line })
      for (const a of [-0.6, 0, 0.6]) {
        g.beginPath().moveTo(Math.cos(a + 1.2) * 11, Math.sin(a + 1.2) * 11)
        g.lineTo(Math.cos(a - 1.9) * 11, Math.sin(a - 1.9) * 11).stroke({ width: 1, color: line, alpha: 0.5 })
      }
      g.ellipse(-3, -3, 4, 3).fill({ color: 0xe8cf8a, alpha: 0.5 })
      T.hayBale = bake(g)
    }
    {
      // elevation contour (hills district, skies): elevation read from directly overhead as soft
      // concentric shading bands, NOT a side-view hill silhouette — a bump drawn in profile would
      // read as floating debris from this camera angle. Same "value over silhouette" trick the
      // rockChunk/asteroid props already use for their lit/shaded faces, just pushed further: soft
      // alpha ellipses, lightest at the crest, a darker downslope shadow on one side.
      const g = new Graphics()
      const hi = 0xcabb96
      const lo = 0x6b5a44
      g.ellipse(0, 0, 90, 62).fill({ color: hi, alpha: 0.16 })
      g.ellipse(-6, -5, 62, 42).fill({ color: hi, alpha: 0.20 })
      g.ellipse(-10, -8, 34, 22).fill({ color: hi, alpha: 0.26 })
      g.ellipse(18, 20, 46, 28).fill({ color: lo, alpha: 0.18 }) // shaded downslope
      T.contour = bake(g)
    }
    // ---- road strips (skies only) ---------------------------------------------------------------
    // The carriageway tiles (T.roadMinor/Major/Highway) are baked by buildSkiesTextures() below and
    // declared there and nowhere else: one tile pitch long by the street's own width, at TRUE world
    // size, laid along a whole street run by updateStreets as a TilingSprite. Long axis is +x, which
    // matches roadAt's convention (angle 0 = a street running along x). Anything with a SHAPE —
    // manholes, patches, arrows, crosswalks — is a separate decal or junction sprite, because those
    // vary along the street and a repeating tile by definition cannot.
    {
      // obstacle footprint (v5.6.10): the collision contract, drawn HARD where every decor shadow is
      // soft. A subtly darkened packed-earth pad plus a crisp rim ring sitting on the collider edge,
      // so a player learns "this stops me" by eye, not only by bumping it. Baked in greyscale at a
      // reference radius and multiplied by each biome's `foot` colour (chosen for contrast, dark on
      // pale floors / pale on dark floors); syncObstacles scales it by o.r/ref so the rim lands
      // EXACTLY on o.r — what the sim tests is what the eye sees.
      const g = new Graphics()
      const REF = 100
      g.circle(0, 0, REF).fill({ color: 0xffffff, alpha: 0.30 })                       // occlusion pad
      g.circle(0, 0, REF * 0.62).fill({ color: 0xffffff, alpha: 0.16 })                // deeper toward centre
      g.circle(0, 0, REF).stroke({ width: REF * 0.14, color: 0xffffff, alpha: 1 })     // hard rim ON the edge
      T.obFoot = { ...bake(g), ref: REF }
    }
    // ---- body interior props (v5.6) ----------------------------------------
    // The Body is the intro chapter: a pale warm-cream floor (0xf4efe6) walked by soft-red cells,
    // a pale white cell and an amber antibody. Its floor furniture is anatomy, not botany — but it
    // must stay DECOR: every fill sits low-contrast on the floor (measured 1.1-1.6x WCAG luminance)
    // and far below every enemy (3.9-6.4x), in a warm pink/rose/cream band hue-clear of the red
    // cell, so a platelet is never mistaken for a cell in peripheral vision. Soft fills, no hard
    // dark outlines — a dark edge is the enemy read, so props carry themselves on value alone.
    {
      // villi mound (big): a tuft of rounded intestinal villi rising off the floor. Each finger is a
      // spine with a mild lean, a gentle taper and a ROUND cap (blunt, never a spike), over a soft
      // basal mound. Fixed per-bake jitter (like pebble) so no two fingers match. Origin at the base.
      const g = new Graphics()
      const body = 0xe8b6c1
      const hi = 0xf0cbd3
      g.ellipse(1, -4, 27, 9).fill({ color: body, alpha: 0.85 }) // basal mound, drawn first
      const fingers = [[-19, 30, 0.42], [-9, 44, 0.16], [3, 51, 0.61], [13, 42, 0.28], [22, 29, 0.53]]
      for (const [bx, h, seed] of fingers) {
        const lean = (hash(seed * 7.1 + 2.3) - 0.5) * 11
        const wob = 0.78 + hash(seed * 3.7 + 1.1) * 0.42
        const spine = (t) => [bx + lean * t * t, -t * h]
        g.poly(spineOutline(spine, (t) => 6.6 * wob * (1 - 0.34 * t), 14)).fill(body) // stalk
        g.circle(bx + lean, -h, 4.6 * wob).fill(body)                                  // round cap
        g.ellipse(bx + lean - 1.6, -h - 1.4, 2.1 * wob, 2.8 * wob).fill({ color: hi, alpha: 0.5 }) // lit tip
      }
      T.villi = bake(g)
    }
    {
      // vesicle cluster (big): a grape-bunch of translucent transport vesicles. Overlapping alpha
      // discs darken where they stack, so the bunch reads without any hard line; each carries a soft
      // pale specular. Top-down, spins freely.
      const g = new Graphics()
      const wall = 0xe3b7c2
      const hi = 0xf3dde3
      const bubs = [[0, 1, 15], [-15, 6, 11], [13, 8, 12], [-6, -13, 9], [8, -11, 9], [-19, -5, 7], [3, 16, 8], [18, -4, 7]]
      for (const [x, y, r] of bubs) {
        g.circle(x, y, r).fill({ color: wall, alpha: 0.5 }).stroke({ width: 1.1, color: wall, alpha: 0.55 })
        g.circle(x - r * 0.32, y - r * 0.34, r * 0.28).fill({ color: hi, alpha: 0.7 }) // specular
      }
      T.vesicles = bake(g)
    }
    {
      // platelet (mid/detail): a small irregular disc — a lumpy rounded plate with a paler granular
      // centre. Blunt lobed outline, no hard edge. Reused small + dimmed on the detail layer.
      const g = new Graphics()
      const fill = 0xe7bcc4
      const shape = (a) => 11 * (0.86 + 0.1 * Math.cos(a * 3 + 0.7) + 0.06 * Math.sin(a * 5 - 1.3))
      g.poly(radialOutline(shape, 34)).fill(fill)
      g.ellipse(-1.5, -1.5, 5.5, 4.5).fill({ color: 0xf3d6db, alpha: 0.6 }) // pale granular centre
      T.platelet = bake(g)
    }
    {
      // lipid droplet (mid): a soft fat globule — pale cream fill, a bright rim arc on the lit side
      // and a round specular, a soft shaded base opposite. Reads as an oily bead. Top-down.
      const g = new Graphics()
      const cream = 0xefd9c8
      const rim = 0xf6ead9
      const shape = (a) => 13 * (0.94 + 0.05 * Math.cos(a * 2 + 0.4))
      g.poly(radialOutline(shape, 32)).fill(cream)
      g.ellipse(3, 4, 6, 4).fill({ color: 0xe4c3b4, alpha: 0.35 })                                      // shaded base
      g.beginPath().arc(0, 0, 12, Math.PI * 0.85, Math.PI * 1.72).stroke({ width: 2, color: rim, alpha: 0.7, cap: 'round' }) // lit rim
      g.circle(-4, -4.5, 3).fill({ color: rim, alpha: 0.8 })                                            // specular
      T.lipid = bake(g)
    }
    {
      // capillary squiggle (mid/detail): a thin branching vessel. taperStroke narrows toward every
      // tip so it reads as a vessel and not a scribble, with a faint lighter lumen down the main run.
      const g = new Graphics()
      const vein = 0xe6b5bd
      taperStroke(g, [[-24, 6], [-10, -4], [4, 2], [16, -6], [26, -2]], 4.2, 1.4, vein, 4) // main run
      taperStroke(g, [[4, 2], [9, 12], [17, 17]], 3, 1, vein, 3)                            // lower branch
      taperStroke(g, [[-10, -4], [-13, -14], [-9, -22]], 2.6, 0.9, vein, 3)                 // upper branch
      taperStroke(g, [[-22, 5], [-9, -3], [4, 1.5], [15, -5]], 1.3, 0.6, 0xf0cbd3, 4)       // lumen
      T.capillary = bake(g)
    }
    {
      // plasma mote (detail): a tiny drifting plasma blob — a soft disc with a paler core. Kept very
      // low alpha at populate time so it barely stains the floor.
      const g = new Graphics()
      g.circle(0, 0, 6).fill({ color: 0xecc9cf, alpha: 0.75 })
      g.circle(-1.2, -1.2, 2.4).fill({ color: 0xf6ead9, alpha: 0.7 })
      T.mote = bake(g)
    }

    // ---- v5.4 signature/weapon props ---------------------------------------
    // snap traps (undergrowth signature, run.traps): they damage the PLAYER AND ENEMIES, so armed
    // vs sprung has to be readable in a glance, at speed, while being chased. The two states are
    // baked as separate textures and swapped in placeTrap rather than redrawn per frame:
    //   ARMED  = jaws SPREAD WIDE with bared teeth + a pale trigger plate. Wide + toothy + bright.
    //   SPRUNG = jaws SHUT into a single closed bar, teeth hidden, dulled. Narrow + smooth + dim.
    // The silhouettes differ (a ring vs a bar), so the read survives even at a glance in the dark.
    {
      const g = new Graphics()
      const steel = 0xa8b0ba
      const line = 0x2f333a
      g.circle(0, 0, 15).fill({ color: 0x1c1f24, alpha: 0.55 })                       // pit shadow
      for (const s of [-1, 1]) { // the two open jaws: arcs sprung back, teeth pointing IN
        g.beginPath().arc(0, 0, 15, s > 0 ? -0.3 : Math.PI - 0.3, s > 0 ? 0.3 + 0 : Math.PI + 0.3)
        g.stroke({ width: 4.5, color: steel, cap: 'round' })
        g.beginPath().arc(0, 0, 15, s > 0 ? -1.15 : Math.PI - 1.15, s > 0 ? 1.15 : Math.PI + 1.15)
        g.stroke({ width: 4, color: steel, cap: 'round' })
        for (let i = -2; i <= 2; i++) { // bared teeth, tapering inward
          const a = (s > 0 ? 0 : Math.PI) + i * 0.42
          taperStroke(g, [[Math.cos(a) * 14, Math.sin(a) * 14], [Math.cos(a) * 7.5, Math.sin(a) * 7.5]], 2.6, 0.8, steel, 2)
        }
      }
      g.circle(0, 0, 6).fill(0xd8cfb0).stroke({ width: 1.6, color: line })            // trigger plate
      g.circle(0, 0, 2.2).fill({ color: line, alpha: 0.7 })
      g.beginPath().arc(0, 0, 15, 0.5, 1.1).stroke({ width: 2, color: 0x5f666f })     // spring bridge
      g.beginPath().arc(0, 0, 15, Math.PI + 0.5, Math.PI + 1.1).stroke({ width: 2, color: 0x5f666f })
      T.trapArmed = bake(g)
    }
    {
      const g = new Graphics()
      const dull = 0x6b727c
      const g2 = 0x3a3f47
      g.circle(0, 0, 12).fill({ color: 0x1c1f24, alpha: 0.4 })
      g.poly(spineOutline((t) => [-13 + t * 26, 0], (t) => 3.4 * bulge(0.12 + 0.8 * t, 0.5), 14))
        .fill(dull).stroke({ width: 1.6, color: g2 })                                 // jaws shut: one bar
      g.beginPath().moveTo(-11, 0).lineTo(11, 0).stroke({ width: 1, color: 0x8f959d, alpha: 0.6 }) // seam
      g.circle(0, 0, 4).fill({ color: g2, alpha: 0.8 })
      T.trapSprung = bake(g)
    }
    {
      // traffic car (city signature, run.lanes): top-down, nose +x, drawn at the real
      // TRAFFIC_CAR_LEN × TRAFFIC_CAR_W hitbox so what sweeps you is what you saw coming.
      const g = new Graphics()
      const body = 0xf2c53d
      const line = 0x6b4f0e
      const L = TRAFFIC_CAR_LEN
      const W = TRAFFIC_CAR_W
      for (const s of [-1, 1]) { // tyres, under the shell
        g.rect(L * 0.16, s * W * 0.42 - W * 0.06, L * 0.16, W * 0.12).fill(0x1c1f24)
        g.rect(-L * 0.3, s * W * 0.42 - W * 0.06, L * 0.16, W * 0.12).fill(0x1c1f24)
      }
      // shell: one tapered outline, blunt at the boot and narrowing over the bonnet
      g.poly(spineOutline((t) => [-L * 0.5 + t * L, 0], (t) => W * 0.44 * bulge(0.14 + 0.8 * (1 - t), 0.34), 26))
        .fill(body).stroke({ width: 2.4, color: line })
      g.poly(spineOutline((t) => [-L * 0.24 + t * L * 0.44, 0], (t) => W * 0.3 * bulge(0.2 + 0.7 * t, 0.5), 14))
        .fill(0x2b3a4a).stroke({ width: 1.6, color: line })                            // cabin glass
      g.ellipse(-L * 0.06, -W * 0.1, L * 0.18, W * 0.08).fill({ color: 0x9fd8ff, alpha: 0.35 }) // glass sheen
      g.ellipse(0, W * 0.26, L * 0.4, W * 0.14).fill({ color: 0x8a6512, alpha: 0.2 })  // shaded flank
      g.ellipse(0, -W * 0.28, L * 0.36, W * 0.1).fill({ color: 0xfae79a, alpha: 0.3 }) // lit flank
      g.beginPath() // panel seams — hairline
      g.moveTo(L * 0.28, -W * 0.3).lineTo(L * 0.28, W * 0.3)
      g.moveTo(-L * 0.32, -W * 0.32).lineTo(-L * 0.32, W * 0.32)
      g.stroke({ width: 1.2, color: 0x8a6512, alpha: 0.5 })
      for (const s of [-1, 1]) {
        g.ellipse(L * 0.45, s * W * 0.22, L * 0.04, W * 0.08).fill(0xfff6d0)          // headlights
        g.ellipse(-L * 0.47, s * W * 0.24, L * 0.03, W * 0.07).fill(0xff5545)         // tail lights
      }
      T.car = bake(g)
    }
    {
      // The Mower (garden's `mower` elite flag — see rollMowerLane in sim.js). Same contract as
      // the car above: top-down, nose +x, drawn at the REAL deck hitbox so what sweeps you is what
      // you saw coming.
      //
      // v6.6.15: rebuilt from reference photos, because v6.6.14 shipped it on a false premise —
      // "a mower is SHORT and WIDE, the opposite of the taxi". It is not. A 21-inch walk-behind is
      // 56.4in x 22.3in assembled and every top view of one is LONGER than it is wide; the old
      // 60x96 was the ratio inverted, and it read as a squashed brick. Now 160x96 with the real
      // anatomy front to back: cutting deck with the engine on it, grass bag behind, handle last.
      const g = new Graphics()
      const L = MOWER_DECK_LEN
      const W = MOWER_DECK_W
      const deck = 0xd94f3d        // domestic-machine red: the one saturated thing on a green lawn
      const line = 0x4a1b14
      const bag = 0x2b3138
      const metal = 0x9aa3ab
      // Handle last in the silhouette and FIRST in the draw order, so the deck overlaps its roots.
      for (const s of [-1, 1]) {
        g.moveTo(-L * 0.16, s * W * 0.2).lineTo(-L * 0.46, s * W * 0.26)
        g.stroke({ width: 4, color: metal, cap: 'round' })
      }
      g.moveTo(-L * 0.46, -W * 0.26).lineTo(-L * 0.46, W * 0.26)
      g.stroke({ width: 6, color: metal, cap: 'round' })
      for (const s of [-1, 1]) {   // wheels: small in front, big at the back, outside the deck
        g.roundRect(L * 0.18, s * W * 0.42 - W * 0.09, L * 0.13, W * 0.18, 3).fill(0x1c1f24)
        g.roundRect(-L * 0.12, s * W * 0.45 - W * 0.11, L * 0.15, W * 0.22, 4).fill(0x1c1f24)
      }
      // grass bag, slung behind the deck and narrower than it
      g.roundRect(-L * 0.42, -W * 0.3, L * 0.3, W * 0.6, 9).fill(bag).stroke({ width: 2.4, color: 0x171a1e })
      // the cutting deck: the widest thing on the machine, and the part that actually hits you
      g.roundRect(-L * 0.2, -W * 0.44, L * 0.68, W * 0.88, 14).fill(deck).stroke({ width: 3, color: line })
      g.roundRect(-L * 0.14, -W * 0.38, L * 0.56, W * 0.18, 8).fill({ color: 0xff9a86, alpha: 0.32 }) // lit flank
      g.ellipse(L * 0.1, W * 0.28, L * 0.24, W * 0.1).fill({ color: 0x8f2b1f, alpha: 0.26 })          // shaded flank
      g.roundRect(L * 0.4, -W * 0.34, L * 0.06, W * 0.68, 3).fill(line)                               // cutting lip
      g.circle(L * 0.06, 0, W * 0.2).fill(metal).stroke({ width: 2.5, color: line })                  // engine
      g.circle(L * 0.06, 0, W * 0.085).fill(0x30363c)
      T.mower = bake(g)
    }
    {
      // trash tornado (city, run.debris): the funnel's THROAT, seen from directly overhead — the
      // mouth as a wide pale ring, then tighter rings stepping off-centre into a near-black core,
      // so the shaft appears to lean away from you down a hole in the street.
      //
      // v6.8 first drew this as an upright side-elevation funnel (mouth at the top, tip dragging
      // the ground) which is simply the wrong projection for this camera: every other entity here
      // is seen from above. Owner picked this read from three top-down candidates shot on one
      // identical in-game frame (spiral arms / this / a bodiless debris swarm) — see
      // scripts/scenes/trash-tornado.js if it ever needs re-judging.
      //
      // The OFF-CENTRE step is what makes it work. Concentric rings drawn on a shared centre are
      // rotationally symmetric, so spinning the sprite would animate nothing at all; stepping each
      // ring sideways gives the column a direction, and the spin then reads as a throat wobbling
      // as it turns. Origin (0,0) is the sim's hit centre and bake() anchors on the Graphics
      // origin (not the bounds centre), so the mouth lands on run.debris[i].x/y.
      // v6.8.2: ONE TEXTURE PER RING, not one texture for the whole throat. The rings turn at
      // different speeds (see TORNADO_RING_SPIN / syncTornadoes) and a single baked sprite can only
      // turn as a unit. Each ring is baked with its off-centre offset already in it and its
      // Graphics origin left at (0,0) — bake() anchors on that origin, so spinning the sprite
      // sweeps the offset circle around the hit centre, which IS the swirl.
      const DUST = 0xb9a98f, LIGHT = 0xe0d4bc, DARK = 0x4a4034
      // v6.9 (owner: "make tornadoes 30% more transparent") — ONE multiplier over every alpha in
      // this bake rather than a re-tuned ramp, so the depth gradient the design is built on stays
      // exactly as picked and only its overall weight moves. Applies to the scraps too: leaving
      // them opaque over a body this faint makes the junk read as the entity and the funnel as a
      // smudge behind it.
      const A = 0.7
      // ---- v6.10 Burst Hydrant jet textures ---------------------------------------------------
      // Baked, not drawn per frame. The first pass at this effect was four variations of Graphics
      // circles and every one of them read as a diagram rather than as water — the owner's verdict
      // was "change completely the visual". Everything else in this game is a baked texture with an
      // irregular silhouette; a perfect vector circle is what made it look like UI.
      //
      // Palette moves from the old flat sewer-green to WATER: white foam over a pale cyan-green
      // body. The green is retained in the rim only, where it still has to do its safety-cue job of
      // never being confusable with the red volatile-bomb telegraph that hurts the player.
      //
      // Plan view throughout: these are lobed rings seen from directly above, not a column.
      const FOAM = 0xf2fffb, WATER = 0x9fe8d0, DEEP = 0x4fae90
      // Ragged foam rings, counter-rotated at different speeds by the rig. The lobed outline is the
      // whole trick — a circle turning looks static, a lobed ring turning reads as churn.
      // ALL FOUR BAKE AT THE SAME R0. The first attempt shrank R0 per layer AND scaled it back up
      // per layer at draw time, and the two fought: the composite landed at about half the jet's
      // real radius, so the foam floated in the middle of its own rim. One baked radius means the
      // rig's `k = gy.r / JET_BAKE_R` maps a texture straight onto the hitbox, and layer size is
      // decided in exactly one place (the draw multipliers).
      //
      // Lobe count is high and wobble is shallow (11-17 lobes at ~0.09) because the first pass used
      // 7 lobes at 0.20 and came out a flower — a starburst silhouette with petals, not foam. Foam
      // wants a busy, barely-irregular edge.
      // A SHEARED FIRE HYDRANT. The zone is not a painted area any more — it is a physical object
      // on the street with its cap blown off, throwing water flat across the asphalt.
      //
      // Four earlier passes were all variations on "translucent coloured disc" (green vector
      // circles, then white foam rings, then outlined splash blobs) and every one was rejected. The
      // fault was never the drawing: a zone that IS its own hitbox has to be 128px of art, and
      // 128px of translucent anything turns to wash. A recognisable object at the centre plus a
      // thin quiet ring for the radius decouples the two, so the art can be small, opaque and
      // high-contrast while the hitbox stays big.
      //
      // No green anywhere. Steel and white, with the hydrant's dull red as the only chroma — and
      // that red lives on a 26px OBJECT, not on a translucent area, so it cannot be misread as the
      // amber/red hazard language the traffic lanes and volatile bombs own.
      const H_RED = 0xc9503f, H_STEEL = 0x8e98a0, H_DARK = 0x24282b, WHITE = 0xffffff, RINSE = 0xdfeef2
      // Top-down hydrant. From directly overhead a hydrant is its bonnet: a chunky disc with the
      // side nozzles poking out either side and the front nozzle facing you. Baked at ~13px radius
      // and drawn at a FIXED pixel size (HYDRANT_PX) — a hydrant is a real object, so it must not
      // scale with the damage radius the way every other zone visual in this game does.
      const hydrant = (capped) => {
        const g = new Graphics()
        for (const a of [Math.PI / 2, -Math.PI / 2, 0]) {   // nozzles: two side, one front
          g.circle(Math.cos(a) * 8.5, Math.sin(a) * 8.5, 3.6)
            .fill({ color: H_STEEL }).stroke({ width: 1.5, color: H_DARK })
        }
        g.circle(0, 0, 10).fill({ color: H_RED }).stroke({ width: 1.8, color: H_DARK })     // barrel
        if (capped) {
          g.circle(0, 0, 5.4).fill({ color: H_STEEL }).stroke({ width: 1.5, color: H_DARK }) // bonnet
          g.circle(0, 0, 1.8).fill({ color: H_DARK })
        } else {
          // Throat kept SMALL. At 36px on screen the only thing that reads is the colour block, so
          // a wide dark opening just turns the hydrant into a dark blob with a red rim.
          g.circle(0, 0, 4.2).fill({ color: 0x141719 })      // the open throat, cap gone
          g.circle(0, 0, 2.8).fill({ color: RINSE, alpha: 0.95 })
        }
        return bake(g)
      }
      T.hydrantCapped = hydrant(true)
      T.hydrantOpen = hydrant(false)
      // The blown cap, tumbling clear. One small dark disc is the cheapest possible cue that
      // something just came apart, and it is unambiguously a plan view.
      {
        const g = new Graphics()
        g.circle(0, 0, 5).fill({ color: H_STEEL }).stroke({ width: 1.5, color: H_DARK })
        g.circle(0, 0, 1.8).fill({ color: H_DARK })
        T.hydrantCap = bake(g)
      }
      // Water sheeting outward. Rings of white blobs, but CONCENTRATED near the hydrant (about half
      // the zone radius) rather than out at the rim — water leaves a burst main fast and thick at
      // the source and arrives at the edge as loose droplets, which the particles carry. Keeping
      // the solid art off the rim is what stops the effect covering the fight.
      // A STREAM: water hosed out sideways, seen from above. Baked pointing along +x with its
      // origin at the nozzle, so the rig just rotates it at the target and scales x to the distance.
      // Narrow and dense at the nozzle, widening and breaking into separate gouts further out —
      // that spread is what makes it read as a jet of water rather than as a drawn line.
      //
      // JITTER THE ANGLE (kept from the abandoned radial version, because it is the lesson that
      // took three passes): evenly spaced same-size circles read as a pattern — a flower, a cog, a
      // donut — however much you vary radius and size. Here the equivalent is jittering each gout
      // ALONG and ACROSS the stream, and mixing two size classes.
      T.jetStream = []
      for (let i = 0; i < 2; i++) {
        const g = new Graphics()
        const L = JET_BAKE_R * 2       // baked length; the rig scales x to reach the target
        // Dense and fine at the nozzle, opening into fewer, bigger, more scattered gouts downrange.
        // The first version used a uniform blob size along the axis and came out a STRING OF
        // PEARLS — a jet of water is a size gradient, not a row of beads, so radius has to grow
        // hard with t while the count stays high enough that the near end never separates.
        for (let k = 0; k < 40; k++) {
          const t = Math.pow((k + hash(k * 7.3 + i * 3.1) * 0.9) / 40, 0.85)
          const spread = 0.9 + t * t * 8.5          // the cone opens with distance
          const off = (hash(k * 4.9 + i * 6.7) - 0.5) * 2 * spread
          const fat = hash(k * 2.7 + i * 1.9) > 0.78
          const rad = (fat ? 1.8 + hash(k * 5.1) * 1.6 : 0.75 + hash(k * 3.3) * 0.85) * (0.55 + t * t * 4.2)
          g.circle(t * L, off, rad)
            .fill({ color: i === 0 ? WHITE : RINSE, alpha: (0.95 - t * 0.4) * (i === 0 ? 1 : 0.6) })
        }
        T.jetStream.push(bake(g))
      }
      // The leak at the source: a tight spatter right at the nozzle, so the hydrant is visibly
      // losing water everywhere and not only along the streams.
      {
        const g = new Graphics()
        for (let k = 0; k < 14; k++) {
          const step = (Math.PI * 2) / 14
          const a = k * step + (hash(k * 9.7) - 0.5) * step * 1.7
          const rr = 4.5 + hash(k * 3.1) * 5
          g.circle(Math.cos(a) * rr, Math.sin(a) * rr, 1.2 + hash(k * 5.3) * 1.8)
            .fill({ color: k % 3 ? WHITE : RINSE, alpha: 0.8 })
        }
        T.jetSource = bake(g)
      }
      // Broken asphalt around the base — the hydrant did not come off politely. Kept dark and
      // chunky so it grounds the object instead of glowing.
      {
        const g = new Graphics()
        const hole = []
        for (let k = 0; k < 13; k++) {
          const a = (k / 13) * Math.PI * 2
          const rr = 7.5 * (0.66 + hash(k * 3.3 + 1.7) * 0.62)
          hole.push(Math.cos(a) * rr, Math.sin(a) * rr)
        }
        g.poly(hole).fill({ color: 0x1b1f22, alpha: 0.6 })
        for (let k = 0; k < 7; k++) {   // slabs levered up around the rim
          const a = hash(k * 4.1 + 0.4) * Math.PI * 2
          const d = 11 + hash(k * 2.2 + 3.9) * 6
          const cx = Math.cos(a) * d, cy = Math.sin(a) * d
          const s = 3.4 + hash(k * 6.3) * 2.6
          const slab = []
          for (let j = 0; j < 5; j++) {
            const ja = a + 1.1 + (j / 5) * Math.PI * 2
            const rr = s * (0.6 + hash(j * 3.7 + k * 1.9) * 0.7)
            slab.push(cx + Math.cos(ja) * rr, cy + Math.sin(ja) * rr)
          }
          g.poly(slab).fill({ color: 0x59626a, alpha: 1 }).stroke({ width: 1.6, color: 0x0f1214, alpha: 0.95 })
        }
        T.jetCrack = bake(g)
      }
      T.tornadoRings = []
      for (let i = 0; i < 6; i++) {
        const t = i / 5
        const g = new Graphics()
        // The ramp runs 0.12 -> 0.86 before A. v6.8.1's flat 0.2 outer read as a solid pale disc
        // lying ON the street rather than as airborne dust. The stroke is tied to its own ring's
        // fill at just over half, because a crisp dark outline on a near-invisible ring is exactly
        // what made the mouth look like a drawn object.
        const alpha = (0.12 + 0.148 * i) * A
        g.circle(11 * t * t, 0, 30 - 24 * t)          // quadratic step: the lean grows with depth
          .fill({ color: i % 2 ? LIGHT : DUST, alpha })
          .stroke({ width: 1.3, color: DARK, alpha: alpha * 0.55 })
        if (i === 5) g.circle(11, 0, 4.5).fill({ color: 0x241f19, alpha: 0.85 * A }) // core
        // Caught scraps ride the MOUTH (the outermost ring), which is the one detail that says
        // TRASH tornado and not a portal — and riding one ring means they now orbit at the mouth's
        // own speed instead of being frozen relative to the throat. Same facet palette as the lone
        // chunk this bake replaced in v6.8.
        if (i === 0) {
          for (let k = 0; k < 4; k++) {
            const a = hash(k * 5.7 + 0.9) * Math.PI * 2
            const r = 16 + hash(k * 2.4 + 5.5) * 12
            const cx = Math.cos(a) * r, cy = Math.sin(a) * r
            const s = 3.2 + hash(k * 7.1) * 2
            const pts = []
            for (let j = 0; j < 5; j++) {
              const ja = a + (j / 5) * Math.PI * 2
              const rr = s * (0.65 + hash(j * 2.9 + cx * 0.13 + 3.1) * 0.6)
              pts.push(cx + Math.cos(ja) * rr, cy + Math.sin(ja) * rr)
            }
            g.poly(pts).fill({ color: DUST, alpha: A }).stroke({ width: 1, color: DARK, alpha: A })
          }
        }
        T.tornadoRings.push(bake(g))
      }
    }
    {
      // rock chunk (skies, run.lobs): the kaiju's thrown masonry — chunkier and colder than trash
      const g = new Graphics()
      const pts = []
      for (let i = 0; i < 7; i++) {
        const a = (i / 7) * Math.PI * 2
        const rr = 12 * (0.68 + hash(i * 5.17 + 2.3) * 0.5)
        pts.push(Math.cos(a) * rr, Math.sin(a) * rr)
      }
      g.poly(pts).fill(0x9aa0a8).stroke({ width: 1.8, color: 0x474d55 })
      g.ellipse(-3, -3, 6, 4).fill({ color: 0xd0d6de, alpha: 0.45 })
      g.ellipse(3, 4, 6, 3).fill({ color: 0x474d55, alpha: 0.3 })
      g.beginPath().moveTo(-7, 2).lineTo(2, -5).stroke({ width: 1.1, color: 0x474d55, alpha: 0.5 })
      T.rockChunk = bake(g)
    }
    {
      // Net Toss in flight (trawl, run.lobs with `snare`). A GATHERED BUNDLE, not a spread mesh:
      // it is a net that has been balled up and thrown, and it opens only where it lands. Drawn
      // from directly overhead like everything else in this file that is not a building.
      // WARM, because the wall it is borrowed from is cold — see GEAR_VIS by updateGear for why
      // the player's own gear may never share the trawl wall's palette.
      const g = new Graphics()
      const pts = []
      for (let i = 0; i < 9; i++) {
        const a = (i / 9) * Math.PI * 2
        const rr = 13 * (0.74 + hash(i * 3.71 + 8.9) * 0.42)
        pts.push(Math.cos(a) * rr, Math.sin(a) * rr)
      }
      g.poly(pts).fill(0x8a5220).stroke({ width: 1.6, color: 0xf0a94a })
      // Twine over the bundle: a few chords, so it reads as MESH at 13px rather than as a sack.
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI
        g.beginPath()
          .moveTo(Math.cos(a) * -11, Math.sin(a) * -11)
          .lineTo(Math.cos(a) * 11, Math.sin(a) * 11)
          .stroke({ width: 1, color: 0xf0a94a, alpha: 0.75 })
      }
      // Sinkers around the rim — the weights that make it drop and the reason it holds.
      for (let i = 0; i < 5; i++) {
        const a = (i / 5) * Math.PI * 2 + 0.4
        g.circle(Math.cos(a) * 12, Math.sin(a) * 12, 2.4).fill(0xf25f3a)
      }
      T.tossNet = bake(g)
    }
    // ---- voxel boulder (hills district, skies — v5.9.1 art experiment) ------------------------
    // "the 'rocks'?? asset is just ugly" (playtest report). T.rockChunk right above is kept EXACTLY
    // as-is — it still does its other job (run.lobs, the kaiju's thrown masonry) untouched — this
    // is a SEPARATE bake, used ONLY by the hills district's BIG_HILLS/MID_HILLS/DETAIL_HILLS tables
    // below, so reverting this experiment (if it doesn't earn its keep) is a small diff: those three
    // array entries plus deleting this block, nothing else in the file to touch.
    // Hand-drawn faux-voxel, not an imported/generated asset (the ask): blocky cube-like forms,
    // flat colour fills with NO gradients, hard-stroked edges between every face, and ONE light
    // direction reused byte-for-byte on every cube in every variant — the bare top-face fill is
    // lightest, a thin RIGHT-edge strip one step darker (a lit side face), a thin BOTTOM-edge strip
    // darkest (the face in full shadow). Light-from-upper-left matches this file's other upright
    // buildings (T.silo's lit-left/shaded-right flank, T.house/T.barn's lit-left roof face, all
    // above) — the closest thing this codebase has to an established sun direction. Top-down, not
    // isometric: the bevel strips are thin slivers of the SAME top-down rect, not a rotated 3/4 view
    // — this is the same "mostly the top face, a thin flank strip for volume" convention T.silo/
    // T.house/T.barn already use, just with hard flat facets instead of soft alpha shading.
    // Consistency demands every cube stay AXIS-ALIGNED (no per-cube rotation): the shading is
    // computed in this shape's own local space, so rotating a cube would rotate its shading with it
    // — exactly the "inconsistent lighting reads as wrong" trap the brief warns about. Irregularity
    // instead comes from varying each cube's size/offset only, several overlapping per variant. For
    // the same reason the district tables below mark every voxelRock kind `upright: true` — NOT
    // because a boulder is base-anchored (it's mass-centred, like every other top-down scatter rock
    // here), but because `upright` is applyPropKind's only lever for "small rotation jitter, not a
    // full spin" — seeing this whole field with every boulder's lighting pointing the same way is
    // the entire point, so full spin (this file's default for top-down scatter) is not an option.
    {
      function voxelCube(g, cx, cy, w, h, top, mid, dark, line) {
        const bevel = Math.min(w, h) * 0.22 // side-face thickness — thin: mostly-overhead, not a side view
        g.rect(cx - w / 2, cy - h / 2, w, h).fill(top).stroke({ width: 1.6, color: line })
        g.rect(cx + w / 2 - bevel, cy - h / 2, bevel, h).fill(mid).stroke({ width: 1.2, color: line })  // right face: lit side
        g.rect(cx - w / 2, cy + h / 2 - bevel, w, bevel).fill(dark).stroke({ width: 1.2, color: line }) // bottom face: shadow side
      }
      function bakeVoxel(draw) {
        const g = new Graphics()
        draw(g)
        return bake(g)
      }
      const ROCK_TOP = 0x9aa0a8, ROCK_MID = 0x7d838c, ROCK_DARK = 0x565c64, ROCK_LINE = 0x363b41
      // A: one big single block, with a smaller chip stacked at a corner to break up the rectangle
      T.voxelRockA = bakeVoxel((g) => {
        voxelCube(g, 0, 0, 46, 40, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
        voxelCube(g, 16, -14, 16, 14, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
      })
      // B: two merged blocks, an L-shaped pair
      T.voxelRockB = bakeVoxel((g) => {
        voxelCube(g, -10, 0, 34, 30, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
        voxelCube(g, 16, 10, 26, 22, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
      })
      // C: three small blocks, a loose scattered pile
      T.voxelRockC = bakeVoxel((g) => {
        voxelCube(g, -14, -6, 22, 20, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
        voxelCube(g, 10, -10, 18, 16, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
        voxelCube(g, 2, 14, 20, 17, ROCK_TOP, ROCK_MID, ROCK_DARK, ROCK_LINE)
      })
    }

    // dust mote: tiny soft blurred dot (screen-space ambience, title + gameplay)
    {
      const c = document.createElement('canvas')
      c.width = c.height = 16
      const ctx = c.getContext('2d')
      const grad = ctx.createRadialGradient(8, 8, 0, 8, 8, 8)
      grad.addColorStop(0, 'rgba(255,255,255,0.9)')
      grad.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = grad
      ctx.fillRect(0, 0, 16, 16)
      T.dustMote = Texture.from(c)
    }

    // CAUSTIC TILE (v7.x, The Surf) — the net of focused sunlight on a sea floor, baked once as a
    // SEAMLESS tile and then scrolled by two TilingSprites (see updateCaustics and CAUSTIC_VIS).
    //
    // The pattern is a sum of three sine waves whose phases are themselves modulated by the other
    // axis — the cheapest field that folds back on itself the way a refracted wavefront does, rather
    // than the regular egg-crate that plain sin(x)*sin(y) gives. What turns that field into caustics
    // is the RIDGE step below: brightness is taken from how close the field is to ZERO, not from its
    // height, so what gets drawn is the thin crease where the wave changes sign. Focused light is a
    // caustic BECAUSE it is a fold, and a fold is a zero crossing; shading by height instead gives a
    // soft plasma cloud, which is the look this went through on the way here.
    //
    // SEAMLESS is arithmetic, not luck: every frequency below is an INTEGER multiple of the tile's
    // own 2π, so the field at x = tile is identical to the field at x = 0 and the tiling has no
    // visible grid. Change any of those coefficients to a non-integer and a hard seam appears every
    // `tile` px in both axes — which on a scrolling layer reads as the floor being made of panels.
    {
      const N = CAUSTIC_VIS.tile
      const c = document.createElement('canvas')
      c.width = c.height = N
      const ctx = c.getContext('2d')
      const img = ctx.createImageData(N, N)
      const d = img.data
      for (let y = 0; y < N; y++) {
        const v = (y / N) * Math.PI * 2
        for (let x = 0; x < N; x++) {
          const u = (x / N) * Math.PI * 2
          const s = (Math.sin(u * 3 + Math.sin(v * 2) * 1.6)
                   + Math.sin(v * 4 + Math.sin(u * 3) * 1.4)
                   + Math.sin((u + v) * 2 + Math.sin((u - v) * 3) * 1.2)) / 3
          const ridge = Math.max(0, 1 - Math.abs(s) * CAUSTIC_VIS.sharp)
          const a = Math.pow(ridge, CAUSTIC_VIS.gamma)
          const i = (y * N + x) * 4
          // White with the shape carried in ALPHA, so the layer can be tinted per chapter and its
          // additive blend adds nothing at all where the pattern is dark.
          d[i] = d[i + 1] = d[i + 2] = 255
          d[i + 3] = (a * 255) | 0
        }
      }
      ctx.putImageData(img, 0, 0)
      T.caustic = Texture.from(c)
    }
  }
  buildTextures()

  // ==============================================================================================
  // SKIES ART DIRECTION (v5.10) — bakes
  // docs/superpowers/specs/2026-07-25-skies-art-direction.md
  // ==============================================================================================
  // Everything in here is baked ONCE and pooled as sprites; nothing below is ever constructed per
  // frame. It is also entirely skies-scoped: every texture is read only from a code path gated on
  // chapterHasStorm / chapterHasDistricts / chapterHasRoads, so no other chapter can see it.
  //
  // THE SHADOW LAW (spec §5.1.2). Every structure plan bakes its own cast shadow at ONE constant
  // offset for the whole region (SKIES_SHADOW). One light direction across an entire region is the
  // cheapest, strongest "this is a photograph of a place" cue there is. It also SHIFTS the bake's
  // bounds, and therefore bake()'s returned anchor — which is exactly the v5.9.2 "sprites sitting
  // off their colliders" bug class. skiesPlan() below draws a symmetric zero-alpha BOUNDS KEEPER
  // first, so ax/ay come out at exactly 0.5 no matter what the shadow does.
  const SKB = SKIES_BAKE_PX / 2      // 64 — half the plan canvas; the bounds keeper's half-extent
  const SKR = 46                     // content half-extent: SKR + shadow offset must stay under SKB
  const SH_DX = SKIES_SHADOW.dx * SKR
  const SH_DY = SKIES_SHADOW.dy * SKR
  const SH_COL = SKIES_SHADOW.color
  const SH_A = SKIES_SHADOW.alpha
  // How wide a plan's CONTENT (2 x SKR) is drawn, as a multiple of the collider radius o.r. The
  // spec's starting point was 1.9 x o.r measured across the whole 128px canvas, which put a house
  // at ~24px on screen — too small for six shingle courses and a lit dormer pane to survive, i.e.
  // it threw away the detail this whole pass exists to add. 2.6 puts a house at 29-42px, a barn or
  // silo at 48-66 and a tower at 63-96, against a 44px player: you still tower over a house, which
  // is the v5.8 kaiju premise, but a downtown block is genuinely big enough to look at. 3.0 is also
  // the ceiling: streamObstacles keeps structure centres >= 2*maxR + 40 = 104px apart, so a bigger
  // multiplier would let the largest towers visibly overlap — the v5.9.2 "wall of blobs" report.
  const SKIES_PLAN_SCALE = 3.0

  function skiesPlan(draw) {
    const g = new Graphics()
    g.rect(-SKB, -SKB, SKB * 2, SKB * 2).fill({ color: 0x000000, alpha: 0 }) // bounds keeper (see above)
    draw(g)
    return bake(g, 0)
  }
  // A canvas-gradient texture (the T.blotches / stormBlob idiom): the only way to get a real
  // feathered falloff, which is what an additive light needs to not look like a cardboard cutout.
  function canvasTex(w, h, draw) {
    const c = document.createElement('canvas')
    c.width = w; c.height = h
    draw(c.getContext('2d'), w, h)
    return Texture.from(c)
  }

  function buildSkiesTextures() {
    // ---- structure plans (spec §5) -----------------------------------------------------------
    // All six kinds redrawn as TOP-DOWN PLANS. They were side-view, upright, base-anchored bakes
    // under a top-down camera, which is the whole reason "a house is a box plus a triangle".
    // Detail counts come from SKIES_STRUCTURE_ART and are not decorative: in kaiju fiction scale is
    // communicated by the DENSITY OF SMALL DETAIL around the monster, so "some windows" bakes as a
    // smear and "a 4x6 grid, 11 lit" bakes as a building.
    const A = SKIES_STRUCTURE_ART

    // window run helper: lays `n` 3x4 panes along a flank strip, `lit` of them warm. The lit/dark
    // split is a fixed pattern, not a roll, so the two variants differ by DESIGN (that is how
    // "window flicker" is faked with zero per-frame Graphics — spec §5.2).
    function panes(g, x0, y0, dx, dy, n, litEvery, art) {
      for (let k = 0; k < n; k++) {
        const lx = x0 + dx * k, ly = y0 + dy * k
        const lit = (k % litEvery) === 0
        g.rect(lx, ly, 3, 4).fill(lit ? art.windowLit : art.windowDark)
      }
    }

    // v5.11 ("no building etc", playtest report). The v5.10 tower had exactly two variants and BOTH
    // used the same fixed 36x30 footprint, so a whole downtown block was one silhouette repeated —
    // at a glance the city read as tiled wallpaper rather than as buildings. Variety in ROOF
    // FURNITURE alone could not fix that: from directly overhead the thing that distinguishes one
    // building from the next is its FOOTPRINT, because that is the shape you actually see. So a
    // variant now carries its own proportions (a narrow slab, a wide low block, a square tower) as
    // well as its own roof, and there are five of them instead of two.
    //
    // Every plan still bakes into the same 128px canvas through skiesPlan's bounds keeper, so a
    // smaller footprint genuinely reads as a smaller building on screen rather than being rescaled
    // back up to fill the frame.
    const TOWER_VARIANTS = [
      { W: 36, H: 30, roof: 'tank',      litEvery: 2 },   // the v5.10 variant A, unchanged
      { W: 36, H: 30, roof: 'helipad',   litEvery: 3 },   // the v5.10 variant B, unchanged
      { W: 22, H: 44, roof: 'cooling',   litEvery: 2 },   // narrow slab, long axis N-S
      { W: 45, H: 21, roof: 'skylights', litEvery: 4 },   // wide low block — a warehouse or a mall
      { W: 30, H: 31, roof: 'garden',    litEvery: 3 },   // square, with a planted roof
    ]

    function towerPlan(v) {
      const vb = A.tower.variantB
      return skiesPlan((g) => {
        const W = v.W, H = v.H, ch = A.tower.chamferPx * 0.55
        // roof deck outline, TWO corners chamfered — a chamfer reads as a designed building; a
        // rounded blob reads as rubble, which is precisely the bug being fixed.
        const deck = [
          -W + ch, -H, W, -H, W, H - ch, W - ch, H, -W, H, -W, -H + ch,
        ]
        const shadow = deck.map((val, i) => val + (i % 2 ? SH_DY : SH_DX))
        g.poly(shadow).fill({ color: SH_COL, alpha: SH_A })
        // flank walls: the +x and +y sides, carrying the window grid (a top-down building shows a
        // sliver of its own facade on the two faces the light does not reach)
        g.poly([W, -H, W + 12, -H + 7, W + 12, H - ch + 7, W, H - ch]).fill(A.tower.flank)
        g.poly([-W, H, -W + 7, H + 12, W - ch + 7, H + 12, W - ch, H]).fill(A.tower.flank)
        g.poly(deck).fill(A.tower.deck).stroke({ width: 1.6, color: A.tower.edge })
        g.poly([-W + ch + 3, -H + 3, W - 3, -H + 3, W - 3, H - ch - 3, -W + 3, H - 3])
          .stroke({ width: 1.2, color: A.tower.parapet, alpha: 0.75 })   // inner parapet ledge
        // gravel flecks — fixed-hash, the texture that says "tar-and-gravel roof". Count scales
        // with the deck area so a wide block is not sparser than a narrow one.
        const flecks = Math.round(A.tower.gravelFlecks * (W * H) / (36 * 30))
        for (let k = 0; k < flecks; k++) {
          const gx = (hash(k * 3.71 + 0.9) - 0.5) * (W - 5) * 2
          const gy = (hash(k * 5.13 + 2.7) - 0.5) * (H - 5) * 2
          g.circle(gx, gy, A.tower.gravelPx / 2).fill({ color: A.tower.gravel, alpha: A.tower.gravelAlpha })
        }
        // HVAC units: box on a dark plinth, 5 fin hairlines, a fan disc with 4 blade ticks. Placed
        // in deck-relative fractions so they land on the roof whatever its proportions are.
        const units = [[-0.55, -0.5, 0.6, 0.45], [0.1, 0.35, 0.45, 0.36]]
        for (const [fx0, fy0, fw, fh] of units) {
          const ux = fx0 * W, uy = fy0 * H, uw = Math.max(10, fw * W), uh = Math.max(8, fh * H * 0.8)
          g.rect(ux - 1.5, uy - 1.5, uw + 3, uh + 3).fill(A.tower.hvacBase)
          g.rect(ux, uy, uw, uh).fill(A.tower.hvac).stroke({ width: 0.8, color: A.tower.hvacBase })
          for (let f = 1; f <= A.tower.hvacFins; f++) {
            const fx = ux + (uw * f) / (A.tower.hvacFins + 1)
            g.moveTo(fx, uy + 1.5).lineTo(fx, uy + uh - 1.5).stroke({ width: 0.7, color: A.tower.hvacBase, alpha: 0.8 })
          }
          g.circle(ux + uw - 5, uy + uh / 2, 4).fill(A.tower.hvacBase)
          for (let b = 0; b < 4; b++) {
            const ba = (b / 4) * Math.PI * 2 + 0.4
            g.moveTo(ux + uw - 5, uy + uh / 2)
              .lineTo(ux + uw - 5 + Math.cos(ba) * 3.4, uy + uh / 2 + Math.sin(ba) * 3.4)
              .stroke({ width: 0.7, color: A.tower.hvac })
          }
        }
        // stairwell penthouse, with its OWN cast shadow at the region offset
        const sw = Math.min(20, W * 0.55), sh = Math.min(16, H * 0.5)
        g.rect(W * 0.28 + 3, -H * 0.2 + 4, sw, sh).fill({ color: SH_COL, alpha: SH_A * 0.8 })
        g.rect(W * 0.28, -H * 0.2, sw, sh).fill(A.tower.stairwell).stroke({ width: 1, color: A.tower.edge })
        g.rect(W * 0.28 + 3, -H * 0.2 + sh * 0.5, 6, sh * 0.45).fill(A.tower.stairDoor)

        if (v.roof === 'helipad') {
          // white circle + an 'H' of three bars. Nothing else on a roof looks like this.
          g.circle(-W * 0.33, H * 0.27, vb.helipadR).stroke({ width: 2, color: 0xffffff, alpha: vb.helipadAlpha })
          g.rect(-W * 0.5, H * 0.03, 2.4, 14).fill({ color: 0xffffff, alpha: vb.helipadAlpha })
          g.rect(-W * 0.22, H * 0.03, 2.4, 14).fill({ color: 0xffffff, alpha: vb.helipadAlpha })
          g.rect(-W * 0.5, H * 0.23, W * 0.28, 2.4).fill({ color: 0xffffff, alpha: vb.helipadAlpha })
        } else if (v.roof === 'tank') {
          // water tank on legs, with a rung ladder up its flank
          for (const lx of [-W * 0.83, -W * 0.5]) for (const ly of [H * 0.13, H * 0.47]) g.rect(lx, ly, 2, 4).fill(A.tower.edge)
          g.circle(-W * 0.66, H * 0.2, 9).fill(A.tower.waterTank).stroke({ width: 1.2, color: A.tower.edge })
          for (let r = 0; r < A.tower.tankRungs; r++) {
            g.rect(-W * 0.75, -1 + r * 2.2, 6, 0.8).fill({ color: A.tower.edge, alpha: 0.75 })
          }
        } else if (v.roof === 'cooling') {
          // three cooling drums in a row down the slab's long axis — the industrial read, and the
          // only roof here whose furniture is repeated identical units, which is what plant is.
          for (let k = 0; k < 3; k++) {
            const cy2 = -H * 0.5 + k * H * 0.42
            g.circle(-W * 0.25 + 4, cy2 + 4, 7).fill({ color: SH_COL, alpha: SH_A * 0.8 })
            g.circle(-W * 0.25, cy2, 7).fill(A.tower.hvac).stroke({ width: 1, color: A.tower.edge })
            for (let f = 0; f < 6; f++) {
              const fa = (f / 6) * Math.PI * 2
              g.moveTo(-W * 0.25 + Math.cos(fa) * 3, cy2 + Math.sin(fa) * 3)
                .lineTo(-W * 0.25 + Math.cos(fa) * 6.4, cy2 + Math.sin(fa) * 6.4)
                .stroke({ width: 0.8, color: A.tower.hvacBase })
            }
          }
        } else if (v.roof === 'skylights') {
          // a grid of pale glazed panels, faintly lit from inside — the wide-block signature, and
          // the one roof that puts light INSIDE the footprint instead of at its edge.
          for (let r = 0; r < 2; r++) {
            for (let k = 0; k < 4; k++) {
              const gx = -W * 0.62 + k * W * 0.35, gy = -H * 0.3 + r * H * 0.5
              g.rect(gx + 2, gy + 2, 13, 8).fill({ color: SH_COL, alpha: SH_A * 0.7 })
              g.rect(gx, gy, 13, 8).fill({ color: A.tower.windowLit, alpha: 0.5 }).stroke({ width: 0.9, color: A.tower.edge })
            }
          }
        } else {
          // planted roof: irregular canopy patches and a pale path threading them. Green on a roof
          // is rare enough that one of these per block reads instantly as a different building.
          for (let k = 0; k < 7; k++) {
            const gx = (hash(k * 4.3 + 1.7) - 0.5) * (W - 8) * 1.7
            const gy = (hash(k * 6.1 + 3.3) - 0.5) * (H - 8) * 1.7
            g.circle(gx, gy, 4 + hash(k * 2.9) * 5).fill({ color: 0x4e6b46, alpha: 0.85 })
          }
          g.moveTo(-W * 0.7, H * 0.3).bezierCurveTo(-W * 0.2, -H * 0.1, W * 0.2, H * 0.35, W * 0.6, -H * 0.2)
            .stroke({ width: 3, color: A.tower.parapet, alpha: 0.55 })
        }

        // antenna mast + 3 guy wires + the DARK aviation-lamp bead (the LIT lamp is a separate
        // pooled blink sprite — a blinking light is the one thing that cannot bake; see §7.4)
        const mx = W - 8, my = -H + 6
        g.moveTo(mx, my).lineTo(mx, my - A.tower.mastPx).stroke({ width: 1.5, color: A.tower.mast })
        for (let w = 0; w < A.tower.guyWires; w++) {
          const wa = -Math.PI * 0.85 + (w / (A.tower.guyWires - 1)) * Math.PI * 0.7
          g.moveTo(mx, my - A.tower.mastPx)
            .lineTo(mx + Math.cos(wa) * 14, my + Math.sin(wa) * 6 + 8)
            .stroke({ width: 0.7, color: A.tower.mast, alpha: 0.7 })
        }
        g.circle(mx, my - A.tower.mastPx, 1.6).fill(A.tower.lampDark)
        // window grid on the two flank slivers — palette law 1's ONLY permitted form for warm gold
        // (a static <= 5px lit rectangle). Run lengths follow the flank they sit on, so a wide block
        // gets a long row of windows on its south face and a short one on its east.
        const vRun = Math.max(3, Math.round((H * 2 - 12) / 7))
        const hRun = Math.max(3, Math.round((W * 2 - 12) / 8))
        panes(g, W + 2, -H + 9, 0, 7, vRun, v.litEvery, A.tower)
        panes(g, W + 6.5, -H + 12, 0, 7, vRun - 1, v.litEvery + 1, A.tower)
        panes(g, -W + 9, H + 3, 8, 0, hRun, v.litEvery, A.tower)
        panes(g, -W + 13, H + 7.5, 8, 0, hRun - 1, v.litEvery + 1, A.tower)
        // fire escape on the +y flank: diagonal ticks + landing bars
        const escTicks = Math.max(3, Math.round(A.tower.escapeTicks * W / 36))
        for (let e = 0; e < escTicks; e++) {
          const ex = -W + 4 + e * 6
          g.moveTo(ex, H + 2).lineTo(ex + 5, H + 10).stroke({ width: 1, color: A.tower.fireEscape })
        }
        for (let l = 0; l < A.tower.escapeLandings; l++) {
          g.rect(-W + 2, H + 3 + l * 3.4, Math.min(26, W * 0.72), 0.9).fill({ color: A.tower.fireEscape, alpha: 0.85 })
        }
      })
    }
    T.skTowerA = towerPlan(TOWER_VARIANTS[0])
    T.skTowerB = towerPlan(TOWER_VARIANTS[1])
    T.skTowerC = towerPlan(TOWER_VARIANTS[2])
    T.skTowerD = towerPlan(TOWER_VARIANTS[3])
    T.skTowerE = towerPlan(TOWER_VARIANTS[4])

    function housePlan(variantB) {
      const h = A.house
      return skiesPlan((g) => {
        // THE LOT IS BAKED INTO THE SAME TEXTURE (spec §5.3): a driveway that doesn't touch its
        // house is worse than no driveway, and suburbs' "lot furniture" as separate scattered floor
        // props is exactly what produced a yard with a fence in the middle of it.
        g.rect(-40, -34, 80, 68).fill({ color: h.lot.lawn, alpha: h.lot.lawnAlpha })   // lot pad
        if (variantB) {
          g.ellipse(-24, 18, 11, 7).fill(A.house.variantB.pool)                        // kidney pool
          g.ellipse(-19, 20, 6, 4.5).fill(A.house.variantB.pool)
          g.ellipse(-24, 18, 11, 7).stroke({ width: 1.5, color: A.house.variantB.coping })
          g.beginPath().arc(-26, 16, 6, Math.PI * 1.1, Math.PI * 1.7)
            .stroke({ width: 1.1, color: 0xffffff, alpha: 0.5 })                       // highlight crescent
          g.rect(-16, 14, 3, 1).fill(A.house.variantB.coping)                          // ladder tick
        } else {
          for (let k = 0; k < h.lot.hedgeLobes; k++) {                                 // L of hedge
            g.circle(-38 + k * 5, -30, 4).fill({ color: 0x4e6640, alpha: 0.9 })
          }
          for (let k = 0; k < 4; k++) g.circle(-38, -26 + k * 5, 4).fill({ color: 0x4e6640, alpha: 0.9 })
        }
        g.rect(18, -34, 12, 30).fill(h.lot.drive)                                       // driveway to the rim
        g.rect(-36, 22, 18, 12).fill({ color: 0x7a6a58, alpha: 0.85 })                   // rear deck pad
        for (let k = 0; k < h.lot.deckPlanks; k++) {
          g.rect(-36, 22 + k * 1.7, 18, 0.7).fill({ color: 0x000000, alpha: 0.2 })
        }
        g.rect(24, 20, 10, 10).fill({ color: 0x7d7266, alpha: 0.95 }).stroke({ width: 1, color: 0x4a4238 })
        g.moveTo(24, 25).lineTo(34, 25).stroke({ width: 1.2, color: 0x4a4238 })          // shed + its ridge
        g.rect(8, 26, 4, 6).fill(h.lot.bins[0])
        g.rect(13, 26, 4, 6).fill(h.lot.bins[1])
        g.beginPath().arc(30, -12, 4, 0, Math.PI * 1.6).stroke({ width: 1.2, color: 0x3a5a3a, alpha: 0.9 }) // hose loop

        const W = 21, H = 15
        g.rect(-W + SH_DX * 0.5, -H + SH_DY * 0.5, W * 2, H * 2).fill({ color: SH_COL, alpha: SH_A })
        // hipped roof: two facing slopes at two tones, meeting a ridge, with hip diagonals
        g.poly([-W, -H, W, -H, 11, -4, -11, -4]).fill(h.roofLit)
        g.poly([-W, H, W, H, 11, -4, -11, -4]).fill(h.roofShade)
        g.poly([-W, -H, -W, H, -11, -4]).fill(h.roofShade)
        g.poly([W, -H, W, H, 11, -4]).fill(h.roofLit)
        for (let c = 1; c <= h.shingleCourses; c++) {                                    // shingle courses
          const t = c / (h.shingleCourses + 1)
          g.moveTo(-W + t * 10, lerp(-H, -4, t)).lineTo(W - t * 10, lerp(-H, -4, t))
            .stroke({ width: 0.7, color: 0x000000, alpha: h.shingleAlpha })
          g.moveTo(-W + t * 10, lerp(H, -4, t)).lineTo(W - t * 10, lerp(H, -4, t))
            .stroke({ width: 0.7, color: 0x000000, alpha: h.shingleAlpha })
        }
        g.moveTo(-11, -4).lineTo(11, -4).stroke({ width: 2, color: h.ridge })            // ridge cap
        for (const ey of [-H, H]) g.moveTo(-W, ey).lineTo(W, ey).stroke({ width: 1, color: h.gutter, alpha: 0.8 })
        g.rect(W - 1, H - 5, 1.4, 5).fill(h.gutter)                                       // downpipe tick
        g.rect(-14 + 2.5, -12 + 3, 9, 9).fill({ color: SH_COL, alpha: SH_A })              // chimney's own shadow
        g.rect(-14, -12, 9, 9).fill(h.chimney).stroke({ width: 0.8, color: h.ridge })
        g.rect(-12, -10, 5, 3).fill(0x2a2018)                                              // flue
        g.rect(2, -11, 8, 7).fill(h.roofShade).stroke({ width: 0.8, color: h.ridge })       // dormer
        g.rect(4, -9.5, 4, 4).fill(h.dormerPane)
        g.moveTo(6, -9.5).lineTo(6, -5.5).stroke({ width: 0.5, color: h.ridge })
        g.rect(-4, 4, 7, 5).fill({ color: h.skylight, alpha: h.skylightAlpha })             // skylight
        g.rect(W - 2, -4, 24, 18).fill({ color: SH_COL, alpha: SH_A * 0.7 })
        g.rect(W - 4, -6, 24, 18).fill(h.roofShade).stroke({ width: 1.2, color: h.ridge })  // garage wing
        for (let p = 1; p <= h.garagePanels; p++) {
          g.moveTo(W - 4, -6 + (18 * p) / (h.garagePanels + 1)).lineTo(W + 20, -6 + (18 * p) / (h.garagePanels + 1))
            .stroke({ width: 0.7, color: 0x000000, alpha: 0.22 })
        }
        g.circle(W - 6, 12, 1.6).fill(h.porchLamp)                                          // porch lamp
      })
    }
    T.skHouseA = housePlan(false)
    T.skHouseB = housePlan(true)

    T.skBarn = skiesPlan((g) => {
      const b = A.barn
      // attached paddock, drawn first (ground furniture under the building)
      g.rect(-42, 6, 40, 34).fill({ color: 0x5f6a48, alpha: 0.35 })
      g.rect(-40, 12, 34, 20).fill({ color: b.muck, alpha: 0.55 })
      for (let p = 0; p < b.paddockPosts; p++) {
        g.rect(-42 + p * 5.6, 6, 1.6, 4).fill(0x6b5a44)
        g.rect(-42 + p * 5.6, 38, 1.6, 4).fill(0x6b5a44)
      }
      for (let k = 0; k < b.bales; k++) {                                                    // hay bales
        g.circle(-34 + k * 11, 34, 4.5).fill(0xc9a94a).stroke({ width: 0.8, color: 0x8a6f2e })
        g.beginPath().arc(-34 + k * 11, 34, 4.5, 0.6, 3.2).stroke({ width: 0.6, color: 0x8a6f2e, alpha: 0.7 })
      }
      g.moveTo(6, 24).quadraticCurveTo(20, 32, 34, 26).stroke({ width: 5, color: b.mudTrack, alpha: 0.6 }) // mud track
      const W = 26, H = 16
      g.rect(-W + SH_DX * 0.6, -H + SH_DY * 0.6, W * 2, H * 2).fill({ color: SH_COL, alpha: SH_A })
      // gambrel roof: two shallow upper slopes + two steep lower ones, ridge down the middle
      g.rect(-W, -H, W * 2, H).fill(b.roofLit)
      g.rect(-W, 0, W * 2, H).fill(b.roofShade)
      g.moveTo(-W, -6).lineTo(W, -6).stroke({ width: 1, color: 0x000000, alpha: 0.3 })        // hip break
      g.moveTo(-W, 6).lineTo(W, 6).stroke({ width: 1, color: 0x000000, alpha: 0.3 })
      for (let k = 1; k <= b.battens; k++) {                                                   // batten seams
        const bx = -W + (W * 2 * k) / (b.battens + 1)
        g.moveTo(bx, -H).lineTo(bx, H).stroke({ width: 0.7, color: 0x000000, alpha: 0.24 })
      }
      g.poly([4, -14, 16, -12, 14, -4, 2, -6]).fill({ color: b.rust, alpha: b.rustAlpha })      // rust patch
      g.rect(-W, -1.4, W * 2, 2.8).fill(0xd8d0bc)                                               // painted ridge vent
      g.rect(-4, -4, 8, 8).fill(0xb8b0a0).stroke({ width: 0.9, color: 0x4a3a28 })                // cupola
      g.moveTo(-4, 0).lineTo(4, 0).stroke({ width: 0.8, color: 0x4a3a28 })
      g.moveTo(0, -4).lineTo(0, 4).stroke({ width: 0.8, color: 0x4a3a28 })                       // weathervane cross
      g.rect(W - 9, -8, 9, 16).fill(b.hayDoor)                                                   // X-braced hay door
      g.moveTo(W - 9, -8).lineTo(W, 8).stroke({ width: 1, color: 0x8a6a4a })
      g.moveTo(W, -8).lineTo(W - 9, 8).stroke({ width: 1, color: 0x8a6a4a })
    })

    T.skSilo = skiesPlan((g) => {
      const s = A.silo
      const R = 24
      g.circle(SH_DX * 0.7, SH_DY * 0.7, R).fill({ color: SH_COL, alpha: SH_A })
      // pale fan of spilled grain at the base — the one soft shape on an otherwise hard object
      g.poly([R - 4, 6, R + 20, 2, R + 22, 18, R - 2, 14]).fill({ color: s.spill, alpha: s.spillAlpha })
      g.circle(0, 0, R).fill(s.body).stroke({ width: 1.6, color: 0x53565a })
      // the cap as radial facet lines converging on an OFF-CENTRE apex. That off-centre apex is the
      // ENTIRE reason a circle reads as a cone from directly above rather than as a disc.
      const ax = -R * s.apexOffset, ay = -R * s.apexOffset * 0.7
      for (let f = 0; f < s.facets; f++) {
        const fa = (f / s.facets) * Math.PI * 2
        g.moveTo(ax, ay).lineTo(Math.cos(fa) * R, Math.sin(fa) * R)
          .stroke({ width: 0.8, color: 0x8f9296, alpha: 0.8 })
      }
      g.circle(ax, ay, 2.6).fill(0x8f9296)
      // the cone's SHADED side: a crescent on the flank away from the light. Radial facet lines
      // alone read as a manhole cover from above; it is the value break that says "cone".
      g.beginPath()
      g.arc(0, 0, R, -0.35, 2.2)
      g.arc(ax, ay, R * 0.92, 2.2, -0.35, true)
      g.fill({ color: 0x000000, alpha: 0.22 })
      for (let r = 1; r <= s.seams; r++) {                                                    // corrugation rings
        g.circle(ax * (1 - r / (s.seams + 1)), ay * (1 - r / (s.seams + 1)), (R * r) / (s.seams + 1))
          .stroke({ width: 0.8, color: 0x53565a, alpha: s.seamAlpha })
      }
      g.rect(ax + 5, ay - 8, 6, 6).fill(0xa7aaad).stroke({ width: 0.7, color: 0x53565a })       // cap hatch
      // ladder cage down one flank: two rails and nine rungs
      g.moveTo(-3, 2).lineTo(-3, R - 1).stroke({ width: 0.9, color: 0x53565a })
      g.moveTo(3, 2).lineTo(3, R - 1).stroke({ width: 0.9, color: 0x53565a })
      for (let r = 0; r < s.ladderRungs; r++) {
        const ry = 3 + (r * (R - 5)) / s.ladderRungs
        g.moveTo(-3, ry).lineTo(3, ry).stroke({ width: 0.7, color: 0x53565a, alpha: 0.9 })
      }
      g.rect(-R - 20, -3, 20, 5).fill(0x9aa0a8).stroke({ width: 0.8, color: 0x53565a })          // auger arm
      g.rect(-R - 27, -6, 8, 11).fill(0x7d838c).stroke({ width: 0.8, color: 0x53565a })          // hopper box
    })

    T.skPier = skiesPlan((g) => {
      const p = A.pier
      // three deck sections with REAL GAPS between them — a hole in the fill, not a dark line.
      // That single detail is what sells wood over water (spec §5.6).
      const segs = [[-40, -12, 24, 26], [-13, -12, 26, 26], [12, -12, 28, 26]]
      for (const [sx, sy, sw, sh] of segs) {
        g.rect(sx + SH_DX * 0.5, sy + SH_DY * 0.5, sw, sh).fill({ color: SH_COL, alpha: SH_A * 0.8 })
      }
      for (const [sx, sy, sw, sh] of segs) {
        g.rect(sx, sy, sw, sh).fill(0xa9835a).stroke({ width: 1.2, color: 0x4a3420 })
        const n = Math.round((p.boards * sw) / 78)
        for (let k = 1; k <= n; k++) {
          g.moveTo(sx, sy + (sh * k) / (n + 1)).lineTo(sx + sw, sy + (sh * k) / (n + 1))
            .stroke({ width: 0.7, color: 0x4a3420, alpha: 0.5 })
        }
      }
      for (let k = 0; k < p.pilings; k++) {                                                    // pilings + halo
        const px = -36 + k * 15, py = k % 2 ? -9 : 9
        g.circle(px, py, 4.4).fill({ color: 0x000000, alpha: 0.3 })
        g.circle(px, py, 3).fill(0x6b4a2c).stroke({ width: 0.8, color: 0x2e2216 })
      }
      for (let k = 0; k < p.bollards; k++) {                                                   // bollards + rope
        const bx = -32 + k * 20
        g.circle(bx, -15, 2.6).fill(0x3f4348).stroke({ width: 0.7, color: 0x1c1e22 })
        if (k < 2) {
          g.circle(bx, -15, 4.4).stroke({ width: 0.8, color: 0xb8a888, alpha: 0.8 })
          g.circle(bx, -15, 6).stroke({ width: 0.7, color: 0xb8a888, alpha: 0.6 })
        }
      }
      g.rect(2, 14, 8, 1.6).fill(0x3f4348)                                                     // cleat T-glyph
      g.rect(5, 12, 1.6, 5).fill(0x3f4348)
      // crane rig at the head: mast, jib, hanging hook line
      g.rect(34, -10, 3, 16).fill(0x6d7480).stroke({ width: 0.7, color: 0x2b3038 })
      g.moveTo(35, -10).lineTo(35, -22).stroke({ width: 2, color: 0x6d7480 })
      g.moveTo(35, -22).lineTo(16, -18).stroke({ width: 1.6, color: 0x6d7480 })
      g.moveTo(16, -18).lineTo(16, -9).stroke({ width: 0.7, color: 0x9aa1ab })
      // shack with a corrugated roof of parallel ridge arcs, and one lit lantern
      g.rect(-38, -10, 18, 16).fill(0x8a8378).stroke({ width: 1, color: 0x3a352e })
      for (let k = 0; k < p.shackRoofArcs; k++) {
        g.beginPath().arc(-37 + k * 2, -2, 8, Math.PI * 1.05, Math.PI * 1.95)
          .stroke({ width: 0.7, color: 0x5a544a, alpha: 0.75 })
      }
      g.rect(-24, -6, 3, 3).fill(p.lantern)
      g.circle(-30, 8, 3).fill({ color: p.tyre, alpha: 0.9 }).stroke({ width: 1, color: 0x15181c }) // tyre fender
      // moored dinghy with a baked static V-wake, and two wave-crest lines along the base
      g.poly([-2, 22, 12, 20, 16, 25, 10, 30, -2, 28]).fill(0x8a5a3a).stroke({ width: 0.9, color: 0x3f2a18 })
      g.moveTo(-2, 22).lineTo(-16, 16).stroke({ width: 0.9, color: 0xdfe9f0, alpha: 0.4 })
      g.moveTo(-2, 28).lineTo(-16, 33).stroke({ width: 0.9, color: 0xdfe9f0, alpha: 0.4 })
      for (let k = 0; k < p.waveLines; k++) {
        g.moveTo(-42, 32 + k * 6).quadraticCurveTo(0, 27 + k * 6, 42, 33 + k * 6)
          .stroke({ width: 1.4, color: 0xdfe9f0, alpha: 0.3 })
      }
    })

    T.skTree = skiesPlan((g) => {
      const t = A.tree
      const R = 26
      // scalloped radial edge, NEVER a smooth circle — a smooth green disc is the single most
      // "programmer art" shape available and parks was made of them.
      const edge = []
      for (let k = 0; k < t.scallops * 4; k++) {
        const a = (k / (t.scallops * 4)) * Math.PI * 2
        const rr = R * (0.86 + 0.14 * Math.cos(a * t.scallops)) * (0.94 + hash(k * 3.1) * 0.12)
        edge.push(Math.cos(a) * rr, Math.sin(a) * rr)
      }
      g.poly(edge.map((v, i) => v + (i % 2 ? SH_DY : SH_DX))).fill({ color: SH_COL, alpha: SH_A })
      for (let s = 0; s < t.branchSpokes; s++) {                                     // spokes seen through the gaps
        const sa = (s / t.branchSpokes) * Math.PI * 2 + 0.3
        g.moveTo(0, 0).lineTo(Math.cos(sa) * R * 0.95, Math.sin(sa) * R * 0.95)
          .stroke({ width: 1.4, color: 0x2e2620, alpha: 0.85 })
      }
      g.poly(edge).fill(t.canopyShade)
      for (let l = 0; l < t.lobes; l++) {                                            // overlapping lit lobes
        const la = (l / t.lobes) * Math.PI * 2 + 0.7
        g.circle(Math.cos(la) * R * 0.42 - 3, Math.sin(la) * R * 0.42 - 4, R * 0.42)
          .fill({ color: t.canopyLit, alpha: 0.82 })
      }
      g.circle(0, 0, 3.4).fill(t.trunk)                                              // trunk at the centre of mass
    })

    T.skOutcrop = skiesPlan((g) => {
      const o = A.outcrop
      const facets = [
        [[-22, -14], [4, -20], [10, -2], [-16, 4]],
        [[4, -20], [24, -8], [18, 8], [10, -2]],
        [[-16, 4], [10, -2], [16, 14], [-10, 16]],
      ]
      g.poly(facets[2].flat().map((v, i) => v + (i % 2 ? SH_DY : SH_DX)))
        .fill({ color: SH_COL, alpha: SH_A })                                        // downslope shadow skirt
      for (let f = 0; f < facets.length; f++) {
        const lum = o.facetLum[f]
        const c = mix(0x000000, o.body, lum)
        g.poly(facets[f].flat()).fill(c).stroke({ width: 1.2, color: 0x4a453e })
      }
      for (let k = 0; k < o.lichenDots; k++) {                                       // lichen on the LIT facets only
        const lx = -20 + hash(k * 4.7 + 1.3) * 26
        const ly = -18 + hash(k * 6.1 + 2.9) * 20
        g.circle(lx, ly, 1.1).fill({ color: o.lichen, alpha: 0.7 })
      }
      for (let k = 0; k < o.screeChips; k++) {                                       // scree tail, downslope
        const sx = 14 + k * 6 + hash(k * 3.3) * 5
        const sy = 12 + k * 5 + hash(k * 5.9) * 5
        g.poly([sx, sy, sx + 4, sy - 2, sx + 5, sy + 3, sx + 1, sy + 4]).fill({ color: 0x6f675c, alpha: 0.85 })
      }
    })

    // ---- v5.11 kaiju redesign — the PLAYER's own body/tail (spec: "the one thing on screen the
    // player looks at constantly" was still the generic cross-chapter blob, ~44px on screen next to
    // a tower drawing up to 96px). Gated on CHAPTERS.skies.render.form === 'kaiju' (playerForm
    // below); every other chapter's rig — including pond/undergrowth, which also set `tail: true` —
    // never reads any of this and stays byte-identical.
    //
    // Same "identical geometry between the coloured and white bakes" contract drawEnemy/roster use:
    // `white` forces every fill to 0xffffff so the two textures share bounds (and therefore bake()'s
    // anchor), letting T.kaijuFlash swap onto pFlash for the hurt-flash pop without the silhouette
    // shifting under it. Unlike a structure plan there is no live per-instance radius to scale
    // against (PLAYER.radius never changes) so these bake AT THEIR FINAL ON-SCREEN SIZE directly —
    // no runtime scale factor, the same way T.playerBody itself already works.
    //
    // Limb polys are drawn FIRST with their socket end tucked well inside the torso's silhouette, so
    // the torso poly drawn on top of them hides the join and only the distal limb protrudes — the
    // same "flank sliver under the main deck" trick towerPlan uses above (this file, ~line 2748).
    const K = SKIES_KAIJU
    // Right-side torso profile, HEAD to TAIL-ROOT (top to bottom); mirrorShape closes it into a
    // symmetric polygon by appending the reversed, x-negated list — see its own comment.
    function mirrorShape(rightPts) {
      const left = rightPts.slice().reverse().map(([x, y]) => [-x, y])
      return rightPts.concat(left).flat()
    }
    function drawKaijuBody(g, white) {
      const bodyLit = white ? 0xffffff : K.bodyLit
      const bodyMid = white ? 0xffffff : K.bodyMid
      const bodyShade = white ? 0xffffff : K.bodyShade
      const plateBase = white ? 0xffffff : K.plateBase
      const plateEdge = white ? 0xffffff : K.plateEdge
      const scute = white ? 0xffffff : K.scute
      const band = white ? 0xffffff : K.band
      const jawDark = white ? 0xffffff : K.jawDark
      const teeth = white ? 0xffffff : K.teeth
      const claw = white ? 0xffffff : K.claw
      const horn = white ? 0xffffff : K.horn
      const eyeWhite = white ? 0xffffff : K.eyeWhite

      // forelimbs + hindlimbs: socket point first (hidden under the torso), a couple of knuckle
      // points, then the visible paw/foot with three claw ticks fanning off it. Filled a shade
      // LIGHTER than the plain body (mix toward bodyLit) — at the small size a limb actually
      // reads at, the plain bodyMid fill plus a dark stroke plus three dark claw ticks read as a
      // near-black stub, not "a green limb with dark claws"; the lighter fill keeps the green
      // identity legible even where the claw ticks cover a good fraction of the small shape.
      const limbFill = white ? 0xffffff : mix(bodyMid, bodyLit, 0.55)
      function limb(pts, clawAt, side) {
        const p = pts.map(([x, y]) => [x * side, y])
        g.poly(p.flat()).fill(limbFill).stroke({ width: 2, color: bodyShade, alpha: 0.75 })
        const cx = clawAt[0] * side, cy = clawAt[1]
        const base = Math.atan2(cy, cx)
        for (let c = -1; c <= 1; c++) {
          const a = base + c * 0.55
          g.moveTo(cx, cy).lineTo(cx + Math.cos(a) * 10, cy + Math.sin(a) * 10)
            .stroke({ width: 2.2, color: claw, cap: 'round' })
        }
      }
      for (const side of [-1, 1]) {
        limb([[46, -8], [84, 0], [116, 20], [98, 30], [70, 10]], [116, 20], side)     // forelimb
        limb([[44, 76], [80, 92], [88, 122], [66, 128], [42, 102]], [88, 122], side)  // hindlimb
      }

      // torso: broad shoulders tapering to the hips, MASS-CENTRED (0,0 sits mid-back, not the base)
      const torsoR = [
        [20, -58], [30, -44], [52, -24], [76, -2], [70, 24], [60, 52], [56, 80], [40, 104], [16, 122],
      ]
      g.poly(mirrorShape(torsoR)).fill(bodyMid).stroke({ width: 2.4, color: bodyShade })
      // volume: a lit top-plane biased upper-left (this chapter's ONE light direction — see
      // SKIES_SHADOW), a shaded flank biased lower-right. Same two-pass "volume" convention every
      // other creature in this file already uses (radialOutline's own doc comment), just biased by
      // the region's light law instead of a generic top/underside split.
      g.ellipse(-22, -8, 58, 70).fill({ color: bodyLit, alpha: 0.30 })
      g.ellipse(26, 38, 54, 62).fill({ color: bodyShade, alpha: 0.26 })

      // spine banding — surface detail, not silhouette
      for (let i = 0; i < K.bandCount; i++) {
        const by = lerp(-4, 80, i / (K.bandCount - 1))
        const hw = by < 10 ? 48 : by < 40 ? 34 : by < 65 ? 22 : 12
        g.moveTo(-hw, by).quadraticCurveTo(0, by + 6, hw, by).stroke({ width: 3, color: band, alpha: 0.28 })
      }
      // flank scutes: small overlapping bumps along both outer edges, each a 2-tone bump (a darker
      // base + a small lit fleck) so the flank reads as plated, not smooth
      for (let i = 0; i < K.scuteRows; i++) {
        const sy = lerp(-28, 94, i / (K.scuteRows - 1))
        for (const side of [-1, 1]) {
          const sx = (54 - Math.abs(sy) * 0.06) * side * 0.94
          g.ellipse(sx, sy, 9, 6).fill({ color: scute, alpha: 0.55 })
          g.ellipse(sx - side * 1.6, sy - 1.6, 4, 2.4).fill({ color: bodyLit, alpha: 0.28 })
        }
      }

      // DORSAL PLATES — BAKED ANATOMY FIRST. SKIES_FX.rampage's chain-charge glow (render.js
      // updateRampage) lands on these SAME (0, plateY) points SECOND, rather than an arc that used
      // to rotate with facingAngle regardless of this (non-rotating) body — see that function.
      const plateN = SKIES_FX.rampage.plates
      for (let i = 0; i < plateN; i++) {
        const f = i / (plateN - 1)
        const py = lerp(-44, 92, f)
        const bump = Math.max(0, 1 - Math.abs(f - 0.42) * 1.5)
        const h = lerp(8, 19, bump)
        g.poly([0, py - h, h * 0.6, py, 0, py + h * 0.8, -h * 0.6, py])
          .fill(plateBase).stroke({ width: 1.2, color: plateEdge, alpha: 0.7 })
      }

      // head: skull tapering to a point between two small brow horns, a jaw with jagged teeth, and
      // two white-sclera eyes (pupils are the existing pooled T.pupil sprites — see syncPlayer)
      const headW = 42
      g.poly([-headW, -60, headW, -60, headW * 0.85, -108, 0, -134, -headW * 0.85, -108])
        .fill(bodyMid).stroke({ width: 2.2, color: bodyShade })
      g.ellipse(-13, -100, 25, 29).fill({ color: bodyLit, alpha: 0.28 })   // skull top-plane
      for (const side of [-1, 1]) {
        g.poly([26 * side, -112, 14 * side, -140, 6 * side, -114]).fill(horn)   // brow horn
      }
      g.poly([-34, -60, 34, -60, 28, -44, 0, -36, -28, -44])
        .fill(jawDark).stroke({ width: 1.6, color: 0x0d1410 })                  // jaw
      for (let t = 0; t < K.jawTeeth; t++) {
        const tx = lerp(-26, 26, t / (K.jawTeeth - 1))
        g.poly([tx - 3, -50, tx + 3, -50, tx, -42]).fill(teeth)
      }
      for (const side of [-1, 1]) {
        g.circle(22 * side, -96, 13).fill(eyeWhite).stroke({ width: 1.4, color: bodyShade })
      }
      // pale chest hint just under the jaw — the one belly-toned accent on an otherwise back/flank
      // palette (cheap, and it keeps the head from reading as glued straight onto a solid green wall)
      g.ellipse(0, -30, 15, 19).fill({ color: eyeWhite, alpha: 0.16 })
    }
    T.kaijuBody = (() => { const g = new Graphics(); drawKaijuBody(g, false); return bake(g) })()
    T.kaijuFlash = (() => { const g = new Graphics(); drawKaijuBody(g, true); return bake(g) })()

    // ground shadow: the kaiju's own bigger disc (T.playerShadow, the generic blob's, is far too
    // small once the silhouette above is this big) — see syncPlayer for the SKIES_SHADOW-direction
    // offset this is placed at, instead of the generic blob's straight-down one.
    T.kaijuShadow = (() => {
      const g = new Graphics()
      g.ellipse(0, 0, K.shadowRx, K.shadowRy).fill({ color: 0x000000, alpha: 0.32 })
      return bake(g)
    })()

    // the articulated tail: ONE tapering, banded segment (reused for all three chain links at
    // decreasing scale — same "one texture, several instances" idiom tailA/tailB already used with
    // the plain T.fx.trace_05 streak) instead of the generic translucent flagellum every other
    // `tail: true` chapter still shows. Small dorsal-spike nubs continue the body's plate ridge onto
    // the tail so the two don't read as two unrelated systems.
    const TAIL_SEG_REF = 140
    // "a heavier, darker kaiju tail" (CHAPTERS.skies.render.tailTint's old doc, when the tail was
    // still the generic flagellum): baked a shade darker than the body itself, not tinted darker at
    // runtime — this bake carries its own final palette, same as the body (see drawKaijuBody above).
    const TAIL_FILL = mix(K.bodyMid, K.bodyShade, 0.4)
    T.kaijuTailSeg = (() => {
      const g = new Graphics()
      const L = TAIL_SEG_REF, W = 32
      g.poly([0, -W / 2, L * 0.5, -W * 0.32, L, 0, L * 0.5, W * 0.32, 0, W / 2])
        .fill(TAIL_FILL).stroke({ width: 2, color: K.bodyShade })
      g.poly([0, -W * 0.28, L * 0.55, -W * 0.16, L * 0.88, -2, L * 0.2, -W * 0.1])
        .fill({ color: K.bodyLit, alpha: 0.3 })   // top-plane highlight, biased along the same taper
      for (let k = 1; k <= 4; k++) {               // banding rings, tapering with the tail itself
        const x = (L * k) / 5
        const w = (W / 2) * (1 - x / L) * 0.92
        g.moveTo(x, -w).lineTo(x, w).stroke({ width: 2, color: K.band, alpha: 0.35 })
      }
      for (let k = 0; k < 3; k++) {                 // small dorsal-spike nubs continuing the ridge
        const x = 12 + (L * 0.68 * k) / 2
        const h = 8 * (1 - x / L)
        g.poly([x - 4, -W * 0.2, x + 4, -W * 0.2, x, -W * 0.2 - h]).fill(K.plateBase)
      }
      return { ...bake(g), ref: L }
    })()

    // ---- ruins (spec §5.9) — permanent geometry left where a structure was --------------------
    // Kind-specific, at the same cost as a generic scar, and the only thing in the chapter that
    // RECORDS what you did. Keyed by world position (the obstacle is gone from run.obstacles by
    // the time this draws) via the render-local crush ledger.
    function ruinBase(g, R) {
      g.circle(0, 0, R).fill({ color: SKIES_RUIN.scar, alpha: SKIES_RUIN.scarAlpha })
      for (let k = 0; k < SKIES_RUIN.rebarTicks; k++) {
        const a = (k / SKIES_RUIN.rebarTicks) * Math.PI * 2 + 0.4
        g.moveTo(Math.cos(a) * R * 0.7, Math.sin(a) * R * 0.7)
          .lineTo(Math.cos(a) * R * 1.05, Math.sin(a) * R * 1.05 - 3)
          .stroke({ width: 1.1, color: 0x6b6357, alpha: 0.9 })
      }
    }
    T.skRuin = {}
    T.skRuin.tower = skiesPlan((g) => {
      ruinBase(g, 32)
      for (let s = 0; s < SKIES_RUIN.byKind.tower.slabSteps; s++) {         // stepped floor-plate edges
        g.rect(-26 + s * 5, -20 + s * 6, 44 - s * 10, 5).fill({ color: 0x8d8577, alpha: 0.9 })
      }
      for (let c = 0; c < SKIES_RUIN.byKind.tower.rubbleChunks; c++) {
        const cx = -14 + c * 8 + hash(c * 3.3) * 6, cy = 4 + hash(c * 5.7) * 12
        g.poly([cx, cy, cx + 7, cy - 3, cx + 9, cy + 4, cx + 2, cy + 6]).fill(0xc9c2b0).stroke({ width: 0.8, color: 0x5a544a })
      }
      g.rect(16, -24, 9, 14).fill(0xc9c2b0).stroke({ width: 1, color: 0x5a544a })  // surviving corner column
      g.circle(0, 0, 30).stroke({ width: 4, color: 0x1a1712, alpha: 0.35 })        // scorch ring
    })
    T.skRuin.house = skiesPlan((g) => {
      ruinBase(g, 20)
      for (let k = 0; k < SKIES_RUIN.byKind.house.timberX; k++) {
        const cx = -14 + k * 9, cy = -6 + hash(k * 2.7) * 12
        g.moveTo(cx - 6, cy - 5).lineTo(cx + 6, cy + 5).stroke({ width: 2, color: 0xa8865c })
        g.moveTo(cx + 6, cy - 5).lineTo(cx - 6, cy + 5).stroke({ width: 2, color: 0x8a6a44 })
      }
      g.rect(8 + 2, -18 + 2.5, 9, 11).fill({ color: SH_COL, alpha: SH_A })
      g.rect(8, -18, 9, 11).fill(0x8f7a68).stroke({ width: 1, color: 0x5f3c2d })    // THE SURVIVING CHIMNEY
      g.rect(10, -16, 5, 3).fill(0x2a2018)
      for (let k = 0; k < SKIES_RUIN.byKind.house.shingles; k++) {
        const sx = -20 + hash(k * 4.1) * 40, sy = -14 + hash(k * 6.3) * 30
        g.rect(sx, sy, 4, 2.5).fill({ color: 0x7a4e3b, alpha: 0.85 })
      }
      g.rect(-20, 10, 14, 7).fill(0x6f7f8f).stroke({ width: 0.8, color: 0x2b3038 })  // flattened car
      g.rect(-18, 11.5, 10, 4).fill({ color: 0x1e2733, alpha: 0.8 })
    })
    T.skRuin.silo = skiesPlan((g) => {
      ruinBase(g, 24)
      g.beginPath().arc(0, 0, 20, Math.PI * 0.7, Math.PI * 1.9)
        .stroke({ width: 5, color: 0xc7c9cc })                                       // split cylinder wall arc
      g.poly([-6, 4, 26, 0, 30, 20, -2, 18]).fill({ color: SKIES_RUIN.byKind.silo.grainFan, alpha: 0.5 })
    })
    T.skRuin.barn = skiesPlan((g) => {
      ruinBase(g, 26)
      g.poly([-24, -14, 0, 6, 24, -14, 24, -6, 0, 14, -24, -6]).fill(0x74302a).stroke({ width: 1.2, color: 0x2e1a14 })
      const wa = STORM_VIS.windAngle
      for (let k = 0; k < 9; k++) {                                                  // hay strewn DOWNWIND
        const d = 10 + k * 4
        const hx = Math.cos(wa) * d + (hash(k * 3.7) - 0.5) * 10
        const hy = Math.sin(wa) * d + (hash(k * 5.1) - 0.5) * 10
        g.rect(hx, hy, 5, 1.6).fill({ color: 0xc9a94a, alpha: 0.75 })
      }
    })
    T.skRuin.pier = skiesPlan((g) => {
      ruinBase(g, 20)
      g.ellipse(4, 4, 26, 15).fill({ color: 0x5a4a6a, alpha: 0.32 })                 // iridescent oil slick
      g.ellipse(0, 2, 17, 10).fill({ color: 0x3a5a6a, alpha: 0.28 })
      for (let k = 0; k < SKIES_RUIN.byKind.pier.plankRaft; k++) {
        const px = -20 + hash(k * 3.9) * 38, py = -12 + hash(k * 6.7) * 26
        const pa = hash(k * 8.1) * Math.PI
        const dx = Math.cos(pa) * 8, dy = Math.sin(pa) * 8
        g.moveTo(px - dx, py - dy).lineTo(px + dx, py + dy)
          .stroke({ width: 2.6, color: 0xa9835a, cap: 'square' })
      }
    })
    T.skRuin.tree = skiesPlan((g) => {
      ruinBase(g, 14)
      g.circle(0, 0, 7).fill(0x5a4a38).stroke({ width: 1.2, color: 0x2e2620 })       // stump
      for (let k = 0; k < 10; k++) {                                                  // splintered crown ring
        const a = (k / 10) * Math.PI * 2
        g.moveTo(Math.cos(a) * 5, Math.sin(a) * 5).lineTo(Math.cos(a) * 9, Math.sin(a) * 9)
          .stroke({ width: 1.2, color: 0xc9b48a })
      }
      for (let k = 0; k < SKIES_RUIN.byKind.tree.branches; k++) {
        const a = hash(k * 4.3) * Math.PI * 2, d = 12 + hash(k * 7.1) * 14
        g.moveTo(Math.cos(a) * d, Math.sin(a) * d)
          .lineTo(Math.cos(a) * d + 8, Math.sin(a) * d + 3)
          .stroke({ width: 1.6, color: 0x46583b })
      }
    })

    // ---- vehicles (spec §6) — "you must be able to tell a bus from a sedan" -------------------
    // Replaces T.car (the CITY chapter's yellow traffic taxi, baked from TRAFFIC_CAR_LEN) for skies
    // use. Bodies bake WHITE so SKIES_VEHICLE.bodyTints drives the colour per instance and litTint
    // keeps the floor tint out of it; glass/wheels bake as low-value greys so they multiply DOWN
    // under any body colour and the hierarchy holds.
    const V = SKIES_VEHICLE
    function vehicle(spec, kind) {
      const g = new Graphics()
      const L = spec.len / 2, W = spec.w / 2
      g.roundRect(-L + SH_DX * 0.12, -W + SH_DY * 0.12, spec.len, spec.w, 2.5)
        .fill({ color: SH_COL, alpha: SH_A })
      for (const s of [-1, 1]) {                                                    // wheels peeking at the corners
        const n = spec.wheels / 2
        for (let k = 0; k < n; k++) {
          const wx = -L + 3 + (k * (spec.len - 7)) / Math.max(1, n - 1)
          g.rect(wx - 2, s * W - 1.2, 4, 2.5).fill(V.wheel)
        }
      }
      g.roundRect(-L, -W, spec.len, spec.w, 2.5).fill(0xffffff).stroke({ width: 1, color: 0x6a6f76 })
      g.rect(-L + 2, -W + 1.4, spec.len - 4, 1.6).fill({ color: 0xffffff, alpha: 0.55 })  // roof highlight streak
      if (kind === 'bus') {
        for (let k = 0; k < spec.windowBays; k++) {                                 // 6 window bays per flank
          const bx = -L + 5 + k * ((spec.len - 10) / spec.windowBays)
          for (const s of [-1, 1]) {
            g.rect(bx, s * (W - 3.4) - 1.2, (spec.len - 10) / spec.windowBays - 2, 2.6)
              .fill({ color: V.glass, alpha: V.glassAlpha })
          }
        }
        g.rect(L - 5, -3, 3.5, 6).fill(0xd8d4c8)                                     // destination board
        for (let k = 0; k < spec.roofHatches; k++) g.rect(-6 + k * 9, -2, 5, 4).fill(0x7a7f86)
        g.moveTo(-2, -W).lineTo(-2, W).stroke({ width: 0.9, color: 0x5a5f66 })        // double-door seam
        g.moveTo(1, -W).lineTo(1, W).stroke({ width: 0.9, color: 0x5a5f66 })
      } else {
        g.poly([L - 8, -W + 1.5, L - 3, -W + 3.4, L - 3, W - 3.4, L - 8, W - 1.5])
          .fill({ color: V.glass, alpha: V.glassAlpha })                              // windshield trapezoid
        if (kind === 'sedan') {
          g.poly([-L + 8, -W + 1.5, -L + 3, -W + 3.4, -L + 3, W - 3.4, -L + 8, W - 1.5])
            .fill({ color: V.glass, alpha: V.glassAlpha })                            // rear screen
          for (const s of [-1, 1]) g.rect(L - 10, s * (W + 0.4) - 0.7, 2, 1.4).fill(0x6a6f76) // mirror nubs
          for (const sx of [-3, 4]) g.moveTo(sx, -W).lineTo(sx, W).stroke({ width: 0.7, color: 0x6a6f76, alpha: 0.6 })
        } else {
          g.rect(-2, -2.5, 5, 4).fill(0x7a7f86)                                       // roof vent
          g.moveTo(2, -W).lineTo(2, W).stroke({ width: 0.9, color: 0x6a6f76 })         // sliding-door seam
        }
      }
      for (const s of [-1, 1]) {
        g.circle(L - 1.4, s * (W - 2.6), 1.1).fill(V.head)
        g.circle(-L + 1.4, s * (W - 2.6), 1).fill(V.tail)
      }
      return bake(g, 1)
    }
    T.vehSedan = vehicle(V.sedan, 'sedan')
    T.vehVan = vehicle(V.van, 'van')
    T.vehBus = vehicle(V.bus, 'bus')

    // ---- district surfaces (spec §4.5) --------------------------------------------------------
    function groundTile(draw) { const g = new Graphics(); draw(g); return bake(g) }
    // v5.13: T.districtGround.parks (the mown-stripe bake) is deleted from here — it was written in
    // v5.10 for populateBlotch, which returns early for every chapter that has a terrain map, so it
    // was never drawn once. The stripes now live in T.terrainTile.parks, which populateTerrain
    // actually reads.
    // farms: a CENTRE-PIVOT IRRIGATION CIRCLE. A perfect circle in a field of straight rows is
    // unmistakable from overhead and exists nowhere else in nature.
    T.pivotCircle = groundTile((g) => {
      const f = DISTRICT_SURFACE.farms
      const R = f.pivotRadius / 2
      g.circle(0, 0, R).stroke({ width: 5, color: 0xffffff, alpha: f.pivotAlpha })
      g.circle(0, 0, R * 0.62).stroke({ width: 3, color: 0xffffff, alpha: f.pivotAlpha * 0.7 })
      g.moveTo(0, 0).lineTo(R, -R * 0.12).stroke({ width: 3.5, color: 0xffffff, alpha: f.pivotAlpha * 1.4 }) // pivot arm
      g.circle(0, 0, 6).fill({ color: 0xffffff, alpha: f.pivotAlpha * 2 })
      g.rect(-R, R - f.headlandPx, R * 2, f.headlandPx).fill({ color: 0xffffff, alpha: 0.08 })       // headland strip
    })
    // sea: a CONTAINER YARD. Tiny dense saturated rectangles against dark water is the highest
    // detail-density-per-line-of-code in the whole redesign, and the only place in the chapter
    // where hue does the talking (litTint — a tinted container yard is just a grey grid).
    T.containerYard = (() => {
      const g = new Graphics()
      const s = DISTRICT_SURFACE.sea
      g.rect(-s.yardCols * 9 - 6, -s.yardRows * 6 - 6, s.yardCols * 18 + 12, s.yardRows * 12 + 12)
        .fill({ color: 0x3a4048, alpha: 0.7 })                                        // the hardstand
      for (let c = 0; c < s.yardCols; c++) {
        for (let r = 0; r < s.yardRows; r++) {
          const bx = -s.yardCols * 9 + c * 18, by = -s.yardRows * 6 + r * 12
          const hue = s.boxHues[Math.floor(hash(c * 7.7 + r * 3.1) * s.boxHues.length)]
          g.rect(bx + SH_DX * 0.06, by + SH_DY * 0.06, s.boxW, s.boxH).fill({ color: SH_COL, alpha: SH_A })
          g.rect(bx, by, s.boxW, s.boxH).fill(hue).stroke({ width: 0.6, color: 0x1a1d22 })
          for (let k = 1; k < 4; k++) {
            g.moveTo(bx + (s.boxW * k) / 4, by).lineTo(bx + (s.boxW * k) / 4, by + s.boxH)
              .stroke({ width: 0.4, color: 0x000000, alpha: 0.28 })                    // corrugation
          }
        }
      }
      return bake(g)
    })()
    T.riprap = (() => {                                                                // breakwater arm
      const g = new Graphics()
      for (let k = 0; k < 14; k++) {
        const bx = -90 + k * 13 + (hash(k * 2.7) - 0.5) * 5
        const by = Math.sin(k * 0.42) * 12 + (hash(k * 5.1) - 0.5) * 6
        const r = 7 + hash(k * 3.3) * 4
        const pts = []
        for (let s = 0; s < 5; s++) {
          const a = (s / 5) * Math.PI * 2
          const rr = r * (0.7 + hash(k * 11 + s * 2.1) * 0.5)
          pts.push(bx + Math.cos(a) * rr, by + Math.sin(a) * rr)
        }
        g.poly(pts).fill(0x7d838c).stroke({ width: 1, color: 0x3a3f47 })
      }
      return bake(g)
    })()
    // a REAL wave crest: two parallel crest arcs and a foam speckle band. Kill list §8.6 — T.foam
    // is `T.fx.trace_05`, i.e. the sea's breaking wave IS the POND's current-streak sprite, reused
    // again by populateEdge for coastlines.
    T.waveCrest = (() => {
      const g = new Graphics()
      const s = DISTRICT_SURFACE.sea
      for (let a = 0; a < s.crestArcs; a++) {
        g.moveTo(-60, a * 7).quadraticCurveTo(0, -9 + a * 7, 60, a * 7)
          .stroke({ width: 2.6 - a * 0.8, color: s.foam, alpha: s.crestAlpha - a * 0.12, cap: 'round' })
      }
      for (let k = 0; k < s.foamSpeckle; k++) {
        const fx = -58 + hash(k * 3.7) * 116
        const fy = -6 + hash(k * 6.1) * 16
        g.circle(fx, fy, 0.9 + hash(k * 9.3) * 1.2).fill({ color: s.foam, alpha: 0.3 + hash(k * 2.3) * 0.3 })
      }
      return bake(g)
    })()
    // downtown: a painted parking lot. Cars park ALIGNED TO THE STALL ANGLE — random rotation is
    // the loudest possible tell that props were scattered by an algorithm, not placed by a city.
    T.parkingLot = (() => {
      const g = new Graphics()
      const d = DISTRICT_SURFACE.downtown
      const bayW = 13, bayL = 26
      g.rect(-d.baysPerRow * bayW / 2 - 8, -bayL - 10, d.baysPerRow * bayW + 16, bayL * 2 + 20)
        .fill({ color: 0x2b2f36, alpha: 0.8 })
      for (let r = 0; r < d.bayRows; r++) {
        for (let b = 0; b <= d.baysPerRow; b++) {
          const bx = -d.baysPerRow * bayW / 2 + b * bayW
          const by = r === 0 ? -bayL - 4 : 4
          g.rect(bx, by, 1.6, bayL).fill({ color: d.paint, alpha: d.paintAlpha })
        }
      }
      for (let k = 0; k < 7; k++) {                                                    // one hatched loading bay
        g.moveTo(-d.baysPerRow * bayW / 2 - 6, -bayL - 8 + k * 5)
          .lineTo(-d.baysPerRow * bayW / 2 + 12, -bayL - 16 + k * 5)
          .stroke({ width: 1.4, color: d.paint, alpha: 0.4 })
      }
      return bake(g)
    })()
    // hills: dirt track. v5.10.1: was three flat strokes of one colour at up to 250px — "exactly the
    // simple squares and lines" the user rejected for a landmark-sized bake. Now: a shadowed bed (the
    // track sits IN the terrain), TWIN tire ruts rather than one flat band, and a scatter of gravel.
    T.switchback = (() => {
      const g = new Graphics()
      const h = DISTRICT_SURFACE.hills
      const pts = [[-80, 40], [30, 14], [-40, -14], [70, -42]]
      for (let k = 0; k < pts.length - 1; k++) {
        g.moveTo(pts[k][0], pts[k][1]).lineTo(pts[k + 1][0], pts[k + 1][1])
          .stroke({ width: h.trackW + 5, color: 0x000000, alpha: 0.18, cap: 'round', join: 'round' })
      }
      for (const side of [-1, 1]) {
        for (let k = 0; k < pts.length - 1; k++) {
          const [x0, y0] = pts[k], [x1, y1] = pts[k + 1]
          const dx = x1 - x0, dy = y1 - y0
          const len = Math.hypot(dx, dy) || 1
          const nx = (-dy / len) * side * h.trackW * 0.28, ny = (dx / len) * side * h.trackW * 0.28
          g.moveTo(x0 + nx, y0 + ny).lineTo(x1 + nx, y1 + ny)
            .stroke({ width: h.trackW * 0.36, color: h.trackColor, alpha: 0.75, cap: 'round', join: 'round' })
        }
      }
      for (let i = 0; i < 14; i++) {                                              // scattered gravel
        const seg = Math.floor(hash(i * 3.7) * (pts.length - 1))
        const t = hash(i * 5.1 + 1)
        const [x0, y0] = pts[seg], [x1, y1] = pts[seg + 1]
        const gx = x0 + (x1 - x0) * t + (hash(i * 7.3) - 0.5) * h.trackW * 0.9
        const gy = y0 + (y1 - y0) * t + (hash(i * 2.9) - 0.5) * h.trackW * 0.9
        g.circle(gx, gy, 1 + hash(i * 4.1) * 1.4).fill({ color: 0x4a3f30, alpha: 0.5 + hash(i * 6.6) * 0.3 })
      }
      return bake(g)
    })()
    // district SEAMS (kill list §8.11): populateEdge draws T.fence — a picket fence — at EVERY
    // land/land border, including between a farm and a moor. A seam is a chance to say what the two
    // regions are; three seam bakes cost the same as one reused one.
    T.hedgeSeam = (() => {
      const g = new Graphics()
      const h = DISTRICT_EDGE.hedge
      for (let k = 0; k < h.lobes; k++) {
        const hx = (k - (h.lobes - 1) / 2) * h.pitchPx * 0.55
        g.circle(hx, (hash(k * 3.1) - 0.5) * 4, 8 + hash(k * 5.3) * 3).fill(h.color)
      }
      g.rect(-h.lobes * h.pitchPx * 0.3, 5, h.lobes * h.pitchPx * 0.6, 3).fill({ color: 0x000000, alpha: 0.25 })
      return bake(g)
    })()
    // v5.10.1: was a filled rect + 16 IDENTICAL 2px ticks — no stone outlines, no cap course. Now a
    // running-bond course of individually-outlined stone blocks (two staggered rows, joints offset
    // like a real dry-stone wall) plus a lighter cap-stone line along the top.
    T.wallSeam = (() => {
      const g = new Graphics()
      const w = DISTRICT_EDGE.wall
      g.rect(-70, -4, 140, 8).fill({ color: w.color, alpha: 0.9 })
      const blockW = w.pitchPx * 0.62
      for (const row of [0, 1]) {
        const y0 = -4 + row * 4
        const offset = row ? blockW * 0.5 : 0
        for (let x = -70 - offset; x < 70; x += blockW) {
          const bx0 = Math.max(-70, x), bx1 = Math.min(70, x + blockW)
          if (bx1 <= bx0) continue
          g.rect(bx0, y0, bx1 - bx0, 4).stroke({ width: 0.9, color: 0x000000, alpha: row ? 0.28 : 0.32 })
        }
      }
      g.rect(-70, -4, 140, 1.6).fill({ color: 0xffffff, alpha: 0.12 })   // cap course: a lighter lid line
      g.rect(-70, 4, 140, 2.5).fill({ color: 0x000000, alpha: 0.3 })     // ground-contact shadow
      return bake(g)
    })()

    // ---- threat glyphs (spec §3.2) -----------------------------------------------------------
    // "Everything STATIC in a telegraph is a BAKED TEXTURE scaled to the live radius; only the
    // MOVING element is per-frame Graphics." This is not a mitigation, it is the design —
    // SHELL_MAX_LIVE (6) and MAX_STRAFE_LOCKS (10) telegraphs of graduated ticks drawn live would
    // not hold on a phone. All of these bake WHITE so one glyph can be tinted per threat.
    const TREF = 100
    // ARTILLERY: the only SQUARE telegraph in the game. Four L corner brackets + ranging
    // graduations on two edges (every 3rd long) — a surveyor's target box, not a circle.
    T.tgSquare = (() => {
      const g = new Graphics()
      const a = SKIES_FX.artillery
      const arm = TREF * 0.34
      for (const sx of [-1, 1]) {
        for (const sy of [-1, 1]) {
          g.moveTo(sx * TREF, sy * TREF - sy * arm).lineTo(sx * TREF, sy * TREF)
            .lineTo(sx * TREF - sx * arm, sy * TREF)
            .stroke({ width: 5, color: 0xffffff, join: 'miter', cap: 'butt' })
        }
      }
      for (let k = 0; k < a.graduations; k++) {                      // ranging ticks on two edges
        const t = -TREF * 0.55 + (k / (a.graduations - 1)) * TREF * 1.1
        const long = k % a.gradEveryLong === 0
        g.rect(t - 1.5, -TREF, 3, long ? 13 : 7).fill({ color: 0xffffff, alpha: 0.9 })
        g.rect(-TREF, t - 1.5, long ? 13 : 7, 3).fill({ color: 0xffffff, alpha: 0.9 })
      }
      return { ...bake(g, 0), ref: TREF }
    })()
    // the sweeping hand, in two parts so the dark HATCH BARS and the ochre wedge FILL can be
    // tinted independently (the only hatched fill in the game, per the threat table)
    T.tgHandFill = (() => {
      const g = new Graphics()
      g.poly([0, 0, TREF, -TREF * 0.17, TREF, TREF * 0.17]).fill(0xffffff)
      return { ...bake(g, 0), ref: TREF }
    })()
    T.tgHandBars = (() => {
      const g = new Graphics()
      for (let k = 0; k < 6; k++) {
        const x0 = TREF * (0.16 + k * 0.14)
        const hw = x0 * 0.17
        g.moveTo(x0 - 6, -hw).lineTo(x0 + 6, hw).stroke({ width: 3.2, color: 0xffffff, cap: 'butt' })
      }
      return { ...bake(g, 0), ref: TREF }
    })()
    // the falling shell's OWN shadow — hard-ish edge (a shadow, not a glow). ARTILLERY ONLY (v5.10.1:
    // this used to also serve sky's ionisation wash and crush's warm interior spill — three unrelated
    // threats sharing one texture, tinted differently, which a reviewer correctly called out as "not
    // actually differentiated" — see T.skyIonWash and T.crushSpill below for their own dedicated bakes.
    T.shellShadow = { tex: canvasTex(128, 128, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,1)')
      gr.addColorStop(0.7, 'rgba(255,255,255,0.92)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    }), ax: 0.5, ay: 0.5, ref: 64 }
    // sky's OWN ionisation wash — a soft, no-hard-edge diffuse haze (reads as ENERGY, not MASS),
    // unlike T.shellShadow's opaque disc with a hard-ish 0.7 cutoff (reads as a solid falling object).
    T.skyIonWash = { tex: canvasTex(128, 128, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0.8)')
      gr.addColorStop(0.4, 'rgba(255,255,255,0.4)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')     // pure soft falloff, no hard edge anywhere
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    }), ax: 0.5, ay: 0.5, ref: 64 }
    // SKY: the impact mark is a ring of INWARD-POINTING CHEVRONS closing on the strike point — NOT
    // corner brackets. v5.10.1 P0 fix: T.skyBrackets used to be T.tgSquare's four L corners
    // copy-pasted with different arm/width numbers (both shrink inward over the fuse, both sat on the
    // SAME shellShadow disc) — two of the spec's three separation axes shared, and past
    // SKIES_TELEGRAPH_LOD_PX the `far` gate strips everything else, leaving "a bracket + a disc" as
    // literally the same picture in different tints (fails the spec's own greyscale test, §9.5). A
    // ring of chevrons is a fundamentally different silhouette from a square of L corners even in
    // greyscale, at any distance, and it echoes the descent vector's own sliding chevrons (§3 sky row)
    // instead of borrowing artillery's language.
    T.skyChevrons = (() => {
      const g = new Graphics()
      const n = 6
      const arm = TREF * 0.24
      for (let i = 0; i < n; i++) {
        const a = (i / n) * Math.PI * 2
        const cx = Math.cos(a) * TREF, cy = Math.sin(a) * TREF
        const ux = -Math.cos(a), uy = -Math.sin(a)          // inward, toward the strike point
        const px2 = -uy, py2 = ux
        g.moveTo(cx + px2 * arm * 0.55, cy + py2 * arm * 0.55)
          .lineTo(cx + ux * arm, cy + uy * arm)
          .lineTo(cx - px2 * arm * 0.55, cy - py2 * arm * 0.55)
          .stroke({ width: 7, color: 0xffffff, join: 'round', cap: 'round' })
      }
      return { ...bake(g, 0), ref: TREF }
    })()
    // Lichtenberg trees — dendritic branches burned into the ground by a strike. Pre-computed
    // (4 variants so no two scars match), recursive, 3 generations, tapering.
    T.branchTree = []
    for (let v = 0; v < SKIES_FX.sky.branchTrees; v++) {
      const g = new Graphics()
      const grow = (x, y, ang, len, w, gen, salt) => {
        const ex = x + Math.cos(ang) * len, ey = y + Math.sin(ang) * len
        g.moveTo(x, y).lineTo(ex, ey).stroke({ width: w, color: 0xffffff, cap: 'round' })
        if (gen <= 0) return
        const n = 2 + (hash(salt * 3.1) > 0.6 ? 1 : 0)
        for (let k = 0; k < n; k++) {
          const spread = (hash(salt * 5.7 + k * 2.3) - 0.5) * 1.5
          grow(ex, ey, ang + spread, len * (0.52 + hash(salt * 7.3 + k) * 0.25), w * 0.55, gen - 1, salt * 1.7 + k * 4.1 + 3)
        }
      }
      for (let s = 0; s < 5; s++) {
        const a = (s / 5) * Math.PI * 2 + v * 0.4
        grow(0, 0, a, 46 + hash(v * 3.3 + s) * 20, 4.5, 2, v * 11 + s * 2.7 + 1)
      }
      T.branchTree.push({ ...bake(g), ref: 200 })
    }
    // MISSILE: a rotating lock diamond — four corner ticks on a 45-degree square, anchored on YOU.
    // The only mark in the game that lives on the player.
    T.lockDiamond = (() => {
      const g = new Graphics()
      const R = SKIES_FX.missile.diamondPx / 2
      for (let k = 0; k < 4; k++) {
        const a = (k / 4) * Math.PI * 2 + Math.PI / 4
        const cx = Math.cos(a) * R, cy = Math.sin(a) * R
        const ta = a + Math.PI / 2
        g.moveTo(cx - Math.cos(ta) * R * 0.42, cy - Math.sin(ta) * R * 0.42)
          .lineTo(cx, cy).lineTo(cx + Math.cos(ta) * R * 0.42, cy + Math.sin(ta) * R * 0.42)
          .stroke({ width: 3, color: 0xffffff, join: 'miter' })
      }
      return { ...bake(g, 0), ref: R }
    })()
    T.missileDart = (() => {                                    // the physical projectile itself
      const g = new Graphics()
      g.poly([9, 0, 2, -3, -8, -3, -8, 3, 2, 3]).fill(0xd8d4cc).stroke({ width: 1, color: 0x2a2620 })
      g.poly([-4, -3, -9, -7, -6, -3]).fill(0x8a8f96)
      g.poly([-4, 3, -9, 7, -6, 3]).fill(0x8a8f96)
      g.rect(-2, -1.2, 6, 2.4).fill({ color: 0xff2d6f, alpha: 0.9 })   // signal-magenta band
      return bake(g)
    })()
    T.magentaStar = (() => {                                    // missile impact: a hard star
      const g = new Graphics()
      const pts = []
      for (let k = 0; k < 12; k++) {
        const a = (k / 12) * Math.PI * 2
        const r = k % 2 ? 8 : 26
        pts.push(Math.cos(a) * r, Math.sin(a) * r)
      }
      g.poly(pts).fill(0xffffff)
      return bake(g)
    })()
    T.sootRing = { tex: canvasTex(128, 128, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, w * 0.18, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0)')
      gr.addColorStop(0.45, 'rgba(255,255,255,0.85)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    }), ax: 0.5, ay: 0.5 }
    // JET: the halogen landing-light pool, additive, aspect 1 : 0.22
    T.landingPool = canvasTex(512, 112, (ctx, w, h) => {
      ctx.save(); ctx.translate(w / 2, h / 2); ctx.scale(1, h / w)
      const gr = ctx.createRadialGradient(0, 0, 0, 0, 0, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,1)')
      gr.addColorStop(0.5, 'rgba(255,255,255,0.42)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(0, 0, w / 2, 0, Math.PI * 2); ctx.fill(); ctx.restore()
    })
    // CRUSH: angular hard-edged shards with VISIBLE EDGES (slab / roof tile / plank). This is what
    // replaces crushBurst's soft round Kenney circle_05 puffs — soft round particles are precisely
    // what makes a collapsing building read as a cartoon dust cloud (kill list §8.4).
    T.shard = [
      (() => { const g = new Graphics(); g.poly([-7, -5, 8, -6, 7, 5, -6, 6]).fill(0xffffff).stroke({ width: 1.4, color: 0x7a7a7a }); return bake(g) })(),
      (() => { const g = new Graphics(); g.poly([-5, -4, 6, -6, 4, 5, -6, 3]).fill(0xffffff).stroke({ width: 1.2, color: 0x707070 }); g.moveTo(-4, 0).lineTo(4, -1).stroke({ width: 0.8, color: 0x8a8a8a }); return bake(g) })(),
      (() => { const g = new Graphics(); g.poly([-11, -2.5, 11, -3.5, 11, 2.5, -11, 3.5]).fill(0xffffff).stroke({ width: 1.1, color: 0x757575 }); return bake(g) })(),
    ]
    T.dustSkirt = canvasTex(256, 128, (ctx, w, h) => {
      ctx.save(); ctx.translate(w / 2, h / 2); ctx.scale(1, h / w)
      const gr = ctx.createRadialGradient(0, 0, 0, 0, 0, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0.55)')
      gr.addColorStop(0.55, 'rgba(255,255,255,0.26)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.beginPath(); ctx.arc(0, 0, w / 2, 0, Math.PI * 2); ctx.fill(); ctx.restore()
    })
    T.clod = (() => {
      const g = new Graphics()
      g.poly([-4, -3, 4, -4, 5, 2, -2, 4]).fill(0xffffff).stroke({ width: 1, color: 0x6a6a6a })
      return bake(g)
    })()
    T.smokePuff = canvasTex(64, 64, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0.85)')
      gr.addColorStop(0.6, 'rgba(255,255,255,0.32)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    })
    // v5.10.1: a denser, harder-edged core than T.smokePuff's fully-gauzy falloff — grit is solid
    // debris, smoke is gas, and they should not read as the same particle at different sizes.
    T.gritPuff = canvasTex(32, 32, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,1)')
      gr.addColorStop(0.55, 'rgba(255,255,255,0.9)')
      gr.addColorStop(0.75, 'rgba(255,255,255,0.3)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    })
    // JET stitch: the small dark ground-scorch mark the tracer dash leaves. This glyph's "home".
    T.scorchTick = (() => {
      const g = new Graphics()
      g.poly([-3, -1.4, 3, -1.8, 3.4, 1.4, -2.6, 1.8]).fill(0xffffff)
      return bake(g)
    })()
    // v5.10.1: T.scorchTick used to also serve sky's rising sparks and missile's impact sparks —
    // three unrelated threats sharing one small glyph. Each gets its own shape now: sky's sparks
    // RISE (a thin vertical streak, not a ground-hugging flag) and missile's are a radiating fleck.
    T.sparkTick = (() => {                                     // SKY: a thin rising spark streak
      const g = new Graphics()
      g.poly([0, 3.2, 0.7, -3.2, 0, -4, -0.7, -3.2]).fill(0xffffff)
      return bake(g)
    })()
    T.impactFleck = (() => {                                   // MISSILE: a small radiating diamond
      const g = new Graphics()
      g.poly([0, -3.4, 2.3, 0, 0, 3.4, -2.3, 0]).fill(0xffffff)
      return bake(g)
    })()
    T.artFireball = (() => {                                   // BLACK-CORED fireball: ordnance, not a pop
      const g = new Graphics()
      g.circle(0, 0, 30).fill({ color: SKIES_FX.artillery.fireball, alpha: 0.85 })
      g.circle(0, 0, 20).fill({ color: SKIES_FX.artillery.fireball, alpha: 1 })
      g.circle(2, 1, 11).fill(SKIES_FX.artillery.fireballCore)
      return bake(g)
    })()
    // v5.10.1 P0 fix: warm interior-spill glow (crush's ONE beat of ambience gold, spec palette law
    // 1) used to reuse T.shellShadow — a hard-edged FALLING-OBJECT shadow tinted gold. A soft square
    // glow (matching the palette law's "static <=5px lit rectangle" language) is a genuinely different
    // read: light bleeding from a window, not a shadow cast by something overhead.
    T.crushSpill = canvasTex(96, 96, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0.9)')
      gr.addColorStop(0.5, 'rgba(255,255,255,0.4)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr
      ctx.fillRect(w * 0.28, w * 0.28, w * 0.44, w * 0.44)   // a soft SQUARE spill, not a disc
    })
    // VOLATILE ELITE BOMB (spec-adjacent P0 fix, config.js SKIES_FX.volatile) — a toothed ring that
    // GROWS unstable rather than closing inward like gun/sky, so its motion axis differs from both.
    // Acid-green, never red (palette law: red is alert-only), never violet or ochre.
    T.voltRing = (() => {
      const g = new Graphics()
      const teeth = 10
      for (let i = 0; i < teeth; i++) {
        const a = (i / teeth) * Math.PI * 2
        const x0 = Math.cos(a) * TREF * 0.86, y0 = Math.sin(a) * TREF * 0.86
        const x1 = Math.cos(a) * TREF * 1.08, y1 = Math.sin(a) * TREF * 1.08
        g.moveTo(x0, y0).lineTo(x1, y1).stroke({ width: 6, color: 0xffffff, cap: 'round' })
      }
      g.circle(0, 0, TREF * 0.86).stroke({ width: 3, color: 0xffffff, alpha: 0.7 })
      return { ...bake(g, 0), ref: TREF }
    })()
    T.voltSpike = (() => {                                     // detonation: a hard acid spike, not
      const g = new Graphics()                                  // a fireball and not a bolt
      g.poly([0, -10, 2.6, -1.5, 0, 0, -2.6, -1.5]).fill(0xffffff)
      return bake(g)
    })()
    T.voltCore = canvasTex(48, 48, (ctx, w) => {                // the small pulsing unstable core —
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)   // its own dedicated
      gr.addColorStop(0, 'rgba(255,255,255,1)')                                   // glow, not T.dot
      gr.addColorStop(0.5, 'rgba(255,255,255,0.5)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    })
    T.plate = (() => {                                         // rampage dorsal plate
      const g = new Graphics()
      g.poly([0, -9, 6, 0, 0, 8, -6, 0]).fill(0xffffff)
      return bake(g)
    })()
    // v5.10.1: the rampage heartbeat ring used to reuse T.novaRing — the SAME plain double-ring
    // shared with revive and shatter (both also 0.35-0.45s). T.novaRing stays exactly as-is (it is
    // cross-chapter shared machinery, "the same neutral ring, recolored", used well beyond skies —
    // touching it would be an unrequested change to every other chapter). Rampage gets its own
    // notched pulse ring instead, so its "only looping effect" is not a recolor of two other systems.
    T.rampagePulse = (() => {
      const g = new Graphics()
      g.circle(0, 0, 64).stroke({ width: 6, color: 0xffffff, alpha: 0.55 })
      const teeth = 10
      for (let i = 0; i < teeth; i++) {
        const a = (i / teeth) * Math.PI * 2
        g.moveTo(Math.cos(a) * 58, Math.sin(a) * 58).lineTo(Math.cos(a) * 76, Math.sin(a) * 76)
          .stroke({ width: 3, color: 0xffffff })
      }
      return bake(g)
    })()
    // v5.10.1: the rampage screen bloom used to be a bare `T.fx.circle_05` — the same Kenney particle
    // hydrant bubbles, conduct arcs and traffic exhaust all reuse verbatim. A screen bloom's shape IS
    // correctly a soft radial gradient (that is what a glow is), so the fix here is giving rampage its
    // OWN hand-authored bake rather than sharing the literal asset three unrelated effects use.
    T.rampageBloom = canvasTex(256, 256, (ctx, w) => {
      const gr = ctx.createRadialGradient(w / 2, w / 2, 0, w / 2, w / 2, w / 2)
      gr.addColorStop(0, 'rgba(255,255,255,0.9)')
      gr.addColorStop(0.35, 'rgba(255,255,255,0.55)')
      gr.addColorStop(0.7, 'rgba(255,255,255,0.18)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    })
    // v5.10.1: artillery's muzzle flash and missile's exhaust used to both reuse the generic
    // T.fx.flare_01 (shared, elsewhere in this file, by frostarc/shockarc/homing/beam — fine for
    // those, since they are not one of this chapter's own six threats). These two ARE, so they get
    // their own small bakes: a muzzle flash is a hard angular burst, an exhaust is a soft trailing
    // comet, and neither is the shared round flare.
    T.muzzleFlash = (() => {
      const g = new Graphics()
      const pts = []
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2
        const r = k % 2 ? 4 : 11
        pts.push(Math.cos(a) * r, Math.sin(a) * r)
      }
      g.poly(pts).fill(0xffffff)
      return bake(g)
    })()
    T.exhaustPuff = canvasTex(48, 48, (ctx, w) => {
      const gr = ctx.createRadialGradient(w * 0.6, w / 2, 0, w * 0.6, w / 2, w * 0.5)
      gr.addColorStop(0, 'rgba(255,255,255,0.9)')
      gr.addColorStop(0.5, 'rgba(255,255,255,0.4)')
      gr.addColorStop(1, 'rgba(255,255,255,0)')
      ctx.fillStyle = gr; ctx.fillRect(0, 0, w, w)
    })

    // v5.16: the LIGHT LAYER is gone — searchlight cones, kerb lamps, klaxon rings and the
    // blinking aviation beacons, plus their four bakes (T.lightCone/T.lampPool/T.klaxonRing/
    // T.lampMast) and every pool and update that drove them. It was the chapter's stated identity
    // ("the lights are looking for you") and it was also, by volume, the largest source of moving
    // pale shapes on the floor. Removed on the same call as the rest of the declutter pass.
    // NOTE: this retires the one gameplay hook it carried — a cone was anchored to a CRUSHABLE
    // structure, so flattening the anchor killed the cone mid-sweep. Nothing else read that link.

    // ---- road markings + decals + junctions (spec §4.2-§4.3) ----------------------------------
    // The carriageway tile is stamped at a NON-UNIFORM scale (x 0.48, y 0.34 minor / 0.62 major),
    // so anything baked into it is stretched by a different factor on each axis AND per road class.
    // Only shapes that survive that go in here, pre-compensated; everything with a shape becomes a
    // separate, uniformly-scaled decal below.
    // v6.9.1: baked at TRUE WORLD SIZE — RP.tilePitch px along the street by the street's own width
    // across it — and consumed by a TilingSprite laid along a whole street run (updateStreets). No
    // stretch, so no pre-compensation: what is drawn here is what lands on the ground. The tile
    // MUST be seamless left-to-right (every band runs the full pitch) and its top and bottom rows
    // are the kerb, which is where the repeat wraps — anything that bleeds across that edge shows
    // up as a doubled kerb.
    {
      const RP = ROAD_PAINT
      function carriageway(width, major) {
        const g = new Graphics()
        const L = RP.tilePitch, h = width / 2
        g.rect(-L / 2, -h, L, width).fill(major ? RP.asphaltMajor : RP.asphaltMinor)
        g.rect(-L / 2, -6, L, 12).fill({ color: RP.sheen, alpha: RP.sheenAlpha })   // wet crown sheen
        for (const s of [-1, 1]) {             // wheel-polish bands where tyres actually run
          g.rect(-L / 2, s * h * RP.polishAt - 3.5, L, 7).fill({ color: RP.polish, alpha: RP.polishAlpha })
        }
        for (const s of [-1, 1]) {             // kerb line, both long edges
          g.rect(-L / 2, s < 0 ? -h : h - RP.kerbW, L, RP.kerbW).fill(RP.kerb)
        }
        if (major) {
          for (const s of [-1, 1]) {           // double yellow
            g.rect(-L / 2, s * RP.doubleYellowGap / 2 - RP.doubleYellowW / 2, L, RP.doubleYellowW)
              .fill({ color: RP.doubleYellow, alpha: 0.9 })
          }
        } else {                               // minor streets: one dash per pitch, centred
          g.rect(-RP.dashLen / 2, -1.4, RP.dashLen, 2.8).fill({ color: RP.centreline, alpha: RP.centrelineAlpha })
        }
        // Left at the default clamp addressMode ON PURPOSE. Setting it to 'repeat' looks like the
        // obvious thing and is what breaks the tiling: these bakes are 96x60 / 96x108 / 96x128
        // render textures, i.e. non-power-of-two, so the GPU sampler clamps instead of wrapping and
        // the strip draws ONE tile and then extends its last column for the rest of the street. The
        // symptom is a road with a single dash at one end and none after it. Pixi's own tiling
        // shader wraps in the fragment stage and does not care about POT — so leave it alone.
        return { ...bake(g, 0), w: width }
      }
      T.roadMinor = carriageway(ROAD_MINOR_WIDTH, false)
      T.roadMajor = carriageway(ROAD_MAJOR_WIDTH, true)
      T.roadHighway = carriageway(HIGHWAY_WIDTH, true)
    }
    T.rdManhole = (() => {
      const g = new Graphics()
      const k = ROAD_DECAL.kinds.manhole
      g.circle(0, 0, k.r).fill(k.color).stroke({ width: 1.2, color: 0x22262c })
      for (let t = 0; t < k.rimTicks; t++) {
        const a = (t / k.rimTicks) * Math.PI * 2
        g.moveTo(Math.cos(a) * k.r * 0.55, Math.sin(a) * k.r * 0.55)
          .lineTo(Math.cos(a) * k.r * 0.9, Math.sin(a) * k.r * 0.9)
          .stroke({ width: 1, color: 0x22262c, alpha: 0.8 })
      }
      return bake(g, 1)
    })()
    T.rdPatch = (() => {
      const g = new Graphics()
      const k = ROAD_DECAL.kinds.patch
      const pts = []
      for (let s = 0; s < k.sides; s++) {
        const a = (s / k.sides) * Math.PI * 2
        const r = (k.px / 2) * (0.68 + hash(s * 7.3 + 1.9) * 0.55)
        pts.push(Math.cos(a) * r, Math.sin(a) * r)
      }
      g.poly(pts).fill(k.color).stroke({ width: 1.2, color: 0x22262c, alpha: 0.7 })
      return bake(g, 1)
    })()
    // v5.10.1: was two bare rects — no grate bars, no kerb lip. Now each slot gets a stroked kerb
    // lip and internal grate bars (a storm drain, not a hole).
    T.rdDrain = (() => {
      const g = new Graphics()
      const k = ROAD_DECAL.kinds.drain
      for (const s of [-1, 1]) {
        const y0 = s * k.pairGap / 2 - k.slotH / 2
        g.rect(-k.slotW / 2 - 1, y0 - 1, k.slotW + 2, k.slotH + 2).stroke({ width: 1, color: 0x4a4f57, alpha: 0.6 })
        g.rect(-k.slotW / 2, y0, k.slotW, k.slotH).fill(k.color)
        const bars = 4
        for (let b = 1; b < bars; b++) {
          const bx = -k.slotW / 2 + (b / bars) * k.slotW
          g.moveTo(bx, y0 + 0.4).lineTo(bx, y0 + k.slotH - 0.4).stroke({ width: 0.8, color: 0x14171b, alpha: 0.8 })
        }
      }
      return bake(g, 1)
    })()
    // v5.10.1: was one rectangle plus one triangle. Now a single tapered-shaft, winged-head polygon
    // with a thin outline — a real painted turn-arrow silhouette, not two primitives glued together.
    T.rdArrow = (() => {
      const g = new Graphics()
      const k = ROAD_DECAL.kinds.arrow
      const L = k.lenPx
      g.poly([
        -L / 2, -1.6,
        L * 0.05, -1.6,
        L * 0.05, -5,
        L / 2, 0,
        L * 0.05, 5,
        L * 0.05, 1.6,
        -L / 2, 1.6,
      ]).fill({ color: k.color, alpha: k.alpha }).stroke({ width: 1, color: 0x000000, alpha: 0.15 })
      return bake(g, 1)
    })()
    // JUNCTIONS — enumerated, not stamped, and baked AT TRUE WORLD SIZE so they are never scaled
    // at all (which is what lets a junction carry circles and a zebra pitch the stretched
    // carriageway tile cannot).
    T.junction = {}
    for (const variant of ROAD_JUNCTION.variants) {
      const J = ROAD_JUNCTION
      const vMajor = variant.startsWith('major')
      const hMajor = variant.endsWith('Major')
      const vh = (vMajor ? ROAD_MAJOR_WIDTH : ROAD_MINOR_WIDTH) / 2
      const hh = (hMajor ? ROAD_MAJOR_WIDTH : ROAD_MINOR_WIDTH) / 2
      const g = new Graphics()
      // v6.9.2: the crossing is sized OFF THE STREET, not fixed. The box and the bar spread already
      // scaled with ROAD_*_WIDTH, but the depth of the crossing and the bar thickness were hard 22
      // and 4 — fine on the old 30px lane, and a row of tick marks once a street became 130px wide.
      const narrow = Math.min(vh, hh) * 2
      const zebraDepth = Math.round(narrow * 0.28)
      const barW = Math.max(4, Math.round(narrow * 0.055))
      g.rect(-vh, -hh, vh * 2, hh * 2).fill(vMajor || hMajor ? ROAD_PAINT.asphaltMajor : ROAD_PAINT.asphaltMinor)
      // four approach zebra crosswalks: 7 bars, every 3rd worn
      for (const [ax, ay] of [[0, -1], [0, 1], [-1, 0], [1, 0]]) {
        const along = ax ? hh : vh          // half-width of the street being crossed
        const outAt = ax ? vh : hh
        for (let b = 0; b < J.zebraBars; b++) {
          const t = -along + 3 + (b * (along * 2 - 6)) / (J.zebraBars - 1)
          const worn = b % J.zebraWornEvery === 0
          const alpha = worn ? J.zebraWornAlpha : J.zebraAlpha
          if (ax) g.rect(ax * outAt + (ax > 0 ? 3 : -3 - zebraDepth), t - barW / 2, zebraDepth, barW).fill({ color: J.zebraColor, alpha })
          else g.rect(t - barW / 2, ay * outAt + (ay > 0 ? 3 : -3 - zebraDepth), barW, zebraDepth).fill({ color: J.zebraColor, alpha })
        }
        // stop bar behind each crossing
        if (ax) g.rect(ax * (outAt + zebraDepth + 5), -along, J.stopBarW, along * 2).fill({ color: J.zebraColor, alpha: 0.5 })
        else g.rect(-along, ay * (outAt + zebraDepth + 5), along * 2, J.stopBarW).fill({ color: J.zebraColor, alpha: 0.5 })
      }
      if (J.arrowsOnMajor && (vMajor || hMajor)) {   // painted turn arrow on each major approach
        const k = ROAD_DECAL.kinds.arrow
        if (hMajor) {
          g.rect(-vh - 46, -hh * 0.5 - 2, 18, 4).fill({ color: k.color, alpha: k.alpha })
          g.poly([-vh - 26, -hh * 0.5, -vh - 38, -hh * 0.5 - 6, -vh - 38, -hh * 0.5 + 6]).fill({ color: k.color, alpha: k.alpha })
        }
        if (vMajor) {
          g.rect(vh * 0.5 - 2, hh + 28, 4, 18).fill({ color: k.color, alpha: k.alpha })
          g.poly([vh * 0.5, hh + 26, vh * 0.5 - 6, hh + 38, vh * 0.5 + 6, hh + 38]).fill({ color: k.color, alpha: k.alpha })
        }
      }
      for (let m = 0; m < J.manholes; m++) {
        g.circle((m - 0.5) * vh * 0.9, (0.5 - m) * hh * 0.7, 7).fill(ROAD_DECAL.kinds.manhole.color)
          .stroke({ width: 1.2, color: 0x22262c })
      }
      if (variant === J.stalledCar) {
        // one abandoned sedan slewed across the box — everyone fled. The only survivor of the cut
        // "emergency vehicles" proposal (a driving vehicle needs a pathfinder over roadAt).
        const V2 = SKIES_VEHICLE.sedan
        const ca = 0.7, cs = Math.sin(ca), cc = Math.cos(ca)
        const quad = (lx, ly) => [lx * cc - ly * cs + 6, lx * cs + ly * cc - 4]
        const corners = [[-V2.len / 2, -V2.w / 2], [V2.len / 2, -V2.w / 2], [V2.len / 2, V2.w / 2], [-V2.len / 2, V2.w / 2]]
        g.poly(corners.map(([lx, ly]) => quad(lx, ly)).flat()).fill(0x6f7f8f).stroke({ width: 1.2, color: 0x2b3038 })
        g.poly([[-4, -V2.w / 2 + 1.5], [6, -V2.w / 2 + 2.5], [6, V2.w / 2 - 2.5], [-4, V2.w / 2 - 1.5]].map(([lx, ly]) => quad(lx, ly)).flat())
          .fill({ color: SKIES_VEHICLE.glass, alpha: SKIES_VEHICLE.glassAlpha })
      }
      T.junction[variant] = bake(g, 2)
    }
  }
  buildSkiesTextures()

  // Weapon-visual textures/lookups that composite fx sprites (glow-behind-star, mine
  // core, etc.) — needs T.fx, so it runs once the fx sheet is loaded (see `ready` below),
  // not from buildTextures(). Everything it sets is only ever read from sync(), which
  // main.js never calls before `await renderer.ready` resolves.
  function buildFxTextures() {
    // star bullet: soft flare glow baked behind a spinning gold star
    {
      const c = new Container()
      const glow = new Sprite(T.fx.flare_01)
      glow.anchor.set(0.5)
      glow.tint = 0xffb347
      glow.alpha = 0.8
      glow.scale.set(fxScale(T.fx.flare_01, 44))
      const star = new Sprite(T.fx.star_04)
      star.anchor.set(0.5)
      star.tint = 0xff9d1a
      star.scale.set(fxScale(T.fx.star_04, 30))
      // double-stack: Kenney glyphs are soft-alpha, one layer washes out on the light floor
      const star2 = new Sprite(T.fx.star_04)
      star2.anchor.set(0.5)
      star2.tint = 0xff9d1a
      star2.scale.set(star.scale.x)
      c.addChild(glow, star, star2)
      T.bullet = bakeComposite(c)
    }
    // orbit spark: mint/teal diamond sparkle, tinted live (see placeOrb)
    {
      const tex = T.fx.magic_05
      T.orb = { tex, ax: 0.5, ay: 0.5 }
      T.orbScale = fxScale(tex, 30)
    }
    // wave nova ring: expanding glow ring, tinted sky blue live (see placeNova)
    {
      const tex = T.fx.light_02
      T.nova = { tex, ax: 0.5, ay: 0.5 }
      T.novaTexR = fxRadius(tex)
    }
    // Boomerang Leaf (run.boomerangs): a DRAWN leaf. v6.6.13, playtest — "leaf blade doesn't look like
    // a leaf". It didn't: the weapon has been the Boomerang Leaf since v5.3, but the art stayed the
    // Kenney slash glyph tinted orange, i.e. a crescent BLADE. Shape is what says leaf, so it's
    // drawn: a pointed lens widest ~40% from the base, a midrib, three vein pairs and a stem.
    // It stays WARM AMBER rather than going green — the garden floor is bright lawn (bg 0x4e8240
    // under a 0xaad066 tint) and a green leaf on it is a green leaf on green grass. A dry leaf
    // reads as a leaf and keeps the contrast the orange crescent had.
    {
      const LEAF_FILL = 0xf2a04a       // dry warm amber
      const LEAF_RIM = 0x6d3411        // dark rim: what actually separates it from the lawn
      const LEAF_VEIN = 0xffd9a5       // pale midrib/veins — the detail that names the shape
      const L = 34, HW = 9.5           // length, half-width at the belly
      const N = 36
      const halfW = (t) => {
        const u = Math.min(1, Math.max(0, Math.pow(t, 0.78))) // belly ~40% from the base, sharp tip
        // The ripple is the art rule, not decoration: a clean lens reads as a procedural blob.
        return HW * Math.pow(Math.max(0, Math.sin(Math.PI * u)), 0.85) * (1 + 0.09 * Math.sin(t * 27))
      }
      const g = new Graphics()
      const top = [], bot = []
      for (let i = 0; i <= N; i++) {
        const t = i / N
        const x = -L / 2 + L * t
        const w = halfW(t)
        top.push(x, -w)
        bot.push(x, w)
      }
      const back = []
      for (let i = bot.length - 2; i >= 0; i -= 2) back.push(bot[i], bot[i + 1])
      g.poly([...top, ...back]).fill(LEAF_FILL).stroke({ width: 1.4, color: LEAF_RIM, join: 'round' })
      g.moveTo(-L / 2, 0).lineTo(L / 2 - 1, 0).stroke({ width: 1.5, color: LEAF_VEIN })
      for (const t of [0.32, 0.5, 0.68]) {
        const x = -L / 2 + L * t
        const w = halfW(t) * 0.7
        g.moveTo(x, 0).lineTo(x + L * 0.13, -w).stroke({ width: 1, color: LEAF_VEIN })
        g.moveTo(x, 0).lineTo(x + L * 0.13, w).stroke({ width: 1, color: LEAF_VEIN })
      }
      g.moveTo(-L / 2, 0).lineTo(-L / 2 - 3.5, 0).stroke({ width: 1.8, color: LEAF_RIM })
      T.boomerang = bake(g)            // anchor = the local origin = mid-rib, so it spins about itself
      T.boomerangScale = 1             // baked at its on-screen size already
    }
    // slime mine: coral glow behind a red-pink diamond core
    {
      const c = new Container()
      const glow = new Sprite(T.fx.circle_05)
      glow.anchor.set(0.5)
      glow.tint = 0xff9166
      glow.alpha = 0.55
      glow.scale.set(fxScale(T.fx.circle_05, 46))
      const core = new Sprite(T.fx.magic_04)
      core.anchor.set(0.5)
      core.tint = 0xff4f7a
      core.scale.set(fxScale(T.fx.magic_04, 26))
      c.addChild(glow, core)
      T.mine = bakeComposite(c)
    }
    // homing wisp: lavender sparkle baked double-stacked (soft alpha washes out solo)
    {
      const c = new Container()
      for (let i = 0; i < 2; i++) {
        const s = new Sprite(T.fx.magic_04)
        s.anchor.set(0.5)
        s.tint = 0x9b4fd0
        s.scale.set(fxScale(T.fx.magic_04, 30))
        c.addChild(s)
      }
      T.homing = bakeComposite(c)
      T.homingScale = 1
    }
    // stinger needle (v5.3 garden): a thin amber streak, double-stacked (soft alpha washes out solo),
    // pointing +x natively so placeBullet can rotate it to the needle's velocity. A bright tip spark
    // sells the "point". Visually distinct from the round spinning star bullet.
    {
      const c = new Container()
      for (let i = 0; i < 2; i++) {
        const s = new Sprite(T.fx.trace_05)
        s.anchor.set(0.5)
        s.tint = 0xffb347
        s.scale.set(fxScale(T.fx.trace_05, 26), fxScale(T.fx.trace_05, 6))
        c.addChild(s)
      }
      const tip = new Sprite(T.fx.spark_04)
      tip.anchor.set(0.5)
      tip.tint = 0xffe4a0
      tip.position.x = 11
      tip.scale.set(fxScale(T.fx.spark_04, 10))
      c.addChild(tip)
      T.needle = bakeComposite(c)
    }
    // The Surf's Skipping Shell (run.bullets, weapon:'shell'). A scallop in PLAN VIEW — hinge at the
    // back, fan opening forward along +x so placeBullet can rotate it to the shell's velocity and
    // the direction it is skimming is readable. Baked dark-on-pale deliberately: the beach floor is
    // the lightest surface in the game, so a pale shell has nowhere to go and the first cut of this
    // (a cream-tinted needle) could not be found in its own screenshot.
    {
      const g = new Graphics()
      const L = 15                       // half-length, hinge to lip
      const W = 11                       // half-width across the fan
      // The body: a fan that widens from the hinge to the lip.
      g.moveTo(-L, 0)
      g.bezierCurveTo(-L * 0.2, -W * 1.05, L * 0.55, -W, L * 0.92, -W * 0.34)
      g.bezierCurveTo(L * 1.06, 0, L * 1.06, 0, L * 0.92, W * 0.34)
      g.bezierCurveTo(L * 0.55, W, -L * 0.2, W * 1.05, -L, 0)
      g.fill({ color: 0x8a5a48 })
      g.stroke({ width: 1.6, color: 0x4a2c22, alpha: 0.9 })
      // Radial ribs, the one detail that says SHELL rather than leaf or blade at this size.
      for (let i = -2; i <= 2; i++) {
        const a = (i / 2) * 0.62
        g.moveTo(-L * 0.82, 0)
        g.lineTo(-L * 0.82 + Math.cos(a) * L * 1.7, Math.sin(a) * L * 1.7 * 0.62)
        g.stroke({ width: 1.1, color: 0x5e3a2c, alpha: 0.55 })
      }
      // A pale lip along the leading edge: wet shell catches the light, and it is what keeps the
      // silhouette from closing up into a dark blob when it is moving fast.
      g.moveTo(L * 0.86, -W * 0.42)
      g.bezierCurveTo(L * 1.04, 0, L * 1.04, 0, L * 0.86, W * 0.42)
      g.stroke({ width: 2.2, color: 0xf0dcc0, alpha: 0.85 })
      T.shell = bake(g)
    }
    // enemy missile (skies helicopters, run.enemyShots): the only enemy-owned projectile, so it must
    // never be confused with the player's amber stinger needle — cold steel body, hot red exhaust
    // flare behind it, pointing +x natively so placeShot can aim it along its velocity.
    {
      const c = new Container()
      const flare = new Sprite(T.fx.flare_01)
      flare.anchor.set(0.5)
      flare.tint = 0xff5545
      flare.alpha = 0.85
      flare.position.x = -9
      flare.scale.set(fxScale(T.fx.flare_01, 16))
      c.addChild(flare)
      for (let i = 0; i < 2; i++) { // double-stacked: one soft-alpha layer washes out
        const b = new Sprite(T.fx.trace_05)
        b.anchor.set(0.5)
        b.tint = 0xd8dde4
        b.scale.set(fxScale(T.fx.trace_05, 24), fxScale(T.fx.trace_05, 7))
        c.addChild(b)
      }
      const tip = new Sprite(T.fx.spark_04)
      tip.anchor.set(0.5)
      tip.tint = 0xff8c42
      tip.position.x = 10
      tip.scale.set(fxScale(T.fx.spark_04, 9))
      c.addChild(tip)
      T.missile = bakeComposite(c)
    }
    // pond player's flagellum tail: a soft streak glyph, double-stacked (one layer washes out)
    for (const t of [tailA, tailB]) t.texture = T.fx.trace_05
  }

  // Prop + fx sprite sheets (bush/grass/.../leaf, star/flare/twirl/...) load async;
  // `ready` resolves once T.props/T.fx are populated and the fx-dependent weapon
  // textures above are baked. reset/sync/idle all guard on propsReady so it's safe to
  // call them before this settles — they just skip floor drawing until then; main.js
  // additionally awaits `ready` itself before the game loop ever calls sync()/idle().
  let propsReady = false
  const ALL_URLS = { ...PROP_URLS, ...FX_URLS }
  const ready = Assets.load(Object.values(ALL_URLS)).then((loaded) => {
    T.props = {}
    for (const name in PROP_URLS) T.props[name] = loaded[PROP_URLS[name]]
    T.fx = {}
    for (const name in FX_URLS) T.fx[name] = loaded[FX_URLS[name]]
    // v5.10 (kill list §8.6): T.foam used to live here — `T.fx.trace_05`, i.e. the sea district's
    // breaking-wave prop WAS the pond's current-streak sprite, reused a third time by populateEdge
    // for coastlines. It is gone; skies draws T.waveCrest, a real crest (two parallel arcs and a
    // foam speckle band), baked in buildSkiesTextures.
    buildFxTextures()
    propsReady = true
  })

  function spriteOf(look) {
    const s = new Sprite(look.tex)
    s.anchor.set(look.ax, look.ay)
    return s
  }

  // ------------------------------------------------------------- stage layout
  // Organic floor (ground blotches + scattered foliage) lives in floorLayer, the
  // first child of world, so it inherits camera + shake for free — see the "organic
  // floor" section below for how its cells get populated. It stays visible in both
  // gameplay and idle (title screen); only entitiesLayer (player/enemies/bullets/...)
  // toggles with run state, so `world` itself is never hidden.
  const world = new Container()
  const floorLayer = new Container()
  const blotchLayer = new Container()
  const roadLayer = new Container()   // skies only (v5.9) — sits over the district floor tint, under every prop
  const roadDecalLayer = new Container() // skies only (v5.10) — manholes/patches/drains/arrows, uniformly scaled
  const junctionLayer = new Container()  // skies only (v5.10) — enumerated crosswalk composites, true world size
  const ruinLayer = new Container()      // skies + city (v5.10, v6.3) — permanent crush ruins, from the render-local ledger, gated by chapterHasRuins
  const bigLayer = new Container()
  const midLayer = new Container()
  const detailLayer = new Container()
  const clutterLayer = new Container() // skies-urban only (v5.9) — extra furniture, see populateClutter
  const edgeLayer = new Container() // skies districts only (v5.9.1) — border markers, see populateEdge
  // v5.12: groundLayer sits UNDER everything and carries the terrain's COLOUR as a continuous field
  // (see updateGroundField). blotchLayer above it now carries only texture. Separating the two is the
  // fix for the checkerboard — see updateGroundField's header for the full account.
  const groundLayer = new Container()
  floorLayer.addChild(groundLayer, blotchLayer, roadLayer, roadDecalLayer, junctionLayer, ruinLayer,
    bigLayer, midLayer, detailLayer, clutterLayer, edgeLayer)

  const entitiesLayer = new Container()
  const idleLayer = new Container()
  const dustLayer = new Container()
  const vignette = new Sprite(T.vignette)
  vignette.alpha = 0
  // Full-field lightning flash (skies chapter, v5.7.2, LIGHTNING.flash): a flat white screen-space
  // rect, NOT the vignette's edge-only radial gradient — a strike/ambient bolt should whiten the
  // WHOLE view, briefly. Texture.WHITE is Pixi's built-in 1x1 white pixel, no bake needed. Sits
  // directly below vignette in the stage stack (see addChild below) so a same-frame damage flash
  // — the safety cue — still visibly wins.
  const lightningFlash = new Sprite(Texture.WHITE)
  lightningFlash.alpha = 0
  // ---- THE WATER (v7.x Book 2 / The Surf) ------------------------------------------------------
  // A flat screen-space wash of colour over the world, from CHAPTERS[id].render.water. Same
  // Texture.WHITE + fitScreen idiom as lightningFlash directly above; a chapter that declares no
  // `water` never shows it, so this is inert everywhere but the beach.
  //
  // WHY A WASH AND NOT A DARKER PALETTE. The Surf is ankle-deep, not the open ocean — the chapter
  // below it (The Reef) gets its depth from bgColor alone, because down there the water IS the
  // scene. Here the sand has to stay sand and stay warm, and only look like it is being seen THROUGH
  // something. Retinting the floor cannot do that: it would recolour the ground and leave the fish,
  // the crowd and the props sitting on top of it in dry air. A layer between the camera and the
  // whole world is what "a bit underwater" actually is, and it costs one sprite.
  //
  // ABOVE `world` AND BELOW EVERYTHING ELSE ON THE STAGE (see the addChild below), which is the same
  // rule darkLayer states for itself: floating damage numbers (idleLayer), the blown sand, and the
  // red damage vignette are safety and readability cues that live between the player and the screen,
  // not between the player and the sea floor. Tinting them would be dimming the instruments.
  const waterWash = new Sprite(Texture.WHITE)
  waterWash.alpha = 0
  // ---- ABOVE THE WATERLINE ---------------------------------------------------------------------
  // The one place things are drawn that the water is NOT in front of (owner, 2026-08-15: "seagulls
  // shouldn't have the blue tint, they are above water"). Sits on the STAGE, immediately over
  // waterWash, so anything parented here is painted after the wash and keeps its own colour.
  //
  // Its transform is copied from `world` every frame (syncAboveWater, called from stepGullDives), so
  // its children are positioned in WORLD coordinates exactly like any other entity — including under
  // map mode's zoom. Without that copy a bird would be pinned to the screen and slide over the beach
  // as the camera moved, which reads as a UI element rather than as an animal.
  //
  // A gull is the whole reason it exists, and the split inside one strike is the point: the BIRD
  // goes here, its SHADOW stays down in particleLayer with the rest of the world. The shadow is cast
  // on the sea floor and is therefore seen through the water; the bird is in the air and is not. The
  // gap between the two already carried the altitude (see stepGullDives) — now the colour does too.
  const aboveWater = new Container()
  // v5.0 pond biome layers (empty/hidden for body): ambient current motes live on the stage
  // (screen space, like dust); obstacles + hazard pools read as ground decals under the roster;
  // toxin blooms hang over enemies but under the player; whip flashes sit over the weapons.
  // Declared BEFORE the stage addChild below — currentLayer is referenced there (TDZ otherwise).
  const currentLayer = new Container()
  const poolLayer = new Container()
  const obstacleLayer = new Container()
  const bloomLayer = new Container()
  const whipLayer = new Container()
  // Storm overlay (skies signature look, v5.6.18 — see updateStorm below). cloudShadowLayer is a
  // `world` child (floor < shadows < entities, so shadows dim the ground but sit under the roster);
  // stormCloudLayer/stormRainLayer are stage-level, drawn OVER the whole world (clouds parallax the
  // camera, rain is plain screen space) — same "declared before the addChild that uses it" rule.
  const cloudShadowLayer = new Container()
  const stormCloudLayer = new Container()
  const stormRainLayer = new Container()
  // v6.5 undergrowth: falling leaves (chapterHasLeaves) — stage-level screen-space overlay,
  // dustLayer's exact idiom (own container directly on stage, unaffected by camera/world
  // position). Declared here for the same reason as the layers above it: addChild'd before its
  // own const is a TDZ crash that only shows in the minified bundle.
  const leafLayer = new Container()

  // ---- THE DARK (v7.x Book 2) ------------------------------------------------------------------
  // A screen-space scrim over the whole world, its alpha driven by the chapter's resource bar.
  // Owner: "if we're stealing light, then our surroundings should be dark, and darker the less
  // light we have" — then, on seeing it: "you are the source light, you EMIT the light, but the
  // less light you have, the less far you emit." So the darkness is not a sheet whose alpha ramps,
  // it is a HOLE whose radius shrinks, and the player is standing in the hole.
  //
  // ONE SPRITE over a per-frame LIGHTMAP, and the singular is the whole point. The darkness this
  // chapter wants is one field:
  //
  //     D(p) = dim * falloff(|p - player| / R)   , and 0 inside any sun shaft
  //
  // and a field is not something you can assemble by stacking translucent objects. Two objects
  // composite as 1-(1-a1)(1-a2), so wherever their coverages disagree you get a seam, and the seam
  // sits on the boundary of whichever object is disagreeing — its circle, or, far worse, its SQUARE.
  // v7.55 shipped this as a scrim plus a falloff sprite and had a straight-edged artefact from each:
  //   - the scrim's holes were Graphics.cut(). cut()'s own doc says a hole must lie wholly inside
  //     the shape, but the rule it does not state is the one that bit: earcut wants holes that do
  //     not overlap EACH OTHER, and the player's circle overlapping a shaft's is not an edge case
  //     here, it is the chapter. Three mutually-overlapping discs triangulated into a hard wedge of
  //     night across the whole viewport, which is how it was reported from play.
  //   - the falloff SPRITE was square and unclipped, and a radial gradient clamps past its outer
  //     radius, so its corners sat at alpha 1 over scrim that was already solid. The dark went down
  //     twice (0.86 -> 0.98) and the sprite's bounding box showed as hard seams at px/py +/- R.
  // Clipping that sprite instead of rebuilding is the tempting repair and it does not work: the box
  // edge just moves INSIDE the shaft pools, as a straight line across the one place the chapter is
  // supposed to play normally. Any fix that moves an edge rather than removing it is the tell that
  // the construct, not the tuning, is wrong.
  //
  // So the field is COMPUTED into a small offscreen canvas rather than composited from objects.
  // One coverage, so no seam can exist.
  //
  // IT CARRIES DARKNESS AS OPAQUE COLOUR AND IS COMPOSITED WITH MULTIPLY: white where lit (multiply
  // leaves the scene alone), the chapter's dark tint where not, a colour ramp between. The version
  // before this one built the same field in the canvas's ALPHA channel — fill white, punch the
  // lights out with `destination-out`, draw the result as a translucent tinted sprite — and it did
  // not survive on the owner's phone. At 88/100 Light, with a radius covering the screen twice over,
  // the whole screen was black except the sun shafts.
  //
  // THE SHAFTS ARE THE TELL, and they are why this is a rewrite and not a tune. They are arc()+fill()
  // and they rendered; the player's light was a drawImage() of a pre-baked offscreen canvas whose
  // ALPHA was the entire effect, and it contributed nothing at all. Four releases were spent moving
  // where this layer switches on (41% -> 50% -> 90% of the bar), which only moved where the blackout
  // began — the reports read as tuning complaints and never were. Both halves of that path are now
  // gone: nothing is baked offscreen, and no alpha channel carries anything. Every operation here is
  // a fill with an opaque colour.
  //
  // Overlaps still compose for free: painting white over white is idempotent, which is the property
  // destination-out was chosen for in the first place.
  //
  // The buffer is DELIBERATELY tiny (DARK_MAP_W px wide, ~3-4x smaller than the screen) and stretched
  // up. The field it holds is a gradient plus a few discs, so the upscale costs nothing visible, and
  // it keeps the per-frame texture upload at a few tens of KB. It also softens the shaft rim by a
  // couple of px, which the shaft's own painted ring (updateShafts, drawn UNDER this) reads through.
  //
  // A STAGE child sitting directly above `world`, and both halves of that matter:
  //   - above `world`, so it dims the floor, the props, the roster and the player as one flat
  //     sheet. A `world` child would slide and scale with the camera and stop being a scrim.
  //   - BELOW idleLayer/dustLayer/lightningFlash/vignette, so floating damage numbers and the red
  //     damage vignette stay at full strength. Dimming the safety cues along with the world is how
  //     a dark chapter turns into an unfair one, and the whole point is that the dark costs you
  //     information about the CROWD, not about your own health.
  //
  // The shafts REMOVE darkness, they are not brighter sprites painted over the top. That is a
  // gameplay requirement and not a look: additive light over a flattened scene raises its
  // brightness but cannot un-flatten it, so a shaft drawn that way is a glowing disc you can see
  // LESS inside — the exact opposite of what standing in the light is for. Punching the alpha out
  // shows the untouched world, so the lit pool is the one place the chapter plays normally.
  const DARK_MAP_W = 128
  const darkLayer = new Container()
  const darkCanvas = document.createElement('canvas')
  // alpha:false — there is no transparency to preserve here, and saying so keeps any premultiply
  // handling out of the upload path entirely.
  const darkCtx = darkCanvas.getContext('2d', { alpha: false })
  darkCanvas.width = DARK_MAP_W
  darkCanvas.height = DARK_MAP_W
  const darkTex = Texture.from(darkCanvas)
  const darkSprite = new Sprite(darkTex)
  darkSprite.blendMode = 'multiply'
  darkLayer.addChild(darkSprite)
  darkLayer.visible = false

  // ---- SWELL (v7.x Book 2) ---------------------------------------------------------------------
  // The waves. Pooled world-space crest streaks built on the CURRENT_VIS idiom — same respawn-in-
  // view, same fade envelope — with one deliberate difference: a FIXED heading instead of an
  // advected force field. A current has a field and a swell has a direction, and reusing
  // updateCurrents would have meant inventing a fake force field to make a straight line.
  //
  // A `world` CHILD, unlike the dark scrim above it, because a wave is a thing at a place: it has
  // to slide past the camera. It sits under `entitiesLayer`, so a crest never draws over an enemy —
  // surface glints ON TOP of the roster would read better as "we are below the surface looking up"
  // and would cost legibility in a chapter whose whole mechanic is already taking legibility away.
  const swellLayer = new Container()

  // ---- CAUSTICS (v7.x Book 2) -------------------------------------------------------------------
  // Two tiled, additive copies of the baked caustic pattern drifting across each other. See
  // CAUSTIC_VIS for why two and why they must drift in different directions.
  //
  // A `world` CHILD and UNDER entitiesLayer, both deliberately. In the world because caustics are on
  // the FLOOR and have to scroll with it — a screen-locked shimmer reads as a filter over the game
  // rather than as light in it. Under the entities because this is the seabed being lit: the crowd
  // stays at full contrast, and the two things that are NOT seabed get the right answer for free —
  // the sandbar and the tide pools both live in entitiesLayer, so no caustic falls on the dry bar
  // (correct: it is out of the water) and none scribbles over a pool's depth steps.
  const causticLayer = new Container()
  const causticTiles = CAUSTIC_VIS.layers.map((L) => {
    const t = new TilingSprite({ texture: T.caustic, width: 1, height: 1 })
    t.blendMode = 'add'
    t.tint = CAUSTIC_VIS.tint
    t.alpha = L.alpha
    t.tileScale.set(L.scale)
    causticLayer.addChild(t)
    return { t, L }
  })
  causticLayer.visible = false
  let causticT = 0
  // cx/cy are the camera offset (world.position), so -cx is the world x at the left edge of the
  // screen. The sprite is parked over the viewport with a margin and resized to it, which keeps the
  // fill rate at one screen no matter how far the player has walked from the origin.
  //
  // tilePosition then CANCELS the sprite's own position. Without that the pattern is anchored to the
  // sprite's top-left, so it would ride the camera and sit perfectly still relative to the screen
  // while the sand scrolled underneath it — the one failure that would make this read as a lens
  // effect instead of as light on the ground, and it looks completely fine in a still frame.
  function updateCaustics(cx, cy, dt) {
    if (!causticLayer.visible) return
    causticT += dt
    const M = 64
    const w = viewW() + M * 2, h = viewH() + M * 2
    for (const { t, L } of causticTiles) {
      t.position.set(-cx - M, -cy - M)
      t.width = w
      t.height = h
      t.tilePosition.set(-t.x + causticT * L.vx, -t.y + causticT * L.vy)
    }
  }

  // ---- the light layer (v5.10, spec §7) — the chapter's identity -------------------------------
  // "TOKUSATSU NIGHT — the lights are looking for you." Sits between the cloud shadows and the
  // entities so light cuts THROUGH cloud shadow. blendMode appears nowhere else in this file:
  // additive is a new concept here and it is a CORRECTNESS requirement, not a perf note. Each
  // sub-container draws from exactly ONE texture, or Pixi v8's batcher breaks on every
  // blend-mode/texture transition — three sub-containers, three draw calls.
  world.addChild(floorLayer, swellLayer, causticLayer, cloudShadowLayer, entitiesLayer)
  app.stage.addChild(world, waterWash, aboveWater, darkLayer, currentLayer, stormCloudLayer, stormRainLayer, idleLayer, dustLayer, leafLayer, lightningFlash, vignette)
  entitiesLayer.visible = false // title screen shows first; reset(run) reveals entities

  // v5.3 garden field layers (empty/hidden for other chapters, driven purely by run.trails/webs/
  // lures presence — no hard chapter gate needed since createRun leaves them [] elsewhere):
  //   trailLayer/webLayer sit with the ground decals (under enemies); lureLayer floats the decoy
  //   beacon over the swarm; stripG is a telegraph Graphics like bombG (see redrawStrips).
  const trailLayer = new Container()
  const webLayer = new Container()
  // v7.x Book 2 surf: the dry patches (run.sandbars). Same no-gate rule as its neighbours — the
  // array is empty in every chapter but The Surf. Deliberately the DEEPEST of the ground-patch
  // layers after the mown stripes: a sandbar is the ground itself, so a web, a pheromone trail or a
  // tide pool drawn over one has to sit on top of it, never under.
  const sandLayer = new Container()
  const lureLayer = new Container()
  const stripG = new Graphics()
  // v5.4 chapter-4-7 field layers. Like the garden/pond layers above these need no chapter gate —
  // they're driven purely by the presence of their run.* array, which createRun leaves empty
  // elsewhere. Declared HERE, above the entitiesLayer.addChild below: the v5.0 pond crash was a
  // layer being addChild'd before its own const, which only blew up in the minified bundle.
  //   wellG/trapLayer  = permanent ground furniture, under the roster
  //   laneG/hazardG    = telegraph Graphics, same idiom as bombG/stripG
  //   teleG            = the roster's own attack telegraphs (see redrawTelegraphs), likewise
  //   debrisLayer      = the tornado's orbiting junk (player weapon, sits with the orbs)
  //   shotLayer/carLayer/lobLayer = airborne things, over the crowd
  const wellG = new Graphics()
  // v5.24 the blank: binding-node filaments (syncBinds) — wellG's exact idiom, one Graphics
  // cleared+redrawn per frame, driven purely by 'bindnode' entries in run.enemies (none elsewhere)
  const bindG = new Graphics()
  const trapLayer = new Container()
  // v6.6.22: the stripes the mower leaves on the lawn. Render-only — cut grass has no sim effect,
  // so this never touches `run` and lives entirely in renderer state. Deepest child of
  // entitiesLayer below: a cut is ON the ground, under the trails, webs and everything else.
  const mownG = new Graphics()
  const mown = []                  // {x,y,angle,w,len} in world space, oldest first
  const mownByLane = new WeakMap() // lane object -> its growing stripe, so a pass extends one entry
  const MOWN_MAX = 24              // ~4 minutes of passes; the oldest cut fades from memory first
  let mownDirty = false            // only rebuild the geometry while a mower is actually driving
  const laneG = new Graphics()
  const hazardG = new Graphics()
  // v6.10 open jets. A RIG pool (Container per jet, counter-rotating foam sprites inside), not a
  // flat sprite pool — so reset() must hide .root, see the note there. Sits directly above hazardG
  // because the telegraph and the jet it becomes have to stack in that order.
  const jetLayer = new Container()
  const teleG = new Graphics()
  // v6.7.6 Beam Prism (run.prisms): the refracted sub-beams. ADDITIVE and its own Graphics, because
  // this is light — the same reason strafePoolLayer below is its own container. A sub-beam is
  // already resolved damage by the time it is drawn (see the run.prisms note in state.js), so this
  // draws a decaying segment and nothing else; the pooled beamPool sprites stay for the real arms.
  // Two of them: prismBodyG paints NORMALLY so the fan holds its own red on any ground (additive
  // red over a light floor barely moves the pixel), prismG stays additive for the white-hot core on
  // top, where adding light is the correct model. See entitiesLayer.addChild for where they sit.
  const prismBodyG = new Graphics()
  const prismG = new Graphics()
  prismG.blendMode = 'add'
  // v5.10 skies: the jet strafe's halogen landing-light pool is the one telegraph element that must
  // be ADDITIVE (a light on wet asphalt, not a painted band) — its own single-texture container, so
  // the blend-mode switch costs exactly one batch break. rampG carries the rampage rim-lights and
  // heartbeat ring; smokeLayer is the second particle pool (spec §1.2).
  const strafePoolLayer = new Container()
  strafePoolLayer.blendMode = 'add'
  const shellLayer = new Container()   // baked artillery glyphs (box / hatched hand / shell shadow)
  const skyLayer = new Container()     // baked sky-strike glyphs (chevron ring / ionisation wash)
  const voltLayer = new Container()    // baked volatile-elite-bomb glyph (P0 fix, its own drawer)
  const scarLayer = new Container()    // Lichtenberg ground scars, fading
  const lockLayer = new Container()    // the missile lock diamond — the only mark anchored to YOU
  const rampG = new Graphics()
  const smokeLayer = new Container()
  const debrisLayer = new Container()
  const shotLayer = new Container()
  const carLayer = new Container()
  const lobLayer = new Container()
  const gemLayer = new Container()
  const coinLayer = new Container()
  const holeLayer = new Container()
  // v6.4 pond signature: eddy vortex decals (updateEddies below). Deliberately a CHILD of
  // entitiesLayer, not stage-level like currentLayer (which intentionally floats OVER the whole
  // world, screen-space, per its own comment) — the eddy ring marks a real force boundary, so it
  // must read as floor-level, UNDER the crowd, the same "under entities" contract obstacleLayer/
  // poolLayer/holeLayer already keep. Positioned right after holeLayer: same pooled-vortex idiom.
  const eddyLayer = new Container()
  // v7.x Book 2: sun-shaft decals. A CHILD of entitiesLayer for the same reason eddyLayer is — the
  // shaft marks a real refill boundary, so it has to read as floor-level, UNDER the crowd. Pooled
  // DECALS, not a rig: one sprite plus one ring per shaft, so this pool belongs in reset()'s flat
  // list and must NOT get a `.root.visible` line (converting the two the wrong way round is the
  // silent failure documented in CLAUDE.md).
  const shaftLayer = new Container()
  const novaLayer = new Container()
  const mineLayer = new Container()
  // elite affix ground fx (bomb telegraphs + pacer auras): per-frame vector layers,
  // cleared/redrawn each sync() like arcG below — must sit under enemyLayer/playerC
  // so danger circles read as floor decals, not overlays on top of the entities
  const bombG = new Graphics()
  const pacerG = new Graphics()
  // v5.6.5: the crowd's shadows and the elites' crowns were lifted OUT of the creature textures so
  // they stop inheriting the body's rotation — see groundShadow/eliteCrown up in the art section.
  // Shadows go UNDER every enemy (they're ground decals, cast by an overhead light); crowns go OVER
  // them. Both are declared HERE, above the entitiesLayer.addChild below, for the usual reason: a
  // layer addChild'd before its own const is a TDZ crash that only ever shows in the minified bundle.
  const enemyShadowLayer = new Container()
  const enemyLayer = new Container()
  const enemyCrownLayer = new Container()
  // shield bubble overlay: drawn on top of the elite body it protects
  const shieldG = new Graphics()
  const affixLayer = new Container() // per-elite affix icon badges (Text), see syncAffixBadges
  const playerC = new Container()
  // The Surf's Breaker: its wave crests (run.novas entries carrying `arc`). Directly above playerC
  // because the wave rolls out from the player over the crowd it is shoving, and under the
  // projectiles. One Graphics rather than a sprite pool — see drawBreakers for why an arc cannot be
  // a scaled texture.
  const breakerG = new Graphics()
  // Splash rings (see spawnSplash). Beside breakerG because both are the water's SURFACE rather than
  // anything on the floor, and both therefore belong over the crowd: a ripple you can see a body
  // through is a ripple under it, which is the one thing it is not.
  const splashG = new Graphics()
  // Barnacle crusts, drawn OVER the bodies they are growing on — they sit on top of the enemy
  // sprite, so this has to be added after the entity layer, not with the ground effects.
  const crustG = new Graphics()
  const bulletLayer = new Container()
  const rockLayer = new Container()   // v5.21 lane: drifting asteroids (run.rocks)
  const boomerangLayer = new Container()
  const orbLayer = new Container()
  const homingLayer = new Container()
  const beamLayer = new Container()
  const arcG = new Graphics() // elemental shock arcs (shockarc/frostarc/conduct)
  // v7.23 skies: the Atomic Breath's live forks (run.arcs) and the Tail Lash's drag tethers
  // (run.drags). Its own Graphics rather than arcG because those are one-shot fading procs on a
  // render-local pool, while these are PERSISTING sim entities redrawn from run state every frame.
  // The jagged-polyline drawing itself is shared (jitterPath/strokePath) — a fork and a shock arc
  // are the same picture, so there is no second stroker.
  // Palette law 2 (SKIES_PALETTE): both are the PLAYER's output, so both are atomic cyan-green.
  const breathG = new Graphics()
  // v7.x The Trawl. TWO Graphics in two different places in this list, and the split is the point:
  // the WAKE is churned water, so it belongs down with the floor washes where the crowd swims over
  // it, and the MESH is a physical wall, so it belongs above the crowd — a net drawn under the fish
  // reads as something lying on the bottom, which is the opposite of the thing you must not cross.
  // Neither is a pool: clearing them IS the reset, the same idiom breathG uses (see clearWorld).
  const netWakeG = new Graphics()
  const netG = new Graphics()
  // The player's own gear, and it sits beside netG ABOVE the crowd for exactly the reason netG
  // does: a net drawn under the bodies it has caught reads as something lying on the bottom, which
  // is the opposite of "you are held by this". Same idiom again — not pools; clearing them IS the
  // between-run reset (see clearWorld).
  const longlineG = new Graphics()
  const snareG = new Graphics()
  // v7.x The Deep. Above the bodies it annotates, like crustG: a gape drawn UNDER the fish would
  // be a mouth behind its own head, and a Scent outline under the crowd would be hidden by exactly
  // the bodies it is marking.
  const deepG = new Graphics()
  const particleLayer = new Container()
  const textLayer = new Container()
  entitiesLayer.addChild(
    mownG, sandLayer, netWakeG, wellG, bindG, poolLayer, trailLayer, webLayer, obstacleLayer, trapLayer,
    gemLayer, coinLayer, holeLayer, eddyLayer, shaftLayer, novaLayer, mineLayer,
    scarLayer, bombG, shellLayer, skyLayer, voltLayer, stripG, laneG, hazardG, jetLayer, teleG, strafePoolLayer, rampG, pacerG,
    rockLayer,
    enemyShadowLayer, enemyLayer, enemyCrownLayer, netG, longlineG, snareG,
    bloomLayer, lureLayer, shieldG, affixLayer, crustG, deepG, lockLayer, playerC, breakerG, splashG,
    bulletLayer, boomerangLayer, orbLayer, debrisLayer, homingLayer, shotLayer, beamLayer, whipLayer, arcG, breathG,
    lobLayer, carLayer, smokeLayer, particleLayer,
    // v6.7.7: the refraction sits in FRONT of traffic, smoke and particles — everything except the
    // damage numbers. A taxi crossing a split used to paint over it, which on the one layer whose
    // whole job is to be noticed is the wrong trade. Still under textLayer: numbers stay readable.
    prismBodyG, prismG,
    textLayer,
  )

  // ---------------------------------------------------------- organic floor
  // Ground blotches + scattered foliage: one sprite per occupied world-space cell,
  // picked/tinted/rotated/scaled by cellHash(i, j, salt) so a cell's look never
  // changes as it re-enters view. Sprites pool/release like the enemy pool
  // (acquireFloorSprite/releaseFloorSprite), just keyed by cell instead of entity id.
  const floorCells = new Map() // "i,j,layerName" -> Sprite
  const floorFree = []

  function acquireFloorSprite(parent) {
    let s = floorFree.pop()
    if (!s) s = new Sprite(Texture.EMPTY)
    s.visible = true
    parent.addChild(s)
    return s
  }
  function releaseFloorSprite(s) {
    s.visible = false
    floorFree.push(s)
  }

  // ground blotches: effectively always-on (soft translucent mottling everywhere),
  // texture/rotation/scale/jitter vary so neighboring cells never look tiled
  // Floor tint at a WORLD position: the single chapterRender.floorTint everywhere except skies,
  // where it's the blended per-district tint (config.js districtTintAt) sampled at that spot —
  // this is what makes the ground shift smoothly as the player roams across a Voronoi border.
  function floorTintAt(wx, wy) {
    return chapterHasDistricts ? districtTintAt(wx, wy, districtSeed) : chapterRender.floorTint
  }

  // Per-district on-screen size band for the ground pattern below (v5.9.1) — the "pattern
  // density" half of the ask: downtown reads tighter/denser (a paved grid), farms/sea read
  // broader/sparser (a wide field, calm open water). Districts absent here (parks) fall through
  // to the original chapter-wide [0.9, 1.6] blotch band, unchanged.
  const DISTRICT_GROUND_SCALE = {
    downtown: [0.65, 1.0],
    suburbs:  [0.9, 1.4],
    farms:    [1.1, 1.7],
    hills:    [0.8, 1.3],
    sea:      [1.2, 1.9],
  }
  // ---- THE GROUND COLOUR FIELD (v5.12) ----------------------------------------------------------
  // "You still don't understand how to do procedural layout coherent... layout coherence is just
  // awful" (playtest report, with wide-area captures).
  //
  // v5.11's populateTerrain put ONE OPAQUE SPRITE PER 280px CELL and tinted it from a SINGLE sample
  // of districtTintAt taken at the cell's centre. districtTintAt is continuous everywhere by
  // construction — that was the whole point of building it out of the raw elevation/moisture/urban
  // fields — and then this layer threw all of that away by point-sampling it onto an axis-aligned
  // lattice. One decision, three separate symptoms in the captures:
  //
  //   * the whole map reads as a CHECKERBOARD of flat 280px squares;
  //   * every biome boundary is an axis-aligned STAIRCASE, so a coastline comes out as a straight
  //     horizontal line — the single most obvious "this is generated" tell in the whole image;
  //   * where a field hovers near a threshold (elevation near SEA_LEVEL), neighbouring cells land on
  //     opposite sides of it and the ground breaks into SALT-AND-PEPPER — isolated blue squares
  //     stranded in dry land, which is what the report was pointing at.
  //
  // The fix is to stop making one layer do two jobs. COLOUR is a continuous field and is drawn here,
  // as a low-resolution bilinear-filtered texture per chunk: sample districtTintAt on a coarse grid,
  // upload it as a tiny canvas texture, and let the GPU's linear filtering reconstruct a smooth
  // gradient across the whole chunk. TEXTURE (crop rows, ripples, canopy) stays on the tile layer
  // below, but carries no colour at all, so its grid has nothing to quantise and becomes invisible.
  // This is the standard terrain split — a smooth blend/splat map plus tiled detail — and it is why
  // real terrain renderers do not have this problem.
  //
  // SEAMS. A texture drawn with linear filtering clamps at its outer half-texel, so two adjacent
  // chunks would disagree along their shared edge and leave a visible line — the same class of
  // artefact this is meant to remove. Each chunk therefore samples ONE EXTRA TEXEL OF PADDING on
  // every side and is drawn one texel larger, so texel centres land exactly on the chunk boundary
  // and a neighbour's edge texel holds the identical value. The interpolation is then continuous
  // across the join by construction, not by tuning.
  //
  // COST. districtTintAt is ~1.7us, so a chunk is GROUND_FIELD_N^2 x that, paid ONCE when the chunk
  // is created and then cached: at 24x24 over 512px that is ~0.6ms, and crossing a chunk boundary
  // creates about four. Nothing is recomputed per frame.
  const GROUND_CHUNK = 512      // world px covered by one chunk
  const GROUND_FIELD_N = 24     // samples across a chunk (world px per sample = 512/24 ≈ 21)
  const groundChunks = new Map()   // "i,j" -> Sprite
  const groundFree = []

  function buildGroundChunk(ci, cj) {
    const N = GROUND_FIELD_N
    const ts = GROUND_CHUNK / N            // world px per texel
    const c = document.createElement('canvas')
    c.width = c.height = N + 2             // +1 texel of padding each side, see SEAMS above
    const ctx = c.getContext('2d')
    const img = ctx.createImageData(N + 2, N + 2)
    const ox = ci * GROUND_CHUNK, oy = cj * GROUND_CHUNK
    for (let ty = 0; ty < N + 2; ty++) {
      for (let tx = 0; tx < N + 2; tx++) {
        // texel (tx,ty) centre in world space — matches where the sprite below places it
        const wx = ox + (tx - 0.5) * ts
        const wy = oy + (ty - 0.5) * ts
        const t = districtTintAt(wx, wy, districtSeed)
        const i = (ty * (N + 2) + tx) * 4
        img.data[i] = (t >> 16) & 255
        img.data[i + 1] = (t >> 8) & 255
        img.data[i + 2] = t & 255
        img.data[i + 3] = 255
      }
    }
    ctx.putImageData(img, 0, 0)
    const tex = Texture.from(c)
    tex.source.scaleMode = 'linear'      // the bilinear reconstruction IS the feature
    return tex
  }

  function updateGroundField(cx, cy) {
    if (!chapterHasDistricts) {
      for (const [, s] of groundChunks) { s.visible = false; groundFree.push(s) }
      groundChunks.clear()
      return
    }
    const N = GROUND_FIELD_N
    const ts = GROUND_CHUNK / N
    const i0 = Math.floor(-cx / GROUND_CHUNK) - 1, i1 = Math.floor((-cx + viewW()) / GROUND_CHUNK) + 1
    const j0 = Math.floor(-cy / GROUND_CHUNK) - 1, j1 = Math.floor((-cy + viewH()) / GROUND_CHUNK) + 1
    for (const [, s] of groundChunks) s._seen = false
    for (let i = i0; i <= i1; i++) {
      for (let j = j0; j <= j1; j++) {
        const key = i + ',' + j
        let s = groundChunks.get(key)
        if (!s) {
          s = groundFree.pop()
          if (!s) { s = new Sprite(Texture.EMPTY); s.anchor.set(0); groundLayer.addChild(s) }
          s.visible = true
          s.texture = buildGroundChunk(i, j)
          // drawn one texel larger on every side, anchored one texel back — this is what puts texel
          // centres on the chunk boundary (see SEAMS)
          s.position.set(i * GROUND_CHUNK - ts, j * GROUND_CHUNK - ts)
          s.width = GROUND_CHUNK + 2 * ts
          s.height = GROUND_CHUNK + 2 * ts
          groundChunks.set(key, s)
        }
        s._seen = true
      }
    }
    for (const [key, s] of groundChunks) {
      if (s._seen) continue
      s.visible = false
      if (s.texture && s.texture !== Texture.EMPTY) s.texture.destroy(true)
      s.texture = Texture.EMPTY
      groundFree.push(s)
      groundChunks.delete(key)
    }
  }

  function clearGroundField() {
    for (const [, s] of groundChunks) {
      s.visible = false
      if (s.texture && s.texture !== Texture.EMPTY) s.texture.destroy(true)
      s.texture = Texture.EMPTY
      groundFree.push(s)
    }
    groundChunks.clear()
  }

  // ---- the terrain layer (v5.11) ---------------------------------------------------------------
  // One full-cell tile per cell, no jitter, no random scale, no random rotation — see T.terrainTile's
  // header for why that is the whole point. This runs INSTEAD of populateBlotch on a chapter with a
  // terrain map (skies); every other chapter keeps the scattered-blotch floor unchanged.
  //
  // Per-parcel crop colour. Farmland's patchwork only reads if adjacent fields differ in HUE, and
  // the biome tint alone gives every field the same olive. Each parcel picks a crop from a small
  // palette and the tile tint is pulled most of the way toward it — "most of", not all, so the
  // region's one light still governs and a field cannot escape the chapter's luminance band.
  const PARCEL_CROP_TINTS = [
    0x8f9a53,   // young cereal, green
    0xa8a259,   // ripening barley
    0xb8a765,   // wheat, near harvest
    0x6f7f46,   // dense root crop, dark
    0x9c8f6b,   // stubble
    0x7d6f52,   // ploughed / fallow earth
  ]
  function populateTerrain(s, i, j, cell) {
    if (!chapterHasDistricts || !T.terrainTile) { s.visible = false; return }
    const wx = (i + 0.5) * cell, wy = (j + 0.5) * cell
    const biome = districtAt(wx, wy, districtSeed)

    // FARM PARCELS are the one place a hard-edged coloured rectangle is right (see parcelTile). Only
    // on a cell whose four corners are ALSO farmland, so a parcel edge can never land on a shoreline
    // and cut a square notch into it — which is exactly the artefact the rest of this rewrite exists
    // to remove.
    if (biome === 'farms') {
      const h = cell / 2
      const solid = districtAt(wx - h, wy - h, districtSeed) === 'farms'
        && districtAt(wx + h, wy - h, districtSeed) === 'farms'
        && districtAt(wx - h, wy + h, districtSeed) === 'farms'
        && districtAt(wx + h, wy + h, districtSeed) === 'farms'
      if (solid) {
        const parcel = parcelAt(wx, wy, districtSeed)
        const pats = T.parcelTile
        const idx = parcel.pivot ? pats.length - 1 : (parcel.rows * 2 + (parcel.shade > 0.5 ? 1 : 0)) % (pats.length - 1)
        const look = pats[Math.min(pats.length - 1, idx)]
        s.visible = true
        s.texture = look.tex
        s.anchor.set(look.ax, look.ay)
        s.alpha = 1
        s.rotation = 0
        s.scale.set((cell * 1.03) / look.ref)
        s.position.set(wx, wy)
        // The crop hue is blended over the ground field's own colour at this spot, so a parcel still
        // belongs to its region's light instead of being an unrelated swatch dropped on top.
        s.tint = lerpTint(floorTintAt(wx, wy), PARCEL_CROP_TINTS[parcel.crop], 0.55)
        return
      }
    }

    // Every other cell: TEXTURE ONLY. No fill and no tint — the colour under it is a continuous
    // field (updateGroundField), and the entire point of this layer no longer carrying colour is
    // that its 280px grid has nothing to quantise, so the grid itself becomes invisible.
    const pats = T.terrainTile[biome]
    if (!pats) { s.visible = false; return }
    const look = pats[Math.floor(cellHash(i, j, 1) * pats.length)]
    s.visible = true
    s.texture = look.tex
    s.anchor.set(look.ax, look.ay)
    s.alpha = 1
    s.rotation = 0
    s.scale.set((cell * 1.03) / look.ref)
    s.position.set(wx, wy)
    s.tint = 0xffffff
  }

  // Blend two packed RGB ints. (lerpColorInt lives in config.js and isn't exported; this is the
  // same three-channel mix, kept local rather than widening config's surface for one caller.)
  function lerpTint(a, b, t) {
    const ar = (a >> 16) & 255, ag = (a >> 8) & 255, ab = a & 255
    const br = (b >> 16) & 255, bg = (b >> 8) & 255, bb = b & 255
    return (Math.round(ar + (br - ar) * t) << 16) | (Math.round(ag + (bg - ag) * t) << 8) | Math.round(ab + (bb - ab) * t)
  }

  function populateBlotch(s, i, j, cell) {
    // v5.24 the blank: the void draws NO floor decoration at all — every scatter layer's populate
    // early-outs on chapterIsVoid (this one and the five below); bgColor alone is the ground.
    if (chapterIsVoid) { s.visible = false; return }
    // v5.11: a chapter with a terrain map draws populateTerrain's full-cell surface instead. The
    // scattered-blotch floor below is what every other chapter still uses.
    if (chapterHasDistricts) { s.visible = false; return }
    const jx = (cellHash(i, j, 4) - 0.5) * cell * 0.6
    const jy = (cellHash(i, j, 5) - 0.5) * cell * 0.6
    const wx = (i + 0.5) * cell + jx
    const wy = (j + 0.5) * cell + jy
    // v5.9.1: skies picks a per-district SIGNATURE pattern (T.districtGround, buildTextures above)
    // instead of the generic T.blotches every other chapter (and skies' own parks) still uses below
    // — see that block's header comment for why. farms is the one district that overrides the
    // random spin: its furrows share farmRowSnap's per-FIELD angle (same helper the cropTuft prop
    // uses) so a whole field's tiles read as one set of rows, not scattered dashes.
    if (chapterHasDistricts) {
      const dtype = districtAt(wx, wy, districtSeed)
      const pats = T.districtGround[dtype]
      if (pats) {
        const pat = pats[Math.floor(cellHash(i, j, 1) * pats.length)]
        s.texture = pat.tex
        s.anchor.set(pat.ax, pat.ay)
        s.alpha = 1
        s.rotation = dtype === 'farms' ? farmRowSnap(wx, wy).angle : cellHash(i, j, 2) * Math.PI * 2
        const [lo, hi] = DISTRICT_GROUND_SCALE[dtype] || [0.9, 1.6]
        s.scale.set(lerp(lo, hi, cellHash(i, j, 3)))
        s.position.set(wx, wy)
        s.tint = floorTintAt(wx, wy)
        return
      }
    }
    const idx = Math.floor(cellHash(i, j, 1) * T.blotches.length)
    s.texture = T.blotches[idx]
    s.anchor.set(0.5)
    s.alpha = 1
    s.rotation = cellHash(i, j, 2) * Math.PI * 2
    s.scale.set(lerp(0.9, 1.6, cellHash(i, j, 3)))
    s.position.set(wx, wy)
    s.tint = floorTintAt(wx, wy) // white for body; teal multiply recolours the pond ground
  }

  // ---- prop kinds + per-chapter biomes (v5.4) ------------------------------------------------
  // A "kind" is one scatterable thing. Two flavours, and applyPropKind handles both:
  //   sheet prop — { name } resolves in T.props (1024px source PNGs), so `size` is a TARGET
  //                ON-SCREEN SIZE in px, converted to a scale factor; `tints` pick a baked hue.
  //   baked prop — { baked: true } resolves in T (pebble/root/hydrant/...). Two sizing modes:
  //     `size`  — v5.9 top-down region overhaul: a TARGET ON-SCREEN SIZE in px, exactly like the
  //               sheet-prop path above, fit to the baked texture's OWN intrinsic bounds instead of
  //               a fixed 1024. Every skies district table (DISTRICT_BIOMES below) uses this —
  //               config.js's PROP_SCALE supplies the actual bands. This is the fix for the
  //               reported "cars bigger than houses" bug: `scale` (below) is a bare multiplier on
  //               each texture's OWN arbitrary baked size, so nothing stopped one class's
  //               scale-range times its baked size from exceeding another's (T.car baked from
  //               TRAFFIC_CAR_LEN=150 at scale [0.55,0.75] used to render at 82-112px — BIGGER than
  //               T.house, hand-drawn at 48px baked, at scale [0.9,1.4] = 43-67px). PROP_SCALE's
  //               bands are disjoint and ordered by construction, so `size` can't repeat that bug.
  //     `scale` — the ORIGINAL plain factor range, unchanged. Still used by every chapter-wide
  //               BIOMES entry outside DISTRICT_BIOMES (body/pond/garden/undergrowth/city/beyond) —
  //               none of those are in scope for this pass and must render bit-identical to before.
  // `upright` props keep their footing (small rotation jitter only, anchored at the base for baked
  // ones); top-down props spin freely. `cropRow` (farms district only) overrides BOTH the rotation
  // and the position — see farmRowSnap below. Everything is multiplied by chapterRender.floorTint,
  // so one prop set reads differently under each chapter's light.
  const BUSH_TINTS = [0x86b877, 0x76a869]
  const GRASS_TINTS = [0x9ccc80, 0x8bbf76, 0xa5cb8a]
  const CLUSTER_TINTS = [0xa8d19a, 0xc2dfae, 0x9bc98f]

  // Crop rows (farms district, skies — v5.9 top-down region overhaul): cultivated fields read as
  // top-down ONLY if the rows are straight and regular, which a per-sprite random jitter/rotation
  // can never produce — so cropRow props snap onto a per-FIELD lattice instead of scattering freely.
  // A "field" is its own coarse grid (FARM_FIELD px, deliberately independent of the prop-cell
  // grids in FLOOR_LAYERS) sharing ONE row angle, hashed from the field's own cell so it's
  // deterministic and stable (never re-rolls as the player walks the same field twice). Within a
  // field, (wx,wy) is rotated into row-aligned (u,v) space; only the CROSS-row coordinate v is
  // quantized to FARM_ROW_SPACING (snapping onto one of a few parallel row lines) — the ALONG-row
  // coordinate u is left as-is (already jittered by the caller's per-cell placement), so individual
  // crop clumps still scatter naturally along their row instead of forming a dotted grid.
  const FARM_FIELD = 360        // px per field — one shared row angle per field
  const FARM_ROW_SPACING = 26   // px between adjacent crop rows within a field
  function farmRowSnap(wx, wy) {
    const fi = Math.floor(wx / FARM_FIELD), fj = Math.floor(wy / FARM_FIELD)
    const fieldAngle = hash(fi * 12.9898 + fj * 78.233 + districtSeed * 0.0173 + 91.7) * Math.PI
    const ca = Math.cos(fieldAngle), sa = Math.sin(fieldAngle)
    const u = wx * ca + wy * sa
    const v = -wx * sa + wy * ca
    const vs = Math.round(v / FARM_ROW_SPACING) * FARM_ROW_SPACING
    return { x: u * ca - vs * sa, y: u * sa + vs * ca, angle: fieldAngle }
  }

  // Returns the position the sprite should actually be placed at ({x,y} — normally just the
  // (wx,wy) the caller already computed, EXCEPT cropRow props, which override it via farmRowSnap).
  // v5.10 (spec §4.5): `litTint: true` BYPASSES the floor tint. Chlorine-blue pool water, shipping
  // container red, fresh crosswalk paint and a car's body colour all turn to mud when multiplied by
  // a district floorTint. Saturated accents are the chapter's scarcest resource — the threats own
  // saturation — so the handful of props allowed to keep theirs must opt in explicitly.
  // A neutral night tone for litTint props. `litTint` means "keep your own HUE" — it does not mean
  // "ignore that it is 3am in a thunderstorm". Without this a parked hatchback is the brightest
  // object in the region, outshining the building it is parked next to.
  const SKIES_NIGHT_TINT = 0x9aa0a8
  function propTint(kind, i, j, floorTint) {
    const base = kind.tints ? kind.tints[Math.floor(cellHash(i, j, 2) * kind.tints.length)] : (kind.tint ?? 0xffffff)
    return tintMul(base, kind.litTint ? SKIES_NIGHT_TINT : floorTint)
  }

  function applyPropKind(s, kind, i, j, wx, wy) {
    const floorTint = floorTintAt(wx, wy)
    if (kind.baked) {
      const look = T[kind.name]
      s.texture = look.tex
      s.anchor.set(look.ax, look.ay)
      s.tint = propTint(kind, i, j, floorTint)
      s.alpha = kind.alpha ?? 1
      if (kind.size) {
        const targetPx = lerp(kind.size[0], kind.size[1], cellHash(i, j, 4))
        s.scale.set(targetPx / Math.max(look.tex.width, look.tex.height))
      } else {
        s.scale.set(lerp(kind.scale[0], kind.scale[1], cellHash(i, j, 4)))
      }
    } else {
      s.texture = T.props[kind.name]
      s.anchor.set(0.5, kind.upright ? 0.9 : 0.5)
      s.tint = propTint(kind, i, j, floorTint)
      s.alpha = kind.alpha ?? 1
      s.scale.set(lerp(kind.size[0], kind.size[1], cellHash(i, j, 4)) / 1024)
    }
    if (kind.cropRow) {
      const snap = farmRowSnap(wx, wy)
      s.rotation = snap.angle
      return { x: snap.x, y: snap.y }
    }
    // v5.10 (SKIES_VEHICLE.alignToKerb): a parked vehicle, a parking lot's stall stripes and a
    // tractor all line up with the STREET GRID, never a random spin. Random rotation is the single
    // loudest tell that a scene was scattered by an algorithm rather than laid out by a city.
    if (kind.alignRoad) {
      s.rotation = nearestStreetAngle(wx, wy) + (cellHash(i, j, 3) - 0.5) * 0.06
      return { x: wx, y: wy }
    }
    // upright things stay upright — only top-down scatter is free to spin
    s.rotation = kind.upright ? (cellHash(i, j, 3) - 0.5) * 0.16 : cellHash(i, j, 3) * Math.PI * 2
    return { x: wx, y: wy }
  }

  // big: one bulky landmark per cell — bushes on the green chapters, hard furniture elsewhere
  const BIG_BUSH = [
    { name: 'bush_a', tints: BUSH_TINTS, upright: true, size: [90, 145] },
    { name: 'bush_b', tints: BUSH_TINTS, upright: true, size: [90, 145] },
  ]
  // Pond's own palette (v6.4 — BIOME_POND below). The old roster just aliased `pond: BIOME_GARDEN`
  // (a sunlit-lawn look — pink/white flowers — dropped onto a murky teal floor). Every pond-only
  // tint below is authored against the pond's EFFECTIVE floor (bg 0x2e6258 under floorTint
  // 0x66c2a9, composited over the mean blotch — obstacle-contrast.mjs's own model — luminance
  // ~0.186) into the same ~1.1-1.6x WCAG decor band BIOME_BODY's props use (see that block's
  // comment, ~line 3730): the darker family members (reed/bush/algae/weed/leaf) land ~1.25-1.45x
  // BELOW the floor, the paler ones (mushroom/scatter dust/lilypad sheen) land ~1.25-1.30x ABOVE
  // it — well short of every creature's own contrast (tadpole 3.74x, amoeba 3.54x, tardigrade
  // 2.79x vs this same floor), so decor never competes with the roster for the eye.
  const REED_MURK_TINTS = [0x669369, 0x5c8760]        // big: bush-scale reed; mid: normal-scale reed
  const BUSH_DEEPWATER_TINTS = [0x47928a, 0x3f8078]   // deep-water bush_a
  const MUSHROOM_BOG_TINTS = [0xc5c9b2]                // pale bog mushroom — no pink here
  const ALGAE_TINTS = [0x6b944f, 0x739b55, 0x628d4d]   // cluster_a/b/c
  const WEED_TINTS = [0x6c9456, 0x648d52]              // grass_c/d
  const BIG_POND = [
    { name: 'reed', tints: REED_MURK_TINTS, upright: true, size: [110, 175] }, // bush-scale, murk tint
    { name: 'bush_a', tints: BUSH_DEEPWATER_TINTS, upright: true, size: [90, 145] },
    { name: 'lilypad', baked: true, scale: [1.4, 2.2] },
  ]
  const BIG_UNDERGROWTH = [
    { name: 'root', baked: true, upright: true, scale: [0.85, 1.5] },
    { name: 'bush_a', tints: [0x6f7a4a, 0x5d6840], upright: true, size: [80, 130] },
  ]
  const BIG_CITY = [{ name: 'dumpster', baked: true, upright: true, scale: [0.9, 1.5] }]
  // downtown (skies district, v5.9 top-down region overhaul): rubble is loose GROUND debris here
  // (the actual "tower" landmark comes from the crushable obstacle field, STRUCTURE_SKINS.tower
  // below) — sized from PROP_SCALE.debris, the smallest class, not a bare scale multiplier on
  // rubble's own baked size (that used to render 64-116px, bigger than a house — see PROP_SCALE's
  // doc in config.js for the full bug). 'car' added for item-5 density: downtown streets read as
  // abandoned/wrecked, and the texture already exists (T.car, shared with suburbs/traffic).
  // v5.10 (spec §6, kill list §8.9): the skies car set replaces T.car, the CITY chapter's yellow
  // traffic taxi baked from TRAFFIC_CAR_LEN. Three silhouettes you can tell apart at a glance, all
  // `litTint` (their desaturated body hues must not inherit a park's grass green or a farm's khaki)
  // and all `alignRoad` — parked cars align to the street grid's angle, NEVER a random rotation,
  // which is the single loudest tell that a scene was scattered by an algorithm.
  const SKIES_CARS = [
    // Sized in PROPORTION to their own baked lengths (26 / 32 / 54 px) so the length ratios that
    // carry the read survive — sedan < van < bus — but pegged UNDER PROP_SCALE.car's band rather
    // than across it: a crushable tower's silhouette is only ~2.2 x STRUCTURE_RADIUS.tower (46-70
    // px on screen) in this chapter, because the whole v5.8 premise is a player BIGGER than the
    // city. A bus at PROP_SCALE.car's full 30px x (54/26) would be tower-sized, which is the
    // "cars bigger than houses" bug wearing new art.
    { name: 'vehSedan', baked: true, litTint: true, alignRoad: true, tints: SKIES_VEHICLE.bodyTints, size: [15, 21] },
    { name: 'vehVan', baked: true, litTint: true, alignRoad: true, tints: SKIES_VEHICLE.bodyTints, size: [18, 26] },
    { name: 'vehBus', baked: true, litTint: true, alignRoad: true, tints: SKIES_VEHICLE.bodyTints, size: [31, 43] },
  ]
  const BIG_SKIES = [
    { name: 'rubble', baked: true, upright: true, size: PROP_SCALE.debris },
    { name: 'parkingLot', baked: true, alignRoad: true, litTint: true, size: [150, 190] },
    ...SKIES_CARS,
  ]
  const BIG_BEYOND = [{ name: 'asteroid', baked: true, scale: [1.0, 1.9] }]
  // body: one substantial piece of anatomy per cell — a villi mound (upright, planted) or a
  // top-down bunch of transport vesicles. Both baked in warm pink, both low-contrast decor.
  const BIG_BODY = [
    { name: 'villi', baked: true, upright: true, scale: [0.9, 1.5] },
    { name: 'vesicles', baked: true, scale: [0.85, 1.5] },
  ]

  // Prop biome at a WORLD position: chapterBiome everywhere except skies, where each cell's
  // big/mid/detail set is picked by which district (config.js districtAt) sits under it.
  function biomeAt(wx, wy) {
    return chapterHasDistricts ? DISTRICT_BIOMES[districtAt(wx, wy, districtSeed)] : chapterBiome
  }

  // v6.9.5 (owner: "no trash cans, fire hydrant etc sprites on roads, only inbetween"). The
  // OBSTACLE streamer has rejected roadway since v5.9, but the four decorative floor layers never
  // asked — so hydrants, cones, dumpsters and foliage were scattered across the carriageway. They
  // are skipped rather than pushed aside: a decor cell that lands on tarmac simply has nothing in
  // it, which is also what the gaps between props on a real street look like.
  function onCarriageway(wx, wy) {
    return chapterHasRoads && roadAt(wx, wy, roadSeed, chapterEndlessGrid).onRoad
  }

  function populateBig(s, i, j, cell) {
    if (chapterIsVoid) { s.visible = false; return } // the blank: flat void, no props
    // 0.7 -> 0.94: at 0.7 a prop could only move +-35% of a cell, so the underlying cell pitch was
    // still legible as a grid even once clumping thinned it. 0.94 lets a prop reach almost to its
    // cell's edge, which is what actually erases the lattice.
    const jx = (cellHash(i, j, 5) - 0.5) * cell * 0.94
    const jy = (cellHash(i, j, 6) - 0.5) * cell * 0.94
    const wx = (i + 0.5) * cell + jx
    const wy = (j + 0.5) * cell + jy
    if (onCarriageway(wx, wy)) { s.visible = false; return }
    const kinds = biomeAt(wx, wy).big
    const pos = applyPropKind(s, kinds[Math.floor(cellHash(i, j, 1) * kinds.length)], i, j, wx, wy)
    s.position.set(pos.x, pos.y)
  }

  // mid: grass/flowers/mushroom/reed (upright, side-view) + clusters (top-down)
  const MID_GARDEN = [
    { name: 'grass_a', tints: GRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_b', tints: GRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_c', tints: GRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_d', tints: GRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'flower_a', tints: [0xffd1e0, 0xffd93d], upright: true, size: [34, 55] },
    { name: 'flower_b', tints: [0xfff3f8], upright: true, size: [34, 55] },
    { name: 'mushroom', tints: [0xffb3c6], upright: true, size: [26, 42] },
    { name: 'reed', tints: [0x8fae7a], upright: true, size: [45, 70] },
    { name: 'cluster_a', tints: CLUSTER_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_b', tints: CLUSTER_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_c', tints: CLUSTER_TINTS, upright: false, size: [50, 78] },
  ]
  // pond: reed x2 (murk) + weeds where garden had lawn grass, algae clusters where garden had lawn
  // clusters, bog mushroom, small lilypad — NO flower_a/flower_b (a murky pond grows no sunlit
  // lawn flowers). Tints from the palette declared above BIG_POND.
  const MID_POND = [
    { name: 'reed', tints: REED_MURK_TINTS, upright: true, size: [45, 70] },
    { name: 'reed', tints: REED_MURK_TINTS, upright: true, size: [45, 70] },
    { name: 'mushroom', tints: MUSHROOM_BOG_TINTS, upright: true, size: [26, 42] },
    { name: 'grass_c', tints: WEED_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_d', tints: WEED_TINTS, upright: true, size: [28, 48] },
    { name: 'cluster_a', tints: ALGAE_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_b', tints: ALGAE_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_c', tints: ALGAE_TINTS, upright: false, size: [50, 78] },
    { name: 'lilypad', baked: true, scale: [0.5, 0.75] },
  ]
  // undergrowth: shade botany only — no sunlit flowers down here, and the mushrooms go pallid
  const MID_UNDERGROWTH = [
    { name: 'grass_c', tints: [0x7f8a52, 0x6d7746], upright: true, size: [30, 52] },
    { name: 'grass_d', tints: [0x7f8a52, 0x6d7746], upright: true, size: [30, 52] },
    { name: 'mushroom', tints: [0xd8cfb0, 0xc4b294], upright: true, size: [26, 44] },
    { name: 'bone', baked: true, scale: [0.7, 1.2] },
    { name: 'cluster_b', tints: [0x6f7a4a, 0x59623a], upright: false, size: [46, 74] },
  ]
  // city: street furniture, plus weeds coming up through the cracks (the city is still alive)
  const MID_CITY = [
    { name: 'hydrant', baked: true, upright: true, scale: [0.9, 1.3] },
    { name: 'cone', baked: true, upright: true, scale: [0.85, 1.25] },
    { name: 'grass_a', tints: [0x6f8a52], upright: true, size: [22, 38] },
  ]
  // skies + beyond: nothing grows. Smaller siblings of the big layer's chunks, scattered.
  const MID_SKIES = [
    { name: 'rubble', baked: true, upright: true, size: PROP_SCALE.debris },
    ...SKIES_CARS,
  ]
  const MID_BEYOND = [{ name: 'asteroid', baked: true, scale: [0.35, 0.75] }]
  // body: medium accents — platelet plates, lipid beads, capillary squiggles. Mild alpha so they
  // sit under the enemies. All top-down (spin freely).
  const MID_BODY = [
    { name: 'platelet', baked: true, alpha: 0.9, scale: [0.85, 1.5] },
    { name: 'lipid', baked: true, alpha: 0.9, scale: [0.8, 1.35] },
    { name: 'capillary', baked: true, alpha: 0.85, scale: [0.9, 1.6] },
  ]

  function populateMid(s, i, j, cell) {
    if (chapterIsVoid) { s.visible = false; return } // the blank: flat void, no props
    // 0.7 -> 0.94: at 0.7 a prop could only move +-35% of a cell, so the underlying cell pitch was
    // still legible as a grid even once clumping thinned it. 0.94 lets a prop reach almost to its
    // cell's edge, which is what actually erases the lattice.
    const jx = (cellHash(i, j, 5) - 0.5) * cell * 0.94
    const jy = (cellHash(i, j, 6) - 0.5) * cell * 0.94
    const wx = (i + 0.5) * cell + jx
    const wy = (j + 0.5) * cell + jy
    if (onCarriageway(wx, wy)) { s.visible = false; return }
    const kinds = biomeAt(wx, wy).mid
    const pos = applyPropKind(s, kinds[Math.floor(cellHash(i, j, 1) * kinds.length)], i, j, wx, wy)
    s.position.set(pos.x, pos.y)
  }

  // detail: scatter/leaf sprites + hand-drawn baked bits (pebble, puddle, bone, ...)
  const DETAIL_GARDEN = [
    { name: 'scatter_a', tint: 0xd9e6c0, alpha: 0.55, size: [24, 42] },
    { name: 'scatter_b', tint: 0xd9e6c0, alpha: 0.55, size: [24, 42] },
    { name: 'leaf', tint: 0xe8b28a, alpha: 0.7, size: [18, 32] },
    { name: 'pebble', baked: true, scale: [0.7, 1.4] },
    { name: 'puddle', baked: true, scale: [0.7, 1.4] },
  ]
  // pond: pebble + pale algae dust + dark drift-leaf. No puddle — the whole floor already IS water.
  const DETAIL_POND = [
    { name: 'pebble', baked: true, scale: [0.7, 1.4] },
    { name: 'scatter_a', tint: 0xcfd9b6, alpha: 0.55, size: [24, 42] },
    { name: 'leaf', tint: 0x728b59, alpha: 0.7, size: [18, 32] },
  ]
  // undergrowth: deep leaf litter — the floor IS dead leaves, so scatter/leaf dominate
  const DETAIL_UNDERGROWTH = [
    { name: 'leaf', tint: 0xb08050, alpha: 0.8, size: [20, 36] },
    { name: 'leaf', tint: 0x8a6a3e, alpha: 0.7, size: [18, 32] },
    { name: 'scatter_a', tint: 0xa89466, alpha: 0.6, size: [24, 42] },
    { name: 'bone', baked: true, scale: [0.45, 0.8] },
    { name: 'pebble', baked: true, scale: [0.7, 1.3] },
  ]
  // city: litter and wet asphalt — the puddle earns its keep on a night street
  const DETAIL_CITY = [
    { name: 'scatter_b', tint: 0xc9c4b8, alpha: 0.45, size: [22, 38] },
    { name: 'leaf', tint: 0xb8b0a0, alpha: 0.5, size: [16, 28] },
    { name: 'puddle', baked: true, scale: [0.9, 1.7] },
    { name: 'pebble', baked: true, scale: [0.6, 1.1] },
  ]
  const DETAIL_SKIES = [
    { name: 'pebble', baked: true, size: PROP_SCALE.debris },
    { name: 'scatter_b', tint: 0xd8d2c4, alpha: 0.4, size: [22, 38] },
  ]
  const DETAIL_BEYOND = [
    { name: 'pebble', baked: true, scale: [0.5, 1.1] },
    { name: 'asteroid', baked: true, scale: [0.16, 0.3] },
  ]
  // body: small low-alpha scatter — drifting plasma motes plus tiny dimmed platelets and capillary
  // fragments. Barely stains the floor; pure background stipple.
  const DETAIL_BODY = [
    { name: 'mote', baked: true, alpha: 0.5, scale: [0.6, 1.3] },
    { name: 'platelet', baked: true, alpha: 0.6, scale: [0.4, 0.7] },
    { name: 'capillary', baked: true, alpha: 0.45, scale: [0.5, 0.85] },
  ]

  function populateDetail(s, i, j, cell) {
    if (chapterIsVoid) { s.visible = false; return } // the blank: flat void, no props
    // 0.7 -> 0.94: at 0.7 a prop could only move +-35% of a cell, so the underlying cell pitch was
    // still legible as a grid even once clumping thinned it. 0.94 lets a prop reach almost to its
    // cell's edge, which is what actually erases the lattice.
    const jx = (cellHash(i, j, 5) - 0.5) * cell * 0.94
    const jy = (cellHash(i, j, 6) - 0.5) * cell * 0.94
    const wx = (i + 0.5) * cell + jx
    const wy = (j + 0.5) * cell + jy
    if (onCarriageway(wx, wy)) { s.visible = false; return }
    const kinds = biomeAt(wx, wy).detail
    const pos = applyPropKind(s, kinds[Math.floor(cellHash(i, j, 1) * kinds.length)], i, j, wx, wy)
    s.position.set(pos.x, pos.y)
  }

  // Per-chapter biome: which prop kinds scatter on each floor layer, and how the chapter's
  // run.obstacles colliders are dressed. Keyed by chapter id and latched in reset(run) alongside
  // chapterRender — the CHAPTERS[].render block is data the sim shares, this is render's own.
  // `obstacle.clumps` names sheet props stacked into a mound (the pond's reed idiom);
  // `obstacle.baked` names baked props planted on the pad instead (hard furniture).
  // Every obstacle sits on a hard `foot` ring baked at T.obFoot and scaled so its rim lands EXACTLY
  // on the collider edge o.r — that ring is the collision contract, so `foot` is picked for CONTRAST
  // against each biome's floor (dark rings on pale floors, pale rings on dark floors), not for theme.
  // `tint` is the obstacle mass: denser/darker than the floor props of the same family.
  const OBSTACLE_CLUMPS = ['cluster_a', 'cluster_b', 'cluster_c']
  const BIOME_GARDEN = {
    big: BIG_BUSH, mid: MID_GARDEN, detail: DETAIL_GARDEN,
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x5f8f4a, foot: 0x243617 },
  }
  // The Body gets its OWN anatomy props (was reusing the Garden's bushes/grass — plants inside a
  // host organism). obstacle kept identical to the Garden's: the body has no obstacles in config,
  // so this field is inert here and another agent owns obstacle styling.
  const BIOME_BODY = {
    big: BIG_BODY, mid: MID_BODY, detail: DETAIL_BODY,
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x8fbf6f, glow: 0xbfe8dd, glowAlpha: 0.5 },
  }
  // The Pond gets its OWN murk-water props (v6.4 — was `pond: BIOME_GARDEN`, a bare object-reference
  // alias to the sunlit-lawn look; see BIG_POND's comment above for the full contrast methodology
  // and the measured band). `foot` stays 0x243617 (obstacle-contrast.mjs already clears it — that
  // script reads config.js's floorTint, not this mass tint, so nothing it checks moved); the mass
  // `tint` shifts murkier than the garden's 0x5f8f4a, toward the same dark algae-green family as
  // ALGAE_TINTS/WEED_TINTS above, so an obstacle mound reads as SUBMERGED growth, not a lawn hedge.
  const BIOME_POND = {
    big: BIG_POND, mid: MID_POND, detail: DETAIL_POND,
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x3a5a34, foot: 0x243617 },
  }

  // ---- The Shelf (v7.x Book 2) — open water over the continental shelf --------------------------
  // Owner: "this looks too much like the pond ... we're at the SURFACE of the ocean, we're not in a
  // pond, so green is weird." The Shelf spent one version aliased to BIOME_POND, which put reeds,
  // BOG MUSHROOMS and LILYPADS in the open sea. This is the fix, and it is a retint plus a cast
  // change rather than new art: the prop PNGs are shape-neutral enough that a reed reads as a kelp
  // stipe and a cluster reads as a weed raft, but nothing makes a lilypad read as anything else.
  //
  // GREEN IS THE WHOLE NOTE. Every tint here keeps BLUE >= GREEN, which is the property the pond
  // family breaks (0x669369, 0x6b944f, 0x6c9456 — all green-dominant). Retinting via `floorTint`
  // alone cannot do this: floorTint is a MULTIPLY, so it can only ever drag a green prop toward
  // teal and never off green. The work has to happen here, at the source tints, which is why this
  // is a separate biome and not a wash over the pond's.
  //
  // Contrast follows BIG_POND's measured methodology rather than re-deriving it: the darker family
  // (kelp/seagrass/weed) sits ~1.3-1.45x BELOW the effective floor and the pale family (foam) sits
  // above it, so decor stays well clear of every creature's own contrast and never competes with
  // the roster for the eye. scripts/obstacle-contrast.mjs audits the obstacle line specifically.
  const KELP_TINTS = [0x1f4f5e, 0x1b4553]          // kelp stipe — big/mid `reed`
  const KELP_BUNDLE_TINTS = [0x21545f, 0x1c4a55]   // a bundled holdfast — `bush_a`
  const SEAGRASS_TINTS = [0x246071, 0x1f5566]      // grass_c/d
  const WEEDRAFT_TINTS = [0x2a5f66, 0x25565e, 0x2f6a70] // cluster_a/b/c — floating weed
  const BIG_SHELF = [
    { name: 'reed', tints: KELP_TINTS, upright: true, size: [110, 175] },
    { name: 'bush_a', tints: KELP_BUNDLE_TINTS, upright: true, size: [90, 145] },
    { name: 'cluster_b', tints: WEEDRAFT_TINTS, upright: false, size: [86, 132] },
  ]
  const MID_SHELF = [
    { name: 'reed', tints: KELP_TINTS, upright: true, size: [45, 70] },
    { name: 'grass_c', tints: SEAGRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_d', tints: SEAGRASS_TINTS, upright: true, size: [28, 48] },
    { name: 'cluster_a', tints: WEEDRAFT_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_c', tints: WEEDRAFT_TINTS, upright: false, size: [50, 78] },
  ]
  // Foam, not litter: the pale member of the family is sea foam flecking the surface, which is the
  // one thing on this floor that belongs at the TOP of the water rather than under it.
  const DETAIL_SHELF = [
    { name: 'scatter_a', tint: 0xdcecf6, alpha: 0.5, size: [24, 42] },
    { name: 'scatter_b', tint: 0xc8e2f0, alpha: 0.42, size: [20, 36] },
    { name: 'leaf', tint: 0x2b6270, alpha: 0.65, size: [18, 32] },
    { name: 'pebble', baked: true, scale: [0.7, 1.4] },
  ]
  const BIOME_SHELF = {
    big: BIG_SHELF, mid: MID_SHELF, detail: DETAIL_SHELF,
    // Reef rock, not a submerged hedge: cool blue-grey stone with a near-black foot.
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x2f4d5c, foot: 0x122029 },
  }
  // ---- The Surf (v7.x Book 2 ch 1) — the tide line ---------------------------------------------
  // A retint of the shelf's own trick (shape-neutral prop PNGs re-read as something else), not new
  // art. On a beach the plants are WRACK — weed the tide threw up and left to dry — plus marram
  // tufts back off the water, so the flat `cluster_*` rafts become wrack piles and the uprights stay
  // upright. Registering this at all is the point: chapterBiome falls back to BIOMES.body for an
  // unknown id, and until this line existed The Surf drew VILLI, PLATELETS and plasma motes on its
  // beach — the exact failure BIOME_SHELF's comment warns about, one chapter later.
  //
  // Contrast follows the same rule as its two neighbours: the decor family sits BELOW the effective
  // floor (bgColor 0xbca27a under floorTint 0xe0c79c) so it never competes with the roster, and the
  // one pale member is sea foam. Everything is warm-dominant (R >= G > B), which is what separates
  // this family from The Shelf's blue-dominant one at a glance.
  const WRACK_TINTS = [0x6b5a30, 0x5c4d29]         // dried weed thrown up by the tide
  const WRACK_DARK_TINTS = [0x4f4324, 0x453a1f]    // the older, deeper pile
  const MARRAM_TINTS = [0x7d7a3e, 0x6d6a35]        // dune grass, olive rather than lawn-green
  const BIG_SURF = [
    { name: 'bush_a', tints: WRACK_DARK_TINTS, upright: false, size: [88, 140] },
    { name: 'cluster_b', tints: WRACK_TINTS, upright: false, size: [86, 132] },
  ]
  const MID_SURF = [
    { name: 'grass_c', tints: MARRAM_TINTS, upright: true, size: [30, 50] },
    { name: 'grass_d', tints: MARRAM_TINTS, upright: true, size: [30, 50] },
    { name: 'cluster_a', tints: WRACK_TINTS, upright: false, size: [48, 76] },
    { name: 'cluster_c', tints: WRACK_DARK_TINTS, upright: false, size: [48, 76] },
  ]
  const DETAIL_SURF = [
    { name: 'scatter_a', tint: 0xfaf2e2, alpha: 0.55, size: [22, 40] }, // foam / shell grit
    { name: 'scatter_b', tint: 0xefe1c6, alpha: 0.45, size: [18, 34] },
    { name: 'leaf', tint: 0x5c4d29, alpha: 0.6, size: [16, 30] },       // a scrap of dried weed
    { name: 'pebble', baked: true, scale: [0.7, 1.4] },
  ]
  const BIOME_SURF = {
    big: BIG_SURF, mid: MID_SURF, detail: DETAIL_SURF,
    // A weed-fouled boulder in the wash: warm wet stone over a dark WARM foot ring for the collision
    // contract. Every other biome's foot is near-black, which is right over their dark floors and
    // punches a manhole in this one — the ring only has to clear the contrast the footprint audit
    // asks for, and against sand at luminance ~0.38 a warm 0x3d3324 clears it without going black.
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x6a5c46, foot: 0x3d3324 },
  }
  // ---- The Reef (v7.x Book 2 ch 3) — warm coral over deep water -------------------------------
  // The Shelf's own methodology (a retint of the shape-neutral prop PNGs, not new art), pointed the
  // OPPOSITE way. Every tint in BIOME_SHELF keeps BLUE >= GREEN because it is open sea; a reef is
  // the one place in the ocean that is warm and saturated, so every tint here is RED-DOMINANT
  // (R > G, R > B) and the family runs red -> magenta -> violet. That inversion is the chapter's
  // whole identity, and it is why this is a separate biome rather than a hue nudge on The Shelf's.
  //
  // THE SHAPES, and what each PNG is being re-read as from directly overhead:
  //   bush_b   — a lobed rosette, the ONE prop no water biome uses. From above it is a BRAIN CORAL
  //              head, which is the reef's signature mass and the shape nothing else in the game has.
  //   cluster_* — radial branching rosettes: TABLE CORAL colonies, flat on the floor.
  //   reed / flower_a — vertical blades and budded stalks: SEA WHIPS and gorgonians, upright.
  //   grass_c/d — soft coral tufts, upright.
  //
  // THE MEASURED BAND (WCAG contrast against the effective floor, the obstacle-contrast.mjs model:
  // mean blotch x floorTint over bgColor). The reef floor is bg 0x0a3358 under floorTint 0xa9cfe0 =
  // #4d717f, luminance 0.150 — one step deeper than The Shelf's 0.210.
  //   coral decor  1.78x - 2.54x BELOW the floor   (The Shelf's own family measures 1.94x - 2.69x)
  //   coral grit   1.9x  - 2.3x  ABOVE it
  //   the roster   2.7x  - 4.9x  ABOVE it          (drawMoray/drawDamselfish/drawLionfish)
  // So decor and roster do not merely differ in magnitude, they sit on OPPOSITE SIDES of the floor:
  // everything scenic is darker than the water, everything alive is lighter. That is the same split
  // The Shelf makes, and it is what stops a warm reef competing with a warm player.
  //
  // ⚠ WARM IS ONLY AVAILABLE AT LOW VALUE HERE, and that is a consequence, not a compromise.
  // floorTint multiplies the props (propTint), so at (0.66, 0.81, 0.88) the most red any prop can
  // reach is 0.66 x 255 = 169. A BRIGHT warm coral is unreachable through that multiply; a dark
  // saturated one is not. Hence raw tints authored several steps hotter than they land.
  const CORAL_STAG_TINTS = [0x9c2f30, 0xae3a34]           // branching staghorn — big/mid `reed`
  const CORAL_BRAIN_TINTS = [0x8c2450, 0x7d2048]          // lobed boulder head — `bush_b`
  // The flats carry the most screen area, so they run magenta -> violet -> red rather than all
  // violet: a first probe frame came back reading purple overall, because the two biggest props in
  // it were both from the violet end and the reds were all in the small upright tufts.
  const CORAL_TABLE_TINTS = [0x8a2a5c, 0x7b2a72, 0x932f48] // table/plate colonies — cluster_a/b/c
  const CORAL_SOFT_TINTS = [0x94305c, 0xa33a68]           // soft coral / gorgonian — grass_c/d, flower_a
  // The one ORANGE member, and it is here because a first probe frame of the family above came back
  // reading uniformly magenta-to-violet: red, pink and purple were all present and orange was not,
  // so the reef had a colour rather than a palette. A sponge clump is the honest way to get it.
  // ⚠ IT LANDS AS A WARM BROWN, not as an orange, and that is the ceiling rather than a bad pick:
  // orange at the value this band allows IS brown, and the floorTint multiply takes a third of the
  // red on top. It is therefore a MID prop only — a second probe frame with it at BIG size read as
  // brown mud clumps dominating the reef, which cost more than the hue variety bought.
  const CORAL_SPONGE_TINTS = [0x8f4214, 0xa04e14]         // sponge clump — `bush_a`
  const BIG_REEF = [
    { name: 'bush_b', tints: CORAL_BRAIN_TINTS, upright: false, size: [96, 152] },
    { name: 'reed', tints: CORAL_STAG_TINTS, upright: true, size: [105, 168] },
    { name: 'cluster_b', tints: CORAL_TABLE_TINTS, upright: false, size: [92, 142] },
  ]
  const MID_REEF = [
    { name: 'bush_a', tints: CORAL_SPONGE_TINTS, upright: true, size: [42, 68] },
    { name: 'flower_a', tints: CORAL_SOFT_TINTS, upright: true, size: [40, 66] },
    { name: 'grass_c', tints: CORAL_SOFT_TINTS, upright: true, size: [28, 48] },
    { name: 'grass_d', tints: CORAL_SOFT_TINTS, upright: true, size: [28, 48] },
    { name: 'cluster_a', tints: CORAL_TABLE_TINTS, upright: false, size: [50, 78] },
    { name: 'cluster_c', tints: CORAL_TABLE_TINTS, upright: false, size: [50, 78] },
  ]
  // Coral sand, not foam: the pale member of a reef family is the crushed skeleton of the family
  // above it, lying in the gaps between heads. Low alpha keeps it grit rather than snow.
  const DETAIL_REEF = [
    { name: 'scatter_a', tint: 0xf2d6cc, alpha: 0.5, size: [24, 42] },
    { name: 'scatter_b', tint: 0xe0c0ba, alpha: 0.42, size: [20, 36] },
    // A coral nubbin, NOT the `leaf` prop its two neighbours use. leaf is a maple silhouette and it
    // survives being read as a scrap of dried wrack on a beach or a weed fragment in open water; on
    // a reef floor it is unmistakably a maple leaf, which a probe frame showed at once.
    { name: 'cluster_c', tints: CORAL_TABLE_TINTS, upright: false, alpha: 0.75, size: [20, 34] },
    { name: 'pebble', baked: true, scale: [0.7, 1.4] },
  ]
  const BIOME_REEF = {
    big: BIG_REEF, mid: MID_REEF, detail: DETAIL_REEF,
    // A bommie: the clump mound reads as a coral head, in the family's deepest plum-red, over a
    // near-black aubergine foot. The floor here is dark (L 0.150), so the rim still clears the
    // audit's 2x by going darker still rather than by going black-and-cold — 3.73x, warm.
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x6e2a44, foot: 0x1c0a1a },
  }
  // ---- The Trawl (v7.x Book 2 ch 4) — the boat's discharge, settled -----------------------------
  // The third retint of the same shape-neutral prop PNGs, and the first one where the decor is not
  // ALIVE. Spec §4 gives this chapter's pollution as "bags at mid-water, the boat's discharge", and
  // what an overhead camera sees of that is what has already sunk: bags collapsed flat on the bottom,
  // scraps of lost net, and the dull sheen of settled sediment.
  //
  // THE CONTRAST RULE IS INVERTED HERE, deliberately, and it is the one thing to preserve if these
  // tints are ever touched. The Shelf, the Surf and the Reef all put their decor BELOW the effective
  // floor and their roster ABOVE it, so scenery is dark and life is light. That works when the floor
  // is mid-value. This floor is the darkest in the book (bg 0x05203f under floorTint 0x93b6cc), and
  // pushing the decor below it would put rubbish at near-black on near-black — the props would simply
  // be absent, which is not "sparse", it is a floor that looks broken. So the litter sits just ABOVE
  // the floor in value and stays DESATURATED, while the roster is above it in value AND carries the
  // only saturation in the chapter (the tuna's yellow finlets, the sea lion's brown coat). Value
  // separates the litter from the water; SATURATION separates the life from the litter.
  //
  // Nothing here is green or growing. A weed tint in this family would read as The Shelf.
  //
  // ⚠ NO RADIAL ROSETTES — no `cluster_*` anywhere in this family, and that is a shot-driven rule
  // rather than a preference. The first cut used cluster_a/cluster_c for flat litter, on the same
  // reasoning the reef uses them for table coral, and the probe frame came back with what are
  // unmistakably SNOWFLAKES scattered over the sea bed: a pale, symmetric, radially-branching shape
  // on cold blue is snow, whatever the tint is called. The lobed `bush_*` masses read as crumpled
  // sheet instead, which is what a bag on the bottom actually is. Same failure mode as the reef's
  // `leaf`-is-a-maple-leaf note one block down, found the same way.
  //
  // ⚠ AND THE TINTS ARE AUTHORED HOT. floorTint 0x93b6cc multiplies every prop, i.e. (0.58, 0.71,
  // 0.80) — it takes far more red than blue, so a tint that looks like dirty rope in a swatch lands
  // on screen GREEN. The first NET_TINTS (0x7a7460) came out as grass tufts on the ocean floor. Raw
  // red has to sit well above raw green here for the result to read warm-neutral.
  const BAG_TINTS = [0x8494a1, 0x76858f]        // collapsed plastic, colour long since bleached out
  const NET_TINTS = [0xa8875c, 0x96784f]        // lost monofilament and rope — hot, to land as tan
  const SILT_TINTS = [0x5b6f7e, 0x516574]       // settled sediment, the dullest thing on the floor
  const BIG_TRAWL = [
    // A bag that has come down and spread. `bush_b` is a lobed rosette — the reef reads it as a brain
    // coral head; from directly above, at this size and bleached, it is a sheet of plastic collapsed
    // over the bottom. Deliberately NOT upright: it is lying there, not standing.
    { name: 'bush_b', tints: BAG_TINTS, upright: false, size: [92, 140] },
    { name: 'bush_a', tints: SILT_TINTS, upright: false, size: [84, 130] },
  ]
  const MID_TRAWL = [
    { name: 'bush_a', tints: BAG_TINTS, upright: false, size: [48, 76] },
    { name: 'bush_b', tints: SILT_TINTS, upright: false, size: [44, 70] },
    // EVERYTHING HERE LIES DOWN. There is no upright member, which makes this the only biome in the
    // game with none, and it is the third thing a probe frame had to teach: this prop set is a garden
    // set, so ANY upright entry reads as a plant however it is tinted — `grass_c` came out as sea
    // grass and `flower_a` as budded stalks, on a floor whose whole premise is that nothing grows
    // here. Sunken litter lies on the bottom anyway, so the correct drawing and the available shapes
    // agree for once. The ochre stays as the only warm note among the bags and silt.
    { name: 'bush_a', tints: NET_TINTS, upright: false, size: [40, 62] },
    { name: 'bush_b', tints: NET_TINTS, upright: false, size: [36, 58] },
  ]
  const DETAIL_TRAWL = [
    // Marine snow on the bottom: the palest thing down here, but at low alpha so it stays grit rather
    // than becoming the brightest surface in a chapter whose roster has to win on value.
    { name: 'scatter_a', tint: 0xc6d3dc, alpha: 0.38, size: [20, 36] },
    { name: 'scatter_b', tint: 0xb0bfc9, alpha: 0.32, size: [17, 31] },
    { name: 'pebble', baked: true, scale: [0.6, 1.2] },
  ]
  const BIOME_TRAWL = {
    big: BIG_TRAWL, mid: MID_TRAWL, detail: DETAIL_TRAWL,
    // Unused today — CHAPTERS.trawl.obstacles is null, because open water is the point and there is
    // nothing to hide behind from a hazard that is not aiming at you. Declared anyway so the family
    // is complete: `obstacle` is read unconditionally by the obstacle bake, and a chapter that later
    // grows a wreck or a drum would otherwise crash rather than look wrong.
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x54606b, foot: 0x0d161f },
  }
  // ---- The Deep (v7.x) -------------------------------------------------------------------
  // A WRECK FIELD, and it inherits The Trawl's two hard-won rules wholesale, because this floor is
  // one measured stop further down the same descent:
  //   1. TINTS ARE AUTHORED HOT. floorTint multiplies (0.44, 0.56, 0.65 here — darker again than
  //      the Trawl's), and it takes far more red than blue, so anything that looks right in a
  //      swatch lands on screen green-grey. Raw red sits well above raw green in every entry below.
  //   2. NOTHING STANDS UP. The prop set is a garden set, so any `upright` member reads as a plant
  //      however it is tinted — and a plant on the abyssal floor, where there is no light at all to
  //      grow by, is a worse lie here than it was one chapter up.
  const HULL_TINTS = [0x8a6f5e, 0x7a6152]       // corroded steel: rust over grey, hot to land brown
  const DRUM_TINTS = [0x94815c, 0x827150]       // drums and containers — the last of the paint
  const OOZE_TINTS = [0x4a5a68, 0x41505d]       // abyssal ooze, dimmer than the Trawl's silt
  const BIG_DEEP = [
    // The hulls. Same lobed rosettes the Trawl bleaches into bags, but bigger and darker: from
    // directly overhead a broken hull section IS a large irregular plate lying on the bottom.
    { name: 'bush_b', tints: HULL_TINTS, upright: false, size: [110, 168] },
    { name: 'bush_a', tints: OOZE_TINTS, upright: false, size: [96, 150] },
  ]
  const MID_DEEP = [
    { name: 'bush_a', tints: DRUM_TINTS, upright: false, size: [52, 84] },
    { name: 'bush_b', tints: OOZE_TINTS, upright: false, size: [46, 74] },
    { name: 'bush_a', tints: HULL_TINTS, upright: false, size: [40, 66] },
  ]
  const DETAIL_DEEP = [
    // Marine snow again, but THINNER and dimmer than the Trawl's: less of it makes it this far down,
    // and the roster here has even less light to win against, so grit that reads as bright would be
    // the most visible thing in the chapter.
    { name: 'scatter_a', tint: 0xa8b6c2, alpha: 0.26, size: [18, 32] },
    { name: 'scatter_b', tint: 0x94a3b0, alpha: 0.22, size: [15, 28] },
    { name: 'pebble', baked: true, scale: [0.5, 1.0] },
  ]
  const BIOME_DEEP = {
    big: BIG_DEEP, mid: MID_DEEP, detail: DETAIL_DEEP,
    // Unlike The Trawl's, this one IS used: CHAPTERS.deep declares obstacles, because the wreck
    // field is the chapter's terrain and swimming between hulls is the fantasy.
    obstacle: { clumps: OBSTACLE_CLUMPS, tint: 0x6b5c4e, foot: 0x070c12 },
  }
  const BIOMES = {
    body: BIOME_BODY,
    pond: BIOME_POND,
    surf: BIOME_SURF,
    // v7.x Book 2 — open water, its own family now (see BIOME_SHELF above). Load-bearing, not
    // decorative: chapterBiome falls back to BIOMES.body for an unknown id, so without this line
    // The Shelf draws villi and platelets under a blue tint.
    shelf: BIOME_SHELF,
    // Load-bearing for the same reason as the line above it: a chapter with no BIOMES entry does not
    // throw and does not warn, it silently draws ANOTHER chapter's world (chapterBiome falls back to
    // BIOMES.body, which is how The Surf shipped villi, platelets and plasma motes on its beach).
    reef: BIOME_REEF,
    // Same load-bearing line as the three above it, and the failure is the loudest one yet: without
    // it The Trawl draws VILLI and PLATELETS on the bottom of the ocean, because chapterBiome falls
    // back to BIOMES.body for an unknown id and nothing throws.
    trawl: BIOME_TRAWL,
    // And again, for the fifth time in this book and the same silent failure: chapterBiome falls
    // back to BIOMES.body for an unknown id, so a missing line here does not throw and does not
    // warn — it draws VILLI AND PLATELETS on the abyssal plain.
    deep: BIOME_DEEP,
    garden: BIOME_GARDEN,
    undergrowth: {
      big: BIG_UNDERGROWTH, mid: MID_UNDERGROWTH, detail: DETAIL_UNDERGROWTH,
      // roots + bones: a knot of root arches with a bone half-buried in it
      obstacle: { baked: ['root', 'root', 'bone'], tint: 0xbfae86, foot: 0xffffff },
    },
    city: {
      big: BIG_CITY, mid: MID_CITY, detail: DETAIL_CITY,
      obstacle: { baked: ['dumpster', 'hydrant', 'cone'], tint: 0xd8d4cc, foot: 0x161a20 },
    },
    skies: {
      big: BIG_SKIES, mid: MID_SKIES, detail: DETAIL_SKIES,
      obstacle: { baked: ['rubble', 'rubble'], tint: 0xbfb8a8, foot: 0x38332b },
    },
    beyond: {
      big: BIG_BEYOND, mid: MID_BEYOND, detail: DETAIL_BEYOND,
      // v5.18: `planet` swaps in a dedicated sphere bake AND hides the footprint ring (see the
      // planet branch in syncObstacles). v5.20: that bake became SEVEN archetypes — gas giant, moon,
      // ice, molten, ocean, night side, ringed — chosen per obstacle by position hash in the skin
      // cache, so `planet: true` now means "pick from PLANET_ARCHETYPES", not one fixed texture.
      // That ring is documented as the COLLISION CONTRACT —
      // "this stops me, learned by eye" — and in the lane it stops nothing: stepObstacles skips this
      // chapter entirely now, so a 36px-wide contract ring around a body you fly straight past would
      // be the art telling a lie the sim doesn't back. `foot` stays a real colour because the skin
      // cache tint-multiplies it unconditionally; the ring is hidden by alpha, not by a null.
      obstacle: { baked: ['asteroid', 'asteroid'], planet: true, tint: 0xcfc8e0, foot: 0x8f86b8 },
    },
  }
  chapterBiome = BIOMES.body // title-screen default; reset(run) latches the run's chapter

  // ---- district biomes (skies chapter only, v5.7.x piece 4) ----------------------------------
  // Same {big, mid, detail, obstacle} shape as BIOMES above, keyed by DISTRICTS type (config.js)
  // instead of chapter id — syncObstacles and the floor populate* callbacks pick one of these BY
  // WORLD POSITION (districtAt) instead of chapterBiome when chapterHasDistricts. downtown reuses
  // the chapter's original look unchanged; parks/sea lean on existing foliage/puddle/streak
  // assets re-tinted for the storm night; suburbs is the one hand-drawn set (house/fence baked
  // above — its car reuses T.car, already drawn for the city's traffic lanes, so no second car
  // gets drawn).
  // v5.8 kaiju redesign: `obstacle` here now supplies ONLY the PALETTE (tint/foot) for a district's
  // structures — the SHAPE is o.kind (config.js STRUCTURE_KINDS: 'tower'/'house'/'tree'/'pier'),
  // looked up in STRUCTURE_SKINS right after this table. kind is independent of district (sim.js
  // derives it from its own hash salt, not from districtAt — design doc §2/§5), so it does NOT
  // track 1:1 with whichever district an obstacle happens to land in; syncObstacles combines the
  // two — this table's tint/foot at the obstacle's world position, STRUCTURE_SKINS' silhouette
  // for its kind.
  const PARK_TINTS = [0x3f5a3a, 0x32492e]        // dark hedge/tree-clump green — the daylight
  const PARK_GRASS_TINTS = [0x4a6640, 0x3d5636]  // BUSH_TINTS/GRASS_TINTS would wash out on a dark floor
  const BIG_PARKS = [
    { name: 'bush_a', tints: PARK_TINTS, upright: true, size: [110, 175] }, // tree clumps, bigger than the garden's hedges
    { name: 'root', baked: true, upright: true, size: PROP_SCALE.tree },   // a gnarled trunk/roots poking up
  ]
  const MID_PARKS = [
    { name: 'bush_b', tints: PARK_TINTS, upright: true, size: [70, 110] }, // hedges
    { name: 'grass_c', tints: PARK_GRASS_TINTS, upright: true, size: [30, 52] },
    { name: 'reed', tints: PARK_GRASS_TINTS, upright: true, size: [45, 70] },
  ]
  const DETAIL_PARKS = [
    { name: 'grass_d', tints: PARK_GRASS_TINTS, upright: true, size: [22, 38] },
    { name: 'leaf', tint: 0x3a4f34, alpha: 0.6, size: [18, 32] },
    { name: 'pebble', baked: true, size: PROP_SCALE.debris },
  ]
  // v5.9 top-down region overhaul: every baked prop below is sized off PROP_SCALE (config.js) via
  // applyPropKind's `size` path, not `scale` — see that function's doc comment for the "car bigger
  // than house" bug this replaces. car appears in BOTH big and mid at the SAME absolute band
  // (PROP_SCALE.car): unlike the old scale-multiplier system, "which layer" no longer implies "how
  // big" — it only changes how OFTEN a cell rolls a car vs. a house/fence (see FLOOR_LAYERS' cell/
  // chance per layer), which is exactly the density knob item 5 asked for.
  // v5.10: the side-view T.house/T.fence floor props are gone from suburbs. The crushable
  // structures now ARE detailed top-down houses with their whole lot (driveway, lawn or pool,
  // hedge L, shed, deck, bins) baked into the same texture, so scattering a second, cruder house
  // silhouette next to them is what made the district read as a wireframe suburb.
  const BIG_SUBURBS = [
    { name: 'hedgeSeam', baked: true, size: PROP_SCALE.hedge },
    ...SKIES_CARS,
  ]
  const MID_SUBURBS = [
    { name: 'hedgeSeam', baked: true, size: PROP_SCALE.hedge },
    ...SKIES_CARS,
  ]
  const DETAIL_SUBURBS = [
    { name: 'pebble', baked: true, size: PROP_SCALE.debris },
    { name: 'scatter_a', tint: 0xd8c9a0, alpha: 0.4, size: [20, 34] },
  ]
  // sea's puddle/foam stay `scale`-based, deliberately: they're a WATER/TERRAIN feature (open water,
  // breaking-wave lines), not one of PROP_SCALE's enumerated prop classes (crop/debris/car/fence/
  // hedge/tree/house/pier/barn/silo/tower) — there's no absolute band for them to pull from, and no
  // ordering-invariant claim to honour ("reused at landmark scale" is the intended read, not a bug).
  const SEA_FOAM_TINTS = [0x9fd0ea, 0xbfe6f7] // pale foam-white/cyan, darkened by the sea floorTint multiply
  // v5.10 (spec §4.5, kill list §8.6): T.foam was `T.fx.trace_05` — the sea's breaking wave WAS the
  // pond's current-streak sprite, reused a third time by populateEdge for coastlines. T.waveCrest
  // is a real crest (two parallel arcs + a foam speckle band). The container yard is the district's
  // signature: tiny dense SATURATED rectangles against dark water, `litTint` so the floor tint
  // can't turn a shipping line's red into grey.
  // containerYard is listed twice on purpose: SKIES_FLOOR_KEEP thins the `big` layer to 22%, so a
  // single entry among three put a yard on screen roughly never and the district read as empty
  // water. litTint everywhere here — foam that inherits the sea's own floorTint is invisible
  // against the sea, which is exactly how T.foam managed to hide for two versions.
  const BIG_SEA = [
    { name: 'puddle', baked: true, scale: [3.2, 5.5] }, // the puddle prop's own blue, reused at landmark scale — open water
    { name: 'containerYard', baked: true, litTint: true, size: [170, 210] },
    { name: 'containerYard', baked: true, litTint: true, size: [150, 190] },
    { name: 'riprap', baked: true, litTint: true, size: [150, 190] },
  ]
  const MID_SEA = [
    { name: 'waveCrest', baked: true, litTint: true, tint: SEA_FOAM_TINTS[0], alpha: 0.75, size: [70, 120] },
    { name: 'waveCrest', baked: true, litTint: true, tint: SEA_FOAM_TINTS[1], alpha: 0.6, size: [90, 140] },
    { name: 'puddle', baked: true, scale: [1.4, 2.4] },
  ]
  const DETAIL_SEA = [
    { name: 'waveCrest', baked: true, litTint: true, tint: SEA_FOAM_TINTS[1], alpha: 0.55, size: [40, 70] },
  ]
  // // ponytail: sea's "waves" are static per-cell foam scatter (the CURRENT_VIS/rain streak
  // texture, reused as a floor prop), not a moving wave-advection layer — upgrade to a proper
  // pooled foam-streak system (CURRENT_VIS idiom) if flat/static water reads badly in playtesting.

  // ---- farms district (skies, v5.9 top-down region overhaul) ---------------------------------
  // The headline "more crops" ask: cultivated fields read as top-down ONLY as regular parallel
  // rows, which farmRowSnap (above, near applyPropKind) provides — cropTuft is the one prop in this
  // file with `cropRow: true`. It appears in BOTH mid and detail (two independent cell grids
  // sampled at different phases/frequencies) so rows read as continuous furrows, not a sparse
  // dotted line. big carries the landmark farm furniture — barn/silo (new baked art; STRUCTURE_
  // SKINS below reuses the SAME textures for the crushable buildings, PROP_SCALE-sized there too)
  // plus the odd tractor (T.tractor, pegged to PROP_SCALE.car's band — a working vehicle, same
  // tier as a parked car, not worth its own PROP_SCALE class).
  // v5.11: darkened from [0xd9c76a, 0x8a9a4a, 0x6b5a3a] — bare, they were the brightest, flattest
  // thing on screen, out-shouting the (much darker, night-lit) buildings and searchlights. Same
  // hues, brought down in value; T.cropTuft's own bake (above) adds the actual furrow texture.
  const CROP_TINTS = [0x988b4a, 0x687438, 0x5b4d31] // golden wheat / green leaf-row / tilled-brown row
  // v5.10: the side-view T.barn/T.silo floor props are gone (the crushable structures carry the
  // real top-down plans now). What replaces them is the OTHER instantly-recognisable overhead farm
  // shape — a centre-pivot irrigation circle. A perfect circle in a field of straight rows is
  // unmistakable, and it exists nowhere else in the region.
  const BIG_FARMS = [
    { name: 'pivotCircle', baked: true, size: [340, 460] },
    { name: 'tractor', baked: true, alignRoad: true, size: PROP_SCALE.car },
  ]
  const MID_FARMS = [
    // v5.11: the two cropTuft entries that stood here are GONE, along with the one in DETAIL_FARMS.
    // They scattered individual crop strokes across the field on top of the furrows baked into
    // T.districtGround.farms — two independent hatchings over the same ground, which together are
    // what the playtest report saw as "white lines crossing everything". Rows are now part of the
    // parcel tile itself (T.terrainTile.farms), drawn once, at the field's own scale, and bounded by
    // the field's headland. A field does not need props sprinkled on it to look cultivated.
    { name: 'wallSeam', baked: true, size: PROP_SCALE.fence },             // dry-stone field boundary
    { name: 'hayBale', baked: true, size: [32, 42] },                      // not an enumerated PROP_SCALE class — pegged to the fence/hedge tier by eye
  ]
  const DETAIL_FARMS = [
    { name: 'pebble', baked: true, size: PROP_SCALE.debris },
  ]

  // ---- hills district (skies, v5.9 top-down region overhaul) ---------------------------------
  // Elevation from directly overhead reads as soft contour shading (T.contour above), never a
  // side-view hill silhouette — see that bake's own doc for why. Scattered trees reuse T.root at
  // PROP_SCALE.tree, the same class/size as the parks district's trunk accent.
  // Boulders (v5.9.1 art experiment): T.voxelRockA/B/C (baked above, right after T.rockChunk) —
  // three faux-voxel silhouettes, PROP_SCALE-sized like every other discrete object in these
  // district tables (tree for the big landmark tier, fence for mid, debris for scattered detail —
  // all three bands already fit, no new PROP_SCALE class needed). `upright: true` here is NOT about
  // footing (a boulder is mass-centred, not base-anchored) — it's the only lever applyPropKind has
  // for "small rotation jitter, not a full spin," which these need to keep every cube's baked
  // shading pointing the same way across the whole field (see the bake's own comment for why a
  // full-spin rotation would break that). contour stays `scale`-based like sea's puddle above — it
  // isn't an enumerated PROP_SCALE class (a soft translucent contour patch doesn't compete in the
  // car/house/tower size hierarchy the way a discrete built object does).
  const BIG_HILLS = [
    { name: 'contour', baked: true, scale: [1.3, 2.1] },
    { name: 'switchback', baked: true, size: [190, 250] }, // v5.10: the one man-made line in open
                                                           // moorland — a zigzag is the only shape
                                                           // that says "slope" to a camera with no
                                                           // horizon (spec §4.5)
    { name: 'voxelRockA', baked: true, upright: true, size: PROP_SCALE.tree },
    { name: 'voxelRockB', baked: true, upright: true, size: PROP_SCALE.tree },
  ]
  const MID_HILLS = [
    { name: 'contour', baked: true, scale: [0.7, 1.2] },
    { name: 'voxelRockB', baked: true, upright: true, size: PROP_SCALE.fence },
    { name: 'voxelRockC', baked: true, upright: true, size: PROP_SCALE.fence },
    { name: 'grass_c', tints: PARK_GRASS_TINTS, upright: true, size: [28, 46] },
  ]
  const DETAIL_HILLS = [
    { name: 'voxelRockC', baked: true, upright: true, size: PROP_SCALE.debris },
    { name: 'grass_d', tints: PARK_GRASS_TINTS, upright: true, size: [20, 34] },
  ]

  const DISTRICT_BIOMES = {
    downtown: BIOMES.skies, // unchanged: the chapter's original tall shattered-building rubble
    suburbs: {
      big: BIG_SUBURBS, mid: MID_SUBURBS, detail: DETAIL_SUBURBS,
      obstacle: { tint: 0xcfc0a0, foot: 0x2e2418 },
    },
    parks: {
      big: BIG_PARKS, mid: MID_PARKS, detail: DETAIL_PARKS,
      obstacle: { tint: 0x3f5a3a, foot: 0x1c2a18 },
    },
    sea: {
      big: BIG_SEA, mid: MID_SEA, detail: DETAIL_SEA,
      // v5.8 kaiju redesign: sea's obstacles used to be a plain rock (visual-only placeholder);
      // now they're real crushable dock furniture (STRUCTURE_SKINS.pier, T.jetty/T.boat/T.buoy
      // baked above). Still no swim/slow here — that would be a sim change, out of scope.
      obstacle: { tint: 0x8fa0ac, foot: 0xdaf3ff },
    },
    farms: {
      big: BIG_FARMS, mid: MID_FARMS, detail: DETAIL_FARMS,
      obstacle: { tint: 0xb8a860, foot: 0x2e2712 },
    },
    hills: {
      big: BIG_HILLS, mid: MID_HILLS, detail: DETAIL_HILLS,
      // v5.9.2: hills' structures still roll kind='tree' (config.js DISTRICT_STRUCTURE_KINDS —
      // growing a real 7th kind needs test/sim-test.js's run DD.d, which pins STRUCTURE_KINDS at
      // exactly 6, updated by whoever owns test/), but syncObstacles below special-cases exactly
      // this district to draw STRUCTURE_SKINS.rock instead of 'tree''s usual foliage clump — see
      // that override's own comment. This palette (a stony taupe) still applies either way.
      obstacle: { tint: 0x8a7a62, foot: 0x2e2a20 },
    },
    // v5.11 biomes. Neither gets a bespoke prop set: what defines both is EMPTINESS, and the
    // parcel/dune/swash texture is already in the terrain tile. Desert borrows the hills scatter
    // (boulders and debris are exactly right for a stony arid plain) at a twelfth the build density
    // (BIOME_BUILD_DENSITY, terrain.js); beach borrows sea's shoreline furniture, which is what a
    // beach has on it. Reusing these tables is the correct call rather than a shortcut — inventing
    // two more prop sets would add clutter to the two biomes whose whole job is to be bare.
    desert: {
      big: BIG_HILLS, mid: MID_HILLS, detail: DETAIL_HILLS,
      obstacle: { tint: 0xb09872, foot: 0x35291a },
    },
    beach: {
      big: BIG_SEA, mid: MID_SEA, detail: DETAIL_SEA,
      obstacle: { tint: 0xb0a482, foot: 0x33301f },
    },
  }
  // Structure silhouette per o.kind (v5.8 kaiju redesign, config.js STRUCTURE_KINDS; barn/silo added
  // v5.9): the district table above supplies the PALETTE, this supplies the SHAPE — see its doc
  // comment. Same {baked}/{clumps} shapes syncObstacles already knew how to draw (BIOMES/
  // DISTRICT_BIOMES' `obstacle` used to carry both in one object; kind splits them so a suburb can
  // have a park's stray tree and vice versa, matching the fact that kind and district roll
  // independently).
  //   tower — today's shattered-rubble pair, unchanged (the design doc calls it "a fine starting
  //           point"; downtown's original obstacle look already looked like a small ruin).
  //   house — the suburbs' own hand-drawn house, baked twice: a plain low pitched-roof silhouette
  //           doesn't need a second distinct prop the way tower's rubble pairing does.
  //   tree  — the same OBSTACLE_CLUMPS foliage-mound idiom every organic obstacle already uses
  //           (garden's bushes, the old parks obstacle) — no new art needed for "a park tree/hedge".
  //   pier  — new baked art (jetty/boat/buoy above), for the sea district's dock furniture.
  //   barn/silo — new baked art (above), for the farms district's crushable buildings.
  //   rock  — v5.9.2: the faux-voxel boulder trio (T.voxelRockA/B/C, already baked for the hills
  //           FLOOR layers above), reused as a crushable structure. NOT one of o.kind's own values
  //           (STRUCTURE_KINDS stays at 6 — see this table's own header) — syncObstacles substitutes
  //           it in for kind='tree' obstacles specifically in the hills district, so hills reads as
  //           rocky high ground instead of sharing 'tree''s forest-clump silhouette with parks (the
  //           "the fuck is this?" bug report: the two districts used to render identically).
  // v5.10 art direction (spec §5): every entry now points at a TOP-DOWN PLAN baked by
  // buildSkiesTextures (T.skTower*/skHouse*/skBarn/skSilo/skPier/skTree/skOutcrop), replacing the
  // side-view, base-anchored bakes that a top-down camera could only ever render as "a box plus a
  // triangle". `topDown: true` is read by syncObstacles: the plan is MASS-CENTRED at (0,0) rather
  // than planted at (0, o.r*0.28), it is NOT re-tinted by the district palette (these carry their
  // own night palette, including palette-law-1 lit windows that a tint multiply would turn to mud),
  // and clumpB is suppressed — the lot/paddock/yard detail is baked INTO the same texture, because
  // a driveway that doesn't touch its house is worse than no driveway.
  // This also closes kill-list items §8.7 (hills' crushable structures were the hills FLOOR-DECOR
  // boulders at a bigger scale) and §8.8 (downtown's landmark building was literally the generic
  // rubble prop, which is also downtown's floor debris).
  const STRUCTURE_SKINS = {
    tower: { baked: ['skTowerA', 'skTowerB', 'skTowerC', 'skTowerD', 'skTowerE'], topDown: true },
    house: { baked: ['skHouseA', 'skHouseB'], topDown: true },
    tree: { baked: ['skTree', 'skTree'], topDown: true },
    pier: { baked: ['skPier', 'skPier'], topDown: true },
    barn: { baked: ['skBarn', 'skBarn'], topDown: true },
    silo: { baked: ['skSilo', 'skSilo'], topDown: true },
    rock: { baked: ['skOutcrop', 'skOutcrop'], topDown: true }, // hills override only — see comment above and syncObstacles
  }
  // Which ruin bake a crushed structure leaves behind, by o.kind (SKIES_RUIN, spec §5.9). 'rock'
  // is the hills override above, and reuses tree's stump-and-splinter ruin. v6.3: city's cover-crush
  // forces kind 'dumpster' (sim.js stepLanes) — no dedicated ruin bake exists for it, so it is
  // absent here on purpose and falls through to the `|| 'tower'` default at both call sites
  // (ledgerAdd below, updateRuins' T.skRuin lookup) — angular concrete rubble is the closest
  // neutral stand-in for a smashed steel bin, and it costs zero new art.
  const RUIN_FOR_KIND = { tower: 'tower', house: 'house', barn: 'barn', silo: 'silo', pier: 'pier', tree: 'tree', rock: 'tree' }

  // ---- roads (skies only) ----------------------------------------------------------------------
  // A street is ONE STRIP, not a chain of stamps. Until v6.9.1 this was a per-cell FLOOR_LAYERS
  // layer: every 26px floor cell whose centre landed on tarmac stamped a short rotated quad, sliding
  // itself onto the centreline by asking roadAt again 4px to one side and seeing whether `dist` had
  // shrunk. That probe is wrong for every cell within 4px of the centreline — the probe crosses the
  // line, `dist` does not shrink, and the quad is placed 2*dist off. On a 30px street the result was
  // a visible sideways jog every few stamps, a kerb that doubled and thinned along its own length,
  // and a dash pattern whose pitch was whatever the square cell lattice happened to project onto an
  // oblique street. That is the reported "roads are ugly, sometimes aliasing, not straight".
  //
  // Now the geometry comes from the generator instead of being rediscovered from it: streets are
  // enumerated in their own city's rotated frame (exactly as updateJunctions already does), highways
  // straight off terrain.js's segment list, and each RUN of continuous carriageway gets a single
  // TilingSprite of the true-world-size tile baked above. One sprite per street per view instead of
  // several hundred quads, perfectly straight by construction, and the dash pattern is phase-locked
  // to the city's own along-street coordinate so it never doubles or skips.
  //
  // The march is still needed, and is the only reason this is not just "draw the whole line": a
  // street stops at the urban falloff and at water (roadAt owns both rules), so a run has to be cut
  // where roadAt stops answering. STREET_MARCH is the sampling pitch of that cut — coarse enough to
  // be cheap, fine enough that a kerb never overshoots a coastline by more than its own width.
  const STREET_MARCH = ROAD_MINOR_WIDTH
  // The unit normal to a road running at heading `angle`: the heading is (cos, sin), so the LEFT
  // normal is (-sin, cos). roadAt's `off` is signed along exactly this vector.
  function roadPerp(angle) { return { x: -Math.sin(angle), y: Math.cos(angle) } }

  // ---- MAP MODE (v5.12, dev/debug) -------------------------------------------------------------
  // Renders the world zoomed OUT, with the player, enemies, projectiles and weather hidden, so the
  // procedural layout can be inspected over a wide area as a layout rather than judged through a
  // gameplay viewport. Screenshotting the game as it plays shows roughly one city block, which is
  // far too small a window to see whether a coastline is straight, whether blocks agree with their
  // streets, or whether a road network goes anywhere — every one of those is a property of an area
  // several thousand px across.
  //
  // The whole mechanism is `mapZoom` plus ONE rule: every culling test in this file measures the
  // viewport in WORLD px (viewW/viewH), never in screen px. At zoom 1 those are identical, so
  // normal play is bit-identical to before; at zoom 0.2 the same code streams five times as much
  // world into the same canvas. The camera then applies the zoom once, in sync().
  let mapZoom = 1
  let mapMode = false
  const viewW = () => app.screen.width / mapZoom
  const viewH = () => app.screen.height / mapZoom




  // Which way does the nearest street run at (wx, wy)? Used to align parked vehicles and painted
  // lots to the grid. Answers in the nearest city's frame; 0 outside any city, where there is no
  // grid to align to and the caller's own jitter is the whole answer.
  function nearestStreetAngle(wx, wy) {
    if (!chapterHasRoads) return 0
    const ra = roadAt(wx, wy, roadSeed, chapterEndlessGrid)
    if (ra.onRoad) return ra.angle
    return 0   // v6.9.2: off-road inside a city, the grid is the world's and runs on the axes
  }

  // ---- street strips (v6.9.1) -------------------------------------------------------------------
  // Rebuilt only when the camera leaves its 48px bucket: the strips are WORLD-space and the world
  // container is what the camera moves, so a set built with STREET_PAD of slack stays correct for
  // every frame in between. Without that gate this would re-march every visible street every frame,
  // and the march is the only expensive part (roadAt samples elevation and river noise).
  const STREET_PAD = 200
  // Hard ceiling on strips per rebuild. Gameplay uses ~50; the cap only ever bites in MAP MODE,
  // where the viewport is several thousand px across, and it bounds the MARCH as well as the pool
  // (a full pool with an unbounded march would still burn every roadAt sample it was never going to
  // draw). A truncated map view loses distant streets, which is the correct thing to lose.
  const STREET_MAX = 220
  const streetSprites = []
  let streetKey = ''
  function acquireStreet() {
    const s = new TilingSprite({ texture: Texture.EMPTY, width: 1, height: 1 })
    s.anchor.set(0, 0.5)   // origin at the run's START, mid-carriageway
    roadLayer.addChild(s)
    streetSprites.push(s)
    return s
  }

  function updateStreets(cx, cy) {
    const key = chapterHasRoads
      ? roadSeed + '|' + mapZoom + '|' + Math.round(cx / 48) + '|' + Math.round(cy / 48)
      : 'off'
    if (key === streetKey) return
    streetKey = key
    let n = 0
    // One strip for the stretch of `look`-class carriageway from along-coordinate a0 to a1 on the
    // line through (ox, oy) heading `ang`. `phase` is the run start's along-coordinate in the road's
    // OWN frame (the city's v/u axis, or distance from a highway's first endpoint), which is what
    // keeps the dash pattern continuous across two runs split by a river.
    const strip = (ox, oy, ang, a0, a1, phase, look, alpha = 1) => {
      if (a1 - a0 < 1 || n >= STREET_MAX) return
      const s = streetSprites[n] || acquireStreet()
      n++
      s.visible = true
      s.alpha = alpha
      s.texture = look.tex
      s.width = a1 - a0
      s.height = look.w
      s.rotation = ang
      s.position.set(ox + Math.cos(ang) * a0, oy + Math.sin(ang) * a0)
      const p = ROAD_PAINT.tilePitch
      s.tilePosition.set(-(((phase % p) + p) % p), 0)
    }
    // Two short strips of falling alpha running AWAY from a road's hard end, so the carriageway
    // fades out instead of stopping square. dir is +1 past the far end, -1 before the near one.
    const TAPER = [[90, 0.55], [90, 0.22]]
    const taper = (ox, oy, ang, at, dir, look) => {
      let edge = at
      for (const [len, alpha] of TAPER) {
        const lo = dir > 0 ? edge : edge - len
        strip(ox, oy, ang, lo, lo + len, lo, look, alpha)
        edge += dir * len
      }
    }

    // March the line and cut it wherever roadAt stops answering `kind` — that is where the urban
    // falloff or the water rule ends the street. Runs are extended half a step at each end so a
    // kerb never visibly stops short of the last sample that was still on tarmac.
    // The HEADING test survives from v6.9.1, when overlapping cities each had their own rotated grid
    // and enumerating one city's lines while standing in another produced stray stubs. The world
    // grid makes that impossible, but the test is still the cheap way to stop a street run from
    // continuing through a stretch a WIDER road has taken over (a highway leg outranks a street).
    const march = (ox, oy, ang, a0, a1, kind, look) => {
      const dx = Math.cos(ang), dy = Math.sin(ang)
      // softStart tracks whether the stretch BEFORE the current run was owned by a wider road
      // (soft — no taper needed, that road draws it) or was nothing at all (hard). Starts true: the
      // first sample sits at the view edge, and running out of view is not a road end.
      let start = null, last = 0, softStart = true
      const flush = (soft) => {
        const s0 = start - STREET_MARCH / 2, s1 = last + STREET_MARCH / 2
        strip(ox, oy, ang, s0, s1, s0, look)
        // TAPER (v6.9.3, owner: "thats weird, road just stops"). A street ends where roadAt stops
        // answering, which at the edge of a city is correct and deliberate — a grid that ran exactly
        // to its own boundary would read as a stamped rectangle. What was wrong is HOW it ended: a
        // 210px avenue stopping dead in open ground with a square butt. Two short strips of falling
        // alpha past each hard end read as the paving petering out into a track, which is what
        // leaving a town actually looks like.
        // Only at a HARD end (no road there at all). An end where a highway took over is already
        // covered by that highway's own strip, and fading into it would just dirty the join.
        if (!soft) taper(ox, oy, ang, s1, 1, look)
        if (!softStart) taper(ox, oy, ang, s0, -1, look)
        start = null
      }
      for (let a = a0; a <= a1 + STREET_MARCH && n < STREET_MAX; a += STREET_MARCH) {
        const r = a <= a1 ? roadAt(ox + dx * a, oy + dy * a, roadSeed, chapterEndlessGrid) : { onRoad: false }
        if (r.onRoad && r.kind === kind && Math.abs(Math.cos(r.angle - ang)) > 0.999) {
          if (start === null) start = a   // softStart already holds the previous sample's verdict
          last = a
        } else if (start !== null) {
          flush(r.onRoad)   // r.onRoad here means a WIDER road owns this stretch, not "nothing"
        } else {
          softStart = r.onRoad
        }
      }
      if (start !== null) flush(true)   // ran off the end of the view, not off the end of the road
    }
    if (chapterHasRoads) {
      const w = viewW(), h = viewH()
      const x0 = -cx - STREET_PAD, y0 = -cy - STREET_PAD
      const x1 = -cx + w + STREET_PAD, y1 = -cy + h + STREET_PAD
      const E = STREET_SPACING_MAJOR_EVERY
      // v6.9.2: ONE world grid, axis-aligned — no city frames to enumerate in, so a street is just
      // a line at x = ui*BLOCK_U or y = vi*BLOCK_V. These are the exact indices roadAt itself uses,
      // so the line drawn IS the line the generator answers on.
      // The along-range is passed in ABSOLUTE WORLD COORDINATES and snapped to STREET_MARCH, which
      // is what stops the roads flickering (v6.9.3, owner: "roads flicker and sometimes disappear
      // when i move near it"). march() samples every STREET_MARCH px from a0; when a0 was the view's
      // own edge, the sample POSITIONS slid with the camera, so a run's ends jumped up to a full
      // 130px march every time the camera crossed a rebuild bucket — and a run only one sample long
      // blinked in and out entirely depending on where the samples happened to land. Snapping a0/a1
      // to the world grid makes the sample set a property of the WORLD, so two rebuilds at different
      // camera positions produce byte-identical strips.
      const snapLo = (v) => Math.floor(v / STREET_MARCH) * STREET_MARCH
      const snapHi = (v) => Math.ceil(v / STREET_MARCH) * STREET_MARCH
      // A vertical street runs at PI/2, so from origin (X, 0) the along-coordinate IS the world y;
      // a horizontal one runs at 0, so from (0, Y) it is the world x. That is what lets the snap
      // above be expressed in world units at all.
      for (let ui = Math.ceil(x0 / BLOCK_U); ui * BLOCK_U <= x1; ui++) {
        const major = ((ui % E) + E) % E === 0
        march(ui * BLOCK_U, 0, Math.PI / 2, snapLo(y0), snapHi(y1), 'street', major ? T.roadMajor : T.roadMinor)
      }
      for (let vi = Math.ceil(y0 / BLOCK_V); vi * BLOCK_V <= y1; vi++) {
        const major = ((vi % E) + E) % E === 0
        march(0, vi * BLOCK_V, 0, snapLo(x0), snapHi(x1), 'street', major ? T.roadMajor : T.roadMinor)
      }
      // Highways are straight segments between two city centres and are deliberately exempt from the
      // water rule (a trunk road on a causeway is real), so they need no march at all — just the
      // stretch of each segment the view can see. Enumerated from the view's corners as well as its
      // centre because map mode's viewport is wider than one CITY_GRID cell.
      const segs = new Map()
      for (const [px, py] of [[(x0 + x1) / 2, (y0 + y1) / 2], [x0, y0], [x1, y0], [x0, y1], [x1, y1]]) {
        for (const s of highwaysNear(Math.floor(px / CITY_GRID), Math.floor(py / CITY_GRID), roadSeed)) {
          segs.set(s.ax + ',' + s.ay + ',' + s.bx + ',' + s.by, s)
        }
      }
      for (const s of segs.values()) {
        const ang = Math.atan2(s.by - s.ay, s.bx - s.ax)
        const len = Math.hypot(s.bx - s.ax, s.by - s.ay)
        const dx = Math.cos(ang), dy = Math.sin(ang)
        let a0 = Infinity, a1 = -Infinity
        for (const [px, py] of [[x0, y0], [x1, y0], [x0, y1], [x1, y1]]) {
          const a = (px - s.ax) * dx + (py - s.ay) * dy
          if (a < a0) a0 = a
          if (a > a1) a1 = a
        }
        a0 = Math.max(0, Math.floor((a0 - STREET_PAD) / STREET_MARCH) * STREET_MARCH)
        a1 = Math.min(len, Math.ceil((a1 + STREET_PAD) / STREET_MARCH) * STREET_MARCH)
        strip(s.ax, s.ay, ang, a0, a1, a0, T.roadHighway)
      }
    }
    for (let i = n; i < streetSprites.length; i++) streetSprites[i].visible = false
  }

  // ---- road decals (v5.10, spec §4.2) ---------------------------------------------------------
  // "VARIATION ALONG A STREET IS WHAT STOPS A ROAD READING AS A WIREFRAME; one stamped tile
  // repeated forever is what got us here." Anything with a SHAPE cannot live in the carriageway
  // tile — that tile is stamped at a non-uniform scale (x 0.48, y 0.34 minor / 0.62 major), so a
  // baked circle comes out an oval and by a DIFFERENT amount on an avenue than on a side street.
  // These are separate, uniformly-scaled sprites on their own 160px cell: one decal per cell,
  // picked by cellHash, self-gating on roadAt the way the carriageway layer used to before
  // updateStreets replaced it.
  function populateRoadDecal(s, i, j, cell) {
    if (!chapterHasRoads) { s.visible = false; return }
    const wx = (i + 0.5) * cell, wy = (j + 0.5) * cell
    const ra = roadAt(wx, wy, roadSeed, chapterEndlessGrid)
    if (!ra.onRoad) { s.visible = false; return }
    // roadAt's `off` IS the signed distance along `perp`, so the centreline point is exact — no
    // probe, and in particular no 8px misplacement for a decal that happens to land near the line.
    const perp = roadPerp(ra.angle)
    const cx = wx - perp.x * ra.off
    const cy = wy - perp.y * ra.off
    const along = { x: Math.cos(ra.angle), y: Math.sin(ra.angle) }
    const pick = ['manhole', 'patch', 'drain', 'arrow'][Math.floor(cellHash(i, j, 21) * 4)]
    const slide = (cellHash(i, j, 22) - 0.5) * cell * 0.7
    let look = T.rdManhole, across = 0, rot = 0, alpha = 1
    if (pick === 'manhole') { across = (cellHash(i, j, 23) - 0.5) * ra.half * 1.1 }
    else if (pick === 'patch') { look = T.rdPatch; across = (cellHash(i, j, 23) - 0.5) * ra.half * 1.3; rot = cellHash(i, j, 24) * Math.PI }
    else if (pick === 'drain') { look = T.rdDrain; across = (cellHash(i, j, 23) > 0.5 ? 1 : -1) * (ra.half - 3); rot = ra.angle }
    else { look = T.rdArrow; rot = ra.angle; alpha = 1; across = ra.major ? (cellHash(i, j, 23) > 0.5 ? 1 : -1) * ra.half * 0.45 : 0 }
    s.visible = true
    s.texture = look.tex
    s.anchor.set(look.ax, look.ay)
    s.tint = 0xffffff
    s.alpha = alpha
    s.rotation = rot
    s.scale.set(1)   // baked at TRUE world size — never scaled, which is the whole point
    s.position.set(cx + along.x * slide + perp.x * across, cy + along.y * slide + perp.y * across)
  }

  // ---- extra urban clutter (skies only, v5.9 top-down region overhaul, item 5) ----------------
  // FLOOR_LAYERS' cell/chance are shared by every chapter, so raising them would raise density
  // everywhere, not just skies' cities — out of bounds for a one-file, one-chapter pass. This adds
  // a SEPARATE, self-gated layer instead (same "predicate populate, no-op elsewhere" trick roads
  // use above): extra small furniture for downtown/suburbs/parks only, on its own cell grid so it's
  // genuinely additional instances, not a reshuffle of the existing mid/detail counts. No new art —
  // pure reuse. Cell 150 keeps the per-frame cost in the same ballpark as the existing detail layer
  // (cell 120) rather than the much finer road layer above.
  const CLUTTER_BY_DISTRICT = {
    downtown: [
      { name: 'rubble', baked: true, upright: true, size: PROP_SCALE.debris },
      ...SKIES_CARS,
    ],
    suburbs: [
      { name: 'hedgeSeam', baked: true, size: PROP_SCALE.hedge },
      ...SKIES_CARS,
    ],
    parks: [{ name: 'bush_b', tints: PARK_TINTS, upright: true, size: [55, 90] }],
  }
  function populateClutter(s, i, j, cell) {
    if (chapterIsVoid || !chapterHasDistricts) { s.visible = false; return }
    // v5.12 BUGFIX: this layer had NO JITTER AT ALL — every prop sat exactly on its cell centre, on a
    // 150px lattice, at chance 1.00. This layer draws the tree canopy, so every wood in the world
    // came out as a perfect square orchard of identical discs (measured: autocorrelation peaks at
    // exactly 150 world px on both axes, 98% cell occupancy). The other three scatter layers have
    // had this offset since v5.4; clutter was simply missed. Salts 12/13 — 1 is the kind pick above
    // and 4/5 belong to applyPropKind.
    const jx = (cellHash(i, j, 12) - 0.5) * cell * 0.9
    const jy = (cellHash(i, j, 13) - 0.5) * cell * 0.9
    const wx = (i + 0.5) * cell + jx, wy = (j + 0.5) * cell + jy
    if (onCarriageway(wx, wy)) { s.visible = false; return }
    const kinds = CLUTTER_BY_DISTRICT[districtAt(wx, wy, districtSeed)]
    if (!kinds) { s.visible = false; return }
    const kind = kinds[Math.floor(cellHash(i, j, 1) * kinds.length)]
    const pos = applyPropKind(s, kind, i, j, wx, wy)
    s.position.set(pos.x, pos.y)
  }

  // ---- district borders (skies only, v5.9.1 render fix) ---------------------------------------
  // "a coastline or a field edge wants to read as an edge" (playtest report) — districtTintAt
  // (config.js) already lerps the floor colour across DISTRICT_BLEND_PX either side of a border,
  // but a colour lerp alone reads as a blur, not a boundary. This adds an actual EDGE MARKER: a
  // self-gated predicate layer (same "populate no-ops outside its own case" trick as road/clutter
  // above) that fires only within roughly one DISTRICT_BLEND_PX of a border and orients a marker
  // ALONG it — a picket fence for a land/land seam (reusing T.fence, already baked for suburbs — a
  // field boundary is exactly what a fence already reads as) or a foam streak for any seam touching
  // sea. v5.10 replaced BOTH with real seam art — see the seam pick in populateEdge itself.
  // districtAt is the only border-relevant primitive config.js exports (nearestDistrictSeeds' exact
  // border distance is NOT exported, and this file only owns render.js) — so "near a border" is
  // approximated by sampling districtAt at 4 points BORDER_PROBE px out from this cell (a plain
  // Sobel-style edge test): if any of the four differs from the centre, a border is close, and
  // WHICH ones differ gives a rough outward direction to orient the marker perpendicular to (i.e.
  // running ALONG the border, the way a fence or a shoreline actually would). BORDER_PROBE reuses
  // DISTRICT_BLEND_PX so the marker sits right where the tint is already mid-blend, not offset from
  // it. This is an approximation (a true corner where 3+ districts meet can give a noisy direction),
  // never exact geometry — acceptable for a decorative accent, not for anything sim-relevant.
  const BORDER_PROBE = DISTRICT_BLEND_PX
  function populateEdge(s, i, j, cell) {
    if (chapterIsVoid || !chapterHasDistricts) { s.visible = false; return }
    const jx = (cellHash(i, j, 7) - 0.5) * cell * 0.5
    const jy = (cellHash(i, j, 8) - 0.5) * cell * 0.5
    const wx = (i + 0.5) * cell + jx, wy = (j + 0.5) * cell + jy
    const here = districtAt(wx, wy, districtSeed)
    const east = districtAt(wx + BORDER_PROBE, wy, districtSeed)
    const west = districtAt(wx - BORDER_PROBE, wy, districtSeed)
    const south = districtAt(wx, wy + BORDER_PROBE, districtSeed)
    const north = districtAt(wx, wy - BORDER_PROBE, districtSeed)
    const nx = (east !== here ? 1 : 0) - (west !== here ? 1 : 0)
    const ny = (south !== here ? 1 : 0) - (north !== here ? 1 : 0)
    if (nx === 0 && ny === 0) { s.visible = false; return } // most cells, most of the time — no border nearby
    // v5.10 (spec §4.5, kill list §8.11): a seam is a chance to SAY WHAT THE TWO REGIONS ARE. This
    // used to draw T.fence — a suburban picket fence — at every land/land border, including the
    // one between a farm and a moor. Three seam bakes: a hedge line for suburb/park seams, a
    // dry-stone tick-row for farm/hill seams, and riprap + a real wave crest for any coastline.
    const other = [east, west, south, north].find((d) => d !== here) || here
    const isCoast = here === 'sea' || other === 'sea'
    const seam = isCoast ? 'shore' : (DISTRICT_EDGE.pairs[[here, other].sort().join('|')] || 'hedge')
    const kind = seam === 'shore'
      ? { name: 'waveCrest', baked: true, litTint: true, tints: SEA_FOAM_TINTS, alpha: 0.75, size: [80, 130] }
      : seam === 'wall'
        ? { name: 'wallSeam', baked: true, alpha: 0.8, size: PROP_SCALE.fence }
        : { name: 'hedgeSeam', baked: true, alpha: 0.9, size: PROP_SCALE.hedge }
    const pos = applyPropKind(s, kind, i, j, wx, wy) // handles texture/tint/scale/anchor; rotation overridden next
    s.position.set(pos.x, pos.y)
    s.rotation = Math.atan2(nx, -ny) // perpendicular to the (nx,ny) outward normal — runs ALONG the border
  }

  // road/clutter run over EVERY chapter's cells (touchFloorCell has no chapter gate) but their
  // populate callbacks no-op (s.visible = false) outside skies/urban — see their own doc comments
  // above for why a self-gating predicate layer was the only way to add chapter-scoped density
  // without touching the shared cell/chance numbers every other chapter also uses.
  // v5.9.2 ("the fuck is this?" bug report): big/mid/detail carry an extra `skiesKeep` — see
  // touchFloorCell below and SKIES_FLOOR_KEEP's doc in config.js. blotch/road/clutter/edge have none
  // (undefined), so touchFloorCell's extra gate never fires for them at all, chapter or no.
  const FLOOR_LAYERS = [
    { name: 'blotch', cell: 420, chance: 1.00, parent: blotchLayer, populate: populateBlotch },
    // v5.11 terrain surface (skies only — populateTerrain self-gates on chapterHasDistricts). Its
    // cell is PARCEL so one cell is exactly one farm field; at ~280px a 1900x1000 view is about 50
    // sprites, cheaper than the 420px blotch layer it stands in for.
    { name: 'terrain', cell: PARCEL, chance: 1.00, parent: blotchLayer, populate: populateTerrain },
    // v6.9.1: no 'road' layer here any more — the carriageway is enumerated per STREET by
    // updateStreets, not stamped per cell. The DECALS stay per-cell: they are randomly picked and
    // randomly placed, which is exactly what a tiling strip cannot be.
    { name: 'roadDecal', cell: ROAD_DECAL.cell, chance: ROAD_DECAL.chance, parent: roadDecalLayer, populate: populateRoadDecal },
    { name: 'big', cell: 460, chance: 0.35, parent: bigLayer, populate: populateBig, skiesKeep: SKIES_FLOOR_KEEP.big, clump: true },
    { name: 'mid', cell: 170, chance: 0.55, parent: midLayer, populate: populateMid, skiesKeep: SKIES_FLOOR_KEEP.mid, clump: true },
    { name: 'detail', cell: 120, chance: 0.40, parent: detailLayer, populate: populateDetail, skiesKeep: SKIES_FLOOR_KEEP.detail, clump: true },
    { name: 'clutter', cell: 150, chance: 1.00, parent: clutterLayer, populate: populateClutter, clump: true },
    { name: 'edge', cell: 170, chance: 1.00, parent: edgeLayer, populate: populateEdge },
  ]

  function touchFloorCell(cfg, i, j) {
    if (cellHash(i, j, 999) >= cfg.chance) return
    // Skies-only extra thinning (config.js SKIES_FLOOR_KEEP): a second, independent chance roll on
    // top of cfg.chance so big/mid/detail can be cut hard for skies alone, without lowering the
    // cfg.chance every other chapter's identical layer also reads. `cfg.skiesKeep` is undefined for
    // every layer that doesn't opt in (blotch/road/clutter/edge) and for every OTHER chapter's cells
    // this same layer still gets touched for (chapterHasDistricts is skies-only), so neither ever
    // sees this line do anything.
    if (chapterHasDistricts && cfg.skiesKeep != null && cellHash(i, j, 998) >= cfg.skiesKeep) return
    // v5.12 CLUMPING. cfg.chance is a flat per-cell roll, so scatter came out statistically even —
    // and even spacing is exactly what a LATTICE looks like: the wide-area captures showed woodland
    // as a regular grid of dots. clumpAt (terrain.js) is a contrast-stretched low-frequency mask;
    // multiplying occupancy by it gives dense copses with ragged edges and real clearings, which is
    // what natural cover actually does. Only the scatter layers opt in (cfg.clump) — roads,
    // junctions and the terrain surface must stay deterministic and complete.
    if (chapterHasDistricts && cfg.clump && cellHash(i, j, 997) >= clumpAt((i + 0.5) * cfg.cell, (j + 0.5) * cfg.cell, districtSeed)) return
    const key = i + ',' + j + ',' + cfg.name
    let s = floorCells.get(key)
    if (!s) {
      s = acquireFloorSprite(cfg.parent)
      cfg.populate(s, i, j, cfg.cell)
      floorCells.set(key, s)
    }
    s._seen = true
  }

  // cx,cy follow the same convention as world.position (screen = worldPos + (cx,cy));
  // call with whatever the camera offset is this frame — gameplay, idle drift, reset.
  function updateFloorLayer(cx, cy) {
    if (!propsReady) return
    const w = viewW()
    const h = viewH()
    for (const cfg of FLOOR_LAYERS) {
      const margin = cfg.cell
      const i0 = Math.floor((-cx - margin) / cfg.cell)
      const i1 = Math.floor((-cx + w + margin) / cfg.cell)
      const j0 = Math.floor((-cy - margin) / cfg.cell)
      const j1 = Math.floor((-cy + h + margin) / cfg.cell)
      for (let i = i0; i <= i1; i++) {
        for (let j = j0; j <= j1; j++) touchFloorCell(cfg, i, j)
      }
    }
    for (const [key, s] of floorCells) {
      if (s._seen) s._seen = false
      else { floorCells.delete(key); releaseFloorSprite(s) }
    }
  }

  function clearFloorLayer() {
    for (const [, s] of floorCells) releaseFloorSprite(s)
    floorCells.clear()
  }

  // player rig: shadow stays put, bodyC squashes/hops
  // v5.8 kaiju redesign (skies only): a soft halo behind the whole rig, lit up while a rampage is
  // active (run.rampageT > 0 — see syncPlayer) so the widened crush radius (stepCrush's entire
  // rampage payoff, config.js RAMPAGE_CRUSH_MUL) reads as "I am currently dangerous" at a glance.
  // Built as Texture.EMPTY, like pTail's tailA/tailB below — this rig is constructed synchronously
  // right after buildTextures(), before the fx sheet (T.fx, loaded via Assets) is ready; syncPlayer
  // latches the real circle_05 texture onto it the first time it's actually needed.
  const pRampageGlow = new Sprite(Texture.EMPTY)
  pRampageGlow.anchor.set(0.5)
  pRampageGlow.visible = false
  const pShadow = spriteOf(T.playerShadow)
  pShadow.y = PLAYER.radius * 0.95
  const bodyC = new Container()
  const pBody = spriteOf(T.playerBody)
  const pupilL = spriteOf(T.pupil)
  const pupilR = spriteOf(T.pupil)
  const pFlash = spriteOf(T.playerFlash)
  pFlash.alpha = 0
  // BERSERK's red wash (v7.14). A SEPARATE sprite rather than a tint on pBody, because Pixi's tint
  // is a MULTIPLY: multiplying the mint body (0x7de3c3) by any red can only darken it toward olive,
  // which is what the first attempt shipped and what the probe caught — a multiply cannot turn a
  // green body red. An alpha-blended red silhouette in the body's OWN shape can.
  // Sits above pBody and below the pupils, so the eyes stay sharp while the skin runs hot.
  const pHot = spriteOf(T.playerFlash)
  pHot.alpha = 0
  bodyC.addChild(pBody, pHot, pupilL, pupilR, pFlash)
  // flagellum tail (pond/undergrowth skins): two stacked streak glyphs behind the blob, trailing
  // the player's facingAngle with a wiggle. Textures are fx sprites so they're assigned once the fx
  // sheet loads (buildFxTextures); this rig starts hidden and is revealed by chapterRender.tail.
  // v5.11: tailC is the kaiju rig's third chain link ONLY (see syncPlayer) — pond/undergrowth never
  // show it (it starts and stays invisible, texture never assigned, for any non-kaiju chapter).
  const pTail = new Container()
  pTail.visible = false
  const tailA = new Sprite(Texture.EMPTY)
  const tailB = new Sprite(Texture.EMPTY)
  const tailC = new Sprite(Texture.EMPTY)
  for (const t of [tailA, tailB, tailC]) { t.anchor.set(0.04, 0.5); pTail.addChild(t) }
  playerC.addChild(pRampageGlow, pShadow, pTail, bodyC) // glow sits furthest back, tail above the shadow, behind the body

  // title-screen ambient blobs
  const idleBlobs = []
  {
    const specs = [
      { fill: 0x7de3c3, line: 0x3aa88a, r: 27, fx: 0.26, fy: 0.62, ph: 0 },
      { fill: 0xffb3c6, line: 0xd5567d, r: 19, fx: 0.56, fy: 0.72, ph: 2.1 },
      { fill: 0x8e97f2, line: 0x5560c9, r: 22, fx: 0.78, fy: 0.58, ph: 4.2 },
    ]
    for (const sp of specs) {
      const shadow = spriteOf(T.playerShadow)
      shadow.scale.set(sp.r / PLAYER.radius)
      const blob = spriteOf(makeBlobTexture(sp.fill, sp.line, sp.r))
      idleLayer.addChild(shadow, blob)
      idleBlobs.push({ blob, shadow, ...sp })
    }
  }

  // dust motes: fixed small set of soft dots drifting slowly up-right in SCREEN
  // space (own container directly on stage, unaffected by camera/world position).
  // Active during both gameplay and idle so the scene always feels alive.
  const DUST_COUNT = 14
  const dustMotes = []
  let dustT = 0
  for (let i = 0; i < DUST_COUNT; i++) {
    const s = new Sprite(T.dustMote)
    s.anchor.set(0.5)
    s.scale.set(lerp(0.8, 1.6, hash(i * 5.31 + 1.7)))
    dustLayer.addChild(s)
    dustMotes.push({
      s,
      x: hash(i * 3.11 + 0.4),
      y: hash(i * 7.77 + 2.2),
      vx: 8 + hash(i * 2.13 + 3.3) * 10,
      vy: 6 + hash(i * 4.87 + 5.5) * 8,
    })
  }

  // Per-chapter dust look (CHAPTERS[].render.dust, {tint, alpha}), or null for the white default.
  // The mote texture is a WHITE radial dot, which is right over the dark floors every Book 1 chapter
  // has and reads as smears on a lens over The Surf's pale sand — the same "a mote in the floor's
  // own value is the wrong mote" problem updateLeaves' tint comment already documents, arrived at
  // from the opposite side. Latched in reset().
  let dustLook = null
  function updateDustMotes(dt) {
    if (dt <= 0) return // frozen behind modals, same rule as particles
    dustT += dt
    const w = app.screen.width
    const h = app.screen.height
    // speedMul/sway (v7.x): the same 14 motes read as WIND at their built-in pace, which is wrong on
    // a floor that is under water — sand does not blow through water, it hangs in it. Both default
    // to no-ops so every chapter but the ones that ask keeps the drift it was tuned with.
    const mul = dustLook?.speedMul ?? 1
    const sway = dustLook?.sway ?? 0
    for (let i = 0; i < dustMotes.length; i++) {
      const m = dustMotes[i]
      // The sway is a slow lateral wander, out of phase per mote: suspended grit is moved BY
      // something, and a straight line at any speed reads as a particle travelling under its own
      // power. Phase from i so the field never drifts in unison.
      const s = sway ? Math.sin(dustT * 0.5 + i * 1.9) * sway : 0
      m.x += ((m.vx * mul + s) * dt) / w
      m.y -= (m.vy * mul * dt) / h // up = decreasing y
      if (m.x > 1.08) m.x -= 1.16
      if (m.y < -0.08) m.y += 1.16
      m.s.position.set(m.x * w, m.y * h)
      m.s.alpha = (0.2 + 0.1 * Math.sin(dustT * 2 + i)) * (dustLook?.alpha ?? 1)
    }
  }

  // v6.5 undergrowth: falling leaves (CHAPTERS[].render.leaves — chapterHasLeaves, latched in
  // reset()). Same "own container directly on stage" screen-space idiom as dust motes above, but
  // tinted OFF the floor-scatter leaf palette (config.js DETAIL_UNDERGROWTH's 0xb08050/0x8a6a3e IS
  // the floor — a leaf falling in the same tint over dead-leaf loam would be invisible) and
  // carrying a per-frame tumble the static floor litter can never fake. T.props.leaf loads async
  // (propsReady), so the sprites are built LAZILY the first update after props land — updateFloorLayer's
  // own `if (!propsReady) return` idiom — rather than eagerly with a Texture.EMPTY placeholder.
  const LEAF_COUNT = 12
  const LEAF_TINTS = [0x9fb36a, 0xd9c9a0, 0xc4a76a] // pale fresh-fall greens/tans, not the dead-leaf floor
  const leaves = []
  let leavesBuilt = false

  function buildLeaves() {
    for (let i = 0; i < LEAF_COUNT; i++) {
      const s = new Sprite(T.props.leaf)
      s.anchor.set(0.5)
      s.tint = LEAF_TINTS[i % LEAF_TINTS.length]
      s.alpha = 0.5
      const size = lerp(10, 18, hash(i * 6.11 + 8.8))
      s.scale.set(size / 1024) // leaf.png is a 1024px source sheet — applyPropKind's own scale idiom
      leafLayer.addChild(s)
      leaves.push({
        s,
        x: hash(i * 3.71 + 1.11),
        y: hash(i * 5.33 + 2.22),
        vy: lerp(20, 35, hash(i * 4.44 + 3.33)),
        swayAmp: lerp(10, 24, hash(i * 2.99 + 4.44)),
        swayFreq: lerp(0.6, 1.4, hash(i * 7.13 + 5.55)),
        swayPh: hash(i * 8.31 + 6.66) * Math.PI * 2,
        spin: (hash(i * 9.77 + 7.77) - 0.5) * 3, // per-frame tumble rate, +- a bit over 1 rev/s
        rot: hash(i * 1.31 + 0.55) * Math.PI * 2,
      })
    }
    leavesBuilt = true
  }

  function updateLeaves(dt) {
    leafLayer.visible = chapterHasLeaves
    if (!chapterHasLeaves || !propsReady) return
    if (!leavesBuilt) buildLeaves()
    if (dt <= 0) return // frozen behind modals, same rule as dust motes
    const w = app.screen.width
    const h = app.screen.height
    for (const l of leaves) {
      l.y += (l.vy * dt) / h
      l.rot += l.spin * dt
      if (l.y > 1.08) { l.y = -0.08; l.x = Math.random() } // re-enter at the top, fresh column
      const sway = Math.sin(animT * l.swayFreq + l.swayPh) * l.swayAmp
      l.s.position.set(l.x * w + sway, l.y * h)
      l.s.rotation = l.rot
    }
  }

  // Flow streaks (the pond's `currents` signature, and The Surf's `tide`): world-space streaks that
  // sample the REAL force field the sim pushes everything with and advect along it — exaggerated
  // (flowVis.speedMul) so the gentle sim push reads as an obvious water flow. Each streak is a
  // double-stacked soft trace glyph (one layer washes out on the light floor) rotated to the local
  // flow direction and stretched by speed. Streaks fade in, live a few seconds while advecting, then
  // fade out and respawn in view; they also respawn on straying past the viewport (+margin). Pooled
  // — only transform/alpha touched per frame. currentLayer stays on the stage; world coords are
  // converted to screen with the frame's camera offset (cx,cy: screen = world + (cx,cy)).
  //
  // ONE pool, two chapters (v7.x). The tide shipped with no visual at all: a 46 px/s lateral shove
  // with nothing on screen reads as the controls fighting you, where the design (§5.2) asks it to
  // read as WEATHER. The only thing that differs is the force function and the palette, so the tide
  // borrows this field rather than growing a second one — flowKind picks tideForce over currentForce
  // and TIDE_VIS over CURRENT_VIS, both latched in reset(). The streaks REVERSE when the surge does,
  // which is the tell that there is a backwash and not just a wind.
  const currentStreaks = []
  // Which vis block the pool's sprite SCALES are currently built for (lenPx/widthPx differ between
  // the pond and the tide), or null before the fx textures have loaded. Re-derived whenever it
  // disagrees with flowVis, which is how one pool serves two chapters across a quit-to-title.
  let currentTexVis = null
  let rippleTimer = 0
  for (let i = 0; i < CURRENT_VIS.count; i++) {
    const g = new Container()
    g.visible = false
    const a = new Sprite(Texture.EMPTY)
    const b = new Sprite(Texture.EMPTY)
    for (const s of [a, b]) { s.anchor.set(0.5); s.tint = CURRENT_VIS.tint; g.addChild(s) }
    b.alpha = 0.7 // far copy slightly softer — double-stack punches through the murky floor
    currentLayer.addChild(g)
    currentStreaks.push({ g, a, b, x: 0, y: 0, age: 0, life: 0, ang: 0, spawned: false })
  }

  // Drop a streak at a fresh world position somewhere in the current view (+ a little jitter).
  function respawnStreak(p, cx, cy, w, h, atX, atY) {
    if (atX == null) {
      p.x = -cx + Math.random() * w
      p.y = -cy + Math.random() * h
    } else { p.x = atX; p.y = atY }
    p.age = 0
    p.life = flowVis.life * (1 + (Math.random() * 2 - 1) * flowVis.lifeJitter)
    p.spawned = true
  }

  // The active chapter's flow field at a world point, in px/s. The tide is UNIFORM (one surge for
  // the whole map) so it ignores x/y; the pond's varies per point. Sampled by the streaks below and
  // by the crowd's rock in syncEnemies, so both read the same water the sim is pushing with.
  function flowAt(run, x, y) {
    if (flowKind === 'tide') return tideForce(run)
    if (flowKind === 'currents') return currentForce(run, x, y)
    return { fx: 0, fy: 0 }
  }

  function updateCurrents(run, dt, cx, cy) {
    if (!flowKind) { currentLayer.visible = false; return }
    currentLayer.visible = true
    if (currentTexVis !== flowVis && T.fx && T.fx.trace_05) {
      const lx = fxScale(T.fx.trace_05, flowVis.lenPx)
      const ly = fxScale(T.fx.trace_05, flowVis.widthPx)
      for (const p of currentStreaks) {
        p.a.texture = p.b.texture = T.fx.trace_05
        p.a.scale.set(lx, ly)
        p.b.scale.set(lx * 0.9, ly * 0.85)
      }
      currentTexVis = flowVis
    }
    if (currentTexVis !== flowVis || dt <= 0) return
    const w = app.screen.width
    const h = app.screen.height
    const mg = flowVis.margin

    for (const p of currentStreaks) {
      if (!p.spawned) respawnStreak(p, cx, cy, w, h)
      p.age += dt
      // advect along the exaggerated real field
      const f = flowAt(run, p.x, p.y)
      const vx = f.fx * flowVis.speedMul
      const vy = f.fy * flowVis.speedMul
      p.x += vx * dt
      p.y += vy * dt
      const speed = Math.hypot(vx, vy)
      if (speed > 1) p.ang = Math.atan2(vy, vx) // keep last heading in dead spots
      // screen position (world + camera)
      const sx = p.x + cx
      const sy = p.y + cy
      const off = sx < -mg || sx > w + mg || sy < -mg || sy > h + mg
      if (p.age >= p.life || off) { respawnStreak(p, cx, cy, w, h); continue }
      // fade envelope: in over fadeIn, out over the last fadeOut
      let env = 1
      if (p.age < flowVis.fadeIn) env = p.age / flowVis.fadeIn
      else if (p.age > p.life - flowVis.fadeOut) env = Math.max(0, (p.life - p.age) / flowVis.fadeOut)
      p.g.position.set(sx, sy)
      p.g.rotation = p.ang
      p.g.scale.set(1 + speed * flowVis.stretchPerSpeed, 1) // stretch length with speed
      p.g.alpha = flowVis.alpha * env * (p.boost || 1)
      p.g.visible = true
    }

    // Ripple-train accent: every rippleEvery seconds, restart 3 streaks single-file along one
    // streamline (seeded in view, each offset downstream) with a brief brightness boost — a moving
    // arrow emphasising flow direction. Cheap: it just re-seeds existing pooled streaks.
    for (const p of currentStreaks) if (p.boost) p.boost = Math.max(1, p.boost - dt * 1.2)
    if (flowVis.rippleEvery > 0 && currentStreaks.length >= 3) {
      rippleTimer += dt
      if (rippleTimer >= flowVis.rippleEvery) {
        rippleTimer = 0
        let ox, oy, dx, dy
        // v6.4: bias the train onto an in-view eddy's ring when one exists — a moving arrow tracing
        // the true force boundary reads far better than a random streamline. Random-picks WHICH
        // eddy (and where on its ring) via the same Math.random() calls this block already used —
        // render-side Math.random() is fine, only SIM streaming is RNG-forbidden.
        const visibleEddies = chapterHasEddies
          ? run.eddies.filter((ed) => {
              const sx = ed.x + cx, sy = ed.y + cy
              return sx > -ed.r && sx < w + ed.r && sy > -ed.r && sy < h + ed.r
            })
          : []
        if (visibleEddies.length > 0) {
          const ed = visibleEddies[Math.floor(Math.random() * visibleEddies.length)]
          const ang = Math.random() * Math.PI * 2
          ox = ed.x + Math.cos(ang) * ed.r
          oy = ed.y + Math.sin(ang) * ed.r
          // tangent at this ring point, signed by the eddy's own swirl — mirrors currentForce's own
          // tangential term (sim.js): tx = -uy*dir, ty = ux*dir, where (ux,uy) is the INWARD unit
          // vector (ring point -> centre), i.e. the negative of this point's outward offset.
          const ux = -Math.cos(ang), uy = -Math.sin(ang)
          dx = -uy * ed.dir
          dy = ux * ed.dir
        } else {
          ox = -cx + Math.random() * w
          oy = -cy + Math.random() * h
          const f = flowAt(run, ox, oy)
          const sp = Math.hypot(f.fx, f.fy) || 1
          dx = f.fx / sp
          dy = f.fy / sp
        }
        for (let k = 0; k < 3; k++) {
          const p = currentStreaks[(Math.floor(Math.random() * currentStreaks.length) + k) % currentStreaks.length]
          respawnStreak(p, cx, cy, w, h, ox + dx * k * flowVis.lenPx * 0.9, oy + dy * k * flowVis.lenPx * 0.9)
          p.boost = 2
        }
      }
    }
  }

  function clearCurrents() {
    currentLayer.visible = false
    for (const p of currentStreaks) { p.g.visible = false; p.spawned = false; p.boost = 1 }
    rippleTimer = 0
  }

  // Eddy vortex decals (pond signature, v6.4, run.eddies): the gravity hole's proven treatment
  // (~line 8010 below — two counter-rotating twirl layers at high alpha) plus a stroked rim ring at
  // exactly the eddy's r, the true force boundary (currentForce's eddies term, sim.js). Pooled —
  // grown on demand, hidden past run.eddies.length, EDDY_VIS.config.js owns every tuning number.
  // Unlike currentStreaks, positioned in WORLD space directly: eddyLayer is a child of entitiesLayer
  // (see its own declaration above for why), so no manual camera-offset math is needed here.
  const eddyPool = []
  function acquireEddy() {
    const root = new Container()
    const vortexA = new Sprite(T.fx.twirl_01)
    vortexA.anchor.set(0.5)
    vortexA.tint = EDDY_VIS.tintA
    const vortexB = new Sprite(T.fx.twirl_02)
    vortexB.anchor.set(0.5)
    vortexB.tint = EDDY_VIS.tintB
    const ring = new Graphics()
    root.addChild(vortexA, vortexB, ring)
    eddyLayer.addChild(root)
    return { root, vortexA, vortexB, ring, _r: 0 }
  }
  function placeEddy(ev, ed, i) {
    ev.root.position.set(ed.x, ed.y)
    const twirlPx = ed.r * EDDY_VIS.twirlFrac
    ev.vortexA.scale.set(fxScale(T.fx.twirl_01, twirlPx))
    ev.vortexB.scale.set(fxScale(T.fx.twirl_02, twirlPx * 0.85))
    // Dominant layer (A) spins WITH the eddy's true dir at the full rate; the counter layer (B)
    // spins the OPPOSITE way, slower and dimmer (counterRateMul/counterAlphaMul < 1) — same "one
    // layer sets the read, the other just textures it" trick the hole uses below, but here it's
    // signed by ed.dir so the net swirl a player reads always matches the force's real rotation.
    ev.vortexA.rotation = animT * EDDY_VIS.spinRate * ed.dir + i * 0.6
    ev.vortexB.rotation = -animT * EDDY_VIS.spinRate * EDDY_VIS.counterRateMul * ed.dir + i * 0.9
    const pulse = 1 + EDDY_VIS.pulseAmp * Math.sin(animT * EDDY_VIS.pulseRate + i * 1.3)
    ev.vortexA.alpha = EDDY_VIS.alpha * pulse
    ev.vortexB.alpha = EDDY_VIS.alpha * EDDY_VIS.counterAlphaMul * pulse
    if (ev._r !== ed.r) { // rim ring, redrawn only when the radius changes — same cache the hole uses
      ev._r = ed.r
      ev.ring.clear()
      ev.ring.circle(0, 0, ed.r).stroke({ width: EDDY_VIS.ringWidth, color: EDDY_VIS.ringTint, alpha: EDDY_VIS.ringAlpha })
    }
  }
  function updateEddies(run, dt) {
    if (!chapterHasEddies) { eddyLayer.visible = false; return }
    eddyLayer.visible = true
    const list = run.eddies
    while (eddyPool.length < list.length) eddyPool.push(acquireEddy())
    for (let i = 0; i < eddyPool.length; i++) {
      const ev = eddyPool[i]
      ev.root.visible = i < list.length
      if (i < list.length) placeEddy(ev, list[i], i)
    }
  }
  function clearEddies() {
    eddyLayer.visible = false
    for (const ev of eddyPool) ev.root.visible = false
  }

  // ------------------------------------------------- refill circles (v7.x Book 2): shafts + pools
  // Both chapters' refill circles live in run.shafts (sim.js streamShafts feeds it from refillSpec),
  // and both are drawn as a disc with a rim ON exactly the tested radius, because standing in it IS
  // the mechanic (stepCharge tests centre-to-centre against that radius) and a player has to be able
  // to tell "am I IN it" at a glance.
  //
  // They must not LOOK the same, though, and for a while The Surf's did not look like anything at
  // all: this function early-returned on `signature.type === 'shafts'`, so the tide pools — the only
  // way to refill Humidity, which drives the chapter's damage — drew nothing whatsoever. The gate is
  // now refillLook (see reset), which asks the same refillSpec() question the streamer asks.
  //   'shaft' — The Shelf. A warm additive column of light. `body` is unused and stays cleared.
  //   'pool'  — The Surf. A hole in wet sand with water standing in it: a damp collar, a dark water
  //             body, an off-centre shallow shelf, a bright meniscus, and one soft additive sheen
  //             for the sky caught on the surface. Drawn from directly overhead like everything
  //             else; the water is DARKER than the sand around it, which is what makes it read as a
  //             hole rather than as a glowing marker.
  //
  // A pooled DECAL, not a rig: three display objects that never transform independently of each
  // other. That is why the pool is a flat array and why clearShafts hides the CHILDREN rather than a
  // `.root` — a rig left in the flat list of reset() sets a dead property on a plain object and the
  // previous run's entities stay on screen, with no throw and no warning.
  // The lobed outline as a point list for Graphics.poly, sampled from the SAME lobeFactor the sim
  // tests position against (config.js) — one definition, two consumers, which is the only reason the
  // edge you can see is the edge you can feel. 64 samples: the profile's fastest harmonic is 9 per
  // turn, so this is ~7 points per lobe, well past where the polygon stops reading as faceted.
  const LOBE_SEGMENTS = 64
  function lobePoly(r, shape, rot, ox = 0, oy = 0) {
    const pts = []
    for (let i = 0; i < LOBE_SEGMENTS; i++) {
      const a = (i / LOBE_SEGMENTS) * Math.PI * 2
      const rr = r * lobeFactor(shape, a, rot)
      pts.push(ox + Math.cos(a) * rr, oy + Math.sin(a) * rr)
    }
    return pts
  }

  const shaftPool = []
  function acquireShaft() {
    // Child order IS the stacking order: the water body must sit under its own sheen, so `body` is
    // added first and the additive glow second. A shaft never draws into `body` at all.
    const body = new Graphics()
    const glow = new Sprite(T.fx.light_01)
    glow.anchor.set(0.5)
    glow.blendMode = 'add'
    const ring = new Graphics()
    shaftLayer.addChild(body, glow, ring)
    return { body, glow, ring, _r: 0, _look: null }
  }
  function updateShafts(run) {
    if (!refillLook) { shaftLayer.visible = false; return }
    shaftLayer.visible = true
    const pool = refillLook === 'pool'
    const pocket = refillLook === 'pocket'
    const P = pocket ? AIR_POCKET_VIS : TIDE_POOL_VIS
    const list = run.shafts
    while (shaftPool.length < list.length) shaftPool.push(acquireShaft())
    for (let i = 0; i < shaftPool.length; i++) {
      const sv = shaftPool[i]
      const on = i < list.length
      sv.body.visible = on
      sv.glow.visible = on
      sv.ring.visible = on
      if (!on) continue
      const sh = list[i]
      sv.body.position.set(sh.x, sh.y)
      sv.glow.position.set(sh.x, sh.y)
      sv.ring.position.set(sh.x, sh.y)
      // Breathe, out of phase per circle (i, not animT alone) so a field of them does not pulse in
      // unison — the same trick placeEddy uses for its twirl layers. The pool's is slower and
      // shallower, and it wanders the SIZE rather than only the alpha: calm water, not a beacon.
      if (pool || pocket) {
        const b = 1 + P.breathe * Math.sin(animT * 0.55 + i * 1.7)
        sv.glow.scale.set(fxScale(sv.glow.texture, sh.r * P.sheenFrac * b))
        sv.glow.alpha = P.sheenA * (0.85 + 0.15 * Math.sin(animT * 0.8 + i * 2.3))
      } else {
        sv.glow.scale.set(fxScale(sv.glow.texture, sh.r * 2.1))
        sv.glow.alpha = 0.62 + 0.10 * Math.sin(animT * 1.1 + i * 1.7)
      }
      // Geometry redrawn only when the radius (or the chapter's look) changes, the same cache the
      // eddy ring uses. Neither field's radius moves today, so in practice this runs once per circle.
      if (sv._r !== sh.r || sv._look !== refillLook || sv._shape !== sh.shape || sv._rot !== sh.rot) {
        sv._r = sh.r
        sv._look = refillLook
        // The outline is part of the cache key now: two pools at the same radius are no longer the
        // same drawing. Leaving it out would have redrawn nothing after the first pool and stamped
        // that one shape across the whole field — with the SIM still testing each pool's own lobes,
        // so the edge you could see and the edge that refilled you would be different edges.
        sv._shape = sh.shape
        sv._rot = sh.rot
        sv.body.clear()
        sv.ring.clear()
        if (pocket) {
          // Trapped air seen from directly overhead: a HARD silver mirror, not a glow. Same three
          // strokes as the tide pool one branch down and the same drawn-extent-is-tested-extent
          // rim, but inverted in value — the pool is a dark hole in pale sand, this is a bright
          // disc on a dark reef floor, which is what keeps the two from reading as one another.
          const ar = sh.r * P.airFrac
          sv.glow.tint = P.sheen
          sv.body.circle(0, 0, sh.r).fill({ color: P.shade, alpha: P.shadeA })
          sv.body.circle(0, 0, ar).fill({ color: P.air, alpha: P.airA })
          sv.body.circle(-ar * 0.16, -ar * 0.13, ar * 0.5).fill({ color: P.lobe, alpha: P.lobeA })
          sv.ring.circle(0, 0, sh.r).stroke({ width: P.rimW, color: P.rim, alpha: P.rimA })
        } else if (pool) {
          // Concentric depth steps, outside in, each darker than the one around it — see
          // TIDE_POOL_VIS for why the collar, the shelf and the meniscus are gone. `ring` stays
          // CLEARED and unused: this look has no outline at all, which is the whole "less defined"
          // ask. Leaving the stroke in at a low alpha was the obvious half-measure and it is worse
          // than either extreme — a faint hard edge reads as a rendering seam rather than as a soft
          // one, because the eye finds an edge long before it finds a contrast.
          sv.glow.tint = P.sheen
          // Each depth step is the SAME outline scaled down, not a circle inside a lobe — a pool
          // whose steps were concentric circles under a lobed rim would read as a round hole with a
          // ragged edge painted on, which is the opposite of ground that dips.
          for (const st of P.steps) {
            sv.body.poly(lobePoly(sh.r * st.frac, sh.shape, sh.rot)).fill({ color: st.color, alpha: st.alpha })
          }
        } else {
          sv.glow.tint = 0xfff0c0
          sv.ring.circle(0, 0, sh.r).stroke({ width: 4, color: 0xffe9a8, alpha: 0.55 })
        }
      }
    }
  }
  function clearShafts() {
    shaftLayer.visible = false
    for (const sv of shaftPool) { sv.body.visible = false; sv.glow.visible = false; sv.ring.visible = false }
  }

  // ---------------------------------------------------------------- the net (v7.x The Trawl)
  // The sim carries the net as an infinite line — a unit normal `n` and a signed offset `pos` (see
  // stepTrawl). Drawing an infinite line means drawing the piece of it that is on screen, so both
  // Graphics work in a LOCAL frame that is re-anchored on the player every frame:
  //
  //   rotation = atan2(nx, -ny)  ->  local +x runs ALONG the wall, local +y points BEHIND it
  //   position = the player's own projection onto the line
  //
  // so local x = 0 is always where the player is standing relative to the wall, local x is the same
  // `t` coordinate the sim's holes are stored in (offset by the player's own t), and everything
  // behind the mesh — the wake — is at positive local y. That last part is why the rotation is
  // atan2(nx, -ny) and not atan2(ny, nx): the wake must land on the side the net has ALREADY crossed,
  // and getting that backwards is invisible in code and obvious on screen only if you know which
  // side to expect.
  //
  // REDRAWN EVERY FRAME, deliberately, where the shafts above cache on radius. There is no geometry
  // to cache: `pos` advances continuously, the player's t slides, and a Breach edits the hole list
  // mid-pass. It is a handful of strokes on one Graphics.
  const NET_VIS = {
    mesh: 0x2b3b47, meshLine: 0xd2dee6, rope: 0xe4d9a8,   // mesh body, twine, the head/foot ropes
    wake: 0x6d7f88, wakeA: 0.24,                           // churned sediment behind the wall
    torn: 0xf2e6b4,                                        // the bright frayed ends at a cut
    cell: 34,                                              // px between twines — the mesh's own scale
  }
  function updateNet(run) {
    const net = run.net
    netG.clear()
    netWakeG.clear()
    if (!net) return
    const p = run.player
    // The player's coordinate ALONG the wall, and the world point that corresponds to. Local x is
    // measured from here, so the drawn span always covers the screen however far the run has roamed.
    const tp = p.x * -net.ny + p.y * net.nx
    const ox = net.nx * net.pos + -net.ny * tp
    const oy = net.ny * net.pos + net.nx * tp
    const rot = Math.atan2(net.nx, -net.ny)
    for (const G of [netG, netWakeG]) { G.position.set(ox, oy); G.rotation = rot }
    // Half the drawn span. 1.6 x the view radius comfortably crosses either viewport at any rotation
    // (the worst case is the wall running corner to corner, which needs the half-diagonal itself).
    const L = Math.max(600, run.viewRadius * 1.6)
    const half = TRAWL_HALF
    const depth = TRAWL_WAKE_DEPTH

    // THE WAKE, behind the mesh (positive local y). Sediment settling, so the freshest churn is the
    // strip just behind the wall and it thins with distance back.
    //
    // FOURTEEN BANDS, NOT TWO. The first cut used two rects at 0.3 and 0.15 alpha and the probe
    // frame came back reading as a lit ROAD crossing the ocean: two flat tones meet in a hard
    // straight line, and a hard straight line down the middle of a soft thing is a road marking.
    // Six steps still left faint stripes — on a squared falloff the alpha drops ~0.07 per step at
    // the near end, which is above the threshold at which an edge is visible; fourteen puts every
    // step under ~0.03 and the seams go. Peak alpha also came down: the wake has to be legible
    // enough to steer into and quiet enough not to outshine the mesh, which is what kills you.
    const BANDS = 14
    for (let i = 0; i < BANDS; i++) {
      const y0 = half + (depth * i) / BANDS
      const k = 1 - i / BANDS
      netWakeG.rect(-L, y0, L * 2, depth / BANDS + 1)
        .fill({ color: NET_VIS.wake, alpha: NET_VIS.wakeA * k * k })
    }
    // Stirred-up streaks, drifting along the wall so the band reads as moving water rather than as a
    // painted stripe. Short and varied in length: the first cut ran 16 identical 46px dashes and they
    // read as rain on a window, because regular repetition of an identical mark is a texture and not
    // a current. animT-driven, so they FREEZE behind a modal exactly like every other animation here
    // — intended, not an oversight (see main.js's dt = 0).
    for (let i = 0; i < 22; i++) {
      const sx = ((i * 137.5 + animT * 40) % (L * 2)) - L
      const f = (i * 0.37) % 1
      const sy = half + depth * (0.08 + 0.8 * f)
      const len = 14 + 26 * ((i * 0.61) % 1)
      netWakeG.moveTo(sx, sy).lineTo(sx + len, sy)
        .stroke({ width: 2.2, color: 0xc3d2da, alpha: 0.18 * (1 - f * 0.7), cap: 'round' })
    }

    // THE MESH, in the SEGMENTS a Breach has left of it. Holes are stored in the sim's own t space,
    // so they shift by the player's t to land in local x. Sorted and walked as intervals: whatever is
    // not a hole gets drawn, which means the picture and the damage test can never disagree about
    // where the gap is — they are reading the same list the same way.
    const cuts = net.holes
      .map((h) => [h.t - tp - h.r, h.t - tp + h.r])
      .sort((a, b) => a[0] - b[0])
    const spans = []
    let x = -L
    for (const [a, b] of cuts) {
      if (b <= -L || a >= L) continue
      if (a > x) spans.push([x, Math.min(a, L)])
      x = Math.max(x, Math.min(b, L))
    }
    if (x < L) spans.push([x, L])
    for (const [a, b] of spans) {
      if (b - a < 1) continue
      // 0.34, not the 0.55 this started at: a net is mostly HOLE, and a dark band at half opacity
      // reads as a plank floating on the water. The twines carry the object; the fill only has to
      // darken the water enough that the wall is legible where it crosses a pale patch of floor.
      netG.rect(a, -half, b - a, half * 2).fill({ color: NET_VIS.mesh, alpha: 0.34 })
      // The twines. Two diagonal families make the diamond mesh a real net has; drawn per span so a
      // cut genuinely removes the netting rather than painting a gap over it.
      for (let d = Math.floor(a / NET_VIS.cell) * NET_VIS.cell; d < b + half * 2; d += NET_VIS.cell) {
        for (const s of [-1, 1]) {
          const x0 = Math.max(a, Math.min(b, d))
          const x1 = Math.max(a, Math.min(b, d + s * half * 2))
          if (x1 === x0) continue
          netG.moveTo(x0, -half * s).lineTo(x1, half * s)
            .stroke({ width: 1.6, color: NET_VIS.meshLine, alpha: 0.5 })
        }
      }
      // Head and foot ropes: the two bright lines that make the wall read as a made object rather
      // than as a shadow, and the thing you actually track from across the screen.
      for (const s of [-1, 1]) {
        netG.moveTo(a, s * half).lineTo(b, s * half)
          .stroke({ width: 3.5, color: NET_VIS.rope, alpha: 0.85, cap: 'round' })
      }
      // Frayed ends, at every edge that is a CUT rather than the end of the drawn span. Without this
      // a hole reads as the net simply not being there — the tell has to say "you did this".
      for (const [edge, isCut] of [[a, a > -L], [b, b < L]]) {
        if (!isCut) continue
        for (let k = -2; k <= 2; k++) {
          const y = (k / 2) * half
          netG.moveTo(edge, y).lineTo(edge + (edge === a ? -1 : 1) * (6 + (k & 1) * 7), y * 0.82)
            .stroke({ width: 2, color: NET_VIS.torn, alpha: 0.9, cap: 'round' })
        }
      }
    }
  }

  // ---- The Trawl's own gear: Longline (run.longlines) and Net Toss's landed mesh ---------------
  //
  // ⚠ THE PLAYER'S GEAR IS WARM AND THE WALL IS COLD, and that is the whole reason this does not
  // reuse NET_VIS one screen away from it. Both objects are literally fishing nets and one of them
  // kills you on contact — if they share a palette, the player's own fence reads as an incoming
  // wall every time it is set, in a chapter whose entire skill is knowing where the wall is. The
  // chapter's floor and the wall are the cold half of the frame; amber and hot orange appear here
  // and nowhere else in it, so anything warm on screen is unambiguously YOURS.
  const GEAR_VIS = {
    rope: 0xe8963c, ropeDark: 0x8a5218,   // the set line, and its weighted under-stroke
    hook: 0xffd98a,                        // the hooks — the brightest thing in the chapter
    float: 0xf25f3a,                       // floats and sinkers, the one saturated red
    mesh: 0xf0a94a, meshFill: 0x7a4517,    // a thrown net's twine and the water it darkens
    snood: 26,                             // px between hooks along a set line
    floatGap: 96,                          // px between floats
    fade: 0.7,                             // s of fade-out at the end of a line's life
  }

  // Landed Net Toss meshes. RENDER-LOCAL and aged here, because the sim keeps no entity after the
  // throw lands — the hold lives on the enemies as `stunT` and nothing else survives the frame. A
  // fixed ring buffer, the `whips` idiom: no allocation per cast and an automatic ceiling on how
  // much mesh can be on screen at once.
  const MAX_SNARES = 10
  const snares = []
  for (let i = 0; i < MAX_SNARES; i++) snares.push({ live: false, x: 0, y: 0, r: 0, t: 0, dur: 1 })
  let snareCursor = 0
  function pushSnare(x, y, r, dur) {
    const s = snares[snareCursor]
    snareCursor = (snareCursor + 1) % MAX_SNARES
    s.live = true; s.x = x; s.y = y; s.r = r; s.t = 0
    // The mesh is drawn for as long as the hold it bought. `hold` is the pre-diminishing-returns
    // figure the weapon casts with, so a heavily-resisted pack is released before the drawing
    // finishes — deliberately: the tell is "a net landed here", not a per-body status readout,
    // and each body already carries the stun pose render reads off `stunT`.
    s.dur = Math.max(0.2, dur)
  }

  // Both shapes, redrawn from scratch every frame. dt=0 (paused behind a modal) ages nothing but
  // still draws, so a frozen frame keeps its gear — the same rule the particles follow.
  function updateGear(run, dt) {
    longlineG.clear()
    snareG.clear()

    for (const l of run.longlines || []) {
      // (nx, ny) is the NORMAL, so the rope itself runs along its perpendicular. Getting this pair
      // the wrong way round draws every line at 90 degrees to the thing that is actually damaging,
      // which looks entirely plausible until a body dies beside the rope instead of on it.
      const ax = -l.ny, ay = l.nx
      const h = l.len / 2
      const x0 = l.x - ax * h, y0 = l.y - ay * h
      const x1 = l.x + ax * h, y1 = l.y + ay * h
      const fade = Math.min(1, Math.max(0, l.life / GEAR_VIS.fade))
      // The weighted under-stroke first, then the line over it: two passes make a rope read as
      // having thickness without a gradient, and the dark pass is what keeps it legible when it
      // crosses a pale patch of floor.
      //
      // ⚠ THESE WIDTHS ARE THE DIFFERENCE BETWEEN A ROPE AND A GIRDER, and the first shot got it
      // wrong. At 5.5/2.4px and alpha 0.95 the line drew as a solid orange BAR spanning the screen
      // — opaque, saturated, and heavier than anything else in the frame — which is exactly the
      // "reads as a laser" failure the snoods below exist to prevent, arriving through the main
      // stroke instead. Thin and slightly translucent is what makes it gear lying in water: the
      // floor has to show through it, or it is a painted line on top of the world.
      longlineG.moveTo(x0, y0).lineTo(x1, y1)
        .stroke({ width: 3.6, color: GEAR_VIS.ropeDark, alpha: 0.42 * fade, cap: 'round' })
      longlineG.moveTo(x0, y0).lineTo(x1, y1)
        .stroke({ width: 1.5, color: GEAR_VIS.rope, alpha: 0.8 * fade, cap: 'round' })
      // Snoods: the short branch lines that carry the hooks, alternating sides down the rope. This
      // is what makes it a LONGLINE from overhead rather than a piece of string — a bare segment
      // reads as a laser, which is the one thing this weapon must not look like.
      const n = Math.max(2, Math.floor(l.len / GEAR_VIS.snood))
      for (let i = 0; i <= n; i++) {
        const t = i / n
        const px = x0 + (x1 - x0) * t, py = y0 + (y1 - y0) * t
        const s = (i & 1) ? 1 : -1
        const len = 7 + (i % 3) * 2
        const hx = px + l.nx * s * len, hy = py + l.ny * s * len
        longlineG.moveTo(px, py).lineTo(hx, hy)
          .stroke({ width: 1.2, color: GEAR_VIS.rope, alpha: 0.7 * fade, cap: 'round' })
        longlineG.circle(hx, hy, 2.1).fill({ color: GEAR_VIS.hook, alpha: 0.95 * fade })
      }
      // Floats, spaced in WORLD px rather than per line, so a long line gets more of them and the
      // spacing is a property of the gear instead of a property of the level.
      const fn = Math.max(1, Math.round(l.len / GEAR_VIS.floatGap))
      for (let i = 0; i <= fn; i++) {
        const t = fn === 0 ? 0.5 : i / fn
        const px = x0 + (x1 - x0) * t, py = y0 + (y1 - y0) * t
        longlineG.circle(px, py, 3.4).fill({ color: GEAR_VIS.float, alpha: 0.9 * fade })
        longlineG.circle(px, py, 3.4).stroke({ width: 1, color: 0x3a1a08, alpha: 0.5 * fade })
      }
    }

    for (const s of snares) {
      if (!s.live) continue
      s.t += dt
      if (s.t >= s.dur) { s.live = false; continue }
      // ⚠ BOTH ENVELOPES ARE FIXED TIMES, NOT FRACTIONS OF THE HOLD, and the first cut had them as
      // fractions (open over the first 12% of life, fade over the last 30%). That is a bug with a
      // mod attached to it: Heavy Mesh buys a LONGER hold, and under fractional envelopes a longer
      // hold made the net OPEN IN SLOW MOTION — the better the card, the more sluggish the weapon
      // looked. A net opens as fast as a net opens, whatever it then holds for. Found by shooting
      // an inflated hold to photograph the fresh state and getting a tiny half-drawn mesh back.
      const OPEN_T = 0.14, FADE_T = 0.35
      const open = Math.min(1, s.t / OPEN_T)
      const a = open * Math.min(1, Math.max(0, (s.dur - s.t) / FADE_T))
      const r = s.r * (0.35 + 0.65 * open)
      // ⚠ THE MESH ALPHAS ARE LOAD-BEARING and the first shot had them far too low (fill 0.22,
      // rings 0.55, radials 0.42). A net over a pack IS the whole card, and at those values it was
      // barely findable in its own probe frame — a hold with no visible cause reads as the enemies
      // randomly stopping, which is the "mechanic with no tell" failure this repo has shipped
      // before. It has to be the second most obvious thing on screen after the wall.
      snareG.circle(s.x, s.y, r).fill({ color: GEAR_VIS.meshFill, alpha: 0.38 * a })
      // Concentric rings + radials: a net seen from directly overhead, which is a web, not a dome.
      for (let i = 1; i <= 3; i++) {
        snareG.circle(s.x, s.y, r * (i / 3.4))
          .stroke({ width: 1.6, color: GEAR_VIS.mesh, alpha: 0.85 * a })
      }
      for (let i = 0; i < 10; i++) {
        const ang = (i / 10) * Math.PI * 2
        snareG.moveTo(s.x, s.y).lineTo(s.x + Math.cos(ang) * r, s.y + Math.sin(ang) * r)
          .stroke({ width: 1.3, color: GEAR_VIS.mesh, alpha: 0.65 * a })
      }
      // The weighted rim is what says "this is closed and you are inside it".
      snareG.circle(s.x, s.y, r).stroke({ width: 2.6, color: GEAR_VIS.rope, alpha: 0.8 * a })
      for (let i = 0; i < 8; i++) {
        const ang = (i / 8) * Math.PI * 2 + 0.2
        snareG.circle(s.x + Math.cos(ang) * r, s.y + Math.sin(ang) * r, 2.8)
          .fill({ color: GEAR_VIS.float, alpha: 0.85 * a })
      }
    }
  }

  // ---------------------------------------------------------------- swell (v7.x Book 2)
  // The waves. DRAWN, not sprited — and the sprite version is worth recording because it looked
  // correct in every diagnostic. A pool of 34 tinted `trace_05` streaks reported swellVis=true and
  // crests=34/34, at alpha 0.62 and 26px wide, and was still almost invisible on screen: fxScale
  // squashes the WHOLE texture, transparent margins included, so scaling a soft round blob to
  // 340x26 leaves a sliver of actual ink. "The effect is drawing" and "the effect is visible" are
  // different questions, and only a screenshot answers the second.
  //
  // Sine polylines answer both, and are less code than the pool they replaced (no respawn, no fade
  // envelope, no per-crest bookkeeping) because a swell is a periodic field rather than a set of
  // objects. Crest lines run along world x and travel +y; axis-aligned on purpose, since a rotation
  // would mean re-deriving the visible region in the rotated frame for no read the player can name.
  // ---- The Surf's Breaker: the wave crest (run.novas entries carrying `arc`) -------------------
  //
  // A Graphics redrawn per frame rather than a sprite pool, and the reason is geometric: the crest
  // is an ARC whose half-angle changes with the weapon's level and with the Broad Crest mod, and a
  // baked texture can be scaled but not re-swept. Every other option was worse — a wedge baked at
  // one angle is wrong at every other one, and scattering N foam sprites along the arc makes the
  // pool churn with the arc's width. At most a handful of crests are ever alive (one per cast, x2
  // with Backwash, x3 under IPECAC), so the cost is nothing.
  //
  // DRAWN AS BANDS OF LIGHT AND SHADOW, NOT AS A STROKED ARC — the same rule updateSwell above
  // records from the owner ("I don't think they look like waves"), and it is not a stylistic echo:
  // both are water seen from directly overhead, where a wave is not a line but a strip tilted
  // toward the sky beside a strip tilted away. A stroked arc reads as a CONTOUR — the outline of a
  // shape rather than the surface of water — and the chapter's own background waves would then be
  // drawn in one language and its weapon in another.
  //
  // The foam is the exception and it earns it: whitewater on a breaking wave really is a hard bright
  // edge, and it is what says THIS one is a weapon rather than more scenery.
  // Barnacle crusts (enemy.barnacle). Drawn as lumps ON the body rather than as a tint alone: see
  // the block above syncEnemies' status tints for why a tint cannot carry this one on this floor.
  // One Graphics for every crusted body on screen — a few circles each, and only bodies actually
  // carrying a crust are visited, so a clean field costs one clear() and nothing else.
  //
  // Positions are derived from the enemy's own id, NOT from Math.random: a lump that moves every
  // frame reads as noise rather than as something growing on the body, and a paused frame has to be
  // stable.
  function drawCrusts(run) {
    crustG.clear()
    if (!run.enemies) return
    for (const e of run.enemies) {
      const c = e.barnacle
      if (!c || e._dead) continue
      // Fades in over the crust's first moments and out as it expires, so a body that has just been
      // seeded and one about to shake it off are not the same picture.
      const k = Math.max(0, Math.min(1, (c.t || 0) / (c.dur || 1)))
      const grow = Math.min(1, (1 - k) * 6 + 0.35)     // young crusts are still small
      const rad = (e.radius || 16)
      const n = 5
      for (let i = 0; i < n; i++) {
        // Golden-angle scatter keyed on the body's id, so no two enemies wear the same pattern and
        // none of them shifts between frames.
        const a = e.id * 1.37 + i * 2.399
        const d = rad * (0.28 + 0.46 * ((i * 7 + e.id) % 5) / 4)
        const x = e.x + Math.cos(a) * d, y = e.y + Math.sin(a) * d
        const rr = rad * (0.14 + 0.07 * ((i * 3 + e.id) % 3)) * grow
        crustG.circle(x, y, rr)
        crustG.fill({ color: 0xf2ead8, alpha: 0.92 * k })
        crustG.circle(x, y, rr)
        crustG.stroke({ width: Math.max(1, rr * 0.34), color: 0x6b5a45, alpha: 0.75 * k })
        // The volcano mouth every acorn barnacle has. It is one dot, and it is the whole reason
        // these read as barnacles rather than as blisters or as snow.
        crustG.circle(x, y, rr * 0.32)
        crustG.fill({ color: 0x4a3b2c, alpha: 0.8 * k })
      }
    }
  }

  // ---- The Deep's two per-body tells (v7.x) ---------------------------------------------------
  // Both read PUBLISHED contract fields off the enemy — `gape` and `scentT` — for the reason the
  // crust above does, and for the reason the v7.5x freeze scar exists: render.js learns about a new
  // mechanic only when sim publishes into a field it already reads, and a status kept private is
  // indistinguishable on screen from a status that does not work.
  //
  // THE GAPE IS THE CHAPTER'S ONLY WARNING. It is the timer on the player's greed, drawn on the
  // animal's face, and it cannot be baked: it changes per fish per frame and a bake is made once at
  // boot. So the body, the tooth ring and the dark socket are baked (drawAnglerfish) and the OPENING
  // is drawn here on top of them.
  function drawDeepTells(run) {
    deepG.clear()
    if (!run.enemies) return
    for (const e of run.enemies) {
      if (e._dead) continue
      const rad = e.radius || 16

      // SCENT: a body you have smelled. An outline rather than a tint, deliberately — this chapter
      // is nearly black and a tint on an already-dark body is invisible, while a rim survives any
      // amount of darkness because it is drawn against the water rather than over the animal.
      const st = e.scentT || 0
      if (st > 0) {
        const k = Math.min(1, st / 0.5)             // fades out over the last half-second
        const pulse = 0.75 + 0.25 * Math.sin(animT * 6 + e.id * 0.9)
        deepG.circle(e.x, e.y, rad * 1.18)
          .stroke({ width: Math.max(1.6, rad * 0.13), color: 0xff8a5c, alpha: 0.75 * k * pulse })
        deepG.circle(e.x, e.y, rad * 1.18).fill({ color: 0xff8a5c, alpha: 0.09 * k })
      }

      // GAPE: the mouth opening, centred on the head. The tooth ring in drawAnglerfish's bake sits
      // at local +x, so this wedge has to point the same way the SPRITE does or the two would part
      // company on screen — a mouth opening out of the fish's flank.
      //
      // ⚠ THE FACING IS RE-DERIVED HERE, and that is a knowing duplicate. syncEnemies keeps the
      // smoothed heading on the SPRITE (s._dirX/_dirY), which this pass has no handle on. This look
      // declares no `faceDir` and no `turnRate`, so its sprite snaps straight to the bearing toward
      // the player every frame — which is exactly the line below, with no smoothing to diverge from.
      // If the anglerfish is ever given either hook, this stops being true silently and the mouth
      // will drift off the head: move the drawing into the sprite pass instead of patching it.
      const gp = e.gape || 0
      if (gp <= 0.02) continue
      const a0 = Math.atan2(run.player.y - e.y, run.player.x - e.x)
      const half = 0.22 + gp * 0.95                 // radians either side of the axis
      const reach = rad * (0.55 + gp * 0.75)
      const cx = e.x + Math.cos(a0) * rad * 0.22, cy = e.y + Math.sin(a0) * rad * 0.22
      const pts = [cx, cy]
      for (let i = 0; i <= 10; i++) {
        const a = a0 - half + (i / 10) * half * 2
        pts.push(cx + Math.cos(a) * reach, cy + Math.sin(a) * reach)
      }
      deepG.poly(pts).fill({ color: 0x07090d, alpha: 0.92 })
      // The rim goes from cold to HOT as the bite approaches. Colour, not just size, because the
      // player is reading this in the dark at the edge of their light: a shape change alone is a
      // second-order cue and this is a first-order decision.
      const hot = gp > 0.62
      deepG.poly(pts).stroke({
        width: Math.max(1.4, rad * (0.08 + gp * 0.09)),
        color: hot ? 0xff5a3c : 0xb98a6a,
        alpha: 0.55 + 0.45 * gp,
      })
      // At the very top of the gape the lure flares. This is the last half-second before the bite
      // and it is the one moment the chapter shouts.
      if (gp > 0.82) {
        const flare = (gp - 0.82) / 0.18
        deepG.circle(e.x, e.y, rad * (1.3 + flare * 0.5)).fill({ color: 0xff6a3a, alpha: 0.16 * flare })
      }
    }
  }

  function drawBreakers(run) {
    breakerG.clear()
    if (!run.novas || run.novas.length === 0) return
    for (const n of run.novas) {
      if (n.arc == null) continue
      const life = n.lifeMax || NOVA_LIFE
      const k = Math.max(0, Math.min(1, n.life / life))   // 1 at the cast, 0 as it dies
      const r = Math.max(2, n.r)
      const half = n.arc / 2
      const a0 = n.angle - half, a1 = n.angle + half
      // Thickness scales with the crest's own radius so a wave that reaches further is a bigger
      // wave, not the same ribbon stretched around a longer arc.
      const bw = Math.max(6, r * 0.13)
      // It STEEPENS then breaks: the bands are widest and brightest in the middle of the run, and
      // the whole thing thins out as it dies. A linear fade reads as a ring being switched off.
      const swell = Math.sin(Math.PI * (1 - k)) * 0.65 + 0.35
      // EVERY ARC STARTS ITS OWN SUBPATH. `arc()` appends to whatever path is already open, so
      // without the moveTo the renderer joins the end of one arc to the start of the next with a
      // straight line — and strokes it. With a single crest on screen that join is short, radial and
      // hidden underneath the bands, which is why it survived every probe here; with two crests
      // alive at once (the Backwash mod) it becomes a long straight bar drawn clean across the
      // player. That is exactly what came back from a phone as "a visual glitch with the wave behind
      // you", and the single-crest probe could not have found it.
      const arcAt = (rad, width, color, alpha) => {
        if (alpha <= 0.01) return
        const rr = Math.max(1, rad)
        breakerG.moveTo(n.x + Math.cos(a0) * rr, n.y + Math.sin(a0) * rr)
        breakerG.arc(n.x, n.y, rr, a0, a1)
        breakerG.stroke({ width, color, alpha, cap: 'round' })
      }
      // The back of the wave first (drawn under), then the lit face, then the foam on the crest
      // itself — back to front, so the whitewater sits on top of its own water.
      arcAt(r - bw * 0.9, bw * 1.5, 0x2a5f7a, 0.30 * swell * k)   // the shadowed trough behind it
      arcAt(r - bw * 0.1, bw * 1.2, 0x8fd3e8, 0.34 * swell * k)   // the face turned up to the sky
      arcAt(r + bw * 0.45, bw * 0.55, 0xffffff, 0.62 * swell * k) // whitewater along the crest
      // BUBBLES, through the whole thickness of the wave and not only ahead of it (owner: "the wave
      // should have bubbles in it"). Whitewater IS aerated water — the bubbles are what the white in
      // a breaking wave actually is — so scattering them across the band is what makes the band read
      // as churning water rather than as a painted ribbon.
      //
      // Two kinds, and the mix is the whole trick: most are RINGS, because a bubble seen from above
      // is a bright rim around a lens of water, and a field of filled dots reads as snow or spray
      // instead. A few filled ones sit among them as the foam those bubbles are collapsing into.
      //
      // Positions are derived from the nova's own coordinates and the bubble's index, NEVER from
      // Math.random: a bubble that moves every frame reads as static, a paused frame has to hold
      // still, and two crests alive at once must not flicker against each other.
      const bubbles = 22
      for (let i = 0; i < bubbles; i++) {
        // Golden-angle walk along the arc so the field never falls into visible rows, plus a second
        // irrational term across the band's thickness so it fills rather than lining up on the crest.
        const t = ((i * 0.618034) % 1)
        const a = a0 + (a1 - a0) * t
        const seed = (n.x + n.y) * 0.011 + i * 2.399
        const across = Math.sin(seed * 1.7)                  // -1..1 through the band
        const rr = r + bw * (across * 1.15 - 0.15)
        // Small, and biggest near the crest where the water is breaking hardest.
        const size = bw * (0.10 + 0.13 * Math.abs(Math.sin(seed))) * (1 - Math.abs(across) * 0.45)
        const bx = n.x + Math.cos(a) * rr, by = n.y + Math.sin(a) * rr
        // A bubble grows as the wave breaks and pops as it spends itself, so the field thins out on
        // its own rather than fading uniformly.
        const bAlpha = k * swell * (0.55 + 0.45 * Math.sin(seed * 2.3))
        if (bAlpha <= 0.02 || size < 0.4) continue
        if (i % 4 === 0) {
          breakerG.circle(bx, by, size)
          breakerG.fill({ color: 0xffffff, alpha: 0.42 * bAlpha })
        } else {
          breakerG.circle(bx, by, size)
          breakerG.stroke({ width: Math.max(0.8, size * 0.42), color: 0xffffff, alpha: 0.62 * bAlpha })
        }
      }
    }
  }

  const swellG = new Graphics()
  swellLayer.addChild(swellG)
  let swellT = 0
  function updateSwell(run, dt, cx, cy) {
    if (!swellCfg) { swellLayer.visible = false; return }
    swellLayer.visible = true
    swellT += dt
    const w = app.screen.width, h = app.screen.height
    const cfg = swellCfg
    // Padded past the viewport by one full wavelength, so a crest scrolls in already drawn rather
    // than appearing at the screen edge — and in WORLD coords, because swellLayer is a `world`
    // child and the camera transform is applied above us.
    const pad = cfg.wavelength
    const x0 = -cx - pad, x1 = -cx + w + pad
    const yTop = -cy - pad, yBot = -cy + h + pad
    const k = (Math.PI * 2) / cfg.wavelength
    // The crest field is anchored to WORLD y and scrolled by a wrapped phase, so it slides past the
    // camera instead of riding it. Modulo the spacing, so the phase never grows without bound.
    const phase = (swellT * cfg.speed) % cfg.spacing
    const step = Math.max(14, cfg.wavelength / 16)   // enough samples that the curve is not a zigzag
    // BANDS, not lines. Owner, on the stroked version: "I don't think they look like waves" — and
    // he was right, because a stroked curve is a CONTOUR. Seen from directly overhead a wave is not
    // a line at all: it is a strip of water tilted toward the sky next to a strip tilted away, so
    // what you actually see is alternating light and shadow. Two wide, soft, low-alpha strokes per
    // crest — one either side of it — draw that, and no thin core is drawn at all, because any
    // sharp line immediately reads as an outline again.
    //
    // band 0.5 makes the pair exactly tile the spacing (light spans -bw..0, dark 0..+bw, and the
    // next crest begins where this one ends), so the surface is continuously corrugated rather than
    // striped with gaps of flat water between wave pairs.
    const bw = cfg.spacing * cfg.band
    swellG.clear()
    for (let y = Math.floor(yTop / cfg.spacing) * cfg.spacing + phase; y < yBot; y += cfg.spacing) {
      // Per-crest variation, keyed on the crest's INDEX in the unscrolled field rather than on its
      // current y. Both look stable in a still; only the index is stable while the field SCROLLS,
      // and keying on y makes every crest breathe as it travels, which reads as a shimmer.
      const idx = Math.round((y - phase) / cfg.spacing)
      const amp = cfg.amp * (0.62 + 0.38 * Math.sin(idx * 2.399))
      const v = 0.72 + 0.28 * Math.sin(idx * 1.111 + 1.7)   // this crest's share of the swell
      // A second harmonic at an irrational-ish ratio, so the crest never repeats over the span
      // actually on screen. One sine is a wave in a diagram; two is a wave on water.
      const off = idx * 1.73
      const yAt = (x) => y + Math.sin(x * k + off) * amp + Math.sin(x * k * 2.37 + off * 1.9) * amp * 0.33
      const band = (dy, color, alpha) => {
        swellG.moveTo(x0, yAt(x0) + dy)
        for (let x = x0 + step; x <= x1; x += step) swellG.lineTo(x, yAt(x) + dy)
        swellG.stroke({ width: bw, color, alpha })
      }
      band(-bw * 0.5, cfg.light, cfg.lightA * v)   // the face turned up toward the sky
      band(bw * 0.5, cfg.dark, cfg.darkA * v)      // and its shadowed back
    }
  }
  function clearSwell() {
    swellLayer.visible = false
    swellG.clear()
  }

  // The dark (see darkLayer's block up in the stage setup for WHY it is shaped this way).
  // Reads run.charge through the same darkness() curve sim.js uses for the move-speed penalty, so
  // "the screen dimmed" and "I am slow" can never drift apart into two separate mysteries.
  function updateDark(run, cx, cy) {
    const cfg = CHAPTERS[run.chapter]
    const res = cfg?.resource
    // ONE thing moves with the bar: the RADIUS. `dim` is a flat opacity for whatever lies outside
    // it — ramping it too was tried and rejected in play ("I want the light radius to fade, not the
    // whole screen"), and measured as a no-op anyway.
    const a = res?.dark ? res.dark.dim : 0
    if (a <= 0.004) { darkLayer.visible = false; return }  // no dark in this chapter: no per-frame rebuild
    const w = app.screen.width, h = app.screen.height
    // The player is the lamp. Screen space, via the same (world + c) convention every cull below
    // uses — NOT viewW()/2, which is only the player's position in the chapters that centre the
    // camera (a lane chapter sits them low, see cy above).
    const px = run.player.x + cx, py = run.player.y + cy
    // The light, as the chapter states it: a fraction of the screen's LONGEST SIDE, linear in the
    // bar. Screen-relative because a px count means a different mechanic on every device.
    // run.chargeMax (v7.x Book 2 Task 9 fix round): Deep Lungs' own ceiling, not the config max —
    // omitting this pins the light at radiusFull for the whole band above the OLD max, motionless.
    const R = lightRadius(run.charge, res, Math.max(w, h), run.chargeMax)
    // Nothing to draw once the FULLY-LIT core alone reaches the farthest corner. The falloff runs
    // from LIGHT_CORE_FRAC x R out to R, so that core is the only part guaranteed to be untouched.
    const corner = Math.max(Math.hypot(px, py), Math.hypot(w - px, py),
                            Math.hypot(px, h - py), Math.hypot(w - px, h - py))
    if (R * LIGHT_CORE_FRAC >= corner) { darkLayer.visible = false; return }
    darkLayer.visible = true

    // The lightmap, in its own tiny space. The buffer tracks the screen's ASPECT, so the single
    // scale `s` below serves both axes and a light stays round instead of going oval on a phone.
    // The texture source has to be resized alongside the canvas or it keeps sampling the old frame
    // after a device rotation; the 2D context's own state is wiped by the resize, and everything
    // below re-sets what it needs anyway.
    const bh = Math.max(1, Math.round(DARK_MAP_W * h / w))
    if (darkCanvas.height !== bh) {
      darkCanvas.height = bh
      darkTex.source.resize(DARK_MAP_W, bh)
    }
    const s = DARK_MAP_W / w   // screen px -> buffer px
    // The unlit colour: the chapter's tint lerped out of white by `dim`, so dim 1 IS the tint and
    // dim 0 leaves the scene untouched. `a` is that dim (see the top of this function).
    const tint = cfg.render?.darkTint ?? 0x02131f
    const chan = (c, lit) => Math.round(255 + (c * (1 - lit) + 255 * lit - 255) * a)
    const rgbAt = (lit) => `rgb(${chan(tint >> 16 & 255, lit)},${chan(tint >> 8 & 255, lit)},${chan(tint & 255, lit)})`
    darkCtx.fillStyle = rgbAt(0)
    darkCtx.fillRect(0, 0, DARK_MAP_W, bh)

    // The player's lamp: a per-frame radial gradient between white and that dark, in OPAQUE colour.
    // Built here rather than stamped from a bake, because a drawImage of an offscreen canvas is the
    // exact operation that produced nothing on the owner's device (see darkLayer's block). This is
    // the same primitive as the shafts below, which did render there.
    const lampR = Math.max(1, R * s)
    const grad = darkCtx.createRadialGradient(px * s, py * s, 0, px * s, py * s, lampR)
    grad.addColorStop(0, '#fff')
    DARK_RAMP.forEach((d, i) => {
      const t = LIGHT_CORE_FRAC + (1 - LIGHT_CORE_FRAC) * (i / (DARK_RAMP.length - 1))
      grad.addColorStop(t, rgbAt(1 - d))
    })
    darkCtx.fillStyle = grad
    // A DISC, not the rect: a radial gradient clamps to its last stop past its outer radius, so
    // filling the rect would paint the rim's colour into the corners instead of the dark.
    darkCtx.beginPath()
    darkCtx.arc(px * s, py * s, lampR, 0, Math.PI * 2)
    darkCtx.fill()

    darkCtx.fillStyle = '#fff'
    for (const sh of run.shafts) {
      const sx = sh.x + cx, sy = sh.y + cy
      if (sx + sh.r < 0 || sx - sh.r > w || sy + sh.r < 0 || sy - sh.r > h) continue
      // Hard discs, not blobs: a shaft is a pool of full daylight with an edge you can stand on the
      // wrong side of, and sim.js tests that radius exactly (stepCharge).
      darkCtx.beginPath()
      darkCtx.arc(sx * s, sy * s, sh.r * s, 0, Math.PI * 2)
      darkCtx.fill()
    }
    darkTex.source.update()
    darkSprite.setSize(w, h)
    // Neither tinted nor faded: the COLOUR is the darkness and the sprite is opaque. Doing either
    // here would put the effect back onto the channel that broke.
    darkSprite.tint = 0xffffff
    darkSprite.alpha = 1
  }

  // ---------------------------------------------------------------- storm overlay
  // Night-thunderstorm overlay: three cosmetic, pooled layers on the CURRENT_VIS idiom (pooled
  // sprites, respawn-in-view, fade envelopes). Render-only — reads run.chapter (via chapterHasStorm/
  // chapterHasRain, latched in reset()) and the camera offset, writes nothing back to run.
  //   cloudShadowLayer — big dark blobs, `world` child between floorLayer/entitiesLayer, so they
  //     dim the ground but sit under obstacles/enemies/player. STORM ONLY (chapterHasStorm).
  //   stormCloudLayer  — the same blob texture again, lighter and bigger, stage-level and drawn
  //     OVER everything; its container is offset by only STORM_VIS.cloud.parallaxFactor of the
  //     camera move (see updateStorm) so it visibly lags the ground — the altitude/depth cue.
  //     STORM ONLY (chapterHasStorm).
  //   stormRainLayer   — short streaks, plain screen-space wind-wrap (own function below). v6.3:
  //     gated on chapterHasRain (= storm || render.rain), NOT chapterHasStorm — city gets wet
  //     asphalt without either cloud layer. updateRain used to be called only from inside
  //     updateStorm's early-return, so a chapter with `rain: true` but no `storm` could never reach
  //     it; it is now its own top-level call from sync(), right next to updateStorm.
  // ponytail: one shared wind vector (STORM_VIS.windAngle), not a turbulence field — legible and
  // cheap; nothing here asked for per-blob wind noise.
  function makeDriftPool(container, count, tex) {
    const items = []
    for (let i = 0; i < count; i++) {
      const s = new Sprite(tex)
      s.anchor.set(0.5)
      s.visible = false
      container.addChild(s)
      items.push({ s, x: 0, y: 0, age: 0, life: 0, scaleMul: 1, spawned: false })
    }
    return items
  }
  const cloudShadows = makeDriftPool(cloudShadowLayer, STORM_VIS.shadow.count, T.stormBlob)
  const stormClouds = makeDriftPool(stormCloudLayer, STORM_VIS.cloud.count, T.stormBlob)

  // Drop a drift blob at a fresh spot in the current view (viewX/viewY = world coords of the
  // screen's top-left corner this frame) — same idea as respawnStreak above.
  function respawnDrift(p, cfg, viewX, viewY, w, h) {
    p.x = viewX + Math.random() * w
    p.y = viewY + Math.random() * h
    p.age = 0
    p.life = cfg.life * (1 + (Math.random() * 2 - 1) * cfg.lifeJitter)
    p.scaleMul = 1 + (Math.random() * 2 - 1) * cfg.sizeJitter
    p.spawned = true
  }

  // Shared advect/fade loop for cloudShadows + stormClouds. camX/camY is whatever this layer's
  // sprites must add to their own (wind-drifted) local position to land on screen — used only for
  // the off-screen/respawn test, since the actual screen placement comes from the *container's*
  // position (cloudShadowLayer inherits `world`'s; stormCloudLayer gets the parallax offset set in
  // updateStorm) plus each sprite's own local (p.x, p.y).
  function updateDriftPool(items, cfg, tex, dt, dx, dy, camX, camY) {
    const w = app.screen.width
    const h = app.screen.height
    const mg = cfg.margin
    const viewX = -camX, viewY = -camY
    for (const p of items) {
      if (p.s.texture !== tex) p.s.texture = tex
      if (!p.spawned) respawnDrift(p, cfg, viewX, viewY, w, h)
      p.age += dt
      p.x += dx * dt
      p.y += dy * dt
      const sx = p.x + camX
      const sy = p.y + camY
      const off = sx < -mg || sx > w + mg || sy < -mg || sy > h + mg
      if (p.age >= p.life || off) { respawnDrift(p, cfg, viewX, viewY, w, h); continue }
      let env = 1
      if (p.age < cfg.fadeIn) env = p.age / cfg.fadeIn
      else if (p.age > p.life - cfg.fadeOut) env = Math.max(0, (p.life - p.age) / cfg.fadeOut)
      p.s.position.set(p.x, p.y)
      p.s.scale.set((cfg.sizePx / tex.width) * p.scaleMul)
      p.s.tint = cfg.tint
      p.s.alpha = cfg.alpha * env
      p.s.visible = true
    }
  }

  const rainDrops = []
  for (let i = 0; i < STORM_VIS.rain.count; i++) {
    const s = new Sprite(Texture.EMPTY)
    s.anchor.set(0.5)
    s.visible = false
    stormRainLayer.addChild(s)
    rainDrops.push({ s, x: hash(i * 3.71 + 0.6), y: hash(i * 5.93 + 1.3) })
  }
  let stormTexReady = false

  // Rain: plain SCREEN-space wind-wrap (same trick as updateDustMotes above), not world-space
  // advection like the two drift-blob layers — rain doesn't sample or need to track any world
  // position, so the respawn-in-view machinery above would be pure overhead here.
  // v6.3: gated on chapterHasRain, independent of updateStorm/chapterHasStorm — see this section's
  // doc comment above. clearStorm/setMapMode also hide stormRainLayer directly; this is the
  // per-frame gate for ordinary play.
  function updateRain(dt) {
    if (!chapterHasRain) { stormRainLayer.visible = false; return }
    stormRainLayer.visible = true
    if (!stormTexReady && T.fx && T.fx.trace_05) stormTexReady = true
    if (!stormTexReady) return
    const w = app.screen.width
    const h = app.screen.height
    const wind = STORM_VIS.windAngle
    const vx = Math.cos(wind) * STORM_VIS.rain.speed
    const vy = Math.sin(wind) * STORM_VIS.rain.speed
    const lx = fxScale(T.fx.trace_05, STORM_VIS.rain.lenPx)
    const ly = fxScale(T.fx.trace_05, STORM_VIS.rain.widthPx)
    for (const d of rainDrops) {
      if (d.s.texture !== T.fx.trace_05) { d.s.texture = T.fx.trace_05; d.s.scale.set(lx, ly) }
      d.x += (vx * dt) / w
      d.y += (vy * dt) / h
      if (d.x > 1.1) d.x -= 1.2
      if (d.x < -0.1) d.x += 1.2
      if (d.y > 1.1) d.y -= 1.2
      if (d.y < -0.1) d.y += 1.2
      d.s.position.set(d.x * w, d.y * h)
      d.s.rotation = wind
      d.s.tint = STORM_VIS.rain.tint
      d.s.alpha = STORM_VIS.rain.alpha
      d.s.visible = true
    }
  }

  // v6.3: rain now lives OUTSIDE this function (own top-level updateRain(dt) call from sync(), see
  // this section's doc comment) — updateStorm keeps ONLY the two cloud layers, which stay
  // chapterHasStorm-gated (skies only). Calling updateRain from here too would just be a second,
  // redundant call on storm chapters — sync() calls it unconditionally right after this.
  function updateStorm(run, dt, cx, cy) {
    if (!chapterHasStorm) {
      cloudShadowLayer.visible = false
      stormCloudLayer.visible = false
      return
    }
    cloudShadowLayer.visible = true
    stormCloudLayer.visible = true

    const wind = STORM_VIS.windAngle
    const wx = Math.cos(wind)
    const wy = Math.sin(wind)

    // ground shadows: a `world` child, so its container already carries the full camera offset —
    // camX/camY here is only needed for the drift loop's own off-screen test.
    updateDriftPool(cloudShadows, STORM_VIS.shadow, T.stormBlob, dt,
      wx * STORM_VIS.shadow.speed, wy * STORM_VIS.shadow.speed, cx, cy)

    // overhead clouds: stage-level, so THIS container's position carries the (reduced) camera
    // offset — derived straight from the same cx,cy sync() uses for world.position, scaled by
    // parallaxFactor so the clouds visibly lag the ground as the camera pans.
    const pcx = cx * STORM_VIS.cloud.parallaxFactor
    const pcy = cy * STORM_VIS.cloud.parallaxFactor
    stormCloudLayer.position.set(pcx, pcy)
    updateDriftPool(stormClouds, STORM_VIS.cloud, T.stormBlob, dt,
      wx * STORM_VIS.cloud.speed, wy * STORM_VIS.cloud.speed, pcx, pcy)
  }

  function clearStorm() {
    cloudShadowLayer.visible = false
    stormCloudLayer.visible = false
    stormRainLayer.visible = false // v6.3: still hidden here even though it's no longer this
                                    // function's own latch — a chapter switch must not leave rain
                                    // streaks on screen for a frame before the next updateRain(dt)
                                    // corrects it.
    for (const p of cloudShadows) { p.s.visible = false; p.spawned = false }
    for (const p of stormClouds) { p.s.visible = false; p.spawned = false }
  }

  // ==============================================================================================
  // SKIES v5.10 — the crush ledger, the light layer, and the second particle pool
  // ==============================================================================================

  // ---- the second particle pool (spec §1.2) ----------------------------------------------------
  // MAX_PARTICLES is ONE global 200-slot ring buffer and particleCursor wraps SILENTLY. Adding
  // persistent missile smoke, crush dust and artillery clods to it would evict every hit/kill/
  // pickup particle in the game, with no error and no way to notice but by eye. Same shape, own
  // cap, own layer, and ONLY those three effects may use it.
  const smokeParticles = []
  for (let i = 0; i < SKIES_SMOKE.max; i++) {
    smokeParticles.push({ s: null, live: false, x: 0, y: 0, vx: 0, vy: 0, life: 0, maxLife: 0, scale: 1, grow: 0, drag: 0, grav: 0, spin: 0, fade: 1, tintB: null })
  }
  let smokeCursor = 0
  function spawnSmoke(tex, x, y, vx, vy, life, scale, tint, grow = 0, drag = 0, grav = 0, spin = 0, fade = 1, tintB = null) {
    const p = smokeParticles[smokeCursor]
    smokeCursor = (smokeCursor + 1) % SKIES_SMOKE.max
    if (!p.s) { p.s = new Sprite(tex); p.s.anchor.set(0.5); smokeLayer.addChild(p.s) }
    if (p.s.texture !== tex) p.s.texture = tex
    p.live = true; p.x = x; p.y = y; p.vx = vx; p.vy = vy
    p.life = life; p.maxLife = life; p.scale = scale; p.grow = grow; p.drag = drag; p.grav = grav
    p.spin = spin; p.fade = fade; p.tintB = tintB
    p.s.visible = true; p.s.tint = tint; p.s.rotation = Math.random() * Math.PI * 2
    p.tintA = tint
  }
  function updateSmoke(dt) {
    if (dt === 0) return
    for (const p of smokeParticles) {
      if (!p.live) continue
      p.life -= dt
      if (p.life <= 0) { p.live = false; p.s.visible = false; continue }
      const k = p.drag > 0 ? Math.max(0, 1 - p.drag * dt) : 1
      p.vx *= k
      p.vy = p.vy * k + p.grav * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.scale += p.grow * dt
      p.s.position.set(p.x, p.y)
      p.s.scale.set(Math.max(0.001, p.scale))
      p.s.rotation += p.spin * dt
      const age = 1 - p.life / p.maxLife
      // a smoke ribbon COOLS as it ages: near-tint -> far-tint, which is what makes a corkscrew
      // read as one continuous trail rather than a row of identical dots
      if (p.tintB !== null) p.s.tint = mix(p.tintA, p.tintB, age)
      p.s.alpha = Math.min(1, (p.life / p.maxLife) * p.fade)
    }
  }
  function clearSmoke() {
    for (const p of smokeParticles) { p.live = false; if (p.s) p.s.visible = false }
  }

  // ---- the crush ledger (spec §7.5) ------------------------------------------------------------
  // ONE render-local structure serving THREE features, which is what makes it worth having:
  //   1. the permanent kind-specific ruin + foundation scar left at the site (§5.9);
  //   2. the LAMP BLACKOUT — kerb lamps near an entry render at alpha 0, so ploughing an avenue
  //      leaves a DEAD BLACK CORRIDOR through a lit grid. That corridor is this chapter's whole
  //      fantasy expressed as a lighting state, and it costs one distance test;
  //   3. searchlight anchor invalidation — crush the tower, kill the light.
  // NEVER written back to `run`: render.js does not mutate sim state, and the obstacle is gone from
  // run.obstacles by the time any of this draws, so the ledger is keyed by WORLD POSITION.
  const crushLedger = new Map()
  function ledgerKey(x, y) {
    const c = SKIES_LIGHT.ledger.cellPx
    return Math.round(x / c) + ',' + Math.round(y / c)
  }
  function ledgerAdd(x, y, kind, r) {
    const L = SKIES_LIGHT.ledger
    crushLedger.set(ledgerKey(x, y), { x, y, kind: RUIN_FOR_KIND[kind] || 'tower', r })
    if (crushLedger.size <= L.cap) return
    // over cap: evict the entry farthest from the player (and anything past dropPx outright)
    let worstKey = null, worstD = -1
    for (const [k, e] of crushLedger) {
      const d = (e.x - playerX) ** 2 + (e.y - playerY) ** 2
      if (d > L.dropPx * L.dropPx) { crushLedger.delete(k); continue }
      if (d > worstD) { worstD = d; worstKey = k }
    }
    if (crushLedger.size > L.cap && worstKey) crushLedger.delete(worstKey)
  }
  // The crushed structure's radius, for sizing its ruin. By the time the event reaches us the
  // obstacle is already out of run.obstacles — but syncObstacles has not rebuilt yet this frame
  // (sync() drains events first), so the sprite rig still holds last frame's x/y/r.
  function radiusAtCrush(x, y) {
    for (const ov of obstacleSprites) {
      if (!ov.root.visible) continue
      if (Math.abs(ov.x - x) < 2 && Math.abs(ov.y - y) < 2) return ov.r
    }
    return 16
  }
  const ruinSprites = []
  function updateRuins(cx, cy) {
    let n = 0
    if (chapterHasRuins) {
      const w = viewW(), h = viewH()
      for (const e of crushLedger.values()) {
        const sx = e.x + cx, sy = e.y + cy
        if (sx < -160 || sx > w + 160 || sy < -160 || sy > h + 160) continue
        while (ruinSprites.length <= n) {
          const s = new Sprite(Texture.EMPTY); s.anchor.set(0.5); ruinLayer.addChild(s); ruinSprites.push(s)
        }
        const look = T.skRuin[e.kind] || T.skRuin.tower
        const s = ruinSprites[n++]
        s.visible = true
        s.texture = look.tex
        s.anchor.set(look.ax, look.ay)
        s.tint = 0xffffff
        s.alpha = 1
        s.rotation = 0
        s.scale.set((e.r * SKIES_PLAN_SCALE) / (SKR * 2))
        s.position.set(e.x, e.y)
      }
    }
    for (let i = n; i < ruinSprites.length; i++) ruinSprites[i].visible = false
  }

  // ---- junctions (spec §4.3) — enumerated from the latched grid origin -------------------------
  const junctionSprites = []
  for (let i = 0; i < ROAD_JUNCTION.pool; i++) {
    const s = new Sprite(Texture.EMPTY); s.anchor.set(0.5); s.visible = false
    junctionLayer.addChild(s); junctionSprites.push(s)
  }
  function updateJunctions(cx, cy) {
    let n = 0
    if (chapterHasRoads && T.junction) {
      const w = viewW(), h = viewH()
      const x0 = -cx - 90, y0 = -cy - 90, x1 = -cx + w + 90, y1 = -cy + h + 90
      {
        for (let ui = Math.ceil(x0 / BLOCK_U); ui * BLOCK_U <= x1 && n < junctionSprites.length; ui++) {
          for (let vi = Math.ceil(y0 / BLOCK_V); vi * BLOCK_V <= y1 && n < junctionSprites.length; vi++) {
            const p = { x: ui * BLOCK_U, y: vi * BLOCK_V }
            // A grid node inside the radius can still fall outside the street area — the urban
            // falloff is noise-wobbled, so the outermost nodes have no pavement under them. Asking
            // roadAt is the one check guaranteed to agree with the carriageway updateStreets drew.
            if (!roadAt(p.x, p.y, roadSeed, chapterEndlessGrid).onRoad) continue
            // Class comes straight from the grid index, the same test roadAt itself uses — no probe.
            const E = STREET_SPACING_MAJOR_EVERY
            const uMajor = ((ui % E) + E) % E === 0
            const vMajor = ((vi % E) + E) % E === 0
            const look = T.junction[(uMajor ? 'major' : 'minor') + (vMajor ? 'Major' : 'Minor')]
            const s = junctionSprites[n++]
            s.visible = true
            s.texture = look.tex
            s.anchor.set(look.ax, look.ay)
            s.tint = 0xffffff
            s.alpha = 1
            s.rotation = 0   // baked axis-aligned, and the world grid is too
            s.scale.set(1)   // baked at TRUE world size
            s.position.set(p.x, p.y)
          }
        }
      }
    }
    for (let i = n; i < junctionSprites.length; i++) junctionSprites[i].visible = false
  }


  // ==============================================================================================
  // SKIES v5.10 — THE SIX THREAT SIGNATURES (spec §3)
  // ==============================================================================================
  // Six threats separated on THREE AXES AT ONCE — colour family, shape language, motion verb — with
  // NO TWO SHARING MORE THAN ONE AXIS. That constraint is the whole fix for "everything looks the
  // same", and it is also the acceptance test: a reviewer who has never played must be able to name
  // each threat from a still frame, and again from that frame in GREYSCALE.
  //
  //   strafe    | halogen + orange  | parallel hairlines + ellipse | travels ALONG a line
  //   missile   | magenta           | rotating diamond + helix     | flies AT you, trail persists
  //   artillery | dull olive/ochre  | square box + diagonal hatch  | FALLS; opposed shrink/grow
  //   sky       | violet            | leaning vector + chevron ring| DESCENDS then cracks; sparks rise
  //   crush     | grey/material     | squashed skirt + hard shards | SLOW settle; adds geometry
  //   rampage   | atomic cyan       | rings + dorsal plates        | sustained pulse OUT FROM YOU
  //
  // Every INCOMING threat also carries exactly ONE travelling element that arrives on the exact
  // frame damage lands (the ARRIVAL CLOCK), so the player reads four clocks at four speeds instead
  // of "the circle got brighter". Each clock's duration IS the sim fuse, by reference.

  // The shadow-stroke rule (spec §2): draw every threat stroke TWICE — near-black underneath at
  // width + widen, then the colour on top. This is what lets six SATURATED palettes stay legible
  // over six district floor tints without raising alpha; the alternative is mid-tint mush.
  function inkStroke(g, path, width, color, alpha) {
    path(); g.stroke({ width: width + SKIES_INK.widen, color: SKIES_INK.color, alpha: SKIES_INK.alpha * (alpha ?? 1), join: 'round', cap: 'round' })
    path(); g.stroke({ width, color, alpha, join: 'round', cap: 'round' })
  }
  // Telegraph LOD (spec §3.2): beyond this distance a glyph degrades to its impact mark alone. The
  // far ones carry no information a distant player can act on anyway, and SHELL_MAX_LIVE +
  // MAX_STRAFE_LOCKS glyphs of graduated ticks drawn live do not hold on a phone.
  function farFromPlayer(x, y) {
    const dx = x - playerX, dy = y - playerY
    return dx * dx + dy * dy > SKIES_TELEGRAPH_LOD_PX * SKIES_TELEGRAPH_LOD_PX
  }

  // RAMPAGE JAMMING (spec §3, rampage row): while you are rampaging, every ENEMY telegraph visibly
  // breaks up — you are not merely stronger, their targeting is failing. On rampage END the dropout
  // decays to 0 so the picture RE-ACQUIRES; a hard snap back reads as a rendering bug.
  function jamDrop() { return jamT > 0 && Math.random() < SKIES_JAM.dropout * jamT }
  function jamAlpha(a) { return jamT > 0 ? a * (SKIES_JAM.alphaMin + SKIES_JAM.alphaJitter * Math.random()) : a }

  // ---- 1. TANK ARTILLERY + 2. SKY BOMBARDMENT + 3. VOLATILE ELITE BOMB (run.bombs) --------------
  // v5.10.1 P0 fix: sim.js now pushes an explicit `src: 'gun'|'sky'|'volatile'` on every run.bombs
  // entry (the three push sites, additive fields only — see sim.js). bombSrc used to INFER the
  // source from `duration` matching one of two known fuses and silently treated anything else
  // (volatile elites) as "keep the generic drawer" — which routed a dead elite's corpse-bomb through
  // the FORBIDDEN red telegraph (config.js SKIES_PALETTE.alert is reserved for alert-only) and then,
  // on detonation, through the `else` branch of the explode handler straight into skyDetonation: a
  // volatile elite's death was drawn as the sky's own lightning strike, full-field flash included, in
  // the one chapter whose whole premise is telling the two apart. Reading `b.src` directly instead of
  // guessing from a timing coincidence fixes both halves at once.
  function bombSrc(b) {
    if (!chapterHasStorm) return null
    return b.src === 'gun' || b.src === 'sky' || b.src === 'volatile' ? b.src : null
  }
  // Artillery's trajectory ghost now reads `b.ox`/`b.oy` — the firing tank's own position, set by sim
  // the instant the shell is pushed (sim.js). This used to be a render-side heuristic
  // (`latchBombOrigin`, scanning every artillery enemy for whichever currently held the globally
  // highest `e._shellT`) that a reviewer caught attaching the trajectory ghost + muzzle flash to the
  // wrong, sometimes off-screen, tank whenever an idle tank's timer simply outranked the one that had
  // actually just fired, or whenever two tanks fired the same frame. A per-bomb field sim already has
  // is authoritative; render no longer needs to guess. `firedMuzzle` only tracks "have we already
  // popped this bomb's one-shot muzzle flash", not the origin itself.
  const firedMuzzle = new WeakSet()
  function maybeSpawnMuzzleFlash(b) {
    if (b.src !== 'gun' || firedMuzzle.has(b)) return
    firedMuzzle.add(b)
    spawnParticle(T.muzzleFlash.tex, b.ox, b.oy, 0, 0, SKIES_FX.artillery.muzzleT,
      0.10, SKIES_FX.artillery.muzzle, 0.4, 0)     // muzzle flash: 0.06 s, at the gun that fired
  }

  const shellRigs = []
  function acquireShellRig() {
    const box = new Sprite(T.tgSquare.tex); box.anchor.set(T.tgSquare.ax, T.tgSquare.ay)
    const fill = new Sprite(T.tgHandFill.tex); fill.anchor.set(T.tgHandFill.ax, T.tgHandFill.ay)
    const bars = new Sprite(T.tgHandBars.tex); bars.anchor.set(T.tgHandBars.ax, T.tgHandBars.ay)
    const shadow = new Sprite(T.shellShadow.tex); shadow.anchor.set(0.5)
    shellLayer.addChild(shadow, fill, bars, box)
    const rig = { box, fill, bars, shadow }
    shellRigs.push(rig)
    return rig
  }
  const skyRigs = []
  function acquireSkyRig() {
    const wash = new Sprite(T.skyIonWash.tex); wash.anchor.set(0.5)
    const ring = new Sprite(T.skyChevrons.tex); ring.anchor.set(T.skyChevrons.ax, T.skyChevrons.ay)
    skyLayer.addChild(wash, ring)
    const rig = { wash, ring }
    skyRigs.push(rig)
    return rig
  }
  const voltRigs = []
  function acquireVoltRig() {
    const ring = new Sprite(T.voltRing.tex); ring.anchor.set(T.voltRing.ax, T.voltRing.ay)
    const core = new Sprite(T.voltCore); core.anchor.set(0.5)   // small pulsing unstable core
    voltLayer.addChild(core, ring)
    const rig = { ring, core }
    voltRigs.push(rig)
    return rig
  }

  function drawSkiesBombs(run) {
    const AF = SKIES_FX.artillery
    const SF = SKIES_FX.sky
    const VF = SKIES_FX.volatile
    let si = 0, ki = 0, vi = 0
    for (const b of run.bombs) {
      const src = bombSrc(b)
      if (src === null) continue
      const k = b.duration > 0 ? 1 - Math.max(0, b.fuse) / b.duration : 1   // 0 -> 1 over the fuse
      const far = farFromPlayer(b.x, b.y)
      if (src === 'volatile') {
        // ==== P0 fix: volatile elites used to fall through to the generic RED bomb circle (the
        // forbidden telegraph colour) and then detonate as a re-tinted lightning strike. This threat
        // now has its own colour (acid green — unclaimed by any of the six main threats, the alert
        // red or the ambience gold), its own shape (a toothed ring), and its own motion: it GROWS and
        // destabilises rather than closing inward like gun/sky, so the motion axis differs too.
        const rig = voltRigs[vi++] || acquireVoltRig()
        const pulseHz = 6 + k * 18   // pulses faster as it nears detonation — "going unstable"
        const pulse = 0.5 + 0.5 * Math.sin(animT * pulseHz)
        const jitter = k > 0.6 ? (Math.random() - 0.5) * (k - 0.6) * 30 : 0
        rig.ring.visible = true
        rig.ring.tint = VF.ring
        rig.ring.alpha = jamAlpha(0.4 + 0.45 * k + 0.15 * pulse)
        rig.ring.scale.set((b.radius * (0.5 + 0.55 * k)) / T.voltRing.ref)   // GROWS, not shrinks
        rig.ring.rotation = k * Math.PI * 0.6
        rig.ring.position.set(b.x + jitter, b.y + jitter)
        rig.core.visible = !far
        rig.core.tint = VF.core
        rig.core.alpha = jamAlpha(0.5 + 0.5 * pulse)
        const coreR = 8 + 16 * k
        rig.core.scale.set((coreR * 2) / 48)
        rig.core.position.set(b.x, b.y)
        continue
      }
      if (src === 'gun') {
        // ==== the only SQUARE telegraph, the only HATCHED fill, the only DESATURATED one, and the
        // only one that draws a curved line back to a GROUND ORIGIN. That last part is the
        // mass-read: a screenful of shells visibly RADIATES from scattered tanks, where a screenful
        // of sky strikes is all-parallel.
        const rig = shellRigs[si++] || acquireShellRig()
        const elite = b.radius >= ARTILLERY_ELITE_RADIUS - 1
        // ARRIVAL CLOCK, part 1: the brackets SHRINK INWARD onto the impact point...
        const boxR = b.radius * (1.55 - 0.55 * k)
        rig.box.visible = true
        rig.box.tint = AF.bracket
        rig.box.alpha = jamAlpha(AF.bracketAlpha + AF.bracketAlphaRamp * k)
        rig.box.scale.set(boxR / T.tgSquare.ref)
        rig.box.position.set(b.x, b.y)
        rig.box.rotation = 0
        // ...part 2: the hatched hand sweeps EXACTLY 360 degrees over the fuse and completes on
        // impact. Two opposed motions locking on the same frame is the whole read.
        const hand = k * Math.PI * 2 - Math.PI / 2
        for (const [sp, tint, alpha] of [[rig.fill, AF.hatchFill, AF.hatchAlpha], [rig.bars, AF.hatchBar, AF.hatchBarAlpha]]) {
          sp.visible = !far
          sp.tint = tint
          sp.alpha = jamAlpha(alpha)
          sp.rotation = hand
          sp.scale.set(b.radius / T.tgHandFill.ref)
          sp.position.set(b.x, b.y)
        }
        // ...part 3: the falling shell's OWN shadow grows from 4px to the full blast radius
        rig.shadow.visible = true
        rig.shadow.tint = AF.shellShadow
        rig.shadow.alpha = AF.shellShadowAlpha * (0.35 + 0.65 * k)
        const shR = lerp(AF.shadowStartPx, b.radius * 0.9, k * k)
        rig.shadow.scale.set(shR / T.shellShadow.ref)
        rig.shadow.position.set(b.x, b.y)
        if (elite) {   // AA-turret elites: a radar-green tick on the bracket, nothing else changes
          bombG.circle(b.x, b.y - boxR, 3.2).fill({ color: AF.eliteTick, alpha: 0.9 })
        }
        maybeSpawnMuzzleFlash(b)   // one-shot, gated by the firedMuzzle WeakSet
        // the trajectory ghost, arcing back to the gun that fired it — b.ox/b.oy are the ACTUAL
        // shooter (sim.js sets them at spawn), not a render-side guess
        if (!far && !jamDrop() && b.ox != null && b.oy != null) {
          const mx = (b.ox + b.x) / 2, my = (b.oy + b.y) / 2 - Math.hypot(b.x - b.ox, b.y - b.oy) * 0.28
          inkStroke(bombG, () => { bombG.moveTo(b.ox, b.oy); bombG.quadraticCurveTo(mx, my, b.x, b.y) },
            1.6, AF.ghost, jamAlpha(AF.ghostAlpha))
        }
      } else {
        // ==== the only VIOLET thing, the only MASS-PARALLEL telegraph, the only BRANCHING fractal,
        // and the only telegraph whose particles RISE. Parallelism is the whole composition: a
        // screenful of vectors all leaning at STORM_VIS.windAngle says THE SKY IS FIRING.
        const rig = skyRigs[ki++] || acquireSkyRig()
        rig.ring.visible = true
        rig.ring.tint = SF.ring
        rig.ring.alpha = jamAlpha(0.22 + 0.48 * k)   // v5.13: dimmer early, so a strike EARNS its
                                                      // attention as the fuse burns down instead of
                                                      // announcing itself at full strength on frame 1
        rig.ring.scale.set((b.radius * (1.7 - 0.7 * k)) / T.skyChevrons.ref)   // closing inward
        rig.ring.position.set(b.x, b.y)
        rig.wash.visible = true
        rig.wash.tint = SF.ionisation
        rig.wash.alpha = SF.ionisationAlpha * (0.4 + 0.6 * k)
        rig.wash.scale.set((b.radius * 0.95) / T.skyIonWash.ref)
        rig.wash.position.set(b.x, b.y)
        if (!far) {
          // the descent vector, LEANED ALONG THE WIND so every simultaneous strike is parallel
          const wa = STORM_VIS.windAngle
          const ux = -Math.cos(wa), uy = -Math.sin(wa)
          const topX = b.x + ux * SF.dropPx, topY = b.y + uy * SF.dropPx
          if (!jamDrop()) {
            inkStroke(bombG, () => { bombG.moveTo(topX, topY); bombG.lineTo(b.x, b.y) },
              1.8, SF.descent, jamAlpha(0.30 + 0.35 * k))
          }
          // ARRIVAL CLOCK: a triple chevron slides DOWN the vector, ACCELERATING, and touches
          // ground exactly at fuse = 0
          const ease = Math.pow(k, SF.chevronAccel)
          for (let c = 0; c < SF.chevrons; c++) {
            if (jamDrop()) continue
            const d = SF.dropPx * (1 - ease) + c * SF.chevronGapPx
            if (d > SF.dropPx) continue
            const cx = b.x + ux * d, cy = b.y + uy * d
            const px2 = -uy, py2 = ux
            // arms trail back UP the vector so the chevron's tip points DOWN, at the ground it is
            // about to hit — an arrow pointing back at the sky says exactly the wrong thing
            inkStroke(bombG, () => {
              bombG.moveTo(cx + px2 * 9 + ux * 11, cy + py2 * 9 + uy * 11)
              bombG.lineTo(cx, cy)
              bombG.lineTo(cx - px2 * 9 + ux * 11, cy - py2 * 9 + uy * 11)
            }, 2.4, SF.descent, jamAlpha(0.85 - c * 0.22))
          }
        }
        // crackling spark ticks on the perimeter — they travel UP, always. Nothing else in the
        // chapter has particles that rise, which is the whole point of the axis.
        if (!far) {
          const tick = Math.floor(animT * 14)
          for (let s = 0; s < SF.sparkTicks; s++) {
            if ((s % 3) !== (tick % 3)) continue
            const a = (s / SF.sparkTicks) * Math.PI * 2 + k * 1.5
            const rr = b.radius * (0.9 + 0.12 * hash(s * 3.1 + tick))
            const lift = 5 + 11 * hash(s * 7.7 + tick * 1.3)
            const sx = b.x + Math.cos(a) * rr, sy = b.y + Math.sin(a) * rr
            bombG.moveTo(sx, sy)
            bombG.lineTo(sx + (hash(s * 2.3 + tick) - 0.5) * 4, sy - lift)
            bombG.stroke({ width: 2.2, color: SF.boltCore, alpha: jamAlpha(0.35 + 0.55 * k), cap: 'round' })
          }
        }
      }
    }
    for (let i = si; i < shellRigs.length; i++) {
      const r = shellRigs[i]; r.box.visible = false; r.fill.visible = false; r.bars.visible = false; r.shadow.visible = false
    }
    for (let i = ki; i < skyRigs.length; i++) { skyRigs[i].wash.visible = false; skyRigs[i].ring.visible = false }
    for (let i = vi; i < voltRigs.length; i++) { voltRigs[i].ring.visible = false; voltRigs[i].core.visible = false }
  }
  function clearSkiesBombs() {
    for (const r of shellRigs) { r.box.visible = false; r.fill.visible = false; r.bars.visible = false; r.shadow.visible = false }
    for (const r of skyRigs) { r.wash.visible = false; r.ring.visible = false }
    for (const r of voltRigs) { r.ring.visible = false; r.core.visible = false }
  }

  // Detonations. THREE completely separate drawers (v5.10.1 adds volatile) — a colour swap on one
  // drawer is exactly the bug.
  function artilleryDetonation(x, y, radius) {
    // BLACK-CORED fireball: ordnance, not a cartoon pop
    spawnParticle(T.artFireball.tex, x, y, 0, 0, 0.26, (radius / 90) * 0.9, 0xffffff, 1.2, 0)
    // ten ANGULAR clods on real parabolas, landing and leaving splash decals (they use the smoke
    // pool, so they cannot evict the game's hit/kill particles — spec §1.2)
    for (let i = 0; i < SKIES_FX.artillery.clodCount; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = 130 + Math.random() * 180
      spawnSmoke(T.clod.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp - 120,
        0.5 + Math.random() * 0.25, 0.7 + Math.random() * 0.5, SKIES_FX.artillery.clod,
        0, 0.6, SKIES_FX.crush.shardGravity, (Math.random() - 0.5) * 12)
    }
    addShake(3, 0.16)
  }
  function skyDetonation(x, y, radius) {
    const SF = SKIES_FX.sky
    const b = LIGHTNING.strikeBolt
    // the bolt itself keeps the shared spawnArc machinery (a jagged glow-then-core polyline
    // genuinely IS a bolt — shared MACHINERY, not a shared LOOK; it is retinted violet here)
    spawnArc(lightningBoltPath(x, y, b.dropPx, b.segments, b.jitterPx), SF.boltGlow, SF.boltCore, SF.boltDur, b.width, b.alpha)
    triggerLightningFlash(LIGHTNING.flash.strikeAlpha)
    // dendritic Lichtenberg branches BURNED INTO the ground — the only branching fractal in the game
    const look = T.branchTree[Math.floor(Math.random() * T.branchTree.length)]
    let s = null
    for (const c of scarSprites) if (!c.live) { s = c; break }
    if (!s && scarSprites.length < 12) {
      const sp = new Sprite(Texture.EMPTY); sp.anchor.set(0.5); scarLayer.addChild(sp)
      s = { sp, live: false, t: 0 }; scarSprites.push(s)
    }
    if (s) {
      s.live = true; s.t = SF.scarLife
      s.sp.visible = true
      s.sp.texture = look.tex
      s.sp.anchor.set(look.ax, look.ay)
      s.sp.tint = SF.scar
      s.sp.rotation = Math.random() * Math.PI * 2
      s.sp.scale.set((radius * 1.5) / look.ref)
      s.sp.position.set(x, y)
    }
    // sparks that RISE — T.sparkTick, a thin vertical streak (v5.10.1: was T.scorchTick, the same
    // small glyph missile's impact and the jet's ground scorch also used)
    for (let i = 0; i < 10; i++) {
      const a = Math.random() * Math.PI * 2
      spawnParticle(T.sparkTick.tex, x + Math.cos(a) * radius * 0.6, y + Math.sin(a) * radius * 0.6,
        (Math.random() - 0.5) * 40, -80 - Math.random() * 110, 0.4 + Math.random() * 0.2,
        0.8, SF.boltCore, -0.6, 1.2, 40)
    }
    addShake(3.4, 0.18)
  }
  // VOLATILE detonation (P0 fix): a hard acid-green spike burst + a fast-collapsing ring echo of its
  // own telegraph shape — NOT the artillery fireball (ochre/black) and NOT the sky bolt+scar+flash
  // (violet/white, full-field flash). No lightning, no fireball: a corpse going unstable, not ordnance
  // and not weather.
  function volatileDetonation(x, y, radius) {
    const VF = SKIES_FX.volatile
    for (let i = 0; i < VF.spikeCount; i++) {
      const a = (i / VF.spikeCount) * Math.PI * 2 + Math.random() * 0.3
      const sp = 160 + Math.random() * 140
      spawnParticle(T.voltSpike.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp,
        0.32 + Math.random() * 0.12, 1.0, VF.ring, -1.0, 0)
    }
    spawnParticle(T.voltCore, x, y, 0, 0, 0.22, 1.6, VF.core, 2.4, 0)
    addShake(2.6, 0.14)
  }
  const scarSprites = []
  function updateScars(dt) {
    for (const s of scarSprites) {
      if (!s.live) continue
      if (dt > 0) s.t -= dt
      if (s.t <= 0) { s.live = false; s.sp.visible = false; continue }
      s.sp.alpha = Math.min(1, s.t / SKIES_FX.sky.scarLife) * 0.55
    }
  }
  function clearScars() { for (const s of scarSprites) { s.live = false; s.sp.visible = false } }

  // ---- 3. HELICOPTER MISSILE (spec §3, missile row) --------------------------------------------
  // The only travelling PHYSICAL projectile, the only SPIRAL in the game, the only mark anchored to
  // the PLAYER, and the only magenta in any of the seven chapters.
  const lockDiamond = new Sprite(Texture.EMPTY)
  lockDiamond.anchor.set(0.5)
  lockDiamond.visible = false
  lockLayer.addChild(lockDiamond)
  function drawMissileLocks(run) {
    const M = SKIES_FX.missile
    if (!chapterHasStorm) { lockDiamond.visible = false; return }
    const p = run.player
    let locking = false
    let tightest = 1
    for (const e of run.enemies) {
      if (e._dead || !e.flags || !e.flags.includes('missileVolley')) continue
      const d = Math.hypot(p.x - e.x, p.y - e.y)
      if (d > MISSILE_FIRE_RANGE) continue
      const firing = (e._volleyLeft || 0) > 0
      const left = firing ? 0 : (e._volleyT ?? 99)
      if (left > M.lockT && !firing) continue
      locking = true
      const k = firing ? 1 : 1 - left / M.lockT       // 0 -> 1, reaching 1 on the LAUNCH frame
      tightest = Math.min(tightest, 1 - k)
      if (farFromPlayer(e.x, e.y) || jamDrop()) continue
      // the designation line from the helicopter's nose. v7.21: it used to carry a BEAD crawling
      // toward you as its arrival clock, and the bead was the single most misread mark in the
      // chapter — a small bright dot travelling from a helicopter to your feet is a PROJECTILE in
      // every visual language this genre has, so players read it as a missile that passed through
      // them and did nothing. The lock keeps its clock: the line brightens and the diamond on you
      // snaps tighter (both keyed to the same k), neither of which can be mistaken for a thing
      // being fired. The only travelling mark on this threat is now the dart itself, which is what
      // the four-clocks table above always claimed ("flies AT you").
      const ux = (p.x - e.x) / (d || 1), uy = (p.y - e.y) / (d || 1)
      const dash = 14
      for (let t = 0; t < d - 20; t += dash * 2) {
        if (jamDrop()) continue
        teleG.moveTo(e.x + ux * t, e.y + uy * t)
        teleG.lineTo(e.x + ux * Math.min(t + dash, d - 20), e.y + uy * Math.min(t + dash, d - 20))
      }
      teleG.stroke({ width: 1.4, color: M.designator, alpha: jamAlpha(0.5 + 0.3 * k) })
    }
    lockDiamond.visible = locking
    if (!locking) return
    if (lockDiamond.texture !== T.lockDiamond.tex) {
      lockDiamond.texture = T.lockDiamond.tex
      lockDiamond.anchor.set(T.lockDiamond.ax, T.lockDiamond.ay)
    }
    // DISCRETE SNAP STEPS, never a smooth lerp — a mechanical reticle, not an organic pulse, and it
    // reads at 4 fps of information, which survives being one of eighteen things on screen
    const steps = M.snapSteps
    const snapped = Math.round(tightest * steps) / steps
    const jitterX = jamT > 0 && (jamSnapT % SKIES_JAM.resnapEvery) < 0.05 ? (Math.random() - 0.5) * SKIES_JAM.resnapPx : 0
    const jitterY = jitterX ? (Math.random() - 0.5) * SKIES_JAM.resnapPx : 0
    lockDiamond.tint = M.designator
    lockDiamond.alpha = jamAlpha(0.9)
    lockDiamond.rotation = animT * 0.9
    lockDiamond.scale.set(lerp(0.7, 2.1, snapped))
    lockDiamond.position.set(run.player.x + jitterX, run.player.y + jitterY)
  }
  // the corkscrew smoke helix: MISSILE_TURN is 0, so the dart is dead straight and the SMOKE is
  // what curls. Lateral sine offset that GROWS as the puff ages = a corkscrew seen from above.
  const missileTrailT = []
  function updateMissileTrails(run, dt) {
    if (!chapterHasStorm || dt <= 0) return
    const M = SKIES_FX.missile
    const list = run.enemyShots || []
    // cap emission to the nearest live missiles — the pool budget is derived from exactly this
    const order = list.map((s, i) => [i, (s.x - playerX) ** 2 + (s.y - playerY) ** 2]).sort((a, b) => a[1] - b[1])
    for (let n = 0; n < Math.min(SKIES_SMOKE.emitters, order.length); n++) {
      const i = order[n][0]
      const sh = list[i]
      missileTrailT[i] = (missileTrailT[i] ?? 0) + dt
      if (missileTrailT[i] < SKIES_SMOKE.puffEvery) continue
      missileTrailT[i] -= SKIES_SMOKE.puffEvery
      const sp = Math.hypot(sh.vx, sh.vy) || 1
      const ux = sh.vx / sp, uy = sh.vy / sp
      const phase = animT * M.helixTurns * 6
      const side = Math.sin(phase)
      spawnSmoke(T.smokePuff, sh.x - ux * 8 + -uy * side * M.helixAmpPx, sh.y - uy * 8 + ux * side * M.helixAmpPx,
        -uy * side * M.helixGrowPx, ux * side * M.helixGrowPx, M.ribbonLife, 0.22, M.smokeNear,
        0.30, 0.7, 0, 0.6, M.smokeFar)
      // v5.10.1: was T.fx.flare_01, the same generic flare frostarc/shockarc/homing/beam reuse — one
      // of this chapter's own six threats gets its own dedicated exhaust bake instead.
      spawnParticle(T.exhaustPuff, sh.x - ux * 6, sh.y - uy * 6, 0, 0, 0.14, 0.07, M.exhaustHot, -0.15, 0)
    }
  }
  function missileImpact(x, y) {
    const M = SKIES_FX.missile
    spawnParticle(T.magentaStar.tex, x, y, 0, 0, 0.22, 1.0, M.impactCore, 1.6, 0)
    spawnSmoke(T.sootRing.tex, x, y, 0, 0, 0.9, 0.35, M.impactSoot, 0.7, 1.2, 0, 0.85)
    // T.impactFleck — a small radiating diamond (v5.10.1: was T.scorchTick, shared with sky's rising
    // sparks and the jet's ground scorch)
    for (let i = 0; i < 5; i++) {
      const a = Math.random() * Math.PI * 2
      spawnParticle(T.impactFleck.tex, x, y, Math.cos(a) * 150, Math.sin(a) * 150,
        0.22, 0.7, M.designator, 0, 4)
    }
    addShake(1.6, 0.1)
  }

  // ---- 4. CRUSH (spec §3, crush row) -----------------------------------------------------------
  // The ANTI-TELEGRAPH: no warning iconography at all, because it already happened and YOU did it.
  // The only DESATURATED event, the only SLOW one, the only one that REMOVES light, and the only
  // one that adds PERMANENT geometry. Replaces crushBurst's soft round Kenney circle_05/scorch_01
  // puff — soft round particles are precisely what makes a collapsing building read as a cartoon
  // dust cloud (kill list §8.4) — and drops the "fleeing figures" dots (spec §11).
  function skiesCrush(x, y, kind) {
    const C = SKIES_FX.crush
    const mat = C.byKind[kind] || C.byKind.tower
    const n = C.shardMin + Math.floor(Math.random() * (C.shardMax - C.shardMin + 1))
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = 90 + Math.random() * 150
      const tex = T.shard[Math.floor(Math.random() * T.shard.length)]
      // ANGULAR, hard-edged, with visible edges — and they arc back DOWN under fake gravity and
      // stop, rather than drifting away like smoke
      spawnSmoke(tex.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp - 90,
        C.burstT, 0.7 + Math.random() * 0.5, Math.random() < 0.4 ? mat.dustDark : mat.dust,
        0, 1.1, C.shardGravity, (Math.random() - 0.5) * 9)
    }
    // a LOW SQUASHED dust skirt hugging the ground (ratio 1 : 0.45), expanding then SINKING, and
    // then drifting downwind — not a mushroom
    const wa = STORM_VIS.windAngle
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = 26 + Math.random() * 38
      // Sized against the BUILDING, not against the screen: T.dustSkirt is a 256px canvas, so the
      // scale here has to stay small or a collapsing house throws a 380px cloud that whites out
      // half the view — which is exactly the soft-round-puff failure this rewrite exists to fix.
      spawnSmoke(T.dustSkirt, x, y, Math.cos(a) * sp + Math.cos(wa) * 12, Math.sin(a) * sp * C.skirtAspect + Math.sin(wa) * 12,
        C.dustT, 0.13 + Math.random() * 0.07, i % 2 ? mat.dustDark : mat.dust, 0.09, 0.9, 0, 0, 0.5)
    }
    // ONE beat of warm interior spill, then the site goes dark — the only time this chapter's
    // ambience colour appears anywhere near an event, and it lasts 0.35 s. T.crushSpill (v5.10.1: was
    // T.shellShadow, artillery's own falling-object shadow tinted gold — a soft SQUARE glow reads as
    // light bleeding from a window, which is what this beat actually represents)
    spawnParticle(T.crushSpill, x, y, 0, 0, C.spillT, 0.55, C.spill, -0.5, 0)
    addShake(1.2, 0.07) // light — crush can fire several times a second mid-rampage
  }

  // A coral head going under a Burst (v7.x, The Reef). Same {type:'crush'} event, same sim path,
  // completely different physics — see CORAL_CRUSH's block in config.js for why skiesCrush above
  // cannot be reused: it is dust, brick and window light, and it banks a permanent ruin in the
  // render-local ledger. Underwater there is no dust and nothing is left standing.
  //   chunks sink (positive gravity, high drag) — rock in water, thrown and then dropped;
  //   silt hangs and spreads (no gravity, long life, low alpha) — the cloud you cannot see through;
  //   bubbles RISE, and they are the only thing in the burst that moves against the fall, which is
  //     what sells the whole picture as being underwater rather than merely blue.
  // `r` is the coral's own radius, so the extent ring says exactly what was destroyed.
  function coralShatter(x, y, r) {
    const C = CORAL_CRUSH
    const k = Math.max(0.5, r / 110)   // sized against the bommie, not against the screen
    for (let i = 0; i < C.chunks; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = C.chunkSpeed + Math.random() * C.chunkSpread
      const tex = T.shard[Math.floor(Math.random() * T.shard.length)]
      spawnSmoke(tex.tex, x, y, Math.cos(a) * sp * k, Math.sin(a) * sp * k,
        C.chunkT, (0.5 + Math.random() * 0.45) * k,
        Math.random() < 0.45 ? C.chunkTintDark : C.chunkTint,
        0, 0.9, C.chunkGrav, (Math.random() - 0.5) * 8)
    }
    for (let i = 0; i < C.silt; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = C.siltSpeed * (0.5 + Math.random())
      spawnSmoke(T.fx.circle_05, x, y, Math.cos(a) * sp * k, Math.sin(a) * sp * k,
        C.siltT, (0.28 + Math.random() * 0.16) * k, C.siltTint, 0.16, 1.1, 0, 0, 0.45)
    }
    for (let i = 0; i < C.bubbles; i++) {
      const a = Math.random() * Math.PI * 2
      spawnParticle(T.fx.circle_05, x + Math.cos(a) * r * 0.5, y + Math.sin(a) * r * 0.5,
        Math.cos(a) * 26, -C.bubbleRise * (0.6 + Math.random() * 0.8),
        C.bubbleT, (0.05 + Math.random() * 0.05) * k, C.bubbleTint, 0.02, 0.7)
    }
    spawnRing(x, y, r, C.ringT, T.novaRing, C.ringTint)
    addShake(2.4 * k, 0.12)
  }

  // ---- 5. RAMPAGE (spec §3, rampage row) -------------------------------------------------------
  // A REGIME CHANGE, not an object added to the scene: the only sustained rhythmic effect, the only
  // one sourced AT THE PLAYER, the only cyan, and the only one that changes the LIGHTING STATE of
  // the whole region rather than drawing something new.
  const platePool = []
  for (let i = 0; i < SKIES_FX.rampage.plates; i++) {
    const s = new Sprite(Texture.EMPTY); s.anchor.set(0.5); s.visible = false
    // v5.11: children of bodyC, not playerC — bodyC now ROTATES to face the kaiju's facingAngle
    // (see syncPlayer), so a plate positioned in bodyC's own local "head-up" space (matching
    // drawKaijuBody's coordinate system exactly) automatically lands on the right spine point
    // no matter which way the kaiju is currently facing, with no extra transform math needed here.
    bodyC.addChild(s); platePool.push(s)
  }
  function updateRampage(run, dt) {
    const R = SKIES_FX.rampage
    rampG.clear()
    const active = chapterHasStorm && (run.rampageT || 0) > 0
    if (dt > 0) {
      jamSnapT += dt
      if (active) jamT = 1
      else jamT = Math.max(0, jamT - dt / SKIES_JAM.recoverT)
      if (active) rampBeatT += dt
    }
    // v5.16: the alert-red WAVE that flipped every searchlight to klaxon red went with the light
    // layer, and so did rampWaveR — the wave had exactly one consumer and it was those cones. The
    // rim-light sweep below is a separate thing: it keys off the crush radius, not the wave.
    if (!active) {
      rampBeatT = 0
      // v7.23: the dorsal plates are not rampage's private property any more. The Atomic Breath's
      // wind-up lights the SAME spine — that is what a charging kaiju looks like, and it is what
      // this weapon's own design doc promised before it shipped a bare ring instead. Rampage still
      // wins outright when both are live (it is a whole-run state, the breath is half a second),
      // which is why this sits in the not-active branch rather than fighting the loop above.
      if (!lightPlatesForBreath(run)) for (const s of platePool) s.visible = false
      return
    }
    const p = run.player
    const ringR = PLAYER.radius * R.ringMul
    // the HEARTBEAT: a ring rolled out to the TRUE widened crush radius, so the prettiest effect on
    // screen is also the honest hitbox. 0.6 s loop — the only looping effect in the chapter.
    // T.rampagePulse (v5.10.1: was T.novaRing — the SAME plain double-ring shared with revive and
    // shatter, both also 0.35-0.45s; rampage's "only looping effect" deserves a ring of its own, not a
    // recolor of two unrelated bursts. T.novaRing itself is untouched — it's cross-chapter machinery).
    if (rampBeatT >= R.beat) { rampBeatT -= R.beat; spawnRing(p.x, p.y, ringR, 0.45, T.rampagePulse, R.plateCool) }
    const beat = 1 - (rampBeatT / R.beat)
    rampG.circle(p.x, p.y, ringR).stroke({ width: 2 + 2 * beat, color: R.plateCool, alpha: 0.25 + 0.3 * beat })
    // a cyan RIM LIGHT on every structure inside the ring — the region lights up around you
    for (const ov of obstacleSprites) {
      if (!ov.root.visible) continue
      const d = Math.hypot(ov.x - p.x, ov.y - p.y)
      if (d > ringR + 30) continue
      rampG.circle(ov.x, ov.y, ov.r + 2).stroke({ width: 2, color: R.rimLight, alpha: R.rimAlpha * (1 - d / (ringR + 30)) })
    }
    // Seven dorsal plates chain-charging TAIL -> HEAD, landing on the EXACT SAME fixed spine points
    // drawKaijuBody bakes as anatomy (py = lerp(-44, 92, f), the same bump curve — see that
    // function's own comment). v5.11 fix: this used to be an arc that rotated with facingAngle
    // while the (non-rotating) body underneath it didn't, so "the plates light up" and "the plates
    // exist" were two unrelated systems that only ever agreed by coincidence (the old body had no
    // baked plates to compare against at all). Now children of bodyC (see platePool's own comment),
    // positioned in the SAME local "head-up" space drawKaijuBody draws in — bodyC's own rotation
    // (syncPlayer, facing the kaiju's facingAngle) carries these along automatically, including its
    // hop-bounce squash, with no extra transform needed here.
    const K = SKIES_KAIJU
    const chargeT = ((animT % R.chainT) / R.chainT)
    for (let i = 0; i < platePool.length; i++) {
      const s = platePool[i]
      const f = i / (platePool.length - 1)
      const charge = Math.max(0, 1 - Math.abs(((f + chargeT) % 1) - 0.5) * 3)
      const py = lerp(-44, 92, f)
      const bump = Math.max(0, 1 - Math.abs(f - 0.42) * 1.5)
      s.visible = true
      if (s.texture !== T.plate.tex) { s.texture = T.plate.tex; s.anchor.set(T.plate.ax, T.plate.ay) }
      s.tint = mix(R.plateCool, R.plateHot, charge)
      s.alpha = 0.6 + 0.4 * charge
      s.scale.set(lerp(0.9, 1.7, bump) * (0.9 + 0.3 * charge) * K.plateGlowScale)
      s.rotation = 0   // plates sit upright on the centreline, not tangential to an arc anymore
      s.position.set(0, py)
    }
  }
  // v7.23 Atomic Breath wind-up: the seven dorsal plates charge TAIL -> HEAD and the whole spine
  // brightens as the charge fills, arriving lit at the head exactly as the breath fires. Returns
  // false when there is nothing charging, so the caller can hide the pool as before.
  //
  // Reuses updateRampage's plate machinery wholesale — same platePool, same T.plate texture, same
  // (0, py) spine points drawKaijuBody bakes as anatomy, so this cannot drift out of register with
  // the body the way the pre-v5.11 rotating arc did. The DIFFERENCE from rampage is the motion:
  // rampage runs a continuous loop off animT (it is a sustained state), while this is a one-way
  // fill on the sim's own charge clock — so the plates read as "winding up to something", not as
  // "rampage is on".
  function lightPlatesForBreath(run) {
    if (playerForm !== 'kaiju') return false
    const a = (run.arcs || []).find((x) => x.charge > 0)
    if (!a) return false
    const R = SKIES_FX.rampage
    const K = SKIES_KAIJU
    const k = 1 - Math.max(0, Math.min(1, a.charge / BREATH_CHARGE_T))   // 0 -> 1 across the wind-up
    for (let i = 0; i < platePool.length; i++) {
      const s = platePool[i]
      const f = i / (platePool.length - 1)
      // drawKaijuBody bakes py = lerp(-44, 92, f), so f=0 is the HEAD and f=1 the tail. A tail->head
      // wavefront therefore travels f: 1 -> 0, i.e. it sits at (1 - k).
      const front = Math.max(0, 1 - Math.abs(f - (1 - k)) * 3)
      const charge = Math.min(1, front + k * k * 0.6)   // ...and the whole spine glows hotter as it fills
      const py = lerp(-44, 92, f)
      const bump = Math.max(0, 1 - Math.abs(f - 0.42) * 1.5)
      s.visible = true
      if (s.texture !== T.plate.tex) { s.texture = T.plate.tex; s.anchor.set(T.plate.ax, T.plate.ay) }
      s.tint = mix(R.plateCool, R.plateHot, charge)
      s.alpha = 0.35 + 0.65 * charge
      s.scale.set(lerp(0.9, 1.7, bump) * (0.9 + 0.35 * charge) * K.plateGlowScale)
      s.rotation = 0
      s.position.set(0, py)
    }
    return true
  }

  function clearRampage() {
    rampG.clear()
    jamT = 0; rampBeatT = 0
    kaijuSwipeT = 0
    for (const s of platePool) s.visible = false
    lockDiamond.visible = false
  }

  // ------------------------------------------------------------------- pools
  const enemySprites = new Map() // id -> Sprite
  const enemyFree = []
  const bulletPool = []
  const novaPool = []
  const orbPool = []
  const gemPool = []
  const coinPool = []
  const boomerangPool = []
  const minePool = []
  const homingPool = []
  const holePool = []
  const beamPool = []
  const debrisPool = []
  const jetPool = []          // v6.10 open-jet RIGS (see acquireJet); reset() must hide .root
  const shotPool = []
  const prevCount = {
    bullet: 0, nova: 0, orb: 0, gem: 0, coin: 0,
    boomerang: 0, mine: 0, homing: 0, hole: 0, beam: 0,
    pool: 0, bloom: 0, trail: 0, web: 0, lure: 0,
    sand: 0,    // v7.x surf: sandbars (run.sandbars) — a flat syncPool, see placeSandbar
    trap: 0, debris: 0, shot: 0, jet: 0,
    rock: 0,    // beyond: asteroids (run.rocks). Absent until now, which worked only by accident —
                // syncPool writes prevCount[key] on its first call, so the surplus-hiding loop
                // `i < prevCount[key]` compared against undefined and skipped on frame one alone.
  }

  function syncPool(pool, layer, list, key, tex, apply) {
    const n = list.length
    while (pool.length < n) {
      const s = spriteOf(tex)
      layer.addChild(s)
      pool.push(s)
    }
    for (let i = 0; i < n; i++) {
      const s = pool[i]
      s.visible = true
      apply(s, list[i], i)
    }
    for (let i = n; i < prevCount[key]; i++) pool[i].visible = false
    prevCount[key] = n
  }

  // Holes and beams are multi-sprite composites (counter-rotating vortex layers, scrolling
  // beam streaks) that need independent per-frame transforms on their children, so they
  // can't be a flat syncPool() of single Sprites — each pool slot is a small Container rig
  // instead, grown/hidden with the same acquire-once/hide-tail pattern as syncPool above.
  // Hole rig: gradient disc + crisp vector rim sized to the REAL radius per frame
  // (both upscale cleanly); the twirl sprites stay near their native resolution as a
  // fixed-size spinning core — stretching them to a 700px+ radius washes them to fog.
  const HOLE_TWIRL_MAX = 460 // px, twirl detail size cap
  function acquireHole() {
    const root = new Container()
    const disc = spriteOf(T.holeDisc)
    const ring = new Graphics()
    const vortexA = new Sprite(T.fx.twirl_01)
    vortexA.anchor.set(0.5)
    vortexA.tint = 0x2f1a66
    vortexA.alpha = 1
    const vortexB = new Sprite(T.fx.twirl_02)
    vortexB.anchor.set(0.5)
    vortexB.tint = 0x5a2fb0
    vortexB.alpha = 0.9
    const core = spriteOf(T.holeCore)
    root.addChild(disc, ring, vortexA, vortexB, core)
    holeLayer.addChild(root)
    return { root, disc, ring, vortexA, vortexB, core, _r: 0 }
  }

  function syncHoles(list) {
    const n = list.length
    while (holePool.length < n) holePool.push(acquireHole())
    for (let i = 0; i < n; i++) {
      const hv = holePool[i]
      hv.root.visible = true
      placeHole(hv, list[i], i)
    }
    for (let i = n; i < prevCount.hole; i++) holePool[i].root.visible = false
    prevCount.hole = n
  }

  function acquireBeam() {
    const root = new Container()
    const beamBody = new Container()
    const bar = spriteOf(T.beam)
    const streakA = new Sprite(T.fx.trace_06)
    streakA.anchor.set(0.5)
    streakA.tint = 0xffd9d4 // pale hot — shimmer INSIDE the red blade, not white paint over it
    streakA.alpha = 0.5
    streakA.rotation = Math.PI / 2 // trace_06 is a vertical streak; rotate to lie along the beam
    streakA.scale.set(fxScale(T.fx.trace_06, T.beamRefLen * 0.3), fxScale(T.fx.trace_06, T.beamRefWidth * 1.6))
    const streakB = new Sprite(T.fx.trace_06)
    streakB.anchor.set(0.5)
    streakB.tint = 0xffd9d4
    streakB.alpha = 0.5
    streakB.rotation = Math.PI / 2
    streakB.scale.set(streakA.scale.x, streakA.scale.y)
    beamBody.addChild(bar, streakA, streakB)

    // tip/muzzle sit outside beamBody so the width-squash scale doesn't distort them
    const tip = new Sprite(T.fx.flare_01)
    tip.anchor.set(0.5)
    tip.tint = 0xff5a52 // the saber's tip burns red
    const muzzle = new Sprite(T.fx.muzzle_02)
    muzzle.anchor.set(0.5)
    muzzle.tint = 0xff5a52 // emitter flash, same red as the tip

    root.addChild(beamBody, tip, muzzle)
    beamLayer.addChild(root)
    return { root, beamBody, bar, streakA, streakB, tip, muzzle }
  }

  function expandBeamArms(beams) {
    const out = []
    for (const b of beams) {
      const arms = b.swept ? (b.arms ?? 2) : 1
      if (arms <= 1) { out.push(b); continue }
      for (let k = 0; k < arms; k++) {
        const angle = b.fan
          ? b.angle - b.fan / 2 + (k / (arms - 1)) * b.fan
          : b.angle + (k / arms) * Math.PI * 2
        out.push({ ...b, angle })   // a COPY: render never writes to run
      }
    }
    return out
  }

  // Beam Prism refractions (run.prisms): each entry is a finished segment with a decaying `life`.
  // The colour is the Neon Beam's own tip red (placeBeam's 0xff5a52 / 0xffd9d4), because a
  // refraction has to read as THIS weapon's light bending, not as some second effect that happens
  // to be near it.
  const PRISM_GLOW = 0xff5a52
  const PRISM_CORE = 0xffd9d4
  const PRISM_BURST_F = 0.35   // share of a segment's life spent throwing itself out to full reach

  // A tapered ray: fat where the light bent, pointed where it dies. Drawn as a triangle rather than
  // a stroke because a constant-width stroke is exactly what made v6.7.6 read as a drawn line.
  function prismWedge(g, x, y, ux, uy, halfW, len, color, alpha) {
    const nx = -uy * halfW, ny = ux * halfW
    g.poly([x + nx, y + ny, x - nx, y - ny, x + ux * len, y + uy * len])
    g.fill({ color, alpha })
  }

  function redrawPrisms(run) {
    prismG.clear()
    prismBodyG.clear()
    const list = run.prisms || []
    if (list.length === 0) return
    for (const s of list) {
      const k = Math.max(0, Math.min(1, s.life / PRISM_FLASH_T)) // 1 at cast -> 0 as it fades
      const fade = Math.pow(k, 0.7)
      const gen = s.d ?? 0
      const dx = s.x2 - s.x, dy = s.y2 - s.y
      const full = Math.hypot(dx, dy)
      if (full < 1) continue
      const ux = dx / full, uy = dy / full
      // Each generation is thinner than its parent — light losing energy at every surface. Without
      // it a 40-ray mythic tree draws every ray identically and the fan reads as noise.
      const w = Math.max(3, 11 - gen * 2.6) * (0.55 + 0.45 * fade)
      // The ray throws itself out from the split point rather than appearing whole — the motion is
      // what makes it read as a splash rather than as a shape that was already there.
      const grow = Math.min(1, 0.18 + (1 - k) / PRISM_BURST_F)
      const len = full * grow

      // Three nested wedges, each shorter and hotter than the last. That IS the gradient — a ray
      // that is uniformly bright for 200px reads as a drawn stroke no matter how it's tinted, which
      // is what made v6.7.6's fan look like wireframe. Dense at the surface, dissolving outward.
      prismWedge(prismBodyG, s.x, s.y, ux, uy, w * 1.25, len, PRISM_GLOW, 0.30 * fade)
      prismWedge(prismG, s.x, s.y, ux, uy, w, len * 0.62, PRISM_GLOW, 0.55 * fade)
      prismWedge(prismG, s.x, s.y, ux, uy, w * 0.45, len * 0.30, PRISM_CORE, 0.95 * fade)

      // The bloom AT the split point is what actually says "it bent here" — every ray of one
      // refraction stacks its own, so a wide split lights up brighter than a narrow one for free.
      prismBodyG.circle(s.x, s.y, w * 1.9).fill({ color: PRISM_GLOW, alpha: 0.28 * fade })
      prismG.circle(s.x, s.y, w * 0.85).fill({ color: PRISM_CORE, alpha: 0.7 * fade })

      // The travelling front, alive only while the ray is still extending. Kept small on purpose:
      // at any size where it reads as a disc it reads as a BULLET, i.e. as a separate projectile
      // this weapon does not have — it has to stay a spark riding the leading edge.
      if (grow < 1) {
        prismG.circle(s.x + ux * len, s.y + uy * len, w * 0.22)
        prismG.fill({ color: PRISM_CORE, alpha: 0.45 * fade })
      }
    }
  }

  function syncBeams(list) {
    const n = list.length
    while (beamPool.length < n) beamPool.push(acquireBeam())
    for (let i = 0; i < n; i++) {
      const bv = beamPool[i]
      bv.root.visible = true
      placeBeam(bv, list[i])
    }
    for (let i = n; i < prevCount.beam; i++) beamPool[i].root.visible = false
    prevCount.beam = n
  }

  // ---- v5.0 pond field elements ------------------------------------------------------------
  // Obstacles (run.obstacles): each collider is dressed in its chapter's own furniture, sized to
  // the collider's radius so what you see is what you bump into. The list STREAMS with the player
  // (sim.js streamObstacles, v5.6.13), so this rebuilds when the array identity changes (new run)
  // OR run._obstacleRev bumps (cells materialized/dropped) — otherwise it's a no-op. Every obstacle sits on a HARD footprint ring (T.obFoot) whose rim lands
  // exactly on the collider edge o.r — the collision contract, drawn hard where decor shadows are
  // soft — under a denser mass than the floor props. Two mass styles:
  //   clumps (body/pond/garden) — one sheet prop stacked into a lifted mound: reeds/weeds.
  //   baked  (chapters 4-7)     — two baked props (roots+bone, dumpster/hydrant/cone, rubble,
  //                               asteroids), the big one planted on the pad and a smaller second
  //                               tucked at the rim so the pair reads as a heap, not a double-print.
  // Mass + ring are multiplied by chapterRender.floorTint, so the furniture sits in the biome's light.
  const obstacleSprites = []
  let obstacleToken = null
  let obstacleRev = -1
  // v5.8 kaiju redesign: resolved {tint, foot} per obstacle, keyed by the stable o._cell (sim.js
  // streamObstacles' "i,j" grid key — unique per live obstacle, and deterministic for the cell's
  // whole existence since obstacleCellHash is a pure function of (cell, seed): the same cell always
  // rerolls the identical x/y/r/kind if it pops back after being crushed and re-streamed, so a
  // cached entry never goes stale within a run, only unused once the cell drops out of the field).
  // Exists purely to skip districtAt/districtTintAt (config.js: ~36 hash01 calls EACH, "nowhere
  // near a hot per-frame loop" by that file's own comment) on a rebuild that doesn't need them.
  // Crushing bumps run._obstacleRev every frame it's crushing (sim.js stepCrush) and the field is
  // now ~150 obstacles instead of ~58 (see obstacles.cell/count in config.js), so a full recompute
  // on every such rebuild would be exactly the hot loop that comment warns against. Cleared on
  // reset(run) (see clearObstacles) — a new run rerolls both _obstacleSeed and _districtSeed, so a
  // previous run's cached resolution would be wrong, not just stale.
  const obstacleSkinCache = new Map()
  function acquireObstacle() {
    const root = new Container()
    const ring = new Sprite(Texture.EMPTY) // grounded footprint, UNDER the mass, rim on the collider edge
    ring.anchor.set(0.5)
    const clumpA = new Sprite(Texture.EMPTY)
    clumpA.anchor.set(0.5)
    const clumpB = new Sprite(Texture.EMPTY)
    clumpB.anchor.set(0.5)
    root.addChild(ring, clumpA, clumpB)
    obstacleLayer.addChild(root)
    return { root, ring, clumpA, clumpB, mesh: null, x: 0, y: 0, r: 0 }
  }
  // v5.21/v5.22/v5.23: planets that turn. Held outside syncObstacles because that function is
  // rebuild-gated and this has to run every frame.
  const planetSpinners = []
  const planetMoons = []
  function tickPlanetSpin() {
    for (const pm of planetMoons) {
      const a = pm.phase + animT * pm.rate
      // Seen near edge-on: full swing across, foreshortened up and down. sin < 0 is the far half of
      // the orbit, so the sprite drops BELOW the sphere mesh in its parent — index 1 is under the
      // mesh and under clumpA too, which is what puts a moon behind the ringed world's far annulus
      // as well as behind the body. Everything else is a plain move.
      pm.s.position.set(Math.cos(a) * pm.dist, Math.sin(a) * pm.dist * MOON_ORBIT_SQUASH)
      pm.root.setChildIndex(pm.s, Math.sin(a) < 0 ? 1 : pm.root.children.length - 1)
    }
    for (const ps of planetSpinners) {
      // Spin about the texture's own y (pole) axis, then map into view space through the planet's
      // fixed tilt: M = Ry(-angle) * transpose(tilt), written straight into the shader's three
      // COLUMN vectors. This is the whole reason the redesign happened — a 2D sprite.rotation is a
      // rotation about +z and nothing else, so a tilted spin axis is not expressible until the
      // sphere is real. Because the tilt is constant, the poles hold still and only the surface
      // between them moves, which is what makes it read as a planet instead of a warping ball.
      const th = ps.phase + animT * ps.rate
      const c = Math.cos(th), s = Math.sin(th)
      const [ux, uy, uz] = ps.bu, [vx, vy, vz] = ps.bv, [wx, wy, wz] = ps.bw
      ps.uni.uRot0.set([c * ux - s * wx, vx, s * ux + c * wx])
      ps.uni.uRot1.set([c * uy - s * wy, vy, s * uy + c * wy])
      ps.uni.uRot2.set([c * uz - s * wz, vz, s * uz + c * wz])
      ps.g.update()   // Float32Arrays were mutated in place; without this the GPU keeps last frame's matrix
    }
  }

  function syncObstacles(run) {
    const list = run.obstacles || []
    // v5.6.13: the list STREAMS as the player roams (sim.js streamObstacles mutates it in place
    // and bumps run._obstacleRev) — rebuild on either a fresh array (new run) or a rev bump.
    if (obstacleToken === list && obstacleRev === (run._obstacleRev || 0)) return
    obstacleToken = list
    obstacleRev = run._obstacleRev || 0
    while (obstacleSprites.length < list.length) obstacleSprites.push(acquireObstacle())
    const foot = T.obFoot
    const style = chapterBiome.obstacle // non-skies chapters: one style for every obstacle
    const liveCells = new Set() // this rebuild's obstacle set, for the cache prune below
    planetSpinners.length = 0   // rebuilt below; stale sprite refs would spin a released pool slot
    planetMoons.length = 0
    for (let i = 0; i < obstacleSprites.length; i++) {
      const ov = obstacleSprites[i]
      if (i >= list.length) { ov.root.visible = false; continue }
      const o = list[i]
      ov.root.visible = true
      if (ov.mesh) ov.mesh.visible = false   // pool slots are reused across chapters; only the planet branch re-enables it
      if (ov.moons) for (const m of ov.moons) m.visible = false   // same rule — a moon must not outlive its planet
      ov.root.position.set(o.x, o.y)
      ov.x = o.x; ov.y = o.y; ov.r = o.r
      liveCells.add(o._cell)
      // v5.11: a building INSIDE A CITY is squared to its block. sim's streamObstacles stamps
      // o.rot from the city's own street angle when it snaps the structure off the carriageway
      // (blockSnap, terrain.js); everything in open country keeps the free hashed spin, which is
      // right — a barn in a field answers to nothing, but a row of towers at independent random
      // angles is the loudest possible tell that nobody planned the street they stand on.
      const rot = o.rot ? o.rot + (hash(o.x + o.y * 3.3) - 0.5) * 0.08 : hash(o.x + o.y * 3.3) * Math.PI * 2
      // districts (skies only): each obstacle's PALETTE follows WHERE it sits (districtAt at its
      // own x,y), not one chapter-wide style — see DISTRICT_BIOMES above. Cached per o._cell (see
      // obstacleSkinCache's doc) so a rebuild only pays the district hash chain once per obstacle
      // for its whole lifetime, not once per rebuild.
      let skin = obstacleSkinCache.get(o._cell)
      if (!skin) {
        const structDistrict = chapterHasDistricts ? districtAt(o.x, o.y, districtSeed) : null
        const obStyle = chapterHasDistricts ? DISTRICT_BIOMES[structDistrict].obstacle : style
        const floorAt = floorTintAt(o.x, o.y)
        skin = { tint: tintMul(obStyle.tint, floorAt), foot: tintMul(obStyle.foot, floorAt), district: structDistrict, planet: obStyle.planet === true }
        if (skin.planet) {
          // Which of the seven archetypes, and which hue nudge. Hashed off o.x/o.y — the same idiom
          // the baked-furniture `pick` below uses — because sim's streamObstacles guarantees x/y/r
          // regenerate identically for a cell (test/sim-test.js run V.g walks 20000px away and back
          // and asserts exactly that), so a planet keeps its identity when it re-enters view.
          // NOT hashed off o.kind: STRUCTURE_KINDS is pinned at 6 entries by run DD.d, so a future
          // kind edit would silently reshuffle the planet mix, and pier -> ice world means nothing.
          skin.planetVariant = Math.floor(hash(o.x * 1.7 + o.y * 0.31 + 23.7) * T.planetMaps.length)
          skin.planetTint = T.planetTints[Math.floor(hash(o.x * 1.7 + o.y * 0.31 + 41.1) * T.planetTints.length)]
          skin.planetRot = hash(o.x * 1.7 + o.y * 0.31 + 57.3) * Math.PI * 2
          // Signed, and slow: PLANET_SPIN_MAX is ~1 revolution every 35s at the fastest, which is
          // motion you notice only if you stop and look — the intent is life, not a spinning top.
          skin.planetSpinRate = (PLANET_SPIN_MIN + hash(o.x * 1.7 + o.y * 0.31 + 71.9) * (PLANET_SPIN_MAX - PLANET_SPIN_MIN))
            * (hash(o.x * 1.7 + o.y * 0.31 + 112.3) < 0.5 ? -1 : 1)
          // v5.23.1: THE AXIS, and it is a TILT, not a tumble. A planet turns about the axis through
          // its own poles — which is also the axis its lat/long map converges on. Spinning the
          // sampled direction about any OTHER axis drags that convergence across the visible face,
          // and a pole singularity crossing the disc reads as the surface smearing rather than
          // rotating. So what varies per world is where the pole POINTS, fixed for its lifetime.
          // z is held small so the pole sits near the limb, where the map's convergence is squeezed
          // into a few pixels rather than pinching the middle of the planet.
          const pz = (hash(o.x * 1.7 + o.y * 0.31 + 88.3) - 0.5) * 0.6
          const pa = hash(o.x * 1.7 + o.y * 0.31 + 95.1) * Math.PI * 2
          const ps = Math.sqrt(Math.max(0, 1 - pz * pz))
          // An archetype may pin its own pole (the ringed world must — see its `pole`).
          const pole = T.planetPole[skin.planetVariant] || [Math.cos(pa) * ps, Math.sin(pa) * ps, pz]
          // Orthonormal basis with the pole as its y axis: (u, pole, w) IS the texture->view
          // rotation, so its transpose is what the shader wants. Built once here because only the
          // spin angle changes per frame — the tilt never does.
          const ref = Math.abs(pole[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]
          const cx = ref[1] * pole[2] - ref[2] * pole[1]
          const cy = ref[2] * pole[0] - ref[0] * pole[2]
          const cz = ref[0] * pole[1] - ref[1] * pole[0]
          const cm = Math.hypot(cx, cy, cz) || 1
          const U = [cx / cm, cy / cm, cz / cm]
          skin.planetU = U
          skin.planetV = pole
          skin.planetW = [U[1] * pole[2] - U[2] * pole[1], U[2] * pole[0] - U[0] * pole[2], U[0] * pole[1] - U[1] * pole[0]]
        }
        obstacleSkinCache.set(o._cell, skin)
      }
      // structure SHAPE (v5.8, kinds grown by v5.9): o.kind (config.js STRUCTURE_KINDS —
      // tower/house/tree/pier/barn/silo) picks the silhouette via STRUCTURE_SKINS, independent of
      // the district palette above — see that table's doc comment. Non-skies chapters have no
      // kind-driven table entry to find (chapterHasDistricts is false there), so they fall through
      // to the one chapter-wide `style` exactly as before this redesign — untouched.
      // v5.9.2 override ("the fuck is this?" bug report): parks and hills BOTH roll kind='tree'
      // (config.js DISTRICT_STRUCTURE_KINDS — a real 7th kind would need test/sim-test.js's run
      // DD.d, which pins STRUCTURE_KINDS at exactly 6, updated by whoever owns test/), so the two
      // districts rendered IDENTICALLY: the same foliage-clump silhouette, just re-tinted. Rather
      // than grow the data model, hills' 'tree' obstacles render with the rock skin instead — reusing
      // `skin.district` (cached above, so this costs nothing extra) to catch exactly that one
      // combination. Every other kind/district combination is untouched.
      const shape = chapterHasDistricts
        ? (o.kind === 'tree' && skin.district === 'hills' ? STRUCTURE_SKINS.rock : (STRUCTURE_SKINS[o.kind] || style))
        : style
      // footprint ring: the hard contract. Scaled so its rim lands EXACTLY on the collider edge o.r.
      ov.ring.texture = foot.tex
      // v5.10: under a top-down plan the footprint pad becomes a CONTACT SHADOW in the region's one
      // ink tone, not the district's high-contrast ring colour. A pale ring under a pier over dark
      // water read as a coin the jetty was standing on, which is the opposite of "this is a place".
      ov.ring.tint = (chapterHasDistricts && STRUCTURE_SKINS[o.kind]?.topDown) ? 0x121722 : skin.foot
      // v5.10: for a skies top-down PLAN the ring drops to a contact shadow. At full alpha it is a
      // hard dark disc under every building, which from overhead reads as a coin the structure is
      // standing on — and it is not telling the player anything here anyway, since in this chapter
      // EVERY structure is crushable. The rim still lands exactly on o.r; only its weight changes.
      ov.ring.alpha = (chapterHasDistricts && STRUCTURE_SKINS[o.kind]?.topDown) ? 0.45 : 1
      ov.ring.scale.set(o.r / foot.ref)
      if (shape.baked) {
        // baked furniture: pick two pieces off the kind's list by position hash, plant the big
        // one on the pad and tuck a smaller second at the rim. Baked props carry their own origin
        // (upright ones sit on their base), so the anchor comes from the look, not a fixed 0.5.
        const pick = (salt) => shape.baked[Math.floor(hash(o.x * 1.7 + o.y * 0.31 + salt) * shape.baked.length)]
        // v6.3 Task 4: in the city, a cover-sized obstacle (o.r >= COVER_MIN_R) always bakes as the
        // dumpster — the one prop in BIOMES.city.obstacle.baked actually shaped like something that
        // stops a car. Hydrant/cone stay on the ordinary hash pick; they're under COVER_MIN_R so
        // findCover (sim.js) would never let them shield anyway. Smaller obstacles, and every other
        // chapter's baked sets, are untouched.
        const a = T[run.chapter === 'city' && o.r >= COVER_MIN_R ? 'dumpster' : pick(0)]
        const b = T[pick(11.3)]
        // v5.9.2 ("the fuck is this?" bug report): sized from o.r again, for EVERY chapter — no more
        // chapterHasDistricts branch here. The v5.9 top-down region overhaul had this reading an
        // ABSOLUTE px band off PROP_SCALE[o.kind] instead, independent of o.r; since o.r and `kind`
        // were independent hash rolls (sim.js streamObstacles), a max-radius house could render
        // bigger than a min-radius tower — visible structures overlapping while their colliders sat
        // far apart, exactly the reported wall of blobs. The real fix is upstream: sim.js now rolls
        // o.r itself from a per-kind band (config.js STRUCTURE_RADIUS), so drawing proportional to
        // o.r here is enough to make a tower's silhouette genuinely bigger than a house's — no
        // second, independent sizing system needed on the render side at all.
        if (shape.topDown) {
          // v5.10 (spec §5.1.3): a top-down PLAN is MASS-CENTRED, not base-anchored, and carries
          // its own lot/yard detail plus its own cast shadow — so clumpB (the "second piece tucked
          // at the rim" that made a heap out of two side-view props) is suppressed outright.
          // Sized so the plan's CONTENT half-extent (SKR, the bake's own content radius) lands just
          // past the collider rim: the T.obFoot ring, not the silhouette, is still the contract.
          ov.clumpA.texture = a.tex; ov.clumpA.anchor.set(a.ax, a.ay)
          ov.clumpA.tint = 0xffffff  // plans carry their OWN palette — see STRUCTURE_SKINS' comment
          ov.clumpA.scale.set((o.r * SKIES_PLAN_SCALE) / (SKR * 2))
          ov.clumpA.rotation = 0
          ov.clumpA.position.set(0, 0)
          // v5.12 BUGFIX: `rot` (computed above from o.rot, which sim.js stamps with the owning
          // city's street angle in blockSnap) was being thrown away here, so EVERY structure in the
          // chapter drew as a perfect world-axis rectangle — a diamond block full of rectangles that
          // ignore it. Rotating the ROOT, not clumpA: the tower's aviation lamp is a SIBLING of
          // clumpA positioned in unrotated plan coordinates, so turning clumpA alone would slide the
          // beacon off its mast. The footprint ring is a disc, so rotating root is a no-op for it.
          ov.root.rotation = rot
          ov.clumpB.texture = Texture.EMPTY
          ov.clumpB.scale.set(1)
          continue
        }
        ov.root.rotation = 0   // pooled sprite may have come from a rotated top-down plan
        // v5.18 PLANET (beyond): one centred body, scaled 1:1 to its collider, and NO clumpB. The
        // generic path below is written for base-planted SIDE-VIEW props — it plants the art at
        // o.r * 0.28 (so a tree sits on its pad) and stamps a second smaller copy at the rim (so a
        // rock reads as a heap). Applied to a 260px planet that produced a body offset ~93px below
        // its own centre with a second planet growing out of its edge. A sphere is neither planted
        // nor heaped: it is centred, and it is one object.
        if (skin.planet) {
          // v5.23: THREE layers, in draw order — clumpA is whatever sits BEHIND the sphere (only the
          // ringed world's far annulus), the Mesh is the sphere itself, clumpB is the atmosphere
          // halo plus anything crossing in FRONT. The mesh is inserted at index 2 so it lands
          // between them; created lazily, so pool slots that never hold a planet never pay for a
          // shader. o.r stays cosmetic in this chapter (stepObstacles early-returns on `lane`, no
          // `crush`, no `blink` in the roster) — a chapter reusing `planet: true` with real colliders
          // would need this branch reworked, not just a new archetype.
          if (!ov.mesh) { ov.mesh = makePlanetMesh(); ov.root.addChildAt(ov.mesh, 2) }
          const v = skin.planetVariant
          const behind = T.planetBehind[v], front = T.planetFront[v]
          const res = ov.mesh.shader.resources
          res.uMap = T.planetMaps[v].source
          res.uEmit = T.planetEmits[v].source
          const u = res.uniforms.uniforms
          u.uAtmo.set(T.planetAtmo[v])
          u.uTint.set([(skin.planetTint >> 16 & 255) / 255, (skin.planetTint >> 8 & 255) / 255, (skin.planetTint & 255) / 255])
          ov.mesh.visible = true
          // The quad spans [-1,1], so scaling it by the body radius makes the sphere exactly as wide
          // as the old disc bake was — the ringed world still shrinks to 0.58 to leave room.
          ov.mesh.scale.set(o.r * T.planetBodyR[v])
          // Registered for the per-frame pass below. The matrix CANNOT be advanced here:
          // syncObstacles early-returns unless the obstacle list streams (see its guard), so anything
          // written in this loop is written once when the planet materialises and then never again —
          // which is exactly why the first cut of the v5.21 spin did not rotate in real time.
          planetSpinners.push({ uni: u, g: res.uniforms, bu: skin.planetU, bv: skin.planetV, bw: skin.planetW, phase: skin.planetRot, rate: skin.planetSpinRate })
          ov.clumpA.texture = behind || Texture.EMPTY
          ov.clumpA.anchor.set(0.5)
          ov.clumpA.tint = 0xffffff
          ov.clumpA.rotation = 0
          ov.clumpA.position.set(0, 0)
          ov.clumpA.scale.set(behind ? (o.r * 2) / behind.width : 1)
          ov.clumpB.texture = front || Texture.EMPTY
          ov.clumpB.anchor.set(0.5)
          ov.clumpB.tint = 0xffffff
          ov.clumpB.rotation = 0          // the sun does not orbit the planet
          ov.clumpB.position.set(0, 0)
          ov.clumpB.scale.set(front ? (o.r * 2) / front.width : 1)
          // Moons: one sprite each, hashed off the same x/y as everything else about this world so
          // it keeps its phase when it streams back into view. Registered for tickPlanetSpin, which
          // is where the orbit actually happens — this block runs only on a rebuild.
          const moons = T.planetMoons[v]
          if (moons.length && !ov.moons) ov.moons = []
          for (let k = 0; k < moons.length; k++) {
            if (!ov.moons[k]) {
              const s = new Sprite(Texture.EMPTY)
              s.anchor.set(0.5)
              ov.root.addChild(s)
              ov.moons[k] = s
            }
            const s = ov.moons[k]
            s.visible = true
            s.texture = moons[k].tex
            s.scale.set((o.r * moons[k].mr * 2) / moons[k].tex.width)
            const h = o.x * 1.7 + o.y * 0.31 + 131.7 + k * 7.3
            planetMoons.push({
              s, root: ov.root, dist: o.r * moons[k].dist, phase: hash(h) * Math.PI * 2,
              rate: (MOON_ORBIT_MIN + hash(h + 9.4) * (MOON_ORBIT_MAX - MOON_ORBIT_MIN))
                * (hash(h + 17.2) < 0.5 ? -1 : 1),
            })
          }
          ov.ring.alpha = 0   // no collision contract to draw — see BIOMES.beyond.obstacle
          continue
        }
        const scA = (o.r * 1.9) / Math.max(a.tex.width, a.tex.height)
        const scB = (o.r * 1.15) / Math.max(b.tex.width, b.tex.height)
        ov.clumpA.texture = a.tex; ov.clumpA.anchor.set(a.ax, a.ay); ov.clumpA.tint = skin.tint
        ov.clumpA.scale.set(scA); ov.clumpA.rotation = 0
        ov.clumpA.position.set(0, o.r * 0.28) // base planted just past centre, sitting on the pad
        ov.clumpB.texture = b.tex; ov.clumpB.anchor.set(b.ax, b.ay); ov.clumpB.tint = skin.tint
        ov.clumpB.scale.set(scB); ov.clumpB.rotation = (hash(o.x * 2.9 + o.y) - 0.5) * 0.5
        ov.clumpB.position.set((hash(o.x + o.y * 5.1) - 0.5) * o.r * 0.85, o.r * 0.44) // tucked at the rim
      } else {
        // foliage mound: two stacked cluster sprites lifted into a crown, denser and darker than
        // the single floor bush. The ring, not the foliage overhang, marks the true edge. Sized from
        // o.r again, for every chapter (see the baked branch's comment above for the full story of
        // why the PROP_SCALE.tree-based branch this replaced was the bug, not a deliberate split).
        const tex = T.props[shape.clumps[Math.floor(hash(o.x * 1.7 + o.y * 0.31) * shape.clumps.length)]]
        const sc = (o.r * 2.0) / 1024 // source props are 1024px; on-screen width ≈ collider diameter
        ov.clumpA.texture = tex; ov.clumpA.anchor.set(0.5); ov.clumpA.tint = skin.tint
        ov.clumpA.scale.set(sc); ov.clumpA.rotation = rot; ov.clumpA.position.set(0, -o.r * 0.10)
        ov.clumpB.texture = tex; ov.clumpB.anchor.set(0.5); ov.clumpB.tint = skin.tint
        ov.clumpB.scale.set(sc * 0.82); ov.clumpB.rotation = rot + 0.6; ov.clumpB.position.set(0, -o.r * 0.34)
      }
    }
    // Evict cells that dropped out of the streamed field (crushed, or walked past
    // OBSTACLE_DROP_RADIUS) so the cache tracks the live field's size instead of growing for
    // the whole run — see obstacleSkinCache's doc above.
    if (obstacleSkinCache.size > liveCells.size) {
      for (const key of obstacleSkinCache.keys()) if (!liveCells.has(key)) obstacleSkinCache.delete(key)
    }
  }
  function clearObstacles() {
    obstacleToken = null
    obstacleRev = -1
    obstacleSkinCache.clear()
    for (const ov of obstacleSprites) ov.root.visible = false
  }

  // Hazard pools (run.pools, acid + soap): soft saturated-green discs. One shared readable style
  // (deep green, double-stacked for punch on the light floor); alpha fades over the pool's final
  // moments as its remaining life `t` runs down.
  const poolPool = []
  function acquirePoolDisc() {
    const root = new Container()
    const a = new Sprite(T.fx.circle_05); a.anchor.set(0.5)
    const b = new Sprite(T.fx.circle_05); b.anchor.set(0.5)
    root.addChild(a, b)
    poolLayer.addChild(root)
    return { root, a, b }
  }
  function syncPools(list) {
    const n = list.length
    while (poolPool.length < n) poolPool.push(acquirePoolDisc())
    for (let i = 0; i < n; i++) {
      const pv = poolPool[i]
      const p = list[i]
      pv.root.visible = true
      pv.root.position.set(p.x, p.y)
      const fade = Math.min(1, p.t / 0.6) // dissolve over the last 0.6s of life
      const sc = fxScale(T.fx.circle_05, Math.max(p.r, 1) * 2)
      pv.a.scale.set(sc); pv.a.tint = 0x2fbf3f; pv.a.alpha = 0.5 * fade
      pv.b.scale.set(sc * 0.68); pv.b.tint = 0x7fe86a; pv.b.alpha = 0.55 * fade
    }
    for (let i = n; i < prevCount.pool; i++) poolPool[i].root.visible = false
    prevCount.pool = n
  }

  // Toxin blooms (run.blooms): expanding venom-green clouds. Three stacked soft puffs sized to the
  // sim-grown radius `r`, alpha ramps in as the cloud forms and out as it expires (t → dur).
  const bloomPool = []
  function acquireBloom() {
    const root = new Container()
    const a = new Sprite(T.fx.circle_05); a.anchor.set(0.5)
    const b = new Sprite(T.fx.circle_05); b.anchor.set(0.5)
    const c = new Sprite(T.fx.circle_05); c.anchor.set(0.5)
    root.addChild(a, b, c)
    bloomLayer.addChild(root)
    return { root, puffs: [a, b, c] }
  }
  function syncBlooms(run) {
    const list = run.blooms || []
    const n = list.length
    while (bloomPool.length < n) bloomPool.push(acquireBloom())
    // v6.4 Tide-Carried (WEAPON_MODS.bloom.tideCarried): with picks held, stepBlooms drifts each
    // cloud along currentForce — invisibly, unless something ELSE marks it. When a cloud's centre
    // sits inside an eddy's ring, its puffs shift toward cyan: "my cloud is riding the current" is
    // now an observable event, not just a silent position nudge. Cheap: <=8 clouds x <=10 eddies.
    const tideCarried = (run.weaponMods?.bloom?.tideCarried ?? 0) > 0
    for (let i = 0; i < n; i++) {
      const bv = bloomPool[i]
      const bl = list[i]
      bv.root.visible = true
      bv.root.position.set(bl.x, bl.y)
      const dur = Math.max(0.001, bl.dur)
      const inA = Math.min(1, bl.t / (dur * 0.2))
      const outA = Math.min(1, (dur - bl.t) / (dur * 0.25))
      const alpha = Math.max(0, Math.min(inA, outA))
      const sc = fxScale(T.fx.circle_05, Math.max(bl.r, 1) * 2)
      let inEddy = false
      if (tideCarried) {
        for (const ed of run.eddies) {
          const dx = ed.x - bl.x, dy = ed.y - bl.y
          if (dx * dx + dy * dy < ed.r * ed.r) { inEddy = true; break }
        }
      }
      for (let k = 0; k < 3; k++) {
        const s = bv.puffs[k]
        const off = k === 0 ? 0 : bl.r * 0.4
        const ang = animT * 0.6 + k * 2.1
        s.position.set(Math.cos(ang) * off, Math.sin(ang) * off)
        s.scale.set(sc * (k === 0 ? 1 : 0.72) * (1 + 0.05 * Math.sin(animT * 3 + k)))
        s.tint = inEddy ? (k % 2 ? 0x6fe0c0 : 0x3faea0) : (k % 2 ? 0x6fe04a : 0x3fae2f)
        s.alpha = alpha * (k === 0 ? 0.5 : 0.4)
      }
    }
    for (let i = n; i < prevCount.bloom; i++) bloomPool[i].root.visible = false
    prevCount.bloom = n
  }

  // ---- v5.3 garden field elements ----------------------------------------------------------
  // Pheromone trails (run.trails, {x,y,t}): faint amber dots dropped under dying ants that living
  // ants accelerate along. Soft ground decals, brightest when fresh, fading as t → 0 (t counts down
  // from PHEROMONE_LIFE). Amber reads on the warm lawn floor (a saturated tint, not a pale wash).
  const trailPool = []
  function acquireTrail() {
    const s = new Sprite(T.fx.circle_05)
    s.anchor.set(0.5)
    trailLayer.addChild(s)
    return s
  }
  function syncTrails(list) {
    const n = list.length
    while (trailPool.length < n) trailPool.push(acquireTrail())
    for (let i = 0; i < n; i++) {
      const s = trailPool[i]
      const tr = list[i]
      s.visible = true
      s.position.set(tr.x, tr.y)
      const fade = Math.max(0, Math.min(1, tr.t / PHEROMONE_LIFE))
      s.tint = 0xe8a23a // warm amber pheromone
      s.alpha = 0.42 * fade
      s.scale.set(fxScale(T.fx.circle_05, 26))
    }
    for (let i = n; i < prevCount.trail; i++) trailPool[i].visible = false
    prevCount.trail = n
  }

  // Spider web slow-zones (run.webs, {x,y,r,t}): a real orb web baked ONCE and scaled per patch.
  // Pale silvery-cool silk reads on the warm sunlit garden lawn (floorTint 0xaad066 — cool wins on
  // warm ground). Off-centre hub, ~10 jittered radial spokes, sagging capture rings (each ring arc
  // bows INWARD toward the hub — that catenary sag is THE thing that reads as silk, not a wheel), a
  // few broken segments for wear, and a taut outer frame ring whose spoke-tips sit at EXACTLY the
  // slow radius r (drawn extent == tested extent). Rotated per-patch so tiled webs don't look
  // stamped; dissolves over its final 0.8s; a faint interior veil fills the zone so the hazard reads.
  const WEB_BAKE_RIM = 144 // bake radius (2× WEB_R=72) so hairlines survive scaling down to r
  const webTex = (() => {
    const g = new Graphics()
    const RIM = WEB_BAKE_RIM
    const N = 10                                // radial spokes
    const HX = RIM * 0.055, HY = -RIM * 0.04    // hub, slightly off-centre
    const rings = [0.30, 0.47, 0.63, 0.80, 1.0] // capture-ring fractions hub→rim (last = frame)
    const SAG = 0.35                            // sag depth as a fraction of ring spacing
    // spoke tips on the origin-centred rim circle, with fixed angular jitter (baked once, no flicker)
    const th = [], px = [], py = []
    for (let i = 0; i < N; i++) {
      const a = (i / N) * Math.PI * 2 + (hash(i * 12.9 + 3.1) - 0.5) * 0.14 // ±0.07rad jitter
      th.push(a); px.push(Math.cos(a) * RIM); py.push(Math.sin(a) * RIM)
    }
    // faint interior veil so the slow-zone reads as a filled area — geometry carries the read
    g.circle(0, 0, RIM).fill({ color: 0xdfeef6, alpha: 0.06 })
    // radial spokes, hub → tip (dimmer/cooler structural threads)
    for (let i = 0; i < N; i++) g.moveTo(HX, HY).lineTo(px[i], py[i])
    g.stroke({ width: 1.2, color: 0xcfe2ee, alpha: 0.65, cap: 'round' })
    // capture rings (inner) — concentric around the off-centre hub, each segment sagging toward it;
    // a few segments broken for wear. quad control at M + 2·sag·û gives an actual mid-arc sag of `sag`.
    for (let r = 0; r < rings.length - 1; r++) {
      const f = rings[r], fp = r === 0 ? 0 : rings[r - 1]
      for (let i = 0; i < N; i++) {
        if (hash(r * 7.3 + i * 2.9 + 1.7) < 0.12) continue // broken segment
        const j = (i + 1) % N
        const vix = HX + f * (px[i] - HX), viy = HY + f * (py[i] - HY)
        const vjx = HX + f * (px[j] - HX), vjy = HY + f * (py[j] - HY)
        const mx = (vix + vjx) / 2, my = (viy + vjy) / 2
        let ux = HX - mx, uy = HY - my; const ul = Math.hypot(ux, uy) || 1; ux /= ul; uy /= ul
        const sag = SAG * (f - fp) * Math.hypot(px[i] - HX, py[i] - HY) // frac × radial ring spacing
        g.moveTo(vix, viy).quadraticCurveTo(mx + ux * 2 * sag, my + uy * 2 * sag, vjx, vjy)
      }
    }
    g.stroke({ width: 1.0, color: 0xeef6fb, alpha: 0.85, cap: 'round' })
    // taut outer frame ring — spoke tips at EXACTLY r (= drawn rim), only a gentle bow between them
    for (let i = 0; i < N; i++) {
      const j = (i + 1) % N
      const mx = (px[i] + px[j]) / 2, my = (py[i] + py[j]) / 2
      let ux = -mx, uy = -my; const ul = Math.hypot(ux, uy) || 1; ux /= ul; uy /= ul
      const sag = RIM * 0.05
      g.moveTo(px[i], py[i]).quadraticCurveTo(mx + ux * sag, my + uy * sag, px[j], py[j])
    }
    g.stroke({ width: 1.4, color: 0xeef6fb, alpha: 0.9, cap: 'round' })
    // 2 thin anchor tethers just past the rim (clearly tethers, not web body)
    for (const i of [2, 7]) g.moveTo(px[i], py[i]).lineTo(Math.cos(th[i]) * (RIM + 7), Math.sin(th[i]) * (RIM + 7))
    g.stroke({ width: 0.9, color: 0xcfe2ee, alpha: 0.5, cap: 'round' })
    // messy hub tangle
    for (let k = 0; k < 3; k++) {
      const a = k * 2.1 + 0.4, ln = RIM * 0.05
      g.moveTo(HX - Math.cos(a) * ln, HY - Math.sin(a) * ln).lineTo(HX + Math.cos(a) * ln, HY + Math.sin(a) * ln)
    }
    g.stroke({ width: 0.8, color: 0xeef6fb, alpha: 0.7, cap: 'round' })
    return bake(g)
  })()
  // SLIME, for The Deep's hagfish (run.webs again — same mechanic, same array, different animal).
  //
  // ⚠ THIS EXISTS BECAUSE AN FX BAKED FOR ONE BIOME IS WRONG ON THE NEXT ONE, and the first probe
  // frame of The Deep is the evidence: the abyssal plain was covered in GIANT WHITE ORB-WEAVER
  // WEBS, because `webZone` is a chapter-agnostic flag and the only art it had was a garden
  // spider's. Nothing throws, no test can see it, and it was the loudest thing on a screen whose
  // whole premise is that there is almost no light. A hagfish's slow patch is MUCUS: a low
  // irregular sheet with no hub, no spokes and no rings — every one of which is a structure a
  // spider builds and a hagfish cannot.
  const SLIME_BAKE_RIM = 144
  const slimeTex = (() => {
    const g = new Graphics()
    const R = SLIME_BAKE_RIM
    // An irregular lobed outline rather than a circle: slime spreads by flowing, so its edge is
    // uneven and its centre is wherever it landed.
    const lobe = (scale, alpha, color) => {
      const pts = []
      for (let i = 0; i < 26; i++) {
        const a = (i / 26) * Math.PI * 2
        const rr = R * scale * (0.82 + hash(i * 3.7 + scale * 11) * 0.32)
        pts.push(Math.cos(a) * rr, Math.sin(a) * rr)
      }
      g.poly(pts).fill({ color, alpha })
    }
    // ⚠ THESE ALPHAS ARE FOR THE STACK, NOT FOR ONE PATCH. Slime patches overlap heavily (a hagfish
    // lays one every few seconds while it walks), and alpha compounds — the first cut used
    // 0.20/0.16/0.14, which reads correctly in isolation and piles into a bright pale MASS around
    // the player in a chapter whose premise is near-total darkness. Judge this on a frame with
    // several overlapping, never on one.
    lobe(1.0, 0.11, 0xbfe0d2)
    lobe(0.78, 0.09, 0xd6efe2)
    lobe(0.5, 0.08, 0xeafaf2)
    // Strands: a hagfish's slime is famously FIBROUS — it comes out in threads that catch. A few
    // long meandering ones, not a radial set, so it never reads as a wheel.
    for (let i = 0; i < 7; i++) {
      const a0 = hash(i * 5.3 + 1.7) * Math.PI * 2
      const a1 = a0 + 1.4 + hash(i * 2.9) * 1.8
      const r0 = R * (0.25 + hash(i * 7.1) * 0.55)
      const r1 = R * (0.35 + hash(i * 4.4) * 0.6)
      g.moveTo(Math.cos(a0) * r0, Math.sin(a0) * r0)
        .quadraticCurveTo(0, 0, Math.cos(a1) * r1, Math.sin(a1) * r1)
        .stroke({ width: R * 0.018, color: 0xe8fbf3, alpha: 0.32, cap: 'round' })
    }
    // Trapped bubbles — the one detail that says "this is a fluid" rather than "this is a stain".
    for (let i = 0; i < 12; i++) {
      const a = hash(i * 9.1 + 4.2) * Math.PI * 2
      const d = R * hash(i * 6.6 + 2.2) * 0.85
      g.circle(Math.cos(a) * d, Math.sin(a) * d, R * (0.014 + hash(i * 3.3) * 0.026))
        .fill({ color: 0xf4fffb, alpha: 0.2 })
    }
    return bake(g)
  })()

  const webPool = []
  function acquireWeb() {
    const spr = new Sprite(webTex.tex); spr.anchor.set(webTex.ax, webTex.ay)
    webLayer.addChild(spr)
    return { root: spr, spr }
  }
  // `slimy` is a RENDER-ONLY chapter flag (CHAPTERS[].render.webLook), so the mechanic, its radius
  // and its slow are byte-identical in both chapters and only the drawing changes — which is the
  // whole contract the `render` block exists to keep.
  function syncWebs(list, slimy = false) {
    const n = list.length
    const look = slimy ? slimeTex : webTex
    const rim = slimy ? SLIME_BAKE_RIM : WEB_BAKE_RIM
    while (webPool.length < n) webPool.push(acquireWeb())
    for (let i = 0; i < n; i++) {
      const wv = webPool[i]
      const web = list[i]
      wv.root.visible = true
      if (wv.spr.texture !== look.tex) { wv.spr.texture = look.tex; wv.spr.anchor.set(look.ax, look.ay) }
      wv.root.position.set(web.x, web.y)
      const fade = Math.min(1, web.t / 0.8) // dissolve over the last 0.8s of life
      const ph = hash(web.x * 0.11 + web.y * 0.07) // fixed per-patch seed (rotation + shimmer phase)
      wv.spr.rotation = ph * Math.PI * 2                        // fixed per position — no stamped tiling
      wv.spr.scale.set(Math.max(web.r, 1) / rim)                // drawn extent == the tested extent
      wv.spr.alpha = fade * (0.86 + 0.14 * Math.sin(animT * 1.6 + ph * 6.28)) // cheap one-sprite shimmer
    }
    for (let i = n; i < prevCount.web; i++) webPool[i].root.visible = false
    prevCount.web = n
  }

  // Sandbars (v7.x Book 2 / The Surf — run.sandbars, {x,y,r,_cell}): dry ground you can walk onto,
  // where you move at signature.bars.slowMul and Humidity falls at bars.drainMul. run.webs above is
  // the idiom this copies exactly — a ground patch that slows you, baked ONCE and scaled per patch,
  // rotated by a position hash so a field of them is not stamped.
  //
  // It ships as a renderer at all because of the design's §5.3: Humidity drives this chapter's
  // damage, and the named mitigation for that — the reason the owner's override was accepted — is
  // that "the sandbar is a PLACE, so the player can always see the cause and step off it". An
  // invisible sandbar is a global damage debuff with no cause on screen, which is precisely the
  // thing §5.3 says must not happen.
  //
  // The drawing, from directly overhead like everything else. A beach seen from above is not a
  // blob, it is a TEXTURE — so the read is carried by wind ripples and shell grit, not by the
  // silhouette, and the irregularity lives INSIDE the tested radius rather than on it:
  //   - the wet apron fills the whole tested disc and its waterline stroke sits at EXACTLY r, so
  //     drawn extent == tested extent (the web decal's and the eddy ring's contract);
  //   - the dry sand is a wobbled blob inside that, and the driest crown a smaller one off-centre,
  //     which is also what a real bar looks like: wet all round, dry in the middle.
  const SAND_BAKE_RIM = 300 // bake radius (2x the shipped bars.r of 150) so ripples survive scaling
  // ONE BAKE PER SHAPE (owner, 2026-08-15: variable shapes, not only circles). A sandbar used to be
  // a single texture rotated per patch, so every dry patch on the beach was the same island turned a
  // different way — which a player reads as one prop stamped repeatedly, exactly the tell the ripple
  // and grit detail was added to avoid at close range.
  //
  // The outline is now LOBE_SHAPES[i], the same table the sim tests standing-on against. A bake per
  // entry is what lets this stay a plain sprite pool instead of a Graphics per patch: six textures,
  // picked by cell hash and then turned by the patch's own stored rotation.
  const sandbarTex = LOBE_SHAPES.map((_, shapeIdx) => {
    const V = SANDBAR_VIS
    const RIM = SAND_BAKE_RIM
    const g = new Graphics()
    // The patch outline at this radius, in bake space. rot 0: the per-patch turn is applied to the
    // SPRITE, so the sim's `rot` and the drawing's rotation are the one same angle.
    const outline = (mean, ox, oy) => lobePoly(mean, shapeIdx, 0, ox, oy)
    // The wet apron and the waterline follow the lobes: this is the edge the mechanic is tested on,
    // so a circle here would be a visible ring that means nothing and a felt edge somewhere else.
    g.poly(outline(RIM, 0, 0)).fill({ color: V.damp, alpha: 0.16 })                       // the wet apron
    g.poly(outline(RIM, 0, 0)).stroke({ width: V.dampW, color: V.damp, alpha: V.dampA })  // waterline, ON r
    g.poly(outline(RIM * 0.86, 0, 0)).fill({ color: V.sand, alpha: V.sandA })
    g.poly(outline(RIM * 0.5, -RIM * 0.1, -RIM * 0.08)).fill({ color: V.crown, alpha: V.crownA })
    // Wind ripples: near-parallel wavy lines, each cut to the chord of the dry area at its own y so
    // none of them runs off the sand. The whole sprite is rotated per patch, so drawing them all
    // along one axis here costs nothing in variety. The chord is taken against the INSCRIBED circle
    // (1 - LOBE_DEPTH of the dry radius) rather than the dry radius itself: a lobed patch pulls in
    // and a chord measured on the outer radius would run a ripple out over the water at every notch.
    const RR = RIM * 0.82 * (1 - LOBE_DEPTH)
    for (let k = 0; k < V.ripples; k++) {
      const y = -RR + ((k + 0.5) / V.ripples) * RR * 2
      const half = Math.sqrt(Math.max(0, RR * RR - y * y)) * 0.92
      if (half < 14) continue
      g.moveTo(-half, y + Math.sin(-half * 0.02 + k) * 5)
      for (let x = -half + 10; x <= half; x += 10) g.lineTo(x, y + Math.sin(x * 0.02 + k) * 5)
    }
    g.stroke({ width: 3, color: V.ripple, alpha: V.rippleA, cap: 'round' })
    // Shell grit, on a fixed hash so it is baked once and never flickers.
    // Shell grit, on a fixed hash so it is baked once and never flickers. Pulled inside the patch's
    // own profile at each speck's angle, for the same reason the ripples are — grit floating on the
    // water outside a notch is the tell that the outline and the decoration disagree.
    for (let k = 0; k < V.specks; k++) {
      const a = hash(k * 3.7 + 0.5) * Math.PI * 2
      const d = Math.sqrt(hash(k * 5.1 + 2.2)) * RIM * 0.78 * lobeFactor(shapeIdx, a, 0)
      g.circle(Math.cos(a) * d, Math.sin(a) * d, 2 + hash(k * 7.3 + 4.4) * 3)
    }
    g.fill({ color: V.speck, alpha: V.speckA })
    return bake(g)
  })
  const sandPool = []
  function placeSandbar(s, b) {
    s.position.set(b.x, b.y)
    // Shape AND rotation both come off the patch itself, straight from the streamer. The rotation
    // used to be hashed here from the patch's world position — a second, independent derivation of
    // something the sim now also needs, and the classic way two halves of one fact drift apart.
    //
    // A bake is a LOOK — `{ tex, ax, ay }` — not a Texture, so swapping one in means the anchor as
    // well as the texture. Assigning the look straight to `s.texture` throws nothing here and dies
    // deep inside Pixi's sprite pipe on the next render ("Cannot destructure property 'width' of
    // 'texture.orig'"), which reads as a renderer bug rather than as a wrong assignment.
    const look = sandbarTex[b.shape ?? 0] ?? sandbarTex[0]
    s.texture = look.tex
    s.anchor.set(look.ax, look.ay)
    s.rotation = b.rot ?? 0
    s.scale.set(Math.max(b.r, 1) / SAND_BAKE_RIM) // the waterline lands at EXACTLY r
  }

  // Pheromone Lure decoys (run.lures, {x,y,t,dur,...}): a cute beacon the swarm converges on — soft
  // amber glow + a pulsing double-stacked gold star, floated over the crowd so it POPS. Fades in over
  // its first moments; the one-shot burst on expiry renders via the {type:'explode'} event elsewhere.
  // MINIMES share this pool because they share run.lures, but they must NOT share the look: the
  // card is "copies of you", and it was shipping as the Pheromone Lure's amber beacon — a gold
  // star, which reads as a pickup, not as a copy of the player. The body below is T.playerBody,
  // the player's OWN bake, scaled down: the repo's rule is that UI depicting a game entity uses
  // the game's art rather than a lookalike, and here the entity being depicted is the player.
  const lurePool = []
  function acquireLure() {
    const root = new Container()
    const glow = new Sprite(T.fx.circle_05); glow.anchor.set(0.5)
    const ring = new Sprite(T.fx.light_02); ring.anchor.set(0.5)
    const star1 = new Sprite(T.fx.star_04); star1.anchor.set(0.5)
    const star2 = new Sprite(T.fx.star_04); star2.anchor.set(0.5)
    // spriteOf, NOT `new Sprite(T.playerBody)`: bake() returns a LOOK ({tex, ax, ay}), not a
    // Texture, and it carries its own anchor. Constructing the sprite by hand hands Pixi an object
    // and draws nothing at all — no throw, no warning, an empty patch of floor where the copy
    // should be. Caught only by looking at a capture.
    const shadow = spriteOf(T.playerShadow); shadow.visible = false
    const body = spriteOf(T.playerBody); body.visible = false
    // The player's eyes are SEPARATE sprites over the body bake, and the body is TINTED per
    // chapter (chapterRender.playerTint). A copy carrying neither is a different creature: the
    // first capture of this showed a bright mint blob with plain eyes standing next to a dark
    // green player in a visor. Both are reproduced below at the same proportions.
    const eyeL = spriteOf(T.pupil); eyeL.visible = false
    const eyeR = spriteOf(T.pupil); eyeR.visible = false
    root.addChild(glow, ring, star1, star2, shadow, body, eyeL, eyeR)
    lureLayer.addChild(root)
    return { root, glow, ring, star1, star2, shadow, body, eyeL, eyeR }
  }
  function syncLures(list) {
    const n = list.length
    while (lurePool.length < n) lurePool.push(acquireLure())
    for (let i = 0; i < n; i++) {
      const lv = lurePool[i]
      const lu = list[i]
      lv.root.visible = true
      lv.root.position.set(lu.x, lu.y)
      const pulse = 0.5 + 0.5 * Math.sin(animT * 6 + i * 1.3)
      const inA = Math.min(1, lu.t / 0.25) // fade in over the first 0.25s (lu.t ages up to lu.dur)
      // A MINIME IS A SMALL YOU; a planted Pheromone Lure is the amber beacon it always was.
      // `lu.minime` is the sim's own flag (sim.js sets it on the entity it pushes into run.lures).
      const mini = !!lu.minime
      lv.star1.visible = lv.star2.visible = lv.ring.visible = !mini
      lv.body.visible = lv.shadow.visible = lv.eyeL.visible = lv.eyeR.visible = mini
      if (mini) {
        // Keep a faint glow so it still reads as a DECOY the swarm wants, not as a second player —
        // dimmer and cooler than the beacon's, and under the body rather than around it.
        lv.glow.tint = 0xffd36b; lv.glow.alpha = 0.26 * inA * (0.7 + 0.3 * pulse)
        lv.glow.scale.set(fxScale(T.fx.circle_05, 44 + pulse * 8))
        lv.shadow.alpha = 0.5 * inA
        lv.shadow.scale.set(MINIME_DRAW_SCALE)
        lv.shadow.position.set(0, 2)
        lv.body.alpha = inA
        lv.body.scale.set(MINIME_DRAW_SCALE)
        lv.body.tint = chapterRender.playerTint   // the same tint the live player wears
        // Match the PLAYER's own rig, which flips rather than rotates outside the kaiju chapter —
        // a rotating body here would be a different projection from the thing it is a copy of.
        if (lu.vx) lv.body.scale.x = Math.sign(lu.vx) * MINIME_DRAW_SCALE
        // Eyes, at the player's own proportions (syncPlayer's pr * 0.36 / -pr * 0.16), scaled down
        // with the body. No look-around wiggle: a decoy staring straight ahead reads as a decoy.
        const pr = PLAYER.radius * MINIME_DRAW_SCALE
        lv.eyeL.scale.set(MINIME_DRAW_SCALE); lv.eyeR.scale.set(MINIME_DRAW_SCALE)
        lv.eyeL.alpha = lv.eyeR.alpha = inA
        lv.eyeL.position.set(-pr * 0.36, -pr * 0.16)
        lv.eyeR.position.set(pr * 0.36, -pr * 0.16)
        continue
      }
      lv.glow.tint = 0xffd36b; lv.glow.alpha = 0.5 * inA * (0.7 + 0.3 * pulse)
      lv.glow.scale.set(fxScale(T.fx.circle_05, 70 + pulse * 14))
      lv.ring.tint = 0xffe9a0; lv.ring.alpha = 0.55 * inA
      lv.ring.scale.set(fxScale(T.fx.light_02, 54 + pulse * 10))
      const ssc = fxScale(T.fx.star_04, 30 + pulse * 6)
      lv.star1.tint = lv.star2.tint = 0xff9d1a
      lv.star1.scale.set(ssc); lv.star2.scale.set(ssc)
      lv.star1.rotation = animT * 1.5; lv.star2.rotation = -animT * 1.2
      lv.star1.alpha = lv.star2.alpha = inA
    }
    for (let i = n; i < prevCount.lure; i++) lurePool[i].root.visible = false
    prevCount.lure = n
  }

  // Pesticide spray strips (run.strips): telegraphed rotated rectangles — one shared Graphics cleared/
  // redrawn per frame, same telegraph idiom as redrawBombs (Graphics is the sanctioned exception for
  // ground telegraphs). During `fuse`: a pulsing amber warning outline that ramps urgency toward 0
  // (no hazard fill yet). Once live: a filled acid-green hazard strip fading over its remaining life.
  function redrawStrips(run) {
    stripG.clear()
    for (const s of run.strips || []) {
      const cos = Math.cos(s.angle), sin = Math.sin(s.angle)
      const hx = s.len / 2, hy = s.w / 2
      const flat = []
      for (const [lx, ly] of [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]]) {
        flat.push(s.x + lx * cos - ly * sin, s.y + lx * sin + ly * cos)
      }
      // v5.24 the blank (look:'erase' — erasure bands, eraser wakes, immuneMemory residue): a strip
      // of world going BLANK. v6.6.14: this is now the ONLY kind of strip in the game. The garden's
      // pesticide spray was the other one, and it is gone — its elite drives a visible mower now
      // (see the MOWER_* block in config.js), because a rectangle drawn on the player by an
      // offscreen ant is a hazard with no cause anyone could see. Fuses here vary per source
      // (0.15-0.75s), so the warning is a flat pulse rather than a fuse-normalised urgency ramp,
      // and active strips fade over their last half second.
      // v6.3.1: strips tagged variant:'residue' (immuneMemory death residue, eraser wakes) draw at
      // ~0.55× alpha, fuse and live alike — at d3 they can be onscreen alongside the boss's OWN
      // (untagged, full-strength) bands/star, and three identical erase hazard families stacked
      // would blur into one illegible mess [panel/fun].
      if (s.look === 'erase') {
        const dim = s.variant === 'residue' ? 0.55 : 1
        if (s.fuse > 0) {
          const pulse = 0.5 + 0.5 * Math.sin(animT * 9)
          stripG.poly(flat).fill({ color: 0xdde4ee, alpha: (0.16 + pulse * 0.1) * dim })
          stripG.poly(flat).stroke({ width: 3, color: 0x9aa6c4, alpha: (0.55 + pulse * 0.3) * dim })
        } else {
          const fade = Math.min(1, s.t / 0.5)
          stripG.poly(flat).fill({ color: 0xdde4ee, alpha: 0.9 * fade * dim })
          stripG.poly(flat).stroke({ width: 2.5, color: 0x9aa6c4, alpha: 0.85 * fade * dim })
        }
      }
    }
  }

  // ---- v5.4 chapter-4-7 field elements -----------------------------------------------------
  // Every one of these guards its run.* field (`run.traps || []`): the sim half lands in parallel,
  // and a chapter that never seeds the array must render nothing rather than throw.
  //
  // Snap traps (undergrowth signature, run.traps {x,y,r,armed,rearmAt,_cell} — v6.5, STREAMED by
  // sim.js's streamTraps, see that function's doc): permanent furniture that bites BOTH sides, so
  // it's drawn to be read at a glance — the armed texture is a wide toothed ring, the sprung one a
  // shut bar (see the bakes). rearmAt is an ABSOLUTE run.time (0 while armed); a sprung trap dims
  // to alpha 0.45 and lifts back to full as `simTime` (latched once per frame in sync(), before
  // this pool syncs) closes on rearmAt, so "this one is about to be live again" is legible without
  // a number. An armed trap breathes so it reads as hot even when you're not looking at it. Any
  // trap — armed or sprung — within AMBUSH_R of the player also carries a warm pulse while
  // WEAPON_MODS.clawRake.ambushPredator is held (ambushHeld/ambushPX/ambushPY, same per-frame
  // latch), mirroring the armed-or-sprung contract slashClaws' own scan uses (sim.js).
  const trapPool = []

  // v5.21 lane: an asteroid. Reuses T.asteroid — the same rock already scattered as this chapter's
  // baked obstacle furniture, which is the point: the hazard IS the local debris, not a new species.
  // Tumble comes from rk.rot (sim-owned, so it survives a pause and matches across a re-render).
  const rockPool = []
  function placeRock(s, rk) {
    if (s.texture !== T.asteroid.tex) { s.texture = T.asteroid.tex; s.anchor.set(T.asteroid.ax, T.asteroid.ay) }
    s.position.set(rk.x, rk.y)
    s.rotation = rk.rot
    s.scale.set((rk.r * 2) / Math.max(T.asteroid.tex.width, T.asteroid.tex.height))
    // Warm stone, deliberately OFF the chapter's lilac. The ambient debris drifting past is
    // 0xcfc8e0-ish, and a hazard that shares a palette with scenery is a hazard nobody dodges.
    s.tint = 0xc9a887
    s.alpha = 1
  }

  function placeTrap(s, tr) {
    const look = tr.armed ? T.trapArmed : T.trapSprung
    if (s.texture !== look.tex) { s.texture = look.tex; s.anchor.set(look.ax, look.ay) }
    s.position.set(tr.x, tr.y)
    const sc = (tr.r || 30) / 15 // both traps are baked at a 15px working radius
    let tint = 0xffffff
    let alpha = 1
    if (tr.armed) {
      s.scale.set(sc * (1 + 0.03 * Math.sin(animT * 3 + (tr.x + tr.y) * 0.05)))
      s.rotation = 0
    } else {
      // re-arm tell: the closer simTime gets to rearmAt (an absolute run.time), the
      // brighter/steadier the sprung trap sits
      const k = SNAP_TRAP_REARM > 0 ? 1 - Math.max(0, Math.min(1, (tr.rearmAt - simTime) / SNAP_TRAP_REARM)) : 1
      tint = mix(0x6b727c, 0xffffff, k)
      alpha = 0.45 + k * 0.5
      s.scale.set(sc)
      s.rotation = 0
    }
    // ambushPredator tell (render-only, fun F1): armed OR sprung — mirrors slashClaws' scan, so
    // springing your own trap can't visibly look like it switched the buff off.
    if (ambushHeld) {
      const dx = tr.x - ambushPX, dy = tr.y - ambushPY
      if (dx * dx + dy * dy <= AMBUSH_R * AMBUSH_R) {
        const pulse = 0.5 + 0.5 * Math.sin(animT * 6)
        tint = mix(tint, 0xfff2c0, 0.3 + 0.25 * pulse)
        alpha = Math.min(1, alpha + 0.15 * pulse)
      }
    }
    s.tint = tint
    s.alpha = alpha
  }

  // Traffic lanes (city signature, run.lanes): 'warn' telegraphs the approach, then 'sweep' runs a
  // vehicle down the band. One shared Graphics cleared and redrawn per frame (the redrawStrips
  // idiom). The two vehicles that ride run.lanes want opposite telegraphs and get them below: the
  // garden's mower shows the stripe it is about to cut, the city's van shows its headlights.
  function redrawLanes(run) {
    laneG.clear()
    for (const ln of run.lanes || []) {
      const cos = Math.cos(ln.angle)
      const sin = Math.sin(ln.angle)
      const hx = ln.len / 2
      const hy = ln.w / 2
      const flat = []
      for (const [lx, ly] of [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]]) {
        flat.push(ln.x + lx * cos - ly * sin, ln.y + lx * sin + ly * cos)
      }
      const warn = ln.phase === 'warn'
      const warnT = ln.warnT ?? TRAFFIC_WARN
      const urgency = warn ? (warnT > 0 ? 1 - ln.t / warnT : 1) : 1
      const pulse = 0.5 + 0.5 * Math.sin(animT * (6 + urgency * 16))
      const fillA = warn ? 0.06 + urgency * 0.1 + pulse * 0.04 : 0.05
      const rimA = warn ? Math.min(1, 0.45 + urgency * 0.4 + pulse * 0.12) : 0.3
      // v6.6.14: two vehicles share this band now. The mower's telegraph is the STRIPE A MOWER
      // LEAVES — pale cut grass running the length of the lane — so the shape itself says what is
      // coming, while the rim stays the same warning amber the city uses (the hazard reading is
      // carried by the rim, not by inventing a second danger colour). Deliberately NOT green: the
      // floor is lawn, and the garden already spends amber on pheromone trails and green on webs.
      const mower = ln.look === 'mower'
      if (mower) {
        // The mower keeps its v6.6.14 volume EXACTLY — the owner named it (with the toad) as the
        // level everything else should come down to, so it is the reference, not a target.
        laneG.poly(flat).fill({ color: 0xf2ecd0, alpha: fillA * 1.6 })
        laneG.poly(flat).stroke({ width: 3, color: 0xffe37a, alpha: rimA })
        // mown rows ALONG the lane — the one pattern nothing else in this game draws
        for (let i = -1; i <= 1; i++) {
          const off = i * hy * 0.5
          laneG.moveTo(ln.x - hx * cos - off * sin, ln.y - hx * sin + off * cos)
          laneG.lineTo(ln.x + hx * cos - off * sin, ln.y + hx * sin + off * cos)
          laneG.stroke({ width: 2, color: 0xffffff, alpha: (warn ? 0.16 + urgency * 0.16 : 0.1) * (0.7 + 0.3 * pulse) })
        }
      } else {
        // v6.9.1 (owner: "their telegraph should be like headlights, not a bland yellow rectangle —
        // it should move in front of the car, get brighter when the car is closer"). The v6.7.5
        // telegraph was a static amber slab plus four chevrons: a DIAGRAM of the hazard, drawn all
        // at once, saying nothing about how far off it was. What warns you on a real street is the
        // car's own headlights arriving before the car, so that is what this draws — and it draws
        // them in syncCars, on the SAME rig that carries the van, not here. Two reasons:
        //   - they are literally the same lights. The rig's glow sprite runs through the telegraph
        //     and straight on into the sweep with nothing switching over, which is the whole read.
        //   - a beam has no edge. Drawn as Graphics it needs a gradient Pixi's fills do not have;
        //     the stacked-cone workaround came back with visible straight steps across the asphalt,
        //     which is worse than the slab it replaced. The soft fx sprite is edgeless for free.
        // What stays here is the two long lane edges as hairlines: the beam only lights the stretch
        // it has reached, and "be outside these" has to hold for the whole band. No chevrons — a
        // beam already points where it is going.
        for (const s of [-1, 1]) {
          laneG.moveTo(ln.x - hx * cos - s * hy * sin, ln.y - hx * sin + s * hy * cos)
          laneG.lineTo(ln.x + hx * cos - s * hy * sin, ln.y + hx * sin + s * hy * cos)
        }
        laneG.stroke({ width: 1.5, color: 0xffe37a, alpha: warn ? 0.18 + urgency * 0.26 + pulse * 0.12 : 0.16 })
      }
      // v6.3 Task 4: "this can shield you" — during the telegraph only, ring every obstacle big
      // enough to stop the car (o.r >= COVER_MIN_R, see its doc in config.js) whose center falls
      // inside this band. Same along/perp test as the quad above, padded by the obstacle's own
      // radius so a shield merely clipping the band's edge still lights up.
      // ln.cover === false (the mower) skips this ENTIRELY: sim.js does not consult findCover for
      // such a lane, and garden obstacles do sit in the >= COVER_MIN_R band, so drawing the ring
      // here would visibly promise a shield that does nothing.
      if (warn && ln.cover !== false) {
        for (const o of run.obstacles || []) {
          if (o.r < COVER_MIN_R) continue
          const odx = o.x - ln.x, ody = o.y - ln.y
          const along = odx * cos + ody * sin
          const perp = -odx * sin + ody * cos
          if (Math.abs(along) > hx + o.r || Math.abs(perp) > hy + o.r) continue
          laneG.circle(o.x, o.y, o.r + 5).stroke({ width: 2.5, color: 0xffe37a, alpha: 0.5 + 0.2 * pulse })
        }
      }
    }
  }

  // The car itself: one rig per live lane — the baked vehicle plus the pair of headlight washes it
  // throws down the street. Its centre is (x,y) + dir × ((carT - 0.5) × len), straight off the
  // contract, EXCEPT during the city's telegraph, where the body is hidden and the rig is parked
  // TRAFFIC_APPROACH px back up the lane, sliding forward so it arrives exactly as the sweep starts
  // (v6.9.1 — see the redrawLanes branch and TRAFFIC_APPROACH's doc in config.js). One rig for both
  // phases is the point: nothing switches over between the warning and the thing it warned about.
  const carPool = []
  let carCount = 0
  // v6.6.14: the pool holds BOTH vehicles, so a rig has one sprite per look and shows the one this
  // lane calls for. A single shared sprite would have put a taxi on the lawn.
  function acquireCar() {
    const root = new Container()
    const glows = [0, 1].map(() => {
      const g = new Sprite(T.fx.light_02)
      g.anchor.set(0.5)
      g.tint = 0xfff3c4
      root.addChild(g)
      return g
    })
    const body = spriteOf(T.car)
    const mower = spriteOf(T.mower)
    root.addChild(body, mower)
    carLayer.addChild(root)
    return { root, glows, body, mower }
  }
  // The cut lawn itself. Finished stripes never change, so the geometry is only rebuilt while a
  // mower is mid-pass (mownDirty) — every other frame this is a no-op and the Graphics just draws.
  // PALER than the garden floor (0x4e8240), which is how a fresh cut reads; the rows along it are
  // the same pattern the mower's telegraph uses, so the promise and the result match. Kept
  // translucent — cut grass is still grass, and the floor's blotches and foliage must show through.
  // v6.6.26 (owner: "less yellow cut grass"). It was paler AND yellower: sampled off the live
  // canvas, the finished stripe composited to hue 91 deg against the lawn's 107 (and the rows to
  // 83), i.e. a 16-24 deg pull toward yellow on top of the +10 brightness. Cut grass is lighter,
  // not yellower — yellow is what a DEAD lawn looks like. Both colours are re-picked to composite
  // back to ~100 deg at 50%/45% alpha over 0x4e8240, so the stripe keeps the value lift that makes
  // it legible and loses the hue shift that made it look scorched.
  function redrawMown() {
    if (!mownDirty) return
    mownDirty = false
    mownG.clear()
    for (const st of mown) {
      if (st.len <= 1) continue
      const cos = Math.cos(st.angle)
      const sin = Math.sin(st.angle)
      const hx = st.len / 2
      const hy = st.w / 2
      const flat = []
      for (const [lx, ly] of [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]]) {
        flat.push(st.x + lx * cos - ly * sin, st.y + lx * sin + ly * cos)
      }
      mownG.poly(flat).fill({ color: 0x78aa56, alpha: 0.5 })
      for (let i = -1; i <= 1; i++) {
        const off = i * hy * 0.5
        mownG.moveTo(st.x - hx * cos - off * sin, st.y - hx * sin + off * cos)
        mownG.lineTo(st.x + hx * cos - off * sin, st.y + hx * sin + off * cos)
        mownG.stroke({ width: 2, color: 0x92c977, alpha: 0.45 })
      }
    }
  }

  function syncCars(run) {
    // A car lane gets its rig for the WHOLE lane, telegraph included (v6.9.1); a mower lane only
    // once its deck is actually on the grass, because the mower's telegraph is the stripe it is
    // about to cut and a machine hovering at the end of it would say the opposite.
    const lanes = (run.lanes || []).filter((l) => l.phase === 'sweep' || l.look !== 'mower')
    while (carPool.length < lanes.length) carPool.push(acquireCar())
    for (let i = 0; i < lanes.length; i++) {
      const ln = lanes[i]
      const cv = carPool[i]
      const isMower = ln.look === 'mower'
      const warn = ln.phase === 'warn'
      // How lit the beams are, 0..1. During the telegraph this IS how close the car is; once it is
      // on the lane it is simply full, so nothing dips at the handover.
      const lit = warn ? 1 - ln.t / (ln.warnT ?? TRAFFIC_WARN) : 1
      cv.root.visible = true
      // Telegraph: the lamps sit TRAFFIC_APPROACH px back up the lane and slide forward, reaching
      // the lane's entry (carT 0, i.e. -len/2) exactly as the sweep begins.
      const d = warn
        ? -ln.len / 2 - (1 - lit) * TRAFFIC_APPROACH
        : ((ln.carT ?? 0) - 0.5) * ln.len
      const cx = ln.x + Math.cos(ln.angle) * d
      const cy = ln.y + Math.sin(ln.angle) * d
      cv.root.position.set(cx, cy)
      cv.root.rotation = ln.angle
      cv.body.visible = !isMower && !warn
      cv.mower.visible = isMower && !warn
      cv.body.scale.set(1)
      cv.mower.scale.set(1)
      // The headlights: a PAIR of soft washes thrown well down the lane, flickering just enough to
      // feel driven. Their length is TRAFFIC_BEAM, so during the telegraph the light reaches a
      // player standing at the lane's centre long before the van does — which is the entire job of
      // a telegraph, done by the object that is coming rather than by a rectangle drawn around it.
      // A mower on a sunlit lawn at noon has no headlights.
      for (let g = 0; g < 2; g++) {
        const s = cv.glows[g]
        s.visible = !isMower
        s.position.set(TRAFFIC_BEAM * 0.42, (g ? 1 : -1) * TRAFFIC_CAR_W * 0.26)
        s.scale.set(fxScale(T.fx.light_02, TRAFFIC_BEAM * 0.95), fxScale(T.fx.light_02, TRAFFIC_CAR_W * 1.15))
        s.alpha = (0.16 + lit * 0.4) * (0.94 + 0.06 * Math.sin(animT * 22 + g))
      }
      const backLen = (isMower ? MOWER_DECK_LEN : TRAFFIC_CAR_LEN) * 0.5
      // v6.6.22: grow this pass's cut. The stripe runs from the lane's tail to the deck's leading
      // edge, so grass goes short UNDER the mower rather than appearing once it has gone by. One
      // entry per pass (keyed off the lane object, which survives the whole sweep), extended in
      // place — the mower does not lay down a new stripe every frame.
      if (isMower) {
        let st = mownByLane.get(ln)
        if (!st) {
          st = { x: ln.x, y: ln.y, angle: ln.angle, w: ln.deckW ?? MOWER_DECK_W, len: 0 }
          mownByLane.set(ln, st)
          mown.push(st)
          if (mown.length > MOWN_MAX) mown.shift()
        }
        const cut = Math.max(0, Math.min(ln.len, d + ln.len / 2 + backLen))
        if (cut !== st.len) {
          st.len = cut
          const mid = -ln.len / 2 + cut / 2
          st.x = ln.x + Math.cos(ln.angle) * mid
          st.y = ln.y + Math.sin(ln.angle) * mid
          mownDirty = true
        }
      }
      if (!warn && frameDt > 0 && Math.random() < (isMower ? 0.9 : 0.5)) {
        // the car throws exhaust and road spray; the mower throws CLIPPINGS — same particle, sprayed
        // sideways out of the deck rather than straight back, because that is where a chute points
        const side = isMower ? (Math.random() < 0.5 ? 1 : -1) : 0
        const nx = -Math.sin(ln.angle) * side * 70
        const ny = Math.cos(ln.angle) * side * 70
        spawnParticle(T.fx.circle_05, cx - Math.cos(ln.angle) * backLen, cy - Math.sin(ln.angle) * backLen,
          -Math.cos(ln.angle) * 40 + nx, -Math.sin(ln.angle) * 40 + ny,
          isMower ? 0.45 : 0.3, isMower ? 0.06 : 0.08, isMower ? 0x7cb342 : 0x8f959d, 0.1, 2)
      }
    }
    for (let i = lanes.length; i < carCount; i++) carPool[i].root.visible = false
    carCount = lanes.length
  }

  // Gravity wells (beyond signature, run.wells {x,y,r,g}): permanent, harmless, and they BEND every
  // projectile that flies through — so the field has to be legible without ever reading as damage.
  // Deliberately NOT the black hole's look (that's the player's weapon and it kills): no dark core,
  // no vortex. Instead a cold open ring with inward-drifting contour rings and CURVED streamlines
  // that show which way a shot gets bent — the animation flows inward, so the pull direction reads.
  // v5.23.7: the glow is CIRCLES, not a stretched texture. It used to be T.holeDisc — a 512px
  // canvas radial gradient — blown up to the well's ~380px diameter and laid on the darkest
  // background in the game. One reporter sees a hard-edged rectangle stuck to the well, measured at
  // exactly that sprite's width with hard top and bottom edges: a sprite's own QUAD, showing where
  // only a soft disc should be. Same device, and the same class of fault, as the ring that drew
  // nothing through a canvas clip() in v5.23.5. So the well stops going through a canvas texture at
  // all — the glow is now nested fills in wellG, the Graphics that was already drawing every other
  // part of this thing. A quad that isn't there cannot show its edges, and the pooled sprite, its
  // syncPool call and the well's prevCount slot all go with it.
  const WELL_GLOW = [[1.0, 0.03], [0.86, 0.035], [0.72, 0.04], [0.58, 0.045],
    [0.44, 0.05], [0.3, 0.055], [0.18, 0.06]]
  function syncWells(run) {
    const list = run.wells || []
    wellG.clear()
    for (let i = 0; i < list.length; i++) {
      const w = list[i]
      const r = w.r || 190
      // The glow, outermost first so the alphas stack toward the middle the way the gradient's did.
      for (const [f, a] of WELL_GLOW) wellG.circle(w.x, w.y, r * f).fill({ color: 0x4a3a86, alpha: a })
      wellG.circle(w.x, w.y, r).stroke({ width: 2, color: 0x9fb0ff, alpha: 0.3 }) // influence edge
      // contour rings drifting inward: three rings sharing one phase, respawning at the rim
      for (let k = 0; k < 3; k++) {
        const p = ((animT * 0.35 + k / 3 + i * 0.17) % 1)
        const rr = r * (1 - p)
        wellG.circle(w.x, w.y, Math.max(2, rr)).stroke({ width: 1.6, color: 0xbfc8ff, alpha: 0.32 * p })
      }
      // streamlines: short arcs spiralling in, drawn as real curves so the BEND is the message
      for (let k = 0; k < 8; k++) {
        const a0 = (k / 8) * Math.PI * 2 + animT * 0.25 + i * 0.4
        wellG.beginPath()
        for (let j = 0; j <= 8; j++) {
          const f = j / 8
          const rr = r * (0.92 - f * 0.55)
          const a = a0 + f * 0.85 // the swirl: angle advances as the radius closes
          const px = w.x + Math.cos(a) * rr
          const py = w.y + Math.sin(a) * rr
          if (j === 0) wellG.moveTo(px, py)
          else wellG.lineTo(px, py)
        }
        wellG.stroke({ width: 1.4, color: 0x9fb0ff, alpha: 0.28 })
      }
      const core = 0.5 + 0.5 * Math.sin(animT * 2 + i)
      wellG.circle(w.x, w.y, r * 0.07 + core * 2).fill({ color: 0xdfe4ff, alpha: 0.5 })
    }
  }

  // Binding-node filaments (v5.24 the blank, P2): a line from every alive 'bindnode' enemy to the
  // player, thickening and saturating toward the player's violet as the node ages (e._bindT,
  // sim-owned, 0 -> BLANK_YANK_T) — the line getting heavier IS the yank countdown. Filtered off
  // run.enemies directly; no chapter gate needed, the rosterId exists nowhere else. A gentle
  // sag in the middle keeps it reading as a strand under tension, not a laser.
  function syncBinds(run) {
    bindG.clear()
    const p = run.player
    for (const e of run.enemies) {
      if (e.rosterId !== 'bindnode') continue
      const k = Math.min(1, (e._bindT || 0) / BLANK_YANK_T)
      const color = mix(0x8880a8, 0x8a5fe0, k)
      // sag: a quadratic bowed perpendicular to the strand, straightening as the yank nears
      const mx = (e.x + p.x) / 2, my = (e.y + p.y) / 2
      const dx = p.x - e.x, dy = p.y - e.y
      const len = Math.hypot(dx, dy) || 1
      const bow = len * 0.06 * (1 - k) * Math.sin(animT * 2.2 + e.id)
      bindG.moveTo(e.x, e.y)
      bindG.quadraticCurveTo(mx - (dy / len) * bow, my + (dx / len) * bow, p.x, p.y)
      bindG.stroke({ width: 1.5 + k * 4, color, alpha: 0.35 + k * 0.5, cap: 'round' })
      bindG.circle(e.x, e.y, 4 + k * 3).fill({ color, alpha: 0.5 + k * 0.4 }) // root bead on the node
    }
  }

  // Hydrant zones + reality rifts (run.zones {x,y,r,fuse,dur,dmg}) and Debris Toss landing rings
  // (run.lobs): both are "this circle is about to go off", so they share one telegraph Graphics.
  // Zones damage ENEMIES ONLY, so they're drawn in a cool sewer-green that can never be mistaken
  // for the red volatile-bomb telegraph (bombG) that hurts YOU — the colour IS the safety cue.
  function redrawHazards(run) {
    hazardG.clear()
    for (const gy of run.zones || []) {
      // A Burst Hydrant zone (jetDur set) is drawn by the hydrant rig in syncJets. All that belongs
      // here is its RADIUS, because the radius is the hitbox and nothing else on the rig carries
      // it — the hydrant is a fixed-size object and the water sits well inside the edge. A thin
      // cool ring, deliberately quiet: the player needs to be able to find it, not look at it, and
      // a dozen of these can overlap. Cool white-blue, nowhere near the amber/red that means "this
      // one hurts YOU".
      if (gy.jetDur > 0) {
        if (gy.delay > 0) continue          // dormant, not yet arrived
        // The RANGE ring is drawn only while the hydrant is on its fuse — it is the telegraph, and
        // that is the one moment the player needs to know how far this thing will reach before
        // deciding where to stand. Once it is spraying, the streams show exactly what is being hit,
        // so the ring is pure clutter: several live hydrants each drawing a 256px circle is what
        // made the effect unreadable, and aimed streams are the whole reason it no longer has to.
        if (gy.fuse > 0) {
          const dur = Math.max(0.001, gy.dur || 1)
          const urgency = 1 - Math.max(0, Math.min(1, gy.fuse / dur))
          hazardG.circle(gy.x, gy.y, gy.r).stroke({ width: 2, color: 0xbcd8e0, alpha: 0.16 + urgency * 0.26 })
          hazardG.circle(gy.x, gy.y, gy.r * urgency).stroke({ width: 1.5, color: 0xdfeef2, alpha: 0.14 + urgency * 0.18 })
        }
        continue
      }
      // A seam (a zone carrying `d`) draws itself: the green bubbling grate below is the SEWER's
      // safety cue, and a seam has nothing to warn you about — zones never touch the player.
      if (gy.d > 0) { riftTelegraph(gy); continue }
      const dur = Math.max(0.001, gy.dur || 1)
      const urgency = 1 - Math.max(0, Math.min(1, gy.fuse / dur))
      const pulse = 0.5 + 0.5 * Math.sin(animT * (5 + urgency * 18))
      // v6.10: fill DOWN, rim UP. Up to ZONE_MAX_LIVE zones can overlap now that jets persist,
      // and a stack of translucent discs is soup — the rim is what has to survive the overlap,
      // because with a live jet the rim IS the hitbox and the player routes around it.
      hazardG.circle(gy.x, gy.y, gy.r).fill({ color: 0x3fae7a, alpha: 0.05 + urgency * 0.08 + pulse * 0.03 })
      hazardG.circle(gy.x, gy.y, gy.r).stroke({ width: 2.5 + urgency * 2.5, color: 0x6fe0a8, alpha: Math.min(1, 0.55 + urgency * 0.4) })
      // the charge: an inner ring swelling toward the rim as the fuse burns down
      hazardG.circle(gy.x, gy.y, gy.r * urgency).stroke({ width: 2, color: 0xbfffe0, alpha: 0.35 + pulse * 0.2 })
      if (frameDt > 0 && Math.random() < 0.35) { // bubbles boiling up out of the grate
        const a = Math.random() * Math.PI * 2
        const d = Math.random() * gy.r * 0.7
        spawnParticle(T.fx.circle_05, gy.x + Math.cos(a) * d, gy.y + Math.sin(a) * d,
          0, -30 - urgency * 40, 0.4, 0.05, 0x6fe0a8, 0.05, 0.5)
      }
    }
    for (const lb of run.lobs || []) { // where the thrown chunk is going to land
      const k = Math.max(0, Math.min(1, lb.t / Math.max(0.001, lb.flight)))
      hazardG.circle(lb.tx, lb.ty, lb.r).stroke({ width: 2, color: 0xffb37a, alpha: 0.25 + k * 0.45 })
      hazardG.circle(lb.tx, lb.ty, lb.r * k).fill({ color: 0xffb37a, alpha: 0.12 })
    }
  }

  // ---- v6.10 the burst hydrant --------------------------------------------------------------
  // A rig per Burst Hydrant zone, live for BOTH phases of its life: the hydrant stands on the street
  // rattling while the fuse burns, then its cap blows off and it sheets water until the main runs
  // dry. The telegraph is therefore a physical object you can see coming, not a disc painted on the
  // road — which is the whole reason four passes of translucent zone art got thrown away.
  //
  // The hydrant is drawn at a FIXED pixel size. Every other zone visual in this game scales with
  // its radius; this one must not, because it is an object and objects do not grow when the weapon
  // levels. The damage radius is carried by a thin ring in hazardG instead. Decoupling the art from
  // the hitbox is what finally let the effect be small, opaque and high-contrast while the zone
  // itself stays 128px wide.
  //
  // THE CAMERA LOOKS STRAIGHT DOWN. The hydrant is its bonnet seen from above, the water sheets
  // flat across the asphalt, the cap tumbles along the ground. Nothing here is a side elevation —
  // v6.8 shipped that mistake once with the Trash Tornado and it cost a version to undo.
  function acquireJet() {
    const root = new Container()
    const crack = spriteOf(T.jetCrack)
    const source = spriteOf(T.jetSource)
    // Two sprites per stream (a dense white core and a looser rinse-coloured spread) so a stream
    // has depth without a second bake per target. HYDRANT_STREAMS_MAX is the ceiling the sim
    // clamps to, so every target the sim picks always has a jet to be drawn with.
    const streams = []
    for (let i = 0; i < HYDRANT_STREAMS_MAX; i++) {
      streams.push(T.jetStream.map((look) => {
        const sp = spriteOf(look)
        root.addChild(sp)
        return sp
      }))
    }
    const body = spriteOf(T.hydrantCapped)
    const cap = spriteOf(T.hydrantCap)
    root.addChild(crack, source, body, cap)
    jetLayer.addChild(root)
    return { root, crack, source, streams, body, cap }
  }

  // `list` is every Burst Hydrant zone — fuse phase AND open phase. Zones without a jetDur are
  // Reality Shard rifts, which keep their own green telegraph in redrawHazards and never get a
  // hydrant; filtering them out is the caller's job.
  function syncJets(list) {
    const n = list.length
    while (jetPool.length < n) jetPool.push(acquireJet())
    for (let i = 0; i < n; i++) {
      const rig = jetPool[i]
      const gy = list[i]
      rig.root.visible = true
      rig.root.position.set(gy.x, gy.y)
      const k = gy.r / JET_BAKE_R
      // A hydrant is bolted to the street: fixed heading per zone, never spinning. Derived from the
      // position so it is stable frame to frame without render having to store anything.
      const face = ((gy.x * 0.013 + gy.y * 0.017) % 1) * Math.PI * 2

      if (gy.jet > 0) {
        // ---- open: the cap is off ----
        const life = Math.max(0.001, gy.jetDur || 1)
        const age = 1 - Math.max(0, Math.min(1, gy.jet / life))
        const swell = age < 0.10 ? age / 0.10 : 1 - Math.max(0, (age - 0.7) / 0.3) * 0.65
        const fade = 1 - Math.max(0, (age - 0.85) / 0.15)
        rig.root.alpha = 1
        rig.crack.visible = true
        rig.crack.scale.set(HYDRANT_PX / JET_BAKE_R)   // scars the street at the BASE, not the rim
        rig.crack.rotation = face
        rig.crack.alpha = 1
        if (rig.body.texture !== T.hydrantOpen.tex) {
          rig.body.texture = T.hydrantOpen.tex
          rig.body.anchor.set(T.hydrantOpen.ax, T.hydrantOpen.ay)
        }
        rig.body.scale.set(HYDRANT_PX / JET_BAKE_R)
        rig.body.rotation = face
        rig.body.alpha = 1
        // The cap, thrown clear on eruption and skittering to a stop. Its whole travel happens in
        // the first ~15% of the life; after that it just lies there.
        const fly = Math.min(1, age / 0.15)
        rig.cap.visible = true
        rig.cap.scale.set(HYDRANT_PX / JET_BAKE_R)
        rig.cap.position.set(Math.cos(face + 2.1) * 34 * fly, Math.sin(face + 2.1) * 34 * fly)
        rig.cap.rotation = fly * 7
        rig.cap.alpha = 0.9
        rig.source.visible = true
        rig.source.scale.set((HYDRANT_PX / JET_BAKE_R) * swell * (1 + 0.1 * Math.sin(animT * 13 + i)))
        rig.source.rotation = animT * 1.6 + i
        rig.source.alpha = 0.85 * fade
        // One stream per target the sim locked this frame (g.streams, positions not ids). Local
        // coordinates: the root is already at the hydrant, so a target is just its offset.
        const targets = gy.streams || []
        for (let t = 0; t < rig.streams.length; t++) {
          const pair = rig.streams[t]
          const tg = targets[t]
          if (!tg) { for (const sp of pair) sp.visible = false; continue }
          const dx = tg.x - gy.x, dy = tg.y - gy.y
          const dist = Math.max(1, Math.hypot(dx, dy))
          const ang = Math.atan2(dy, dx)
          pair.forEach((sp, j) => {
            sp.visible = true
            sp.rotation = ang
            // x scales to reach the target; y stays near 1 so the cone keeps its baked spread
            // instead of getting fat on long shots. The wobble is what makes it look like water
            // under pressure rather than a static wedge.
            sp.scale.set(dist / (JET_BAKE_R * 2), (0.85 + j * 0.35) * (1 + 0.12 * Math.sin(animT * 17 + t * 2 + j)))
            sp.alpha = (j === 0 ? 0.95 : 0.55) * fade * swell
          })
        }
        if (frameDt > 0) jetSpray(gy, 1, 0xffffff)
        continue
      }

      // ---- fuse: intact, and shaking ----
      const dur = Math.max(0.001, gy.dur || 1)
      const urgency = 1 - Math.max(0, Math.min(1, gy.fuse / dur))
      rig.root.alpha = 1
      rig.crack.visible = false
      rig.cap.visible = false
      rig.source.visible = false
      for (const pair of rig.streams) for (const sp of pair) sp.visible = false
      if (rig.body.texture !== T.hydrantCapped.tex) {
        rig.body.texture = T.hydrantCapped.tex
        rig.body.anchor.set(T.hydrantCapped.ax, T.hydrantCapped.ay)
      }
      rig.body.scale.set((HYDRANT_PX / JET_BAKE_R) * (1 + urgency * 0.12))
      rig.body.rotation = face
      rig.body.alpha = 1
      // The rattle: amplitude and frequency both climb as the fuse burns down, so how close the
      // eruption is is readable from the object itself and not only from the ring around it.
      const shake = urgency * urgency * 3.2
      rig.body.position.set(Math.sin(animT * (26 + urgency * 40)) * shake,
        Math.cos(animT * (31 + urgency * 44)) * shake * 0.7)
      if (frameDt > 0 && Math.random() < urgency * 0.4) {   // water starting to weep out of the seams
        const a = Math.random() * Math.PI * 2
        spawnParticle(T.fx.circle_05, gy.x, gy.y, Math.cos(a) * 30, Math.sin(a) * 30,
          0.28, 0.05, 0xdfeef2, -0.01, 3.0)
      }
    }
    for (let i = n; i < prevCount.jet; i++) jetPool[i].root.visible = false
    prevCount.jet = n
  }

  // Droplets thrown outward and dragged to a stop before the rim, so the water reads as landing
  // inside the zone rather than escaping it. MAX_PARTICLES is 200 across the whole game and
  // ZONE_MAX_LIVE allows 12 jets, so this stays deliberately stingy per jet rather than
  // budgeting for one beautiful hydrant in isolation.
  function jetSpray(gy, rate, tint) {
    if (Math.random() > 0.5 * rate) return
    const a = Math.random() * Math.PI * 2
    const sp = gy.r * (0.9 + Math.random() * 1.0)
    spawnParticle(T.fx.circle_05, gy.x, gy.y, Math.cos(a) * sp, Math.sin(a) * sp,
      0.34 + Math.random() * 0.18, 0.08, tint, -0.02, 3.6)
  }

  // ---- v5.4 roster attack telegraphs -------------------------------------------------------
  // The chapter-4-7 predators all commit to an attack they cannot steer out of, and every one of
  // them snapshots its heading/target at the START of a telegraph phase — so what render draws
  // here is not a hint, it's the literal path. Sidestepping it always works; that's the contract.
  // Read off the phase state each sim step keeps on the enemy (_pounceState/_airState/
  // _chargeState/_beamState/_coneAngle), all of which MUST be guarded: the roster flags are
  // per-chapter, and title/daily/archetype-fallback enemies carry none of them.
  //
  // The colour IS the safety cue, the same rule redrawHazards' green zones follow. Four of these
  // five end in the player taking damage, so they speak the established amber hazard language of
  // the traffic lanes and spray strips (0xffd24a fill / 0xffe37a rim), tightening and quickening
  // as the fuse burns down. The flashlight cone is the deliberate exception — see its block.
  function redrawTelegraphs(run) {
    teleG.clear()
    const p = run.player
    for (const e of run.enemies) {
      // pounce 'aim' (undergrowth's cat): it has stopped dead and its heading is already locked, so
      // the leap is knowable before it happens — draw it and stepping aside beats it. The lane ends
      // exactly where the cat will (speed × POUNCE_LEAP_T), and it vanishes the moment it leaps:
      // during 'leap' there is nothing left to warn about, the cat itself is the thing you see.
      if (e._pounceState === 'aim') {
        // v6.6.30 (owner: "their telegraph should be a bit more subtle"). Three overlapping bright
        // amber elements — a filled lane, a thick pulsing spine and a pulsing ring — were shouting
        // the same fact three times. What survives is the INFORMATION, at a fraction of the volume:
        //   - the lane stays, because it is the thing you step out of, but it is a hairline EDGE
        //     pair instead of a filled slab, and it does not pulse at all
        //   - the spine is gone entirely. It duplicated the lane and was the loudest thing on it.
        //   - the landing ring stays and remains the strongest mark, because it is the only element
        //     that says WHERE, and it is the one a player actually reads.
        // Deliberately not quieter than this: v6.6.30 also makes the leap connect for the first
        // time, so the telegraph is now carrying real counterplay rather than decorating a whiff.
        const urgency = POUNCE_AIM_T > 0 ? 1 - Math.max(0, e._pounceT || 0) / POUNCE_AIM_T : 1
        const pulse = 0.5 + 0.5 * Math.sin(animT * (6 + urgency * 16))
        const ux = e._pounceDirX || 0
        const uy = e._pounceDirY || 0
        const len = POUNCE_LEAP_DIST
        const ex = e.x + ux * len
        const ey = e.y + uy * len
        const hw = e.radius * 1.5
        const nx = -uy * hw
        const ny = ux * hw
        // lane EDGES only — two hairlines that fade out along the leap, so the near end (where the
        // cat is, and where you are looking) reads and the far end does not stripe the whole screen
        for (const s of [1, -1]) {
          teleG.moveTo(e.x + nx * s, e.y + ny * s)
          teleG.lineTo(ex + nx * s, ey + ny * s)
        }
        teleG.stroke({ width: 1, color: 0xffd24a, alpha: 0.1 + urgency * 0.14 })
        // landing ring: closes onto the impact point as it commits — a shrinking ring reads as
        // "something is arriving here", which is exactly what is about to happen
        teleG.circle(ex, ey, hw * (1.9 - urgency * 0.8))
          .stroke({ width: 1.5 + urgency * 1.5, color: 0xffe37a, alpha: Math.min(1, 0.22 + urgency * 0.36 + pulse * 0.08) })
      }

      // aerialStrike 'mark' (undergrowth's owl): the owl is overhead and untouchable, so the shadow
      // on the ground IS the attack — it's the only part of it the player can see or act on. The
      // blot swells (the owl is getting closer to the ground) while the amber ring tightens onto the
      // locked point. The point never re-aims, so walking off the mark always beats it.
      // v6.7.5: the third element is gone. A static amber ring at exactly the blot's own radius
      // drew the same circle the shadow was already filling — the pounce rework's "duplicated the
      // lane and was the loudest thing on it" defect, in a different shape. Shadow says WHERE (and
      // swelling, that the owl is dropping); the tightening ring says WHEN. Nothing else is needed,
      // and the ring itself comes down to the volume the toad's landing ring settled on.
      if (e._airState === 'mark') {
        const urgency = AERIAL_MARK_T > 0 ? 1 - Math.max(0, e._airT || 0) / AERIAL_MARK_T : 1
        const pulse = 0.5 + 0.5 * Math.sin(animT * (6 + urgency * 16))
        const tx = e._airTargX ?? e.x
        const ty = e._airTargY ?? e.y
        const r = e.radius * 1.4
        teleG.circle(tx, ty, r * (0.4 + urgency * 0.6)).fill({ color: 0x2a2438, alpha: 0.16 + urgency * 0.26 })
        teleG.circle(tx, ty, r * (2.4 - urgency * 1.4))
          .stroke({ width: 1.5 + urgency * 1.5, color: 0xffe37a, alpha: Math.min(1, 0.22 + urgency * 0.36 + pulse * 0.08) })
      }

      // lineCharge 'lock' (city's robot vacuum): deliberately the SAME band-and-chevrons lane the
      // traffic signature draws (redrawLanes) — both are city hazards that run you down in a
      // straight line, so they must read as one rule rather than two things to learn. Only the
      // anchoring differs: a traffic lane is centred on its band, this one starts at the vacuum and
      // runs LINE_CHARGE_LEN forward along the heading it just locked.
      // v6.7.5: quietened in lockstep with redrawLanes — see the recipe there. Same reduction, same
      // reasoning; the two MUST move together or "one rule, not two" stops being true. One thing
      // does differ: this band keeps its full rectangle stroke rather than dropping to two long
      // edges, because its far end is only LINE_CHARGE_LEN away and IS information — it says where
      // the charge stops, which is the difference between backing off and standing still.
      if (e._chargeState === 'lock') {
        const urgency = LINE_CHARGE_LOCK_T > 0 ? 1 - Math.max(0, e._chargeT || 0) / LINE_CHARGE_LOCK_T : 1
        const pulse = 0.5 + 0.5 * Math.sin(animT * (6 + urgency * 16))
        const cos = e._chargeDirX || 0
        const sin = e._chargeDirY || 0
        const hy = LINE_CHARGE_W / 2
        const flat = []
        for (const [lx, ly] of [[0, -hy], [LINE_CHARGE_LEN, -hy], [LINE_CHARGE_LEN, hy], [0, hy]]) {
          flat.push(e.x + lx * cos - ly * sin, e.y + lx * sin + ly * cos)
        }
        teleG.poly(flat).fill({ color: 0xffd24a, alpha: 0.03 + urgency * 0.05 })
        teleG.poly(flat).stroke({ width: 1.5, color: 0xffe37a, alpha: 0.22 + urgency * 0.34 + pulse * 0.06 })
        // chevrons pointing downstream — the redrawLanes "which way" cue, same geometry, same count
        const n = 4
        for (let i = 0; i < n; i++) {
          const d = ((i + 0.5) / n) * LINE_CHARGE_LEN
          const tipX = e.x + (d + hy * 0.5) * cos
          const tipY = e.y + (d + hy * 0.5) * sin
          const back = hy * 0.45
          teleG.beginPath()
          for (const s of [-1, 1]) {
            teleG.moveTo(tipX - cos * back - sin * s * hy * 0.55, tipY - sin * back + cos * s * hy * 0.55)
            teleG.lineTo(tipX, tipY)
          }
          teleG.stroke({ width: 2, color: 0xffe37a, alpha: 0.16 + urgency * 0.2 })
        }
      }

      // flashlightCone (undergrowth's exterminator elite): the one telegraph here that is NOT a
      // damage cue — the cone hurts nothing at all, it ENRAGES the swarm standing in it. So it
      // breaks the amber hazard language on purpose: no rim stroke, no fuse, nothing tightening,
      // nothing to dodge. It's a soft edgeless wash in the exact orange an enraged enemy tints to
      // (0xff8a5c, see syncEnemies) — the light is the colour of the thing it makes. Three nested
      // sectors give it a lamp's falloff instead of an edge, so it can never be misread as a floor
      // hazard you must stay out of: what walks OUT of it is the threat, not the standing in it.
      if (e._coneAngle !== undefined && e._coneAngle !== null) {
        const breathe = 0.5 + 0.5 * Math.sin(animT * 3)
        for (let k = 0; k < 3; k++) {
          const f = 1 - k * 0.3 // outermost sector is the true FLASHLIGHT_RANGE/ARC extent
          teleG.moveTo(e.x, e.y)
          teleG.arc(e.x, e.y, FLASHLIGHT_RANGE * f, e._coneAngle - FLASHLIGHT_ARC * f, e._coneAngle + FLASHLIGHT_ARC * f)
          teleG.lineTo(e.x, e.y)
          teleG.fill({ color: 0xff8a5c, alpha: 0.05 + k * 0.03 + breathe * 0.015 })
        }
      }

      // pullBeam 'beam' (beyond's UFO elite): the pull is a radius test, not a shaft — so the ring
      // is the real information (inside it you are being taken) and the tether is the confirmation
      // of which way. PULL_BEAM_FORCE sits under the player's own speed, so "walk out" is always
      // the answer and the ring is what tells you how far out is out. PULL_BEAM_T is a window
      // rather than a fuse, so instead of tightening, the beam irises open and snaps shut — it
      // should never pop into existence already at full strength.
      if (e._beamState === 'beam') {
        const left = Math.max(0, e._beamT || 0)
        const k = Math.max(0, Math.min(1, Math.min(PULL_BEAM_T - left, left) / 0.18))
        const flick = 0.85 + 0.15 * Math.sin(animT * 30) // the tractor hum
        teleG.circle(e.x, e.y, PULL_BEAM_RANGE)
          .stroke({ width: 2 + k, color: 0xffd24a, alpha: 0.32 * k * flick })
        teleG.circle(e.x, e.y, (PULL_BEAM_W / 2) * 1.15 * k).fill({ color: 0xffe37a, alpha: 0.22 * k * flick })
        const dx = e.x - p.x
        const dy = e.y - p.y
        const d = Math.hypot(dx, dy)
        if (d <= PULL_BEAM_RANGE && d > 1e-6) {
          const ux = dx / d
          const uy = dy / d
          const hw = (PULL_BEAM_W / 2) * k
          const nx = -uy * hw
          const ny = ux * hw
          const band = [p.x + nx, p.y + ny, e.x + nx, e.y + ny, e.x - nx, e.y - ny, p.x - nx, p.y - ny]
          teleG.poly(band).fill({ color: 0xffd24a, alpha: 0.12 * k * flick })
          teleG.poly(band).stroke({ width: 2, color: 0xffe37a, alpha: 0.45 * k * flick })
          // motes crawling UP the tether toward the saucer: the arrows point where you are being
          // taken, scrolling so the drag is legible even while you're winning against it
          const n = Math.max(2, Math.round(d / 60))
          for (let i = 0; i < n; i++) {
            const f = ((i + (animT * 0.9) % 1) / n)
            const cx = p.x + ux * d * f
            const cy = p.y + uy * d * f
            teleG.beginPath()
            for (const s of [-1, 1]) {
              teleG.moveTo(cx - ux * hw * 0.5 - uy * s * hw * 0.6, cy - uy * hw * 0.5 + ux * s * hw * 0.6)
              teleG.lineTo(cx + ux * hw * 0.5, cy + uy * hw * 0.5)
            }
            teleG.stroke({ width: 2, color: 0xffe37a, alpha: 0.5 * k * flick * (1 - f) })
          }
        }
      }
    }
  }

  // ---- 6. JET STRAFE (spec §3, jet row) --------------------------------------------------------
  // sim fires a one-off {type:'strafeLock', x, y, angle, len} the instant a jet's heading locks
  // (stepStrafe), then the jet HOLDS for STRAFE_TELEGRAPH_T before flying the pass at
  // STRAFE_RUN_SPEED_MUL. render remembers x/y/angle/len in its own small pool rather than
  // re-deriving `len` from live enemy fields (that math is sim's, spdMul/enrage and all).
  //
  // v5.10 — KILL LIST §8.1 AND §8.2, the literal bug in the user's report. This drew in
  // LIGHTNING.telegraph, i.e. the SAME electric blue as the bomb telegraph ("the dash telegraph for
  // planes is the same colour as everything"), using lineCharge's filled band-and-chevrons lane,
  // i.e. the same SHAPE as the city chapter's robot vacuum. Both are gone. The jet is now:
  //   colour — halogen white + tracer ORANGE, which appears nowhere else in any chapter;
  //   shape  — two HAIRLINE RAILS at the exact contact half-width and NO FILL AT ALL, plus a long
  //            narrow additive light ellipse riding between them. Zero brackets, zero chevrons,
  //            zero circles;
  //   motion — the only threat whose DAMAGE POINT TRANSLATES ACROSS THE SCREEN.
  // ARRIVAL CLOCK: the halogen pool races down the lane and arrives at the jet on the frame the run
  // begins. The damage itself is then a STITCH — paired orange dashes walking the lane at the run
  // speed, each popping a grit puff and a scorch tick.
  // v5.13: 10 -> 4. This was sized as PERFORMANCE headroom and turned out to be the chapter's worst
  // source of visual clutter. Every live lock draws two 820px hairline rails THROUGH the player's
  // area (a jet locks from STRAFE_STANDOFF and flies at you), so ten locks is twenty full-screen
  // lines meeting at one point — the starburst in the report. It is a BUDGET now, not headroom:
  // spawnStrafeLock's cursor wraps, so the four most recent locks are the four drawn, which are the
  // four about to matter. A jet whose lane is not drawn still flies and still hurts — but you can
  // see the jet, and four readable lanes beat ten unreadable ones.
  const MAX_STRAFE_LOCKS = 4
  const strafeLocks = []
  const strafePools = []
  for (let i = 0; i < MAX_STRAFE_LOCKS; i++) {
    strafeLocks.push({ live: false, x: 0, y: 0, angle: 0, len: 0, t: 0, stitch: 0 })
    const s = new Sprite(Texture.EMPTY); s.anchor.set(0.5); s.visible = false
    strafePoolLayer.addChild(s); strafePools.push(s)
  }
  let strafeLockCursor = 0
  function spawnStrafeLock(x, y, angle, len) {
    const sp = strafeLocks[strafeLockCursor]
    strafeLockCursor = (strafeLockCursor + 1) % MAX_STRAFE_LOCKS
    sp.live = true; sp.x = x; sp.y = y; sp.angle = angle; sp.len = len; sp.t = 0; sp.stitch = 0
  }
  // Advances every live lock's own clock AND draws it, straight into teleG — called right after
  // redrawTelegraphs (which already cleared+filled teleG this frame, see sync()), so this only ever
  // ADDS to it, never re-clears. dt=0 (paused/frozen behind a modal) holds it exactly where it was.
  function updateStrafeLocks(dt) {
    // (SKIES_FX.strafe.laneLen is the DERIVED length of a nominal pass; the drawer uses sp.len,
    // the length sim actually committed to for THIS jet — spdMul and enrage folded in. The config
    // value stays as the documented reference the lane was designed against.)
    const F = SKIES_FX.strafe
    const total = F.telegraphT + F.runT
    for (let i = 0; i < strafeLocks.length; i++) {
      const sp = strafeLocks[i]
      const poolS = strafePools[i]
      if (!sp.live) { poolS.visible = false; continue }
      if (dt > 0) sp.t += dt
      if (sp.t >= total) { sp.live = false; poolS.visible = false; continue }
      const cos = Math.cos(sp.angle), sin = Math.sin(sp.angle)
      const nx = -sin * F.halfW, ny = cos * F.halfW
      const telegraphing = sp.t < F.telegraphT
      const k = telegraphing ? sp.t / F.telegraphT : (sp.t - F.telegraphT) / F.runT
      const far = farFromPlayer(sp.x, sp.y)
      // the two HAIRLINE RAILS, at the true contact corridor (PLAYER.radius + the jet's own radius,
      // which is what stepContactDamage actually tests) — what you see is exactly what hits you
      if (!far) {
        for (const s of [-1, 1]) {
          if (jamDrop()) continue
          inkStroke(teleG, () => {
            teleG.moveTo(sp.x + nx * s, sp.y + ny * s)
            teleG.lineTo(sp.x + cos * sp.len + nx * s, sp.y + sin * sp.len + ny * s)
          }, F.railW, F.railColor, jamAlpha(F.railAlpha * (telegraphing ? 0.5 + 0.5 * k : 1)))
        }
      }
      if (telegraphing) {
        // ARRIVAL CLOCK: the halogen landing-light pool races from the far end of the lane back to
        // the jet, arriving on the frame the run begins. Additive — a light on wet asphalt.
        const d = sp.len * (1 - k)
        poolS.visible = true
        if (poolS.texture !== T.landingPool) poolS.texture = T.landingPool
        poolS.tint = F.poolColor
        poolS.alpha = lerp(F.poolAlphaMin, F.poolAlphaMax, k)
        poolS.rotation = sp.angle
        // v5.10.1: this used to hardcode the height as `F.halfW * 2` — unrelated to `F.poolAspect`
        // (the config value the spec's "long : narrow, 1 : 0.22" jet-row language actually names) and
        // fatter than the baked texture's own aspect (112/512 = 0.22): the pool rendered at ~1:0.37, a
        // dead config key contradicted by the number actually drawn. Deriving height from poolAspect
        // keeps the drawn shape, the baked texture and the documented value all in agreement.
        const poolLen = F.halfW * 5.4
        poolS.scale.set(poolLen / T.landingPool.width, (poolLen * F.poolAspect) / T.landingPool.height)
        poolS.position.set(sp.x + cos * d, sp.y + sin * d)
        // the jet's own nav lights, port red / starboard green — two 2px dots, the smallest
        // possible "that is an aircraft" cue and the only red allowed near a telegraph
        teleG.circle(sp.x + nx * 0.55, sp.y + ny * 0.55, 2).fill({ color: F.navRed, alpha: jamAlpha(0.85) })
        teleG.circle(sp.x - nx * 0.55, sp.y - ny * 0.55, 2).fill({ color: F.navGreen, alpha: jamAlpha(0.85) })
      } else {
        // THE STITCH: paired orange tracer dashes walking the lane at the run speed. This is the
        // damage, travelling — the one thing no other threat in the chapter does.
        // v5.13, two declutter fixes:
        //  1. It was ungated by `far`, unlike the rails above — so a jet strafing off at the edge of
        //     the world still laid a full-length orange dashed line across the view.
        //  2. It drew EVERY dash from the lane's origin to the head, so by the end of a 1.0s run it
        //     was an 820px streak that had stopped travelling and just sat there. Drawing only the
        //     dashes within `stitchTailPx` behind the head is what the design note above actually
        //     describes — damage in motion, with a tail, not a completed stripe.
        poolS.visible = false
        if (!far) {
          const head = sp.len * k
          const tail = Math.max(head % F.dashPitch, head - F.stitchTailPx)
          for (let d = tail; d < head; d += F.dashPitch) {
            const bx = sp.x + cos * d, by = sp.y + sin * d
            for (const s of [-1, 1]) {
              teleG.moveTo(bx + nx * s * 0.6 - cos * F.dashLen * 0.5, by + ny * s * 0.6 - sin * F.dashLen * 0.5)
              teleG.lineTo(bx + nx * s * 0.6 + cos * F.dashLen * 0.5, by + ny * s * 0.6 + sin * F.dashLen * 0.5)
            }
          }
          teleG.stroke({ width: F.dashW + 2.5, color: SKIES_INK.color, alpha: SKIES_INK.alpha })
          for (let d = tail; d < head; d += F.dashPitch) {
            const bx = sp.x + cos * d, by = sp.y + sin * d
            for (const s of [-1, 1]) {
              teleG.moveTo(bx + nx * s * 0.6 - cos * F.dashLen * 0.5, by + ny * s * 0.6 - sin * F.dashLen * 0.5)
              teleG.lineTo(bx + nx * s * 0.6 + cos * F.dashLen * 0.5, by + ny * s * 0.6 + sin * F.dashLen * 0.5)
            }
          }
          teleG.stroke({ width: F.dashW, color: F.tracer, alpha: 0.95, cap: 'butt' })
          teleG.circle(sp.x + cos * head, sp.y + sin * head, 3).fill({ color: F.tracerCore, alpha: 0.9 })
        }
        // each newly-walked dash pops a grit puff and a scorch tick where it struck
        if (dt > 0 && !far) {
          sp.stitch += (sp.len / F.runT) * dt
          while (sp.stitch >= F.dashPitch) {
            sp.stitch -= F.dashPitch
            const d = sp.len * k
            const px2 = sp.x + cos * d, py2 = sp.y + sin * d
            spawnParticle(T.gritPuff, px2, py2, (Math.random() - 0.5) * 60, (Math.random() - 0.5) * 60,
              0.3, F.gritPx / 32, F.gritColor, 0.4, 3)
            spawnParticle(T.scorchTick.tex, px2, py2, 0, 0, 0.55, F.scorchPx / 6, 0x1a1712, 0, 0)
          }
        }
      }
    }
  }
  function clearStrafeLocks() {
    for (const sp of strafeLocks) sp.live = false
    for (const s of strafePools) s.visible = false
  }

  // Debris Toss lobs (run.lobs): the sim only tracks t counting UP to flight — THE ARC IS RENDER'S.
  // Ground position lerps (fromX,fromY) -> (tx,ty); the chunk lifts off it by a parabola peaking at
  // the halfway point (4k(1-k), scaled to the throw's length), and a shadow stays on the ground
  // beneath it. The shadow is what sells the height — without it a lob just slides.
  const lobPool = []
  function acquireLob() {
    const root = new Container()
    const shadow = spriteOf(T.playerShadow)
    shadow.tint = 0x000000
    const chunk = spriteOf(T.rockChunk)
    // Two payloads share this rig: the kaiju's masonry and the Trawl's thrown net. One sprite each
    // and a visibility swap, rather than two pools — the flight, the parabola and the shadow are
    // identical and are the whole reason run.lobs was reused for Net Toss in the first place.
    const net = spriteOf(T.tossNet)
    root.addChild(shadow, chunk, net)
    lobLayer.addChild(root)
    return { root, shadow, chunk, net }
  }
  let lobCount = 0
  function syncLobs(run) {
    const list = run.lobs || []
    while (lobPool.length < list.length) lobPool.push(acquireLob())
    for (let i = 0; i < list.length; i++) {
      const lb = list[i]
      const lv = lobPool[i]
      lv.root.visible = true
      const k = Math.max(0, Math.min(1, lb.t / Math.max(0.001, lb.flight)))
      const gx = lerp(lb.fromX, lb.tx, k)
      const gy = lerp(lb.fromY, lb.ty, k)
      const throwLen = Math.hypot(lb.tx - lb.fromX, lb.ty - lb.fromY)
      const hop = Math.min(160, 40 + throwLen * 0.3) * 4 * k * (1 - k) // parabola, peaks at k=0.5
      lv.root.position.set(gx, gy)
      lv.shadow.position.set(0, 0)
      lv.shadow.alpha = 0.1 + 0.2 * (1 - hop / 160)
      // The shadow tracks the THROWN OBJECT, not the landing radius — for a net those are different
      // numbers (a 13px bundle that opens to 142px), and using r here painted a shadow the size of
      // the whole detonation under a ball in mid-air.
      const shadowR = lb.snare > 0 ? 14 : lb.r
      lv.shadow.scale.set((shadowR / PLAYER.radius) * 0.5 * (1 - 0.3 * (hop / 160)))
      // Which payload. A net TUMBLES more slowly than a rock and is scaled off its own bundle size
      // rather than off `r` — r is where it will OPEN, not how big the thrown ball is, and scaling
      // a 13px bundle to a 142px radius fills the screen with one sprite.
      const isNet = lb.snare > 0
      const body = isNet ? lv.net : lv.chunk
      lv.chunk.visible = !isNet
      lv.net.visible = isNet
      body.position.set(0, -hop)
      body.rotation = isNet ? k * 3.4 + i : k * 9 + i
      body.scale.set(isNet ? 1 : (lb.r || 20) / 12)
    }
    for (let i = list.length; i < lobCount; i++) lobPool[i].root.visible = false
    lobCount = list.length
  }

  // Whip swings (one-off {type:'whip'} events, render-local like rings/arcs). An ANCHORED melee
  // sweep — NOT a projectile: ONE shape pinned to the player, deep mint over the murky floor,
  // raking across the swept wedge over its short life with a bright spark at the tip. Segment-chain
  // approaches read as "concatenated blobs" (twice user-rejected) — one shape IS the arc, don't
  // rebuild it from parts.
  //
  // v6.6.13: the swoosh is DRAWN, not stamped from Kenney's slash_02. Measured, that PNG's ink
  // spans ~177 degrees about its own centre, so the swing covered two to three times the wedge the
  // sim actually tests (80 degrees at lv1): enemies stood well inside the swoosh taking nothing,
  // and a Wide Arc pick — a real +34% enemies hit per swing, measured — changed nothing anyone
  // could SEE. That is the playtest report ("not clear or doesn't do anything") in full. Same
  // defect and same fix as the Claw Rake's gash (see bakeClawGash): draw it, and budget the DRAWN
  // extent onto the TESTED extent. Shared with the kaiju tail swipe, which has the same mod.
  //
  // But that fix was ANGULAR ONLY, and the RADIAL half of the same lie outlived it.
  // fireFlagella (sim.js) damages every enemy whose centre is in the FILLED sector — r from the
  // player out to `range`. The swoosh was a crescent hanging inward only SWOOSH_W (40 of a 100px
  // bake) from the rim, so at lv5 it drew r in [105,175] and the inner 60% of the reach, which in
  // a survivors-like is where the swarm actually IS, took damage with nothing drawn on it. Probed
  // with scripts/scenes/flagella-hitbox.js: 7 enemies hit, 1 under the swoosh. So the band now
  // opens all the way to the player (a FAN leaving the body, not a crescent on the rim) and the
  // fade moved from the shape's outline into its alpha: solid at the leading edge, out to nothing
  // at the trailing one, so the sweep drags a radar-style trail instead of flashing whole. That
  // fade also replaces the lagging ghost sprite, which was the old motion smear.
  const MAX_WHIPS = 8
  const WHIP_CORE = 0x2fd6a0         // vivid spring-green swoosh — must sit clearly ABOVE the murky floor
  const WHIP_EDGE = 0x9fffd9         // lighter mint rim: what separates the swoosh from the floor
  const WHIP_TIP = 0xcafff0          // the crack: the one light accent, tip only
  // Baked reference geometry. The band hangs INWARD from SWOOSH_R, so the drawn outer edge lands
  // on `range` and can never overshoot the sector.
  const SWOOSH_R = 100
  const SWOOSH_SPAN = 1.05           // rad the baked shape subtends. Kept well clear of pi: the
                                     // squash below inverts a tan, which is useless near the pole
                                     // (this is why slash_02's ~3.1 rad of ink could not be squashed
                                     // into honesty — there was no faithful q to solve for).
  const SWOOSH_BELLY = 0.5           // <1 puts the belly at the TRAILING root, so the shape opens out
                                     // of the player rather than hanging off the rim
  const SWOOSH_TAIL = 0              // alpha left at the trailing edge — 0 is the full radar drag
  const WHIP_SWEEP = 0.45            // fraction of the wedge spent on TRAVEL; the shape's own width
                                     // is the rest, and the two always sum to exactly `arc`
  // Widest the SHAPE is ever drawn, in rad. Squashing (q<1) keeps the band hugging the reach
  // circle; STRETCHING it (q>1) throws the ends off that circle and the swoosh degenerates into a
  // vertical lens — caught on glass at the kaiju tail's 169deg, where it stopped reading as a swing
  // at all. So the shape never exceeds its own baked span, and a wider wedge than that spends the
  // surplus on TRAVEL instead: the tail sweeps further, cyclone goes all the way round, and the
  // drawn extent still lands on `arc` exactly.
  const WHIP_HALF_MAX = SWOOSH_SPAN / 2
  const whips = []
  for (let i = 0; i < MAX_WHIPS; i++) whips.push({ live: false, x: 0, y: 0, angle: 0, range: 0, arc: 0, travel: 0, tipA: 0, tipR: 0, t: 0, dur: 0.18, root: null, lead: null, tip: null })
  let whipCursor = 0
  // One fan, baked once and shared by every swing. Drawn with the arc's CENTRE at the local origin
  // and bulging +x, so bake()'s anchor puts that centre on the player, rotation is just the
  // bearing, and scale is just the reach — the gash's convention exactly.
  let swooshTex = null
  function bakeSwoosh() {
    const g = new Graphics()
    const N = 48
    const outer = [], inner = []
    for (let i = 0; i <= N; i++) {
      const t = i / N                                  // 0 = trailing tail, 1 = leading crack
      const a = -SWOOSH_SPAN / 2 + SWOOSH_SPAN * t
      const ca = Math.cos(a), sa = Math.sin(a)
      // Belly profile: 0 at both ends, fat toward the leading end. Clamp the sin's argument — t can
      // land a hair outside [0,1] in float, and pow(negative, fraction) is NaN, and ONE NaN vertex
      // blanks the whole baked texture (the v5.4 bulge() bug, same shape as bakeClawGash's clamp).
      // The band opens the whole way to SWOOSH_R — i.e. to the player — so the drawn shape covers
      // the radial extent the sim tests and not just its rim.
      const u = Math.min(1, Math.max(0, Math.pow(t, SWOOSH_BELLY)))
      const w = SWOOSH_R * Math.pow(Math.max(0, Math.sin(Math.PI * u)), 0.7)
      outer.push(SWOOSH_R * ca, SWOOSH_R * sa)
      inner.push((SWOOSH_R - w) * ca, (SWOOSH_R - w) * sa)
    }
    const back = []
    for (let i = inner.length - 2; i >= 0; i -= 2) back.push(inner[i], inner[i + 1])
    // The fade is ANGULAR: solid at the leading edge, washing out to SWOOSH_TAIL at the trailing
    // one, so the fan drags a radar-style trail instead of flashing whole. The shape hugs radius
    // ~SWOOSH_R, so y = r*sin(a) is monotonic in the local angle a — a plain linear gradient in y
    // IS the angular one. 'global' textureSpace means these are the Graphics' own local coords
    // (origin = the player); the runtime rotation carries the ramp along and the y-squash only
    // compresses it, so no per-swing work is needed and this still bakes exactly once.
    const yEnd = SWOOSH_R * Math.sin(SWOOSH_SPAN / 2)
    const fade = (hex, a) => `rgba(${(hex >> 16) & 255},${(hex >> 8) & 255},${hex & 255},${a})`
    const ramp = (c) => new FillGradient({
      type: 'linear', textureSpace: 'global',
      start: { x: 0, y: -yEnd }, end: { x: 0, y: yEnd },
      colorStops: [
        { offset: 0, color: fade(c, SWOOSH_TAIL) },
        { offset: 0.6, color: fade(c, SWOOSH_TAIL + (1 - SWOOSH_TAIL) * 0.45) },
        { offset: 1, color: c },
      ],
    })
    g.poly([...outer, ...back]).fill(ramp(WHIP_CORE)).stroke({ width: 2, fill: ramp(WHIP_EDGE), join: 'round' })
    return bake(g)
  }
  function makeSwoosh() {
    if (!swooshTex) swooshTex = bakeSwoosh()
    const s = new Sprite(swooshTex.tex)
    s.anchor.set(swooshTex.ax, swooshTex.ay) // the arc's centre → sits on the player
    return s
  }
  function spawnWhip(x, y, angle, range, arc) {
    const wp = whips[whipCursor]
    whipCursor = (whipCursor + 1) % MAX_WHIPS
    if (!wp.root) {
      wp.root = new Container()
      wp.lead = makeSwoosh()
      wp.tip = new Sprite(T.fx.spark_04)
      wp.tip.anchor.set(0.5)
      wp.tip.tint = WHIP_TIP
      wp.root.addChild(wp.lead, wp.tip)
      whipLayer.addChild(wp.root)
    }
    wp.live = true
    wp.x = x; wp.y = y; wp.angle = angle; wp.range = range; wp.arc = arc || 1
    wp.t = 0
    wp.root.visible = true
    // Budget the drawn wedge onto the tested one: half-span + half the travel == arc/2, exactly.
    // Scaling y by q maps a local angle a to atan(q * tan a), so the drawn span follows q — the
    // rake's solve, inverted rather than linearised (tan is superlinear; the linearisation runs
    // several percent wide at the tips, and wide is the direction that lies to the player).
    const half = Math.min(wp.arc * (1 - WHIP_SWEEP) / 2, WHIP_HALF_MAX)
    wp.travel = wp.arc - half * 2
    // half <= SWOOSH_SPAN/2 by the clamp above, so q <= 1 always: the squash only ever pulls the
    // shape INSIDE the reach circle, never past the sector the sim tests.
    const q = Math.tan(half) / Math.tan(SWOOSH_SPAN / 2)
    const cs = Math.cos(SWOOSH_SPAN / 2), sn = Math.sin(SWOOSH_SPAN / 2)
    const sc = wp.range / SWOOSH_R
    wp.lead.scale.set(sc, sc * q)
    wp.tipA = half                         // == atan(q * tan(SPAN/2)) by construction of q
    wp.tipR = sc * SWOOSH_R * Math.hypot(cs, q * sn) // the shape's end, which the squash pulls in
  }
  function updateWhips(dt) {
    for (const wp of whips) {
      if (!wp.live) continue
      if (dt > 0) wp.t += dt
      if (wp.t >= wp.dur) { wp.live = false; wp.root.visible = false; continue }
      const k = wp.t / wp.dur
      wp.root.position.set(wp.x, wp.y)
      const flash = Math.sin(Math.PI * k) // ramp in then out
      // the fan rakes from one rim of the wedge to the other (a full turn at arc = 2pi / cyclone)
      const bearing = (kk) => wp.angle - wp.travel / 2 + wp.travel * kk
      wp.lead.rotation = bearing(k)
      wp.lead.alpha = flash
      const tipAngle = bearing(k) + wp.tipA
      wp.tip.position.set(wp.tipR * Math.cos(tipAngle), wp.tipR * Math.sin(tipAngle))
      wp.tip.rotation = k * 6 // a little spin on the spark
      wp.tip.alpha = Math.pow(flash, 1.6) * 0.95 // sharp pop, concentrated at full extension
      wp.tip.scale.set(fxScale(T.fx.spark_04, wp.range * 0.3))
    }
  }
  function clearWhips() {
    for (const wp of whips) { wp.live = false; if (wp.root) wp.root.visible = false }
  }

  // Claw Rake slashes (one-off {type:'clawRake'} events) — the whip's anchored-melee idiom, on a
  // deliberately different shape. The whip is ONE FAT solid swoosh curling across the wedge
  // (bakeSwoosh above), and borrowing it made the rake read as a second whip. A rake is THREE THIN PARALLEL
  // GASHES landing together, side by side at one reach, splayed across the wedge. They flash as one
  // and drift outward as they fade — the arc reads as raked, not swung. Each tine is one drawn gash
  // (see bakeClawGash), never a chain of segments — the same "one shape IS the arc" rule as the whip.
  const MAX_CLAWS = 8
  // Each tine's reach as a fraction of the rake's range. THE GASHES MUST NOT TOUCH — the gap
  // between them is the whole claw read; the moment they overlap they fuse into one fat crescent
  // and it's a swoosh again. Two things have to hold together:
  //   - the spacing here must exceed a gash's thickness (GASH_W + rim). At range 100 these sit at
  //     72/86/100px: ~14px apart against a ~9px gash, so ~5px of floor shows between them.
  //   - the FAN must stay SMALL. A gash spans GASH_SPAN (0.92 rad) along its length, so fanning by
  //     less than that (the old +-0.24) doesn't separate them at all — it just slides overlapping
  //     arcs along each other. Separation comes from the radius; the fan is only a slight splay.
  const CLAW_TINE_R = [0.72, 0.86, 1.0]
  // The fan and the sweep both spend the SAME angular budget as the gash itself — everything drawn
  // has to fit inside arc/2 (see the q solve in updateClaws), so widening either one narrows the
  // gashes. Keep them small: the drawn rake must never claim ground the sector doesn't test.
  const CLAW_TINE_FAN = [-0.08, 0.0, 0.075] // rad (x arc): a paw's claws splay a little, not a lot
  const CLAW_FAN_MAX = 0.08                 // == max |CLAW_TINE_FAN|, kept as a const for the solve
  const CLAW_SWEEP = 0.15                   // fraction of arc the rake travels across during its life
  const CLAW_TINE_A = [0.82, 1.0, 0.78]     // outer gashes lighter — the middle claw bites deepest
  // A gash is DRAWN, not stamped from the Kenney slash glyph. That PNG's alpha falls off soft and
  // round, so it can only ever read as a fat smear — there is no needle tip anywhere in it, at any
  // scale or squash. A claw mark is the opposite shape: double-tapered, sharp at BOTH ends, fat at
  // the belly, with a hard rim. Drawing it also deletes three workarounds the glyph needed — the
  // hand-measured arc center (bake() returns the anchor), the 82°->50° squash (GASH_SPAN just IS
  // the wedge), and the stacked rim+core copies (the stroke is the rim).
  const GASH_R = 100            // baked arc radius; updateClaws scales by rad / GASH_R
  const GASH_SPAN = 0.92        // rad the gash subtends
  const GASH_W = 6.5            // width at the belly — THIN. This plus the rim must stay under the
                                // CLAW_TINE_R spacing above, or the three gashes merge into a smear.
  const GASH_BELLY = 0.85       // <1 pushes the belly toward the tip — a claw drags deepest past the bite
  const GASH_FILL = 0xf0834a    // warm rust, straight off the reference
  const GASH_RIM = 0x5c1c0a     // dark rim: what actually separates the gashes on the loam floor
  const CLAW_DRIFT = 0.10       // fraction of range the tines rake outward as they fade
  const claws = []
  for (let i = 0; i < MAX_CLAWS; i++) claws.push({ live: false, x: 0, y: 0, angle: 0, range: 0, arc: 0, t: 0, dur: 0.16, root: null, tines: null })
  let clawCursor = 0
  // One curved, double-tapered gash, baked once and shared by every tine. Drawn with the arc's
  // CENTER at the local origin, so bake()'s returned anchor puts that center on the player: then
  // rotation is just the bearing and scale is just the reach.
  let gashTex = null
  function bakeClawGash() {
    const g = new Graphics()
    const N = 44
    const left = [], right = []
    for (let i = 0; i <= N; i++) {
      const t = i / N
      const a = -GASH_SPAN / 2 + GASH_SPAN * t
      const ca = Math.cos(a), sa = Math.sin(a)
      // Belly profile: 0 at both tips, fat in the middle. Clamp the sin's argument — t can land a
      // hair outside [0,1] in float, and pow(negative, fraction) is NaN. One NaN vertex blanks the
      // whole baked texture (the v5.4 bulge() bug, same shape).
      const u = Math.min(1, Math.max(0, Math.pow(t, GASH_BELLY)))
      const w = GASH_W * Math.pow(Math.max(0, Math.sin(Math.PI * u)), 0.8) * 0.5
      left.push(GASH_R * ca + ca * w, GASH_R * sa + sa * w)   // offset along the radial: a gash
      right.push(GASH_R * ca - ca * w, GASH_R * sa - sa * w)  // thickens across its own curve
    }
    // walk out one edge and back the other — right reversed, in x,y pairs
    const back = []
    for (let i = right.length - 2; i >= 0; i -= 2) back.push(right[i], right[i + 1])
    g.poly([...left, ...back]).fill(GASH_FILL).stroke({ width: 1.5, color: GASH_RIM, join: 'round' })
    return bake(g)
  }
  function makeTine() {
    if (!gashTex) gashTex = bakeClawGash()
    const s = new Sprite(gashTex.tex)
    s.anchor.set(gashTex.ax, gashTex.ay) // the arc's center → sits on the player
    return s
  }
  function spawnClaw(x, y, angle, range, arc) {
    const cp = claws[clawCursor]
    clawCursor = (clawCursor + 1) % MAX_CLAWS
    if (!cp.root) {
      cp.root = new Container()
      cp.tines = CLAW_TINE_R.map(() => makeTine())
      cp.root.addChild(...cp.tines)
      whipLayer.addChild(cp.root)
    }
    cp.live = true
    cp.x = x; cp.y = y; cp.angle = angle; cp.range = range; cp.arc = arc || 1
    cp.t = 0
    cp.root.visible = true
  }
  function updateClaws(dt) {
    for (const cp of claws) {
      if (!cp.live) continue
      if (dt > 0) cp.t += dt
      if (cp.t >= cp.dur) { cp.live = false; cp.root.visible = false; continue }
      const k = cp.t / cp.dur
      cp.root.position.set(cp.x, cp.y)
      const flash = Math.sin(Math.PI * k) // ramp in then out, exactly like the whip's
      // The whole rake sweeps only a LITTLE across the wedge (the fan already covers it) and rakes
      // outward as it fades — a swing would re-read as the whip.
      const sweep = cp.angle + cp.arc * (k - 0.5) * CLAW_SWEEP
      // ...and it lands ON `range`, never past it: rake outward INTO the hitbox edge, don't
      // overshoot it (a plain 1 + DRIFT*k put the outer gash 10% beyond what the sector tests).
      const reach = 1 - CLAW_DRIFT + CLAW_DRIFT * k
      // The gash is baked at a FIXED GASH_SPAN, but the wedge the sim tests is cp.arc — which
      // changes with level and with wideRake. Squash across the bearing so the DRAWN wedge is the
      // TESTED wedge: scaling y by q maps a local angle a to atan(q*tan a), so the span follows q.
      // Budget the outermost drawn edge — half a gash + the fan + half the sweep travel — onto
      // exactly arc/2 and invert that exactly (the tempting q ~= budget/(SPAN/2) linearisation is
      // 4% wide at the tips, because tan is superlinear). Without this the rake drew ~50% wider
      // than its own hitbox at lv1, and enemies sat visually inside the claws taking nothing.
      // v6.6.28: budget is CLAMPED just under pi/2. The solve inverts a tangent, so at
      // budget >= pi/2 — reached at cast arc ~4.553 rad — tan flips sign, q goes negative and the
      // whole tine fan draws INSIDE OUT. That was always latent, but v6.6.28's +30% base arc lowers
      // the wideRake investment needed to reach it from bonus > 3.79 to bonus > 2.67, i.e. from five
      // epic picks to five mixed rare/epic ones — inside what a real build rolls. Past this point
      // the drawn wedge stops tracking the hitbox (it saturates instead of inverting), which is the
      // lesser of the two wrongs and the only one that still looks like a claw.
      const budget = Math.min(cp.arc * (0.5 - CLAW_FAN_MAX - CLAW_SWEEP * 0.5), Math.PI * 0.5 - 0.02)
      const q = Math.tan(budget) / Math.tan(GASH_SPAN * 0.5)
      for (let i = 0; i < cp.tines.length; i++) {
        const tine = cp.tines[i]
        const rad = cp.range * CLAW_TINE_R[i] * reach
        // Anchored at its arc's center and bulging +x from it, so rotation IS the bearing and the
        // x-scale IS the reach. Thickness is radial, so near the belly it rides sx and the squash
        // barely blunts the tips.
        const sx = rad / GASH_R
        tine.scale.set(sx, sx * q)
        tine.rotation = sweep + CLAW_TINE_FAN[i] * cp.arc
        tine.alpha = Math.pow(flash, 1.3) * 0.95 * CLAW_TINE_A[i]
      }
    }
  }
  function clearClaws() {
    for (const cp of claws) { cp.live = false; if (cp.root) cp.root.visible = false }
  }

  // Roar wavefronts (one-off {type:'roar'} events) — v5.6.16: the sim emitted this event from day
  // one and render NEVER had a case for it, so the skies starter was literally invisible ("I don't
  // see or understand what my weapon does"). A roar is pressure, not a blade: three thin arc BANDS
  // radiating through the wedge from the player, expanding INTO the hitbox edge (the last band
  // dies exactly at `range` — the drawn extent is the tested extent, per the claw rule) and fading
  // as they travel. Warm dark amber on the skies' pale cool concrete (warm-vs-cool + darker value
  // is what reads there — pale-on-pale is the chapter's documented camouflage trap).
  // v7.27: DRAWN AS A REAL ARC, not a baked sprite stretched to fake one.
  //
  // It used to be the claw's fixed-span-bake + tan-exact y-squash: one band baked spanning
  // ROAR_SPAN (1.0 rad), scaled by q = tan(arc/2)/tan(ROAR_SPAN/2) in Y to "become" the cast's arc.
  // That is a LINEARISATION, and it only holds near the baked span — its own comment admitted it was
  // "wide at the tips". wideRoar multiplies `arc` at runtime, so a real build walks straight out of
  // the range where it holds: L5's 1.30 rad already needs q = 1.7, +150% width needs 2.6, +200%
  // needs 6.6. At those factors the sprite is not a wider arc, it is the SAME arc smeared into a
  // tall ellipse — which is why the owner reported "we just see orange lines on the screen" and
  // "it doesn't look like a roar sound pressure wave anymore when >150% roar width".
  //
  // Graphics arcs have no such limit: they are drawn at the cast's true arc, so the picture is
  // correct at 0.9 rad and at 2.6 rad alike, and the q hack, the bake and its two constants are all
  // gone with it. Cost is trivial — one cast is drawn at a time and the ripple field is at most
  // (screen radius / 55) rings, rebuilt on a Graphics that is cleared every frame anyway (same idiom
  // as hazardG/laneG/breathG).
  const MAX_ROARS = 6
  const ROAR_COLOR = 0xf0a63f
  const roarG = new Graphics()
  whipLayer.addChild(roarG)
  const roars = []
  for (let i = 0; i < MAX_ROARS; i++) roars.push({ live: false, x: 0, y: 0, angle: 0, range: 0, arc: 0, t: 0, dur: 0.34 })
  let roarCursor = 0
  function spawnRoar(x, y, angle, range, arc) {
    const rp = roars[roarCursor]
    roarCursor = (roarCursor + 1) % MAX_ROARS
    rp.live = true
    rp.x = x; rp.y = y; rp.angle = angle; rp.range = range; rp.arc = arc || 1
    rp.t = 0
  }
  // ---- the roar's ripple field --------------------------------------------------------------
  // The roar draws as CONCENTRIC RIPPLES: 20px rings on a 55px pitch, born at the mouth, travelling
  // outward at a fixed speed, filling the cast's cone out to its range. Two properties matter and
  // both are load-bearing, because the look this replaced went solid orange on a scaled build and
  // the owner reported the chapter unplayable:
  //
  //  1. NOTHING DRAWN SCALES WITH A STAT. Ring thickness and pitch are absolute px, so a longer roar
  //     is MORE rings, never fatter ones. The old band was `radius * 0.14` thick, which at a +229%
  //     range build is a 185px slab, and no alpha makes a 185px slab read as a wave.
  //  2. THE RIPPLES ARE CONTINUOUS, not one train per cast. Ink on screen is therefore a function of
  //     the ripple pitch (fixed) and not of FIRE RATE. Measured, this is not optional: at +320% rate
  //     the roar re-fires every 0.10s while its wave needs 0.34s to cross, so a per-cast train never
  //     got past 30% of the way out before being replaced (probe read k=0.25, front=266px, every
  //     single frame) — the effect sat permanently ON the player instead of passing over the field.
  //
  // Rings are STROKED, never filled as annuli. The `arc(ro) + arc(ri, reversed) + fill()` idiom used
  // elsewhere in this file does not cut its hole at these ring counts: it composites as nested
  // filled SECTORS, whose radial profile is a staircase stepping down once per ring with no gap ever
  // reaching the floor (measured 157 units of ink at the centre decaying to 9 at the rim over 6
  // steps — i.e. a solid orange disc). A stroke of width ROAR_RING_PX is a 20px ring by
  // construction. If you ever reintroduce a filled band here, shoot it at a +200% range build first.
  const ROAR_RING_PX = 20       // ring thickness, absolute px at every radius
  const ROAR_GAP_PX = 35        // gap between rings — pitch is RING + GAP = 55px
  const ROAR_RIPPLE_SPEED = 620 // px/s the ripple train travels outward — a look, not a stat
  const ROAR_RIPPLE_ALPHA = 0.4 // peak per-ring alpha, mid-flight (owner: 20% more transparent)
  let ripplePhase = 0           // shared outward travel, so a new cast does not restart the ripples
  function updateRoars(dt) {
    roarG.clear()
    ripplePhase += dt * ROAR_RIPPLE_SPEED
    // One cast drawn at a time. The ripple field is continuous and identical for every live cast, so
    // a second one contributes nothing but opacity — its rings land exactly on the first one's.
    const liveSorted = roars.filter((r) => r.live).sort((a, b) => a.t - b.t) // youngest first
    for (let i = 1; i < liveSorted.length; i++) liveSorted[i].live = false
    for (const rp of roars) {
      if (!rp.live) continue
      if (dt > 0) rp.t += dt
      if (rp.t >= rp.dur) { rp.live = false; continue }
      const k = rp.t / rp.dur
      // The wavefront is born at the MOUTH — a fixed distance — and expands to `range`. It used to
      // be born at 30% OF RANGE, so the dead zone in front of the kaiju SCALED with the range stat:
      // 82px out at L5's 275, ~180px out with range mods past 200%, which meant the early sweep (the
      // part that reads as a roar leaving the head) never existed and Long Roar made its own effect
      // worse the more you took. The arc CENTRE stays on the player because that is where inSector
      // tests from, so the wedge on screen is still the honest hitbox, and a band at the mouth's
      // radius passes through the mouth anyway. Body radius outside skies (the Blank has no kaiju).
      const roarStart = playerForm === 'kaiju' ? SKIES_KAIJU.muzzle * SKIES_KAIJU.bodyScale : PLAYER.radius
      const a0 = rp.angle - rp.arc / 2
      const a1 = rp.angle + rp.arc / 2

      // Rings fade out over the last quarter of the cast's life, so when the player stops firing the
      // field dies away instead of popping. Under sustained fire k never gets near 0.75.
      const env = k > 0.75 ? (1 - k) / 0.25 : 1
      // viewRadius from the renderer's OWN screen — main.js derives run.viewRadius from exactly this,
      // and updateRoars takes only dt, so reading it here avoids threading `run` through. Past the
      // screen edge there is no picture, only cost.
      const viewR = Math.hypot(app.screen.width, app.screen.height) / 2
      const period = ROAR_RING_PX + ROAR_GAP_PX
      const edge = Math.min(rp.range, viewR + 40)
      const span = Math.max(period, edge - roarStart)
      for (let r = roarStart + ripplePhase % period; r <= edge; r += period) {
        // Fade in off the mouth and out at the far edge — a ring must not blink into existence.
        const f = (r - roarStart) / span
        const alpha = ROAR_RIPPLE_ALPHA * Math.sin(Math.PI * Math.min(1, f * 1.2)) * env
        if (alpha <= 0.004) continue
        roarG.arc(rp.x, rp.y, r, a0, a1).stroke({ width: ROAR_RING_PX, color: ROAR_COLOR, alpha })
      }
    }
  }
  function clearRoars() {
    roarG.clear()
    for (const rp of roars) rp.live = false
  }

  // particles: fixed-size freelist of sprites + plain data
  const particles = []
  for (let i = 0; i < MAX_PARTICLES; i++) {
    particles.push({
      s: null, live: false, x: 0, y: 0, vx: 0, vy: 0, life: 0, maxLife: 0, scale: 1, grow: 0, drag: 0, grav: 0,
      spiral: false, cx: 0, cy: 0, ang: 0, angVel: 0, rad: 0, radVel: 0,
    })
  }
  let particleCursor = 0

  function spawnParticle(tex, x, y, vx, vy, life, scale, tint, grow = 0, drag = 0, grav = 0) {
    const p = particles[particleCursor]
    particleCursor = (particleCursor + 1) % MAX_PARTICLES
    if (!p.s) {
      p.s = new Sprite(tex)
      p.s.anchor.set(0.5)
      particleLayer.addChild(p.s)
    }
    if (p.s.texture !== tex) p.s.texture = tex
    p.live = true
    p.spiral = false
    p.x = x
    p.y = y
    p.vx = vx
    p.vy = vy
    p.life = life
    p.maxLife = life
    p.scale = scale
    p.grow = grow
    p.drag = drag
    p.grav = grav
    p.s.visible = true
    p.s.tint = tint
    p.s.rotation = Math.random() * Math.PI * 2
  }

  // Black-hole suction particles: orbit (cx,cy) at shrinking radius instead of flying in
  // a straight line — same freelist/slot as spawnParticle, just a different motion model.
  function spawnSpiralParticle(tex, cx, cy, ang, rad, angVel, life, scale, tint, grow = 0) {
    const p = particles[particleCursor]
    particleCursor = (particleCursor + 1) % MAX_PARTICLES
    if (!p.s) {
      p.s = new Sprite(tex)
      p.s.anchor.set(0.5)
      particleLayer.addChild(p.s)
    }
    if (p.s.texture !== tex) p.s.texture = tex
    p.live = true
    p.spiral = true
    p.cx = cx
    p.cy = cy
    p.ang = ang
    p.angVel = angVel
    p.rad = rad
    p.radVel = -rad / life
    p.life = life
    p.maxLife = life
    p.scale = scale
    p.grow = grow
    p.s.visible = true
    p.s.tint = tint
    p.s.rotation = ang
  }

  function updateParticles(dt) {
    if (dt === 0) return
    for (const p of particles) {
      if (!p.live) continue
      p.life -= dt
      if (p.life <= 0) { p.live = false; p.s.visible = false; continue }
      if (p.spiral) {
        p.ang += p.angVel * dt
        p.rad = Math.max(0, p.rad + p.radVel * dt)
        p.x = p.cx + Math.cos(p.ang) * p.rad
        p.y = p.cy + Math.sin(p.ang) * p.rad
        p.scale += p.grow * dt
        p.s.position.set(p.x, p.y)
        p.s.scale.set(Math.max(p.scale, 0.001))
        p.s.alpha = p.life / p.maxLife
        continue
      }
      const k = p.drag > 0 ? Math.max(0, 1 - p.drag * dt) : 1
      p.vx *= k
      p.vy = p.vy * k + p.grav * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.scale += p.grow * dt
      p.s.position.set(p.x, p.y)
      p.s.scale.set(p.scale)
      p.s.alpha = p.life / p.maxLife
    }
  }

  function clearParticles() {
    for (const p of particles) {
      p.live = false
      if (p.s) p.s.visible = false
    }
  }

  // expanding rings: small ring-buffer of one-off animated effects (mine explosions).
  // Not run-state — purely a render-local visual, same freelist idea as particles.
  const MAX_RINGS = 12
  const rings = []
  for (let i = 0; i < MAX_RINGS; i++) rings.push({ s: null, live: false, x: 0, y: 0, t: 0, dur: 0.35, maxR: 90 })
  let ringCursor = 0

  // look: baked {tex,ax,ay} to draw (defaults to the warm explosion ring); tint: applied
  // on top (defaults to white = baked colors as-is). Both optional/backward-compatible —
  // existing explosionBurst() calls are untouched; tinted bursts pass
  // T.novaRing (neutral white) + a saturated tint so the same geometry can be recolored.
  function spawnRing(x, y, maxR = 90, dur = 0.35, look = T.novaWarm, tint = 0xffffff) {
    const rg = rings[ringCursor]
    ringCursor = (ringCursor + 1) % MAX_RINGS
    if (!rg.s) {
      rg.s = spriteOf(look)
      novaLayer.addChild(rg.s)
    }
    if (rg.s.texture !== look.tex) rg.s.texture = look.tex
    rg.s.tint = tint
    rg.live = true
    rg.x = x
    rg.y = y
    rg.t = 0
    rg.dur = dur
    rg.maxR = maxR
    rg.s.visible = true
  }

  function updateRings(dt) {
    if (dt === 0) return
    for (const rg of rings) {
      if (!rg.live) continue
      rg.t += dt
      if (rg.t >= rg.dur) { rg.live = false; rg.s.visible = false; continue }
      const k = rg.t / rg.dur
      rg.s.position.set(rg.x, rg.y)
      rg.s.scale.set(Math.max(k * rg.maxR, 1) / 64)
      rg.s.alpha = 1 - k
    }
  }

  function clearRings() {
    for (const rg of rings) {
      rg.live = false
      if (rg.s) rg.s.visible = false
    }
  }

  // damage numbers: pooled Text objects, reuse the oldest when full
  const dmgTexts = []
  function spawnDamage(x, y, dmg, crit, dot, label = null) {
    let d = dmgTexts.find((t) => !t.live)
    if (!d && dmgTexts.length < MAX_DMG_TEXTS) {
      const t = new Text({
        text: '',
        style: {
          fontFamily: 'Trebuchet MS, Verdana, sans-serif',
          fontSize: 17,
          fontWeight: '900',
          fill: 0xffffff,
          stroke: { color: 0x6b5847, width: 3.5, join: 'round' },
        },
      })
      t.anchor.set(0.5)
      textLayer.addChild(t)
      d = { t, live: false, age: 0, x: 0, y: 0 }
      dmgTexts.push(d)
    }
    if (!d) {
      d = dmgTexts[0]
      for (const o of dmgTexts) if (o.age > d.age) d = o
    }
    d.live = true
    d.age = 0
    d.x = x + (Math.random() * 10 - 5)
    d.y = y - 10
    d.t.text = label ? label.text : String(Math.round(dmg))
    // DoT ticks read as small muted numbers so a status-covered crowd doesn't flood the screen.
    // v5.24: chapterRender.ink (the blank) replaces the white base fill — white numbers vanish on
    // the white void — and pulls the muted DoT grey toward itself for the same reason. The crit
    // orange and the stroke survive on white as-is.
    const ink = chapterRender.ink ?? 0xffffff
    d.t.tint = label ? label.tint : crit ? 0xff8c42 : dot ? (ink === 0xffffff ? 0xd8cbbd : mix(ink, 0xffffff, 0.45)) : ink
    d.t.visible = true
    d._base = label ? 0.95 : crit ? 1.25 : dot ? 0.6 : 0.85
  }

  function updateDamage(dt) {
    for (const d of dmgTexts) {
      if (!d.live) continue
      d.age += dt
      if (d.age >= 0.75) { d.live = false; d.t.visible = false; continue }
      const k = d.age / 0.75
      const pop = 1 + 0.35 * Math.max(0, 1 - d.age * 7)
      d.t.position.set(d.x, d.y - 30 * k)
      d.t.scale.set(d._base * pop)
      d.t.alpha = k > 0.55 ? 1 - (k - 0.55) / 0.45 : 1
    }
  }

  function clearDamage() {
    for (const d of dmgTexts) {
      d.live = false
      d.t.visible = false
    }
  }

  // ------------------------------------------------------------------- state
  let animT = 0        // run animation clock (frozen when dt=0)
  // v6.5 undergrowth: set once per frame in sync(), before the syncPool block — placeTrap reads
  // simTime against a trap's absolute rearmAt for the re-arm tell; ambushHeld/ambushPX/ambushPY
  // mirror slashClaws' own AMBUSH_R scan (sim.js) for the render-only proximity pulse. Read-only
  // snapshots of `run`, never written back.
  let simTime = 0
  let ambushHeld = false
  let ambushPX = 0
  let ambushPY = 0
  let hop = 0          // player hop phase
  let breathe = 0
  let idleT = 0
  let flashT = 0       // player hurt flash
  // v5.11 kaiju redesign: 0->1 pulse set by the `tail` sim event (WEAPONS.tailLash/stepLashWeapon),
  // decaying over SKIES_KAIJU.swipeDecay seconds — see syncPlayer's kaiju tail branch. The event
  // already drives spawnWhip's arc-swoosh at the hit site (handleEvents); this makes the anatomical
  // tail itself visibly crack at the same moment, instead of only an effect appearing where it
  // lands. Harmless outside skies: tailLash isn't in any other chapter's weapon pool, so the `tail`
  // event never fires there and this timer just sits at 0, unread (playerForm === 'kaiju' gates its use).
  let kaijuSwipeT = 0
  let vignetteA = 0
  let lightningFlashA = 0 // full-field white flash alpha (skies lightning, LIGHTNING.flash), decays in sync()
  let prevSkiesBombs = new Set() // last frame's run.bombs objects (skies only) — see handleEvents
  let prevSkiesShots = new Set() // ditto for run.enemyShots — tells a missile that IMPACTED from one
                                 // that merely fizzled, without a sim change (spec §1.1's problem,
                                 // solved render-side by object-identity diffing)
  let flashCooldown = 0          // s left in the full-field flash budget (spec §1.3)
  let jamT = 0                   // rampage telegraph-jamming strength, 1 while rampaging then
                                 // decaying over SKIES_JAM.recoverT so the picture RE-ACQUIRES
  let jamSnapT = 0               // lock-diamond re-snap cadence
  let rampBeatT = 0              // heartbeat-ring accumulator
  // v5.8 kaiju redesign: last frame's run.rampageT, render-local memory only — NEVER written back
  // to run (render must not mutate it). RAMPAGE's trigger is a LEVEL (rampageT jumps 0 ->
  // RAMPAGE_DURATION in one frame, sim.js stepRampage), not an event, so it's detected the same way
  // justStruck above diffs bomb identity: compare this frame's value against last frame's copy —
  // see handleEvents. Stays 0 forever for any chapter without `crush` (state.js: rampageT never
  // moves off 0 there), so this is inert everywhere but skies.
  let prevRampageT = 0
  let frameDt = 0      // this frame's dt, for pool callbacks that need real elapsed time
  let playerX = 0      // player position, for pool callbacks whose entities are player-anchored (beams)
  let playerY = 0
  const homingTimers = [] // per-slot accumulator: index-aligned with homingPool, trail particle cadence
  const shotTimers = []   // per-slot accumulator: index-aligned with the enemyShots pool, smoke cadence
  const holeParticleTimers = [] // per-slot accumulator: index-aligned with holePool, suction particle cadence
  const shake = { t: 0, dur: 1, amp: 0, ox: 0, oy: 0 }

  function addShake(amp, dur) {
    const current = shake.t > 0 ? shake.amp * (shake.t / shake.dur) : 0
    if (amp < current) return
    shake.amp = amp
    shake.t = dur
    shake.dur = dur
  }

  function fitScreen() {
    const w = app.screen.width
    const h = app.screen.height
    if (vignette.width !== w || vignette.height !== h) {
      vignette.width = w
      vignette.height = h
    }
    if (lightningFlash.width !== w || lightningFlash.height !== h) {
      lightningFlash.width = w
      lightningFlash.height = h
    }
    if (waterWash.width !== w || waterWash.height !== h) {
      waterWash.width = w
      waterWash.height = h
    }
  }

  // ------------------------------------------------------------------ events
  function killPoof(x, y, etype, elite) {
    const color = elite ? 0xff9d5c : (ENEMY_LOOKS[etype]?.fill ?? 0xcccccc)
    const n = 5 + (Math.random() * 4 | 0)
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = 50 + Math.random() * 110
      spawnParticle(T.dot.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp - 20,
        0.35 + Math.random() * 0.25, 0.4 + Math.random() * 0.5, color, -0.6, 3)
    }
    spawnParticle(T.dot.tex, x, y, 0, -8, 0.32, 1.3, 0xfffdf5, 3.2, 0)
  }

  // `healed` (v7.2): the AVARICE anomaly converts a share of collected coins into HP instead of
  // paying out. sim.js has always flagged the event; nothing read it, so the conversion looked and
  // sounded exactly like a normal pickup while the coin counter silently failed to move — the one
  // moment the card is actually doing its thing, and it was invisible. Reuses the revive's
  // heart-pink rather than introducing a colour: that is already this game's "you got health back"
  // vocabulary, so it reads without being taught.
  function pickupSparkle(x, y, coin, healed = false) {
    const tint = healed ? 0xff8fb1 : coin ? 0xffcf4d : 0xffd93d
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2
      spawnParticle(T.sparkle.tex, x, y, Math.cos(a) * 35, Math.sin(a) * 35 - 45,
        0.3 + Math.random() * 0.15, 0.35 + Math.random() * 0.3, i === 2 ? 0xffffff : tint, -0.5, 2)
    }
  }

  function explosionBurst(x, y, radius = 90) {
    const k = radius / 90 // visuals tuned at 90px; scale to the actual blast radius
    const n = 8 + (Math.random() * 3 | 0) // 8-10
    for (let i = 0; i < n; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = (90 + Math.random() * 140) * k
      spawnParticle(T.dot.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp,
        0.3 + Math.random() * 0.2, (0.4 + Math.random() * 0.4) * k, 0xffb37a, -0.8, 4)
    }
    // scorch flash: quick scale-up + fast fade, reads as an impact flash under the ring
    spawnParticle(T.fx.scorch_01, x, y, 0, 0, 0.22, 0.05 * k, 0xffcf6b, 1.0, 0)
    // a few jagged spark shards flung outward
    for (let i = 0; i < 4; i++) {
      const a = Math.random() * Math.PI * 2
      const sp = (160 + Math.random() * 120) * k
      spawnParticle(T.fx.spark_04, x, y, Math.cos(a) * sp, Math.sin(a) * sp,
        0.22 + Math.random() * 0.1, (0.06 + Math.random() * 0.03) * k, 0xff8c42, 0, 5)
    }
    // The blast-extent ring: default white vanishes on the blank's void, so it goes violet there.
    spawnRing(x, y, radius, 0.35, T.novaWarm, chapterIsVoid ? 0x8a5fe0 : 0xffffff)
  }

  // ---- Reality Shard seams (v7.29) -----------------------------------------------------------
  // tornSeam used to be a sewer zone that erupted as a campfire: a green bubbling disc at the
  // shard's departure point for 0.3s, then explosionBurst's orange scorch. Water and fire, in the
  // one chapter that is neither, describing a point when the mechanic is a LINE.
  //
  // Now the art IS the hitbox. sim.js hands over (a, d) — the heading and the length of the skip —
  // and hit-tests a capsule about exactly the segment drawn here, so a seam cuts what it looks
  // like it cuts. It opens at its widest the instant the shard leaves and pinches shut as the fuse
  // burns: space healing over the gap, not a charge going off.
  //
  // The budget is the second constraint. At Lv5 with Quick Draw a build plants ~30 seams a SECOND
  // (4 shards x a blink every 0.2s x a volley every 0.5s), so ~9 are alive at any moment. This
  // spends 6 particles on a close; explosionBurst spends 13, which is why it turned to soup.
  const RIFT_EDGE = 0xc9b8ff  // lit lilac, off the shard bullet's own violet — the torn edge
  const RIFT_CORE = 0xffffff  // the mouths, and the zip

  function riftTelegraph(gy) {
    const dur = Math.max(0.001, gy.dur || 1)
    const k = 1 - Math.max(0, Math.min(1, gy.fuse / dur)) // 0 -> 1 over the fuse
    const a = gy.a || 0
    const d = gy.d || gy.r * 2
    const ux = Math.cos(a), uy = Math.sin(a)
    const px = -uy, py = ux
    // THIN, and DARKER INSIDE than the void it sits in. A fat symmetric lens is a petal however it
    // is tinted: the first cut of this filled it violet and four parallel seams read, unmistakably,
    // as a lotus — the Trash Tornado trap again, a coherent drawing of the wrong thing. What makes
    // it a hole instead is that you can see nothing through it.
    const W = d * 0.07 * (1 - k)                 // widest at birth, pinched shut at the pop
    const ex = gy.x + ux * d, ey = gy.y + uy * d
    const mx = gy.x + ux * d * 0.5, my = gy.y + uy * d * 0.5
    hazardG.moveTo(gy.x, gy.y)
      .quadraticCurveTo(mx + px * W * 2, my + py * W * 2, ex, ey)
      .quadraticCurveTo(mx - px * W * 2, my - py * W * 2, gy.x, gy.y)
      .fill({ color: 0x05010f, alpha: 0.55 * (1 - k) })
      .stroke({ width: 1.2 + (1 - k) * 1.3, color: RIFT_EDGE, alpha: 0.4 + 0.5 * (1 - k) })
    // The two mouths stay lit all the way down. They are the only part that survives a stack of
    // overlapping seams, and they are where the shard actually was — in and out.
    hazardG.circle(gy.x, gy.y, 2.5).fill({ color: RIFT_CORE, alpha: 0.5 + k * 0.4 })
      .circle(ex, ey, 2.5).fill({ color: RIFT_CORE, alpha: 0.5 + k * 0.4 })
  }

  // The close. No ring: a ring is a blast radiating from a point, and this is a line zipping shut.
  function riftBurst(x, y, radius, a = 0, d = 0) {
    const len = d || radius * 2
    const ux = Math.cos(a), uy = Math.sin(a)
    spawnArc([[x, y], [x + ux * len, y + uy * len]], RIFT_CORE, RIFT_EDGE, 0.14, 4, 1)
    for (let i = 0; i < 4; i++) {
      const side = i % 2 ? 1 : -1
      const ca = a + side * (1.35 + Math.random() * 0.5)
      const t = 0.25 + Math.random() * 0.5   // squeezed out from somewhere along the seam
      const sp = 150 + Math.random() * 110
      spawnParticle(T.fx.spark_04, x + ux * len * t, y + uy * len * t,
        Math.cos(ca) * sp, Math.sin(ca) * sp, 0.20, 0.05, RIFT_EDGE, 0, 5)
    }
    spawnParticle(T.fx.light_01, x + ux * len * 0.5, y + uy * len * 0.5, 0, 0,
      0.16, 0.07, RIFT_CORE, 0.6, 0)
    addShake(1, 0.07)
  }

  // Crush collapse (skies only — sim.js's stepCrush, {type:'crush',x,y,kind}). v5.10 replaced this
  // outright: see skiesCrush above for the shard/dust/ruin treatment and kill list §8.4 for what it
  // reused (T.fx.circle_05 + T.fx.scorch_01 + T.dot — the same two Kenney textures explosionBurst
  // uses, just tinted grey, plus the same soft dot as kill-poofs and pickup sparkles). The "fleeing
  // figures" dots are gone too (spec §11: the lights-going-out beat carries the same implication
  // better and abstractly).

  function beamSparkle(x, y) {
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2
      spawnParticle(T.sparkle.tex, x, y, Math.cos(a) * 70, Math.sin(a) * 70,
        0.3 + Math.random() * 0.1, 0.35 + Math.random() * 0.2, i % 2 ? 0xff8fab : 0xb06cf0, -0.6, 3)
    }
  }

  function strokePath(g, path, width, color, alpha) {
    g.moveTo(path[0][0], path[0][1])
    for (let i = 1; i < path.length; i++) g.lineTo(path[i][0], path[i][1])
    g.stroke({ width, color, alpha, join: 'round', cap: 'round' })
  }

  // Elemental shock arcs (shockarc/frostarc/conduct): jagged-polyline visuals driven by a
  // one-off render-local pool instead of run-state (these are single-shock proc events,
  // not a persisting sim list) — spawn once, fade over `dur`, then recycle. v5.7.2: also reused
  // by skies' lightning bolts (strikeLightning below) — same jagged glow-
  // then-core stroke IS a lightning bolt, no separate drawer needed. width/peak default to the
  // original hardcoded 7/1 so shockarc/frostarc/conduct's look is byte-for-byte unchanged.
  const MAX_ARCS = 8
  const arcs = []
  for (let i = 0; i < MAX_ARCS; i++) {
    arcs.push({ live: false, points: null, life: 0, dur: 0.25, outer: 0x6c5ce7, inner: 0xffffff, width: 7, peak: 1 })
  }
  let arcCursor = 0

  function spawnArc(points, outer, inner = 0xffffff, dur = 0.25, width = 7, peak = 1) {
    const a = arcs[arcCursor]
    arcCursor = (arcCursor + 1) % MAX_ARCS
    a.live = true
    a.points = points
    a.life = dur
    a.dur = dur
    a.outer = outer
    a.inner = inner
    a.width = width
    a.peak = peak
  }

  function updateArcs(dt) {
    if (dt <= 0) return
    for (const a of arcs) {
      if (!a.live) continue
      a.life -= dt
      if (a.life <= 0) a.live = false
    }
  }

  function clearArcs() {
    for (const a of arcs) a.live = false
    arcG.clear()
  }

  // Jagged-jitter builder used by redrawArcs: deterministic-hash trick (stable frame-to-frame,
  // freezes cleanly at dt=0).
  function jitterPath(pts, salt) {
    const path = [pts[0]]
    for (let i = 0; i < pts.length - 1; i++) {
      const [x1, y1] = pts[i]
      const [x2, y2] = pts[i + 1]
      const dx = x2 - x1
      const dy = y2 - y1
      const len = Math.hypot(dx, dy) || 1
      const nx = -dy / len
      const ny = dx / len
      const subN = 2 + (hash(x1 * 12.9898 + y1 * 78.233 + salt) > 0.5 ? 1 : 0) // 2-3 points
      for (let s = 1; s <= subN; s++) {
        const t = s / (subN + 1)
        const bx = x1 + dx * t
        const by = y1 + dy * t
        const seed = x1 * 12.9898 + y1 * 78.233 + x2 * 4.14 + y2 * 9.23 + s * 17.17 + salt
        const j = (hash(seed) - 0.5) * 18
        path.push([bx + nx * j, by + ny * j])
      }
      path.push([x2, y2])
    }
    return path
  }

  // v7.23 skies. Two persisting player effects, one Graphics, cleared and redrawn from run state
  // every frame — the same idiom as hazardG/laneG, and it needs no pool because a fork is a
  // polyline whose vertex COUNT changes every tick (it re-forks as bodies die).
  function redrawBreath(run) {
    breathG.clear()
    const p = run.player
    // Tail Lash: a tether from the kaiju to each aircraft being reeled in. Without it the plane
    // reads as sliding toward you for no reason — the tether IS the causal link.
    // DELIBERATELY NOT JAGGED. The first cut ran this through jitterPath like the fork below, and
    // the probe frame showed the two weapons as the same effect: cyan-green crackle leaving the
    // kaiju's head, twice. "It's not clear" is the complaint that started this whole rework, so the
    // two must not converge. A tail is a TAUT CABLE and lightning is JAGGED — one straight heavy
    // stroke against a jittered polyline separates them at a glance, with no new colour needed.
    for (const d of run.drags || []) {
      const e = run.enemies.find((x) => x.id === d.id)
      if (!e) continue
      breathG.moveTo(p.x, p.y).lineTo(e.x, e.y).stroke({ width: 9, color: SKIES_PALETTE.player, alpha: 0.28, cap: 'round' })
      breathG.moveTo(p.x, p.y).lineTo(e.x, e.y).stroke({ width: 3.5, color: SKIES_PALETTE.playerHot, alpha: 0.9, cap: 'round' })
      // A hook at the far end: the bit that is actually holding the aircraft.
      breathG.circle(e.x, e.y, 9).stroke({ width: 3, color: SKIES_PALETTE.playerHot, alpha: 0.9 })
    }
    for (let i = 0; i < (run.arcs || []).length; i++) {
      const a = run.arcs[i]
      // The wind-up draws NOTHING here (v7.26, owner: "remove the green circle tell"). A closing
      // ring stood in for the telegraph while the dorsal plates were unimplemented; now that they
      // chain-charge along the spine (lightPlatesForBreath) the ring is a second tell for the same
      // half-second, on a weapon that fires continuously — so it read as permanent screen furniture
      // rather than as a warning. The plates are the telegraph.
      if (a.charge > 0) continue
      if (!a.nodes || a.nodes.length < 2) continue
      // v7.26 (owner: "should shoot from the mouth"). The sim roots the fork at the player's
      // CENTRE, which is correct for it — the chain's geometry is body-to-body and the first
      // segment's origin has no bearing on what is damaged. Where it is DRAWN from is anatomy, so
      // it is resolved here: drawKaijuBody points the head at local -y and syncPlayer rotates bodyC
      // by facingAngle + PI/2, which works out to a plain forward offset along facingAngle once the
      // container scale is applied. Only the first node moves; every jump after it is a real body.
      const pts = a.nodes.map((n) => [n.x, n.y])
      if (playerForm === 'kaiju' && p.facingAngle != null) {
        const m = SKIES_KAIJU.muzzle * SKIES_KAIJU.bodyScale
        pts[0] = [p.x + Math.cos(p.facingAngle) * m, p.y + Math.sin(p.facingAngle) * m]
      }
      const path = jitterPath(pts, i * 5.1)
      strokePath(breathG, path, 10, SKIES_PALETTE.player, 0.35)
      strokePath(breathG, path, 3.5, SKIES_PALETTE.playerHot, 0.95)
    }
  }

  function redrawArcs() {
    arcG.clear()
    for (let ai = 0; ai < arcs.length; ai++) {
      const a = arcs[ai]
      if (!a.live) continue
      const pts = a.points
      if (!pts || pts.length < 2) continue
      const alpha = Math.max(0, Math.min(1, a.life / a.dur)) * a.peak
      const path = jitterPath(pts, ai * 3.7)
      strokePath(arcG, path, a.width, a.outer, alpha * 0.35)
      strokePath(arcG, path, Math.max(1, a.width * 2 / 7), a.inner, alpha)
    }
  }

  // Jagged vertical polyline from off the top of (x,y) cracking straight down onto it — lateral
  // jitter tapers to exactly 0 at the last point so the bolt always lands ON the strike point.
  // Feeds spawnArc (its own jitterPath pass adds a layer of finer wobble on top of this). Math.
  // random is fine here: a one-shot cosmetic shape, not on the deterministic sim path.
  function lightningBoltPath(x, y, dropPx, segments, jitterPx) {
    const pts = []
    for (let i = 0; i <= segments; i++) {
      const t = i / segments
      const j = (Math.random() * 2 - 1) * jitterPx * (1 - t)
      pts.push([x + j, y - dropPx * (1 - t)])
    }
    return pts
  }

  // v5.10: the single strikeLightning() drawer that served BOTH the tank shell and the sky strike
  // is gone — that shared drawer is kill-list §8.3 in its purest form. See artilleryDetonation and
  // skyDetonation, which share nothing but the screen shake.

  // v5.10 (spec §1.3): the photosensitivity budget is CENTRAL, not per-effect —
  // LIGHTNING.flash.strikeAlpha is 0.55 and a late-run barrage lands several strikes a second. A
  // flash inside the cooldown window is ADMITTED at a fraction of its requested alpha rather than
  // dropped (a strike you cannot see is worse than a dim one). The paired rule lives in syncPlayer:
  // the rampage screen bloom is forced to 0 on any frame where the flash is up, so the two never
  // co-render. flashCooldown is drained in sync().
  function triggerLightningFlash(alpha) {
    if (flashCooldown > 0) { lightningFlashA = Math.max(lightningFlashA, alpha * SKIES_FLASH.suppressedMul); return }
    lightningFlashA = Math.max(lightningFlashA, alpha)
    flashCooldown = SKIES_FLASH.minGap
  }

  // v5.13: updateAmbientLightning is DELETED ("too much animation"). It fired a full-field white
  // flash plus a bolt every 6-14s that meant nothing, damaged nothing and could not be acted on —
  // and v5.10.1 had already had to give it a THIRD hue purely so players would stop reading it as
  // an incoming strike. An effect that has to be redesigned to be ignorable is an effect that
  // should not be drawn. The real strike bolt (strikeLightning, still live) keeps every bit of
  // this idiom; the sky is not quieter when something is actually falling on you.

  function levelupBurst(x, y) {
    for (let i = 0; i < 14; i++) {
      const a = (i / 14) * Math.PI * 2
      const sp = 130 + Math.random() * 70
      spawnParticle(T.sparkle.tex, x, y, Math.cos(a) * sp, Math.sin(a) * sp,
        0.5 + Math.random() * 0.2, 0.55 + Math.random() * 0.35,
        i % 2 ? 0x7de3c3 : 0xffd93d, -0.8, 3)
    }
  }

  function handleEvents(run, events) {
    // v5.7.2: skies re-themes REAL bomb detonations (run.bombs — bombardment/artillery/volatile,
    // all of it) as lightning instead of the generic 'explode' burst below — see that case. Bomb
    // objects are created once and mutated in place until removed (stepBombs/stepBombardment in
    // sim.js: b.fuse -= dt, then run.bombs = run.bombs.filter(...) drops the dead ones), so object
    // identity is stable frame-to-frame. Diffing this frame's run.bombs against last frame's set
    // tells us exactly which bombs just went off — zero sim reads beyond the array itself, and no
    // change to run.bombs' shape or timing.
    let justStruck = null
    let justFizzled = null
    if (chapterHasStorm) {
      const curBombs = new Set(run.bombs)
      justStruck = []
      for (const b of prevSkiesBombs) if (!curBombs.has(b)) justStruck.push(b)
      prevSkiesBombs = curBombs
      // same trick for run.enemyShots: a missile that IMPACTED emits an explode event this frame
      // and is gone from the array, which is how the magenta impact drawer knows it is a missile
      // and not a weapon nova that happened to land on the same pixel
      const curShots = new Set(run.enemyShots || [])
      justFizzled = []
      for (const sh of prevSkiesShots) if (!curShots.has(sh)) justFizzled.push(sh)
      prevSkiesShots = curShots
    } else if (prevSkiesBombs.size || prevSkiesShots.size) {
      prevSkiesBombs = new Set() // left skies mid-flight (e.g. a run ended) — drop stale refs
      prevSkiesShots = new Set()
    }

    // v5.8 kaiju redesign: RAMPAGE activating is a level, not an event (sim.js stepRampage jumps
    // run.rampageT from 0 straight to RAMPAGE_DURATION the frame the meter fills) — catch the 0 ->
    // active transition here the same way justStruck above catches a bomb detonating, then hand the
    // sustained glow to syncPlayer (it reads run.rampageT itself every frame; this only needs the
    // ONE-TIME entry pulse). prevRampageT is render-local memory, never written back to run.
    if (run.rampageT > 0 && prevRampageT <= 0) addShake(5, 0.3) // the widened crush radius just landed
    prevRampageT = run.rampageT

    for (const e of events) {
      switch (e.type) {
        case 'hit':
          spawnDamage(e.x, e.y, e.dmg, e.crit, e.dot)
          break
        // A shot that bounced off a Shore Crab's raised claw. This exists because the alternative is
        // NOTHING happening on screen, and nothing-happening is indistinguishable from a broken
        // weapon — which is precisely how the elements redesign shipped a dead freeze. Deliberately
        // NOT a damage number: the player dealt no damage, and a floating 0 is worse than a spark.
        // A short pale spray thrown back ALONG the guard's own bearing, so the tell also says which
        // side is covered — the information the player needs is "go round", not "you missed".
        case 'guardblock': {
          const a0 = e.angle ?? 0
          for (let i = 0; i < 3; i++) {
            const a = a0 + (Math.random() - 0.5) * 1.1
            const sp = 70 + Math.random() * 70
            spawnParticle(T.fx.circle_05, e.x + Math.cos(a0) * 12, e.y + Math.sin(a0) * 12,
              Math.cos(a) * sp, Math.sin(a) * sp, 0.16 + Math.random() * 0.1, 0.05, 0xffe8cf, 0.1, 2)
          }
          break
        }
        case 'kill':
          killPoof(e.x, e.y, e.etype, e.elite)
          break
        // v6.6.25: something the mower cut down (sim.js's stepLanePasses, {type:'mow',x,y,r}).
        // Deliberately NOT the 'crush' path below — that is the skies' masonry treatment, with
        // brick dust and a permanent ruin decal, and a mown bush must not leave rubble on a lawn.
        // Reuses the mower's own clipping particle so a felled bush and the spray off the deck read
        // as one event. Scaled by the thing's radius: a big shrub throws more than a tuft.
        case 'mow': {
          const n = 4 + Math.min(8, Math.round((e.r ?? 24) / 5))
          for (let i = 0; i < n; i++) {
            const a = Math.random() * Math.PI * 2
            const sp = 60 + Math.random() * 90
            spawnParticle(T.fx.circle_05, e.x, e.y, Math.cos(a) * sp, Math.sin(a) * sp,
              0.35 + Math.random() * 0.2, 0.07, i % 3 ? 0x7cb342 : 0x9ccc65, 0.1, 2)
          }
          break
        }
        case 'crush': {
          const cr = radiusAtCrush(e.x, e.y)
          // v7.x: stepCrush now has two callers — the kaiju walking through a town, and The Reef's
          // Burst going through a coral head — and they are the same EVENT with different physics.
          // Branching here (on the chapter latch, not on e.kind) rather than emitting a second
          // event type keeps the sim's third entry point to the crush path free of a render concern.
          if (chapterHasBurst) { coralShatter(e.x, e.y, cr); break }
          // v5.10: e.kind IS read now — it is the point. Brick does not fall like grain and neither
          // falls like a pier into water (SKIES_FX.crush.byKind), and the site keeps a kind-specific
          // baked RUIN afterwards: the only thing in the chapter that records what you did.
          skiesCrush(e.x, e.y, e.kind)
          ledgerAdd(e.x, e.y, e.kind, cr)
          break
        }
        // v6.3 dispatch beat (sim.js: CHAPTERS[].dispatch chapters, elite spawn only): "you've been
        // reported" finally lands in-run. Brief red strobe at the elite's spawn point — two rings,
        // staggered, well under 0.5s total — plus main.js's siren and ui.js's HUD line.
        case 'dispatch':
          spawnRing(e.x, e.y, 60, 0.22, T.novaRing, 0xff5a4a)
          spawnRing(e.x, e.y, 34, 0.18, T.novaRing, 0xff5a4a)
          break
        case 'hurt': {
          // v6.3.4: damage now scales (dmgScale/difficulty), so a floored 1-dmg tick and a 60-dmg
          // late elite hit must not read as the same event — scale the fixed magnitudes below by
          // how big the hit was relative to maxHP (a hit >= 20% of maxHP keeps full feedback).
          const frac = Math.min(1, (e.dmg / Math.max(1, run.player.maxHP)) * 5)
          const hurtMul = 0.4 + 0.6 * frac
          // v7.2: a hit you did to YOURSELF, on purpose, on a schedule, is not an attack. OVERLOAD
          // spends 0.75 HP/s in whole points, so it emits ~150 `hurt` events over a run — at full
          // reaction that is a shake-and-red pulse every 1.33 seconds for the rest of the game,
          // which reads as a malfunction rather than as a cost. Damped to a faint vignette with no
          // shake and no flash: still legible as "you are burning", never mistaken for damage
          // taken. `src` is set only by the anomaly, so every other DoT in the game is untouched.
          if (e.src === 'overload') {
            vignetteA = Math.max(vignetteA, 0.12)
            break
          }
          addShake(6 * hurtMul, 0.25)
          vignetteA = 0.6 * hurtMul
          flashT = 0.28 * hurtMul
          break
        }
        case 'levelup':
          levelupBurst(run.player.x, run.player.y)
          break
        // v5.21 lane: the Repulsion shove. Two concentric rings expanding to the REAL sim radius
        // (e.r, pushed by stepRepulse) rather than a fixed size — the player has to be able to learn
        // where the edge is, and a burst that lies about its reach makes the cooldown feel arbitrary.
        case 'repulse':
          spawnRing(e.x, e.y, e.r, 0.42, T.novaWarm, 0xbca8ff)
          spawnRing(e.x, e.y, e.r * 0.62, 0.28, T.novaWarm, 0xe8dcff)
          break
        case 'rockhit':
          spawnRing(e.x, e.y, 70, 0.26, T.novaWarm, 0xc9bda4)
          break
        // v7.x The Trawl — Breach. NO SFX_FOR_EVENT ENTRY, and that is a decision rather than an
        // omission: Breach fires on the SAME press as the Pulse, which already sounds ('hole'), so a
        // second sample would double up on one button. The rule CLAUDE.md states is that an event
        // earns a sound by being rare enough to bear one; this one is rare and already audible.
        //
        // The HOLE itself is persistent and is drawn by updateNet (frayed
        // ends at every cut edge), so this event is only the moment of tearing: a ring at the cut
        // scaled to the hole the spend actually bought, so an empty bar and a full one visibly do
        // different amounts of damage to the wall. `e.r` and not a constant, for the same reason
        // stepRepulse pushes its scaled radius rather than REPULSE_RADIUS — a burst that lies about
        // its reach makes the cooldown feel arbitrary.
        case 'breach':
          spawnRing(e.x, e.y, e.r, 0.34, T.novaWarm, 0xf2e6b4)
          spawnRing(e.x, e.y, e.r * 0.55, 0.22, T.novaWarm, 0xffffff)
          break
        case 'revive':
          // Revive Token fired (see CONSUMABLES in config.js): a heart-warm double ring +
          // levelup-style burst sells the second chance; the sim already shoved enemies back.
          levelupBurst(e.x, e.y)
          spawnRing(e.x, e.y, 300, 0.45, T.novaRing, 0xff8fb1)
          spawnRing(e.x, e.y, 180, 0.35, T.novaRing, 0xffd166)
          addShake(5, 0.3)
          break
        case 'gem':
          pickupSparkle(e.x, e.y, false)
          break
        case 'coin':
          pickupSparkle(e.x, e.y, true, !!e.healed)
          // AVARICE's conversion gets a NUMBER (v7.15). The pink sparkle alone was not enough to
          // read in play — reported as "coins just give gold, it never heals" — because the coin
          // that heals looks like every other coin except for a 0.3s tint, the coin counter's
          // failure to move is invisible mid-fight, and +5 on a 150 HP bar is a couple of pixels.
          // Heart-pink to match the sparkle and the revive, so the whole vocabulary is one colour.
          if (e.healed && e.heal > 0) spawnDamage(e.x, e.y, 0, false, false, { text: `+${e.heal}`, tint: 0xff8fb1 })
          break
        case 'shoot':
          if (e.weapon === 'wave') {
            addShake(2.5, 0.12)
            // v6.2: a ripple TRAIN — the live nova entity draws the main ring; two trailing
            // rings at 60%/85% turn one flat circle into a wave that visibly travels.
            if (e.maxR) {
              spawnRing(e.x, e.y, e.maxR * 0.6, 0.25, T.nova, 0x59b7ff)
              spawnRing(e.x, e.y, e.maxR * 0.85, 0.35, T.nova, 0x59b7ff)
            }
          }
          break
        case 'bloom':  spawnRing(e.x, e.y, 40, 0.35, T.nova, 0x2fb6a3); break // v6.2: cast was invisible
        case 'lure':   spawnRing(e.x, e.y, 34, 0.30, T.nova, 0x67b26f); break // v6.2: cast was invisible
        case 'hydrant': spawnRing(e.x, e.y, 44, 0.40, T.nova, 0x5c8a4e); break // v6.2: cast was invisible
        case 'whip':
          // flagella lash: arc sweep flash + a soft shake (melee weight)
          spawnWhip(e.x, e.y, e.angle, e.range, e.arc)
          addShake(2, 0.1)
          break
        // The Surf's Skipping Shell touching down. Sand and foam thrown up where it landed, along
        // the direction it was travelling — a splash that goes UP in a top-down game reads as a
        // symmetrical puff, so the grit is what carries "it skipped off the sand" rather than "it
        // exploded here". Small shake only: this fires several times per throw.
        case 'skip': {
          // A fast droplet crown, constant across every splash variant so the variants isolate one
          // variable — how the splash's BODY is drawn (see placeNova).
          for (let i = 0; i < 11; i++) {
            const a = (i / 11) * Math.PI * 2 + Math.random() * 0.4
            const sp = 200 + Math.random() * 210
            spawnParticle(T.fx.spark_04, e.x, e.y, Math.cos(a) * sp, Math.sin(a) * sp,
              0.17 + Math.random() * 0.09, 0.04, i % 3 ? 0xffffff : 0xa8dcee, 0.03, 1.2)
          }
          addShake(1.2, 0.06)
          break
        }
        // A larva taking hold. Deliberately tiny and shakeless: this is the START of a slow grind,
        // not a payoff, and it fires several times a second in a crowd. It exists at all because
        // without it the only sign a cast connected is a tint change on a body that may be behind
        // three others.
        case 'crust': {
          for (let i = 0; i < 3; i++) {
            const a = Math.random() * Math.PI * 2
            const sp = 30 + Math.random() * 50
            spawnParticle(T.fx.spark_04, e.x, e.y, Math.cos(a) * sp, Math.sin(a) * sp,
              0.3, 0.06, 0xe9dcc6, 0.04, 1.4)
          }
          break
        }
        case 'roar':
          // v5.6.16: sonic wavefronts through the wedge + a shove-weight shake (see spawnRoar)
          spawnRoar(e.x, e.y, e.angle, e.range, e.arc)
          addShake(2.5, 0.12)
          break
        case 'tail':
          // v7.23 Tail Lash: a LINE, not a sector, so the whip's fat swoosh no longer describes it.
          // spawnArc is exactly the right drawer — a one-shot jagged polyline that flashes and
          // fades — and it is already here for the elemental shocks. Atomic cyan-green, palette
          // law 2: this is the player's own reach, never a threat.
          spawnArc([[e.x, e.y], [e.x + Math.cos(e.angle) * e.range, e.y + Math.sin(e.angle) * e.range]],
            SKIES_PALETTE.player, SKIES_PALETTE.playerHot, 0.22, 6, 1)
          // A lash that HOOKED something lands harder than one that swiped empty air.
          addShake(e.hooked > 0 ? 4 : 2, e.hooked > 0 ? 0.16 : 0.09)
          kaijuSwipeT = SKIES_KAIJU.swipeKick   // the anatomical tail itself cracks (syncPlayer)
          break
        case 'breath':
          // Atomic Breath: the cast itself only kicks the screen — the wind-up ring and the fork
          // are drawn from run.arcs every frame (redrawBreath), because both persist.
          addShake(2, 0.1)
          break
        case 'toss':
          // debris toss AND net toss: the lobs themselves are visible entities (syncLobs) — the
          // event only kicks the screen so the throw has weight
          addShake(1.5, 0.08)
          break
        case 'longline':
          // The line itself is drawn from run.longlines every frame (updateGear), because it
          // persists — the event is only the moment of paying it out.
          addShake(1.2, 0.07)
          break
        case 'scent':
          // The Deep's button. The MARK on each body is drawn every frame from `scentT`
          // (drawDeepTells) because it persists and because bodies swim into it after the press —
          // so this is only the cast itself: one expanding ring saying how far the smell reached.
          // spawnRing is the shipped one-shot expander every other radial cue here already uses.
          spawnRing(e.x, e.y, e.r, 0.4, T.novaRing, 0xff8a5c)
          addShake(2 + 2 * (e.charged ?? 0), 0.12)
          break
        case 'anglerBite':
          // A bite that CONNECTS is already carried by the `hurt` event's red vignette, so this is
          // the fish's half: a short hard snap at the mouth. Drawn on a MISS too, and deliberately
          // — the player who backed off in time has earned the right to see the jaws close on
          // nothing, and a tell that only fires when you are hit teaches nothing about the timing.
          spawnRing(e.x, e.y, 70, e.hit ? 0.3 : 0.18, T.novaRing, e.hit ? 0xff4a2a : 0x8a6a55)
          addShake(e.hit ? 4.5 : 1.4, e.hit ? 0.16 : 0.07)
          break
        case 'finHit':
          // The shark's own body. `power` is the speed scaling the card is sold on — a sweep drawn
          // identically at a crawl and at a sprint would make the whole mechanic invisible — so it
          // drives both the swoosh's reach and the kick.
          spawnWhip(e.x, e.y, e.angle, e.range * (0.72 + 0.28 * e.power), e.arc)
          addShake(1 + 2.4 * e.power, 0.07)
          break
        case 'snare':
          // The landed mesh has no sim entity behind it (the hold lives on each body as `stunT`),
          // so THIS is where the drawing is born — see pushSnare. The kick scales with the catch:
          // a net over five bodies should land harder than one that closed on empty water.
          pushSnare(e.x, e.y, e.radius, e.hold)
          addShake(e.caught > 0 ? 2.6 : 1.2, e.caught > 0 ? 0.12 : 0.07)
          break
        case 'clawRake':
          // Claw Rake: three parallel gashes (spawnClaw — NOT the whip's swoosh; see there). A
          // lighter shake than the lash: it's a quick shred, and at this cadence a full-weight one
          // would rattle the screen nonstop.
          spawnClaw(e.x, e.y, e.angle, e.range, e.arc)
          addShake(1.2, 0.07)
          break
        case 'strafeLock':
          // Jet strafe wind-up (v5.9.1, see updateStrafeLocks above) — a WARNING, not an impact, so
          // no screen shake here (nothing has hit anything yet; the shake for the actual pass is
          // just the jet's own contact damage, same as any other enemy).
          spawnStrafeLock(e.x, e.y, e.angle, e.len)
          break
        case 'explode': {
          // A seam zipping shut is not a detonation — it never reaches the skies branches below.
          if (e.rift) { riftBurst(e.x, e.y, e.radius, e.a, e.d); break }
          // THE GULL LANDS. Not a detonation drawer at all: the whole point of this hazard is that
          // the thing arriving is an ANIMAL, so what plays here is the bird, hitting and leaving in
          // one motion ("a big bird plunging and taking off immediately"). The descent is already on
          // screen as the shadow; this is only the last beat of it.
          if (e.src === 'gull') { gullStrike(e.x, e.y, e.radius); break }
          // v5.10.1: THREE separate detonation drawers in skies, not one re-tinted burst. Which one
          // is decided by object identity, not by guessing from timing: justStruck holds the
          // run.bombs entries that vanished this frame (with `src` still on them, set explicitly by
          // sim.js — see bombSrc), and justFizzled holds the run.enemyShots that vanished. Volatile
          // used to fall through the `else` here straight into skyDetonation (a dead elite reading as
          // a lightning strike) — now it gets its own branch and its own drawer.
          const struckIdx = justStruck
            ? justStruck.findIndex((b) => b.x === e.x && b.y === e.y && b.radius === e.radius)
            : -1
          if (struckIdx >= 0) {
            const b = justStruck[struckIdx]
            justStruck.splice(struckIdx, 1)
            const bsrc = bombSrc(b)
            if (bsrc === 'gun') artilleryDetonation(e.x, e.y, e.radius)
            else if (bsrc === 'volatile') volatileDetonation(e.x, e.y, e.radius)
            else skyDetonation(e.x, e.y, e.radius)
            break                                   // all three drawers set their own shake
          }
          const fizzIdx = justFizzled
            ? justFizzled.findIndex((sh) => Math.abs(sh.x - e.x) < 1.5 && Math.abs(sh.y - e.y) < 1.5)
            : -1
          if (fizzIdx >= 0) {
            justFizzled.splice(fizzIdx, 1)
            missileImpact(e.x, e.y)                  // magenta star + black soot ring, NOT
            break                                    // explosionBurst's orange spark_04 (§8.5)
          }
          explosionBurst(e.x, e.y, e.radius)
          addShake(e.radius && e.radius < 80 ? 1.5 : 3, 0.16)
          break
        }
        case 'hole':
          // vortex opening reads fine on its own — no shake
          break
        case 'beam':
          beamSparkle(run.player.x, run.player.y)
          addShake(2, 0.12)
          break
        case 'shriek': // v6.2: the scream is no longer a recolored slime wave — staggered violet panic rings
          for (let i = 0; i < 3; i++) spawnRing(e.x, e.y, e.radius * (0.5 + i * 0.28), 0.3 + i * 0.09, T.nova, 0xb06cf0)
          addShake(2, 0.12)
          break
        case 'blink': // v6.2: realityShard's teleport — afterimage ring at the origin, rift streak to the exit
          spawnRing(e.x, e.y, 26, 0.22, T.nova, 0xb9a8f0)
          spawnArc([[e.x, e.y], [e.tx, e.ty]], 0xb9a8f0, 0xffffff, 0.18, 5, 0.7)
          break
        case 'shockarc':
          // the lightning infusion's arc: violet outer, bright yellow core
          if (e.points && e.points.length > 1) {
            spawnArc(e.points, 0x8a7bff, 0xffe94d, 0.2)
            const [lx, ly] = e.points[e.points.length - 1]
            spawnParticle(T.fx.flare_01, lx, ly, 0, 0, 0.18, 0.08, 0xffe94d, -0.1, 0)
          }
          break
        case 'ignitejump':
          // Fire spreading from a burning body to the next one. The event carried (x,y)->(tx,ty)
          // from the day it was written and nothing ever drew it, so on screen a second enemy
          // simply began burning for no visible reason. Unlike the arcs above it emits a PAIR of
          // points rather than a chain, so build the two-point path here. Palette is the ignite
          // one already used by the per-frame flame particle (0xff7a30), not a new colour.
          spawnArc([[e.x, e.y], [e.tx, e.ty]], 0xff7a30, 0xffd8a0, 0.18)
          spawnParticle(T.fx.flame_05, e.tx, e.ty, 0, -34, 0.35, 0.09, 0xff7a30, 0.15, 0.5)
          break
        // ---- v5.24 the blank (boss script). Every ring below carries an EXPLICIT tint:
        // spawnRing's default is white, which is invisible on the white void.
        case 'bossSpawn': {
          // implosion — the void condensing into a body: sparks converge INTO the arrival point,
          // then rings snap outward. Same treatment for stage 1's arrival and 2/3's reforms.
          for (let i = 0; i < 12; i++) {
            const a = (i / 12) * Math.PI * 2 + Math.random() * 0.3
            const d = 140 + Math.random() * 60
            spawnParticle(T.fx.star_08, e.x + Math.cos(a) * d, e.y + Math.sin(a) * d,
              -Math.cos(a) * d * 2.4, -Math.sin(a) * d * 2.4, 0.4, 0.09, i % 2 ? 0x8a5fe0 : 0x8880a8, -0.1, 0)
          }
          spawnRing(e.x, e.y, 230, 0.5, T.novaRing, 0x8a5fe0)
          spawnRing(e.x, e.y, 140, 0.36, T.novaRing, 0x8880a8)
          addShake(6, 0.35)
          break
        }
        case 'bossDead': {
          // the final kill only — the deletion deletes itself: a full-field white-out (the void
          // taking everything back, reusing the stage-level flash sprite) over a violet/ink burst
          lightningFlashA = 1
          for (let i = 0; i < 16; i++) {
            const a = (i / 16) * Math.PI * 2
            const sp = 170 + Math.random() * 160
            spawnParticle(T.fx.star_08, e.x, e.y, Math.cos(a) * sp, Math.sin(a) * sp,
              0.6 + Math.random() * 0.3, 0.12, i % 2 ? 0x8a5fe0 : 0x4a4458, -0.1, 2)
          }
          spawnRing(e.x, e.y, 420, 0.7, T.novaRing, 0x8a5fe0)
          spawnRing(e.x, e.y, 260, 0.5, T.novaRing, 0x4a4458)
          addShake(9, 0.5)
          break
        }
        case 'yank': {
          // the P2 drag landing: a violet ring where you ended up — sim already fired 'hurt' for
          // the vignette, this marks the SPOT so the sudden displacement reads as the yank
          spawnRing(e.x, e.y, 150, 0.35, T.novaRing, 0x8a5fe0)
          spawnRing(e.x, e.y, 80, 0.25, T.novaRing, 0x4a4458)
          addShake(5, 0.25)
          break
        }
      }
    }
  }

  // ------------------------------------------------------------------- reset
  function clearWorld() {
    for (const [id, s] of enemySprites) {
      s.visible = false
      hideAffixBadges(s)
      hideEnemyDecor(s)
      enemyFree.push(s)
      enemySprites.delete(id)
    }
    shieldG.clear()
    pacerG.clear()
    bombG.clear()
    stripG.clear()
    // v6.6.22: the lawn grows back between runs. mownByLane is a WeakMap keyed on lane objects the
    // old run owned, so it empties itself once those are unreachable — only the list needs clearing.
    mown.length = 0
    mownG.clear()
    mownDirty = false
    laneG.clear()
    hazardG.clear()
    teleG.clear()
    wellG.clear()
    bindG.clear()
    breathG.clear() // v7.23: a Graphics, not a pool — clearing it IS the reset (see redrawBreath)
    // v7.x The Trawl: same idiom as breathG above. A run that ends mid-pass must not leave a net
    // hanging over the summary screen and the next chapter.
    netG.clear()
    netWakeG.clear()
    // The player's gear, same idiom. `snares` is render-local state with no run.* entity behind it,
    // so unlike run.longlines it does NOT empty itself when the run object is replaced — clearing
    // the Graphics alone would leave every live slot to redraw its mesh on the next frame of the
    // next run. The flag is the reset; the Graphics clear only hides the current frame.
    longlineG.clear()
    snareG.clear()
    deepG.clear()
    for (const s of snares) s.live = false
    for (const key of Object.keys(prevCount)) prevCount[key] = 0
    for (const pool of [
      bulletPool, novaPool, orbPool, gemPool, coinPool,
      boomerangPool, minePool, homingPool, trapPool, shotPool,
      sandPool,    // v7.x surf: FLAT (one Sprite per dry patch) — likewise, not a rig
      rockPool,    // beyond: FLAT (one Sprite per asteroid). Was in NEITHER list — the lane's rocks
                   // stayed on screen into whatever came next, because a pool is only ever hidden
                   // by being named here and nothing checks that every pool is.
    ]) {
      for (const s of pool) s.visible = false
    }
    // debrisPool holds RIGS since v6.8.2 (a Container per funnel, one sprite per ring), so it must
    // hide .root — left in the flat list above, `s.visible = false` would set a dead property on a
    // plain object and quietly leave last run's funnels on screen.
    for (const tv of debrisPool) tv.root.visible = false
    for (const jv of jetPool) jv.root.visible = false        // rig pool: .root, not .visible
    for (const cv of carPool) cv.root.visible = false
    for (const lv of lobPool) lv.root.visible = false
    carCount = 0
    lobCount = 0
    for (const hv of holePool) hv.root.visible = false
    for (const bv of beamPool) bv.root.visible = false
    for (const pv of poolPool) pv.root.visible = false
    for (const bv of bloomPool) bv.root.visible = false
    for (const s of trailPool) s.visible = false
    for (const wv of webPool) wv.root.visible = false
    for (const lv of lurePool) lv.root.visible = false
    clearObstacles()
    clearWhips()
    clearClaws()
    clearRoars()
    clearStrafeLocks()
    clearCurrents()
    clearEddies()
    clearShafts()
    clearSwell()
    darkLayer.visible = false   // a run ending mid-dark must not leave the scrim over the next screen
    clearStorm()
    clearSkiesBombs()
    clearScars()
    clearRampage()
    clearSmoke()
    crushLedger.clear()
    for (const s of ruinSprites) s.visible = false
    for (const s of junctionSprites) s.visible = false
    for (const s of streetSprites) s.visible = false
    streetKey = ''
    prevSkiesShots = new Set()
    flashCooldown = 0
    jamSnapT = 0
    clearParticles()
    clearRings()
    clearArcs()
    clearDamage()
    clearFloorLayer()
    // the colour field is keyed to the run's world seed, so it has to go too
    clearGroundField()
    shake.t = 0
    shake.amp = 0
    shake.ox = 0
    shake.oy = 0
    flashT = 0
    vignetteA = 0
    vignette.alpha = 0
    lightningFlashA = 0
    lightningFlash.alpha = 0
    prevSkiesBombs = new Set()
    prevRampageT = 0
    animT = 0
    hop = 0
    breathe = 0
  }

  // -------------------------------------------------------------------- sync
  // The two anomalies that change the player's SKIN rather than adding chrome (v7.14). Read from
  // the RUN here because syncPlayer takes the player; returns both as 0..1 so the renderer never
  // has to know either card's tuning. Null when neither card is held, which is the common case and
  // the one that must cost nothing.
  //   BERSERK's value fades with _berserkT (hurtPlayer refreshes it to BERSERK_DURATION), so the
  // tell is strongest on the hit and dies with the window — the tint IS the timer.
  //   STILLNESS's is the same ramp the damage multiplier reads (stepAnomalies), so the silhouette
  // and the damage can never disagree.
  function playerBuffs(run) {
    const a = run.anomalies
    if (!a || (!a.berserk && !a.stillness)) return null
    const clamp01 = (v) => Math.max(0, Math.min(1, v))
    return {
      berserk: a.berserk ? clamp01((run._berserkT ?? 0) / BERSERK_DURATION) : 0,
      still: a.stillness ? clamp01((run._stillT ?? 0) / STILLNESS_RAMP) : 0,
    }
  }

  // `buffs` (v7.14): the two anomalies that change the player's SKIN rather than adding chrome —
  // { berserk, still }, both 0..1, built by playerBuffs() at the call site because this function
  // takes the PLAYER and both live on the run.
  function syncPlayer(p, dt, rampageT = 0, buffs = null) {
    playerC.position.set(p.x, p.y)

    // v5.11 kaiju redesign, generalised (undertow): swap the whole body/flash/shadow onto the
    // active chapter's dedicated bake (playerForm) and back onto the generic cross-chapter blob for
    // every chapter that declares no form — same texture-swap-if-changed idiom pRampageGlow uses
    // below. The anchor travels WITH the texture (bake()'s own {ax,ay}) since a dedicated
    // silhouette isn't centred the way the round blob is; guard on pBody alone (all three always
    // swap together) to keep this a single check.
    if (playerForm === 'kaiju') {
      if (pBody.texture !== T.kaijuBody.tex) {
        pBody.texture = T.kaijuBody.tex; pBody.anchor.set(T.kaijuBody.ax, T.kaijuBody.ay)
        pFlash.texture = T.kaijuFlash.tex; pFlash.anchor.set(T.kaijuFlash.ax, T.kaijuFlash.ay)
        pHot.texture = T.kaijuFlash.tex; pHot.anchor.set(T.kaijuFlash.ax, T.kaijuFlash.ay)
        pShadow.texture = T.kaijuShadow.tex; pShadow.anchor.set(T.kaijuShadow.ax, T.kaijuShadow.ay)
      }
      // the region's ONE light direction (SKIES_SHADOW), scaled off the shadow's own reference
      // size (SKIES_KAIJU.shadowRx), instead of the generic blob's small straight-down disc (the
      // generic branch below, unchanged). +20 nudges it toward the tail/hip so it settles under the
      // creature's mass rather than dead-centre.
      const shOff = SKIES_KAIJU.shadowRx * SKIES_KAIJU.bodyScale
      pShadow.position.set(SKIES_SHADOW.dx * shOff, SKIES_SHADOW.dy * shOff + 20 * SKIES_KAIJU.bodyScale)
    } else if (playerForm === 'fish') {
      // Book 2's fish (drawFish, near drawKaijuBody above): FISH_PHASES baked swim frames, flipped
      // through on animT — the same speed (`animT * 10`) syncEnemies uses for the centipede's
      // ROSTER_LOOKS phases, so the two share a cadence. syncEnemies keys its flip off a per-sprite
      // `_animFrame` because a pack must not swim in lockstep; the player rig has no such per-entity
      // state (there's only ever one), so the frame is picked directly here. A plain straight-down
      // shadow like the generic blob's — this chapter has no light direction of its own the way
      // SKIES_SHADOW gives skies.
      const wIdx = Math.floor(animT * 10) % FISH_PHASES
      const wBody = T.fishBody[wIdx], wFlash = T.fishFlash[wIdx]
      if (pBody.texture !== wBody.tex) {
        pBody.texture = wBody.tex; pBody.anchor.set(wBody.ax, wBody.ay)
        pFlash.texture = wFlash.tex; pFlash.anchor.set(wFlash.ax, wFlash.ay)
        pHot.texture = wFlash.tex; pHot.anchor.set(wFlash.ax, wFlash.ay)
        pShadow.texture = T.fishShadow.tex; pShadow.anchor.set(T.fishShadow.ax, T.fishShadow.ay)
      }
      pShadow.position.set(0, PLAYER.radius * 0.95)
    } else {
      // STILLNESS picks a rung of the morph ladder; rung 0 IS the plain body, so a run without the
      // card takes exactly the old texture. Compared against the CHOSEN look rather than against
      // T.playerBody — the old guard would have seen a morphed body as "not the base" and reset it
      // to round on the very next frame, every frame.
      const rung = buffs && buffs.still > 0
        ? Math.min(STILL_STEPS - 1, Math.round(buffs.still * (STILL_STEPS - 1)))
        : 0
      const bodyLook = rung > 0 ? T.playerStill[rung] : T.playerBody
      const flashLook = rung > 0 ? T.playerStillFlash[rung] : T.playerFlash
      if (pBody.texture !== bodyLook.tex) {
        pBody.texture = bodyLook.tex; pBody.anchor.set(bodyLook.ax, bodyLook.ay)
      }
      // pFlash and pHot both wear the silhouette of whatever shape the body currently is
      if (pFlash.texture !== flashLook.tex) {
        pFlash.texture = flashLook.tex; pFlash.anchor.set(flashLook.ax, flashLook.ay)
        pHot.texture = flashLook.tex; pHot.anchor.set(flashLook.ax, flashLook.ay)
        pShadow.texture = T.playerShadow.tex; pShadow.anchor.set(T.playerShadow.ax, T.playerShadow.ay)
      }
      pShadow.position.set(0, PLAYER.radius * 0.95)
    }

    // per-chapter blob tint (white = identity for body) + optional tail. The kaiju AND fish bakes
    // both carry their OWN final palette rather than a tint-multiplied base — same "plans carry
    // their own palette, tint bypassed" rule the top-down structure bakes use (STRUCTURE_SKINS'
    // topDown entries set clumpA.tint = 0xffffff, above) — otherwise a uniform multiply by
    // playerTint (0x7ad07a for skies, 0xffffff for surf) would push the kaiju's
    // pale sclera or the fish's fin and gill highlights toward the same hue as the body fill, right
    // when that contrast matters most.
    pBody.tint = (playerForm === 'kaiju' || playerForm === 'fish') ? 0xffffff : chapterRender.playerTint
    // BERSERK (v7.14): the skin runs hot while the window is open. Strongest on the frame you are
    // hit and fading with _berserkT, so the wash IS the timer — no chrome, nothing to read.
    // An alpha-blended red silhouette, NOT a tint on pBody: see pHot's own note at the rig.
    pHot.tint = BERSERK_TINT
    pHot.alpha = buffs
      ? BERSERK_TINT_MAX * Math.min(1, buffs.berserk / BERSERK_TINT_TAIL)
      : 0
    if (chapterRender.tail) {
      pTail.visible = true
      if (playerForm === 'kaiju') {
        // the articulated kaiju tail (T.kaijuTailSeg): three CHAINED segments, each rooted at the
        // previous one's tip (not all fanned from one point the way the generic flagellum's tailA/
        // tailB share pTail's own origin below) — see T.kaijuTailSeg's own comment.
        const K = SKIES_KAIJU
        if (dt > 0) kaijuSwipeT = Math.max(0, kaijuSwipeT - dt / K.swipeDecay)
        const kick = kaijuSwipeT
        // `ang` (facing + PI, the REAR direction) uses the SAME 0-fallback as bodyC's own rotation
        // above, so the tail's root and the body's actual rear always agree — the root offset
        // rotates with it too (K.tail.rootY away from centre, in the rear direction), instead of a
        // fixed straight-down offset that only matched the body's rear when facing was also "down".
        const ang = (p.facingAngle == null ? 0 : p.facingAngle) + Math.PI // trail behind
        pTail.position.set(Math.cos(ang) * K.tail.rootY, Math.sin(ang) * K.tail.rootY)
        // TAIL SWIPE WHIP: a faster, wider base sway right when the `tail` event fires (kick decays
        // to 0 over K.swipeDecay), so the weapon's own limb visibly cracks, not just spawnWhip's arc.
        pTail.rotation = ang + Math.sin(animT * (9 + kick * 9)) * (0.32 + kick * 0.85)
        if (tailA.texture !== T.kaijuTailSeg.tex) {
          for (const t of [tailA, tailB, tailC]) { t.texture = T.kaijuTailSeg.tex; t.anchor.set(0, 0.5) }
        }
        tailA.visible = tailB.visible = tailC.visible = true
        // T.kaijuTailSeg carries its own final palette (a shade darker than the body — see its own
        // comment), so — like pBody above — the sprite tint is bypassed rather than multiplying
        // chapterRender.tailTint on top of an already-final colour.
        tailA.tint = tailB.tint = tailC.tint = 0xffffff
        const ref = T.kaijuTailSeg.ref
        tailA.scale.set(K.tail.lenA / ref)
        tailA.rotation = 0
        tailA.position.set(0, 0)
        const rotB = Math.sin(animT * 9 + 1.1) * (0.22 + kick * 0.5)
        tailB.scale.set(K.tail.lenB / ref)
        tailB.rotation = rotB
        tailB.position.set(K.tail.lenA, 0)
        const rotC = rotB + Math.sin(animT * 9 + 2.3) * (0.30 + kick * 0.7)
        tailC.scale.set(K.tail.lenC / ref)
        tailC.rotation = rotC
        tailC.position.set(K.tail.lenA + Math.cos(rotB) * K.tail.lenB, Math.sin(rotB) * K.tail.lenB)
      } else {
        // flagellum tail (pond/undergrowth, unchanged): two stacked streak glyphs behind the blob.
        // Restores T.fx.trace_05 explicitly (harmless no-op unless a PRIOR run this session was
        // skies — see the kaiju branch above swapping tailA/B/C onto T.kaijuTailSeg instead).
        pTail.position.set(0, 0)
        const ang = (p.facingAngle == null ? Math.PI * 0.5 : p.facingAngle) + Math.PI // trail behind
        pTail.rotation = ang + Math.sin(animT * 9) * 0.35 // wiggle
        const sc = fxScale(T.fx.trace_05, PLAYER.radius * 1.6)
        if (tailA.texture !== T.fx.trace_05) { tailA.anchor.set(0.04, 0.5); tailB.anchor.set(0.04, 0.5) }
        tailA.texture = T.fx.trace_05
        tailB.texture = T.fx.trace_05
        const tint = chapterRender.tailTint ?? 0x66e0d0
        tailA.tint = tailB.tint = tint
        tailA.scale.set(sc, sc * 0.5)
        tailB.scale.set(sc * 0.9, sc * 0.42)
        tailB.rotation = Math.sin(animT * 9 + 1.2) * 0.25 // secondary flutter on the far segment
        tailC.visible = false // v5.11: the kaiju rig's third chain link only — never shown here
      }
    } else {
      pTail.visible = false
    }

    // v5.8 kaiju redesign: RAMPAGE glow (see pRampageGlow's doc above). Ramped by rampageT /
    // RAMPAGE_DURATION so it's brightest right after triggering (handleEvents' shake pulse lands
    // the same frame) and fades out in step with the buff's own countdown — sim.js's stepRampage
    // drains run.rampage to 0 across that identical window, so the glow and the meter bar (ui.js)
    // hit zero together. A fast pulse on top keeps it reading as "active" rather than a static tint;
    // the storm overlay and lightning flash already own full-field white (see LIGHTNING.flash), so
    // this stays a warm, player-local halo instead of competing for the same visual register.
    if (rampageT > 0) {
      // T.rampageBloom (v5.10.1: was the bare Kenney T.fx.circle_05 — the same particle geyser
      // bubbles, conduct arcs and traffic exhaust all reuse verbatim; the chapter's largest sustained
      // effect gets its own hand-authored bake instead of sharing that literal asset).
      if (pRampageGlow.texture !== T.rampageBloom) pRampageGlow.texture = T.rampageBloom
      const frac = Math.min(1, rampageT / RAMPAGE_DURATION)
      const pulse = 0.75 + 0.25 * Math.sin(animT * 10)
      pRampageGlow.visible = true
      // v5.10 palette law 2: ATOMIC CYAN-GREEN IS THE PLAYER AND IS NEVER A THREAT. The old warm
      // orange sat directly on artillery's fireball; cyan is now yours alone, learned in one run.
      pRampageGlow.tint = SKIES_FX.rampage.bloom
      // spec §1.3's paired rule: the full-field flash and the rampage bloom NEVER co-render
      const suppressed = lightningFlashA > SKIES_FLASH.bloomCutoff
      pRampageGlow.alpha = suppressed ? 0 : 0.55 * frac * pulse
      // v5.11: scaled up again for the kaiju's own bigger silhouette — sized off PLAYER.radius like
      // before, this used to be a halo well outside the OLD ~44px body; against the new one it would
      // read as swallowed inside it instead of surrounding it.
      const glowMul = playerForm === 'kaiju' ? SKIES_KAIJU.bloomScale : 1
      pRampageGlow.scale.set(fxScale(T.rampageBloom, PLAYER.radius * (2.6 + 0.3 * pulse) * glowMul))
    } else {
      pRampageGlow.visible = false
    }

    if (dt > 0) {
      if (p.moving) hop += dt * 11
      else breathe += dt * 2.4
    }
    let sx, sy, by
    if (p.moving) {
      const w = Math.sin(hop)
      sx = 1 + 0.07 * w
      sy = 1 - 0.07 * w
      by = -Math.abs(Math.sin(hop)) * 4.5
    } else {
      const w = Math.sin(breathe)
      sx = 1 - 0.025 * w
      sy = 1 + 0.035 * w
      by = 0
    }
    if (playerForm === 'kaiju') {
      // v5.11: the kaiju body ROTATES to face p.facingAngle instead of just flipping L/R — a
      // directional silhouette (head, jaw, limbs, a tail rooted at the rear) needs an actual
      // facing, unlike the round symmetric blob every other chapter's flip-only rig was built for.
      // drawKaijuBody draws the head pointing local "up" (-y); + PI/2 is the fixed offset that
      // turns "up" into "facingAngle" once rotated (see this block's own tail comment below for the
      // same rotation applied to where the tail ROOTS). No p.facing flip: rotation alone now
      // supplies the facing, and the silhouette is symmetric enough (deliberately) that a flip on
      // top would only double-transform, not add anything a rotation doesn't already give it.
      // v5.11: x SKIES_KAIJU.bodyScale — the one knob that resizes the whole creature (see that
      // field's comment in config.js). It lives on the CONTAINER so body, flash, dorsal plates and
      // the three-segment tail chain all scale together; scaling the sprites individually would
      // leave the tail rooted at an unscaled hip offset.
      bodyC.scale.set(sx * SKIES_KAIJU.bodyScale, sy * SKIES_KAIJU.bodyScale)
      bodyC.rotation = (p.facingAngle == null ? 0 : p.facingAngle) + Math.PI / 2
    } else if (playerForm === 'fish') {
      // drawFish's nose already sits at local +x (spine(t) runs noseX -> noseX - len, the same
      // "head at +x" convention drawCentipede uses for the enemy version) — unlike the kaiju's -y
      // head this needs no rotation offset at all, facingAngle points it directly. No bodyScale
      // knob either: the fish is drawn at its final on-screen size, same as the kaiju bake, but
      // without a chapter-wide resize multiplier to go with it.
      // "You grow in each chapter" (the book's arc) is THIS number and nothing else — one bake,
      // scaled per chapter by CHAPTERS[].render.formScale, defaulting to 1 for The Surf.
      bodyC.scale.set(sx * formScale, sy * formScale)
      bodyC.rotation = p.facingAngle == null ? 0 : p.facingAngle
    } else {
      bodyC.scale.set(p.facing * sx, sy)
      bodyC.rotation = 0   // restores the flip-only rig's implicit "never rotates" if a PRIOR run
                           // this session drew a rotating form (kaiju/fish rotate bodyC above)
    }
    bodyC.y = by
    // The shadow is a sibling of bodyC, not a child, so it needs the same bodyScale applied by hand
    // — otherwise shrinking the kaiju would leave it standing on its old, much larger shadow.
    const shadowSquash = 1 - 0.12 * Math.abs(Math.sin(hop)) * (p.moving ? 1 : 0)
    pShadow.scale.set(playerForm === 'kaiju' ? shadowSquash * SKIES_KAIJU.bodyScale
      : playerForm === 'fish' ? shadowSquash * formScale : shadowSquash)

    // pupil tracking (local +x flips with the body toward facing)
    if (playerForm === 'kaiju') {
      // bigger head, further-set eyes (drawKaijuBody's sclera circles, radius 13 at ±22,-96) — same
      // tracking motion, just rescaled off the kaiju's own eye geometry instead of PLAYER.radius.
      const eyeR = 13, eyeOffX = 22, eyeOffY = -96
      const pupilScale = (eyeR * 0.5) / (PLAYER.radius * 0.115)
      pupilL.scale.set(pupilScale)
      pupilR.scale.set(pupilScale)
      const lookX = p.moving ? eyeR * 0.5 : Math.sin(animT * 0.9) * eyeR * 0.32
      const lookY = eyeR * 0.15 + Math.sin(animT * 1.3) * eyeR * 0.1
      pupilL.position.set(-eyeOffX + lookX, eyeOffY + lookY)
      pupilR.position.set(eyeOffX + lookX, eyeOffY + lookY)
    } else if (playerForm === 'fish') {
      // the eyes are baked straight into drawFish (like drawCentipede's enemy version below it) —
      // no live tracking pupil the way the round blob and the kaiju's sclera-and-pupil eyes get.
      pupilL.scale.set(0)
      pupilR.scale.set(0)
    } else {
      pupilL.scale.set(1)
      pupilR.scale.set(1)
      const pr = PLAYER.radius
      const lookX = p.moving ? pr * 0.07 : Math.sin(animT * 0.9) * pr * 0.045
      const lookY = pr * 0.02 + Math.sin(animT * 1.3) * pr * 0.015
      pupilL.position.set(-pr * 0.36 + lookX, -pr * 0.16 + lookY)
      pupilR.position.set(pr * 0.36 + lookX, -pr * 0.16 + lookY)
    }

    // hurt flash: white pop then red fade
    if (flashT > 0) {
      if (dt > 0) flashT = Math.max(0, flashT - dt)
      if (flashT > 0.2) {
        pFlash.tint = 0xffffff
        pFlash.alpha = 0.9
      } else {
        pFlash.tint = 0xff4d5e
        pFlash.alpha = (flashT / 0.2) * 0.45
      }
    } else {
      pFlash.alpha = 0
    }

    // invuln blink
    playerC.alpha = p.invuln > 0 ? (Math.sin(animT * 32) > 0 ? 1 : 0.4) : 1
  }

  // Elite affix badges: small Text icons floating above an elite's sprite, one per
  // affix id (side by side when there's 2). Pooled/cached on the enemy sprite slot
  // itself (s._affixTexts), same lifetime as that slot (survives enemy-id recycling
  // via enemyFree, just like s._frostT etc. above) — texts live in affixLayer, not
  // as Sprite children, so they don't inherit the enemy's tint/rotation/flip.
  const AFFIX_BADGE_SPACING = 15
  function syncAffixBadges(s, e) {
    // Elites only: affixes on a non-elite are internal plumbing (the blank's Antibody carries
    // 'anchored' purely for knockback immunity), not a badge to advertise.
    const affixes = e.elite ? e.affixes : null
    const n = affixes ? affixes.length : 0
    if (!s._affixTexts) s._affixTexts = []
    while (s._affixTexts.length < n) {
      const t = new Text({
        text: '',
        style: { fontFamily: 'Trebuchet MS, Verdana, sans-serif', fontSize: 14 },
      })
      t.anchor.set(0.5)
      affixLayer.addChild(t)
      s._affixTexts.push(t)
    }
    const baseX = e.x - ((n - 1) * AFFIX_BADGE_SPACING) / 2
    const y = e.y - e.radius - 14
    for (let i = 0; i < s._affixTexts.length; i++) {
      const t = s._affixTexts[i]
      if (i < n) {
        const info = ELITE_AFFIXES[affixes[i]]
        t.text = info ? info.icon : '?'
        t.position.set(baseX + i * AFFIX_BADGE_SPACING, y)
        t.visible = true
      } else {
        t.visible = false
      }
    }
  }
  function hideAffixBadges(s) {
    if (!s._affixTexts) return
    for (const t of s._affixTexts) t.visible = false
  }

  // The enemy's shadow and crown, which no longer ride inside its texture (see groundShadow/
  // eliteCrown in the art section). They ride ALONGSIDE it instead: same world position, same
  // scale `k` (= radius ratio × holePull shrink), same alpha — but rotation 0, always.
  // Lifetime is the pooled enemy sprite's: created lazily on the slot, hidden by hideEnemyDecor()
  // everywhere the slot is released (the syncEnemies sweep and clearWorld), so a recycled id can
  // never inherit the previous occupant's crown. `look` changes under a slot when an enemy is
  // recycled, so the crown texture is re-latched off it every frame, not just on creation.
  function syncEnemyDecor(s, e, look, k, flash) {
    const sh = look.shadow
    if (sh) {
      if (!s._shadow) {
        s._shadow = spriteOf(T.enemyShadow)
        enemyShadowLayer.addChild(s._shadow)
      }
      s._shadow.visible = true
      s._shadow.position.set(e.x, e.y + sh.y * k)
      s._shadow.scale.set((sh.rx / SHADOW_TEX_R) * k, (sh.ry / SHADOW_TEX_R) * k)
      s._shadow.alpha = s.alpha
    } else if (s._shadow) s._shadow.visible = false
    // crown: elite-only, so look.crown is null for the rest and this whole branch never runs.
    // No tint — a hit-flash swaps to the white twin like the body does, and the elemental tints
    // multiplied a gold crown into mud anyway back when it was baked in.
    const cr = look.crown
    if (cr) {
      const ct = crownLook(cr.r)
      if (!s._crown) {
        s._crown = new Sprite(Texture.EMPTY)
        enemyCrownLayer.addChild(s._crown)
      }
      const tex = flash ? ct.white : ct.tex
      if (s._crown.texture !== tex) s._crown.texture = tex
      s._crown.anchor.set(ct.ax, ct.ay)
      s._crown.visible = true
      s._crown.position.set(e.x, e.y + cr.top * k)
      s._crown.scale.set(k)
      s._crown.alpha = s.alpha
    } else if (s._crown) s._crown.visible = false
  }
  function hideEnemyDecor(s) {
    if (s._shadow) s._shadow.visible = false
    if (s._crown) s._crown.visible = false
  }

  // Volatile bomb telegraphs (run.bombs): danger circles under enemies/player, urgency
  // (fill alpha, rim strength, pulse rate) ramping up as fuse -> 0. One shared Graphics
  // cleared/redrawn per frame, same pattern as arcG/redrawArcs above.
  // v5.10 (kill list §8.3): this drew artillery and sky bombardment IDENTICALLY, because run.bombs
  // carried no discriminator — one drawer, one colour, two completely different threats.
  // v5.10.1: they now go through three SEPARATE drawers (drawSkiesBombs above), and the source is
  // an explicit `b.src` stamped by sim at the push site (sim.js/1589/1826), NOT inferred from
  // `duration` as the first pass did. That inference is why volatile-elite corpses used to fall
  // through to the red circle below AND detonate as the sky's signature bolt — an elite's death was
  // indistinguishable from a lightning strike, in the one chapter built around telling the sky apart
  // from the guns. Only bombs with no `src` at all — i.e. every OTHER chapter's — reach the red
  // circle now; in skies, all three sources are claimed by drawSkiesBombs.
  function redrawBombs(run) {
    bombG.clear()
    for (const b of run.bombs || []) {
      if (bombSrc(b) !== null) continue
      const urgency = b.duration > 0 ? 1 - b.fuse / b.duration : 1
      const pulse = 0.5 + 0.5 * Math.sin(animT * (5 + urgency * 16))
      // v6.7.5: same pass as redrawLanes. Nothing is removed here — a fill and a rim is already the
      // minimum that says "circle, and it is filling up" — so this is volume only: the rim was
      // reaching a solid alpha 1.0 at width 5, the single loudest stroke left in the game once the
      // lanes came down. It is not the thing the owner named, but leaving it at full blast while
      // its neighbours halve would just make IT the new loudest telegraph.
      const fillA = Math.min(0.2, 0.08 + urgency * 0.1 + pulse * 0.03)
      const rimA = Math.min(0.8, 0.35 + urgency * 0.35 + pulse * 0.08)
      // v5.24 the blank (src:'trail' — the Antibody detonating your own recorded path): same
      // urgency ramp, but violet. The warm red above was tuned against dark floors and washes out
      // on the white void; the violet is the player's own hue — it IS your trail coming back.
      // THE SURF'S GULLS (src:'gull') get a SHADOW, not a danger circle — owner's brief is "a
      // telegraph seagull shadow that gets bigger and darker as the seagull plunges towards you".
      // It is deliberately not the red rim every other hazard wears: this threat is not the beach
      // warning you, it is a bird you can see coming, and a shadow is the only telegraph in the game
      // that is also a diegetic object. Physically a descending bird's shadow would SHRINK and
      // sharpen; the owner asked for bigger-and-darker and that is the right call for a game — the
      // growth is what says "filling up", and a shrinking telegraph reads as a threat receding.
      if (b.src === 'gull') {
        drawGullShadow(b, urgency)
        continue
      }
      const color = b.src === 'trail' ? 0x8a5fe0 : 0xff6b81
      bombG.circle(b.x, b.y, b.radius).fill({ color, alpha: fillA })
      bombG.circle(b.x, b.y, b.radius).stroke({ width: 1.5 + urgency * 1.5, color, alpha: rimA })
    }
    if (chapterHasStorm) drawSkiesBombs(run)
    else clearSkiesBombs()
  }

  // ---- The Surf's gull hazard (v7.x) -----------------------------------------------------------
  // THE TELEGRAPH: the bird's own shadow on the sand, growing and darkening as it drops. It is the
  // only telegraph in the game that is a diegetic object rather than a warning, so it carries no
  // rim, no pulse and no colour that sand cannot make — everything that would make it read as UI.
  // Three properties do the work instead:
  //   PLANFORM — a real gull from above: a curved leading edge, a notched trailing edge, a head in
  //     front of the wings and a forked tail behind. The old cut was two straight-edged triangles
  //     and an ellipse, which reads as a bat, or as a paper dart, or as nothing.
  //   THE BEAT — the wings flap while the bird is still high and LOCK SWEPT BACK as it commits, so
  //     the SHAPE tells you how long you have, independently of size and darkness. From overhead a
  //     raised wing simply projects shorter, so the beat is a span modulation and nothing else moves.
  //   PENUMBRA — a cast shadow has a soft edge that TIGHTENS as the caster nears the ground. Four
  //     nested fills at falling alpha do it; the halo is wide and faint at the top of the dive and
  //     collapses onto a hard core at the bottom. That sharpening is a second clock on the same
  //     event, and it is the part that makes the shape feel like it is coming down rather than
  //     merely being scaled up.
  // Physically a descending bird's shadow SHRINKS. The owner asked for bigger-and-darker and that is
  // the right call for a game: growth is what says "filling up", and a shrinking telegraph reads as
  // a threat receding.
  const GULL_SHADOW_INK = 0x2a2114
  const GULL_SHADOW_LAYERS = [[0.34, 0.13], [0.20, 0.28], [0.09, 0.52], [0, 1]]
  // Half of the planform, nose to tail, on the +y side, in units of R. `sweep` folds the wings back
  // along the body (1 = a stoop), `span` foreshortens them (the wingbeat, seen from above).
  function gullPlanformHalf(sweep, span) {
    const tip = [-0.30 - 0.46 * sweep, 0.98 * span]
    const shoulder = [0.34, 0.10]
    const ctrl = [0.30 - 0.30 * sweep, 0.60 * span]        // leading edge bows FORWARD
    const half = [[0.66, 0], shoulder]
    for (let i = 1; i <= 6; i++) {                         // quadratic leading edge
      const u = i / 6, v = 1 - u
      half.push([v * v * shoulder[0] + 2 * v * u * ctrl[0] + u * u * tip[0],
        v * v * shoulder[1] + 2 * v * u * ctrl[1] + u * u * tip[1]])
    }
    half.push([-0.26 - 0.24 * sweep, 0.46 * span])         // the notch in the trailing edge
    half.push([-0.18, 0.13])                               // wing root, trailing
    half.push([-0.48, 0.17])                               // tail, forked
    half.push([-0.78, 0.11])
    half.push([-0.64, 0])
    return half
  }
  function drawGullShadow(b, urgency) {
    // Committed to the stoop over the second half of the fuse: wings fold, the beat stops.
    const stoop = Math.max(0, (urgency - 0.42) / 0.58)
    const sweep = stoop * stoop * 0.9
    const beat = 1 - stoop
    const phase = (b.x * 0.031 + b.y * 0.027) % 1
    const span = 1 - beat * 0.34 * (1 - Math.abs(Math.cos(animT * 4.6 + phase * 6.283)))
    const rot = ((b.x * 0.013 + b.y * 0.011) % 1) * Math.PI * 2
    const cs = Math.cos(rot), sn = Math.sin(rot)
    const R = b.radius * (0.34 + 0.66 * urgency)
    const ink = 0.07 + 0.30 * urgency
    const soft = 1.30 - 0.78 * urgency                     // the penumbra tightens as it drops
    const half = gullPlanformHalf(sweep, span)
    for (const [spread, aMul] of GULL_SHADOW_LAYERS) {
      const k = R * (1 + spread * soft)
      const pts = []
      for (const [x, y] of half) pts.push(b.x + (x * k) * cs - (y * k) * sn, b.y + (x * k) * sn + (y * k) * cs)
      for (let i = half.length - 2; i >= 1; i--) {
        const [x, y] = half[i]
        pts.push(b.x + (x * k) * cs + (y * k) * sn, b.y + (x * k) * sn - (y * k) * cs)
      }
      bombG.poly(pts).fill({ color: GULL_SHADOW_INK, alpha: ink * aMul })
    }
  }

  // ---- The Surf's gull strike (v7.x) ----------------------------------------------------------
  // THE PAYOFF: the bird itself. A gull is a HAZARD, not an enemy (sim: stepGullStrike -> run.bombs
  // with src:'gull'), so it has no entity to sync and no sprite pool of its own. What it needs is
  // one short animation at the moment of impact — the bird is already at the ground when this fires,
  // because the shadow carried the whole descent, so this is "hit and gone" and not the dive.
  //
  // GROWING = CLOSER, because the camera is overhead: a bird climbing away from the ground SHRINKS.
  // That is the one cue that makes an overhead bird read as vertical motion at all, and it is why
  // the sprite scales DOWN here while the telegraph shadow scales UP. Two more carry it with that:
  //   ITS OWN SHADOW, left lagging on the sand and shrinking behind it. A plan view has no horizon,
  //     so the gap opening between a body and its shadow is the only way to say "off the ground".
  //   A WINGBEAT. Three baked poses — the stoop it arrives in (wings folded, feet thrown forward),
  //     then a downstroke/upstroke pair alternating at ~4.5Hz. A bird that left on one fixed pose
  //     read as a sprite being tweened away, which is what the first cut did.
  // Baked at GULL_DIVE_R (not scaled up off the 12px roster gull, whose texture at the size this
  // wants is a 6x magnification and visibly soft), so every frame of this is a DOWNSCALE.
  function drawGullPose(g, r, sweep, span, feet, white) {
    const f = (c) => white ? 0xffffff : c
    const line = f(0xa8ada4)
    const half = gullPlanformHalf(sweep, span)
    // FEET first, under everything: two orange legs thrown forward past the head with the toes
    // splayed. Only the stoop wears them, and they are most of why that pose reads as a STRIKE
    // rather than as a gull that happens to be narrow.
    if (feet) {
      for (const sd of [-1, 1]) {
        const hx = r * 1.15, hy = sd * r * 0.42
        taperStroke(g, [[r * 0.30, sd * r * 0.16], [r * 0.80, sd * r * 0.34], [hx, hy]], r * 0.11, r * 0.07, f(0xdd9a2c), 3)
        for (const t of [-0.5, 0, 0.5]) {
          taperStroke(g, [[hx, hy], [hx + r * 0.34 * Math.cos(t + sd * 0.25), hy + r * 0.34 * Math.sin(t + sd * 0.25)]],
            r * 0.06, r * 0.03, f(0xe8a83c), 2)
        }
      }
    }
    // WINGS. Drawn as the planform's own outline so the shadow and the bird are literally the same
    // shape — the thing that landed is the thing you were watching.
    for (const sd of [-1, 1]) {
      const pts = []
      for (const [x, y] of half) pts.push(x * r * 2.5, sd * y * r * 2.5)
      // close the half back along the body centreline
      pts.push(-r * 1.6, 0)
      g.poly(pts).fill(f(0xf4f2ea)).stroke({ width: Math.max(1.6, r * 0.055), color: line })
      if (!white) {
        // dark primaries: the outer third of the wing, over-painted. It is the one hard value break
        // on a near-white bird over pale sand, and without it the whole silhouette dissolves.
        const outer = half.slice(4, 10).map(([x, y]) => [x * r * 2.5, sd * y * r * 2.5])
        g.poly(outer.flat()).fill({ color: 0x33373a, alpha: 0.9 })
      }
    }
    // BODY over the wing roots — a torpedo, nose +x, so the two wings read as attached to it.
    g.poly(spineOutline((t) => [r * 1.05 - t * r * 2.35, 0],
      (t) => r * 0.30 * bulge(Math.min(0.999, Math.max(0.001, t)), t < 0.4 ? 0.4 : 0.7), 26))
      .fill(f(0xfaf9f4)).stroke({ width: Math.max(1.6, r * 0.06), color: line })
    if (!white) {
      g.ellipse(r * 0.24, 0, r * 0.42, r * 0.15).fill({ color: 0xffffff, alpha: 0.5 })
      darkEye(g, r * 0.74, -r * 0.09, r * 0.075, r * 0.07, 0x191b1c, true)
      darkEye(g, r * 0.74, r * 0.09, r * 0.075, r * 0.07, 0x191b1c, false)
    }
    taperStroke(g, [[r * 0.96, 0], [r * 1.34, 0]], r * 0.08, r * 0.03, f(0xd8a23a), 3) // beak
  }
  // ---- SPLASH RINGS (v7.x, The Surf) -----------------------------------------------------------
  // Rings on the water surface, spreading and fading. Drawn into one Graphics rather than pooled as
  // sprites for the same reason the swell and the Breaker's crest are: there is no ring texture in
  // src/fx (circle_05 is a filled blob), and fxScale stretches a texture's transparent margin along
  // with its ink, so a soft disc scaled to a thin annulus is mostly nothing — the failure the swell's
  // own block records after a sprite version reported 34/34 crests drawing and was invisible.
  //
  // World-space, so it scrolls with the beach it is on. See SPLASH_VIS for why the rings are
  // staggered and why they ease out.
  const splashes = []
  function spawnSplash(x, y, radius, opt) {
    splashes.push({
      x, y, radius, t: 0,
      life: (opt?.life ?? SPLASH_VIS.life) + SPLASH_VIS.stagger * (opt?.rings ?? SPLASH_VIS.rings),
      rings: opt?.rings ?? SPLASH_VIS.rings,
      alpha: opt?.alpha ?? SPLASH_VIS.alpha,
      crown: opt?.crown ?? true,
      ringLife: opt?.life ?? SPLASH_VIS.life,
    })
  }

  // THE PLAYER'S WAKE. Ripples left where the body just was, emitted per DISTANCE rather than per
  // second (see WAKE_VIS): standing still leaves nothing, which is both true and what stops a
  // stationary player from disappearing under their own rings.
  //
  // One ring and no crown — a crown is water thrown UP, which is what an impact does and swimming
  // does not. This is the same drawing code as a gull hitting the surface, four times fainter and
  // with the violent parts turned off, which is the honest relationship between the two events.
  let wakeOn = false
  let wakeAcc = 0
  let wakeX = null, wakeY = null
  function updateWake(px, py) {
    if (!wakeOn) return
    if (wakeX === null) { wakeX = px; wakeY = py; return }
    const d = Math.hypot(px - wakeX, py - wakeY)
    // A teleport (a run starting, the Blank's yank) must not fill the beach with a line of rings.
    if (d > 400) { wakeX = px; wakeY = py; wakeAcc = 0; return }
    wakeAcc += d
    wakeX = px; wakeY = py
    if (wakeAcc < WAKE_VIS.every) return
    wakeAcc = 0
    spawnSplash(px, py, WAKE_VIS.r, { rings: 1, crown: false, life: WAKE_VIS.life, alpha: WAKE_VIS.alpha })
  }
  function stepSplashes(dt) {
    splashG.clear()
    if (!splashes.length) return
    const V = SPLASH_VIS
    for (let i = splashes.length - 1; i >= 0; i--) {
      const s = splashes[i]
      s.t += dt
      if (s.t >= s.life) { splashes.splice(i, 1); continue }
      // The crown: the water thrown straight up at the point of contact, gone almost at once. It is
      // what stops the rings reading as having appeared from nothing.
      if (s.crown && s.t < V.crownLife) {
        const k = s.t / V.crownLife
        splashG.circle(s.x, s.y, s.radius * (0.30 + 0.55 * k))
        splashG.fill({ color: V.crown, alpha: V.crownA * (1 - k) * (1 - k) })
      }
      for (let r = 0; r < s.rings; r++) {
        const age = s.t - r * V.stagger
        if (age <= 0 || age >= s.ringLife) continue
        const k = age / s.ringLife
        // sqrt: fast at birth, spending itself as it goes. A linear ring reads as a UI pulse.
        const rr = s.radius * (V.r0 + (V.rMax - V.r0) * Math.sqrt(k))
        const fade = (1 - k) * (1 - k)
        splashG.circle(s.x, s.y, rr)
        splashG.stroke({ width: Math.max(0.9, V.width * (1 - k * 0.65)), color: V.color, alpha: s.alpha * fade })
      }
    }
  }

  const gullDives = []
  const gullFree = []
  function gullStrike(x, y, radius) {
    let rec = gullFree.pop()
    if (!rec) {
      rec = { sp: new Sprite(Texture.EMPTY), sh: new Sprite(Texture.EMPTY) }
      rec.sh.anchor.set(0.5)
      // TWO LAYERS, ONE STRIKE, and the split is physical rather than a stacking trick: the shadow
      // lies on the sea floor, so it goes in the world with everything else the water is in front
      // of; the bird is in the air, so it goes in aboveWater and the blue never touches it (see that
      // container's block). Ordering still holds — the world is painted before aboveWater, so the
      // shadow can no more paint over the bird than it could when they were siblings.
      particleLayer.addChild(rec.sh)
      aboveWater.addChild(rec.sp)
    }
    rec.sp.visible = true
    rec.sp.tint = 0xffffff
    rec.sh.visible = true
    rec.sh.tint = GULL_SHADOW_INK
    // A heading it leaves along, derived from the impact point so two strikes do not fly off in
    // lockstep. It banks away rather than straight up: a bird that took off vertically would read
    // as a helicopter.
    const a = ((x * 0.017 + y * 0.013) % 1) * Math.PI * 2
    rec.x = x; rec.y = y
    rec.ca = Math.cos(a); rec.sa = Math.sin(a)
    rec.t = 0; rec.life = 0.55
    // The whole animation is sized off the blast: wingspan 2.3x the radius, i.e. a bird that clearly
    // overhangs the crater it just made. Fixed off the SPREAD pose so the stoop does not appear to
    // shrink the animal when it opens its wings.
    rec.k = (radius * 2.3) / GULL_DIVE_SPAN
    gullDives.push(rec)
    // IT LANDS IN WATER (owner, 2026-08-15). The beach is ankle-deep, so a strike throws water
    // first and the bottom second — the rings and the crown carry the impact (spawnSplash), and what
    // stays here is the spray plus the sand it stirred up off the floor underneath.
    spawnSplash(x, y, radius)
    if (T.fx && T.fx.circle_05) {
      // DROPLETS, thrown clear and slowed hard: water is heavy, so unlike the dry grains this
      // replaced they decelerate rather than skating on. Near-white with the water's blue in it.
      for (let i = 0; i < SPLASH_VIS.drops; i++) {
        const ga = (i / SPLASH_VIS.drops) * Math.PI * 2 + Math.random() * 0.45
        const gv = 190 + Math.random() * 230
        spawnSmoke(T.fx.circle_05, x, y, Math.cos(ga) * gv, Math.sin(ga) * gv,
          0.30 + Math.random() * 0.20, fxScale(T.fx.circle_05, 5 + Math.random() * 7),
          SPLASH_VIS.color, -0.03, 3.4, 0, 0, 1.25)
      }
      // The floor it punched through: fewer, slower, dirtier than the old dry burst, and hanging in
      // the water instead of falling out of the air — stirred sand is the tell that this is SHALLOW.
      for (let i = 0; i < 6; i++) {
        const ga = Math.random() * Math.PI * 2
        spawnSmoke(T.fx.circle_05, x + Math.cos(ga) * radius * 0.30, y + Math.sin(ga) * radius * 0.30,
          Math.cos(ga) * 34, Math.sin(ga) * 34, 0.72, fxScale(T.fx.circle_05, radius * 0.55),
          0xd9c8a6, 0.34, 0.9, 0, 0.45, 0.5)
      }
    }
    addShake(2.6, 0.13)
  }
  // ---- THE SANDBAR BREAKS THE SURFACE (v7.x) ---------------------------------------------------
  // A soft warm light laid over each dry patch, in aboveWater — i.e. AFTER the chapter's blue wash,
  // which is the only place it can undo it. See SANDBAR_VIS.dry for the reasoning; the short version
  // is that a sandbar is the one piece of ground here that is out of the water, and a flat wash over
  // the whole screen has no way to know that.
  //
  // Additive and soft-edged, which makes it a light rather than a patch: it warms whatever is
  // STANDING on the bar as well as the bar itself, so a crab up in the sun is lit like one, and it
  // adds no second hard circle to compete with the rim the mechanic is actually tested against.
  // One pooled sprite per bar, the same acquire-and-hide idiom as every other flat pool here.
  const drySandPool = []
  function syncDrySand(bars) {
    const V = SANDBAR_VIS
    const on = wakeOn && V.dry != null   // same "is this chapter underwater" latch as the caustics
    while (drySandPool.length < bars.length) {
      const s = new Sprite(T.fx.light_01)
      s.anchor.set(0.5)
      s.blendMode = 'add'
      s.tint = V.dry
      aboveWater.addChild(s)
      drySandPool.push(s)
    }
    for (let i = 0; i < drySandPool.length; i++) {
      const s = drySandPool[i]
      const b = on ? bars[i] : null
      s.visible = !!b
      if (!b) continue
      s.position.set(b.x, b.y)
      s.alpha = V.dryA
      s.scale.set(fxScale(s.texture, b.r * V.dryFrac * 2))
    }
  }

  // aboveWater is a STAGE child, so it gets none of the camera transform `world` carries. Copying it
  // here is what lets everything inside be positioned in plain world coordinates, and copying the
  // SCALE as well as the position is what keeps it honest in map mode, where world.scale is mapZoom.
  function syncAboveWater() {
    aboveWater.position.copyFrom(world.position)
    aboveWater.scale.copyFrom(world.scale)
  }
  function stepGullDives(dt) {
    syncAboveWater()
    stepSplashes(dt)
    for (let i = gullDives.length - 1; i >= 0; i--) {
      const d = gullDives[i]
      d.t += dt
      const k = Math.min(1, d.t / d.life)
      if (k >= 1) {
        d.sp.visible = false
        d.sh.visible = false
        gullFree.push(d)
        gullDives.splice(i, 1)
        continue
      }
      // POSE: the stoop it arrives in, then a beat. The first swap is what sells "and immediately
      // took off" — one pose held through the whole exit reads as a decal being tweened.
      const pose = d.t < 0.13 ? 0 : 1 + (Math.floor((d.t - 0.13) / 0.11) % 2)
      const look = T.gullDive[pose]
      if (d.sp.texture !== look.tex) { d.sp.texture = look.tex; d.sp.anchor.set(look.ax, look.ay) }
      if (d.sh.texture !== look.tex) d.sh.texture = look.tex
      // It hangs for a beat on contact and then accelerates out — a bird that started at full speed
      // never looks like it touched anything.
      const off = 620 * Math.pow(Math.max(0, k - 0.06) / 0.94, 1.8)
      const bx = d.x + d.ca * off
      const by = d.y + d.sa * off
      const sc = d.k * (1.06 - 0.62 * k)
      d.sp.scale.set(sc)
      d.sp.position.set(bx, by)
      d.sp.rotation = Math.atan2(d.sa, d.ca)
      d.sp.alpha = k < 0.72 ? 1 : 1 - (k - 0.72) / 0.28
      // Its shadow, left behind ON THE GROUND and shrinking: the gap between the two IS the altitude.
      d.sh.anchor.set(look.ax, look.ay)
      d.sh.scale.set(d.k * (1.0 - 0.72 * k))
      d.sh.position.set(d.x + d.ca * off * 0.42, d.y + d.sa * off * 0.42)
      d.sh.rotation = d.sp.rotation
      d.sh.alpha = 0.34 * (1 - k) * (1 - k)
    }
  }

  function syncEnemies(run) {
    const px = run.player.x
    shieldG.clear()
    pacerG.clear()
    for (const e of run.enemies) {
      let s = enemySprites.get(e.id)
      if (!s) {
        s = enemyFree.pop()
        if (!s) {
          s = new Sprite(Texture.EMPTY)
          enemyLayer.addChild(s)
        }
        s.visible = true
        s._look = null
        // per-status particle cadence timers, kept on the sprite itself (it's the stable
        // per-enemy-id slot, same idea as holeParticleTimers but keyed by id via the Map
        // rather than a flat pool index — enemies don't have one)
        s._frostT = 0
        s._igniteT = 0
        s._venomT = 0
        s._stunT = 0
        s._enrageT = 0
        // v6.4 phase (tardigrade cryptobiosis flicker): last-seen solid/ghost state, so the flip
        // particle below fires on a real transition and not on a recycled slot's first frame.
        s._lastPhaseSolid = undefined
        enemySprites.set(e.id, s)
      }
      s._seen = true
      // prefer the per-rosterId themed silhouette; fall back to the archetype look for enemies
      // whose rosterId has no baked creature (daily/title/future chapters)
      const rkey = e.rosterId ? e.rosterId + (e.elite ? '_elite' : '') : null
      const look = (rkey && T.roster[rkey]) || T.enemies[e.elite ? e.type + '_elite' : e.type]
      // Animated looks (look.frames, e.g. the centipede's baked wave phases): flip through the
      // frames on animT, offset per enemy id so a pack doesn't slither in lockstep. Frozen/stunned
      // creatures HOLD their current pose (matching the wisp-wobble rule below) instead of
      // snapping to frame 0. Anchor rides the texture: each frame bakes its own (near-identical)
      // anchor, and the white twin of the SAME frame shares it, so hit-flash still doesn't jump.
      let frame = look
      if (look.frames) {
        if (look.poseOf) {
          // state-selected (the cat's pounce poses): no timer, no freeze rule — the pose IS the
          // state, so a frozen cat correctly keeps whatever pose it was caught in.
          s._animFrame = Math.min(look.frames.length - 1, Math.max(0, look.poseOf(e) | 0))
        } else {
          const halted = (e.frozen || 0) > 0 || (e.stunT || 0) > 0
          if (!halted || s._animFrame === undefined || s._animFrame >= look.frames.length) {
            s._animFrame = Math.floor(animT * 10 + e.id * 1.7) % look.frames.length
          }
        }
        frame = look.frames[s._animFrame]
      }
      const tex = e.hitFlash > 0 ? frame.white : frame.tex
      if (s._look !== look) s._look = look
      if (s.texture !== tex) {
        s.texture = tex
        s.anchor.set(frame.ax, frame.ay)
      }
      // v5.8 kaiju redesign: chapterRender.enemyDrawScale (skies only, default 1 everywhere else)
      // shrinks the DRAWN size on top of the ordinary radius ratio — jets/helis/tanks read as
      // specks under a kaiju without a single hit test moving. This is the only thing `k` feeds
      // (body scale below + the shadow/crown scale handed to syncEnemyDecor) — e.radius itself,
      // and every hit test that reads it, is untouched. Do NOT thread this into anything that
      // isn't a pure draw dimension (see config.js's enemyDrawScale doc for why rev.1's sim-side
      // `enemyScale` knob was cut).
      const k = (e.radius / look.baseR) * (chapterRender.enemyDrawScale ?? 1)
      // Aim at the player, as far as this creature's VIEW allows (look.maxLean — see ROSTER_LOOKS).
      // The roster mixes three views, so no single bearing->rotation rule serves all of them: the
      // bugs and airframes are true top-down and rotate freely, the animals are 3/4 with a distinct
      // UP that turns upside down if rotated past vertical, and the cells have no forward axis at all.
      // But those are not three code paths — they're one, with a different clamp. Split the bearing
      // into a left/right MIRROR and an ELEVATION: `flip` covers the horizontal half-plane exactly as
      // the pre-v5.6.4 code's `px < e.x ? -1 : 1` did, and `lean` — measured against |dx| so it
      // mirrors along with the body, then clamped to maxLean — tilts the nose up or down toward the
      // player. Together (flip, lean) still spans the whole circle: maxLean = 90deg reproduces full
      // facing exactly, maxLean = 0 collapses to the original pure mirror. The mirror pops at dx = 0,
      // exactly where the original flip popped, so this adds no pop that wasn't already there.
      // Scale runs BEFORE rotation, hence the flip on X.
      //
      // v6.6.33: the bearing that feeds this is no longer unconditionally "toward the player". Two
      // optional look hooks sit in front of it, and every look without them behaves exactly as
      // before (instant, player-facing):
      //   look.faceDir(e)  -> a [dx, dy] the creature should face INSTEAD of the player, or null.
      //                       The toad returns its locked _pounceDir while aiming and leaping.
      //   look.turnRate(e) -> rad/s the body may swing at. Infinity (the default) is the old
      //                       snap-to-bearing; 0 freezes the current facing outright.
      // The smoothed heading lives on the SPRITE, not on `run` — render must never write to the
      // sim, and the sprite is the stable per-enemy slot (same idiom as _spinA/_animFrame above).
      // It is smoothed as a VECTOR and only then split into flip/lean: interpolating the decomposed
      // pair would tear at the mirror boundary, where flip is discontinuous by construction.
      let tdx = px - e.x
      let tdy = run.player.y - e.y
      // SUBMISSION: an ally faces WHAT IT IS FIGHTING, not you. Without this it would draw
      // walking backwards in all 32 roster looks — bearing is derived here from run.player every
      // frame, and look.faceDir is declared per LOOK, so it cannot express "this INSTANCE has a
      // different target". sim publishes the seek point it already computed as _tgtX/_tgtY.
      // Contract field, read guarded (`|| 0` idiom above): the sim half may not have landed.
      if ((e.allyT || 0) > 0 && (e._tgtX !== undefined)) {
        tdx = e._tgtX - e.x
        tdy = e._tgtY - e.y
      }
      if (look.faceDir) {
        const d = look.faceDir(e)
        if (d && (d[0] || d[1])) { tdx = d[0]; tdy = d[1] }
      }
      const tlen = Math.hypot(tdx, tdy) || 1
      tdx /= tlen
      tdy /= tlen
      const rate = look.turnRate ? look.turnRate(e) : Infinity
      if (!(rate < Infinity)) { s._dirX = tdx; s._dirY = tdy }
      else {
        if (s._dirX === undefined) { s._dirX = tdx; s._dirY = tdy }
        // rotate the held heading toward the target by at most rate*dt, shortest way round
        const cur = Math.atan2(s._dirY, s._dirX)
        let diff = Math.atan2(tdy, tdx) - cur
        while (diff > Math.PI) diff -= Math.PI * 2
        while (diff < -Math.PI) diff += Math.PI * 2
        const step = Math.min(Math.abs(diff), rate * frameDt) * Math.sign(diff)
        s._dirX = Math.cos(cur + step)
        s._dirY = Math.sin(cur + step)
      }
      const dx = s._dirX
      const flip = dx < 0 ? -1 : 1
      const maxLean = look.maxLean
      const lean = Math.atan2(s._dirY, Math.abs(dx))
      const face = flip * Math.max(-maxLean, Math.min(maxLean, lean))
      // holePull (0..1, set by sim while an enemy is being sucked into a black hole) may
      // not exist on older/other enemies — guard it. Shrinks + spins the sprite as it nears.
      const pull = e.holePull || 0
      const shrink = 1 - pull * 0.45
      s.scale.set(k * flip * shrink, k * shrink)

      // Elemental status (contract fields, guarded — sim half may not have landed yet).
      const frozen = e.frozen || 0
      const chill = e.chill || 0
      const venom = e.venom || 0
      // The venom DOSE, 0..1: `venom` carries the damage-taken amp, which sim publishes every
      // step. One number, so the tint and the drip particles both scale by how poisoned it is.
      const venomK = Math.min(1, Math.max(0, venom))
      const ignite = e.ignite || 0
      // The Surf's Barnacles. A contract field like the four above, and guarded the same way — a
      // status render.js has not been told about is a weapon that grinds bodies down invisibly.
      const crust = e.barnacle ? Math.max(0, Math.min(1, (e.barnacle.t || 0) / (e.barnacle.dur || 1))) : 0
      // v5.4 behavioural statuses (same guarded-contract rule): enrage = the flashlight cone turned
      // this thing up, stun = it can't act, fear = it's running from you.
      const fear = e.fearT || 0
      const stun = e.stunT || 0
      const enrage = e.enrageT || 0

      // frozen and stun both halt walk/idle animation (here: the wisp's rotation wobble)
      const wobble = (e.type === 'wisp' && frozen <= 0 && stun <= 0) ? Math.sin(animT * 9 + e.id * 1.7) * 0.13 : 0
      // v6.4 pond identity: currents visibly rock the swarm — a small rotation wobble scaled by the
      // LOCAL field strength (flowAt, the same field the sim itself pushes everyone with), so
      // an enemy sitting in an eddy's core rocks harder than one out at the ambient drift's calm
      // spots. Same frozen/stun hold the wisp wobble above already respects — subtle by design, the
      // water rocks the swarm, it doesn't shake it.
      // v7.x: The Surf's tide gets it too, and there it carries more than flavour. stepTide moves
      // the CROWD by the same vector it moves the player, and the design says that is what makes the
      // surge read as weather rather than as a control tax — the crowd rocking on the surge and
      // going still at slack water is what says "the water did that", not "the stick is fighting me".
      let currentWobble = 0
      if (flowKind && frozen <= 0 && stun <= 0) {
        const cf = flowAt(run, e.x, e.y)
        currentWobble = Math.min(1, Math.hypot(cf.fx, cf.fy) / 60) * 0.10 * Math.sin(animT * 4 + e.id)
      }
      // look.spin (the blank's Antibody): slow constant self-rotation for radially-symmetric,
      // lean-0 forms. Accumulated per sprite off animT's delta rather than read as animT*spin,
      // so frozen/stun HOLD the pose (the wisp-wobble rule) and it resumes without snapping.
      if (look.spin) {
        if (s._spinT === undefined) { s._spinT = animT; s._spinA = 0 }
        if (frozen <= 0 && stun <= 0) s._spinA += (animT - s._spinT) * look.spin
        s._spinT = animT
      }
      s.rotation = face + wobble + currentWobble + pull * animT * 5 + (look.spin ? s._spinA : 0)
      s.position.set(e.x, e.y)

      // dominant tint, one status wins (frozen > chill > venom > ignite > none). The
      // hit-flash white silhouette overrides all of these so the hit pop still reads white —
      // except on the void, where white-on-white is invisible: the all-white twin takes any tint
      // verbatim, so ink turns the same bake into a dark silhouette pop (the chapter's inversion).
      if (e.hitFlash > 0) s.tint = chapterIsVoid ? (chapterRender.ink ?? 0xffffff) : 0xffffff
      else if (frozen > 0) s.tint = 0x9fd8ff
      else if (chill > 0) s.tint = 0xc4e4ff
      // venom ramps with the dose: a flat tint made "a bit poisoned" and "about to melt" look
      // identical. The LOW end is deliberately the old flat value — a ramp starting near white
      // reads as no tint at all on the first stack, which is the very complaint this fixes — so
      // the ramp only ever goes deeper than what shipped before, never fainter.
      else if (venom > 0) s.tint = mix(0xa8e6a0, 0x46a52f, venomK)
      else if (ignite > 0) s.tint = 0xffc09a
      // Crusted: chalky shell-white. Ranked with the elemental statuses because it IS ticking
      // damage, and below them because it is the slowest of the four. Hue-clear of frozen's blue
      // and stun's grey-brown so a crusted body is never mistaken for a halted one — this weapon's
      // whole promise is that the pack is being eaten while it keeps walking at you.
      else if (crust > 0) s.tint = mix(0xbfae95, 0xefe6d4, crust)
      // Behavioural statuses rank BELOW the elemental ones (those are ticking damage — the more
      // urgent read) but above the elite shimmer. Among themselves: enrage first, because it's the
      // only one of the three that makes an enemy MORE dangerous.
      else if (enrage > 0) s.tint = 0xff8a5c
      else if (stun > 0) s.tint = 0xb9b0a2
      else if (fear > 0) s.tint = 0xcfc2ff
      // v6.4 phase (tardigrade cryptobiosis flicker, _phaseSolid === false = ghosted): ranked BELOW
      // stun/fear — a ghost is untouchable, not an emergency — but ABOVE the elite shimmer, so a
      // ghosted elite still reads ghosted first. The alpha drop alone (0.35, below) reads as a
      // damage-desync bug on the most-farmed pond enemy, so ghosting gets its own tint: a pale
      // spectral blue-cyan, hue-clear of every elemental tint above it (frozen's 0x9fd8ff included).
      else if (e._phaseSolid === false) s.tint = 0x9fd4e8
      else if (e.elite && chapterRender.eliteIridescent) {
        // pond soap-bubble elites shimmer through pale iridescent hues. Bodies are now baked
        // saturated, and tint multiplies, so mix the hue 50% toward white first — otherwise the
        // shimmer muddies the creature colours instead of glazing them.
        const hues = chapterRender.eliteIridescent
        const seg = ((animT * 0.4 + e.id * 0.31) % 1) * hues.length
        const a0 = Math.floor(seg) % hues.length
        s.tint = mix(mix(hues[a0], hues[(a0 + 1) % hues.length], seg - Math.floor(seg)), 0xffffff, 0.5)
      }
      else s.tint = 0xffffff

      // cheap status particles, dt-gated (no spawns while frozen behind a modal)
      if (frameDt > 0) {
        if (frozen > 0) {
          s._frostT += frameDt
          if (s._frostT >= 0.4) {
            s._frostT -= 0.4
            spawnParticle(T.fx.star_08, e.x, e.y - e.radius * 0.3, 0, -12,
              0.4, 0.1, 0xcdeeff, -0.1, 1)
          }
        } else s._frostT = 0

        if (ignite > 0) {
          s._igniteT += frameDt
          if (s._igniteT >= 0.25) {
            s._igniteT -= 0.25
            spawnParticle(T.fx.flame_05, e.x + (Math.random() * 8 - 4), e.y, 0, -34,
              0.35, 0.09, 0xff7a30, 0.15, 0.5)
          }
        } else s._igniteT = 0

        if (venom > 0) {
          s._venomT += frameDt
          if (s._venomT >= 0.4) {
            s._venomT -= 0.4
            const stacks = venomK * 8
            spawnParticle(T.fx.circle_05, e.x, e.y + e.radius * 0.25, 0, -18 - stacks * 3,
              0.45, 0.05 + stacks * 0.006, 0x4fae4f, 0.06, 0.35)
          }
        } else s._venomT = 0

        // stun: dazed sparks circling overhead — the classic "it can't act" read
        if (stun > 0) {
          s._stunT += frameDt
          if (s._stunT >= 0.16) {
            s._stunT -= 0.16
            const a = animT * 6
            spawnParticle(T.fx.star_08, e.x + Math.cos(a) * e.radius * 0.7, e.y - e.radius - 4,
              Math.cos(a) * 20, -6, 0.35, 0.07, 0xffe94d, -0.02, 0)
          }
        } else s._stunT = 0

        // enrage: embers boiling off it. Faster cadence than any other status — this one is a
        // WARNING, and the flashlight cone can light up a whole crowd at once.
        if (enrage > 0) {
          s._enrageT += frameDt
          if (s._enrageT >= 0.18) {
            s._enrageT -= 0.18
            spawnParticle(T.fx.flame_05, e.x + (Math.random() * 10 - 5), e.y - e.radius * 0.2,
              0, -46, 0.3, 0.07, 0xff5545, 0.1, 0.4)
          }
        } else s._enrageT = 0
      }

      // phase (beyond's flickers): _phaseSolid false = ghosted, untouchable and harmless. Always
      // assigned, never left dangling — a recycled slot must not inherit a ghost's alpha.
      s.alpha = e._phaseSolid === false ? 0.35 : 1

      // v6.4 phase flip particle: a couple of soft spectral motes puff outward on any solid<->ghost
      // transition (same spawnParticle idiom the stun stars above use), so the state CHANGE is an
      // event the player sees, not just a silent tint/alpha swap. Guarded on s._lastPhaseSolid !==
      // undefined (set fresh whenever a sprite is (re)acquired, above) so a recycled slot getting
      // its first phase enemy doesn't read as "just flipped".
      const isSolid = e._phaseSolid !== false
      if (frameDt > 0 && s._lastPhaseSolid !== undefined && s._lastPhaseSolid !== isSolid) {
        for (let m = 0; m < 2; m++) {
          const a = Math.random() * Math.PI * 2
          spawnParticle(T.fx.circle_05, e.x + Math.cos(a) * e.radius * 0.4, e.y + Math.sin(a) * e.radius * 0.4,
            Math.cos(a) * 14, Math.sin(a) * 14, 0.4, 0.09, 0x9fd4e8, 0.12, 0)
        }
      }
      s._lastPhaseSolid = isSolid

      // shadow under it, crown over it — placed after s.alpha since they inherit it
      syncEnemyDecor(s, e, look, k * shrink, e.hitFlash > 0)

      // ---- v4 elite affixes (contract fields, guarded — sim half may not have landed yet)
      syncAffixBadges(s, e)

      if (e.affixes && e.affixes.includes('shielded') && e.hp > e.maxHP * SHIELD_HP_FRAC) {
        // soap-bubble shield: low-alpha fill + saturated rim, gentle scale pulse.
        // Vanishes the instant hp crosses the threshold (redrawn fresh every frame,
        // nothing persists once this branch stops running for the enemy).
        const pulse = 1 + 0.04 * Math.sin(animT * 5 + e.id * 1.3)
        const r = (e.radius + 6) * pulse
        shieldG.circle(e.x, e.y, r).fill({ color: 0x4da3ff, alpha: 0.10 })
        shieldG.circle(e.x, e.y, r).stroke({ width: 3, color: 0x4da3ff, alpha: 0.7 })
      }

      if (e.affixes && e.affixes.includes('pacer')) {
        // subtle warm aura ring at the affix's push/pull radius, slow pulse
        const pulse = 0.5 + 0.5 * Math.sin(animT * 1.5 + e.id * 0.7)
        pacerG.circle(e.x, e.y, PACER_RADIUS).stroke({ width: 2, color: 0xffb347, alpha: 0.18 + pulse * 0.14 })
      }

      // SUBMISSION: the ally ring. A GROUND RING is a plan view by construction, which is the
      // one marker shape that cannot get the projection wrong (the camera looks straight down —
      // a badge or banner would be the v6.8 Trash Tornado error again). It rides shieldG, a SHARED
      // Graphics cleared every frame at 11890: no pool, no bake, no lifetime and no reset site, so
      // it is immune to the three silent-failure classes the pooled options expose (a rig left in
      // the flat clearWorld list, an unreset per-slot field, a stale recycled slot).
      //   Sized off the SPRITE, not e.radius: skies sets enemyDrawScale 0.55, which shrinks the
      // body but not the radius, so a radius-sized ring would float away from what it marks.
      //   Colour is a warm gold rather than a pale mint because the void chapter's floor is WHITE
      // and every boss FX there carries an explicit non-white tint for exactly this reason.
      //   The ring closes as the loan runs down, so the timer is readable without a HUD element.
      // ponytail: a ring is a stand-in for a real "turned" treatment (a recoloured bake). It is
      // named as one in the commit — the upgrade path is a per-instance tint slot, which the
      // strictly-ranked tint ladder at 12048 does not currently have room for.
      if ((e.allyT || 0) > 0) {
        const frac = Math.max(0, Math.min(1, e.allyT / SUBMISSION_DURATION))
        const r = (s.height ? s.height * 0.5 : e.radius) + 7
        shieldG.circle(e.x, e.y, r).stroke({ width: 3, color: ALLY_RING, alpha: 0.85 })
        // the inner arc drains with the loan — a clock you read at a glance, in plan view.
        // beginPath() IS LOAD-BEARING: Pixi v8's arc() CONTINUES the current path, so without it
        // the arc is joined to whatever was last drawn on shieldG — and shieldG is shared with
        // every shielded enemy on the map. v7.12 shipped without it and drew a long gold line from
        // this ring to an off-screen shield ring (reported from play). Every other arc() in this
        // file is already guarded the same way; this one was the exception.
        shieldG.beginPath()
        shieldG.arc(e.x, e.y, r - 4, -Math.PI / 2, -Math.PI / 2 + frac * Math.PI * 2)
          .stroke({ width: 2, color: ALLY_RING_ARC, alpha: 0.9 })
      }
    }
    for (const [id, s] of enemySprites) {
      if (s._seen) s._seen = false
      else {
        s.visible = false
        s.alpha = 1
        s._frostT = 0
        s._igniteT = 0
        s._venomT = 0
        s._stunT = 0
        s._enrageT = 0
        s._lastPhaseSolid = undefined
        hideAffixBadges(s)
        hideEnemyDecor(s)
        enemyFree.push(s)
        enemySprites.delete(id)
      }
    }
  }

  function sync(run, dt, events) {
    if (idleLayer.visible) {
      // first frame after reset(run) is handled in reset; guard anyway
      idleLayer.visible = false
      entitiesLayer.visible = true
    }
    fitScreen()
    animT += dt
    frameDt = dt
    playerX = run.player.x
    playerY = run.player.y

    handleEvents(run, events)

    // camera + shake
    if (dt > 0 && shake.t > 0) {
      shake.t = Math.max(0, shake.t - dt)
      const k = shake.amp * (shake.t / shake.dur)
      shake.ox = (Math.random() * 2 - 1) * k
      shake.oy = (Math.random() * 2 - 1) * k
      if (shake.t === 0) { shake.amp = 0; shake.ox = 0; shake.oy = 0 }
    }
    // cx/cy are the camera offset in WORLD px (screen = (world + c) * mapZoom), which is what every
    // culling test below assumes. At mapZoom 1 this is exactly the old expression.
    // v5.18 THE LANE ANCHORS THE PLAYER TO ITS TRAILING EDGE. Every other chapter centres the
    // camera, which is right when threats come from all sides. Here they come from ONE side, so a
    // centred camera spends half the screen on space you have already flown through and gives you
    // only half a screen of warning about the thing you are actually fighting. Space Invaders puts
    // you at the bottom and fills everything above you with descending aliens — that framing IS the
    // genre, not decoration. LANE_CAMERA_FRAC of the viewport is therefore ahead of you.
    // v7.x: on WHICH edge follows the chapter's laneAxis. The Beyond runs -y, so the player sits at
    // LANE_CAMERA_FRAC down the screen (near the bottom, flying up); The Reef runs +x, so it sits at
    // 1 - LANE_CAMERA_FRAC across (near the left, swimming right). Same fraction ahead either way.
    const laneAheadX = chapterHasLane && chapterLaneAxis.fwd === 'x'
    const laneAheadY = chapterHasLane && chapterLaneAxis.fwd === 'y'
    const laneFrac = (v, dir) => (dir < 0 ? v * LANE_CAMERA_FRAC : v * (1 - LANE_CAMERA_FRAC))
    const cx = (laneAheadX ? laneFrac(viewW(), chapterLaneAxis.dir) : viewW() / 2) - run.player.x + shake.ox
    const cy = (laneAheadY ? laneFrac(viewH(), chapterLaneAxis.dir) : viewH() / 2) - run.player.y + shake.oy
    world.scale.set(mapZoom)
    world.position.set(cx * mapZoom, cy * mapZoom)
    updateGroundField(cx, cy)
    updateFloorLayer(cx, cy)
    updateCaustics(cx, cy, dt)
    // v5.10 skies ground enumeration (spec §4.3): junctions and crush ruins are placed
    // ANALYTICALLY from the road grid + the render-local crush ledger, not by an extra
    // FLOOR_LAYERS sweep. (v5.16: updateLamps went with the light layer.)
    updateStreets(cx, cy)
    updateJunctions(cx, cy)
    updateRuins(cx, cy)

    // red vignette flash — keeps fading behind frozen modals/summary (dt=0)
    vignetteA = Math.max(0, vignetteA - (dt > 0 ? dt : 1 / 60) * 2.6)
    vignette.alpha = vignetteA

    // full-field lightning flash (skies) — same "keeps fading at dt=0" treatment as the vignette
    lightningFlashA = Math.max(0, lightningFlashA - (dt > 0 ? dt : 1 / 60) / LIGHTNING.flash.fadeDur)
    lightningFlash.alpha = lightningFlashA
    if (dt > 0) flashCooldown = Math.max(0, flashCooldown - dt)   // the photosensitivity budget
    // v5.16: the LIGHTNING REVEAL (spec §7.3) went with the light layer — it was one alpha channel
    // on that container, and there is no longer a container to brighten.

    // v6.5 undergrowth: latch this frame's trap/ambush read-state BEFORE the syncPool block below
    // reads them (placeTrap's re-arm tell, ambush proximity pulse).
    simTime = run.time
    ambushHeld = (run.weaponMods.clawRake?.ambushPredator ?? 0) > 0
    ambushPX = run.player.x
    ambushPY = run.player.y

    syncObstacles(run)
    tickPlanetSpin()   // must follow syncObstacles: a rebuild repopulates the spinner list
    syncWells(run)
    syncBinds(run)
    syncPools(run.pools || [])
    syncTrails(run.trails || [])
    syncWebs(run.webs || [], CHAPTERS[run.chapter]?.render?.webLook === 'slime')
    // v7.x surf: the dry patches. `|| []` like every field above — a save or a test run predating
    // the chapter has no run.sandbars at all.
    // sandbarTex is a LIST now (one bake per outline) — the pool's default texture is the first, and
    // placeSandbar swaps in the patch's own.
    syncPool(sandPool, sandLayer, run.sandbars || [], 'sand', sandbarTex[0], placeSandbar)
    syncDrySand(run.sandbars || [])
    updateWake(run.player.x, run.player.y)
    syncPool(trapPool, trapLayer, run.traps || [], 'trap', T.trapArmed, placeTrap)
    syncPool(rockPool, rockLayer, run.rocks || [], 'rock', T.asteroid, placeRock)
    syncPlayer(run.player, dt, run.rampageT || 0, playerBuffs(run))
    syncEnemies(run)
    syncBlooms(run)
    syncLures(run.lures || [])
    redrawBombs(run)
    redrawStrips(run)
    redrawLanes(run)
    redrawHazards(run)
    // The hydrant rig owns BOTH phases of a Burst Hydrant zone — rattling on its fuse, then sheeting
    // water — so unlike the old open-jet-only pass this takes the whole list. Zones with no jetDur
    // are Reality Shard rifts, which keep the plain green telegraph redrawHazards draws above.
    // `delay` zones are dormant (a cast's stagger) — planted in the sim but not yet arrived, so
    // nothing is drawn for them at all.
    syncJets((run.zones || []).filter((g) => g.jetDur > 0 && !(g.delay > 0)))
    redrawTelegraphs(run)
    updateStrafeLocks(dt) // draws INTO teleG, on top of what redrawTelegraphs just drew — see its own comment
    if (chapterHasStorm) {
      drawMissileLocks(run)          // also draws into teleG
      updateMissileTrails(run, dt)
      updateScars(dt)
    }
    updateRampage(run, dt)           // clears rampG itself; no-ops (and decays the jamming) elsewhere
    syncCars(run)
    redrawMown()                     // after syncCars: it is what grows the stripe this frame
    syncLobs(run)

    syncPool(bulletPool, bulletLayer, run.bullets, 'bullet', T.bullet, placeBullet)
    syncPool(novaPool, novaLayer, run.novas, 'nova', T.nova, placeNova)
    syncPool(orbPool, orbLayer, run.orbs, 'orb', T.orb, placeOrb)
    syncPool(gemPool, gemLayer, run.gems, 'gem', T.gem, placeGem)
    syncPool(coinPool, coinLayer, run.coins, 'coin', T.coin, placeCoin)
    syncPool(boomerangPool, boomerangLayer, run.boomerangs, 'boomerang', T.boomerang, placeBoomerang)
    syncPool(minePool, mineLayer, run.mines, 'mine', T.mine, placeMine)
    syncPool(homingPool, homingLayer, run.homingShots, 'homing', T.homing, placeHoming)
    syncTornadoes(run.debris || [])
    syncPool(shotPool, shotLayer, run.enemyShots || [], 'shot', T.missile, placeShot)
    syncHoles(run.holes)
    // v5.22: expand a SWEPT beam into one drawn arm per damaging arm. syncBeams draws a single
    // sprite per run.beams entry, so the opposite arm has never been drawn at all — it dealt
    // damage down a line with nothing on screen. Fan mode made that visible rather than causing it:
    // b.angle is the fan's CENTRE there, so the one sprite pointed where no arm actually was.
    // The angle math mirrors sim.js's beamArmAngles. render can't import sim, and the beam entity
    // carries everything needed to derive it — but the two must stay in step, so change them together.
    syncBeams(expandBeamArms(run.beams))
    redrawPrisms(run)
    updateArcs(dt)
    redrawArcs()
    redrawBreath(run) // v7.23 skies: Atomic Breath forks + Tail Lash drag tethers

    updateWhips(dt)
    updateClaws(dt)
    updateRoars(dt)
    updateParticles(dt)
    stepGullDives(dt)   // The Surf: the bird taking off after a strike (no-op elsewhere)
    updateSmoke(dt)   // the second, separately-capped pool (missile ribbon, crush dust, clods)
    updateRings(dt)
    updateDamage(dt)
    updateDustMotes(dt)
    updateLeaves(dt)
    updateCurrents(run, dt, cx, cy)
    updateEddies(run, dt)
    updateShafts(run)
    updateNet(run)            // v7.x The Trawl: no-op (both Graphics cleared) unless run.net exists
    updateGear(run, dt)       // v7.97 the Trawl's own gear: set lines + landed Net Toss meshes
    updateSwell(run, dt, cx, cy)
    drawBreakers(run)
    drawCrusts(run)
    drawDeepTells(run)   // v7.x The Deep: the anglerfish's gape and the Scent outline
    updateDark(run, cx, cy)   // AFTER updateShafts: it cuts its holes from the same run.shafts list
    updateStorm(run, dt, cx, cy)
    updateRain(dt) // v6.3: own top-level call — chapterHasRain no longer implies chapterHasStorm
  }

  // Hoisted syncPool callbacks (fresh closures per frame are pointless garbage)
  // v6.2 per-weapon bullet tints — see placeBullet below.
  const WEAPON_BULLET_TINT = { shard: 0xb9a8f0, quill: 0xf2ead8, trash: 0xc27b4a, debris: 0x9aa0a6 }
  function placeBullet(s, b, i) {
    s.position.set(b.x, b.y)
    // Stinger needles (v5.3 garden) share run.bullets with star shots but render as thin amber
    // streaks aimed along their velocity — swap this pool slot's texture/anchor/tint on the fly.
    if (b.weapon === 'stinger') {
      if (s.texture !== T.needle.tex) { s.texture = T.needle.tex; s.anchor.set(T.needle.ax, T.needle.ay) }
      s.tint = 0xffcf6b
      s.rotation = Math.atan2(b.vy, b.vx)
      s.scale.set(1)
      return
    }
    // v6.6.28: quills get the needle's treatment for the same reason the needle has it — a quill is
    // a thrown spine, not a spark. Until now they were drawn with the rotationally-symmetric star
    // sprite on an arbitrary slow spin, so they did not point where they were going. That was
    // survivable while every quill flew outward and only outward; reboundQuills makes half of them
    // fly INWARD, and "the ring is sweeping back through you" has no visual signature at all if the
    // sprite looks identical either way. Bone-white, not the needle's amber, so the two weapons'
    // projectiles stay distinguishable when a build carries both.
    if (b.weapon === 'quill') {
      if (s.texture !== T.needle.tex) { s.texture = T.needle.tex; s.anchor.set(T.needle.ax, T.needle.ay) }
      // brighter and fatter than the stinger's needle, which is baked for the garden's sunlit lawn.
      // The undergrowth floor lands around 0x514628 (relative luminance ~0.06) and its documented
      // failure mode is thin-and-dark-on-dark; at the needle's native 1.0 a quill all but vanished.
      s.tint = 0xfff2d8
      s.rotation = Math.atan2(b.vy, b.vx)
      s.scale.set(1.7)
      return
    }
    // The Surf's Skipping Shell. A flat shell skimming edge-on, so it is drawn ALONG its velocity
    // like the needle and the quill rather than as a symmetrical spark — a shell that does not point
    // where it is going cannot read as skipping, and this one visibly changes direction at every
    // touch-down, which is the half of the card a round sprite throws away.
    if (b.weapon === 'shell') {
      if (s.texture !== T.shell.tex) { s.texture = T.shell.tex; s.anchor.set(T.shell.ax, T.shell.ay) }
      s.tint = 0xffffff               // the bake carries its own colour; a tint here would flatten it
      s.rotation = Math.atan2(b.vy, b.vx)
      // A slow tumble as it flies, keyed off the shell's own position so two shells in the air never
      // spin in lockstep and read as one object. Small: it is skimming, not cartwheeling.
      s.scale.set(1 + 0.10 * Math.sin(animT * 9 + (b.x + b.y) * 0.02), 1)
      return
    }
    // A barnacle larva. Small, pale and round on purpose — it is a seed, and the thing worth looking
    // at is the crust it becomes on the body, not the delivery.
    if (b.weapon === 'barnacle') {
      if (s.texture !== T.bullet.tex) { s.texture = T.bullet.tex; s.anchor.set(T.bullet.ax, T.bullet.ay) }
      s.tint = 0xe9dcc6
      s.rotation = 0
      s.scale.set(0.55)
      return
    }
    if (s.texture !== T.bullet.tex) { s.texture = T.bullet.tex; s.anchor.set(T.bullet.ax, T.bullet.ay) }
    // v6.2: four weapons used to fall through to the plain gold star — each now carries its own
    // tint (shard rift-violet, quill bone, trash rust, debris dust). Everything else stays white
    // (the star tint is baked; white also resets a slot recycled from a needle).
    s.tint = WEAPON_BULLET_TINT[b.weapon] ?? 0xffffff
    s.rotation = animT * 2.2 + i * 0.9 // slow spin
    s.scale.set(1 + 0.1 * Math.sin(animT * 7 + i * 2.4)) // slight scale pulse
  }
  function placeNova(s, n) {
    // A nova carrying `arc` is a Breaker crest and is drawn by drawBreakers. This pool draws FULL
    // RINGS, so leaving it in would paint a complete circle over a weapon whose entire read is that
    // it covers only the side you face — and the sector would still be correct in the sim, so the
    // weapon would measure right and look wrong.
    if (n.arc != null) { s.visible = false; return }
    s.position.set(n.x, n.y)
    // A Skipping Shell's touch-down is a DARK MARK, not a bright one, and that inverts what every
    // other impact in this game does. It is the one treatment with a physical argument behind it:
    // wet sand really is a value step darker than dry, so water landing on a beach darkens it. The
    // bright options were all variations on a pale disc against the palest floor in the game, which
    // is the same trap that made the shell sprite itself invisible — and on this floor they read as
    // a dust puff rather than as a splash. Owner picked this off a four-way A/B on one pinned frame.
    //
    // The chapter is already committed to this reading elsewhere: its sandbars are DRY sand drawn
    // BRIGHTER than the damp floor (see SANDBAR_VIS and the render block in CHAPTERS.surf), so
    // "darker means wetter" is a rule the player is being taught by the ground itself.
    //
    // The bright half of the effect lives entirely in the droplet crown spawned by the 'skip' event,
    // which stays white — a dark mark alone would have no impact at all.
    if (n.look === 'foam') {
      s.tint = 0x7a6144
      s.scale.set(Math.max(n.r, 1) / T.novaTexR)
      s.alpha = 0.42 * Math.max(0, 1 - n.r / n.maxR) + 0.18
      return
    }
    // v6.2: a panic nova reads violet; a slime wave stays sky-blue.
    s.tint = n.fear ? 0xb06cf0 : 0x59b7ff
    s.scale.set(Math.max(n.r, 1) / T.novaTexR)
    s.alpha = 0.9 * Math.max(0, 1 - n.r / n.maxR) + 0.1
  }
  function placeOrb(s, o, i) {
    s.position.set(o.x, o.y)
    s.tint = 0x2bbf9e
    s.rotation = animT * 1.6 + i * 1.1 // gentle rotation
    // v4.1 Big Orbs mod: orbs carry their effective hit radius (o.r, falls back to ORB_R)
    const sizeMul = (o.r ?? ORB_R) / ORB_R
    s.scale.set(T.orbScale * sizeMul * (1 + 0.12 * Math.sin(animT * 6 + i * 2.1)))
  }
  function placeGem(s, g) {
    s.position.set(g.x, g.y)
    s.scale.set(1 + 0.15 * Math.sin(animT * 5 + (g.x + g.y) * 0.05))
  }
  function placeCoin(s, c) {
    s.position.set(c.x, c.y)
    s.scale.set(1 + 0.1 * Math.sin(animT * 4 + (c.x - c.y) * 0.05))
  }
  function placeBoomerang(s, b, i) {
    s.position.set(b.x, b.y)
    s.tint = 0xffffff                 // the leaf carries its own colours (see the bake) — do not tint
    s.rotation = animT * 14 + i * 1.7 // fast spin, derived from animT so dt=0 freezes it
    const sizeMul = b.hitR ? b.hitR / 14 : 1 // v4.1 Big Blade mod (14 = base BOOMERANG_HIT_R in sim.js)
    s.scale.set(T.boomerangScale * sizeMul)  // uniform: a stretch skews the leaf, and the spin already reads as speed
  }
  function placeMine(s, m) {
    s.position.set(m.x, m.y)
    const base = m.small ? 0.6 : 1 // v4.1 Cluster mod bomblets read smaller
    if (m.arm > 0) {
      s.alpha = 0.55
      s.scale.set(base * (1 + 0.05 * Math.sin(animT * 3 + (m.x + m.y) * 0.05))) // arming: slow pulse
    } else {
      s.alpha = 1
      s.scale.set(base * (1 + 0.1 * Math.sin(animT * 8 + (m.x + m.y) * 0.05))) // armed: faster pulse
    }
  }
  // Trash Tornado funnels (run.debris): sim owns their positions outright (they hunt), so this only
  // draws where they already are.
  //
  // v6.8.2 (owner: "rings should swirl at different speeds") — each ring is its own sprite turning
  // at its own rate, mouth slowest and core fastest, the way a real vortex conserves angular
  // momentum inward. That differential is the whole reason this is a rig and not one rotated
  // texture: turning six rings in lockstep is indistinguishable from turning one disc, which is
  // what v6.8.1 shipped. Values are rad/s, driven by animT so a frozen frame (dt=0 behind a modal)
  // freezes the swirl too.
  const TORNADO_RING_SPIN = [1.1, 1.5, 2.0, 2.7, 3.6, 4.8]

  function acquireTornado() {
    const root = new Container()
    const rings = T.tornadoRings.map((look) => {
      const s = spriteOf(look)
      root.addChild(s)
      return s
    })
    debrisLayer.addChild(root)
    return { root, rings }
  }

  function syncTornadoes(list) {
    const n = list.length
    while (debrisPool.length < n) debrisPool.push(acquireTornado())
    for (let i = 0; i < n; i++) {
      const rig = debrisPool[i]
      const d = list[i]
      rig.root.visible = true
      rig.root.position.set(d.x, d.y)
      // The breathing pulse stays on the ROOT so every ring swells together — per-ring pulses read
      // as the throat coming apart rather than as one thing turning.
      rig.root.scale.set(((d.r ?? DEBRIS_R) / DEBRIS_R) * (1 + 0.06 * Math.sin(animT * 8 + i * 2.2)))
      for (let k = 0; k < rig.rings.length; k++) {
        // The + i * 1.3 offset is per FUNNEL, not per ring: without it a pack turns in unison and
        // six funnels read as one object smeared across the street.
        rig.rings[k].rotation = animT * TORNADO_RING_SPIN[k] + i * 1.3 + k * 0.9
      }
    }
    for (let i = n; i < prevCount.debris; i++) debrisPool[i].root.visible = false
    prevCount.debris = n
  }
  // Enemy missiles (run.enemyShots): aimed along velocity, trailing smoke. These are the only
  // things on screen shooting AT the player, so they get a trail — motion you can track and outrun.
  function placeShot(s, sh, i) {
    s.position.set(sh.x, sh.y)
    s.tint = 0xffffff
    s.rotation = Math.atan2(sh.vy, sh.vx)
    // v5.10 skies: a hard finned DART, not the generic soft missile glyph — this is the only
    // travelling physical projectile in the game and it carries the chapter's signal magenta. Its
    // corkscrew smoke ribbon is emitted by updateMissileTrails on the separate smoke pool, so the
    // grey circle_05 puff below (every other chapter's enemy shot) is skipped here.
    if (chapterHasStorm) {
      if (s.texture !== T.missileDart.tex) { s.texture = T.missileDart.tex; s.anchor.set(T.missileDart.ax, T.missileDart.ay) }
      s.scale.set(1.15)
      return
    }
    if (s.texture !== T.missile.tex) { s.texture = T.missile.tex; s.anchor.set(T.missile.ax, T.missile.ay) }
    s.scale.set(1)
    if (shotTimers[i] === undefined) shotTimers[i] = 0
    if (frameDt > 0) {
      shotTimers[i] += frameDt
      if (shotTimers[i] >= 0.05) {
        shotTimers[i] -= 0.05
        spawnParticle(T.fx.circle_05, sh.x, sh.y, -sh.vx * 0.1, -sh.vy * 0.1,
          0.3, 0.06, 0x9aa0a8, 0.12, 2)
      }
    }
  }
  function placeHoming(s, h, i) {
    s.position.set(h.x, h.y)
    s.tint = 0xffffff // tint baked into the texture
    s.rotation = animT * 3 + i * 1.3 // tiny spin
    s.scale.set(T.homingScale)
    if (homingTimers[i] === undefined) homingTimers[i] = 0
    if (frameDt > 0) {
      homingTimers[i] += frameDt
      if (homingTimers[i] >= 0.06) {
        homingTimers[i] -= 0.06
        spawnParticle(T.fx.flare_01, h.x, h.y, -h.vx * 0.15, -h.vy * 0.15,
          0.25, 0.09, 0xc9a0f0, -0.2, 2)
      }
    }
  }
  function placeHole(hv, h, i) {
    hv.root.position.set(h.x, h.y)
    const breathe = 1 + 0.05 * Math.sin(animT * 4 + i * 1.7) // subtle scale breathing
    hv.root.scale.set(breathe)
    // children sized to the real radius (root stays ~1 so the twirl cap holds)
    hv.disc.scale.set(h.radius / T.holeDiscRef)
    const twirlPx = Math.min(h.radius * 1.2, HOLE_TWIRL_MAX)
    hv.vortexA.scale.set(fxScale(T.fx.twirl_01, twirlPx))
    hv.vortexB.scale.set(fxScale(T.fx.twirl_02, twirlPx * 0.85))
    hv.core.scale.set((h.radius * HOLE_CORE_FRAC) / (T.holeRefR * 0.16))
    if (hv._r !== h.radius) { // crisp rim ring, redrawn only when the radius changes
      hv._r = h.radius
      hv.ring.clear()
      hv.ring.circle(0, 0, h.radius).stroke({ width: 5, color: 0x5a2fb0, alpha: 0.4 })
      hv.ring.circle(0, 0, h.radius * 0.985).stroke({ width: 2, color: 0xc9b3f5, alpha: 0.35 })
    }
    hv.vortexA.rotation = animT * 1.8 + i * 0.6
    hv.vortexB.rotation = -animT * 1.8 * 1.4 + i * 0.9 // counter-rotating, 1.4x speed
    hv.ring.rotation = animT * 0.4

    const elapsed = h.duration - h.life
    let a = elapsed < 0.2 ? elapsed / 0.2 : 1
    if (h.life < 0.3) a = Math.min(a, h.life / 0.3)
    hv.root.alpha = Math.max(0, Math.min(1, a))

    // suction particles: spawn at the rim, spiral inward toward the center, fading out
    if (holeParticleTimers[i] === undefined) holeParticleTimers[i] = 0
    if (frameDt > 0) {
      holeParticleTimers[i] += frameDt
      if (holeParticleTimers[i] >= 0.09) {
        holeParticleTimers[i] -= 0.09
        const ang = Math.random() * Math.PI * 2
        const spin = (Math.random() < 0.5 ? 1 : -1) * (6 + Math.random() * 3)
        const tex = Math.random() < 0.5 ? T.fx.star_08 : T.fx.circle_05
        spawnSpiralParticle(tex, h.x, h.y, ang, h.radius * 0.95, spin, 0.7, 0.09, 0x9a6fd0, -0.1)
      }
    }
  }
  function placeBeam(bv, b) {
    bv.root.position.set(playerX, playerY)
    bv.root.rotation = b.angle

    // `swept` is the Pulsar Sweep and nothing else (config.js WEAPONS.pulsarSweep), so it is
    // the whole weapon test — a pool slot serves either weapon, hence swapping here and not in
    // acquireBeam. Both bakes share geometry, so the anchor spriteOf set still holds.
    const swept = b.swept === true
    bv.bar.texture = (swept ? T.beamSweep : T.beam).tex   // bake() returns {tex, ax, ay}, not a Texture
    bv.tip.tint = bv.muzzle.tint = swept ? 0xa08cff : 0xff5a52
    bv.streakA.tint = bv.streakB.tint = swept ? 0xdcd6ff : 0xffd9d4

    const spawnElapsed = b.duration - b.life
    const spawnIn = spawnElapsed < 0.12 ? Math.max(0, spawnElapsed / 0.12) : 1 // width squashes in
    const despawnOut = b.life < 0.3 ? Math.max(0, b.life / 0.3) : 1 // width shrinks with the fade
    const pulse = 0.8 + 0.15 * Math.sin(animT * 20)

    bv.beamBody.scale.set(b.length / T.beamRefLen, (b.width / T.beamRefWidth) * spawnIn * pulse)
    bv.beamBody.alpha = despawnOut

    // shimmer streaks scrolling along the beam's local (pre-scale) length
    const scrollSpeed = 300
    bv.streakA.position.x = (animT * scrollSpeed) % T.beamRefLen
    bv.streakB.position.x = (animT * scrollSpeed + T.beamRefLen / 2) % T.beamRefLen

    // end-cap flare at the live tip (outside beamBody so width-squash doesn't distort it)
    bv.tip.position.x = b.length
    bv.tip.scale.set(fxScale(T.fx.flare_01, b.width * 1.3))
    bv.tip.alpha = spawnIn * despawnOut * (0.7 + 0.2 * Math.sin(animT * 16))

    // origin flash: big pop on spawn, settles into a small idle spark, fades on despawn
    const muzzlePop = spawnIn < 1 ? lerp(0.2, 1.4, spawnIn) : 1
    bv.muzzle.scale.set(fxScale(T.fx.muzzle_02, b.width * 2.2) * muzzlePop)
    bv.muzzle.alpha = (spawnIn < 1 ? spawnIn : 0.55 + 0.15 * Math.sin(animT * 18)) * despawnOut
  }

  // -------------------------------------------------------------------- idle
  function idle(dt) {
    fitScreen()
    idleT += dt
    updateDustMotes(dt)

    // slow synthetic camera drift so the organic floor keeps feeling alive behind
    // the title screen even with no real player/camera to follow
    const cx = -idleT * 20
    const cy = -idleT * 14
    world.position.set(cx, cy)
    updateFloorLayer(cx, cy)

    const w = app.screen.width
    const h = app.screen.height
    for (const b of idleBlobs) {
      const t = idleT * 2 + b.ph
      const bounce = Math.abs(Math.sin(t))
      const squash = Math.cos(t * 2) * 0.06
      const x = w * b.fx
      const y = h * b.fy
      b.blob.position.set(x, y - bounce * 16)
      b.blob.scale.set(1 - squash, 1 + squash)
      b.shadow.position.set(x, y + b.r * 0.75)
      b.shadow.scale.set((b.r / PLAYER.radius) * (1 - bounce * 0.25))
      b.shadow.alpha = 1 - bounce * 0.35
    }
  }

  // ------------------------------------------------------------------- reset
  function reset(run) {
    // Gull strikes in flight when a run ends. These are NOT in the flat-pool list below — that list
    // does `s.visible = false` over plain sprite arrays, and gullDives holds {sp, sh, ...} records
    // (TWO sprites each — the bird and the shadow it left on the sand), so adding it there would set
    // a dead property on an object literal, throw nothing, and leave last run's birds hanging over
    // the new one. Same trap the rig pools carry, opposite direction. The WHOLE RECORD goes back on
    // the free list, not d.sp: recycling the sprite alone orphans its shadow, visible, forever.
    for (const d of gullDives) { d.sp.visible = false; d.sh.visible = false; gullFree.push(d) }
    gullDives.length = 0
    // Splash rings outlive their bird — they are a plain list redrawn every frame, not sprites, so
    // they are invisible to the flat-pool sweep below for a different reason and need saying here.
    splashes.length = 0
    splashG.clear()
    // The dry-sand lights are in aboveWater, NOT in the flat-pool sweep below, so they need saying
    // here too: a chapter change that turns the water off would otherwise leave last run's warm
    // discs burning over a beach that no longer has sandbars under them.
    for (const s of drySandPool) s.visible = false
    // Latch the per-chapter palette BEFORE clearing/repainting so the floor repopulates and the
    // player rig tints under the new chapter. Title (run == null) falls back to the body look.
    const cfg = run ? CHAPTERS[run.chapter] : null
    chapterRender = cfg?.render ?? BODY_RENDER
    // The water wash (see waterWash's block in the stage setup). Set here and never touched again:
    // it is a property of the chapter, not of the frame, so unlike the dark it has nothing to
    // recompute. The title screen (run == null) falls back to BODY_RENDER, which declares no water.
    const water = chapterRender.water
    waterWash.tint = water?.tint ?? 0xffffff
    waterWash.alpha = water?.alpha ?? 0
    waterWash.blendMode = water?.blend ?? 'normal'
    // One key says "this chapter is under water" and turns on everything that follows from it: the
    // light on the floor, and the ripples the player pushes across the surface. See CHAPTERS.surf's
    // `caustics` for why the two are not separate flags.
    causticLayer.visible = !!chapterRender.caustics
    wakeOn = !!chapterRender.caustics
    wakeAcc = 0; wakeX = null
    // The pond drifts, The Surf surges; every other chapter draws no flow field at all. Re-tinting
    // the whole streak pool here (rather than at construction, where it used to be fixed to the
    // pond's teal) is what lets one pool serve both looks.
    const sigType = cfg?.signature?.type
    flowKind = sigType === 'currents' ? 'currents' : sigType === 'tide' ? 'tide' : null
    flowVis = flowKind === 'tide' ? TIDE_VIS : CURRENT_VIS
    for (const p of currentStreaks) { p.a.tint = flowVis.tint; p.b.tint = flowVis.tint }
    chapterHasEddies = !!(sigType === 'currents' && cfg?.signature?.eddies)
    // refillSpec() and not signature.type: The Shelf's shafts ARE its signature, The Surf's pools
    // hang off signature.pools, and streamShafts fills run.shafts from whichever one exists. Asking
    // the same question the streamer asks is what keeps "the sim made a circle" and "the renderer
    // draws a circle" from being two independent chapter tests that can disagree.
    refillLook = cfg?.signature && refillSpec(cfg.signature)
      ? (sigType === 'shafts' ? 'shaft' : sigType === 'air' ? 'pocket' : 'pool')
      : null
    swellCfg = cfg?.render?.swell ?? null
    chapterHasStorm = !!chapterRender.storm
    // v6.3: `storm` implies both — skies stays bit-identical (storm was always rain+ruins there);
    // city opts into rain/ruins individually without the clouds `storm` alone would also switch on.
    chapterHasRain = !!(chapterRender.storm || chapterRender.rain)
    chapterHasRuins = !!(chapterRender.storm || chapterRender.ruins)
    playerForm = chapterRender.form ?? null
    formScale = chapterRender.formScale ?? 1
    chapterHasLeaves = !!chapterRender.leaves
    // Read `cfg`, not CHAPTERS[run.chapter] — `run` is null on the quit-to-title path (main.js
    // onQuit), and dereferencing it here threw before ui.showScreen('title') could run, softlocking
    // the player on the Paused screen. Every other line in this block already guards for that.
    chapterHasLane = cfg?.lane === true
    chapterHasBurst = cfg?.burst === true
    chapterLaneAxis = laneAxes(cfg)   // null-safe on the quit-to-title path, like the line above
    chapterIsVoid = !!chapterRender.voidFloor
    chapterHasDistricts = !!chapterRender.districts
    districtSeed = run?._districtSeed ?? 0
    // roads is a chapter-TOP-LEVEL flag (config.js CHAPTERS.skies.roads), not under `render` like
    // the others above — it's sim-relevant (streamObstacles keeps buildings off streets) as well as
    // render-relevant, so it lives next to `crush`/`obstacles`, not inside the render-only block.
    chapterHasRoads = !!cfg?.roads
    chapterEndlessGrid = !!cfg?.endlessGrid
    // v5.12 BUGFIX — this was `run?._obstacleSeed`, i.e. render drew the street network from a
    // DIFFERENT Math.random() draw than the one the terrain, cities and buildings come from
    // (state.js draws the two independently). v5.11 moved sim's own roadAt call to the world seed
    // and rewrote the comment here to say roads had been unified — but never changed this line, so
    // the road graph and everything it is supposed to belong to described two different planets.
    // That is the single largest cause of "layout coherence is just awful": streets ran across
    // farmland where the urban falloff makes a street geometrically impossible, downtown blocks
    // carried forty buildings and no road at all, and crosswalks landed mid-block at the angle of a
    // grid that was not there. Measured over eight wide captures: matched seeds put 0.0% of street
    // area on farms/parks/desert and leave 0.0% of downtown roadless; the split seeds put up to 20%
    // and 75%.
    roadSeed = run?._districtSeed ?? 0
    // v5.10: recover the per-seed road grid origin ONCE per run, before anything that enumerates
    // prop/obstacle set for this chapter — a chapter with no biome entry falls back to the green
    // one, so a future CHAPTERS id renders (bushes and all) before it gets art of its own
    chapterBiome = (run && BIOMES[run.chapter]) || BIOMES.body
    dustLook = chapterRender.dust ?? null
    for (const m of dustMotes) { m.s.tint = dustLook?.tint ?? 0xffffff; m.s.alpha *= dustLook?.alpha ?? 1 }
    R.background.color = chapterRender.bgColor
    clearWorld()
    if (run) {
      entitiesLayer.visible = true
      idleLayer.visible = false
      fitScreen()
      // snap camera onto the player immediately
      const cx = viewW() / 2 - run.player.x
      const cy = viewH() / 2 - run.player.y
      world.scale.set(mapZoom)
      world.position.set(cx * mapZoom, cy * mapZoom)
      updateGroundField(cx, cy)
      playerX = run.player.x
      playerY = run.player.y
      updateFloorLayer(cx, cy)
      updateStreets(cx, cy)
      updateJunctions(cx, cy)
      syncPlayer(run.player, 0, 0, playerBuffs(run))
    } else {
      entitiesLayer.visible = false
      idleLayer.visible = true
      idleT = 0
    }
  }

  // Dev/debug entry point for MAP MODE (see mapZoom's comment above). Zoom < 1 pulls the camera
  // back; `bare` hides everything that is not the procedural world — the player rig, all entities,
  // projectiles and FX, the storm's cloud shadows and rain, and the additive light layer — leaving
  // ground, roads, junctions, kerb furniture, props and buildings. Not reachable from gameplay;
  // main.js only wires it up behind a URL flag.
  function setMapMode(on, zoom) {
    mapMode = !!on
    mapZoom = on ? (zoom || 0.25) : 1
    // entitiesLayer is NOT hidden wholesale: obstacleLayer lives inside it, and the BUILDINGS are
    // half of what a layout view exists to show (the first capture hid them and produced a map of
    // bare roads on flat ground). Hide every child of it EXCEPT the structures, plus the weather and
    // cloud shadows are big soft shapes that wash over exactly the boundaries this view is meant
    // to make legible. (v5.16: the additive light layer they were listed beside is gone.)
    for (const child of entitiesLayer.children) child.visible = on ? child === obstacleLayer : true
    entitiesLayer.visible = true
    cloudShadowLayer.visible = !on
    stormRainLayer.visible = !on
    stormCloudLayer.visible = !on
    // A zoomed-out world streams far more cells than the pools were sized for at 1:1, and every
    // cached floor sprite is positioned for the old viewport — drop them so the next frame
    // repopulates against the new one.
    clearFloorLayer()
    clearGroundField()
  }

  // v6.7.2: PNG data URLs of the baked roster looks, for the title's chapter cards. The cards used
  // to advertise each chapter with three emoji, and emoji lie — there is no tardigrade glyph, so it
  // shipped as 🐻 and read as a bear. drawTardigrade already exists a few thousand lines up; the
  // only thing missing was a way to get it out of Pixi, since ui.js may not import it.
  // BUILD-TIME ONLY. The game never calls this: scripts/bake-cast.mjs does, once, through the
  // ?debug window.__renderer handle, and writes the results to src/cast/*.png which ui.js globs as
  // ordinary asset URLs. It is not called at runtime because each extract is a readPixels that
  // stalls the pipeline until the GPU catches up, and doing two dozen before the first paint cost
  // seconds of black screen on a slow context. Re-run the script when creature art changes.
  // Never throws: a missing thumbnail costs one face on a card, and the script reports it.
  async function castThumbs(ids) {
    const out = {}
    for (const id of ids) {
      const look = T.roster[id]
      if (!look) continue
      try {
        out[id] = await R.extract.base64(look.tex)
      } catch {
        // extract does a GPU readback; on a context that refuses one we simply have no face here
      }
    }
    return out
  }

  return { reset, sync, idle, ready, setMapMode, castThumbs }
}
